COLLDATA("muslim","ur",[[622,"صفیہ بنت شیبہ نے سیدہ عائشہ ؓ سے روایت کی کہ انہوں نے کہا : میں حیض کی حالت میں ہوتی تو رسول اللہ صلی اللہ علیہ وسلم میری گود کو تکیہ بناتے اور قرآن پڑھتے","",{"u2":"صفیہ بنت شیبہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے کہا: میں حیض کی حالت میں ہوتی تو رسول اللہ صلی اللہ علیہ وسلم میری گود کو تکیہ بناتے اور قرآن پڑھتے"}],[623,"سیدنا انس رضی اللہ عنہ سےروایت ہے کہ یہودی ، جب ان کی کوئی عورت حائضہ ہوتی تو نہ وہ اس کے ساتھ کھانا کھاتے اور نہ اس کے ساتھ گھر ہی میں اکٹھے رہتے ۔ چنانچہ نبی اکرم صلی اللہ علیہ وسلم کے صحابہ نے آپ سے اس بارے میں پوچھا ، اس پر اللہ تعالیٰ نے آیت تاری : ’’یہ آپ سے حیض کے بارے میں سوال کرتے ہیں ، آپ فرما دیجیے ، یہ اذیت ( کا وقت ) ہے ، اس لیے محیض ( مقام حیض ) میں عورتوں ( کے ساتھ مجامعت ) سے دور ہو ‘‘ آخر تک ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جماع کے سوا سب کچھ کرو ۔ ‘‘ یہودیوں تک یہ بات پہنچی تو کہنے لگے : یہ آدمی ہمارے دین کی ہر بات کی مخالفت ہی کرنا چاہتا ہے ۔ ( یہ سن کر ) اسید بن حضیر اور عباد بن بشر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور دونوں نے کہا : اے اللہ کے رسول! یہود اس اس طرح کہتے ہیں تو یکا ہم ان ( عورتوں ) سے جماع بھی نہ کر لیا کریں ؟ اس پر رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدل گیا حتی کہ ہم نے سمجھا کہ آپ دونوں سے ناراض ہو گئے ہیں ۔ وہ دونوں نکل گئے ، آگے سے رسول اللہ صلی اللہ علیہ وسلم کے لیے دودھ کا ہدیہ آرہا تھا ، آپ نے کسی کو ان کے پیچھے بھیجا اور ان کو ( بلواکر ) دودھ پلایا ، وہ سمجھ گئے کہ آپ ان سے ناراض نہیں ہوئے ۔","",{"u2":"سیدنا انس رضی اللہ عنہ سےروایت ہے کہ یہودی، جب ان کی کوئی عورت حائضہ ہوتی تو نہ وہ اس کے ساتھ کھانا کھاتے اور نہ اس کے ساتھ گھر ہی میں اکٹھے رہتے۔ چنانچہ نبی اکرم صلی اللہ علیہ وسلم کے صحابہ نے آپ سے اس بارے میں پوچھا، اس پر اللہ تعالیٰ نےآیت تاری: ’’یہ آپ سے حیض کے بارے میں سوال کرتے ہیں، آپ فرما دیجیے، یہ اذیت (کاوقت) ہے، اس لیے محیض(مقام حیض) میں عورتوں (کے ساتھ مجامعت) سے دور ہو ‘‘ آخر تک۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جماع کے سوا سب کچھ کرو۔‘‘\nیہودیوں تک یہ بات پہنچی تو کہنے لگے: یہ آدمی ہمارے دین کی ہر بات کی مخالفت ہی کرنا چاہتا ہے۔ (یہ سن کر) اسید بن حضیر اور عباد بن بشر رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور دونوں نے کہا:اے اللہ کے رسول! یہود اس اس طرح کہتے ہیں تو یکا ہم ان (عورتوں) سے جماع بھی نہ کر لیا کریں؟ اس پر رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدل گیا حتی کہ ہم نے سمجھا کہ آپ دونوں سے ناراض ہو گئے ہیں۔ وہ دونوں نکل گئے، آگے سے رسول اللہ صلی اللہ علیہ وسلم کے لیے دودھ کا ہدیہ آرہا تھا، آپ نے کسی کو ان کے پیچھے بھیجا اور ان کو (بلواکر) دودھ پلایا، وہ سمجھ گئے کہ آپ ان سے ناراض نہیں ہوئے۔"}],[624,"وکیع ، ابو معاویہ اور ہشیم نے اعمش سے حدیث بیان کی ، انہوں نے منذر بن یعلیٰ سے ( جن کی کنیت ابو یعلیٰ ہے ) انہوں نے ابن حنفیہ سے ، انہوں نے ( اپنے والد ) سیدنا علی رضی اللہ عنہ سے روایت کی ، کہا : مجھے مذی ( منی سے مختلف رطوبت جو اسی راستے سے خارج ہوتی ہے ) زیادہ آتی تھی اور میں آپ کی بیٹی کے ( ساتھ ) رشتے کی وجہ سے براہ راست نبی کریم صلی اللہ علیہ وسلم سے پوچھنے میں شرم محسوس کرتا تھا ۔ میں نے مقداد بن اسود سے کہا ، انہوں نےآپ سے پوچھا ، آپ نے فرمایا : ’’ ( اس میں متبلا آدمی ) اپنا عضو مخصوص دھوئے اور وضو کر لے ۔ ‘‘","",{"u2":"وکیع، ابو معاویہ اور ہشیم نے اعمش سے حدیث بیان کی،انہوں نے منذر بن یعلیٰ سے (جن کی کنیت ابو یعلیٰ ہے) انہوں نے ابن حنفیہ سے، انہوں نے (اپنے والد) سیدنا علی رضی اللہ عنہ سے روایت کی، کہا: مجھے مذی (منی سے مختلف رطوبت جو اسی راستے سے خارج ہوتی ہے) زیادہ آتی تھی اور میں آپ کی بیٹی کے (ساتھ) رشتے کی وجہ سے براہ راست نبی کریم صلی اللہ علیہ وسلم سے پوچھنے میں شرم محسوس کرتا تھا۔ میں نے مقداد بن اسود سے کہا، انہوں نےآپ سے پوچھا، آپ نے فرمایا:’’(اس میں متبلا آدمی) اپنا عضو مخصوص دھوئے اور وضو کر لے۔ ‘‘"}],[625,"شعبہ نے سلیمان اعمش سے باقی ماندہ سابقہ سند کے ساتھ سیدنا علی رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : میں نے سیدہ فاطمہ ؓ ( کے ساتھ رشتے ) کی وجہ سے نبی اکرم صلی اللہ علیہ وسلم سے مذی کےبارے میں پوچھنے میں شرم محسوس کی تو میں نے مقداد کو کہا ، انہوں نے آپ صلی اللہ علیہ وسلم سے پوچھا ، آپ نے فرمایا : ’’اس سے وضو ( کرنا پڑتا ) ہے ۔ ‘‘","",{"u2":"شعبہ نے سلیمان اعمش سے باقی ماندہ سابقہ سند کے ساتھ سیدنا علی رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: میں نے سیدہ فاطمہ رضی اللہ عنہا (کے ساتھ رشتے) کی وجہ سے نبی اکرم صلی اللہ علیہ وسلم سے مذی کےبارے میں پوچھنے میں شرم محسوس کی تو میں نے مقداد کو کہا، انہوں نے آپ صلی اللہ علیہ وسلم سے پوچھا، آپ نے فرمایا:’’اس سے وضو (کرنا پڑتا) ہے۔ ‘‘"}],[626,"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے ، کہا : سیدنا علی رضی اللہ عنہ نے فرمایا : ہم نے مقداد بن اسود رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا ، انہوں نے آپ سے مذی کے بارے میں پوچھا جو انسان ( کے عضو مخصوص ) سے خارج ہوتی ہے کہ وہ اس کا کیا کرے ؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’وضو کرو اور شرم گاہ کو دھو لو ۔ ‘‘ ( ترتیب میں پہلے دھونا ، پھر وضو کرنا ہے جس طرح حدیث : 695میں ہے ۔)","",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے، کہا: سیدنا علی رضی اللہ عنہ نے فرمایا:ہم نے مقداد بن اسود رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیجا، انہوں نے آپ سے مذی کے بارے میں پوچھا جو انسان (کے عضو مخصوص) سے خارج ہوتی ہے کہ وہ اس کا کیا کرے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’وضو کرو اور شرم گاہ کو دھو لو۔ ‘‘ (ترتیب میں پہلے دھونا، پھر وضو کرنا ہے جس طرح حدیث:695میں ہے۔)"}],[627,"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رات کو اٹھے ، قضائے حاجت کی ، پھر اپنا چہرہ اور دونوں ہاتھ دھوئے ، پھر سو گئے ۔","",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رات کو اٹھے، قضائے حاجت کی، پھر اپنا چہرہ اور دونوں ہاتھ دھوئے، پھر سو گئے۔"}],[628,"ابوسلمہ بن عبد الرحمن نے سیدہ عائشہ ؓ سےروایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب جنابت کی حالت میں سونا چاہتے تو سونے سے پہلے نماز کے وضو کی طرح وضو کر لیتے تھے ۔","",{"u2":"ابوسلمہ بن عبد الرحمن نے سیدہ عائشہ رضی اللہ عنہا سےروایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب جنابت کی حالت میں سونا چاہتے توسونے سے پہلے نماز کے وضو کی طرح وضو کر لیتے تھے۔"}],[629,"ابن علیہ ، وکیع اور عندر نے شعبہ سے ، انہوں نے حکم سے ، انہوں نے ابراہیم سے ، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ ؓ سےروایت کی : انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم جب حالت جنابت میں ہوتے او رکھانا یا سونا چاہتے تو نماز کے وضو کی طرح وضو کر لیتے تھے ۔","",{"u2":"ابن علیہ،وکیع اور عندر نے شعبہ سے، انہوں نے حکم سے، انہوں نے ابراہیم سے، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سےروایت کی: انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم جب حالت جنابت میں ہوتے او رکھانا یا سونا چاہتے تو نماز کے وضو کی طرح وضو کر لیتے تھے۔"}],[630,"محمد بن مثنیٰ اور ابن بشار دونوں نے کہا : ہمیں محمد بن جعفر نے حدیث سنائی ، اسی طرح عبیداللہ بن معاذ نے حدیث سنائی ، کہا : مجھے میرے والد نے حدیث سنائی ۔ ان دونوں نے کہا : ہمیں شعبہ نے حدیث سنائی ۔ ابن مثنیٰ کی حدیث میں ہے ، حکم نے کہا : میں نے ابراہیم کو حدیث بیان کرتے ہوئے سنا ۔ ( آگے وہی حدیث ہے جو اوپر بیان ہو ئی ۔)","",{"u2":"محمد بن مثنیٰ اور ابن بشار دونوں نے کہا:ہمیں محمد بن جعفر نے حدیث سنائی،اسی طرح عبیداللہ بن معاذ نے حدیث سنائی، کہا:مجھے میرے والد نے حدیث سنائی۔ ان دونوں نے کہا: ہمیں شعبہ نے حدیث سنائی۔\nابن مثنیٰ کی حدیث میں ہے،حکم نے کہا: میں نے ابراہیم کو حدیث بیان کرتے ہوئے سنا۔ (آگے وہی حدیث ہے جو اوپر بیان ہو ئی۔)"}],[631,"عبید اللہ نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سےر وایت کی کہ سیدنا عمر رضی اللہ عنہ نے پوچھا : اے اللہ کے رسول ! ہم میں سے کوئی جنابت کی حالت میں ہو تو کیا وہ ( اسی طرح ) سو سکتا ؟ آپ نے فرمایا : ’’ہاں ، جب وضو کر لے ۔ ‘‘","",{"u2":"عبید اللہ نے نافع سے، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سےر وایت کی کہ سیدنا عمر رضی اللہ عنہ نے پوچھا:اے اللہ کے رسول! ہم میں سے کوئی جنابت کی حالت میں ہو تو کیا وہ (اسی طرح) سو سکتا؟ آپ نے فرمایا:’’ہاں، جب وضو کر لے۔‘‘"}],[632,"ابن جریج سے روایت ہے ( کہا : ) مجھے نافع نے ابن عمر رضی اللہ عنہ سے روایت کرتے ہوئے خبر دی کہ سیدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ دریافت کیا اور کہا : کیا ہم میں سے کوئی شخص جنابت کی حالت میں سو سکتا ہے ؟ آپ نے فرمایا : ’’ہاں ، وضو کر لے پھر ( اس وقت تک کے لیے ) سو جائے جب وہ غسل کرنا چاہے ۔ ‘‘","",{"u2":"ابن جریج سے روایت ہے (کہا:) مجھے نافع نے ابن عمر رضی اللہ عنہ سے روایت کرتے ہوئے خبر دی کہ سیدنا عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ دریافت کیا اور کہا: کیا ہم میں سے کوئی شخص جنابت کی حالت میں سو سکتا ہے؟ آپ نے فرمایا:’’ہاں، وضو کر لے پھر (اس وقت تک کے لیے) سو جائے جب وہ غسل کرنا چاہے۔‘‘"}],[633,"عبداللہ بن دینار سے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے ذکر کیا کہ رات کے وقت وہ جنابت سے دو چار ہو جاتے ہیں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا : ’’وضو کر اور ( اس سے پہلے ) اپناعضو مخصوص دھولو ، پھر سو جاؤ ۔ ‘‘","",{"u2":"عبداللہ بن دینار سے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ عمر رضی اللہ عنہ نے رسو ل اللہ صلی اللہ علیہ وسلم کے سامنے ذکر کیا کہ رات کے وقت وہ جنابت سے دو چار ہو جاتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا:’’وضو کر اور (اس سے پہلے) اپناعضو مخصوص دھولو، پھر سو جاؤ۔‘‘"}],[634,"لیث نے معاویہ بن صالح سے ، انہوں نے عبد اللہ بن ابی قیس سے روایت کی ، انہوں نے کہا : میں نے سیدہ عائشہ ؓ سے رسول اللہ صلی اللہ علیہ وسلم کے وتر کے بارے میں سوال کیا ..... پھر آگے حدیث بیان کی کہ میں نے پوچھا : آپ صلی اللہ علیہ وسلم جنابت کی صورت میں کیا کرتے تھے؟ کیا سونے سے پہلے غسل فرماتے تھے یا غسل سے پہلے سوجاتے تھے ؟ انہوں نے جواب دیا : آپ یہ سب کر لیتے تھے ، بسااوقات نہا کرسوتےاور بسا اوقات وضو کر کے سو جاتے ۔ میں نے کہا : اللہ تعالیٰ کا شکر ہے جس نے ( دین کے ) معاملے میں وسعت رکھی ہے ۔","",{"u2":"لیث نے معاویہ بن صالح سے، انہوں نے عبد اللہ بن ابی قیس سے روایت کی، انہوں نے کہا:میں نے سیدہ عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے وتر کے بارے میں سوال کیا ..... پھر آگے حدیث بیان کی کہ میں نے پوچھا: آپ صلی اللہ علیہ وسلم جنابت کی صورت میں کیا کرتے تھے؟ کیا سونے سے پہلے غسل فرماتے تھے یا غسل سے پہلے سوجاتے تھے؟ انہوں نے جواب دیا:آپ یہ سب کر لیتے تھے، بسااوقات نہا کرسوتےاور بسا اوقات وضو کر کے سو جاتے۔ میں نے کہا: اللہ تعالیٰ کا شکر ہے جس نے (دین کے)معاملے میں وسعت رکھی ہے۔"}],[635,"عبدالرحمن بن مہدی اور ابن وہب دونوں نے معاویہ بن صالح سے سابقہ سند کے ساتھ یہی روایت بیان کی","",{"u2":"عبدالرحمن بن مہدی اور ابن وہب دونوں نے معاویہ بن صالح سے سابقہ سند کے ساتھ یہی روایت بیان کی"}],[636,"ابو بکر بن ابی شیبہ نے کہا : ہمیں حفص بن غیاث نے حدیث سنائی ، نیز ابو کریب نے کہا : ہمیں ابن ابی زائدہ نے خبر دی ، نیز عمرو ناقد اور ابن نمیر نے کہا : ہمیں مروان بن معاویہ فزاری نے حدیث سنائی ، ان سب ( حفص ، ابن ابی زائدہ اور مروان ) نے عاصم سے ، انہوں نے ابومتوکل سے اور انہو ں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کسی نے اپنی بیوی سے مباشرت کر لی ، پھر سے کرنا چاہے تو وہ وضو کر لے ۔ ‘‘ ( حفص بن غیاث سے روایت کرنے والے ) ابو بکر نے اپنی حدیث میں یہ اضافہ کیا : دونوں بار کے درمیان وضو کر لے ، نیز أن يعود ( پھر سے ) کے بجائےأن يعاود ( دوبارہ ) کے الفاظ استعمال کیے ۔","",{"u2":"ابو بکر بن ابی شیبہ نے کہا:ہمیں حفص بن غیاث نے حدیث سنائی، نیز ابو کریب نے کہا: ہمیں ابن ابی زائدہ نے خبر دی، نیز عمرو ناقد اور ابن نمیر نے کہا: ہمیں مروان بن معاویہ فزاری نے حدیث سنائی، ان سب (حفص، ابن ابی زائدہ اور مروان)نے عاصم سے، انہوں نے ابومتوکل سے اور انہو ں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب تم میں سے کسی نے اپنی بیوی سے مباشرت کر لی، پھر سے کرنا چاہے تو وہ وضو کر لے۔ ‘‘ (حفص بن غیاث سے روایت کرنے والے) ابو بکر نے اپنی حدیث میں یہ اضافہ کیا: دونوں بار کے درمیان وضو کر لے، نیز أن یعود(پھر سے) کے بجائےأن یعاود(دوبارہ) کے الفاظ استعمال کیے۔"}],[637,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک ہی غسل سے اپنی ( ایک سے زیادہ ) بیویوں کے پاس جاتے تھے ۔","",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک ہی غسل سے اپنی (ایک سے زیادہ) بیویوں کے پاس جاتے تھے۔"}],[638,"اسحاق بن ابی طلحہ نےکہاکہ مجھے سیدنا انس رضی اللہ عنہ نے یہ حدیث سنائی کہ ام سلیم رضی اللہ عنہ جو ( سیدنا انس رضی اللہ عنہ کی والدہ اور ) اسحاق کی دادی تھیں ، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور آپ سے کہنے لگیں جبکہ سیدہ عائشہ ؓ بھی آپ کے پاس موجود تھیں ، اے اللہ کے رسول ! عورت بھی نیند کے عالم میں اسی طرح خواب دیکھتی ہے جس طرح مرد دیکھتا ہے ، وہ اپنے آپ سے وہی چیز ( نکلتی ہوئی ) دیکھتی ہے جو مرد اپنے حوالے سے دیکھتا ہے ( تو وہ کیا کرے ؟ ) سیدہ عائشہ ؓ کہنے لگیں : ام سلیم ! تو نے عورتوں کو رسوا کر دیا ، تیرا دایاں ہاتھ خاک آلود ہو ( ان کا یہ کہا کہ تیرادایاں ہاتھ خاک آلود ہو ، بری نہیں بلکہ اچھی بات تھی ) تو آپ صلی اللہ علیہ وسلم نے عائشہ ؓ سے فرمایا : ’’بلکہ تمہارا دایاں ہاتھ خاک آلود ہو ۔ ہاں ام سلیم!جب وہ یہ دیکھے تو غسل کرے ۔ ‘‘","",{"u2":"اسحاق بن ابی طلحہ نےکہاکہ مجھے سیدنا انس رضی اللہ عنہ نے یہ حدیث سنائی کہ ام سلیم رضی اللہ عنہا جو (سیدنا انس رضی اللہ عنہ کی والدہ اور) اسحاق کی دادی تھیں، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور آپ سے کہنے لگیں جبکہ سیدہ عائشہ رضی اللہ عنہا بھی آپ کے پاس موجود تھیں، اے اللہ کے رسول! عورت بھی نیند کے عالم میں اسی طرح خواب دیکھتی ہے جس طرح مرد دیکھتا ہے، وہ اپنے آپ سے وہی چیز(نکلتی ہوئی) دیکھتی ہے جو مرد اپنے حوالے سے دیکھتا ہے (تو وہ کیا کرے؟) سیدہ عائشہ رضی اللہ عنہا کہنے لگیں:ام سلیم! تو نے عورتوں کو رسوا کر دیا، تیرا دایاں ہاتھ خاک آلود ہو (ان کا یہ کہا کہ تیرادایاں ہاتھ خاک آلود ہو، بری نہیں بلکہ اچھی بات تھی) تو آپ صلی اللہ علیہ وسلم نے عائشہ رضی اللہ عنہا سےفرمایا:’’بلکہ تمہارا دایاں ہاتھ خاک آلود ہو۔ ہاں ام سلیم!جب وہ یہ دیکھے تو غسل کرے۔‘‘"}],[639,"قتادہ سےروایت ہے کہ سیدنا انس بن مالک رضی اللہ عنہ نے انہیں حدیث سنائی کہ ام سلیم ؓ نے ( انہیں ) بتایا کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے ایسی عورت کے بارے میں پوچھا جو نیند میں وہی چیز دیکھتی ہے جو مرد دیکھتا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب عورت یہ چیز دیکھے تو غسل کرے ۔ ‘‘ ام المومنین سیدہ ام سلمہ ؓ نے فرمایا : میں اس بات پر شرما گئی ۔ ( پھر ) آپ بولیں : کیا ایسا بھی ہوتا ہے ؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’ہاں ، ( ورنہ ) پھر مشابہت کیسے پیدا ہوتی ہے ؟مرد کا پانی گاڑھا سفید ہوتا ہے اور عورت کا پانی پتلا اور زرد ہوتا ہے ، ان دونوں میں سے جس ( کے حصے ) کو غلبہ مل جائے یا ( نئی تشکیل میں ) سبقت لے جائے تو اسی سے ( بچے کی ) مشابہت ہوتی ہے ۔ ‘‘","",{"u2":"قتادہ سےروایت ہے کہ سیدنا انس بن مالک رضی اللہ عنہ نے انہیں حدیث سنائی کہ ام سلیم رضی اللہ عنہا نے (انہیں) بتایا کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے ایسی عورت کے بارے میں پوچھا جونیند میں وہی چیز دیکھتی ہے جو مرد دیکھتا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب عورت یہ چیز دیکھے تو غسل کرے۔ ‘‘ ام المومنین سیدہ ام سلمہ رضی اللہ عنہا نے فرمایا:میں اس بات پر شرما گئی۔ (پھر) آپ بولیں:کیا ایسا بھی ہوتا ہے؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں،(ورنہ) پھر مشابہت کیسے پیدا ہوتی ہے؟مرد کا پانی گاڑھا سفید ہوتا ہے اور عورت کا پانی پتلا اور زرد ہوتا ہے، ان دونوں میں سے جس (کے حصے) کو غلبہ مل جائے یا (نئی تشکیل میں) سبقت لے جائے تو اسی سے (بچے کی) مشابہت ہوتی ہے۔ ‘‘"}],[640,"ابو مالک اشجعی نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے اس عورت کےبارے میں پوچھا جو نیند میں وہی چیز دیکھتی ہے جو مرد اپنی نیند میں دیکھتا ہے تو آپ نے فرمایا : ’’ جب اس کو وہ صورت پیش آئے جو مرد کو پیش آتی ہے تو وہ غسل کرے ۔ ‘‘","",{"u2":"ابو مالک اشجعی نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا:ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے اس عورت کےبارے میں پوچھا جو نیند میں وہی چیز دیکھتی ہے جو مرد اپنی نیند میں دیکھتا ہے تو آپ نے فرمایا:’’ جب اس کو وہ صورت پیش آئے جو مرد کو پیش آتی ہے تو وہ غسل کرے۔ ‘‘"}],[641,"ابو معاویہ نے ہشام بن عروہ سے ، انہوں نے اپنےوالد سے ، انہوں نے زینب بنت ابی سلمہ سے اور انہوں نے ( اپنی والدہ ) سیدہ ام سلمہ ؓسے روایت کی کہ ام سلیم ؓ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور عرض کی : اے اللہ کے رسول ! اللہ تعالیٰ حق سے حیا محسوس نہیں کرتا تو کیا عورت کو احتلام ہو جائے تو اس پر غسل ہے ؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ ہاں ، جب ( منی کا ) پانی دیکھے ۔ ‘‘ ام سلمہؓ نے پوچھا : اے اللہ کے رسول! عورت کو بھی احتلام ہوتا ہے ؟آپ نے فرمایا : ’’تیرے دونوں ہاتھ خاک آلود ہوں ، اس کا بچہ اس کے مشابہ کیسے ہو جاتا ہے ! ‘‘ ( یعنی نطفے کی تشکیل میں دونوں کے مادے کا حصہ ہوتا ۔)","",{"u2":"ابو معاویہ نے ہشام بن عروہ سے، انہوں نے اپنےوالد سے، انہوں نے زینب بنت ابی سلمہ سے اور انہوں نے (اپنی والدہ) سیدہ ام سلمہ رضی اللہ عنہا سے روایت کی کہ ام سلیم رضی اللہ عنہا نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور عرض کی: اے اللہ کے رسول! اللہ تعالیٰ حق سے حیا محسوس نہیں کرتا تو کیا عورت کو احتلام ہو جائے تو اس پر غسل ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ ہاں،جب (منی کا) پانی دیکھے۔‘‘ ام سلمہ رضی اللہ عنہا نے پوچھا: اے اللہ کے رسول! عورت کو بھی احتلام ہوتا ہے؟آپ نے فرمایا:’’تیرے دونوں ہاتھ خاک آلود ہوں، اس کا بچہ اس کے مشابہ کیسے ہو جاتا ہے!‘‘ (یعنی نطفے کی تشکیل میں دونوں کے مادے کا حصہ ہوتا۔)"}],[642,"ہشام کے دو شاگردوں وکیع اور سفیان نے باقی ماندہ سابقہ سند کے ساتھ اسی ( سابقہ حدیث ) کے ہم معنی حدیث بیان کی لیکن انہوں نے یہ اضافہ کیا ہے : ام سلمہ ؓ نے بتایا کہ میں نے کہا : تو نے عورتوں کو رسوا کر دیا ۔ ( سیدہ عائشہ اور سیدہ ام سلمہ ؓ دونوں موجود تھیں ، تعجب کی بنا پر دونوں کے منہ سے یہی بات نکلی ۔)","",{"u2":"ہشام کے دو شاگردوں وکیع اور سفیان نے باقی ماندہ سابقہ سند کے ساتھ اسی (سابقہ حدیث) کے ہم معنی حدیث بیان کی لیکن انہوں نے یہ اضافہ کیا ہے: ام سلمہ رضی اللہ عنہا نے بتایا کہ میں نے کہا: تو نے عورتوں کو رسوا کر دیا۔ (حضرت عائشہ اور سیدہ ام سلمہ رضی اللہ عنہا دونوں موجود تھیں، تعجب کی بنا پر دونوں کے منہ سے یہی بات نکلی۔)"}],[643,"ابن شہاب نے کہا : مجھے عروہ بن زبیر نے خبر دی کہ سیدہ عائشہ ؓ نے انہیں بتایا کہ ام سلیم ؓ جو ابو طلحہ کےبیٹوں کی ماں ہیں ، رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں .... آگے ہشام کی حدیث کے ہم معنی بیان کیا ۔ البتہ اس میں یہ ہے کہ انہوں ( عروہ ) نے کہا : سیدہ عائشہ ؓ نے کہا : میں نے اس سے کہا : تجھ پر افسوس ! کیا عورت کو بھی ایسا نظر آتا ہے ؟","",{"u2":"ابن شہاب نے کہا: مجھے عروہ بن زبیر نے خبر دی کہ سیدہ عائشہ رضی اللہ عنہا نے انہیں بتایا کہ ام سلیم رضی اللہ عنہا جو ابو طلحہ کےبیٹوں کی ماں ہیں، رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں .... آگے ہشام کی حدیث کے ہم معنی بیان کیا۔ البتہ اس میں یہ ہے کہ انہوں (عروہ) نے کہا: سیدہ عائشہ رضی اللہ عنہا نے کہا:میں نے اس سے کہا: تجھ پر افسوس! کیا عورت کو بھی ایسا نظر آتا ہے؟"}],[644,"مسافع بن عبد اللہ نے عروہ بن زبیر سے ، انہوں نے سیدہ عائشہ ؓ سے روایت کی کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی : کیا جب عورت کو احتلام ہو جائے اور وہ پانی دیکھے تو غسل کرے ؟ آپ نے فرمایا : ’’ہاں ۔ ‘‘ عائشہ ؓ نے اس عورت سے کہا : تیرے ہاتھ خاک آلود اور زخمی ہوں ۔ انہوں ( عائشہ ؓ ) نے کہا : تو رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : ’’اسے کچھ نہ کہو ، کیا ( بچے کی ) مشابہت اس کے علاوہ کسی اور وجہ سے ہوتی ہے ! جب ( نطفے کی تشکیل کے مرحلے میں ) اس کا پانی مرد کے پانی پر غالب آ جاتا ہے تو بچہ اپنے ماموؤں کے مشابہ ہوتا ہے اور جب مرد کاپانی عورت کے پانی پر غالب آتا ہے تو بچہ اپنے چچاؤں کے مشابہ ہوتا ہے ۔ ‘‘","",{"u2":"مسافع بن عبد اللہ نے عروہ بن زبیر سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی: کیا جب عورت کواحتلام ہو جائے اور وہ پانی دیکھے توغسل کرے؟ آپ نے فرمایا:’’ہاں۔ ‘‘عائشہ رضی اللہ عنہا نے اس عورت سےکہا: تیرے ہاتھ خاک آلود اور زخمی ہوں۔ انہوں (عائشہ رضی اللہ عنہا)نے کہا: تو رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:’’اسے کچھ نہ کہو، کیا (بچے کی) مشابہت اس کے علاوہ کسی اور وجہ سے ہوتی ہے! جب (نطفے کی تشکیل کے مرحلے میں) اس کا پانی مرد کے پانی پر غالب آ جاتا ہے تو بچہ اپنے ماموؤں کے مشابہ ہوتا ہے اور جب مرد کاپانی عورت کے پانی پر غالب آتا ہے تو بچہ اپنے چچاؤں کےمشابہ ہوتا ہے۔‘‘"}],[645,"ابو توبہ نے ، جو ربیع بن نافع ہیں ، ہم سے حدیث بیان کی ، کہا : معاویہ بن سلام نے ہمیں اپنے بھائی زید سے حدیث سنائی ، کہا : انہوں نے ابوسلام سے سنا ، کہا : مجھ سے ابو اسماء رحبی نے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم کے آزادکردہ غلام ثوبان رضی اللہ عنہ نے انہیں یہ حدیث سنائی ، کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے پاس کھڑا تھا ایک یہودی عالم ( حبر ) آپ کے پاس آیا اور کہا : اے محمد! آپ پر سلام ہو ، میں نے اس کو اتنے زور سے دھکا دیا کہ وہ گرتے گرتے بچا ۔ اس نے کہا : مجھے دھکا کیوں دیتے ہو؟ میں نے کہا : تم یا رسول اللہ ! نہیں کہہ سکتے ؟ یہودی نے کہا : ہم تو آپ کو اسی نام سے پکارتے ہیں جو آپ کے گھر والوں نے آپ کا رکھا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’یقیناً میرا نام محمد ( صلی اللہ علیہ وسلم ) ہے جو میرے گھر والوں نے رکھا ہے ۔ ‘‘ یہودی بولا : میں آپ سے پوچھنے آیا ہوں ۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا : ’’اگر میں تمہیں کچھ بتاؤں گا تو کیا تمہیں اس سے فائدہ ہو گا؟ ‘‘ اس نے کہا : میں اپنے دونوں کانو ں سے توجہ سے سنوں گا ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ایک چھڑی ، جو آپ کے پاس تھی ، زمین پر آہستہ آہستہ ماری اور فرمایا : ’’پوچھو ۔ ‘‘ یہودی نے کہا : جس دن زمین دوسری زمین سے بدلے گی اور آسمان ( بھی ) بدلے جائیں گے تو لوگ کہاں ہوں گے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ وہ پل ( صراط ) سے ( ذرا ) پہلے اندھیرے میں ہوں گے؟ آپ نے فرمایا : ’’فقرائے مہاجرین ۔ ‘‘ یہودی نے پوچھا : جب وہ جنت میں داخل ہوں گے تو ان کو کیا پیش کیا جائےگا؟ تو آپ نے فرمایا : ’’مچھلی کےجگر کا زائد حصہ ۔ ‘‘ اس نے کہا : اس کے بعد ان کا کھانا کیا ہوگا؟ آپ نے فرمایا : ’’ان کے لیے جنت میں بیل ذبح کیا جائے گا جو اس کے اطراف میں چرتا پھرتا ہے ۔ ‘‘ اس نے کہا : اس ( کھانے ) پر ان مشروب کیا ہو گا؟آپ نے فرمایا : ’’اس ( جنت ) کے سلسبیل نامی چشمے سے ۔ ‘‘ اس نے کہا : آپ نے سچ کہا ، پھر کہا : میں آپ سے ایک چیز کے بارے میں پوچھنے آیا ہوں جسے اہل زمین سے محض ایک بنی جانتا ہے یا ایک دو اور انسان ۔ آپ نےفرمایا : ’’اگر میں تمہیں بتا دیا تو کیا تمہیں اس سے فائدہ ہوگا؟ ‘‘ اس نے کہا : میں کان لگا کر سنوں گا ۔ اس نے کہا : میں آپ سے اولاد کے بارے میں پوچھنے آیا ہوں ۔ آپ نےفرمایا : ’’ مرد کا پانی سفید ہوتا ہے اور عورت کا پانی زرد ، جب دونوں ملتے ہیں اور مرد کا مادہ منویہ عورت کی منی سے غالب آ جاتا ہے تو اللہ کے حکم سے دونوں کے ہاں بیٹا پیدا ہوتا ہے اور جب عورت کی منی مرد کی منی پر غالب آ جاتی ہے تو اللہ عزوجل کے حکم سے دونوں کے ہاں بیٹی پیدا ہوتی ۔ ‘‘ یہودی نے کہا : آپ نے واقعی صحیح فرمایا اور آپ یقیناً نبی ہیں ، پھر وہ پلٹ کر چلا گیا ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’اس نے مجھ سے جس چیز کے بارے میں سوال کیا اس وقت تک مجھے اس میں سے کسی چیز کا کچھ علم نہ تھا حتی کہ اللہ تعالیٰ نے مجھے اس کا علم عطا کر دیا ۔ ‘‘","",{"u2":"ابو توبہ نے، جو ربیع بن نافع ہیں، ہم سے حدیث بیان کی، کہا: معاویہ بن سلام نے ہمیں اپنےبھائی زید سے حدیث سنائی،کہا: انہوں نے ابوسلام سے سنا،کہا: مجھ سے ابو اسماء رحبی نے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم کے آزادکردہ غلام ثوبان رضی اللہ عنہ نے انہیں یہ حدیث سنائی،کہا: میں رسول ا للہ صلی اللہ علیہ وسلم کے پاس کھڑا تھا ایک یہودی عالم (حبر) آپ کے پاس آیا اورکہا: اے محمد! آپ پر سلام ہو، میں نے اس کو اتنے زور سے دھکا دیا کہ وہ گرتے گرتے بچا۔ اس نے کہا: مجھے دھکا کیوں دیتے ہو؟ میں نے کہا: تم یا رسول اللہ! نہیں کہہ سکتے؟ یہودی نے کہا: ہم تو آپ کو اسی نام سے پکارتے ہیں جو آپ کے گھر والوں نے آپ کا رکھا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’یقیناً میرا نام محمد(صلی اللہ علیہ وسلم) ہے جو میرے گھر والوں نے رکھا ہے۔ ‘‘ یہودی بولا: میں آپ سے پوچھنے آیا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے فرمایا:’’اگر میں تمہیں کچھ بتاؤں گا تو کیا تمہیں اس سے فائدہ ہو گا؟ ‘‘ اس نے کہا: میں اپنے دونوں کانو ں سے توجہ سے سنوں گا۔تورسول اللہ صلی اللہ علیہ وسلم نے ایک چھڑی، جو آپ کے پاس تھی، زمین پر آہستہ آہستہ ماری اور فرمایا: ’’پوچھو۔‘‘ یہودی نے کہا: جس دن زمین دوسری زمین سے بدلے گی اور آسمان (بھی) بدلے جائیں گے تو لوگ کہاں ہوں گے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ وہ پل (صراط)سے (ذرا) پہلے اندھیرے میں ہوں گے؟ آپ نے فرمایا:’’فقرائے مہاجرین۔‘‘ یہودی نے پوچھا: جب وہ جنت میں داخل ہوں گے تو ان کو کیا پیش کیا جائےگا؟ تو آپ نے فرمایا:’’مچھلی کےجگر کا زائد حصہ۔ ‘‘ اس نے کہا:اس کے بعد ان کا کھانا کیا ہوگا؟ آپ نے فرمایا:’’ان کے لیے جنت میں بیل ذبح کیا جائے گا جو اس کے اطراف میں چرتا پھرتا ہے۔‘‘ اس نے کہا:اس (کھانے) پر ان مشروب کیا ہو گا؟آپ نے فرمایا:’’اس (جنت) کے سلسبیل نامی چشمے سے۔‘‘ اس نے کہا:آپ نے سچ کہا، پھر کہا: میں آپ سے ایک چیز کے بارے میں پوچھنے آیا ہوں جسے اہل زمین سے محض ایک بنی جانتا ہے یاایک دو اور انسان۔ آپ نےفرمایا:’’اگر میں تمہیں بتا دیا تو کیا تمہیں اس سے فائدہ ہوگا؟ ‘‘ اس نے کہا: میں کان لگا کر سنوں گا۔ اس نے کہا: میں آپ سے اولاد کے بارے میں پوچھنے آیا ہوں۔ آپ نےفرمایا:’’ مرد کا پانی سفید ہوتا ہے اور عورت کا پانی زرد، جب دونوں ملتے ہیں اور مرد کا مادہ منویہ عورت کی منی سے غالب آ جاتا ہے تو اللہ کے حکم سے دونوں کے ہاں بیٹا پیدا ہوتا ہے اور جب عورت کی منی مرد کی منی پر غالب آ جاتی ہے تو اللہ عزوجل کے حکم سے دونوں کےہاں بیٹی پیدا ہوتی۔ ‘‘ یہودی نے کہا: آپ نے واقعی صحیح فرمایا اور آپ یقیناً نبی ہیں، پھر وہ پلٹ کر چلا گیا۔\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’اس نے مجھ سے جس چیز کے بارے میں سوال کیا اس وقت تک مجھے اس میں سے کسی چیز کا کچھ علم نہ تھاحتی کہ اللہ تعالیٰ نے مجھے اس کا علم عطا کر دیا۔‘‘"}],[646,"یحییٰ بن حسان نے ہمیں خبر دی کہ ہمیں معاویہ بن سلام نے اسی اسناد کے ساتھ اسی طرح حدیث سنائی ، سوائے اس کے کہ ( یحییٰ نے ) قائما ( کھڑا تھا ) کے بجائے قاعداً ( بیٹھا تھا ) کہا اور ( زیادۃ کبد النون کے بجائے ) زائدۃ کبدالنون کہا ( معنی ایک ہی ہے ) اور انہوں نے اذکر و آنت ( اس کے ہاں بیٹا اور بیٹی کی ولادت ہوتی ہے ) کے الفاظ کہے ، اور اذکر و آنثا ( ان دونوں کے ہاں بیٹا پیدا ہوا ہے اور ان دونوں کے ہاں بیٹی پیدا ہوتی ہے ) کے الفاظ نہیں کہے ۔","",{"u2":"یحییٰ بن حسان نے ہمیں خبر دی کہ ہمیں معاویہ بن سلام نے اسی اسناد کے ساتھ اسی طرح حدیث سنائی، سوائے اس کے کہ (یحییٰ نے)قائما(کھڑا تھا) کے بجائے قاعداً (بیٹھاتھا)کہا اور (زیادۃ کبد النون کے بجائے) زائدۃ کبدالنون کہا(معنی ایک ہی ہے) اور انہوں نے اذکر و آنت (اس کے ہاں بیٹا اور بیٹی کی ولادت ہوتی ہے) کے الفاظ کہے، اور اذکر و آنثا(ان دونوں کے ہاں بیٹا پیدا ہوا ہےاور ان دونوں کے ہاں بیٹی پیدا ہوتی ہے) کے الفاظ نہیں کہے۔"}],[647,"ابو معاویہ نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ ؓ سے ر وایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم غسل جنابت فرماتے تو پہلے اپنے ہاتھ دھوتے ، پھر دائیں ہاتھ سے بائیں ہاتھ پر پانی ڈال کر اپنی شرم گاہ دھوتے ، پھر نماز کے وضو کی مانند وضو فرماتے ، پھر پانی لے کر انگلیوں کو بالوں کی جڑوں میں داخل کرتے ، جب آپ سمجھتے کہ آپ نے اچھی طرح جڑوں میں پانی پہنچا دیا ہے ۔ تو اپنے سر پر دونوں ہاتھوں سے تین چلو ڈالتے ۔ پھر سارے جسم پر پانی ڈالتے ( اور جسم دھوتے ) پھر ( آخر میں ) اپنے دونوں پاؤں دھو لیتے ۔","",{"u2":"ابو معاویہ نے ہشام بن عروہ سے، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے ر وایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم غسل جنابت فرماتے تو پہلے اپنے ہاتھ دھوتے، پھر دائیں ہاتھ سے بائیں ہاتھ پر پانی ڈال کر اپنی شرم گاہ دھوتے، پھر نماز کے وضو کی مانند وضو فرماتے، پھر پانی لے کر انگلیوں کو بالوں کی جڑوں میں داخل کرتے، جب آپ سمجھتے کہ آپ نے اچھی طرح جڑوں میں پانی پہنچا دیا ہے۔ تواپنے سر پر دونوں ہاتھوں سے تین چلو ڈالتے۔ پھر سارے جسم پر پانی ڈالتے (اور جسم دھوتے) پھر (آخر میں) اپنے دونوں پاؤں دھو لیتے۔\nجریر، علی بن مسہر اور ابن نمیر نے ہشام کی اسی سند کے ساتھ (یہ) حدیث روایت کی لیکن ان (تینوں) کی حدیث میں پاؤں دھونے کا ذکر نہیں ہے۔"}],[648,"جریر ، علی بن مسہر اور ابن نمیر نے ہشام کی اسی سند کے ساتھ ( یہ ) حدیث روایت کی لیکن ان ( تینوں ) کی حدیث میں پاؤں دھونے کا ذکر نہیں ہے ۔","",{"u2":"وکیع نے ہشام کی اسی سند کے ساتھ سیدہ عائشہ رضی اللہ عنہا سے حدیث بیان کی کہ رسو ل اللہ صلی اللہ علیہ وسلم نے جنابت سےغسل فرمایا، آغاز کرتے ہوئے تین بار ہتھلیاں دھوئیں ..... پھر ابو معاویہ کی حدیث کی طرح بیان کیا، تاہم پاؤں دھونے کا ذکر نہ کیا۔"}],[649,"وکیع نے ہشام کی اسی سند کے ساتھ سیدہ عائشہ ؓ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے جنابت سے غسل فرمایا ، آغاز کرتے ہوئے تین بار ہتھلیاں دھوئیں ..... پھر ابو معاویہ کی حدیث کی طرح بیان کیا ، تاہم پاؤں دھونے کا ذکر نہ کیا ۔"],[650,"زائدہ نے ہشام سے اسی سند کے ساتھ سیدہ عائشہ ؓ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب غسل جنابت فرماتے ( تو ) اس طرح آغاز کرتے کہ برتن میں ہاتھ داخل کرنے سے پہلے اپنے دونوں ہاتھ دھوتے ، پھر نماز کے لیے اپنے وضو کی طرح وضو فرماتے ۔","",{"u2":"زائدہ نے ہشام سے اسی سند کے ساتھ سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب غسل جنابت فرماتے (تو) اس طرح آغاز کرتے کہ برتن میں ہاتھ داخل کرنے سے پہلے اپنے دونوں ہاتھ دھوتے، پھر نماز کے لیے اپنے وضو کی طرح وضو فرماتے۔"}],[651,"عیسیٰ بن یونس نے ہم سے حدیث بیان کی ، ( کہا : ) ہم سے اعمش نے حدیث بیان کی ، انہوں نے سالم بن ابی جعد سے ، انہوں نے کریب سے ، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : مجھے میری خالہ میمونہ ؓ نے بتایا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے غسل جنابت کے لیے آپ کے قریب پانی رکھا ، آپ نے اپنی دونوں ہتھیلیوں کو دو یا تین دفعہ دھویا ، پھر اپنا ( دایاں ) ہاتھ برتن میں داخل کیا اور اس کے ذریعے سے اپنی شرم گاہ پر پانی ڈالا اور اسے اپنے بائیں ہاتھ سے دھویا ، پھر اپنے بائیں ہاتھ کو زمین پر مار کر اچھی طرح رگڑ اور اپنا نماز جیسا وضو فرمایا ، پھر ہتھیلی بھر کر تین لپ پانی اپنے سر پر ڈالا ، پھر اپنے سارے جسم کو دھویا ، پھر اپنی اس جگہ سے دور ہٹ گئے اور اپنے دونوں پاؤں دھوئے ، پھر میں تولیہ آپ کے پاس لائی تو آپ نے اسے واپس کر دیا ۔","",{"u2":"عیسیٰ بن یونس نے ہم سے حدیث بیان کی، (کہا:)ہم سے اعمش نے حدیث بیان کی، انہوں نے سالم بن ابی جعد سے، انہوں نے کریب سے، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی، کہا: مجھے میری خالہ میمونہ رضی اللہ عنہا نے بتایا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے غسل جنابت کے لیے آپ کے قریب پانی رکھا، آپ نے اپنی دونوں ہتھیلیوں کو دو یا تین دفعہ دھویا، پھر اپنا (دایاں) ہاتھ برتن میں داخل کیا اور اس کے ذریعے سے اپنی شرم گاہ پر پانی ڈالا اور اسے اپنے بائیں ہاتھ سے دھویا، پھر اپنے بائیں ہاتھ کو زمین پر مار کر اچھی طرح رگڑ اور اپنا نماز جیسا وضو فرمایا،پھر ہتھیلی بھر کر تین لپ پانی اپنے سر پر ڈالا، پھر اپنے سارے جسم کو دھویا، پھر اپنی اس جگہ سے دور ہٹ گئے اور اپنے دونوں پاؤں دھوئے، پھر میں تولیہ آپ کے پاس لائی تو آپ نے اسے واپس کر دیا۔"}],[652,"وکیع اور ابو معاویہ نے اعمش کی سابقہ سندکے ساتھ یہ روایت بیان کی لیکن ان دونوں کی حدیث میں سر پر تین لپ ڈالنے کا ذکر نہیں ہے ۔ وکیع کی حدیث میں پورے وضو کی کیفیت کا بیان ہے ۔ اس میں ( انہوں نے ) کلی اور ناک میں پانی ڈالنے کا ذکر کیا ، اور ابو معاویہ کی حدیث میں تو لیے کا ذکر نہیں ہے ۔","",{"u2":"وکیع اور ابو معاویہ نے اعمش کی سابقہ سندکے ساتھ یہ روایت بیان کی لیکن ان دونوں کی حدیث میں سر پر تین لپ ڈالنے کا ذکر نہیں ہے۔ وکیع کی حدیث میں پورے وضو کی کیفیت کا بیان ہے۔ اس میں (انہوں نے) کلی اور ناک میں پانی ڈالنے کا ذکر کیا، اور ابو معاویہ کی حدیث میں تولیے کا ذکر نہیں ہے۔"}],[653,"عبد اللہ بن ادریس نے اعمش کی سابقہ سند کے ساتھ ابن عباس رضی اللہ عنہ سے سیدہ میمونہ ؓ کی روایت بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس تولیہ لایا گیا توآپ نے اسے ہاتھ نہ لگایا اور پانی کے ساتھ اس طرح کرنے لگے ، یعنی جھاڑنے لگے ۔","",{"u2":"عبد اللہ بن ادریس نے اعمش کی سابقہ سند کے ساتھ ابن عباس رضی اللہ عنہ سے سیدہ میمونہ رضی اللہ عنہا کی روایت بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس تولیہ لایا گیا توآپ نے اسے ہاتھ نہ لگایا اور پانی کے ساتھ اس طرح کرنے لگے،یعنی جھاڑنے لگے۔"}],[654,"قاسم ( بن محمدبن ابی بکر ) نے سیدہ عائشہ ؓ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم جب غسل جنابت فرماتے تو تقریباً اتنا بڑا برتن منگواتے جتنا اونٹنی کا دودھ دھونے کا ہوتا ہے ۔ اور چلو سے پانی لیتے اور سر کے دائیں حصے سے آغاز فرماتے ، پھر بائیں طرف ( پانی ڈالتے ) ، پھر دونوں ہاتھوں ( کا لپ بنا کر اس ) سے ( پانی ) لیتے اور ان سے سر پر ( پانی ) ڈالتے ۔","",{"u2":"قاسم (بن محمدبن ابی بکر) نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، کہا:رسول اللہ صلی اللہ علیہ وسلم جب غسل جنابت فرماتے تو تقریباً اتنا بڑا برتن منگواتے جتنا اونٹنی کا دودھ دھونے کا ہوتا ہے۔ اور چلو سے پانی لیتے اور سر کے دائیں حصے سےآغاز فرماتے، پھر بائیں طرف (پانی ڈالتے)، پھر دونوں ہاتھوں (کا لپ بنا کر اس) سے (پانی) لیتے اور ان سے سر پر (پانی) ڈالتے۔"}],[655,"امام مالک نے ابن شہاب ( زہری ) سے ، انہوں نے عروہ سے اور انہوں نےسیدہ عائشہ ؓ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک ہی برتن سے ، جو ایک فرق ( تین صاع یا ساڑھےتیرہ لٹر ) کا تھا ، غسل جنابت فرمایا کرتے تھے","",{"u2":"امام مالک نے ابن شہاب (زہری)سے، انہوں نے عروہ سے اور انہوں نےسیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک ہی برتن سے، جو ایک فرق (تین صاع یا ساڑھےتیرہ لٹر) کا تھا، غسل جنابت فرمایا کرتے تھے"}],[656,"قتیبہ بن سعید اور ابن رمح نے لیث سے ، اسی طرح قتیبہ بن سعید ، ابوبکر بن ابی شیبہ ، عمرو ناقد اور زہیر بن حرب نے سفیان سے حدیث بیان کی ، ان دونوں ( لیث اور سفیان ) نے زہری سے ، انہوں نے عروہ سے ، انہوں نے سیدہ عائشہؓ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک بڑے پیالے سے ، جو ایک فرق کی مقدار جتنا تھا ، غسل فرماتے ۔ میں اور آپ ایک برتن میں ( سے ) غسل کرتے تھے ۔ سفیان کی حدیث میں ( في الإنا ء الواحدکے بجائے ) من إناء واحد ( ایک برتن سے ) ہے ۔ قتیبہ نے کہا ، سفیان نے کہا : فرق تین صاع کا ہوتا ہے ۔","",{"u2":"قتیبہ بن سعید اور ابن رمح نے لیث سے، اسی طرح قتیبہ بن سعید، ابوبکر بن ابی شیبہ، عمرو ناقد اورزہیر بن حرب نے سفیان سے حدیث بیان کی، ان دونوں (لیث اور سفیان) نے زہری سے، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک بڑے پیالے سے، جو ایک فرق کی مقدارجتنا تھا، غسل فرماتے۔ میں اور آپ ایک برتن میں (سے) غسل کرتے تھے۔\nسفیان کی حدیث میں (فی الإنا ء الواحدکے بجائے) من إناء واحد (ایک برتن سے) ہے۔\nقتیبہ نے کہا، سفیان نے کہا: فرق تین صاع کا ہوتا ہے۔"}],[657,"ابو بکر بن حفص نے ابو سلمہ بن عبد الرحمن ( بن عوف جو سیدہ عائشہ کے رضاعی بھانجے تھے ) سےر وایت کی ، انہوں نے کہا : میں اور سیدہ عائشہ ؓ کا رضاعی بھائی ( عبد اللہ بن یزید ) ان کی خدمت میں حاضر ہوئے تو اس نے ان سے نبی اکرم صلی اللہ علیہ وسلم کے غسل جنابت کے بارے میں سوال کیا ، چنانچہ انہوں نے ایک صاع کے بقدربرتن منگوایا او راس سے غسل کیا ، ہمارے اور ان کے درمیان ( دیوار وغیرہ کا ) پردہ حائل تھا ، اپنے سر پر تین دفعہ پانی ڈالا ۔ ابو سلمہ نے بتایا کہ نبی اکرم صلی اللہ علیہ وسلم کی ازواج مطہرات اپنے سر ( کے بالوں ) کو کاٹ لیتی تھیں یہاں تک کہ وہ وفرہ ( کانوں کے نچلے حصے کی لمبائی کے بال ) کی طرح ہو جاتے ۔","",{"u2":"ابو بکر بن حفص نے ابو سلمہ بن عبد الرحمن (بن عوف جوحضرت عائشہ کے رضاعی بھانجے تھے) سےر وایت کی، انہوں نے کہا:میں اور سیدہ عائشہ رضی اللہ عنہا کا رضاعی بھائی(عبد اللہ بن یزید) ان کی خدمت میں حاضر ہوئے تو اس نے ان سے نبی اکرم صلی اللہ علیہ وسلم کے غسل جنابت کے بارے میں سوال کیا،چنانچہ انہوں نے ایک صاع کے بقدربرتن منگوایا او راس سے غسل کیا، ہمارے اور ان کے درمیان (دیوار وغیرہ کا) پردہ حائل تھا، اپنے سر پر تین دفعہ پانی ڈالا۔ ابو سلمہ نے بتایا کہ نبی اکرم صلی اللہ علیہ وسلم کی ازواج مطہرات اپنے سر (کے بالوں) کو کاٹ لیتی تھیں یہاں تک کہ وہ وفرہ (کانوں کے نچلے حصے کی لمبائی کے بال) کی طرح ہو جاتے۔"}],[658,"بکیر بن عبداللہ نے ابو سلمہ بن عبدالرحمن سے روایت کی ، کہا : سیدہ عائشہ ؓ نے فرمایا : جب رسول اللہ صلی اللہ علیہ وسلم غسل فرماتے تو دائیں ہاتھ سے آغاز فرماتے ، اس پر پانی ڈال کر اسے دھوتے ، پھر جہاں ناپسندیدہ چیز لگی ہوتی اسے دائیں ہاتھ سے پانی ڈال کر بائیں ہاتھ سے دھوتے ، جب اس سے فارغ ہو جاتے تو سر پر پانی ڈالتے ۔ سیدہ عائشہ ؓ نے بتایا کہ میں اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن سے نہاتے جب کہ دونوں جنابت کی حالت میں ہوتے ۔","",{"u2":"بکیر بن عبداللہ نے ابو سلمہ بن عبدالرحمن سے روایت کی، کہا: سیدہ عائشہ رضی اللہ عنہا نے فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم غسل فرماتے تودائیں ہاتھ سے آغاز فرماتے، اس پر پانی ڈال کر اسے دھوتے،پھر جہاں ناپسندیدہ چیز لگی ہوتی اسے دائیں ہاتھ سے پانی ڈال کر بائیں ہاتھ سے دھوتے، جب اس سے فارغ ہو جاتے تو سر پر پانی ڈالتے۔\nسیدہ عائشہ رضی اللہ عنہا نے بتایا کہ میں اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن سے نہاتے جب کہ دونوں جنابت کی حالت میں ہوتے۔"}],[659,"حفصہ بنت عبد الرحمن بن ابی بکر سے ( جو منذر بن زبیر کی اہلیہ تھیں ) روایت ہے کہ سیدہ عائشہؓ نے انہیں بتایا کہ وہ ( خود ) اور نبی اکرم صلی اللہ علیہ وسلم ایک برتن میں غسل کرتے جس میں تین مد ( مد ایک صاع کا چوتھاحصہ ہوتا ہے ) یا اس کے قریب پانی آتا","",{"u2":"حفصہ بنت عبد الرحمن بن ابی بکر سے (جو منذر بن زبیر کی اہلیہ تھیں) روایت ہے کہ سیدہ عائشہ رضی اللہ عنہا نے انہیں بتایا کہ وہ (خود) اور نبی اکرم صلی اللہ علیہ وسلم ایک برتن میں غسل کرتے جس میں تین مد (مد ایک صاع کا چوتھاحصہ ہوتا ہے) یا اس کے قریب پانی آتا"}],[660,"قاسم بن محمد ( بن ابی بکر ) نے سیدہ عائشہ ؓ سے روایت کی ، فرمایا : میں اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن سے غسل جنابت کرتے اور ہمارے ہاتھ باری باری اس میں جاتے","",{"u2":"قاسم بن محمد (بن ابی بکر) نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، فرمایا:میں اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن سے غسل جنابت کرتے اور ہمارے ہاتھ باری باری اس میں جاتے"}],[661,"(سیدہ عائشہ کی شاگرد ) معاذہ بنت عبد اللہ نے سیدہ عائشہ ؓ سے روایت کی ، انہوں نے کہا میں اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن سے ، جو میرے اور آپ کے درمیان ہوتا ، غسل کرتے ۔ آپ میری نسبت جلد پانی لیتے حتی کہ میں کہتی : میرے لیے چھوڑیے ، میرے لیے چھوڑیے ۔ وہ ( معاذہ ) کہتی ہے اوروہ دونوں جنبی ہوتے ۔","",{"u2":"(حضرت عائشہ کی شاگرد) معاذہ بنت عبد اللہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا میں اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن سے، جو میرے اور آپ کے درمیان ہوتا،غسل کرتے۔ آپ میری نسبت جلد پانی لیتے حتی کہ میں کہتی: میرے لیے چھوڑیے، میرے لیے چھوڑیے۔ وہ (معاذہ) کہتی ہے اوروہ دونوں جنبی ہوتے۔"}],[662,"سفیان نے عمرو سے ، انہوں نے ابو شعثاء سے ، انہوں نے ابن عباسؓ سے روایت کی ، کہا ، مجھے سیدہ میمونہ ؓ نے خبر دی کہ وہ اور نبی اکرم صلی اللہ علیہ وسلم ایک ( ہی ) برتن میں ( سے ) غسل کرتے تھے ۔","",{"u2":"سفیان نے عمرو سے، انہوں نے ابو شعثاء سے، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی، کہا، مجھے سیدہ میمونہ رضی اللہ عنہا نے خبر دی کہ وہ اور نبی اکرم صلی اللہ علیہ وسلم ایک (ہی) برتن میں (سے) غسل کرتے تھے۔"}],[663,"ابن جریج نے عمرو بن دینار سے روایت کی ، کہا : مجھے جتنا زیادہ ( سےزیادہ ) علم ہے اور جو میرے ذہن میں آتا ہے اس کے مطابق مجھے ابو شعثاء نے خبر دی کہ سیدنا ابن عباس رضی اللہ عنہ نے انہیں بتایاکہ رسول اللہ صلی اللہ علیہ وسلم میمونہ ؓ کے بچے ہوئے پانی سے نہالیتے تھے ۔","",{"u2":"ابن جریج نے عمرو بن دینار سے روایت کی، کہا: مجھے جتنا زیادہ (سےزیادہ) علم ہے اور جو میرے ذہن میں آتا ہے اس کے مطابق مجھے ابو شعثاء نے خبر دی کہ سیدنا ابن عباس رضی اللہ عنہ نے انہیں بتایاکہ رسول اللہ صلی اللہ علیہ وسلم میمونہ رضی اللہ عنہا کے بچے ہوئے پانی سے نہالیتے تھے۔"}],[664,"سیدہ ام سلمہ ؓ نے بیان کیا کہ وہ اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن میں ( سے ) غسل جنابت کرتے تھے ۔","",{"u2":"سیدہ ام سلمہ رضی اللہ عنہا نے بیان کیا کہ وہ اور رسول اللہ صلی اللہ علیہ وسلم ایک برتن میں (سے) غسل جنابت کرتے تھے۔"}],[665,"عبید اللہ بن معاذ نے بیان کی کہ ان کے والد نے انہیں حدیث سنائی اور ابن مثنی نے عبد الرحمان ، یعنی ابن مہدی سے حدیث بیان کی ، ان دونوں نے کہا : ہمیں شعبہ نے عبد اللہ بن عبداللہ بن جبر سے حدیث بیان کی ، کہا : میں نے سیدنا انس رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم پانچ مکوک سے غسل فرماتے اور ایک مکوک سے وضو فرماتے ۔ ( ایک مکوک سوا صاع کے برابر ہوتا ہے ۔ ) ابن مثنی نے مکاییک کی جگہ مکاکی ( تخفیف کے ساتھ وہی ) لفظ بولا ۔ عبید اللہ بن معاذ نے عبد اللہ بن عبد اللہ کہا اور ابن جبر کا ذکر نہیں کیا ۔","",{"u2":"عبید اللہ بن معاذ نے بیان کی کہ ان کے والد نے انہیں حدیث سنائی اور ابن مثنی نے عبد الرحمان،یعنی ابن مہدی سے حدیث بیان کی، ان دونوں نے کہا:ہمیں شعبہ نے عبد اللہ بن عبداللہ بن جبر سے حدیث بیان کی، کہا: میں نے سیدنا انس رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسو ل اللہ صلی اللہ علیہ وسلم پانچ مکوک سے غسل فرماتے اورایک مکوک سے وضو فرماتے۔ (ایک مکوک سوا صاع کے برابر ہوتا ہے۔)\nابن مثنی نے مکاییک کی جگہ مکاکی (تخفیف کے ساتھ وہی) لفظ بولا۔\nعبید اللہ بن معاذ نے عبد اللہ بن عبد اللہ کہا اور ابن جبر کا ذکر نہیں کیا۔"}],[666,"مسعر نے ابن جبر سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم ایک مد سے وضو فرماتے اور ایک صاع سے پانچ مد تک ( کے پانی ) سے غسل کرتے ۔","",{"u2":"مسعر نے ابن جبر سے،انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم ایک مد سے وضو فرماتے اور ایک صاع سے پانچ مد تک (کے پانی) سے غسل کرتے۔"}],[667,"بشر نے کہا : ہمیں ابو ریحانہ نے سیدنا سفینہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ایک صاع پانی سے غسل جنابت فرماتے اور ایک مد پانی سے وضو فرما لیتے ۔","",{"u2":"بشر نے کہا: ہمیں ابو ریحانہ نے سیدنا سفینہ رضی اللہ عنہ سےحدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایک صاع پانی سے غسل جنابت فرماتے اور ایک مد پانی سے وضو فرما لیتے۔"}],[668,"ابو بکر بن ابی شیبہ اور علی بن حجر نے اسماعیل بن علیہ سے ، انہوں نے ابو ریحانہ سے ، انہوں نےسیدنا سفینہؓ سے ( ابو بکر نےکہا : ) رسول اللہ صلی اللہ علیہ وسلم کے صحابی ( سیدنا سفینہ رضی اللہ عنہ ) سے روایت کی ، انہوں نےکہا : رسول اللہ صلی اللہ علیہ وسلم ایک صاع پانی سے غسل فرماتے اور ایک مد پانی سے وضو فرما لیتے ۔ ( علی ) ابن حجر کی روایت میں ہے کہ یا ( ابو ریحانہ نے ایک مد سے وضو فرما لیتے تھے کے بجائے ) ’’ایک مدپانی سے آپ کا وضو ہو جاتاتھا ‘‘ کہا ۔ ابو ریحانہ نے کہا : سفینہ رضی اللہ عنہ عمر رسیدہ ہو گئے تھے ، اس لیے مجھے ان کی حدیث پر اعتماد و وثوق نہیں ہے ۔","",{"u2":"ابو بکر بن ابی شیبہ اورعلی بن حجر نے اسماعیل بن علیہ سے، انہوں نے ابو ریحانہ سے، انہوں نےسیدنا سفینہ رضی اللہ عنہ سے (ابو بکر نےکہا:) رسول اللہ صلی اللہ علیہ وسلم کے صحابی (سیدنا سفینہ رضی اللہ عنہ) سے روایت کی، انہوں نےکہا: رسول اللہ صلی اللہ علیہ وسلم ایک صاع پانی سے غسل فرماتے اور ایک مد پانی سے وضو فرمالیتے۔\n(علی) ابن حجر کی روایت میں ہے کہ یا (ابو ریحانہ نے ایک مد سے وضو فرما لیتے تھے کے بجائے)’’ایک مدپانی سے آپ کا وضو ہو جاتاتھا‘‘ کہا۔ ابو ریحانہ نے کہا: سفینہ رضی اللہ عنہ عمر رسیدہ ہو گئے تھے، اس لیے مجھے ان کی حدیث پر اعتماد و وثوق نہیں ہے۔"}],[669,"ابو احوص نے ابو اسحاق سے ، انہو ں نے سلیمان بن صرد سے ، انہوں نے سیدنا جبیر بن مطعم رضی اللہ عنہ سے روایت کی ، کہا : کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس غسل کےمتعلق ایک دوسرے سے تکرار کی ، چنانچہ بعضوں نے کہا : لیکن میں ، میں تو سر کو اتنا اور اتنا دھو تا ہوں ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’لیکن میں تو اپنے سر پر تین ہتھلیاں بھر کر ( پانی ) ڈالتاہوں ۔ ‘‘","",{"u2":"ابو احوص نے ابو اسحاق سے، انہو ں نے سلیمان بن صرد سے، انہوں نے سیدنا جبیر بن مطعم رضی اللہ عنہ سے روایت کی، کہا: کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس غسل کےمتعلق ایک دوسرے سے تکرار کی، چنانچہ بعضوں نے کہا: لیکن میں، میں تو سر کو اتنا اور اتنا دھو تا ہوں۔ تو رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’لیکن میں تو اپنے سر پر تین ہتھلیاں بھر کر (پانی) ڈالتاہوں۔ ‘‘"}],[670,"شعبہ نے ابو ا سحاق سے ، انہوں نے سلیمان بن صرد سے ، انہوں نے سیدنا جبیر بن مطعم رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ کے پاس غسل جنابت کا ذکر کیا گیا تو آپ نے فرمایا : ’’ لیکن میں ، میں تو اپنے سر پر تین بار پانی بہاتا ہوں ۔ ‘‘","",{"u2":"شعبہ نے ابو ا سحاق سے، انہوں نے سلیمان بن صرد سے، انہوں نے سیدنا جبیر بن مطعم رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ کے پاس غسل جنابت کا ذکر کیا گیا تو آپ نے فرمایا:’’ لیکن میں، میں تو اپنے سر پر تین بار پانی بہاتا ہوں۔‘‘"}],[671,"یحییٰ بن یحییٰ اور اسماعیل بن سالم نے کہا : ہمیں ہشیم نے خبر دی ، انہوں نے ابو بشر سے ، انہوں نے ابو سفیان سے ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سےروایت کی کہ ثقیف کے وفد نے بنی صلی اللہ علیہ وسلم سے پوچھا ، او رکہا : ہمارا علاقہ ایک ٹھنڈا علاقہ ہے تو غسل کیسے ہو؟ آپ نے فرمایا : ’’لیکن میں ، میں تو اپنے سر پر تین بار پانی بہاتا ہوں ۔ ‘‘ ابن سالم نے اپنی روایت میں کہا : ہم سے ہشیم نے بیان کیا ، انہوں ابو بشر نے بتایا اور کہا : بلاشبہ ثقیف کے وفد نے ( سوال پوچھتے ہوئے آپ صلی اللہ علیہ وسلم کو مخاطب کر کے ) کہا : اے اللہ کے رسول","",{"u2":"یحییٰ بن یحییٰ اور اسماعیل بن سالم نے کہا: ہمیں ہشیم نے خبر دی، انہوں نے ابو بشر سے، انہوں نے ابو سفیان سے، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سےروایت کی کہ ثقیف کے وفد نے بنی صلی اللہ علیہ وسلم سے پوچھا، او رکہا:ہمارا علاقہ ایک ٹھنڈا علاقہ ہے تو غسل کیسے ہو؟ آپ نے فرمایا:’’لیکن میں، میں تو اپنے سر پر تین بارپانی بہاتا ہوں۔ ‘‘\nابن سالم نے اپنی روایت میں کہا:ہم سے ہشیم نے بیان کیا، انہوں ابو بشر نے بتایااور کہا: بلاشبہ ثقیف کے وفد نے (سوال پوچھتے ہوئے آپ صلی اللہ علیہ وسلم کو مخاطب کر کے) کہا: اے اللہ کے رسول!"}],[672,"امام جعفر کے والد امام محمد باقر بن علی بن حسین پ رضی اللہ عنہ نے سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب غسل جنابت کرتے تو سر پر پانی کی تین لپیں ڈالتے ، چنانچہ حسن بن محمد نے ان سے کہا : میرے بال تو زیادہ ہیں ۔ جابر رضی اللہ عنہ نے کہا : تو میں نے اس سے کہا : اے بھتیجے! رسول اللہ صلی اللہ علیہ وسلم کے بال تمہارے بالوں سےزیادہ اور عمدہ تھے ۔","",{"u2":"امام جعفر کےوالد امام محمد باقر بن علی بن حسین پ‎﷭ نے سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب غسل جنابت کرتے تو سر پر پانی کی تین لپیں ڈالتے، چنانچہ حسن بن محمد نے ان سے کہا: میرے بال تو زیادہ ہیں۔ جابر رضی اللہ عنہ نے کہا: تو میں نے اس سے کہا: اے بھتیجے! رسول اللہ صلی اللہ علیہ وسلم کے بال تمہارے بالوں سےزیادہ اور عمدہ تھے۔"}],[673,"سفیان بن عیینہ نے ایوب بن موسیٰ سے ، انہوں نے سعید بن ابی سعید مقبیری سے ، انہوں نے سیدہ ام سلمہ ؓ کے مولیٰ عبداللہ بن ابی رافع سے اور انہوں نے سیدہ ام سلمہؓ سے روایت کی ، انہوں نے کہا : میں نے عرض کی : اے اللہ کے رسول ! میں ایک ایسی عورت ہوں کہ کس کر سر کے بالوں کی چوٹی بناتی ہوں تو کیا غسل جنابت کے لیے اس کو کھولوں؟آپ نے فرمایا : ’’نہیں ، تمہیں بس اتنا ہی کافی ہے کہ اپنے سر پر تین چلو پانی ڈالو ، پھر اپنے آپ پر پانی بہا لو تم پاک ہو جاؤں گی ۔ ‘‘","",{"u2":"سفیان بن عیینہ نے ایوب بن موسیٰ سے، انہوں نے سعید بن ابی سعید مقبیری سے، انہوں نے سیدہ ام سلمہ رضی اللہ عنہا کے مولیٰ عبداللہ بن ابی رافع سے اور انہوں نے سیدہ ام سلمہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا:میں نے عرض کی:اے اللہ کے رسول! میں ایک ایسی عورت ہوں کہ کس کر سر کے بالوں کی چوٹی بناتی ہوں تو کیا غسل جنابت کے لیے اس کو کھولوں؟آپ نے فرمایا:’’نہیں، تمہیں بس اتنا ہی کافی ہے کہ اپنے سر پر تین چلو پانی ڈالو، پھر اپنے آپ پر پانی بہا لو تم پاک ہو جاؤں گی۔‘‘"}],[674,"یزید بن ہارون اور عبدالرزاق نے کہا : ہمیں اسی سند کے ساتھ سفیان ثوری نے ایوب بن موسیٰ کے حوالے سے خبر دی ۔ اور عبدالرزاق کی حدیث میں ہے : کیا میں حیض اور جنابت ( کے غسل ) کے لیے اس کو کھولوں؟ تو آپ نے فرمایا : ’’نہیں ۔ ‘‘ آگے ابن عیینہ کی حدیث کے ہم معنی ( روایت ) بیان کی ۔","",{"u2":"یزید بن ہارون اور عبدالرزاق نے کہا:ہمیں اسی سند کے ساتھ سفیان ثوری نے ایوب بن موسیٰ کے حوالے سے خبر دی۔اور عبدالرزاق کی حدیث میں ہے: کیا میں حیض اور جنابت (کے غسل) کے لیے اس کو کھولوں؟ تو آپ نے فرمایا:’’نہیں۔‘‘ آگے ابن عیینہ کی حدیث کے ہم معنی (روایت) بیان کی۔"}],[675,"ایوب بن موسیٰ سے ( سفیان ثوری کے بجائے ) روح بن قاسم نے اسی ( سابقہ سند ) کے ساتھ روایت کی کہ انہوں ( ام سلمہ ؓ ) نے کہا : کیا میں چوٹی کو کھول کر غسل جنابت کروں؟ ...... انہوں ( روح بن قاسم ) نے حیض کا تذکرہ نہیں کیا ۔","",{"u2":"ایوب بن موسیٰ سے (سفیان ثوری کے بجائے) روح بن قاسم نے اسی (سابقہ سند) کے ساتھ روایت کی کہ انہوں (ام سلمہ رضی اللہ عنہا) نے کہا:کیا میں چوٹی کو کھول کر غسل جنابت کروں؟ ...... انہوں (روح بن قاسم) نے حیض کا تذکرہ نہیں کیا۔"}],[676,"عبید اللہ بن عمیر سے روایت ہے ، انہوں نے کہا : سیدہ عائشہؓ کو یہ خبر پہنچی کہ عبداللہ بن عمروؓ عورتوں کو حکم دیتے ہیں کہ وہ غسل کرتے وقت سر کے بال کھولا کرین ۔ تو انہوں نے کہا : اس ابن عمرو پر تعجب ہے ، عورتوں کو حکم دیتا ہے کہ وہ جب غسل کریں تو سر کے بال کھولیں ، وہ انہیں یہ حکم کیوں نہیں دیتا کہ وہ اپنے سر کے بال مونڈ لیں ، میں اور رسول اللہ صلی اللہ علیہ وسلم ایک ہی برتن سے غسل کرتے تھے اور میں اس سے زائد کچھ نہیں کرتی تھی کہ اپنے سر پر تین بار پانی ڈال لیتی ۔","",{"u2":"عبید اللہ بن عمیر سے روایت ہے، انہوں نے کہا: سیدہ عائشہ رضی اللہ عنہا کو یہ خبر پہنچی کہ عبداللہ بن عمرو رضی اللہ عنہ عورتوں کو حکم دیتے ہیں کہ وہ غسل کرتے وقت سر کے بال کھولا کرین۔ تو انہوں نے کہا: اس ابن عمرو پر تعجب ہے، عورتوں کو حکم دیتا ہے کہ وہ جب غسل کریں تو سر کے بال کھولیں،وہ انہیں یہ حکم کیوں نہیں دیتا کہ وہ اپنے سر کے بال مونڈ لیں، میں اور رسول اللہ صلی اللہ علیہ وسلم ایک ہی برتن سے غسل کرتے تھے اور میں اس سے زائد کچھ نہیں کرتی تھی کہ اپنے سر پر تین بار پانی ڈال لیتی۔"}],[677,"عمرو بن محمد ناقد اور ابن ابی عمر نے سفیان بن عیینہ سے حدیث بیان کی ، عمرو نے کہا : ہمیں سفیان بن عیینہ نے منصور بن صفیہ سے ، انہوں نے اپنی والدہ ( صفیہ بنت شیبہ ) سے ، انۂں نے سیدہ عائشہ ؓ سے روایت کی ، انہوں نے کہا : ایک عورت نبی صلی اللہ علیہ وسلم سے پوچھا : وہ غسل حیض کیسے کرے ؟ کہا : پھر عائشہ ؓ نےبتایا کہ آپ نے اسے غسل کا طریقہ سکھایا ( اور فرمایا ) پھر وہ کستوری سے ( معطر ) کپڑے کا ایک ٹکڑالے کر اس سے پاکیزگی حاصل کرے ۔ عورت نے کہا : میں اس سے کیسے پاکیزگی حاصل کروں؟ آپ نے فرمایا : ’’ سبحان اللہ ! اس سے پاکیزگی حاصل کرو ۔ ‘‘ اور آپ نے ( حیا سے ) چہرہ چھپا کر دکھایا ۔ صفیہ نےکہا : عائشہ ؓ نے فرمایا : میں نے اس عورت کو اپنی طرف کھینچ لیا اور میں سمجھ گئی تھی کہ رسول اللہ صلی اللہ علیہ وسلم کیا ( کہنا ) چاہتے ہیں تو میں نےکہا : اس معطر ٹکڑے سے خون کے نشان صاف کرو ۔ ابن ابی عمرو نے اپنی روایت میں کہا : اس کو مل کر خون کے نشانات پر لگا کر صاف کرو ۔","",{"u2":"عمرو بن محمد ناقد اور ابن ابی عمر نے سفیان بن عیینہ سے حدیث بیان کی، عمرو نے کہا: ہمیں سفیان بن عیینہ نے منصور بن صفیہ سے، انہوں نے اپنی والدہ (صفیہ بنت شیبہ) سے، انۂں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا:ایک عورت نبی صلی اللہ علیہ وسلم سے پوچھا: وہ غسل حیض کیسے کرے؟ کہا:پھر عائشہ رضی اللہ عنہا نےبتایا کہ آپ نے اسے غسل کا طریقہ سکھایا (اور فرمایا) پھر وہ کستوری سے (معطر) کپڑے کا ایک ٹکڑالے کر اس سے پاکیزگی حاصل کرے۔ عورت نے کہا: میں اس سے کیسے پاکیزگی حاصل کروں؟ آپ نے فرمایا:’’ سبحان اللہ! اس سے پاکیزگی حاصل کرو۔ ‘‘ اور آپ نے (حیا سے) چہرہ چھپا کر دکھایا۔ صفیہ نےکہا: عائشہ رضی اللہ عنہا نے فرمایا: میں نے اس عورت کو اپنی طرف کھینچ لیا اور میں سمجھ گئی تھی کہ رسول اللہ صلی اللہ علیہ وسلم کیا (کہنا) چاہتے ہیں تو میں نےکہا: اس معطر ٹکڑے سے خون کے نشان صاف کرو۔ ابن ابی عمرو نے اپنی روایت میں کہا: اس کو مل کر خون کے نشانات پر لگا کر صاف کرو۔"}],[678,"وہیب نے کہا : ہمیں منصور نے اپنی والدہ ( صفیہ بنت شیبہ ) سے ، انہوں نے سیدہ عائشہؓ سے روایت کرتے ہوئے بیان کیا کہ ایک عورت نے نبی صلی اللہ علیہ وسلم سے پوچھا کہ میں پاکیزگی ( کے حصول ) کے لیے کیسے غسل کروں؟ تو آپ نے فرمایا : ’’کستوری سے معطر کپڑے کا ٹکڑا لے کر اس سے پاکیزگی حاصل کرو ۔ ‘‘ پھر سفیان کی طرح حدیث بیان کی ۔","",{"u2":"وہیب نے کہا:ہمیں منصور نے اپنی والدہ (صفیہ بنت شیبہ) سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہوئے بیان کیا کہ ایک عورت نے نبی صلی اللہ علیہ وسلم سے پوچھا کہ میں پاکیزگی (کے حصول) کے لیے کیسے غسل کروں؟ تو آپ نے فرمایا:’’کستوری سے معطر کپڑے کا ٹکڑا لے کر اس سے پاکیزگی حاصل کرو۔‘‘ پھر سفیان کی طرح حدیث بیان کی۔"}],[679,"محمد بن جعفر نے کہا : ہمیں شعبہ نے ابراہیم بن مہاجر سے حدیث سنائی ، انہوں نےکہا : میں نے صفیہ سے سنا وہ سیدہ عائشہؓ سے بیان کرتی تھیں کہ اسما ( بنت کشل انصاریہ ) ؓ نے نبی صلی اللہ علیہ وسلم سے غسل حیض کےبارے میں سوال کیا ؟ تو آپ نے فرمایا : ’’ایک عورت اپنا پانی او ربیری کے پتے لے کر اچھی طرح پاکیزگی حاصل کرے ، پھر سر پر پانی ڈال کر اس کو اچھی طرح ملے یہاں تک کہ بالوں کی جڑوں تک پہنچ جائے ، پھر اپنے اوپر پانی ڈالے ، پھر کستوری لگا کپڑے یا روئی کا ٹکڑا لے کر اس سے پاکیزگی حاصل کرے ۔ ‘‘ ‘ تو اسماء نے کہا : اس سے پاکیزگی کیسے حاصل کروں؟ آپ نے فرمایا : ’’سبحان اللہ ! اسے پاکیزگی حاصل کرو ۔ ‘‘ سیدہ عائشہؓ نے کہا : ( جیسے وہ اس بات کو چھپا رہی ہوں ) ’’خون کے نشان پر لگا کر ۔ ‘‘ اور اس نے آپ سے غسل جنابت کے بارے میں پوچھا تو آپ نے فرمایا : ’’ ( غسل کرنے والی ) پانی لے کر اس سے خوب اچھی طرح وضو کرے ، پھر سر پر پانی ڈال کر اسے ملے حتی کہ سر کے بالوں کی جڑوں تک پہنچ جائے ، پھر اپنے آپ پر پانی ڈالے ۔ ‘‘ سیدہ عائشہ ؓ نے کہا : انصار کی عورتیں بہت خوب ہیں ، دین کو اچھی طرح سمجھنے سے شرم ا نہیں نہیں روکتی ۔","",{"u2":"محمد بن جعفر نے کہا:ہمیں شعبہ نے ابراہیم بن مہاجر سے حدیث سنائی، انہوں نےکہا: میں نے صفیہ سے سنا وہ سیدہ عائشہ رضی اللہ عنہا سے بیان کرتی تھیں کہ اسما (بنت کشل انصاریہ) رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے غسل حیض کےبارے میں سوال کیا؟ تو آپ نے فرمایا:’’ایک عورت اپنا پانی او ربیری کے پتے لے کر اچھی طرح پاکیزگی حاصل کرے،پھر سر پر پانی ڈال کر اس کو اچھی طرح ملے یہاں تک کہ بالوں کی جڑوں تک پہنچ جائے، پھر اپنے اوپر پانی ڈالے، پھر کستوری لگا کپڑے یا روئی کا ٹکڑا لے کر اس سے پاکیزگی حاصل کرے۔‘‘‘ تو اسماء نے کہا: اس سے پاکیزگی کیسے حاصل کروں؟ آپ نے فرمایا:’’سبحان اللہ! اسے پاکیزگی حاصل کرو۔‘‘ سیدہ عائشہ رضی اللہ عنہا نے کہا:(جیسے وہ اس بات کو چھپا رہی ہوں)’’خون کے نشان پر لگا کر۔‘‘ اور اس نے آپ سے غسل جنابت کے بارے میں پوچھا تو آپ نے فرمایا: ’’(غسل کرنے والی) پانی لے کر اس سے خوب اچھی طرح وضو کرے، پھر سر پر پانی ڈال کر اسے ملے حتی کہ سر کے بالوں کی جڑوں تک پہنچ جائے، پھر اپنے آپ پر پانی ڈالے۔‘‘ سیدہ عائشہ رضی اللہ عنہا نے کہا: انصار کی عورتیں بہت خوب ہیں، دین کو اچھی طرح سمجھنے سے شرم ا نہیں نہیں روکتی۔"}],[680,"شعبہ کے ایک دوسرے شاگرد عبید اللہ کے والد معاذ بن معاذ عنبری نے کہا : ہمیں شعبہ نے اسی ( مذکورہ ) سند سے اسی ( سابقہ حدیث ) کے ہم معنی حدیث بیان کی اور کہا : آپ نے فرمایا : ’’سبحان اللہ !اس سے پاکیزگی حاصل کرو ‘‘ اور آپ نے اپنا چہرہ چھپا لیا ۔","",{"u2":"شعبہ کے ایک دوسرے شاگرد عبید اللہ کے والد معاذ بن معاذ عنبری نے کہا: ہمیں شعبہ نے اسی (مذکورہ) سند سے اسی (سابقہ حدیث) کے ہم معنی حدیث بیان کی اور کہا: آپ نے فرمایا:’’سبحان اللہ!اس سے پاکیزگی حاصل کرو‘‘ اور آپ نے اپنا چہرہ چھپا لیا۔"}],[681,"(شعبہ کے استاد ) ابراہیم بن مہاجر سے ( شعبہ کے بجائے ) ابو احوص کی سند سے صفیہ بنت شیبہ کے حوالے سے سیدہ عائشہؓ سے روایت ہے ، انہوں نےکہا : اسماءبنت شکل ؓ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور کہا : اے اللہ کے رسول! جب ہم میں سے کوئی عورت غسل حیض کرے تو کیسے نہائے؟ اور ( اسی طرح ) حدیث بیان کی اور اس میں غسل جنابت کا ذکر نہیں کیا ۔","",{"u2":"(شعبہ کے استاد) ابراہیم بن مہاجر سے (شعبہ کے بجائے) ابو احوص کی سند سے صفیہ بنت شیبہ کے حوالے سےسیدہ عائشہ رضی اللہ عنہا سے روایت ہے، انہوں نےکہا:اسماءبنت شکل رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور کہا: اے اللہ کے رسول! جب ہم میں سے کوئی عورت غسل حیض کرے تو کیسے نہائے؟ اور (اسی طرح) حدیث بیان کی اور اس میں غسل جنابت کا ذکر نہیں کیا۔"}],[682,"وکیع نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہؓ سے روایت کی ، انہوں نے کہا : فاطمہ بنت ابی حبیش نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور کہا : اے اللہ کے رسول ! میں ایک ایسی عورت ہوں جسے استحاضہ ہوتا ہے ، اس لیے میں پاک نہیں ہو سکتی تو کیا میں نماز چھوڑ دوں ؟ آپ نے فرمایا : ’’نہیں ، یہ تو بس ایک رگ ( کا خون ) ہے حیض نہیں ہے ، لہٰذا جب حیض شروع ہو تو نماز چھوڑ دو اور جب حیض بند ہو جائے تو اپنے ( جسم ) سے خون دھو لیا کرو اور نماز پڑھو ۔ ‘‘","",{"u2":"وکیع نے ہشام بن عروہ سے، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا:فاطمہ بنت ابی حبیش نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور کہا: اے اللہ کے رسول! میں ایک ایسی عورت ہوں جسے استحاضہ ہوتا ہے، اس لیے میں پاک نہیں ہو سکتی تو کیا میں نماز چھوڑ دوں؟ آپ نے فرمایا:’’نہیں، یہ تو بس ایک رگ (کا خون) ہے حیض نہیں ہے، لہٰذا جب حیض شروع ہو تو نماز چھوڑ دو اور جب حیض بند ہو جائے تو اپنے(جسم) سے خون دھو لیا کرو اور نماز پڑھو۔‘‘"}],[683,"ہشام نے عروہ کے ( شاگرد وکیع کے بجائے ) دوسرے شاگرد وں ابو معاویہ ، جریر ، نمیر اور حماد بن زید کی سندوں سے بھی جو وکیع کی حدیث کی طرح اسی سند سے مروی ہے ، البتہ قتیبہ سے جریر کی روایت کے الفاظ یوں ہیں : فاطمہ بنت ابی حبیش بن عبدالمطلب بن اسد آئیں جو ہمارے خاندان کی ایک خاتون ہیں ۔ امام مسلم نے کہا : حماد بن زید کی حدیث میں ایک حرف زائد ہے جسے ہم نے ذکر نہیں کیا","",{"u2":"ہشام نے عروہ کے (شاگرد وکیع کے بجائے) دوسرے شاگرد وں ابو معاویہ، جریر، نمیر اور حماد بن زید کی سندوں سے بھی جو وکیع کی حدیث کی طرح اسی سندسے مروی ہے، البتہ قتیبہ سے جریر کی روایت کے الفاظ یوں ہیں: فاطمہ بنت ابی حبیش بن عبدالمطلب بن اسد آئیں جو ہمارے خاندان کی ایک خاتون ہیں۔ امام مسلم نے کہا: حماد بن زید کی حدیث میں ایک حرف زائد ہے جسے ہم نے ذکر نہیں کیا"}],[684,"قتیبہ بن سعید اور محمد بن رمح نے لیث سے ، انہوں نے ابن شہاب سے ، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہؓ سے روایت کی ، انہوں نےکہا : ام حبیبہ بنت جحش ؓ نے رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ پوچھا او رکہا : مجھے استحاضہ ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : ’’یہ ایک رگ ( کا خون ) ہے ۔ تم غسل کرو ، پھر ( حیض کے ایام کے خاتمے پر ) نماز پڑھو ۔ ‘‘ تو وہ ہر نماز کے وقت غسل کرتی تھیں ۔ ( امام ) لیث بن سعد نے کہا : ابن شہاب نے یہ نہیں کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ام حبیبہ بنت جحش کو ہر نماز کے لیے غسل کرنے کا حکم دیا تھا ۔ یہ ایسا کام تھا جو وہ خود کرتی تھیں ۔ لیث کے شاگردوں میں سے ابن رمح نے ابنة جحش کے الفاظ استعمال کیے اور ام احبیبہ نہیں کہا ۔","",{"u2":"قتیبہ بن سعید اور محمد بن رمح نے لیث سے، انہوں نے ابن شہاب سے، انہوں نے عروہ سے اورانہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نےکہا: ام حبیبہ بنت جحش رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ پوچھا او رکہا: مجھے استحاضہ ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:’’یہ ایک رگ (کا خون) ہے۔ تم غسل کرو، پھر (حیض کے ایام کے خاتمے پر) نماز پڑھو۔‘‘ تو وہ ہر نماز کےوقت غسل کرتی تھیں۔\n(امام) لیث بن سعد نے کہا: ابن شہاب نے یہ نہیں کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ام حبیبہ بنت جحش کو ہر نماز کے لیے غسل کرنے کا حکم دیا تھا۔ یہ ایسا کام تھا جو وہ خود کرتی تھیں۔\nلیث کے شاگردوں میں سے ابن رمح نے ابنۃ جحش کے الفاظ استعمال کیے اور ام احبیبہ نہیں کہا۔"}],[685,"(لیث کے بجائے ) عمرو بن حارث نے ابن شہاب سے ، انہوں نے عروہ بن زبیر اورعمرہ بنت عبدالرحمن سے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی زوجہ عائشہ ؓ سے روایت کی کہ ام حبیبہ بنت جحش رسول اللہ صلی اللہ علیہ وسلم کی خواہر نسبتی کو ، جو ( ام المومنین زینب بن جحش کی بہن اور ) عبدالرحمن بن عوف رضی اللہ عنہ کی بیوی تھیں ، سات سال تک استحاضہ کا عارضہ لاحق رہا ۔ انہو ں نے ا س کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ دریافت کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’یہ حیض ( کا خون ) نہیں بلکہ یہ ایک رگ ( کا خون ) ہے ، لہٰذا تم غسل کرو اور نماز پڑھو ۔ ‘‘ عائشہ ؓ نے کہا : وہ اپنی بہن زینب بن جحش ؓ کے حجرے میں ایک بڑے تشت ( ٹب ) میں غسل کرتیں تو پانی پر خون کی سرخی غالب آ جاتی ۔ ابن شہاب نے کہا : میں یہ حدیث ابو بکر بن عبدالرحمن بن حارث کو سنائی تو انہوں نے کہا : اللہ تعالیٰ ہند پر رحم فرمائے! کاش وہ بھی یہ فتویٰ سن لیتیں ۔ اللہ کی قسم ! وہ اس بات پر روتی رہتی تھیں کہ استحاضے کی وجہ سے وہ نماز نہیں پڑھ سکتی تھیں ۔","",{"u2":"(لیث کے بجائے) عمرو بن حارث نے ابن شہاب سے، انہوں نے عروہ بن زبیر اورعمرہ بنت عبدالرحمن سے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی زوجہ عائشہ رضی اللہ عنہا سے روایت کی کہ ام حبیبہ بنت جحش رسول اللہ صلی اللہ علیہ وسلم کی خواہر نسبتی کو، جو (ام المومنین زینب بن جحش کی بہن اور)عبدالرحمن بن عوف رضی اللہ عنہ کی بیوی تھیں، سات سال تک استحاضہ کا عارضہ لاحق رہا۔ انہو ں نے ا س کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے فتویٰ دریافت کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’یہ حیض (کا خون) نہیں بلکہ یہ ایک رگ (کا خون) ہے، لہٰذا تم غسل کرو اور نماز پڑھو۔‘‘\nعائشہ رضی اللہ عنہا نے کہا:وہ اپنی بہن زینب بن جحش رضی اللہ عنہا کے حجرے میں ایک بڑے تشت (ٹب) میں غسل کرتیں تو پانی پر خون کی سرخی غالب آ جاتی۔\nابن شہاب نے کہا: میں یہ حدیث ابو بکر بن عبدالرحمن بن حارث کوسنائی تو انہوں نے کہا:اللہ تعالیٰ ہند پر رحم فرمائے! کاش وہ بھی یہ فتویٰ سن لیتیں۔ اللہ کی قسم! وہ اس بات پر روتی رہتی تھیں کہ استحاضے کی وجہ سے وہ نماز نہیں پڑھ سکتی تھیں۔"}],[686,"ابراہیم ، یعنی ابن سعد نے ابن شہاب کے حوالے سے خبر دی ، انہوں نے عمرہ بنت عبد الرحمن سے اور انہوں نے سیدہ عائشہ ؓ سے روایت کی ، انہوں نےفرمایا : ام حبیبہ بنت جحش ؓ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور وہ سات سال تک استحاضے کے عارضے میں مبتلا رہیں ۔ ابراہیم بن سعد کی باقی حدیث’’پانی پر خون کی سرخی غالب آ جاتی تھی ‘‘ تک عمرو بن حارث کی سابقہ روایت کی طرح ہے ، اس کے بعد کا حصہ انہوں نے ذکر نہیں کیا ۔","",{"u2":"ابراہیم،یعنی ابن سعد نے ابن شہاب کے حوالے سے خبر دی، انہوں نے عمرہ بنت عبد الرحمن سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نےفرمایا: ام حبیبہ بنت جحش رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور وہ سات سال تک استحاضے کے عارضے میں مبتلا رہیں۔ ابراہیم بن سعد کی باقی حدیث’’پانی پر خون کی سرخی غالب آ جاتی تھی‘‘ تک عمرو بن حارث کی سابقہ روایت کی طرح ہے، اس کے بعد کا حصہ انہوں نے ذکر نہیں کیا۔"}],[687,"سفیان بن عیینہ نے زہری سے ، انہوں نے عمرہ سے ، انہوں نے سیدہ عائشہ ؓ سےروایت کی کہ بنت جحش سات سال تک استحاضے میں مبتلا رہیں ( آگے باقی ) دوسرے راویوں کی حدیث کی طرح ۔","",{"u2":"سفیان بن عیینہ نے زہری سے، انہوں نے عمرہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سےروایت کی کہ بنت جحش سات سال تک استحاضے میں مبتلا رہیں (آگے باقی) دوسرے راویوں کی حدیث کی طرح۔"}],[688,"یزید بن ابی حبیب نے جعفر سے ، انہوں نے عراک سے ، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ ؓ سےروایت کی ، کہا : ام حبیبہ بنت جحش نے رسول اللہ صلی اللہ علیہ وسلم سے خون کے بارے میں سوال کیا ۔ سیدہ عائشہؓ نے بتایا : میں نے اس کا ٹب خون سے بھرادیکھا تھا ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا : ’’تمہیں پہلے جتنا وقت حیض ( نماز سے ) روکتا تھا اتنا عرصہ رکی رہو ، پھر نہالو اور نماز پڑھو ۔ ‘‘","",{"u2":"یزید بن ابی حبیب نے جعفر سے، انہوں نے عراک سے، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سےروایت کی، کہا: ام حبیبہ بنت جحش نے رسول اللہ صلی اللہ علیہ وسلم سے خون کے بارے میں سوال کیا۔ سیدہ عائشہ رضی اللہ عنہا نے بتایا:میں نے اس کا ٹب خون سے بھرادیکھا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا:’’تمہیں پہلے جتنا وقت حیض (نماز سے) روکتا تھا اتنا عرصہ رکی رہو، پھر نہالو اور نماز پڑھو۔‘‘"}],[689,"اسحاق کے والد بکر بن مضر نے جعفر بن ربیعہ سے باقی ماندہ سابقہ سند سے سیدہ عائشہ ؓ سے روایت کی ، انہوں نے کہا : ام حبیبہ بنت جحش نے ، جو عبد الرحمن بن عوف رضی اللہ عنہ کی بیوی تھیں ، رسول اللہ صلی اللہ علیہ وسلم سے خون ( استحاضہ ) کی شکایت کی تو آپ نے ان سے فرمایا : ’’جتنے دن تمہیں حیض روکتا تھا اتنے دن توقف کرو ، پھر نہالو ۔ ‘‘ تو وہ ہر نماز کے لیے نہایا کرتی تھیں ۔","",{"u2":"اسحاق کے والد بکر بن مضر نے جعفر بن ربیعہ سے باقی ماندہ سابقہ سند سے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: ام حبیبہ بنت جحش نے، جو عبد الرحمن بن عوف رضی اللہ عنہ کی بیوی تھیں، رسول اللہ صلی اللہ علیہ وسلم سے خون (استحاضہ) کی شکایت کی تو آپ نے ان سے فرمایا:’’جتنے دن تمہیں حیض روکتا تھا اتنے دن توقف کرو، پھر نہالو۔‘‘ تو وہ ہر نماز کے لیے نہایا کرتی تھیں۔"}],[690,"نے یزید رشک سے ، انہوں نے معاذہ سے روایت کی کہ ایک عورت نےسیدہ عائشہ ؓ سے پوچھا : کیا ایک عورت ایام حیض کی نمازوں کی قضادے کی ؟ تو عائشہ ؓ نے پوچھا : کیا توحروریہ ( خوارج میں سے ) ہے؟ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں جب ہم میں سے کسی کو حیض آتا تھا تو اسے ( نمازوں کی ) قضا کا حکم نہیں دیا جاتا تھا ۔","",{"u2":"نے یزید رشک سے، انہوں نے معاذہ سے روایت کی کہ ایک عورت نےسیدہ عائشہ رضی اللہ عنہا سے پوچھا: کیا ایک عورت ایام حیض کی نمازوں کی قضادے کی؟ تو عائشہ رضی اللہ عنہا نے پوچھا:کیا توحروریہ (خوارج میں سے) ہے؟ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں جب ہم میں سے کسی کو حیض آتا تھا تو اسے (نمازوں کی) قضا کا حکم نہیں دیا جاتا تھا۔"}],[691,"محمد بن جعفر نے کہا : ہمیں شعبہ نے یزید سے حدیث بیان کی ، انہوں نے کہا : میں نے معاذہ سے سنا کہ انہوں نےسیدہ عائشہ ؓ سے سوال کیا : کیا حائضہ نماز کی قضادے؟ عائشہ ؓ نے کہا : کیا تو حروریہ ( خوارج میں سے ) ہے ؟ رسول اللہ صلی اللہ علیہ وسلم کی ازواج کو حیض آتا تھا تو کیاآپ نے انہیں ( فوت شدہ نمازوں کے ) بدلے میں ادا کرنے کاحکم دیا؟ محمد بن جعفرنے کہا : ان کا مطلب قضا دینے سے تھا ۔ <عربی> </عربی>","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے یزید سے حدیث بیان کی، انہوں نے کہا: میں نے معاذہ سے سنا کہ انہوں نےسیدہ عائشہ رضی اللہ عنہا سے سوال کیا: کیا حائضہ نماز کی قضادے؟ عائشہ رضی اللہ عنہا نے کہا: کیا تو حروریہ (خوارج میں سے) ہے؟ رسول اللہ صلی اللہ علیہ وسلم کی ازواج کو حیض آتا تھا تو کیاآپ نے انہیں (فوت شدہ نمازوں کے) بدلے میں ادا کرنے کاحکم دیا؟ محمد بن جعفرنے کہا: ان کا مطلب قضا دینے سے تھا۔\n<عربی> </عربی>"}],[692,"عاصم نے معاذہ سے روایت کی ، انہوں نے کہا : میں نے عائشہ ؓ سے سوال کیا ، میں نے کہا : حائضہ عورت کا یہ حال کیوں ہے کہ وہ روزوں کی قضا دیتی ہے نماز کی نہیں ؟ انہوں نے فرمایا : کیا تم حروریہ ہو ؟ میں نے عرض کی : میں حروریہ نہیں ، ( صرف ) پوچھنا چاہتی ہوں ۔ انہوں نے فرمایا : ہمیں بھی حیض آتا تھا تو ہمیں روزوں کی قضا دینے کا حکم دیا جاتا تھا ، نماز کی قضا کا حکم نہیں دیا جاتا تھا ۔","",{"u2":"عاصم نے معاذہ سے روایت کی، انہوں نے کہا: میں نے عائشہ رضی اللہ عنہا سے سوال کیا، میں نے کہا: حائضہ عورت کا یہ حال کیوں ہے کہ وہ روزوں کی قضا دیتی ہے نماز کی نہیں؟ انہوں نے فرمایا:کیا تم حروریہ ہو؟ میں نے عرض کی: میں حروریہ نہیں،(صرف) پوچھنا چاہتی ہوں۔ انہوں نے فرمایا: ہمیں بھی حیض آتا تھا تو ہمیں روزوں کی قضا دینے کا حکم دیا جاتا تھا، نماز کی قضا کا حکم نہیں دیا جاتا تھا۔"}],[693,"ابونضر سے روایت ہے کہ سیدہ ام ہانی بنت ابی طالب ؓ کے آزاد کردہ غلام ابو مرہ نے خبر دی کہ انہوں نے ام ہانی ؓ سے سنا ، وہ کہتی تھی کہ میں فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی ، میں نے آپ کو غسل کرتے ہوئے پایا ، آپ کی بیٹی فاطمہ ؓ نے ایک کپڑے کے ذریعے سے آپ ( کے آگے ) پردہ بنایا ہوا تھا ۔","",{"u2":"ابونضر سے روایت ہے کہ سیدہ ام ہانی بنت ابی طالب رضی اللہ عنہا کے آزاد کردہ غلام ابو مرہ نے خبر دی کہ انہوں نے ام ہانی رضی اللہ عنہا سے سنا، وہ کہتی تھی کہ میں فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی، میں نے آپ کو غسل کرتے ہوئے پایا،آپ کی بیٹی فاطمہ رضی اللہ عنہا نے ایک کپڑے کے ذریعے سے آپ (کے آگے) پردہ بنایا ہوا تھا۔"}],[694,"یزید بن ابی حبیب نے سعید بن ابی ہند سے روایت کی کہ عقیل بن ابی طالب کے آزاد کردہ غلام ابو مرہ نے ان سے حدیث بیان کی کہ ام ہانی بنت ابی طالبؓ نے انہیں بتایا کہ جس سال مکہ فتح ہوا وہ ےپ کے پاس حاضر ہوئیں ، آپ مکہ کے بالائی حصے میں تھے ۔ رسول اللہ صلی اللہ علیہ وسلم نہانے کےلیے اٹھے تو فاطمہ ؓ نےآپ کے آگے پردہ تان دیا ، پھر ( غسل کے بعد ) آپ نے اپنا کپڑا لے کر اپنے گرد لپیٹا ، پھر آٹھ رکعتیں چاشت کی نفل پڑھیں ۔","",{"u2":"یزید بن ابی حبیب نے سعید بن ابی ہند سے روایت کی کہ عقیل بن ابی طالب کے آزاد کردہ غلام ابو مرہ نے ان سے حدیث بیان کی کہ ام ہانی بنت ابی طالب رضی اللہ عنہا نے انہیں بتایا کہ جس سال مکہ فتح ہوا وہ ےپ کے پاس حاضر ہوئیں،آپ مکہ کے بالائی حصے میں تھے۔ رسول اللہ صلی اللہ علیہ وسلم نہانے کےلیے اٹھے تو فاطمہ رضی اللہ عنہا نےآپ کے آگے پردہ تان دیا، پھر(غسل کے بعد) آپ نے اپنا کپڑا لے کر اپنے گرد لپیٹا، پھر آٹھ رکعتیں چاشت کی نفل پڑھیں۔"}],[695,"سعید بن ابی ہند کے ایک اور شاگرد ولید بن کثیر نے اسی سند سے حدیث بیان کی اور یہ الفاظ کہے : تو آپ کی بیٹی سیدہ فاطمہ ؓ نے آپ کے کپڑے کے ذریعے سے آپ کے لیے اوٹ بنا دی ۔ آپ جب غسل کے چکے تو وہی کپڑا لیا ، اسے اپنے گرد لپیٹا ، پھر کھڑے ہو کر آٹھ رکعات نماز ادا کی ، یہ چاشت کا وقت تھا ۔","",{"u2":"سعید بن ابی ہند کے ایک اور شاگرد ولید بن کثیر نے اسی سند سےحدیث بیان کی اور یہ الفاظ کہے: تو آپ کی بیٹی سیدہ فاطمہ رضی اللہ عنہا نے آپ کے کپڑے کے ذریعے سے آپ کے لیے اوٹ بنا دی۔ آپ جب غسل کے چکے تو وہی کپڑا لیا، اسے اپنے گرد لپیٹا، پھر کھڑے ہو کر آٹھ رکعات نماز ادا کی، یہ چاشت کا وقت تھا۔"}],[696,"ابن عباس رضی اللہ عنہ نے سیدہ میمونہ ؓ سے روایت کی ، انۂں نے کہا : میں نے نبی اکرم صلی اللہ علیہ وسلم ( کے غسل ) کے لیے پانی رکھا اور آپ کو پردہ مہیاکیا تو آپ نے غسل فرمایا ۔","",{"u2":"ابن عباس رضی اللہ عنہ نے سیدہ میمونہ رضی اللہ عنہا سے روایت کی، انۂں نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم (کے غسل) کے لیے پانی رکھا اور آپ کو پردہ مہیاکیا تو آپ نے غسل فرمایا۔"}],[697,"زید نےحباب نے ضحاک بن عثمان سے روایت کی ، کہا : مجھے زید بن اسلم نے خبر دی ، انہوں نے عبد الرحمن بن ابی سعید خدری رضی اللہ عنہ سے ، انہوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ مرد ، مرد کا ستر نہ دیکھے اور عورت ، عورت کا ستر نہ دیکھے ۔ مرد ، مرد کے ساتھ ایک کپڑے میں نہ ہو اور عورت ، عورت کے ساتھ ایک کپڑے میں نہ ہو ۔ ‘‘","",{"u2":"زید نےحباب نے ضحاک بن عثمان سے روایت کی، کہا: مجھے زید بن اسلم نے خبر دی، انہوں نے عبد الرحمن بن ابی سعید خدری رضی اللہ عنہ سے، انہوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ مرد، مردکا ستر نہ دیکھے اور عورت، عورت کا ستر نہ دیکھے۔ مرد، مرد کے ساتھ ایک کپڑے میں نہ ہو اور عورت، عورت کے ساتھ ایک کپڑے میں نہ ہو۔ ‘‘"}],[698,"مذکورہ روایت کو امام مسلم کو دور اور اساتذہ ہارون بن عبداللہ اور محمد بن رافع دونوں نے ابن ابی فدیک سے اور ابن ابی فدیک نے اسے ضحاک بن عثمان کی مذکورہ سند کے ساتھ بیان کیا ۔ ان دونوں ( ہارون ومحمد ) نے عورۃ کی جگہ عرية الرجل اور عرية المرأة کے الفاظ روایت کیے ۔ ( معنی ایک ہے ۔)","",{"u2":"مذکورہ روایت کو امام مسلم کو دور اور اساتذہ ہارون بن عبداللہ اور محمد بن رافع دونوں نے ابن ابی فدیک سے اور ابن ابی فدیک نے اسے ضحاک بن عثمان کی مذکورہ سند کے ساتھ بیان کیا۔ ان دونوں (ہارون ومحمد) نے عورۃ کی جگہ عریۃ الرجل اور عریۃ المرأۃ کے الفاظ روایت کیے۔ (معنی ایک ہے۔)"}],[699,"ہمام بن منبہ سے روایت ہے : کہا : یہ احادیث ہیں جو سیدنا ابو ہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے ( نقل کرتے ہوئے سنائیں ، انہوں نے متعدد احادیث بیان کیں ان میں سے ایک یہ ہے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’نبی اسرائیل بے لباس ہوکر ، اس طرح نہاتے تھے کہ ایک دوسرے کا ستر دیکھ رہے ہوتے اور موسیٰ علیہ السلام اکیلے نہایا کرتے تھے ۔ بنواسرائیل کہنے لگے : اللہ کی قسم !موسیٰ علیہ السلام ہمارے محض اس لیے نہیں نہاتے کہ ان کے خصیتیں پھولے ہوئے ہیں ۔ ‘‘ آپ نے فرمایا : ’’موسیٰ علیہ السلام ایک دفعہ نہانے کے لیے گئے تو اپنے کپڑے ایک پتھر پر رکھ دیے ، پتھر آپ کے کپڑے لے کر بھاگ کھڑا ہوا ، موسیٰ علیہ السلام اس کے پیچھے یہ کہتے ہوئے سر پٹ دوڑ پڑے : او پتھر !میرے کپڑے ، اوپتھر ! میرے کپڑے ، یہاں تک کہ بنی اسرائیل نے موسیٰ علیہ السلام کے ستر کو دیکھ لیا اور کہنے لگے : اللہ کی قسم ! موسیٰ علیہ السلام کو تو کوئی بیماری نہیں ہے ، جب موسیٰ علیہ السلام کو دیکھ لیا گیا تو پتھر ٹھہر گیا ، موسیٰ علیہ السلام نے اپنے کپڑے پہنے اور پتھر کو مارنے لگے ۔ ‘‘ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : اللہ کی قسم ! پتھر پر چھ یا سات نشان تھے ، یہ پتھر کو موسیٰ علیہ السلام کی مار تھی ۔)","",{"u2":"ہمام بن منبہ سے روایت ہے:کہا: یہ احادیث ہیں جو سیدنا ابو ہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے (نقل کرتے ہوئے سنائیں، انہوں نےمتعدد احادیث بیان کیں ان میں سے ایک یہ ہے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نبی اسرائیل بے لباس ہوکر، اس طرح نہاتے تھے کہ ایک دوسرے کا ستر دیکھ رہے ہوتے اورموسیٰ علیہ السلام اکیلے نہایا کرتے تھے۔ بنواسرائیل کہنے لگے: اللہ کی قسم!موسیٰ علیہ السلام ہمارے محض اس لیے نہیں نہاتے کہ ان کے خصیتیں پھولے ہوئےہیں۔‘‘\nآپ نے فرمایا:’’موسیٰ علیہ السلام ایک دفعہ نہانے کے لیے گئے تو اپنے کپڑے ایک پتھر پر رکھ دیے، پتھر آپ کے کپڑے لے کر بھاگ کھڑا ہوا، موسیٰ علیہ السلام اس کے پیچھے یہ کہتے ہوئے سر پٹ دوڑ پڑے: او پتھر!میرے کپڑے، اوپتھر! میرے کپڑے، یہاں تک کہ بنی اسرائیل نے موسیٰ علیہ السلام کے ستر کو دیکھ لیا اورکہنے لگے: اللہ کی قسم! موسیٰ علیہ السلام کو تو کوئی بیماری نہیں ہے، جب موسیٰ علیہ السلام کو دیکھ لیا گیا تو پتھر ٹھہر گیا، موسیٰ علیہ السلام نے اپنے کپڑے پہنے اور پتھر کو مارنے لگے۔‘‘\nسیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: اللہ کی قسم! پتھر پر چھ یا سات نشان تھے، یہ پتھر کو موسیٰ علیہ السلام کی مار تھی۔"}],[700,"اسحاق بن ابراہیم حنظلی اور محمد بن حاتم نے محمد بن بکر سے روایت کی ، دونوں نےکہا : ہمیں ابن جریج نے خبر دی ، نیز اسحاق بن منصور اور محمد بن رافع نے ( اور یہ الفاظ ان دونوں کے ہیں ) عبد الرزاق کے حوالے سے ابن جریج سے حدیث بیان کی ، انہوں ( ابن جریج ) نے کہا : مجھے عمرو بن دینار نے خبر دی کہ انہوں نے سیدنا جابر رضی اللہ عنہ سے سنا ، کہہ رہے تھے : جب کعبہ تعمیر کیا گیا توعبا رضی اللہ عنہ اور نبی صلی اللہ علیہ وسلم پتھر ڈھونے لگے ، سیدنا عباس رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے کہا : پتھروں سے حفاظت کے لیے اپنا تہبند اٹھا کر کندھے پر رکھ لیجیے ۔ آپ نے ایسا کیا تو آپ زمین پر گر گئے اور آنکھیں ( اوپر ہو کر ) آسمان پر ٹک گئیں ، پھر آپ اٹھے اور کہا : ’’میرا تہبند ، میرا تہبند ۔ ‘‘ تو آپ کا تہبند آپ کو کس کر باندھ دیا گیا ۔ ابن رافع کی روایت میں على رقبتك ( اپنی گردن پر ) کے الفاظ ہیں ، انہوں علی عاتقک ( اپنے کندھے پر ) نہیں کہا ۔","",{"u2":"اسحاق بن ابراہیم حنظلی اور محمد بن حاتم نے محمد بن بکر سے روایت کی، دونوں نےکہا: ہمیں ابن جریج نےخبر دی،نیز اسحاق بن منصور اور محمد بن رافع نے (اور یہ الفاظ ان دونوں کے ہیں) عبد الرزاق کے حوالے سے ابن جریج سے حدیث بیان کی، انہوں (ابن جریج) نے کہا: مجھے عمرو بن دینار نے خبر دی کہ انہوں نے سیدنا جابر رضی اللہ عنہ سے سنا، کہہ رہے تھے: جب کعبہ تعمیر کیا گیا توعبا رضی اللہ عنہ اور نبی صلی اللہ علیہ وسلم پتھر ڈھونے لگے، سیدنا عباس رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے کہا: پتھروں سے حفاظت کے لیے اپنا تہبند اٹھا کر کندھے پر رکھ لیجیے۔ آپ نے ایسا کیا تو آپ زمین پر گر گئے اورآنکھیں (اوپر ہو کر) آسمان پر ٹک گئیں، پھر آپ اٹھے اور کہا:’’میرا تہبند، میرا تہبند۔‘‘ تو آپ کا تہبند آپ کو کس کر باندھ دیا گیا۔\nابن رافع کی روایت میں علی رقبتک(اپنی گردن پر) کے الفاظ ہیں، انہوں علی عاتقک(اپنے کندھے پر) نہیں کہا۔"}],[701,"زکریا بن اسحاق نے حدیث بیان کی ، ( کہا : ) ہم سے عمرو بن دینار نے حدیث بیان کی ، کہا : میں نے سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے سنا ، حدیث بیان کر رہ تھے کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے ساتھ کعبے کے لیے پتھر ڈھو رہے تھے اور آپ کا تہبند جسم پر تھا ، اس موقع پر آپ کے چچا عباس رضی اللہ عنہ نے آپ سے کہا : اے بھتیجے ! بہتر ہو گا کہ تم اپنا تہبند کھول دور اور اسے اپنے مونڈھے پر پتھروں کے نیچے رکھ لو ۔ جابر نےکہا : آپ نے اسے کھول کر اپنے مونڈھے پر رکھ لیا تو آپ کو غش کھا کر گر گئے ۔ جابر رضی اللہ عنہ نے کہا : اس دن کے بعد آپ کو کبھی برہنہ نہیں دیکھا گیا ۔","",{"u2":"زکریا بن اسحاق نے حدیث بیان کی، (کہا:)ہم سے عمرو بن دینار نے حدیث بیان کی، کہا: میں نے سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے سنا، حدیث بیان کر رہ تھے کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے ساتھ کعبے کے لیے پتھر ڈھو رہے تھے اور آپ کا تہبند جسم پر تھا، اس موقع پر آپ کے چچا عباس رضی اللہ عنہ نے آپ سے کہا: اے بھتیجے! بہتر ہو گا کہ تم اپنا تہبند کھول دور اور اسے اپنے مونڈھے پر پتھروں کے نیچے رکھ لو۔ جابر نےکہا: آپ نے اسے کھول کر اپنے مونڈھے پر رکھ لیا تو آپ کو غش کھا کر گر گئے۔ جابر رضی اللہ عنہ نے کہا: اس دن کے بعد آپ کو کبھی برہنہ نہیں دیکھا گیا۔"}],[702,"سیدنا مسور بن مخرمہ رضی اللہ عنہ سے روایت ہے ، کہا : میں ایک بھاری پتھر اٹھانے ہوئے آیا اور میں نے ایک ہلکا سے تہبند باندھا ہوا تھا ، کہا : تو میرا تہبند کھل گیا اور پتھر میرے پاس تھا ۔ میں اس ( پتھر ) کے نیچے نہ رکھ سکا حتی کہ اسے اس کی جگہ پہنچا دیا ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’واپس جا کر اپنا کپڑا پہنو اور ننگے نہ چلا کرو ۔ ‘‘","",{"u2":"سیدنا مسور بن مخرمہ رضی اللہ عنہ سے روایت ہے، کہا: میں ایک بھاری پتھر اٹھانے ہوئے آیا اور میں نے ایک ہلکا سے تہبند باندھا ہوا تھا، کہا: تو میرا تہبند کھل گیا اور پتھر میرے پاس تھا۔ میں اس (پتھر) کے نیچے نہ رکھ سکا حتی کہ اسے اس کی جگہ پہنچا دیا۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’واپس جا کر اپنا کپڑا پہنو اور ننگے نہ چلا کرو۔‘‘"}],[703,"شیبان بن فروخ اور عبداللہ بن محمد بن اسماء ضبعی نے کہا : ہمیں مہدی بن میمون نے حدیث سنائی ، کہا : ہمیں محمد بن عبداللہ بن ابی یعقوب نے حسن بن علی کے آزاد کر دہ غلام حسن بن سعد کے حوالےسے سیدنا عبد اللہ بن جعفر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نےکہا : ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اپنے پیچھے سوار کر لیا ، پھر مجھے ایک راز کی بات بتائی جو میں کسی شخص کو نہیں بتاؤں گا ، قضائے حاجت کے لیے آپ کی محبوب ترین اوٹ ٹیلایا کھجور کا جھنڈ تھا ۔ ( حدیث کے ایک راوی محمد ) ابن اسماء نے اپنی حدیث میں کہا : حائش نخل سے مراد حائط نخل ’’کھجور کا باغ یا جھنڈ ‘‘ ہے ۔","",{"u2":"شیبان بن فروخ اور عبداللہ بن محمد بن اسماء ضبعی نے کہا: ہمیں مہدی بن میمون نے حدیث سنائی، کہا: ہمیں محمد بن عبداللہ بن ابی یعقوب نے حسن بن علی کے آزاد کر دہ غلام حسن بن سعد کے حوالےسے سیدنا عبد اللہ بن جعفر رضی اللہ عنہ سے حدیث بیان کی، انہوں نےکہا: ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اپنے پیچھے سوار کر لیا، پھر مجھے ایک راز کی بات بتائی جو میں کسی شخص کو نہیں بتاؤں گا، قضائے حاجت کے لیے آپ کی محبوب ترین اوٹ ٹیلایا کھجور کا جھنڈ تھا۔\n(حدیث کے ایک راوی محمد) ابن اسماء نے اپنی حدیث میں کہا: حائش نخل سے مراد حائط نخل ’’کھجور کا باغ یا جھنڈ ‘‘ ہے۔"}],[704,"عبد الرحمن بن ابی سعید خدری نے اپنے والد سے روایت کی ، انہوں نےکہا کہ میں سوموار کے دن رسول اللہ صلی اللہ علیہ وسلم کےساتھ قباء گیا ، جب ہم بنو سالم کے محلے میں پہنچے تو رسول اللہ صلی اللہ علیہ وسلم عتبان رضی اللہ عنہ کے دروازے پر رک گئے اور اسے آواز دی تو وہ اپنا تہبند گھسیٹتےہوئے نکلے ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ہم نے اس آدمی کو جلدی میں ڈال دیا ۔ ‘‘ عتبان رضی اللہ عنہ نے کہا : اے اللہ کے رسول ! آپ کی اس مرد کے بارے میں کیا رائے ہے جو بیوی سے جلدی ہٹا دیا جائے ، حالانکہ اس نے منی خارج نہ کی تو اسے کیا کرنا چاہیے ؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’پانی ، صرف پانی سے ہے ۔ ‘‘","",{"u2":"عبد الرحمن بن ابی سعید خدری نے اپنے والد سے روایت کی، انہوں نےکہا کہ میں سوموار کے دن رسول اللہ صلی اللہ علیہ وسلم کےساتھ قباء گیا، جب ہم بنو سالم کے محلے میں پہنچے تو رسول اللہ صلی اللہ علیہ وسلم عتبان رضی اللہ عنہ کے دروازے پر رک گئے اور اسے آواز دی تو وہ اپنا تہبند گھسیٹتےہوئے نکلے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ہم نے اس آدمی کو جلدی میں ڈال دیا۔‘‘ عتبان رضی اللہ عنہ نے کہا: اے اللہ کے رسول! آپ کی اس مرد کے بارے میں کیا رائے ہے جو بیوی سے جلدی ہٹا دیا جائے، حالانکہ اس نے منی خارج نہ کی تو اسے کیا کرنا چاہیے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’پانی، صرف پانی سے ہے۔ ‘‘"}],[705,"ابو علاء بن شخیر رضی اللہ عنہ سے روایت ہے ، کہا کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک حدیث دوسری کو منسوخ کر دیتی ہے ، جیسے قرآن کی ایک آیت دوسری آیت کو منسوخ کر دیتی ہے ۔ ( یعنی اس مفہوم کی احادیث ، آپ ہی کے اس فرمان کے ذریعے سے منسوخ ہو چکی ہیں جو بعد میں آئے گا ۔)","",{"u2":"ابو علاء بن شخیر رحمہ اللہ سے روایت ہے،کہا کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک حدیث دوسری کو منسوخ کر دیتی ہے، جیسے قرآن کی ایک آیت دوسری آیت کو منسوخ کر دیتی ہے۔ (یعنی اس مفہوم کی احادیث، آپ ہی کے اس فرمان کے ذریعے سے منسوخ ہو چکی ہیں جو بعد میں آئے گا۔)"}],[706,"ابوبکر بن ابی شیبہ ، محمد بن مثنی اور ابن بشار نے محمد بن جعفر غندر سے ، انہوں نے شعبہ سے ، انہوں نے حکم کے حوالے سے ذکوان سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سےروایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک انصاری آدمی کے ( مکان کے ) پاس سے گزرے تو سے بلوایا ، وہ اس حال میں نکلا کہ اس کے سر سے پانی ٹپک رہا تھا تو آپ نے فرمایا : ’’ شاید ہم نے تمہیں جلدی میں ڈالا ۔ ‘‘ اس نے کہا : جی ہاں ، اے اللہ کے رسول ! آپ نے فرمایا : ’’ جب تمہیں جلدی میں ڈال دیا جائے یا تم انزال نہ کر سکو تو تم پر غسل لازم نہیں ہے ، البتہ وضو ضروری ہے ۔ ‘‘ ابن بشار نے کہا : جب تمہیں جلدی میں ڈال دیا جائے یا تجھے ( انزال سے ) روک دیا جائے ۔","",{"u2":"ابوبکر بن ابی شیبہ، محمد بن مثنی اور ابن بشار نےمحمد بن جعفر غندر سے، انہوں نے شعبہ سے، انہوں نے حکم کے حوالے سے ذکوان سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سےروایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک انصاری آدمی کے (مکان کے) پاس سے گزرے تو سے بلوایا، وہ اس حال میں نکلا کہ اس کے سر سے پانی ٹپک رہا تھا تو آپ نے فرمایا:’’ شاید ہم نے تمہیں جلدی میں ڈالا۔ ‘‘ اس نے کہا: جی ہاں، اے اللہ کے رسول! آپ نے فرمایا: ’’ جب تمہیں جلدی میں ڈال دیا جائے یا تم انزال نہ کر سکو تو تم پر غسل لازم نہیں ہے، البتہ وضو ضروری ہے۔‘‘\nابن بشار نے کہا: جب تمہیں جلدی میں ڈال دیا جائے یا تجھے (انزال سے) روک دیا جائے۔"}],[707,"حماد اور ابو معاویہ نے ہشام بن عروہ سے ، انہوں نے اپنےوالد سے ، انہوں نے ابو ایوب سے ، انہوں نے سیدنا ابی بن کعب رضی اللہ عنہ سے روایت کی ، کہا : میں رسول اللہ صلی اللہ علیہ وسلم سے اس مرد کے بارے میں پوچھا جو اپنی بیوی کے پاس جاتا ہے ، پھر اسے انزال نہیں ہوتا ۔ تو آپ نے فرمایا : ’’ بیوی سے اسے جو کچھ لگ جائے اس کو دھو ڈالے ، پھر وضو کر کے نماز پڑھ لے ۔ ‘‘","",{"u2":"حماد اور ابو معاویہ نےہشام بن عروہ سے، انہوں نے اپنےوالد سے، انہوں نے ابو ایوب سے، انہوں نے سیدنا ابی بن کعب رضی اللہ عنہ سے روایت کی، کہا: میں رسول اللہ صلی اللہ علیہ وسلم سے اس مرد کے بارے میں پوچھا جو اپنی بیوی کے پاس جاتا ہے،پھر اسے انزال نہیں ہوتا۔ تو آپ نے فرمایا:’’ بیوی سے اسے جو کچھ لگ جائے اس کو دھو ڈالے،پھر وضو کر کے نماز پڑھ لے۔‘‘"}],[708,"شعبہ نے ہشام بن عروہ سے باقی ماندہ سابقہ سند کےساتھ سیدنا ابی بن کعب رضی اللہ عنہ سےروایت کی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے اس مرد کے بارے میں جو اپنی بیوی کے پاس جاتا ہے پھر اسے انزال نہیں ہوتا ، فرمایا : ’’ وہ اپنے عضو کو دھو لے اور وضو کرے ۔ ‘‘","",{"u2":"شعبہ نے ہشام بن عروہ سے باقی ماندہ سابقہ سند کےساتھ سیدنا ابی بن کعب رضی اللہ عنہ سےروایت کی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے اس مرد کے بارے میں جواپنی بیوی کے پاس جاتا ہے پھر اسے انزال نہیں ہوتا، فرمایا:’’ وہ اپنے عضو کو دھو لے اور وضو کرے۔‘‘"}],[710,"ابو سلمہ نے عطاء بن یسار سے خبر دی کہ انہیں سیدنا زید بن خالد جہنی رضی اللہ عنہ نے بیان کیا کہ انہوں نے سیدنا عثمان بن عفان رضی اللہ عنہ سے پوچھا : آپ کی کیا رائے ہے ، جب کسی مرد نے اپنی بیوی سے مجامعت کی اور اس نے منی خارج نہ کی ؟ سیدنا عثمان رضی اللہ عنہ نے ( جواب میں ) کہا : نماز کے وضو کی طرح وضو کرے اور اپنےعضو کو دھولے ۔ سیدنا عثمان رضی اللہ عنہ نے کہا : میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی ۔","",{"u2":"ابو سلمہ نے عطاء بن یسار سے خبر دی کہ انہیں سیدنا زید بن خالد جہنی رضی اللہ عنہ نےبیان کیا کہ انہوں نے سیدنا عثمان بن عفان رضی اللہ عنہ سےپوچھا: آپ کی کیا رائے ہے، جب کسی مرد نے اپنی بیوی سے مجامعت کی اور اس نے منی خارج نہ کی؟ سیدنا عثمان رضی اللہ عنہ نے (جواب میں) کہا: نماز کے وضو کی طرح وضو کرے اور اپنےعضو کو دھولے۔ سیدنا عثمان رضی اللہ عنہ نے کہا: میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی۔"}],[711,"ابوسلمہ نے عطاء بن یسار کےبجائے عروہ بن زبیر سے اور انہوں نے ابو ایوب رضی اللہ عنہ سے خبر دی کہ انہوں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی تھی ۔","",{"u2":"ابوسلمہ نے عطاء بن یسار کےبجائے عروہ بن زبیر سے اور انہوں نےابو ایوب رضی اللہ عنہ سے خبر دی کہ انہوں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی تھی۔"}],[712,"زہیر بن حرب ، ابو غسان مسمعی ، محمد بن مثنیٰ اور ابن بشار نے کہا : ہم سے معاذ بن ہشام نے حدیث بیان کی ، انہوں نے اپنے والد سے ، انہوں نے قتادہ اور مطر نے حسن سے ، انہوں نے ابو رافع سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا : ’’ جب وہ ( مرد ) اس ( عورت ) کی چا شاخوں کے درمیان بیٹھے ، پھر اس سے مجامعت کرے تو اس پر غسل واجب ہو جاتا ہے ۔ ‘‘ مطر کی حدیث میں یہ اضافہ ہے : ’’اگرچہ انزال نہ ہو ۔ ‘‘ اور امام مسلم کے اساتذہ میں سے ( صرف ) زہیر نے شعبہا کی جگہ أشعبها کہا ۔ ( دونوں ایک ہی لفظ شعبہ ( شاخ ) کی جمع ہیں ۔","",{"u2":"زہیر بن حرب، ابو غسان مسمعی، محمد بن مثنیٰ اور ابن بشار نے کہا: ہم سے معاذ بن ہشام نے حدیث بیان کی، انہوں نے اپنے والد سے، انہوں نے قتادہ اور مطر نے حسن سے، انہوں نے ابو رافع سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ جب وہ (مرد) اس (عورت) کی چا شاخوں کے درمیان بیٹھے، پھر اس سے مجامعت کرے تو اس پر غسل واجب ہو جاتا ہے۔‘‘\nمطر کی حدیث میں یہ اضافہ ہے: ’’اگرچہ انزال نہ ہو۔‘‘ اور امام مسلم کے اساتذہ میں سے (صرف) زہیر نے شعبہا کی جگہ أشعبہا کہا۔ (دونوں ایک ہی لفظ شعبہ (شاخ) کی جمع ہیں۔)"}],[713,"شعبہ نے قتادہ سے باقی ماندہ اسی سند سے روایت کی ۔ فرق یہ ہے کہ شعبہ کی اس روایت میں ثم جهدها کی جگہ ثم اجتهد ( پھر سعی کی ) ہےت اور و إن لم ينزل ( اگرچہ انزال نہ ہو ) کے الفاظ نہیں ہیں ۔","",{"u2":"شعبہ نے قتادہ سے باقی ماندہ اسی سند سے روایت کی۔ فرق یہ ہے کہ شعبہ کی اس روایت میں ثم جہدہا کی جگہ ثم اجتہد (پھر سعی کی) ہےت اور و إن لم ینزل (اگرچہ انزال نہ ہو) کے الفاظ نہیں ہیں۔"}],[714,"دو مختلف سندوں کے ساتھ ابو بردہ کے حوالے سے ( ان کے والد ) سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ اس مسئلے میں مہاجرین اور انصار کے ایک گروہ نے اختلاف کیا ۔ انصار نے کہا : غسل صرف ( منی کے ) زور سے نکلنے یا پانی ( کے انزال ) سے فرض ہوتا ہے او رمہاجرین نے کہا : بلکہ جب اختلاط ہو تو غسل واجب ہو جاتا ہے ۔ ( ابو بردہ نے ) کہا : سیدنا ابو موسیٰ رضی اللہ عنہ نے کہا : میں تمہیں اس مسئلے سے چھٹکارا دلاتا ہوں ، میں اٹھا اور سیدہ عائشہؓ کی خدمت میں حاضری کی اجازت طلب کی ، مجھے اجازت دے دی گئی تو میں نے کہا : میری ماں ، یا کہا : ام المؤمنین! میں آپ سے ایک چیز کے بارے میں پوچھنا چاہتا ھوں او رمجھے آپ سے شرم ( بھی ) آر ہی ہے ۔ تو انہوں نے کہا : جو بات تم اپنی اس ماں سے جس نے ( اپنے پیٹ سے ) تمہیں جنم دیا ، پوچھ سکتے تھے ، وہ مجھ سے پوچھناے میں شرم نہ کرو کیونکہ میں بھی تمہاری ماں ہوں ۔ میں نے کہا : تو کون سا ( کام ) غسل کو واجب کرتا ہے؟ انہوں نے کہا : تم ( اس مسئلے کے متعلق ) اس سے ملے ہو جو ( اس سے ) اچھی طرح باخبر ہے ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب وہ ( مرد ) اس ( عورت ) کی چا رشاخوں کے درمیان بیٹھا اور ختنے کی جگہ ختنے کی جگہ سے مَس ہوئی تمو غسل واجب ہو گیا ۔ ‘‘"],[715,"دو مختلف سندوں کے ساتھ ابو بردہ کے حوالے سے ( ان کے والد ) سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ اس مسئلے میں مہاجرین اور انصار کے ایک گروہ نے اختلاف کیا ۔ انصار نے کہا : غسل صرف ( منی کے ) زور سے نکلنے یا پانی ( کے انزال ) سے فرض ہوتا ہے او رمہاجرین نے کہا : بلکہ جب اختلاط ہو تو غسل واجب ہو جاتا ہے ۔ ( ابو بردہ نے ) کہا : سیدنا ابو موسیٰ رضی اللہ عنہ نے کہا : میں تمہیں اس مسئلے سے چھٹکارا دلاتا ہوں ، میں اٹھا اور سیدہ عائشہؓ کی خدمت میں حاضری کی اجازت طلب کی ، مجھے اجازت دے دی گئی تو میں نے کہا : میری ماں ، یا کہا : ام المؤمنین! میں آپ سے ایک چیز کے بارے میں پوچھنا چاہتا ھوں او رمجھے آپ سے شرم ( بھی ) آر ہی ہے ۔ تو انہوں نے کہا : جو بات تم اپنی اس ماں سے جس نے ( اپنے پیٹ سے ) تمہیں جنم دیا ، پوچھ سکتے تھے ، وہ مجھ سے پوچھناے میں شرم نہ کرو کیونکہ میں بھی تمہاری ماں ہوں ۔ میں نے کہا : تو کون سا ( کام ) غسل کو واجب کرتا ہے؟ انہوں نے کہا : تم ( اس مسئلے کے متعلق ) اس سے ملے ہو جو ( اس سے ) اچھی طرح باخبر ہے ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب وہ ( مرد ) اس ( عورت ) کی چا رشاخوں کے درمیان بیٹھا اور ختنے کی جگہ ختنے کی جگہ سے مَس ہوئی تمو غسل واجب ہو گیا ۔ ‘‘","",{"u2":"دو مختلف سندوں کے ساتھ ابو بردہ کے حوالے سے (ان کے والد) سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ اس مسئلے میں مہاجرین اور انصار کے ایک گروہ نے اختلاف کیا۔ انصار نے کہا: غسل صرف (منی کے) زور سے نکلنے یا پانی (کے انزال) سے فرض ہوتا ہے او رمہاجرین نے کہا: بلکہ جب اختلاط ہو تو غسل واجب ہو جاتا ہے۔ (ابو بردہ نے) کہا: حضرت ابو موسیٰ علیہ السلام نے کہا: میں تمہیں اس مسئلے سے چھٹکارا دلاتا ہوں، میں اٹھا اور سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضری کی اجازت طلب کی، مجھے اجازت دے دی گئی تو میں نے کہا: میری ماں، یا کہا: ام المؤمنین! میں آپ سے ایک چیز کے بارے میں پوچھنا چاہتا ھوں او رمجھے آپ سے شرم (بھی) آر ہی ہے۔ تو انہوں نے کہا: جو بات تم اپنی اس ماں سے جس نے (اپنے پیٹ سے) تمہیں جنم دیا، پوچھ سکتے تھے، وہ مجھ سے پوچھناے میں شرم نہ کرو کیونکہ میں بھی تمہاری ماں ہوں۔ میں نے کہا: تو کون سا (کام) غسل کو واجب کرتا ہے؟ انہوں نے کہا: تم (اس مسئلے کے متعلق) اس سے ملے ہو جو (اس سے) اچھی طرح باخبر ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب وہ (مرد) اس (عورت) کی چا رشاخوں کے درمیان بیٹھا اور ختنے کی جگہ ختنے کی جگہ سے مَس ہوئی تمو غسل واجب ہو گیا۔‘‘"}],[716,"ام کلثوم نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہؓ سے روایت کی ، انہوں نے کہا کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم سے ایسے مرد کے بارے میں پوچھا جو اپنی اپنی بیوی سے صحبت کرتا ہے ، پھر انزال نہیں ہوتا ، کیا ان ( دونوں ) پر غسل ہے؟ اور ( اندر ) سیدہ عائشہؓ بھی بیٹھی ہوئی تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’میں اور یہ ( ہم دونوں میاں بیوی ) یہ کرتے ہیں ، پھر ہم ( دونوں ) نہاتے ہیں ۔ ‘‘","",{"u2":"ام کلثوم نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم سے ایسے مرد کے بارے میں پوچھا جو اپنی اپنی بیوی سے صحبت کرتا ہے، پھر انزال نہیں ہوتا، کیا ان (دونوں) پر غسل ہے؟ اور (اندر) سیدہ عائشہ رضی اللہ عنہا بھی بیٹھی ہوئی تھیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اور یہ (ہم دونوں میاں بیوی) یہ کرتے ہیں، پھر ہم (دونوں) نہاتے ہیں۔‘‘"}],[717,"سیدنا زید بن ثابت رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ایسی چیز ( کے کھانے ) س وضو ( لازم ہو جاتا ) ہے جسے آگ نے چھوا ہو ۔ ‘‘","",{"u2":"سیدنا زید بن ثابت رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ایسی چیز (کے کھانے) س وضو (لازم ہو جاتا) ہے جسے آگ نے چھوا ہو۔‘‘"}],[718,"۔ عبد اللہ بن ابراہیم بن قارظ نے بتایا کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو مسجد میں وضو کرتے ہوئے پایا تو ابو ہریرہ رضی اللہ عنہ نے کہا : میں تو پنیر کے ٹکڑوں کی بنا پر وضو کر رہا ہوں جنہیں میں نے کھایا ہے کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا ، آپ فرما رہے تھے : ایسی چیز سے وضو کرو جسے آگ نے چھوا ہو ۔ ‘‘"],[719,"۔ ابن شہاب نے کہا : مجھے سعید بن خالد بن عمرو بن عثمان نے ، جب میں اسے ( سابقہ سند سے ) یہ حدیث سنا رہا تھا ، بتایا کہ اس نے عروہ بن زبیر رضی اللہ عنہ سے ایسی چیز ( کھانے ) سے وضو کے بارے میں پوچھا جسے آگ نے چھوا ہے ، تو عروہ رضی اللہ عنہ نے کہا : میں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہؓ سے سنا ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ایسی چیز سے وضو کرو جسے آگ نے چھوا ہو","",{"u2":"۔ عبد اللہ بن ابراہیم بن قارظ نے بتایا کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو مسجد میں وضو کرتے ہوئے پایا تو ابو ہریرہ رضی اللہ عنہ نے کہا: میں تو پنیر کے ٹکڑوں کی بنا پر وضو کر رہا ہوں جنہیں میں نے کھایا ہے کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ فرما رہے تھے: ایسی چیز سے وضو کرو جسے آگ نے چھوا ہو۔‘‘\n۔ ابن شہاب نے کہا: مجھے سعید بن خالد بن عمرو بن عثمان نے، جب میں اسے (سابقہ سند سے) یہ حدیث سنا رہا تھا، بتایا کہ اس نے عروہ بن زبیر رحمہ اللہ سے ایسی چیز (کھانے) سے وضو کے بارے میں پوچھا جسے آگ نے چھوا ہے، تو عروہ رحمہ اللہ نے کہا: میں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے سنا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایسی چیز سے وضو کرو جسے آگ نے چھوا ہو"}],[720,"عطاء بن یسار نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے بکری کا شانہ تناول فرمایا ، پھر نماز پڑھی اور وضو نہیں کیا ۔","",{"u2":"عطاء بن یسار نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے بکری کا شانہ تناول فرمایا، پھر نماز پڑھی اور وضو نہیں کیا۔"}],[721,"۔ محمد بن عمرو بن عطاء اور علی بن عبد اللہ بن عباس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے گوشت والی ہڈی یا کچھ گوشت کھایا ، پھر نماز پڑھی اور وضو نہیں کیا یا پانی کو نہیں چھوا"],[722,"۔ محمد بن عمرو بن عطاء اور علی بن عبد اللہ بن عباس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے گوشت والی ہڈی یا کچھ گوشت کھایا ، پھر نماز پڑھی اور وضو نہیں کیا یا پانی کو نہیں چھوا"],[723,"۔ محمد بن عمرو بن عطاء اور علی بن عبد اللہ بن عباس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے گوشت والی ہڈی یا کچھ گوشت کھایا ، پھر نماز پڑھی اور وضو نہیں کیا یا پانی کو نہیں چھوا",""],[724,"ابراہیم بن سعد نے کہا : ہمیں زہری نے جعفر بن عمرو بن امیہ ضمیری سے حدیث بیان کی ، انہوں نے اپنے والد سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک شانے سے ( گوشت ) کاٹ کر کھاتے ہوئے دیکھا ، پھر آپ نے نماز پڑھی اور وضو نہیں کیا ۔","",{"u2":"ابراہیم بن سعد نے کہا: ہمیں زہری نے جعفر بن عمرو بن امیہ ضمیری سے حدیث بیان کی، انہوں نے اپنے والد سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک شانے سے (گوشت) کاٹ کر کھاتے ہوئے دیکھا، پھر آپ نے نماز پڑھی اور وضو نہیں کیا۔"}],[725,"ابن شہاب زہری کے دوسر شاگرد عمرو بن حارث نے باقی ماندہ سابقہ سند کے ساتھ عمرو بن امیہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو بکری کے ایک شانے سے ( گوشت ) کاٹتے ہوئے دیکھا ، پھر آپ نے اس میں سے کھایا ، پھر آپ کو نماز کی طرف بلایا گیا تو آپ کھڑے ہوئے اور چھری پھینک دی ، آپ نے نماز پڑھی اور وضو نہیں کیا ۔",""],[726,"بکیر بن اشج نے ابن عباس رضی اللہ عنہ کے مولیٰ کریب سے ، انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہؓ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ان کے ہاں شانے کا گوشت کھایا ، پھر نماز پڑھی اور وضو نہ کیا ۔","",{"u2":"یعقوب بن اشج نے ابن عباس رضی اللہ عنہ کے آزاد کردہ غلام کریب سے، انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا سے یہی حدیث بیان کی ہے۔"}],[727,"سیدنا ابو رافع رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ میں گواہی دیتا ہوں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے لیے بکری کے پیٹ ( کا گوشت ، جگر ، گردے وغیرہ ) بھونتا تھا ( آپ اسے کھاتے ) ، اس کے بعد آپ صلی اللہ علیہ وسلم نماز پڑھتے اور وضو نہ کرتے تھے ۔","",{"u2":"بکیر بن اشج نے ابن عباس رضی اللہ عنہ کے مولیٰ کریب سے، انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ان کے ہاں شانے کا گوشت کھایا، پھر نماز پڑھی اور وضو نہ کیا۔\nسیدنا ابو رافع رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ میں گواہی دیتا ہوں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے لیے بکری کے پیٹ (کا گوشت، جگر، گردے وغیرہ) بھونتا تھا (آپ اسے کھاتے)، اس کے بعد آپ صلی اللہ علیہ وسلم نماز پڑھتے اور وضو نہ کرتے تھے۔"}],[728,"۔ عقیل نے زہری سے ، انہوں نے عبید اللہ بن عبد اللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے دودھ نوش فرمایا : پھر پانی طلب کیا ، کلی کی اور فرمایا : یقیناً اس میں کچھ چکناہٹ ہے ۔ ‘‘","",{"u2":"۔ عقیل نے زہری سے، انہوں نے عبید اللہ بن عبد اللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے دودھ نوش فرمایا: پھر پانی طلب کیا، کلی کی اور فرمایا: یقیناً اس میں کچھ چکناہٹ ہے۔‘‘"}],[729,"عمرو ، اوزاعی اور یونس سب نے عقیل والی سندکے ساتھ زہری سے اسی طرح روایت بیان کی ۔","",{"u2":"عمرو، اوزاعی اور یونس سب نے عقیل والی سندکے ساتھ زہری سے اسی طرح روایت بیان کی۔"}],[730,"محمد بن عمرو بن حلحلہ نے محمد بن عمرو بن عطاء سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے کپڑے زیب تن فرمائے ، پھر نماز کے لیے نکلے تو آپ کو روٹی اور گوشت کا تحفہ پیش کیا گیا ، آپ نے تین لقمے تناول فرمائے ، پھر لوگوں کو نماز پڑھائی اور پانی کو نہیں چھوا ۔","",{"u2":"محمد بن عمرو بن حلحلہ نے محمد بن عمرو بن عطاء سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے کپڑے زیب تن فرمائے، پھر نماز کے لیے نکلے تو آپ کو روٹی اور گوشت کا تحفہ پیش کیا گیا، آپ نے تین لقمے تناول فرمائے، پھر لوگوں کو نماز پڑھائی اور پانی کو نہیں چھوا۔"}],[731,"امام مسلم نے ایک دوسری سند سے ولید بن کثیر کے واسطے سے محمد بن عمرو بن عطاء سے روایت کی ، کہا : میں ابن عباس رضی اللہ عنہ کے ساتھ تھا .... اس کے بعد انہوں نے ابن حلحلہ کی روایت کے ہم معنیٰ حدیث بیان کی ہے اور اس میں یہ اضافہ ہے کہ ابن عباس ؓ موجود تھے اور یہ کہ انہوں نے ( ابن عباس ) نے صلى بالناس ( آپ صلی اللہ علیہ وسلم نے لوگوں کو نماز پڑھائی ) کے بجائے صلى ( آپ صلی اللہ علیہ وسلم نے نماز پڑھی ) کہا ۔","",{"u2":"امام مسلم نے ایک دوسری سند سے ولید بن کثیر کے واسطے سے محمد بن عمرو بن عطاء سے روایت کی، کہا: میں ابن عباس رضی اللہ عنہ کے ساتھ تھا .... اس کے بعد انہوں نے ابن حلحلہ کی روایت کے ہم معنیٰ حدیث بیان کی ہے اور اس میں یہ اضافہ ہے کہ ابن عباس رضی اللہ عنہ موجود تھے اور یہ کہ انہوں نے (ابن عباس) نے صلی بالناس (آپ صلی اللہ علیہ وسلم نے لوگوں کو نماز پڑھائی) کے بجائے صلی (آپ صلی اللہ علیہ وسلم نے نماز پڑھی) کہا۔"}],[732,"ابو کامل فضیل بن حسین جحدری نے کہا : ہمیں ابو عوانہ نے عثمان بن عبد اللہ بن موہب سے حدیث سنائی ، انہوں نے جعفر بن ابی ثور سے اور انہوں نے سیدنا جابر بن سمرہ سے روایت کی کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا : کیا میں بکری کے گوشت سے وضو کروں؟ آپ نے فرمایا : چاہو تو وضو کر لو اور چاہو تو نہ کرو ۔ ‘‘ اس نے کہا : اونٹ کے گوشت سے وضو کروں؟ آپ نے فرمایا : ہاں ، اونٹ کے گوشت سے وضو کرو ۔ ‘‘ اس نے کہا : کیا بکریوں کے باڑے میں نماز پڑھ لوں؟ آپ نے فرمایا : ’’ہاں ۔ ‘‘ اس نے کہا : اونٹوں کے بٹھانے ک جگہ میں نماز پڑھ لوں؟ آپ نے فرمایا : ’’نہیں ۔ ‘‘","",{"u2":"ابو کامل فضیل بن حسین جحدری نے کہا: ہمیں ابو عوانہ نے عثمان بن عبد اللہ بن موہب سے حدیث سنائی، انہوں نے جعفر بن ابی ثور سے اور انہوں نے حضرت جابر بن سمرہ سے روایت کی کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کیا میں بکری کے گوشت سے وضو کروں؟ آپ نے فرمایا: چاہو تو وضو کر لو اور چاہو تو نہ کرو۔‘‘ اس نے کہا: اونٹ کے گوشت سے وضو کروں؟ آپ نے فرمایا: ہاں، اونٹ کے گوشت سے وضو کرو۔‘‘ اس نے کہا: کیا بکریوں کے باڑے میں نماز پڑھ لوں؟ آپ نے فرمایا: ’’ہاں۔‘‘ اس نے کہا: اونٹوں کے بٹھانے ک جگہ میں نماز پڑھ لوں؟ آپ نے فرمایا: ’’نہیں۔‘‘"}],[733,"سماک ، عثمان بن عبد اللہ بن موہب اور اشعث بن ابی شعثاء سب نے جعفر بن ابی ثور سے ، انہوں نے جابر بن سمرہ رضی اللہ عنہ سے اسی طرح حدیث بیان کی جس طرح ابو عوانہ سے ابو کامل نے روایت کی ۔","",{"u2":"سماک، عثمان بن عبد اللہ بن موہب اور اشعث بن ابی شعثاء سب نے جعفر بن ابی ثور سے، انہوں نے جابر بن سمرہ رضی اللہ عنہ سے اسی طرح حدیث بیان کی جس طرح ابو عوانہ سے ابو کامل نے روایت کی۔"}],[734,"عمرو ناقد ، زہیر بن حرب اور ابو بکر بن ابی شیبہ نے سفیان بن عیینہ سے ، انہوں نے زہری سے ، انہوں نے سعید ( بن مسیب ) اور عباد بن تمیم سے اور انہوں نے ان ( عباد ) کے چچا سے روایت کی کہ نبی صلی اللہ علیہ وسلم سے ایک آدمی کے حوالے سے شکایت کی گئی کہ اسے یہ خیال آتا رہتا ہے کہ وہ نماز کے دوران میں کوئی چیز محسوس کرتا ہے ۔ آپ نے فرمایا : ’’ ( وہ نماز سے ) نہ ہٹے یہاں تک کہ کوئی آواز سنے یا کوئی بو محسوس کرے ۔ ‘‘ ابو بکر اور زہیر بن حرب نے اپنی روایت میں ( عباد بن تمیم کے چچا کے بارے میں ) بتایا کہ وہ عبد اللہ بن زید رضی اللہ عنہ ہیں ۔","",{"u2":"عمرو ناقد، زہیر بن حرب اور ابو بکر بن ابی شیبہ نے سفیان بن عیینہ سے، انہوں نے زہری سے، انہوں نے سعید (بن مسیب) اور عباد بن تمیم سے اور انہوں نے ان (عباد) کے چچا سے روایت کی کہ نبی صلی اللہ علیہ وسلم سے ایک آدمی کے حوالے سے شکایت کی گئی کہ اسے یہ خیال آتا رہتا ہے کہ وہ نماز کے دوران میں کوئی چیز محسوس کرتا ہے۔ آپ نے فرمایا: ’’(وہ نماز سے) نہ ہٹے یہاں تک کہ کوئی آواز سنے یا کوئی بو محسوس کرے۔‘‘\nابو بکر اور زہیر بن حرب نے اپنی روایت میں (عباد بن تمیم کے چچا کے بارے میں) بتایا کہ وہ عبد اللہ بن زید رضی اللہ عنہ ہیں۔"}],[735,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کسی کو اپنے پیٹ میں کچھ محسوس ہو اور اسے شبہ ہو جائے کہ اس میں سے کچھ نکلا ہے یا نہیں تو ہر گز مسجد سے نہ نکلے یہاں تک کہ آواز سنے یا بو محسوس کر لے ۔ ‘‘","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو اپنے پیٹ میں کچھ محسوس ہو اور اسے شبہ ہو جائے کہ اس میں سے کچھ نکلا ہے یا نہیں تو ہر گز مسجد سے نہ نکلے یہاں تک کہ آواز سنے یا بو محسوس کر لے۔‘‘"}],[736,"یحییٰ بن یحییٰ ، ابوبکر بن ابی شیبہ ، عمرو ناقد او رابن ابی عمر سب نے سفیان بن عیینہ سے ، انہوں نے زہری سے ، انہوں عبید اللہ بن عبد اللہ سے ، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : سیدہ میمونہ ؓ کی آزاد کردہ لونڈی کو صدقے میں بکری دی گئی ، وہ مر گئی ، رسول اللہ صلی اللہ علیہ وسلم اس کے پاس سے گزرے تو آپ نے فرمایا : ’’تم نے اس چمڑا کیوں نہ اتارا ، اس کو رنگ لیتے اور اس سے فائدہ اٹھا لیتے! ‘‘ لوگوں نے بتایا : یہ مردار ہے ۔ آپ نے فرمایا : بس اس کا کھانا حرام ہے ۔ ‘‘ ابو بکر اور ابن ابی عمر نے اپنی روایت میں عن ابن عباس ، عن میمونہ کہا ( سند میں روایت ابن عباس رضی اللہ عنہ سے آگے میمونہؓ کی طرف منسوب کی ۔)","",{"u2":"یحییٰ بن یحییٰ، ابوبکر بن ابی شیبہ، عمرو ناقد او رابن ابی عمر سب نے سفیان بن عیینہ سے، انہوں نے زہری سے، انہوں عبید اللہ بن عبد اللہ سے، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی، کہا: سیدہ میمونہ رضی اللہ عنہا کی آزاد کردہ لونڈی کو صدقے میں بکری دی گئی، وہ مر گئی، رسول اللہ صلی اللہ علیہ وسلم اس کے پاس سے گزرے تو آپ نے فرمایا: ’’تم نے اس چمڑا کیوں نہ اتارا، اس کو رنگ لیتے اور اس سے فائدہ اٹھا لیتے!‘‘\nلوگوں نے بتایا: یہ مردار ہے۔ آپ نے فرمایا: بس اس کا کھانا حرام ہے۔‘‘\nابو بکر اور ابن ابی عمر نے اپنی روایت میں عن ابن عباس، عن میمونہ کہا (سند میں روایت ابن عباس رضی اللہ عنہ سے آگے میمونہ رضی اللہ عنہا کی طرف منسوب کی۔)"}],[737,"یحییٰ بن یحییٰ ، ابوبکر بن ابی شیبہ ، عمرو ناقد او رابن ابی عمر سب نے سفیان بن عیینہ سے ، انہوں نے زہری سے ، انہوں عبید اللہ بن عبد اللہ سے ، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : سیدہ میمونہ ؓ کی آزاد کردہ لونڈی کو صدقے میں بکری دی گئی ، وہ مر گئی ، رسول اللہ صلی اللہ علیہ وسلم اس کے پاس سے گزرے تو آپ نے فرمایا : ’’تم نے اس چمڑا کیوں نہ اتارا ، اس کو رنگ لیتے اور اس سے فائدہ اٹھا لیتے! ‘‘ لوگوں نے بتایا : یہ مردار ہے ۔ آپ نے فرمایا : بس اس کا کھانا حرام ہے ۔ ‘‘ ابو بکر اور ابن ابی عمر نے اپنی روایت میں عن ابن عباس ، عن میمونہ کہا ( سند میں روایت ابن عباس رضی اللہ عنہ سے آگے میمونہؓ کی طرف منسوب کی ۔)","",{"u2":"یحییٰ بن یحییٰ، ابوبکر بن ابی شیبہ، عمرو ناقد او رابن ابی عمر سب نے سفیان بن عیینہ سے، انہوں نے زہری سے، انہوں عبید اللہ بن عبد اللہ سے، انہوں نے ابن عباس رضی اللہ عنہ سے روایت کی، کہا: سیدہ میمونہ رضی اللہ عنہا کی آزاد کردہ لونڈی کو صدقے میں بکری دی گئی، وہ مر گئی، رسول اللہ صلی اللہ علیہ وسلم اس کے پاس سے گزرے تو آپ نے فرمایا: ’’تم نے اس چمڑا کیوں نہ اتارا، اس کو رنگ لیتے اور اس سے فائدہ اٹھا لیتے!‘‘\nلوگوں نے بتایا: یہ مردار ہے۔ آپ نے فرمایا: بس اس کا کھانا حرام ہے۔‘‘\nابو بکر اور ابن ابی عمر نے اپنی روایت میں عن ابن عباس، عن میمونہ کہا (سند میں روایت ابن عباس رضی اللہ عنہ سے آگے میمونہ رضی اللہ عنہا کی طرف منسوب کی۔)"}],[738,"۔ ابن شہاب کے ایک اور شاگرد صالح نے بھی اسی سند سے یونس کی حدیث کے ہم معنیٰ حدیث بیان کی ۔ 809 ۔ سفیان نے عمرو","",{"u2":"۔ ابن شہاب کے ایک اور شاگرد صالح نے بھی اسی سند سے یونس کی حدیث کے ہم معنیٰ حدیث بیان کی۔\n809۔ سفیان نے عمرو"}],[739,"سفیان نے عمرو سے ، انہوں نے عطاء سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک مردہ پڑی ہوئی بکری کے پاس سے گزرے جو میمونہؓ کی باندی کو بطور صدقہ دی گئی تھی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’انہوں نے اس کے چمڑے کو کیوں نہ اتارا ، وہ اس کو رنگ لیتے اور فائدہ اٹھا لیتے! ‘‘","",{"u2":"سفیان نے عمرو سے، انہوں نے عطاء سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک مردہ پڑی ہوئی بکری کے پاس سے گزرے جو میمونہ رضی اللہ عنہا کی باندی کو بطور صدقہ دی گئی تھی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’انہوں نے اس کے چمڑے کو کیوں نہ اتارا، وہ اس کو رنگ لیتے اور فائدہ اٹھا لیتے!‘‘"}],[740,"ابن جریج نے عمرو بن دینار سے باقی ماندہ سابقہ سند کے ساتھ ابن عباس رضی اللہ عنہ سے روایت کی کہ سیدہ میمونہؓ نے انہیں بتایا کہ ایک بکری ، جو رسول اللہ صلی اللہ علیہ وسلم کی ایک بیوی کی تھی ، مر گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’تم نے اس کا چمڑا اتار کر اس سے فائدہ کیوں نہیں اٹھایا! ‘‘","",{"u2":"ابن جریج نے عمرو بن دینار سے باقی ماندہ سابقہ سند کے ساتھ ابن عباس رضی اللہ عنہ سے روایت کی کہ سیدہ میمونہ رضی اللہ عنہا نے انہیں بتایا کہ ایک بکری، جو رسول اللہ صلی اللہ علیہ وسلم کی ایک بیوی کی تھی، مر گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم نے اس کا چمڑا اتار کر اس سے فائدہ کیوں نہیں اٹھایا!‘‘"}],[741,"عبد الملک بن ابی سلیمان نے عطاء کے حوالے سے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم سیدہ میمونہؓ کی باندی کی ( مردہ ) بکری کے پاس سے گزرے تو آپ نے فرمایا : ’’تم نے اس کے چمڑے سے فائدہ کیوں نہ اٹھایا! ‘‘","",{"u2":"عبد الملک بن ابی سلیمان نے عطاء کے حوالے سے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم سیدہ میمونہ رضی اللہ عنہا کی باندی کی (مردہ) بکری کے پاس سے گزرے تو آپ نے فرمایا: ’’تم نے اس کے چمڑے سے فائدہ کیوں نہ اٹھایا!‘‘"}],[742,"سلیمان بن بلال نے زید بن اسلم سے ، انہوں نے عبد الرحمن بن وعلہ سے ، انہوں نے سیدنا عبد اللہ بن عباسؓ کے حوالے سے خبر دی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ نے فرمایا : ’’جب چمڑے کو رنگ لیا جاتا ہے تو وہ پاک ہو جاتا ہے ۔ ‘‘","",{"u2":"سلیمان بن بلال نے زید بن اسلم سے، انہوں نے عبد الرحمن بن وعلہ سے، انہوں نے سیدنا عبد اللہ بن عباس رضی اللہ عنہ کے حوالے سے خبر دی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ نے فرمایا: ’’جب چمڑے کو رنگ لیا جاتا ہے تو وہ پاک ہو جاتا ہے۔‘‘"}],[743,"سفیان بن عیینہ ، عبد العزیز بن محمد اور سفیان ثوری نے مختلف سندوں کے ساتھ زید بن اسلم کی سابقہ سند کے ساتھ نبی صلی اللہ علیہ وسلم سے اسی طرح روایت بیان کی ، یعنی یحییٰ بن یحییٰ کی حدیث کی طرح ۔","",{"u2":"سفیان بن عیینہ، عبد العزیز بن محمد اور سفیان ثوری نے مختلف سندوں کے ساتھ زید بن اسلم کی سابقہ سند کے ساتھ نبی صلی اللہ علیہ وسلم سے اسی طرح روایت بیان کی، یعنی یحییٰ بن یحییٰ کی حدیث کی طرح۔"}],[744,"۔ یزید بن ابی حبیب نے ابو خیر سے روایت کی کہ میں نے علی بن وعلہ سبائی کو ایک پوستین ( چمڑے کا کوٹ ) پہنے ہوئے دیکھا ، میں نے اسے چھوا تو اس نے کہا : اسے کیوں چھوتے ہو؟ میں نے عبد اللہ بن عباسؓ سے پوچھا تھا : ہم مغرب میں ہوتے ہیں اور ہمارے ساتھ بربر اور مجوسی ہوتے ہیں ، ہمارے پاس مینڈھا لایا جاتا ہے جسے انہوں نے ذبح کیا ہوتا ہے اور ہم ان کے ذبح کیے ہوئے جانور نہیں کھاتے ، وہ ہمارے پاس مشکیزہ لاتے ہیں جس میں وہ چربی ڈالتے ہیں ۔ تو ابن عباسؓ نے جواب دیا : ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تھا ۔ آپ نے فرمایا : ’’ اس کو رنگنا اس کو پاک کر دیتا ہے ۔ ‘‘","",{"u2":"۔ یزید بن ابی حبیب نے ابو خیر سے روایت کی کہ میں نے علی بن وعلہ سبائی کو ایک پوستین (چمڑے کا کوٹ) پہنے ہوئے دیکھا، میں نے اسے چھوا تو اس نے کہا: اسے کیوں چھوتے ہو؟ میں نے عبد اللہ بن عباس رضی اللہ عنہ سے پوچھا تھا: ہم مغرب میں ہوتے ہیں اور ہمارے ساتھ بربر اور مجوسی ہوتے ہیں، ہمارے پاس مینڈھا لایا جاتا ہے جسے انہوں نے ذبح کیا ہوتا ہے اور ہم ان کے ذبح کیے ہوئے جانور نہیں کھاتے، وہ ہمارے پاس مشکیزہ لاتے ہیں جس میں وہ چربی ڈالتے ہیں۔ تو ابن عباس رضی اللہ عنہ نے جواب دیا: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے بارے میں پوچھا تھا۔ آپ نے فرمایا: ’’ اس کو رنگنا اس کو پاک کر دیتا ہے۔‘‘"}],[745,"۔ جعفر بن ربیعہ نے ابو خیر سے روایت کی ، کہا : مجھ سے ابن وعلہ سبائی نے بیان کیا کہ میں نے عبد اللہ بن عباسؓ سے پوچھا : ہم مغرب میں ہوتے ہیں تو مجوسی ہمارے پاس پانی اور چربی کے مشکیزے لاتے ہیں ۔ انہوں نے کہا : پی لیا کرو ۔ میں نے پوچھا : کیا آپ اپنی رائے بتا رہے ہیں؟ ابن عباسؓ نے جواب دیا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سناے : ’’ اس کو رنگنا اس کو پاک کر دیتا ہے ۔ ‘‘","",{"u2":"۔ جعفر بن ربیعہ نے ابو خیر سے روایت کی، کہا: مجھ سے ابن وعلہ سبائی نے بیان کیا کہ میں نے عبد اللہ بن عباس رضی اللہ عنہ سے پوچھا: ہم مغرب میں ہوتے ہیں تو مجوسی ہمارے پاس پانی اور چربی کے مشکیزے لاتے ہیں۔ انہوں نے کہا: پی لیا کرو۔ میں نے پوچھا: کیا آپ اپنی رائےبتا رہے ہیں؟ ابن عباس رضی اللہ عنہ نے جواب دیا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سناے: ’’ اس کو رنگنا اس کو پاک کر دیتا ہے۔‘‘"}],[746,"۔ عبد الرحمان بن قاسم ( بن محمد ) نے اپنے والد سے ، انہوں نے سیدہ عائشہؓ سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ایک سفر میں آپ کے ساتھ نکلے ، جب ہم بیداء یا ذات الجیش کے مقام پر پہنچے تو میرا ہار ٹوٹ کر گر گیا ، رسول اللہ صلی اللہ علیہ وسلم اس کی تلاش کی خاطر ٹھہر گئے ، صحابہ کرام رضی اللہ عنہ بھی آپ کے ساتھ رک گئے ، نہ وہ پانی ( والی جگہ ) پر تھے نہ ان کے پاس پانی ( بچا ہوا ) تھا ۔ لوگ ابو بکر رضی اللہ عنہ کے پاس آئے اور کہا : کیا آپ کو پتہ نہیں ، عائشہؓ نے کیا کیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ ( دوسرے ) لوگوں کو روک رکھا ہے ، نہ وہ پانی ( والی جگہ ) پر ہیں اور نہ لوگوں کے پاس پانی بچا ہے ۔ ابو بکر رضی اللہ عنہ تشریف لائے ( اس وقت ) رسول اللہ صلی اللہ علیہ وسلم میری ران پر سر رکھ کر سو چکے تھے اور کہا : تم نے رسول اللہ صلی اللہ علیہ وسلم کو اور آپ کے ساتھیوں کو روک رکھا ہے جبکہ نہ وہ پانی والی جگہ پر ہیں اور نہ ان کے پاس پانی ہے ۔ عائشہؓ نے فرمایا : سیدنا ابو بکر رضی اللہ عنہ نے مجھے ڈانٹا اور جو کچھ اللہ کو منظور رتھا کہا اور اپنے ہاتھ سے میری کوکھ میں کچوکے لگانے لگے ، مجھے صرف اس بات نے حرکت کرنے سے روکے رکھا کہ رسول اللہ صلی اللہ علیہ وسلم کا سر میری ران پر تھا ، رسول اللہ صلی اللہ علیہ وسلم سوئے رہے اور پانی کے بغیر ہی صبح ہو گی ۔ اس پر اللہ تعالیٰ نے تیمم کی آیت اتاری تو صحابہ کرام رضی اللہ عنہ نے تیمم کیا ۔ اسید بن حضیر رضی اللہ عنہ نے ، جو نقباء میں سے تھے ، کہا : اے ابو بکر رضی اللہ عنہ کے خاندان! یہ آپ کی پہلی برکت نہیں ہے ۔ سیدہ عائشہؓ نے کہا : ہم نے اس اونٹ کو جس پر میں سوار تھی اٹھایا تو ہمیں اس کے نیچے سے ہار مل گیا ۔","",{"u2":"۔ عبد الرحمان بن قاسم (بن محمد) نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ایک سفر میں آپ کے ساتھ نکلے، جب ہم بیداء یا ذات الجیش کے مقام پر پہنچے تو میرا ہار ٹوٹ کر گر گیا، رسول اللہ صلی اللہ علیہ وسلم اس کی تلاش کی خاطر ٹھہر گئے، صحابہ کرام رضی اللہ عنہم بھی آپ کے ساتھ رک گئے، نہ وہ پانی (والی جگہ) پر تھے نہ ان کے پاس پانی (بچا ہوا) تھا۔ لوگ ابو بکر رضی اللہ عنہ کے پاس آئے اور کہا: کیا آپ کو پتہ نہیں، عائشہ رضی اللہ عنہا نے کیا کیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ (دوسرے) لوگوں کو روک رکھا ہے، نہ وہ پانی (والی جگہ) پر ہیں اور نہ لوگوں کے پاس پانی بچا ہے۔ ابو بکر رضی اللہ عنہ تشریف لائے (اس وقت) رسول اللہ صلی اللہ علیہ وسلم میری ران پر سر رکھ کر سو چکے تھے اور کہا: تم نے رسول اللہ صلی اللہ علیہ وسلم کو اور آپ کے ساتھیوں کو روک رکھا ہے جبکہ نہ وہ پانی والی جگہ پر ہیں اور نہ ان کے پاس پانی ہے۔ عائشہ رضی اللہ عنہا نے فرمایا: سیدنا ابو بکر رضی اللہ عنہ نے مجھے ڈانٹا اور جو کچھ اللہ کو منظور رتھا کہا اور اپنے ہاتھ سے میری کوکھ میں کچوکے لگانے لگے، مجھے صرف اس بات نے حرکت کرنے سے روکے رکھا کہ رسو ل اللہ صلی اللہ علیہ وسلم کا سر میری ران پر تھا، رسول اللہ صلی اللہ علیہ وسلم سوئے رہے اور پانی کے بغیر ہی صبح ہو گی۔ اس پر اللہ تعالیٰ نے تیمم کی آیت اتاری تو صحابہ کرام رضی اللہ عنہم نے تیمم کیا۔ اسید بن حضیر رضی اللہ عنہ نے، جو نقباء میں سے تھے، کہا: اے ابو بکر رضی اللہ عنہ کے خاندان! یہ آپ کی پہلی برکت نہیں ہے۔ سیدہ عائشہ رضی اللہ عنہا نے کہا: ہم نے اس اونٹ کو جس پر میں سوار تھی اٹھایا تو ہمیں اس کے نیچے سے ہار مل گیا۔"}],[747,"ہشام کے والد عروہ بن زبیر نے سیدہ عائشہؓ سے روایت کی کہ انہوں نے سیدہ اسماء ؓ سے عاریتاً ہار لیا ، وہ گم ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے کچھ ساتھیوں کو اس کی تلاش کے لیے بھیجا ۔ ان کی نماز کا وقت آ گیا تو انہوں نے بغیر وضو کے نماز پڑھ لی اور جب نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو آپ سے اس بات کی شکایت کی ، ( اس پر ) تیمم کی آیت اتری تو اسید بن حضیر رضی اللہ عنہ نے ( سیدہ عائشہؓ سے ) کہا : اللہ آپ کو بہترین جزا دے ، اللہ کی قسم! آپ کو کبھی کوئی مشکل معاملہ پیش نہیں آیا مگر اللہ تعالیٰ نے آپ کے لیے اس سے نکلنے کی سبیل پیدا کر دی اور اسی میں مسلمانوں کے لیے برکت رکھ کر دی ۔","",{"u2":"ہشام کے والد عروہ بن زبیر نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ انہوں نے سیدہ اسماء رضی اللہ عنہا سے عاریتاً ہار لیا، وہ گم ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے کچھ ساتھیوں کو اس کی تلاش کے لیے بھیجا۔ ان کی نماز کا وقت آ گیا تو انہوں نے بغیر وضو کے نماز پڑھ لی اور جب نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو آپ سے اس بات کی شکایت کی، (اس پر) تیمم کی آیت اتری تو اسید بن حضیر رضی اللہ عنہ نے (سیدہ عائشہ رضی اللہ عنہا سے) کہا: اللہ آپ کو بہترین جزا دے، اللہ کی قسم! آپ کو کبھی کوئی مشکل معاملہ پیش نہیں آیا مگر اللہ تعالیٰ نے آپ کے لیے اس سے نکلنے کی سبیل پیدا کر دی اور اسی میں مسلمانوں کے لیے برکت رکھ کر دی۔"}],[748,"ابو معاویہ نے اعمش سے ، انہوں نے شقیق سے روایت کی ، کہا : میں سیدنا عبد اللہ ( بن مسعود ) اور ابو موسیٰ ؓ کے بیٹھا ہوا تھا ۔ سیدنا ابو موسیٰ نے پوچھا : ابو عبد الرحمن! بتائیےاگر انسان حالت جنابت میں ہو اور ایک ماہ تک اسے پانی نہ ملے تو وہ نماز کا کیا کرے؟ اس پر سیدنا عبد اللہ ( بن مسعود رضی اللہ عنہ ) نے جواب دیا : وہ تیمم نہ کرے ، چاہے اسے ایک ماہ تک پانی نہ ملے ۔ اس پر ابو موسیٰ رضی اللہ عنہ نے کہا : تو سورہ مائدہ کی اس آیت کا کیا مطلب ہے : ’’تم پانی نہ پاؤ تو پاک مٹی سے تیمم کرو؟ ‘‘ اس پر عبد اللہ رضی اللہ عنہ نے جواب دیا : اگر انہیں اس آیت کی بنا پر رخصت دے دی گئی تو خطرہ ہے جب انہیں پانی ٹھنڈا محسوس ہو گا تو وہ مٹی سے تیمم کر لیں گے ۔ ابو موسیٰ رضی اللہ عنہ نے عبد اللہ رضی اللہ عنہ سے کہا : کیا آپ نے عمار کی یہ بات نہیں سنی کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے کسی کام کے لیے بھیجا ، مجھے جنابت ہو گئی اور پانی نہ ملا تو میں چوپائے کی طرح مٹی میں لوٹ پوٹ ہوا ( اور نماز پڑھ لی ) ، پھر میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے اس کا تذکرہ کیا تو آپ نے فرمایا : ’’تمہارے لیے بس اپنے دونوں ہاتھوں سے اس طرح کرنا کافی تھا ۔ ‘‘ پھر آپ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ ایک بار زمین پر مارے ، پھر بائیں ہاتھ کو دائیں پر اور اپنی دونوں ہتھیلیوں کی پشت پر اور اپنے چہرے پر ملا ۔ تو عبد اللہ ( بن مسعود رضی اللہ عنہ ) نے جواب دیا : کیا تمہیں معلوم نہیں کہ سیدنا عمر رضی اللہ عنہ عمار کی بات پر مطمئن نہیں ہوئے تھے ۔ ( تفصیل آگے حدیث : 820 میں ہے ۔)","",{"u2":"ابو معاویہ نے اعمش سے، انہوں نے شقیق سے روایت کی، کہا: میں حضرت عبد اللہ (بن مسعود) اور ابو موسیٰ رضی اللہ عنہ کے بیٹھا ہوا تھا۔ حضرت ابو موسیٰ نے پوچھا: ابو عبد الرحمن! بتائیےاگر انسان حالت جنابت میں ہو اور ایک ماہ تک اسے پانی نہ ملے تو وہ نماز کا کیا کرے؟ اس پر حضرت عبد اللہ (بن مسعود رضی اللہ عنہ) نے جواب دیا:وہ تیمم نہ کرے، چاہے اسے ایک ماہ تک پانی نہ ملے۔ اس پر ابو موسیٰ رضی اللہ عنہ نے کہا: تو سورہ مائدہ کی اس آیت کا کیا مطلب ہے: ’’تم پانی نہ پاؤ تو پاک مٹی سے تیمم کرو؟‘‘ اس پر عبد اللہ رضی اللہ عنہ نے جواب دیا: اگر انہیں اس آیت کی بنا پر رخصت دے دی گئی تو خطرہ ہے جب انہیں پانی ٹھنڈا محسوس ہو گا تو وہ مٹی سے تیمم کر لیں گے۔ ابو موسیٰ رضی اللہ عنہ نے عبد اللہ رضی اللہ عنہ سے کہا: کیا آپ نے عمار کی یہ بات نہیں سنی کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے کسی کام کے لیے بھیجا، مجھے جنابت ہو گئی اور پانی نہ ملا تو میں چوپائے کی طرح مٹی میں لوٹ پوٹ ہوا (اور نماز پڑھ لی)، پھر میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے اس کا تذکرہ کیا تو آپ نے فرمایا: ’’تمہارے لیے بس اپنے دونوں ہاتھوں سے اس طرح کرنا کافی تھا۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ ایک بار زمین پر مارے، پھر بائیں ہاتھ کو دائیں پر اور اپنی دونوں ہتھیلیوں کی پشت پر اور اپنے چہرے پر ملا۔ تو عبد اللہ (بن مسعود رضی اللہ عنہ) نے جواب دیا: کیا تمہیں معلوم نہیں کہ سیدنا عمر رضی اللہ عنہ عمار کی بات پر مطمئن نہیں ہوئے تھے۔ (تفصیل آگے حدیث: 820 میں ہے۔)"}],[749,"عبد الواحد نے کہا : ہمیں اعمش نے شقیق سے حدیث بیان کی ، کہا : ابو موسیٰ اشعری رضی اللہ عنہ نے عبد اللہ ( بن مسعود ) رضی اللہ عنہ سے پوچھا ... پھر ابو معاویہ کی ( سابقہ ) حدیث پورے واقعے سمیت بیان کی ، مگر یہ کہ انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ تمہارے لیے اس طرح کر لینا ہی کافی تھا ۔ ‘‘ اور اپنے دونوں ہاتھ زمین پر مارے ، ( پھر ) اپنے دونوں ہاتھ جھاڑے اور اپنے چہرے اور ہتھیلیوں پر مسح کیا ۔","",{"u2":"عبد الواحد نے کہا: ہمیں اعمش نے شقیق سے حدیث بیان کی، کہا: ابو موسیٰ اشعری رضی اللہ عنہ نے عبد اللہ (بن مسعود) رضی اللہ عنہ سے پوچھا ... پھر ابو معاویہ کی (سابقہ) حدیث پورے واقعے سمیت بیان کی، مگر یہ کہ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ تمہارے لیے اس طرح کر لینا ہی کافی تھا۔‘‘ اور اپنے دونوں ہاتھ زمین پر مارے، (پھر) اپنے دونوں ہاتھ جھاڑے اور اپنے چہرے اور ہتھیلیوں پر مسح کیا۔"}],[750,"۔ یحییٰ بن سعید قطان نے شعبہ سے حدیث بیان کی ، کہا : مجھ سے حکم نے ذر ( بن عبد اللہ بن زرارہ ) سے ، انہوں نے سعید بن عبد الرحمن بن ابزیٰ سے اور انہوں نے اپنے والد سے روایت کی کہ ایک آدمی سیدنا عمر رضی اللہ عنہ کے پاس آیا اور پوچھا : میں جنبی ہو گیا ہوں اور مجھے پانی نہیں ملا ۔ تو انہوں نے جواب دیا : نماز نہ پڑھ ۔ اس پر سیدنا عمار رضی اللہ عنہ نے کہا : امیر المؤمنین! کیا آپ کو یاد نہیں ، جب میں اور آپ ایک فوجی دستے میں تھے تو ہم جنبی ہو گئے اور پانی نہ ملا تو آپ نے نماز نہ پڑھی اور میں مٹی میں لوٹ پوٹ ہو گیا اور نماز پڑھ لی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’تمہارے لیے بس اتنا ہی کافی تھا کہ اپنے دونوں ہاتھ زمین پر مارتے ، پھر ان میں پھونک مار کر ان دونوں سے اپنے چہرے اور اپنی ہتھیلیوں کا مسح کر لیتے ۔ ‘‘ سیدنا عمر رضی اللہ عنہ نے کہا : اے عمار! اللہ سے ڈرو ۔ ( عمار رضی اللہ عنہ نے ) جواب دیا : اگر آپ چاہتے ہیں تو میں یہ واقعہ بیان نہیں کرتا ۔ حکم نے کہا : یہی روایت مجھے ( ذر کے واسطے کے بغیر ) ابن عبد الرحمن بن ابزیٰ نے اپنے والد سے براہ راست بھی سنائی جو بعینہ ذر کی حدیث کی طرح تھی ۔ کہا : مجھے سلمہ نے ذر کے حوالے سے حکم کی بیان کردہ سند کے ساتھ یہ حدیث بیان کی کہ سیدنا عمر رضی اللہ عنہ نے کہا : آپ نے جس چیز ( کی ذمہ داری ) کو اٹھا لیا ہے ہم اسے آپ ہی پر ڈالتے ہیں ( آپ اپنے اعتماد پر یہ روایت بیان کر سکتے ہیں ۔)","",{"u2":"۔ یحییٰ بن سعید قطان نے شعبہ سے حدیث بیان کی، کہا: مجھ سے حکم نے ذر (بن عبد اللہ بن زرارہ) سے، انہوں نے سعید بن عبد الرحمن بن ابزیٰ سے اور انہوں نے اپنے والد سے روایت کی کہ ایک آدمی سیدنا عمر رضی اللہ عنہ کے پاس آیا اور پوچھا: میں جنبی ہو گیا ہوں اور مجھے پانی نہیں ملا۔ تو انہوں نے جواب دیا: نماز نہ پڑھ۔ اس پر سیدنا عمار رضی اللہ عنہ نے کہا: امیر المؤمنین! کیا آپ کو یاد نہیں، جب میں اور آپ ایک فوجی دستے میں تھے تو ہم جنبی ہو گئے اور پانی نہ ملا تو آپ نے نماز نہ پڑھی اور میں مٹی میں لوٹ پوٹ ہو گیا اور نماز پڑھ لی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’تمہارے لیے بس اتنا ہی کافی تھا کہ اپنے دونوں ہاتھ زمین پر مارتے، پھر ان میں پھونک مار کر ان دونوں سے اپنے چہرے اور اپنی ہتھیلیوں کا مسح کر لیتے۔‘‘ سیدنا عمر رضی اللہ عنہ نے کہا: اے عمار! اللہ سے ڈرو۔ (عمار رضی اللہ عنہ نے) جواب دیا: اگر آپ چاہتے ہیں تو میں یہ واقعہ بیان نہیں کرتا۔\nحکم نے کہا: یہی روایت مجھے (ذر کے واسطے کے بغیر) ابن عبد الرحمن بن ابزیٰ نے اپنے والد سے براہ راست بھی سنائی جو بعینہ ذر کی حدیث کی طرح تھی۔ کہا: مجھے سلمہ نے ذر کے حوالے سے حکم کی بیان کردہ سند کے ساتھ یہ حدیث بیان کی کہ سیدنا عمر رضی اللہ عنہ نے کہا: آپ نے جس چیز (کی ذمہ داری) کو اٹھا لیا ہے ہم اسے آپ ہی پر ڈالتے ہیں (آپ اپنے اعتماد پر یہ روایت بیان کر سکتے ہیں۔)"}],[751,"نضر بن شمیل نے شعبہ سے باقی ماندہ سابقہ سند کے ساتھ روایت کی کہ ایک آدمی سیدنا عمر رضی اللہ عنہ کے پاس آیا اور پوچھا : میں جنبی ہو گیا ہوں اور مجھے پانی نہیں ملا ۔ اس کے بعد ( مذکورہ بالا ) حدیث بیان کی اور اس میں یہ اضافہ کیا کہ عمار رضی اللہ عنہ نے کہا : اے امیر المؤمنین! اگر آپ چاہیں تو آپ کے اس حق کی بنا پر جو اللہ تعالیٰ نے مجھ پر رکھا ہے ، میں یہ حدیث کسی کو نہ سناؤں گا ۔ اور ( شعبہ نے یہاں ) مجھے سلمہ نے ذر حدیث بیان کی ( کے الفاظ ) کا ذکر نہیں کیا ۔","",{"u2":"نضر بن شمیل نے شعبہ سے باقی ماندہ سابقہ سند کے ساتھ روایت کی کہ ایک آدمی سیدنا عمر رضی اللہ عنہ کے پاس آیا اور پوچھا: میں جنبی ہو گیا ہوں اور مجھے پانی نہیں ملا۔ اس کے بعد (مذکورہ بالا) حدیث بیان کی اور اس میں یہ اضافہ کیا کہ عمار رضی اللہ عنہ نے کہا: اے امیر المؤمنین! اگر آپ چاہیں تو آپ کے اس حق کی بنا پر جو اللہ تعالیٰ نے مجھ پر رکھا ہے، میں یہ حدیث کسی کو نہ سناؤں گا۔ اور (شعبہ نے یہاں) مجھے سلمہ نے ذر حدیث بیان کی (کے الفاظ) کا ذکر نہیں کیا۔"}],[752,"سیدنا ابن عباس رضی اللہ عنہ کے آزاد کردہ غلام عمیر بیان کرتے ہیں کہ میں اور عبد الرحمن بن یسار ، جو نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہؓ کے آزاد کردہ غلام تھے ، ابو جہم بن حارث بن صمہ انصاری کے پاس پہنچے تو ابو جہم رضی اللہ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم بئر جمل ( نامی جگہ ) سے تشریف لائے تو آپ کو ایک آدمی ملا ، اس نے آپ کو سلام کہا تو آپ نے اس کے سلام کا جواب نہ دیا حتیٰ کہ آپ ایک دیوار کی طرف بڑھے اور آپ نے اپنے چہرے اور ہاتھوں پر مسح کیا ، پھر اس کے سلام کا جواب دیا ۔","",{"u2":"سیدنا ابن عباس رضی اللہ عنہ کے آزاد کردہ غلام عمیر بیان کرتے ہیں کہ میں اور عبد الرحمن بن یسار، جو نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا کے آزاد کردہ غلام تھے، ابو جہم بن حارث بن صمہ انصاری کے پاس پہنچے تو ابو جہم رضی اللہ عنہ نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم بئر جمل (نامی جگہ) سے تشریف لائے تو آپ کو ایک آدمی ملا، اس نے آپ کو سلام کہا تو آپ نے اس کے سلام کا جواب نہ دیا حتیٰ کہ آپ ایک دیوار کی طرف بڑھے اور آپ نے اپنے چہرے اور ہاتھوں پر مسح کیا، پھر اس کے سلام کا جواب دیا۔"}],[753,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے ، ایک آدمی گزرا جبکہ رسول اللہ صلی اللہ علیہ وسلم پیشاب کر رہے تھے ، تو اس نے سلام کہا ، آپ صلی اللہ علیہ وسلم نے اسے سلام کا جواب نہ دیا ۔","",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے، ایک آدمی گزرا جبکہ رسول اللہ صلی اللہ علیہ وسلم پیشاب کر رہے تھے، تو اس نے سلام کہا، آپ صلی اللہ علیہ وسلم نے اسے سلام کا جواب نہ دیا۔"}],[754,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ وہ جنابت کی حالت میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ کے راستوں میں میں سے کسی راستے پر انہیں ملے تو وہ کھسک گئے اور جا کر غسل کیا ۔ نبی صلی اللہ علیہ وسلم نے انہیں تلاش کروایا ۔ جب وہ آپ کی خدمت میں آئے تو آپ نے فرمایا : ’’ابو ہریرہ! تم کہاں تھے؟ ‘‘ انہوں نے عرض کی! اے اللہ کے رسول صلی اللہ علیہ وسلم! جب آپ مجھے ملے تو میں جنابت کی حالت میں تھا ، میں نے غسل کیے بغیر آپ کے پاس بیٹھنا پسند نہ کیا ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’سبحان اللہ! مومن ناپاک ( نجس ) نہیں ہوتا ۔ ‘‘ ( یعنی اس طرح ناپاک نہیں ہوتا کہ اسے کوئی چھو جائے ، قریب بیٹھے یا اس سے ہاتھ ملائے تو وہ بھی ناپاک ہو جائے ۔)"],[755,"سیدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم انہیں ملے جبکہ وہ جنبی تھے تو وہ آپ صلی اللہ علیہ وسلم سے دور ہٹ گئے اور غسل کیا ، پھر آ کر عرض کی کہ میں جنبی تھا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : ’’مسلمان ناپاک نہیں ہوتا ۔ ‘‘","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ وہ جنابت کی حالت میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ کے راستوں میں میں سے کسی راستے پر انہیں ملے تو وہ کھسک گئے اور جا کر غسل کیا۔ نبی صلی اللہ علیہ وسلم نے انہیں تلاش کروایا۔ جب وہ آپ کی خدمت میں آئے تو آپ نے فرمایا: ’’ابو ہریرہ! تم کہاں تھے؟‘‘ انہوں نے عرض کی! اے اللہ کے رسول صلی اللہ علیہ وسلم! جب آپ مجھے ملے تو میں جنابت کی حالت میں تھا، میں نے غسل کیے بغیر آپ کے پاس بیٹھنا پسند نہ کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سبحان اللہ! مومن ناپاک (نجس) نہیں ہوتا۔‘‘ (یعنی اس طرح ناپاک نہیں ہوتا کہ اسے کوئی چھو جائے، قریب بیٹھے یا اس سے ہاتھ ملائے تو وہ بھی ناپاک ہو جائے۔)\nسیدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم انہیں ملے جبکہ وہ جنبی تھے تو وہ آپ صلی اللہ علیہ وسلم سے دور ہٹ گئے اور غسل کیا، پھر آ کر عرض کی کہ میں جنبی تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان ناپاک نہیں ہوتا۔‘‘"}],[756,"سیدہ عائشہؓ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم اپنے تمام اوقات میں اللہ تعالیٰ کا ذکر کرتے تھے","",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم اپنے تمام اوقات میں اللہ تعالیٰ کا ذکر کرتے تھے"}],[757,"۔ حماد نے عمرو بن سے ، انہوں نے سعید بن حویرث سے ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کہ نبی اکرم صلی اللہ علیہ وسلم ( ہاتھ دھو کر ) بیت الخلا سے نکلے تو آپ کے سامنے کھانا پیش کیا گیا ، لوگوں نے آپ سے وضو کا تذکرہ کیا تو آپ نے فرمایا : ’’ ( کیا ) میں نماز پڑھنا چاہتا ہوں کہ وضو کروں؟ ‘‘","",{"u2":"۔ حماد نے عمرو بن سے، انہوں نے سعید بن حویرث سے، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کہ نبی اکرم صلی اللہ علیہ وسلم (ہاتھ دھو کر) بیت الخلا سے نکلے تو آپ کے سامنے کھانا پیش کیا گیا، لوگوں نے آپ سے وضو کا تذکرہ کیا تو آپ نے فرمایا: ’’(کیا) میں نماز پڑھنا چاہتا ہوں کہ وضو کروں؟‘‘"}],[758,"سفیان بن عیینہ نے عمرو سے باقی ماندہ سابقہ سند سے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، کہتے تھے کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے کہ آپ قضائے حاجت کی جگہ سے ( ہاتھ دھو کر ) آئے تو آپ کے سامنے کھانا پیش کیا گیا ، آپ سے عرض کی گئی : کیا آپ وضو نہیں فرمائیں گے؟ آپ نے جواب دیا : کس لیے؟ کیا مجھے نماز پڑھنی ہے کہ وضو کروں؟ ‘‘","",{"u2":"سفیان بن عیینہ نے عمرو سے باقی ماندہ سابقہ سند سے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، کہتے تھے کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے کہ آپ قضائے حاجت کی جگہ سے (ہاتھ دھو کر) آئے تو آپ کے سامنے کھانا پیش کیا گیا، آپ سے عرض کی گئی: کیا آپ وضو نہیں فرمائیں گے؟ آپ نے جواب دیا: کس لیے؟ کیا مجھے نماز پڑھنی ہے کہ وضو کروں؟‘‘"}],[759,"محمد بن مسلم طائفی نے عمرو بن دینار سے ، انہوں نے آل سائب کے آزاد کردہ غلام سعید بن حویرث سے روایت کی کہ اس نے عبد اللہ بن عباس رضی اللہ عنہ کو ( یہ ) کہتے ہوئے سنا : اللہ کے رسول صلی اللہ علیہ وسلم قضائے حاجت کے لیے تشریف لے گئے ، جب آپ آئے تو آپ کو کھانا پیش کیا گیا ، آپ سے عرض کی گئی : اے اللہ کے رسول! کیا آپ وضو نہیں فرمائیں گئے؟ آپ نے جواب دیا : ’’کس لیے؟ کیا نماز کے لیے؟ ‘‘","",{"u2":"محمد بن مسلم طائفی نے عمرو بن دینار سے، انہوں نے آل سائب کے آزاد کردہ غلام سعید بن حویرث سے روایت کی کہ اس نے عبد اللہ بن عباس رضی اللہ عنہ کو (یہ) کہتے ہوئے سنا: اللہ کے رسول صلی اللہ علیہ وسلم قضائے حاجت کے لیے تشریف لے گئے، جب آپ آئے تو آپ کو کھانا پیش کیا گیا، آپ سے عرض کی گئی: اے اللہ کے رسول! کیا آپ وضو نہیں فرمائیں گئے؟ آپ نے جواب دیا: ’’کس لیے؟ کیا نماز کے لیے؟‘‘"}],[760,"اس نے سعید بن حویرث سے سنا ہے ۔","",{"u2":"اس نے سعید بن حویرث سے سنا ہے۔"}],[761,"یحییٰ بن یحییٰ نے حماد بن زید اور ہشیم سے ، ان دونوں نے عبد العزیز بن صہیب سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ( حماد کی حدیث میں ہے : رسول اللہ صلی اللہ علیہ وسلم جب بیت الخلاء میں داخل ہوتے اور ہشیم کے الفاظ ہیں : جب کسی اوٹ والی جگہ میں داخل ہوتے ) تو فرماتے : ’’اے اللہ! میں نر اور مادہ دونوں قسم کی خبیث مخلوق سے تیری پناہ میں آتا ہوں ۔ ‘‘","",{"u2":"یحییٰ بن یحییٰ نے حماد بن زید اور ہشیم سے، ان دونوں نے عبد العزیز بن صہیب سے، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی (حماد کی حدیث میں ہے: رسول اللہ صلی اللہ علیہ وسلم جب بیت الخلاء میں داخل ہوتے اور ہشیم کے الفاظ ہیں: جب کسی اوٹ والی جگہ میں داخل ہوتے) تو فرماتے: ’’اے اللہ! میں نر اور مادہ دونوں قسم کی خبیث مخلوق سے تیری پناہ میں آتا ہوں۔‘‘"}],[762,"اسماعیل بن علیہ نے اسی مذکورہ بالا سند کے ساتھ عبد العزیز سے روایت بیان کی اور ( دعا کے ) یہ الفاظ بیان کیے : أعوذ باللہ من الخبث والخبائث ’’میں نر اور مادہ دونوں قسم کی خبیث مخلوق سے اللہ کی پناہ میں آتا ہوں ۔ ‘‘","",{"u2":"اسماعیل بن علیہ نے اسی مذکورہ بالا سند کے ساتھ عبد العزیز سے روایت بیان کی اور (دعا کے) یہ الفاظ بیان کیے: أعوذ باللہ من الخبث والخبائث ’’میں نر اور مادہ دونوں قسم کی خبیث مخلوق سے اللہ کی پناہ میں آتا ہوں۔‘‘"}],[763,"اسماعیل بن علیہ اور عبد الوارث دونوں نے عبد العزیز سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : نماز کے لیے تکبیر کہہ دی گئی اور رسول اللہ صلی اللہ علیہ وسلم ایک آدمی سے بہت قریب ہو کر آہستہ آہستہ بات کر رہے تھے ۔ ( عبد الوارث کی روایت میں ورسول اللہ صلی اللہ علیہ وسلم نجي لرجل کے بجائے ونبی اللہ صلی اللہ علیہ وسلم یناجی الرجل آپ ایک آدمی سے آہستہ آہستہ باتیں کر رہے تھے ہے ۔ مفہوم ایک ہے ) تو آپ نماز کے لیے کھڑے نہیں ہوئے یہاں تک کہ لوگ ( بیٹھے بیٹھے ) سو گئے ۔","",{"u2":"اسماعیل بن علیہ اور عبد الوارث دونوں نے عبد العزیز سے، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، کہا: نماز کے لیے تکبیر کہہ دی گئی اور رسول اللہ صلی اللہ علیہ وسلم ایک آدمی سے بہت قریب ہو کر آہستہ آہستہ بات کر رہے تھے۔ (عبد الوارث کی روایت میں ورسول اللہ صلی اللہ علیہ وسلم نجی لرجل کے بجائے ونبی اللہ صلی اللہ علیہ وسلم یناجی الرجل آپ ایک آدمی سے آہستہ آہستہ باتیں کر رہے تھے ہے۔ مفہوم ایک ہے) تو آپ نماز کے لیے کھڑے نہیں ہوئے یہاں تک کہ لوگ (بیٹھےبیٹھے) سو گئے۔"}],[764,"شعبہ نے عبد العزیز بن صہیب سے حدیث بیان کی کہ انہوں نے سیدنا انس بن مالک رضی اللہ عنہ کو کہتے ہوئے سنا : نماز کے لیے تکبیر کہہ دی گئی جبکہ رسول اللہ صلی اللہ علیہ وسلم ایک آدمی سے شرگوشی فرما رہے تھے ۔ آپ اس سے سرگوشی فرماتے رہے یہاں تک کہ آپ کے ساتھی ( بیٹھے بیٹھے ) سو گئے ، اس کےبعد آپ آئے اور انہیں نماز پڑھائی ۔","",{"u2":"شعبہ نے عبد العزیز بن صہیب سے حدیث بیان کی کہ انہوں نے سیدنا انس بن مالک رضی اللہ عنہ کو کہتے ہوئے سنا: نماز کے لیے تکبیر کہہ دی گئی جبکہ رسول اللہ صلی اللہ علیہ وسلم ایک آدمی سے شرگوشی فرما رہے تھے۔ آپ اس سے سرگوشی فرماتے رہے یہاں تک کہ آپ کے ساتھی (بیٹھے بیٹھے) سو گئے، اس کےبعد آپ آئے اور انہیں نماز پڑھائی۔"}],[765,"شعبہ نے قتادہ سے روایت کی ، کہا : میں نے سیدنا انس رضی اللہ عنہ سے سنا ، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ ( بیٹھے بیٹھے ) سو جاتے تھے ، پھر وضو کیے بغیر نماز پڑھ لیتے ۔ ( شعبہ کہتے ہیں : ) میں نے ( قتادہ سے ) پوچھا : آپ نے یہ حدیث انس رضی اللہ عنہ سے سنی ہے؟ انہوں نے کہا : ہاں! اللہ کی قسم","",{"u2":"شعبہ نے قتادہ سے روایت کی، کہا: میں نے سیدنا انس رضی اللہ عنہ سے سنا، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ (بیٹھے بیٹھے) سو جاتے تھے، پھر وضو کیے بغیر نماز پڑھ لیتے۔ (شعبہ کہتے ہیں:) میں نے (قتادہ سے) پوچھا: آپ نے یہ حدیث انس رضی اللہ عنہ سے سنی ہے؟ انہوں نے کہا: ہاں! اللہ کی قسم!"}],[766,"ثابت نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : عشاء کی نماز کے لیے اقامت کہہ دی گئی تو ایک آدمی نے ( رسول اللہ سے ) کہا : میرا ایک کام ہے ، چنانچہ آپ صلی اللہ علیہ وسلم کھڑے ہو کر اس سے سرگوشی کرنے لگے حتیٰ کہ لوگ یا کچھ لوگ ( بیٹھے بیٹھے ) سو گئے ، پھر سب نے نماز پڑھی ۔","",{"u2":"ثابت نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: عشاء کی نماز کے لیے اقامت کہہ دی گئی تو ایک آدمی نے (رسول اللہ سے) کہا: میرا ایک کام ہے، چنانچہ آپ صلی اللہ علیہ وسلم کھڑے ہو کر اس سے سرگوشی کرنے لگے حتیٰ کہ لوگ یا کچھ لوگ (بیٹھے بیٹھے) سو گئے، پھر سب نے نماز پڑھی۔"}],[767,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا : جب مسلمان مدینہ آئے تو وہ اکٹھے ہو جاتے اور نمازوں کے اوقات کا انتظار کرتے ، کوئی اس کا اعلان نہیں کرتا تھا ۔ ایک دن انہوں نے اس کے بارے میں گفتگو کی تو بعض نے کہا : عیسائیوں کے گھنٹے کے مانند ایک گھنٹا لے لو اور بعض نے کہا : یہود کے قرنا جیسا قرنا ، البتہ سیدنا عمر رضی اللہ عنہ نے کہا : تم ایک آدمی ہی کیوں نہیں بھیج دیتے جو نماز کا اعلان کرے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : اے بلال! اٹھو اور نماز کا اعلان کرو ۔ ‘‘","",{"u2":"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: جب مسلمان مدینہ آئے تو وہ اکٹھے ہو جاتے اور نمازوں کے اوقات کا انتظار کرتے، کوئی اس کا اعلان نہیں کرتا تھا۔ ایک دن انہوں نے اس کے بارے میں گفتگو کی تو بعض نے کہا: عیسائیوں کے گھنٹے کے مانند ایک گھنٹا لے لو اور بعض نے کہا: یہود کے قرنا جیسا قرنا، البتہ سیدنا عمر رضی اللہ عنہ نے کہا: تم ایک آدمی ہی کیوں نہیں بھیج دیتے جو نماز کا اعلان کرے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے بلال! اٹھو اور نماز کا اعلان کرو۔‘‘"}],[768,"خلف بن ہشام نے کہا : ہمیں حماد بن زید نے حدیث سنائی ، نیز یحییٰ بن یحییٰ نے کہا : ہمیں اسماعیل بن علیہ نے خبر دی ، ان دونوں ( حماد اور یحییٰ ) نے خالد حذاء سے ، انہوں نے ابو قلابہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : بلال رضی اللہ عنہ کو حکم دیا گیا کہ وہ اذان دہرائیں اور اقامت اکہری کہیں ۔ یحییٰ نے ابن علیہ سے ( بیان کردہ ) اپنی روایت میں یہ اضافہ کیا : میں ( اسماعیل ) نے یہ روایت ایوب کو سنائی تو انہوں نے کہا : ( اذان دہرائیں ) اقامت کے سوا","",{"u2":"خلف بن ہشام نے کہا: ہمیں حماد بن زید نے حدیث سنائی، نیز یحییٰ بن یحییٰ نے کہا: ہمیں اسماعیل بن علیہ نے خبر دی، ان دونوں (حماد اور یحییٰ) نے خالد حذاء سے، انہوں نے ابو قلابہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: بلال رضی اللہ عنہ کو حکم دیا گیا کہ وہ اذان دہرائیں اور اقامت اکہری کہیں۔\nیحییٰ نے ابن علیہ سے (بیان کردہ) اپنی روایت میں یہ اضافہ کیا: میں (اسماعیل) نے یہ روایت ایوب کو سنائی تو انہوں نے کہا: (اذان دہرائیں) اقامت کے سوا"}],[769,"عبد الوہاب ثقفی نے خالد حذاء سے باقی ماندہ سابقہ سند کے ساتھ روایت کی کہ انہوں نے ( صحابہ ) نے ( اس پر ) بات کی کہ کسی ایسی چیز کے ذریعے سے نماز کے وقت کی علامت مقرر کریں جس کو لوگ پہچان لیا کریں ۔ انہوں نے کہا کہ وہ آگ روشن کریں یا ناقوس ( گھنٹی ) بجائیں ، پھر ( آخر کار ) بلال رضی اللہ عنہ کو حکم دیا گیا کہ وہ دہری اذان اور اکہری اقامت کہیں ۔","",{"u2":"عبد الوہاب ثقفی نے خالد حذاء سے باقی ماندہ سابقہ سند کے ساتھ روایت کی کہ انہوں نے (صحابہ) نے (اس پر) بات کی کہ کسی ایسی چیز کے ذریعے سے نماز کے وقت کی علامت مقرر کریں جس کو لوگ پہچان لیا کریں۔ انہوں نے کہا کہ وہ آگ روشن کریں یا ناقوس (گھنٹی) بجائیں، پھر (آخر کار) بلال رضی اللہ عنہ کو حکم دیا گیا کہ وہ دہری اذان اور اکہری اقامت کہیں۔"}],[770,"۔ وہیب نے کہا : ہمیں خالد حذاء نے اسی سند کے ساتھ حدیث بیان کی کہ جب لوگ زیادہ ہو گئے تو انہوں نے گفتگو کی کہ وہ علامت مقرر کریں .... آگے ( عبد الوہاب ) ثقفی کی حدیث کے مانند ہے ، فرق صرف اس قدر ہے کہ اس ( وہیب ) نے ( ينوروا نارا ’’آگ روشن کریں ‘‘ کی جگہ ) يوروا نارا ’’آگ جلائیں ‘‘ کہا ۔","",{"u2":"۔ وہیب نے کہا: ہمیں خالد حذاء نے اسی سند کے ساتھ حدیث بیان کی کہ جب لوگ زیادہ ہو گئے تو انہوں نے گفتگو کی کہ وہ علامت مقرر کریں .... آگے (عبد الوہاب) ثقفی کی حدیث کے مانند ہے، فرق صرف اس قدر ہے کہ اس (وہیب) نے (ینوروا نارا ’’آگ روشن کریں‘‘ کی جگہ) یوروا نارا ’’آگ جلائیں‘‘ کہا۔"}],[771,"۔ ایوب نے ابو قلابہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : بلال رضی اللہ عنہ کو حکم دیا گیا کہ دہری اذان اور اکہری قامت کہیں ۔","",{"u2":"۔ ایوب نے ابو قلابہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: بلال رضی اللہ عنہ کو حکم دیا گیا کہ دہری اذان اور اکہری قامت کہیں۔"}],[772,"۔ ابو غسان مسمعی اور اسحاق بن ابراہیم نے مجھے حدیث بیان کی ، ( کہا : ) ابو غسان نے کہا : ہمیں معاذ نے حدیث سنائی اور اسحاق نے کہا : ہمیں دستوائی ( کپڑے ) والے ہشام کے بیٹے معاذ نے خبر دی ، انہوں ( معاذ ) نے کہا : مجھے میرے والد نے عامر احول سے حدیث سنائی ، انہوں نے سیدنا ابو محذورہ رضی اللہ عنہ سے روایت کی کہ اللہ کے نبی صلی اللہ علیہ وسلم نے انہیں یہ اذان سکھائی : الله أكبر الله أكبر ، أشهد أن لا إله إلا اللہ ، أشهد أن لا إله إلا اللہ ، أشهد أن محمدا رسول اللہ ، أشهد أن محمدا رسول اللہ ، پھر دو بار کہے : أشهد أن لا إله إلا اللہ ، پھر دو بار ، أشهد أن محمدا رسول اللہ ، دو بار حی على الصلوٰة دو بار حي على الفلاح دوبار ۔ اسحاق نے یہ اضافہ کیا : الله أكبر الله أكبر ، لا إله إلا اللہ","",{"u2":"۔ ابو غسان مسمعی اور اسحاق بن ابراہیم نے مجھے حدیث بیان کی، (کہا:) ابو غسان نے کہا: ہمیں معاذ نے حدیث سنائی اور اسحاق نے کہا: ہمیں دستوائی (کپڑے) والے ہشام کے بیٹے معاذ نے خبر دی، انہوں (معاذ) نے کہا: مجھے میرے والد نے عامر احول سے حدیث سنائی، انہوں نے سیدنا ابو محذورہ رضی اللہ عنہ سے روایت کی کہ اللہ کے نبی صلی اللہ علیہ وسلم نے انہیں یہ اذان سکھائی:\nاللہ أکبر اللہ أکبر،أشہد أن لا إلہ إلا اللہ، أشہد أن لا إلہ إلا اللہ، أشہد أن محمدا رسول اللہ، أشہد أن محمدا رسول اللہ، پھر دو بار کہے: أشہد أن لا إلہ إلا اللہ، پھر دو بار، أشہد أن محمدا رسول اللہ، دو بار حی علی الصلوٰۃ دو بار حی علی الفلاح دوبار۔ اسحاق نے یہ اضافہ کیا: اللہ أکبر اللہ أکبر، لا إلہ إلا اللہ"}],[773,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے دو مؤذن تھے ، بلال اور نابینا ابن ام مکتومؓ ۔","",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے دو مؤذن تھے، بلال اور نابینا ابن ام مکتوم رضی اللہ عنہا۔"}],[774,"سیدہ عائشہؓ سے بھی اسی ( سابقہ حدیث ) کے مانند حدیث بیان کی گئی ہے ۔","",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے بھی اسی (سابقہ حدیث) کے مانند حدیث بیان کی گئی ہے۔"}],[775,"محمد بن جعفر نے کہا : ہمیں ہشام نے اپنے والد سے حدیث بیان کی ، انہوں نے سیدہ عائشہؓ سے روایت کی ، انہوں نے کہا : ابن ام مکتوم رسول اللہ صلی اللہ علیہ وسلم کے لیے اذان دیا کرتے تھے ، حالانکہ وہ نابینا تھے ۔","",{"u2":"محمد بن جعفر نے کہا: ہمیں ہشام نے اپنے والد سے حدیث بیان کی، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: ابن ام مکتوم رسول اللہ صلی اللہ علیہ وسلم کے لیے اذان دیا کرتے تھے، حالانکہ وہ نابینا تھے۔"}],[776,"۔ یحییٰ بن عبد اللہ اور سعید بن عبد الرحمن نے ہشام سے اسی سند کے ساتھ اس ( مذکورہ بالا روایت ) کے مانند حدیث بیان کی","",{"u2":"۔ یحییٰ بن عبد اللہ اور سعید بن عبد الرحمن نے ہشام سے اسی سند کے ساتھ اس (مذکورہ بالا روایت) کے مانند حدیث بیان کی"}],[777,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ( دشمن پر ) طلوع فجر کے وقت حملہ کرتے تھے اور اذان کی آواز پر کان لگائے رکھتے تھے ، پھر اگر اذان سن لیتے تو رک جاتے ورنہ حملہ کر دیتے ، ( ایسا ہوا کہ ) آپ نے ایک آدمی کو کہتے ہوئے سنا : الله أكبر الله أكبر تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’فطرت ( اسلام ) پر ہے ۔ ‘‘ پھر اس نے کہا : أشهد أن لا إله إلا اللہ ، أشهد أن لا إله إلا اللہ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’تو آگ سے نکل گیا ۔ ‘‘ اس پر صحابہ کرام رضی اللہ عنہ نے دیکھا تو وہ بکریوں کا چرواہا تھا ۔","",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (دشمن پر) طلوع فجر کے وقت حملہ کرتے تھے اور اذان کی آواز پر کان لگائے رکھتے تھے، پھر اگر اذان سن لیتے تو رک جاتے ورنہ حملہ کر دیتے، (ایسا ہوا کہ) آپ نے ایک آدمی کو کہتے ہوئے سنا: اللہ أکبر اللہ أکبر تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’فطرت (اسلام) پر ہے۔‘‘ پھر اس نے کہا: أشہد أن لا إلہ إلا اللہ، أشہد أن لا إلہ إلا اللہ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو آگ سے نکل گیا۔‘‘ اس پر صحابہ کرام رضی اللہ عنہم نے دیکھا تو وہ بکریوں کا چرواہا تھا۔"}],[778,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم اذان سنو تو جو مؤذن کہتا ہے اسی کی طرح کہو ۔ ‘‘","",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم اذان سنو تو جو مؤذن کہتا ہے اسی کی طرح کہو۔‘‘"}],[779,"۔ سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو سنا ، آپ فرما رہے تھے : ’’جب تم مؤذن کو سنو تو اسی طرح کہو جیسے وہ کہتا ہے ، پھر مجھ پر درود بھیجو کیونکہ جو مجھ پر ایک دفعہ درود بھیجتا ہے ، اللہ تعالیٰ اس کے بدلے میں اس پر دس رحمتیں نازل فرماتا ہے ، پھر اللہ تعالیٰ سے میرے لیے وسیلہ مانگو کیونکہ وہ جنت میں ایک مقام ہے جو اللہ کے بندوں میں سے صرف ایک بندے کو ملے گا اور مجھے امید ہے وہ میں ہوں گا ، چنانچہ جس نے میرے لیے وسیلہ طلب کیا اس کے لیے ( میری ) شفاعت واجب ہو گئی ۔ ‘‘","",{"u2":"۔ سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو سنا، آپ فرما رہے تھے: ’’جب تم مؤذن کو سنو تو اسی طرح کہو جیسے وہ کہتا ہے، پھر مجھ پر درود بھیجو کیونکہ جو مجھ پر ایک دفعہ درود بھیجتا ہے، اللہ تعالیٰ اس کے بدلے میں اس پر دس رحمتیں نازل فرماتا ہے، پھر اللہ تعالیٰ سے میرے لیے وسیلہ مانگو کیونکہ وہ جنت میں ایک مقام ہے جو اللہ کے بندوں میں سے صرف ایک بندے کو ملے گا اور مجھے امید ہے وہ میں ہوں گا، چنانچہ جس نے میرے لیے وسیلہ طلب کیا اس کے لیے (میری) شفاعت واجب ہو گئی۔‘‘"}],[780,"سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب مؤذن الله أكبر ، الله أكبر کہے تو تم میں سے ( ہر ) ایک الله أكبر الله أكبر كہے ، پھر وہ ( مؤذن ) کہے أشهد أن لا إلا اللہ تو وہ بھی کہے : أشهد أن لا إله اللہ پھر ( مؤذن ) أشهد أن محمد رسول اللہ کہے تو وہ بھی أشهد أن محمدا رسول اللہ کہے ، پھر وہ ( مؤذن ) حي على الصلاة کہے تو وہ لا حول ولا قوة إلا باللہ کہے ، پھر مؤذن حي على الفلاح کہے ، تو وہ لا حول ولا قوة إلا باللہ کہے ، پھر ( مؤذن ) الله أكبر الله أكبر کہے ، پھر ( مؤذن ) لا إله إلا اللہ کہے تو وہ بھی اپنے دل سے لا إله إلا اللہ کہے تو وہ جنت میں داخل ہو گا ۔ ‘‘","",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب مؤذن اللہ أکبر، اللہ أکبر کہے تو تم میں سے (ہر) ایک اللہ أکبر اللہ أکبر کہے، پھر وہ (مؤذن) کہے أشہد أن لا إلا اللہ تو وہ بھی کہے: أشہد أن لا إلہ اللہ پھر (مؤذن) أشہد أن محمد رسول اللہ کہے تو وہ بھی أشہد أن محمدا رسول اللہ کہے، پھر وہ (مؤذن) حی علی الصلاۃ کہے تو وہ لا حول ولا قوۃ إلا باللہ کہے، پھر مؤذن حی علی الفلاح کہے، تو وہ لا حول ولا قوۃ إلا باللہ کہے، پھر (مؤذن) اللہ أکبر اللہ أکبر کہے، پھر (مؤذن) لا إلہ إلا اللہ کہے تو وہ بھی اپنے دل سے لا إلہ إلا اللہ کہے تو وہ جنت میں داخل ہو گا۔‘‘"}],[781,"۔ محمد بن رمح اور قتیبہ بن سعید کی دو الگ الگ سندوں سے سیدنا سعد بن ابی وقاص رضی اللہ عنہ سے روایت ہے ، انہوں نے رسول اللہ سے روایت کی کہ آپ نے فرمایا : ’’جس نے مؤذن کی آواز سنتے ہوئے یہ کہا : أشهد أن لا إله إلا اللہ وحده لا شريك له ’’میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں ، وہ اکیلا ہے ، اس کا کوئی شریک نہیں ۔ ‘‘ وأن محمدا عبده ورسوله ’’اور محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں ۔ ‘‘ رضيت بالله ربا وبمحمد رسولا وبالإسلام دينا ’’ میں اللہ کے رب ہونے پر اور محمد صلی اللہ علیہ وسلم کے رسول ہونے پر اور اسلام کے دین ہونے پر راضی ہوں ۔ ‘‘ تو اس کے گناہ بخش دیے جائیں گے ۔ ابن رمح نے اپنی روایت میں کہا : جس نے مؤذن کی آواز سنتے ہوئے یہ کہا : وأنا أشهد اور قتیبہ نے وأنا کا لفظ بیان نہیں ۔","",{"u2":"۔ محمد بن رمح اور قتیبہ بن سعید کی دو الگ الگ سندوں سے سیدنا سعد بن ابی وقاص رضی اللہ عنہ سے روایت ہے، انہوں نے رسول اللہ سے روایت کی کہ آپ نے فرمایا: ’’جس نے مؤذن کی آواز سنتے ہوئے یہ کہا: أشہد أن لا إلہ إلا اللہ وحدہ لا شریک لہ ’’میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔‘‘ وأن محمدا عبدہ ورسولہ ’’اور محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں۔‘‘ رضیت باللہ ربا وبمحمد رسولا وبالإسلام دینا ’’ میں اللہ کے رب ہونے پر اور محمد صلی اللہ علیہ وسلم کے رسول ہونے پر اور اسلام کے دین ہونے پر راضی ہوں۔‘‘ تو اس کے گناہ بخش دیے جائیں گے۔\nابن رمح نے اپنی روایت میں کہا: جس نے مؤذن کی آواز سنتے ہوئے یہ کہا: وأنا أشہد اور قتیبہ نے وأنا کا لفظ بیان نہیں۔"}],[782,"عبدہ نے طلحہ بن یحییٰ ( بن طلحہ بن عبید اللہ ) سے اور انہوں نے اپنے چچا ( عیسیٰ بن طلحہ بن عبید اللہ ) سے روایت کی ، انہوں نے کہا : میں معاویہ بن ابی سفیان رضی اللہ عنہ کے پاس تھا ، ان کے پاس مؤذن انہیں نماز کے لیے بلانے آیا ۔ تو معاویہ رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرماتے تھے : قیامت کے دن مؤذن ، لوگوں میں سب سے زیادہ لمبی گردنوں والے ہوں گے ۔ ‘‘","",{"u2":"عبدہ نے طلحہ بن یحییٰ (بن طلحہ بن عبید اللہ) سے اور انہوں نے اپنے چچا (عیسیٰ بن طلحہ بن عبید اللہ) سے روایت کی، انہوں نے کہا: میں معاویہ بن ابی سفیان رضی اللہ عنہ کے پاس تھا، ان کے پاس مؤذن انہیں نماز کے لیے بلانے آیا۔ تو معاویہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرماتے تھے: قیامت کے دن مؤذن، لوگوں میں سب سے زیادہ لمبی گردنوں والے ہوں گے۔‘‘"}],[783,"سفیان نے طلحہ بن یحییٰ سے اور انہوں نے ( اپنے چچا ) عیسیٰ بن طلحہ سے روایت کی ، کہا : میں نے معاویہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : .......... ( آگے ) سابقہ روایت کی مانند ہے ۔","",{"u2":"سفیان نے طلحہ بن یحییٰ سے اور انہوں نے (اپنے چچا) عیسیٰ بن طلحہ سے روایت کی، کہا: میں نے معاویہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: .......... (آگے) سابقہ روایت کی مانند ہے۔"}],[784,"۔ جریر نے اعمش سے ، انہوں نے ابو سفیان ( طلحہ بن نافع ) سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، کہا : میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : بلاشبہ شیطان جب نماز کی پکار ( اذان ) سنتا ہے تو ( بھاگ کر ) چلا جاتا ہے یہاں تک کہ روحاء کے مقام پر پہنچ جاتا ہے ۔ ‘‘ سلیمان ( اعمش ) نے کہا : میں نے ان ( اپنے استاد ابو سفیان طلحہ بن نافع ) سے روحاء کے بارے میں پوچھا تو انہوں نے کہا : یہ مدینہ سے چھتیس میل ( کے فاصلے ) پر ہے ۔","",{"u2":"۔ جریر نے اعمش سے، انہوں نے ابو سفیان (طلحہ بن نافع) سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، کہا: میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: بلاشبہ شیطان جب نماز کی پکار (اذان) سنتا ہے تو (بھاگ کر) چلا جاتا ہے یہاں تک کہ روحاء کے مقام پر پہنچ جاتا ہے۔‘‘\nسلیمان (اعمش) نے کہا: میں نے ان (اپنے استاد ابو سفیان طلحہ بن نافع) سے روحاء کے بارے میں پوچھا تو انہوں نے کہا: یہ مدینہ سے چھتیس میل (کے فاصلے) پر ہے۔"}],[785,"۔ ابو معاویہ نے اعمش سے اسی سند کے ساتھ یہی روایت بیان کی ۔","",{"u2":"۔ ابو معاویہ نے اعمش سے اسی سند کے ساتھ یہی روایت بیان کی۔"}],[786,"۔ اعمش نے ابو صالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : شیطان جب نماز کے لیے پکار ( کی آواز ) سنتا ہے تو گوز مارتا ہوا بھاگتا ہے تاکہ مؤذن کی آواز نہ سن سکے ، پھر جب مؤذن خاموش ہو جاتا ہے تو واپس آ تا ہے اور ( نمازیوں کے دلوں میں ) وسوسہ پیدا ےکرتا ہے ، پھر جب اقامت سنتا ہے تو چلا جاتا ہے تاکہ اس کی آواز نہ سنے ، پھر جب وہ خاموش ہو جاتا ہے تو واپس آتا ہے اور ( لوگوں کے دلوں میں ) وسوسہ ڈالتا ہے ۔ ‘‘","",{"u2":"۔ اعمش نے ابو صالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: شیطان جب نماز کے لیے پکار (کی آواز) سنتا ہے تو گوز مارتا ہوا بھاگتا ہے تاکہ مؤذن کی آواز نہ سن سکے، پھر جب مؤذن خاموش ہو جاتا ہے تو واپس آ تا ہے اور (نمازیوں کے دلوں میں) وسوسہ پیدا ےکرتا ہے، پھر جب اقامت سنتا ہے تو چلا جاتا ہے تاکہ اس کی آواز نہ سنے، پھر جب وہ خاموش ہو جاتا ہے تو واپس آتا ہے اور (لوگوں کے دلوں میں) وسوسہ ڈالتا ہے۔‘‘"}],[787,"خالد بن عبد اللہ نے سہیل سے ، انہوں نے اپنے والد ( ابو صالح السمان ) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب مؤذن اذان کہتا ہے تو شیطان پیٹھ پھیر کر گوز مارتا ہوا جاتا ہے ۔ ‘‘","",{"u2":"خالد بن عبد اللہ نے سہیل سے، انہوں نے اپنے والد (ابو صالح السمان) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب مؤذن اذان کہتا ہے تو شیطان پیٹھ پھیر کر گوز مارتا ہوا جاتا ہے۔‘‘"}],[788,"روح نے سہیل سے روایت کی ، انہوں نے کہا : میرے والد نے مجھے بنو حارثہ کی طرف بھیجا ، کہا : میرے والد نے مجھے بنو حارثہ کی طرف بھیجا ، کہا : میرے ساتھ ہمارا ایک لڑکا ( خادم یا ہمارا ایک ساتھی بھی تھا ) اس کو کسی آواز دینے والے نے باغ سے اس کا نام لے کر آواز دی ۔ کہا : جو ( لڑکا ) میرے ساتھ تھا اس نے باغ کے اندر جھانکا تو اسے کچھ نظر نہ آیا ، چنانچہ میں نے یہ ( واقعہ ) اپنے والد کو بتایا تو انہوں نے کہا : اگر مجھے معلوم ہوتا کہ تم اس واقعے سے دوچار ہو گے تو میں تمہیں نہ بھیجتا لیکن ( آئندہ ) تم اگر کوئی آواز سنو تو نماز کی اذان دو کیونکہ میں نے ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرتے تھے کہ آپ نے فرمایا : ’’جب نماز کے لیے پکارا جاتا ہے تو شیطان پیٹھ پھیر کر گوز مارتا ہوا بھاگ جاتا ہے ۔ ‘‘","",{"u2":"روح نے سہیل سے روایت کی، انہوں نے کہا: میرے والد نے مجھے بنو حارثہ کی طرف بھیجا، کہا: میرے والد نے مجھے بنو حارثہ کی طرف بھیجا، کہا: میرے ساتھ ہمارا ایک لڑکا (خادم یا ہمارا ایک ساتھی بھی تھا) اس کو کسی آواز دینے والے نے باغ سے اس کا نام لے کر آواز دی۔ کہا: جو (لڑکا) میرے ساتھ تھا اس نے باغ کے اندر جھانکا تو اسے کچھ نظر نہ آیا، چنانچہ میں نے یہ (واقعہ) اپنے والد کو بتایا تو انہوں نے کہا: اگر مجھے معلوم ہوتا کہ تم اس واقعے سے دوچار ہو گے تو میں تمہیں نہ بھیجتا لیکن (آئندہ) تم اگر کوئی آواز سنو تو نماز کی اذان دو کیونکہ میں نے ابو ہریرہ رضی اللہ عنہ سے سنا، وہ رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کرتے تھے کہ آپ نے فرمایا: ’’جب نماز کے لیے پکارا جاتا ہے تو شیطان پیٹھ پھیر کر گوز مارتا ہوا بھاگ جاتا ہے۔‘‘"}],[789,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کہ بلاشبہ نبی صلی اللہ علیہ وسلم نے فرمایا : ’’جب نماز کے لیے اذان دی جاتی ہے تو شیطان گوز مارتا ہوا پیچھا بھاگ جاتا ہے تاکہ اذان نہ سنے ، چنانچہ جب اذان پوری کر دی جاتی ہے تو آ جاتا ہے حتیٰ کہ جب نماز کے لیے تکبیر کہی جاتی ہے تو ( پھر ) پیٹھ پھیر کر بھاگ جاتا ہے ، یہاں تک کہ جب تکبیر ختم ہو جاتی ہے تو آ جاتا ہے تاکہ انسان کے دل میں وسوسہ ڈالے ۔ اسے کہتا ہے : فلاں چیز کو یاد کرو ، فلاں چیز کو یاد کرو ، وہ چیزیں جو اسے پہلے یاد نہیں ہوتیں ، یہاں تک کہ آدمی کی یہ حالت ہو جاتی ہے کہ اس کو پتہ ہی نہیں چلتا اس نے کتنی نماز پڑھی ہے ۔ ‘‘","",{"u2":"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کہ بلاشبہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب نماز کے لیے اذان دی جاتی ہے تو شیطان گوز مارتا ہوا پیچھا بھاگ جاتا ہے تاکہ اذان نہ سنے، چنانچہ جب اذان پوری کر دی جاتی ہے تو آ جاتا ہے حتیٰ کہ جب نماز کے لیے تکبیر کہی جاتی ہے تو (پھر) پیٹھ پھیر کر بھاگ جاتا ہے، یہاں تک کہ جب تکبیر ختم ہو جاتی ہے تو آ جاتا ہے تاکہ انسان کے دل میں وسوسہ ڈالے۔ اسے کہتا ہے: فلاں چیز کو یاد کرو، فلاں چیز کو یاد کرو، وہ چیزیں جو اسے پہلے یاد نہیں ہوتیں، یہاں تک کہ آدمی کی یہ حالت ہو جاتی ہے کہ اس کو پتہ ہی نہیں چلتا اس نے کتنی نماز پڑھی ہے۔‘‘"}],[790,"ہمام بن منبہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے مذکورہ بالا روایت کے مانند بیان کیا ، مگر انہوں نے ( ما يدري كم صلى کے بجائے ) إن يدري كيف صلى ’’وہ نہیں جانتا کیسے نماز پڑھی ‘‘ کہا ۔"],[791,"۔ سفیان بن عیینہ نے زہری سے ، انہوں نے سالم سے اور انہوں نے اپنے والد ( عبد اللہ بن عمرؓ ) سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا : جب آپ نماز شروع کرتے تو اپنے دونوں ہاتھ اٹھاتے حتیٰ کہ انہیں کندھوں کے برابر لے آتے اور رکوع سے پہلے اور ( اس وقت بھی ) جب رکوع سے سر اٹھاتے ۔ آپ دو سجدوں کے درمیان انہیں نہ اٹھاتے تھے ۔","",{"u2":"۔ سفیان بن عیینہ نے زہری سے، انہوں نے سالم سے اور انہوں نے اپنے والد (عبد اللہ بن عمر رضی اللہ عنہ) سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا: جب آپ نماز شروع کرتے تو اپنے دونوں ہاتھ اٹھاتے حتیٰ کہ انہیں کندھوں کے برابر لے آتے اور رکوع سے پہلے اور (اس وقت بھی) جب رکوع سے سر اٹھاتے۔ آپ دو سجدوں کے درمیان انہیں نہ اٹھاتے تھے۔"}],[792,"ابن جریج نے ابن شہاب سے اور انہوں نے سالم بن عبد اللہ سے روایت کی کہ سیدنا ابن عمرؓ نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو اپنے دونوں ہاتھ بلند کرتے حتیٰ کہ آپ کے کندھوں کے سامنے آ جاتے ، پھر اللہ اکبر کہتے ، پھر جب رکوع کرنا چاہتے تو یہی کہتے اور جب رکوع سے سر اٹھاتے تو بھی ایسا کرتے اور جب سجدے سے اپنا سر اٹھاتے تو ایسا نہ کرتے تھے ۔","",{"u2":"ابن جریج نے ابن شہاب سے اور انہوں نے سالم بن عبد اللہ سے روایت کی کہ سیدنا ابن عمر رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو اپنے دونوں ہاتھ بلند کرتے حتیٰ کہ آپ کے کندھوں کے سامنے آ جاتے، پھر اللہ اکبر کہتے، پھر جب رکوع کرنا چاہتے تو یہی کہتے اور جب رکوع سے سر اٹھاتے تو بھی ایسا کرتے اور جب سجدے سے اپنا سر اٹھاتے توایسا نہ کرتے تھے۔"}],[793,"عقیل اور یونس دونوں نے اسی طرح روایت کی جس طرح ابن جریج نے کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوتے تو دونوں ہاتھ اٹھاتے ، پھر تکبیر کرہے ۔ ( انہوں نے بحذو منكبيه کے بجائے حذو منكبيه کہا ، دونوں کا مفہوم ایک ہے ۔)","",{"u2":"عقیل اور یونس دونوں نے اسی طرح روایت کی جس طرح ابن جریج نے کی کہ جب رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوتے تو دونوں ہاتھ اٹھاتے، پھر تکبیر کرہے۔ (انہوں نے بحذو منکبیہ کے بجائے حذو منکبیہ کہا، دونوں کا مفہوم ایک ہے۔)"}],[794,"ابو قلابہ سے روایت ہے کہ انہوں نے سیدنا مالک بن حویرث رضی اللہ عنہ کو دیکھا ، جب وہ نماز پڑھتے تو اللہ اکبر کہت پھر اپنے دونوں ہاتھ اٹھاتے اور جب رکوع کرنا چاہتے تو اپنے دونوں ہاتھ اٹھاتے اور جب رکوع سے اپنا سر اٹھاتے تو اپنے دونوں ہاتھ اٹھاتے اور انہوں نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کیا کرتے تھے ۔","",{"u2":"ابو قلابہ سے روایت ہے کہ انہوں نے سیدنا مالک بن حویرث رضی اللہ عنہ کو دیکھا، جب وہ نماز پڑھتے تو اللہ اکبر کہت پھر اپنے دونوں ہاتھ اٹھاتے اور جب رکوع کرنا چاہتے تو اپنے دونوں ہاتھ اٹھاتے اور جب رکوع سے اپنا سر اٹھاتے تو اپنے دونوں ہاتھ اٹھاتے اور انہوں نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کیا کرتے تھے۔"}],[795,"۔ ابوعوانہ نے قتادہ سے ، انہوں نے نصر بن عاصم سے اور انہوں نے سیدنا مالک بن حویرث رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب اللہ اکبر کہتے تو اپنے دونوں ہاتھ بلند کرتے یہاں تک کہ انہیں اپنے کانوں کے برابر لے جاتے اور جب رکوع کرتے تو ( پھر ) اپنے دونوں ہاتھ بلند کرتے یہاں تک کہ انہیں اپنے کانوں کے برابر لے جاتے اور جب رکوع سے اپنا سر اٹھاتے تو سمع اللہ لمن حمده کہتے اور ایسا ہی کرتے ۔","",{"u2":"۔ ابوعوانہ نے قتادہ سے، انہوں نے نصر بن عاصم سے اور انہوں نے سیدنا مالک بن حویرث رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب اللہ اکبر کہتے تو اپنے دونوں ہاتھ بلند کرتے یہاں تک کہ انہیں اپنے کانوں کے برابر لے جاتے اور جب رکوع کرتے تو (پھر) اپنے دونوں ہاتھ بلند کرتے یہاں تک کہ انہیں اپنے کانوں کے برابر لے جاتے اور جب رکوع سے اپنا سر اٹھاتے تو سمع اللہ لمن حمدہ کہتے اور ایسا ہی کرتے۔"}],[796,"قتادہ سے ( ابو عوانہ کے بجائے ) سعید نے باقی ماندہ سے اسی سند کے ساتھ روایت کی کہ انہوں نے ( مالک بن حویرث رضی اللہ عنہ ) نے اللہ کے نبی صلی اللہ علیہ وسلم کو دیکھا اور ( سعید نے ) کہا : یہاں تک کہ دونوں ہاتھ اپنے دونوں کانوں کے کناروں کے سامنے لے جاتے ۔",""],[797,"ابو سلمہ بن عبد الرحمن سے روایت ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ انہیں نماز پڑھا رہے تھے تو جب بھی وہ جھکتے اور ( سر اور جسم کو اوپر ) اٹھاتے تو اللہ اکبر کہتے ، پھر جب سلام پھیرا تو کہا : اللہ کی قسم! میں نماز میں تم سب کی نسبت رسول اللہ صلی اللہ علیہ وسلم سے زیادہ مشابہت رکھتا ہوں ۔","",{"u2":"ابو سلمہ بن عبد الرحمن سے روایت ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ انہیں نماز پڑھا رہے تھے تو جب بھی وہ جھکتے اور (سر اور جسم کو اوپر) اٹھاتے تو اللہ اکبر کہتے، پھر جب سلام پھیرا تو کہا: اللہ کی قسم! میں نماز میں تم سب کی نسبت رسول اللہ صلی اللہ علیہ وسلم سے زیادہ مشابہت رکھتا ہوں۔"}],[798,"ہمیں ابن جریج نے خبر دی کہا : مجھے ابن شہاب نے ابو بکر بن عبد الرحمن سے روایت بیان کی ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو کھڑے ہوتے ہوئے تکبیر کہتے ، پھر رکوع کرتے ہوئے تکبیر کہتے ، پھر جب رکوع سے کمر اٹھاتے تو سمع اللہ لمن حمده کہتے ، پھر قیام کی حالت میں ربنا ولك الحمد کہتے ، پھر جب سجدہ کرنے کے لیے جھکتے تو تکبیر کہتے ، پھر جب اپنا سر اٹھاتے تو تکبیر کہتے ، پھر ( دوسرا ) سجدہ کرتے وقت تکبیر کہتے ، پھر جب ( سجدے سے ) اپنا سر اٹھاتے تو تکبیر کہتے ، آپ پوری نماز میں اسی طرح کرتے یہاں تک کہ اس کو مکمل کر لیتے اور جب دو رکعتوں سے بیٹھنے کے بعد اٹھتے تو ( اس وقت بھی ) تکبیر کہے ۔ پھر ابو ہریرہ رضی اللہ عنہ کہتے : میں نماز میں تم سب کی نسبت رسول اللہ صلی اللہ علیہ وسلم کے ساتھ زیادہ مشابہ ہوں ۔","",{"u2":"ہمیں ابن جریج نے خبر دی کہا: مجھے ابن شہاب نے ابو بکر بن عبد الرحمن سے روایت بیان کی، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو کھڑے ہوتے ہوئے تکبیر کہتے، پھر رکوع کرتے ہوئے تکبیر کہتے، پھر جب رکوع سے کمر اٹھاتے تو سمع اللہ لمن حمدہ کہتے، پھر قیام کی حالت میں ربنا ولک الحمد کہتے، پھر جب سجدہ کرنے کے لیے جھکتے تو تکبیر کہتے، پھر جب اپنا سر اٹھاتے تو تکبیر کہتے، پھر (دوسرا) سجدہ کرتے وقت تکبیر کہتے، پھر جب (سجدے سے) اپنا سر اٹھاتے تو تکبیر کہتے، آپ پوری نماز میں اسی طرح کرتے یہاں تک کہ اس کو مکمل کر لیتے اور جب دو رکعتوں سے بیٹھنے کے بعد اٹھتے تو (اس وقت بھی) تکبیر کہے۔\nپھر ابو ہریرہ رضی اللہ عنہ کہتے: میں نماز میں تم سب کی نسبت رسول اللہ صلی اللہ علیہ وسلم کے ساتھ زیادہ مشابہ ہوں۔"}],[799,"عقیل نے ابن شہاب سے روایت کی ، کہا : مجھے ابو بکر بن عبد الرحمن بن حارث نے بتایا کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو کھڑے ہوتے وقت تکبیر کہتے ...... آگے ابن جریج کی حدیث کی طرح ہے اور ( عقیل نے ) ابو ہریرہ رضی اللہ عنہ کا یہ قول کہ میں نماز میں تم سب کی نسبت رسول اللہ صلی اللہ علیہ وسلم سے زیادہ مشابہ ہوں ، بیان نہیں کیا ۔","",{"u2":"عقیل نے ابن شہاب سے روایت کی، کہا: مجھے ابو بکر بن عبد الرحمن بن حارث نے بتایا کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو کھڑے ہوتے وقت تکبیر کہتے ...... آگے ابن جریج کی حدیث کی طرح ہے اور (عقیل نے) ابو ہریرہ رضی اللہ عنہ کا یہ قول کہ میں نماز میں تم سب کی نسبت رسول اللہ صلی اللہ علیہ وسلم سے زیادہ مشابہ ہوں، بیان نہیں کیا۔"}],[800,"۔ یونس نے ابن شہاب سے خبر دی ، کہا : مجھے ابو سلمہ بن عبد الرحمن نے بتایا کہ سیدنا ابو ہریرہ رضی اللہ عنہ کو جب مروان مدینہ میں اپنا نائب بنا کر جاتا تو جب وہ فرض نماز کے لیے کھڑے ہوتے ، تکبیر کہتے ....... اس کے بعد ( یونس نے ) ابن جریج کی حدیث کے مانند بیان کیا ۔ ان ( یونس ) کی حدیث میں ( یہ اضافہ ) ہے کہ جب وہ نماز پوری کر لیتے اور سلام پھیرتے تو مسجد والوں کی طرف منہ کرتے ( اور ) کہتے : اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں نماز میں تم سب سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کے مشابہ ہوں ۔","",{"u2":"۔ یونس نے ابن شہاب سے خبر دی، کہا: مجھے ابو سلمہ بن عبد الرحمن نے بتایا کہ سیدنا ابو ہریرہ رضی اللہ عنہ کو جب مروان مدینہ میں اپنا نائب بنا کر جاتا تو جب وہ فرض نماز کے لیے کھڑے ہوتے، تکبیر کہتے ....... اس کے بعد (یونس نے) ابن جریج کی حدیث کے مانند بیان کیا۔ ان (یونس) کی حدیث میں (یہ اضافہ) ہے کہ جب وہ نماز پوری کر لیتے اور سلام پھیرتے تو مسجد والوں کی طرف منہ کرتے (اور) کہتے: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں نماز میں تم سب سے زیادہ رسو ل اللہ صلی اللہ علیہ وسلم کے مشابہ ہوں۔"}],[801,"یحییٰ بن ابی کثیر نے ابو سلمہ سے روایت کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نماز میں جب بھی ( سر ) اٹھاتے اور جھکاتے ، تکبیر کہتے ، اس پر ہم نے کہا : ابو ہریرہ رضی اللہ عنہ ! یہ تکبیر کیا ہے؟ انہوں نے کہا : یقیناً یہی رسول اللہ صلی اللہ علیہ وسلم کی نماز ہے ۔","",{"u2":"یحییٰ بن ابی کثیر نے ابو سلمہ سے روایت کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نماز میں جب بھی (سر) اٹھاتے اور جھکاتے، تکبیر کہتے، اس پر ہم نے کہا: ابو ہریرہ رضی اللہ عنہ! یہ تکبیر کیا ہے؟ انہوں نے کہا: یقیناً یہی رسول اللہ صلی اللہ علیہ وسلم کی نماز ہے۔"}],[802,"سہیل کے والد ابو صالح نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ وہ جب بھی ( نماز میں سر ) جھکاتے اور اٹھاتے تو تکبیر کہتے اور بتاتے کہ رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کیا کرتے تھے ۔","",{"u2":"سہیل کے والد ابو صالح نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ وہ جب بھی (نماز میں سر) جھکاتے اور اٹھاتے تو تکبیر کہتے اور بتاتے کہ رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کیا کرتے تھے۔"}],[803,"۔ مطرف سے روایت ہے ، انہوں نے کہا : میں نے اور عمران بن حصین رضی اللہ عنہ نے علی بن ابی طالب رضی اللہ عنہ کی اقتدا میں نماز پڑھی ۔ جب وہ سجدہ کرتے تو تکبیر کہتے اور جب اپنا سر اٹھاتے تو تکبیر کہتے اور جب دو رکعتوں کے بعد کھڑے ہوتے تو تکبیر کہتے ، جب ہم نماز سے فارغ ہوئے تو عمران رضی اللہ عنہ نے میرا ہاتھ پکڑا ، پھر کہا : انہوں نے ہمیں محمد صلی اللہ علیہ وسلم کی نماز پڑھائی ہے یا کہا : انہوں نے مجھے محمد صلی اللہ علیہ وسلم کی نماز یاد دلا دی ہے ۔","",{"u2":"۔ مطرف سے روایت ہے، انہوں نے کہا: میں نے اور عمران بن حصین رضی اللہ عنہ نے علی بن ابی طالب رضی اللہ عنہ کی اقتدا میں نماز پڑھی۔ جب وہ سجدہ کرتے تو تکبیر کہتے اور جب اپنا سر اٹھاتے تو تکبیر کہتے اور جب دو رکعتوں کے بعد کھڑے ہوتے تو تکبیر کہتے، جب ہم نماز سے فارغ ہوئے تو عمران رضی اللہ عنہ نے میرا ہاتھ پکڑا، پھر کہا: انہوں نے ہمیں محمد صلی اللہ علیہ وسلم کی نماز پڑھائی ہے یا کہا: انہوں نے مجھے محمد صلی اللہ علیہ وسلم کی نماز یاد دلا دی ہے۔"}],[804,"سفیان بن عیینہ نے ابن شہاب زہری سے ، انہوں نے محمود بن ربیع سے اور انہوں نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت کی ، وہ اس بات کی نسبت نبی صلی اللہ علیہ وسلم کی طرف کرتے تھے ( کہ آپ صلی اللہ علیہ وسلم نے فرمایا : ) ’’اس شخص کی کوئی نماز نہیں جس نے فاتحہ الکتاب نہ پڑھی ۔ ‘‘","",{"u2":"سفیان بن عیینہ نے ابن شہاب زہری سے، انہوں نے محمود بن ربیع سے اور انہوں نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت کی، وہ اس بات کی نسبت نبی صلی اللہ علیہ وسلم کی طرف کرتے تھے (کہ آپ صلی اللہ علیہ وسلم نے فرمایا:) ’’اس شخص کی کوئی نماز نہیں جس نے فاتحہ الکتاب نہ پڑھی۔‘‘"}],[805,"یونس نے ابن شہاب سے روایت کی ، کہا : مجھے محمود بن ربیع نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے خبر دی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’اس شخص کی کوئی نماز نہیں جس نے ام القریٰ ( فاتحہ ) نہیں پڑھی ۔ ‘‘","",{"u2":"یونس نے ابن شہاب سے روایت کی، کہا: مجھے محمود بن ربیع نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے خبر دی، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس شخص کی کوئی نماز نہیں جس نے ام القریٰ (فاتحہ) نہیں پڑھی۔‘‘"}],[806,"صالح نے ابن شہاب سے روایت کی کہ سیدنا محمود بن ربیع رضی اللہ عنہ نے ، جن کے چہرے پر رسول اللہ صلی اللہ علیہ وسلم نے ان کے کنویں سے کلی کر کے پانی کا چھینٹا دیا تھا ، انہیں بتایا کہ سیدنا عبادہ بن صامت رضی اللہ عنہ نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا رضی اللہ عنہ ’’جس نے ام القریٰ کی قراءت نہ کی ، اس کی کوئی نماز نہیں ۔ ‘‘","",{"u2":"صالح نے ابن شہاب سے روایت کی کہ سیدہ محمود بن ربیع رضی اللہ عنہا نے، جن کے چہرے پر رسول اللہ صلی اللہ علیہ وسلم نے ان کے کنویں سے کلی کر کے پانی کا چھینٹا دیا تھا، انہیں بتایا کہ سیدنا عبادہ بن صامت رضی اللہ عنہ نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا علیہ السلام’’جس نے ام القریٰ کی قراءت نہ کی، اس کی کوئی نماز نہیں۔‘‘"}],[807,"۔ زہری کے ایک اور شاگرد معمر نے اسی سند کے ساتھ اسی کے مانند روایت کی اور یہ اضافہ کیا : ’’ ( فاتحہ ) اور اس کے بعد ( قرآن کا کچھ حصہ ۔ ) ‘‘","",{"u2":"۔ زہری کے ایک اور شاگرد معمر نے اسی سند کے ساتھ اسی کے مانند روایت کی اور یہ اضافہ کیا: ’’(فاتحہ) اور اس کے بعد (قرآن کا کچھ حصہ۔)‘‘"}],[808,"سفیان بن عیینہ نے علاء بن عبد الرحمن سے خبر دی ، انہوں نے اپنے والد سے ، انہوں سیدنا ابو ہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : ’’جس نے کوئی نماز پڑھی اور اس میں ام القریٰ کی قراءت نہ کی تو ناقص ہے ۔ ‘‘ تین مرتبہ فرمایا ، یعنی پوری ہی نہیں ۔ ابو ہریرہ رضی اللہ عنہ سے کہا گیا : ہم امام کے پیچھے ہوتے ہیں ۔ انہوں نے کہا : اس کو اپنے دل میں پڑھ لو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : ’’اللہ تعالیٰ نے فرمایا : میں نے نماز اپنے اور اپنے بندے کے درمیان آدھی آدھی تقسیم کی ہے اور میرے بندے نے جو مانگا ، اس کا ہے جب بندہ ﴿الحمد لله رب العالمين﴾ ’’سب تعریف اللہ ہی کے لیے جو جہانوں کا رب ہے ۔ ‘‘ کہتا ہے تو اللہ تعالیٰ فرماتا ہے : میرے بندے نے میری تعریف کی ۔ اور جب وہ کہتا ہے : ﴿الرحمن الرحيم﴾ ’’سب سے زیادہ رحم کرنے والا ہمیشہ مہربانی کرنے والا ۔ ‘‘ تو اللہ تعالیٰ فرماتا ہے : میرے بندے نے میری ثنا بیان کی ۔ پھر جب وہ کہتا ہے : ﴿ مالك يوم الدين﴾ ’’جزا کے دن کا مالک ۔ ‘‘ تو ( اللہ ) فرماتا ہے : میرے بندے نے میری بزرگی بیان کی ۔ اور ایک دفعہ فرمایا : میرے بندے نے ( اپنے معاملات ) میرے سپرد کر دیے ۔ پھر جب وہ کہتا ہے : ﴿إياك نعبد وإياك نستعين﴾ ’’ہم تیری ہی بندگی کرتے اور تجھ ہی سے مدد چاہتے ہیں ۔ ‘‘ تو ( اللہ ) فرماتا ہے : یہ ( حصہ ) میرے اور میرے بندے کے درمیان ہے اور میرے بندے نے جو مانگا ، اس کا ہے اور جب وہ کہتا ہے : ﴿إهدنا الصراط المستقيم صراط الذين أنعمت عليهم غير المغضوب عليهم والا الضالين﴾ ’’ہمیں راہ راست دکھا ، ان لوگوں کی راہ جن پر تو نے انعام فرمایا ، نہ غضب کیے گئے لوگوں کی ہو اور نہ گمراہوں کی ۔ ‘‘ تو ( اللہ ) فرماتا ہے : یہ میرے بندے کے لیے ہے اور میرے بندے کا ہے جو اس نے مانگا ۔ سفیان نے کہا : مجھے یہ روایت علاء بن عبد الرحمن بن یعقوب نے سنائی ، میں ان کے پاس گیا ، وہ گھر میں بیمار تھے ۔ میں نے ان سے اس حدیث کے بارے میں سوال کیا ( تو انہوں نے مجھے یہ حدیث سنائی ۔)","",{"u2":"سفیان بن عیینہ نے علاء بن عبد الرحمن سے خبر دی، انہوں نے اپنے والد سے، انہوں سیدنا ابو ہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: ’’جس نے کوئی نماز پڑھی اور اس میں ام القریٰ کی قراءت نہ کی تو ناقص ہے۔‘‘ تین مرتبہ فرمایا، یعنی پوری ہی نہیں۔ ابو ہریرہ رضی اللہ عنہ سے کہا گیا: ہم امام کے پیچھے ہوتے ہیں۔ انہوں نے کہا: اس کو اپنے دل میں پڑھ لو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’اللہ تعالیٰ نے فرمایا: میں نے نماز اپنے اور اپنے بندے کے درمیان آدھی آدھی تقسیم کی ہے اور میرے بندے نے جو مانگا، اس کا ہے جب بندہ ﴿الحمد للہ رب العالمین﴾ ’’سب تعریف اللہ ہی کے لیے جو جہانوں کا رب ہے۔‘‘ کہتا ہے تو اللہ تعالیٰ فرماتا ہے: میرے بندے نے میری تعریف کی۔ اور جب وہ کہتا ہے: ﴿الرحمن الرحیم﴾ ’’سب سے زیادہ رحم کرنے والا ہمیشہ مہربانی کرنے والا۔‘‘ تو اللہ تعالیٰ فرماتا ہے: میرے بندے نے میری ثنا بیان کی۔ پھر جب وہ کہتا ہے: ﴿ مالک یوم الدین﴾ ’’جزا کے دن کا مالک۔‘‘ تو (اللہ) فرماتا ہے: میرے بندے نے میری بزرگی بیان کی۔ اور ایک دفعہ فرمایا: میرے بندے نے (اپنے معاملات) میرے سپرد کر دیے۔ پھر جب وہ کہتا ہے: ﴿إیاک نعبد وإیاک نستعین﴾ ’’ہم تیری ہی بندگی کرتے اور تجھ ہی سے مدد چاہتے ہیں۔‘‘ تو (اللہ) فرماتا ہے: یہ (حصہ) میرے اور میرے بندے کے درمیان ہے اور میرے بندے نے جو مانگا، اس کا ہے اور جب وہ کہتا ہے: ﴿إہدنا الصراط المستقیم صراط الذین أنعمت علیہم غیر المغضوب علیہم والا الضالین﴾ ’’ہمیں راہ راست دکھا، ان لوگوں کی راہ جن پر تو نے انعام فرمایا، نہ غضب کیے گئے لوگوں کی ہو اور نہ گمراہوں کی۔‘‘ تو (اللہ) فرماتا ہے: یہ میرے بندے کے لیے ہے اور میرے بندے کا ہے جو اس نے مانگا۔\nسفیان نے کہا: مجھے یہ روایت علاء بن عبد الرحمن بن یعقوب نے سنائی، میں ان کے پاس گیا، وہ گھر میں بیمار تھے۔ میں نے ان سے اس حدیث کے بارے میں سوال کیا (تو انہوں نے مجھے یہ حدیث سنائی۔)"}],[809,"مالک بن انس نے علاء بن عبد الرحمان سے روایت کی ، انہوں نے ہشام بن زہرہ کے آزاد کردہ غلام ابو سائب سے سنا ، کہتے تھے : میں نے ابو ہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ( جس طرح پچھلی روایت ہے ۔)","",{"u2":"مالک بن انس نے علاء بن عبد الرحمان سے روایت کی، انہوں نے ہشام بن زہرہ کے آزاد کردہ غلام ابو سائب سے سنا، کہتے تھے: میں نے ابو ہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔ (جس طرح پچھلی روایت ہے۔)"}],[810,"مالک بن انس نے علاء بن عبد الرحمان سے روایت کی ، انہوں نے ہشام بن زہرہ کے آزاد کردہ غلام ابو سائب سے سنا ، کہتے تھے : میں نے ابو ہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ( جس طرح پچھلی روایت ہے ۔)","",{"u2":"ابن جریج نے بتایا کہ ہمیں علاء بن عبد الرحمان نے خبر دی، کہا: مجھے عبد اللہ بن ہشام بن زہرہ کے بیٹوں کے آزاد کردہ غلام ابو سائب نے بتایا کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے کوئی نماز پڑھی اور اس میں ام القرآن نہ پڑھی‘‘ ... آگے سفیان کی حدیث کے مانند ہے اور (مالک بن انس اور ابن جریج) دونوں کی روایت میں ہے: ’’ اللہ عزوجل نے فرمایا: میں نے نماز اپنے اور اپنے بندے کے درمیان آدھی آدھی تقسیم کی ہے، اس کا آدھا حصہ میرے لیے ہے اور آدھا میرے بندے کے لیے۔‘‘"}],[811,"ابن جریج نے بتایا کہ ہمیں علاء بن عبد الرحمان نے خبر دی ، کہا : مجھے عبد اللہ بن ہشام بن زہرہ کے بیٹوں کے آزاد کردہ غلام ابو سائب نے بتایا کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس نے کوئی نماز پڑھی اور اس میں ام القرآن نہ پڑھی ‘‘ ... آگے سفیان کی حدیث کے مانند ہے اور ( مالک بن انس اور ابن جریج ) دونوں کی روایت میں ہے : ’’ اللہ عزوجل نے فرمایا : میں نے نماز اپنے اور اپنے بندے کے درمیان آدھی آدھی تقسیم کی ہے ، اس کا آدھا حصہ میرے لیے ہے اور آدھا میرے بندے کے لیے ۔ ‘‘","",{"u2":"و اویس نے کہا: مجھے علاء نے خبر دی، کہا: میں نے اپنے والد سے اور ابو سائب سے سنا، وہ دونوں سیدنا ابو ہریرہ رضی اللہ عنہ کے ہم نشیں تھے، ان دونوں نے کہا کہ ابو ہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے کوئی نماز ادا کی اور اس میں فاتحہ الکتاب نہ پڑھی تو وہ (نماز) ادھوری ہے۔‘‘ آپ نے تین دفعہ یہ جملہ فرمایا .... آگے مذکورہ بالا اساتذہ (مالک، سفیان، ابن جریج) کی حدیث کی طرح ہے"}],[812,"حبیب بن شہید سے روایت ہے ، کہا : میں نے عطاء سے سنا ، وہ سیدنا ابو ہریرہ رضی اللہ عنہ سے بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’قراءت کے بغیر کوئی نماز نہیں ۔ ‘‘ ابو ہریرہ رضی اللہ عنہ نے کہا : جو ( نماز ) رسول اللہ صلی اللہ علیہ وسلم نے ہمارے لیے اونچی قراءت سے ادا کی ہم نے بھی تمہارے لیے وہ اونچی قراءت سے ادا کی اور جس ( نماز ) میں آپ نے ( قراءت کو ) مخفی رکھا ، ہم نے بھی اسے تمہارے لیے مخفی رکھا ۔","",{"u2":"حبیب بن شہید سے روایت ہے، کہا: میں نے عطاء سے سنا، وہ سیدنا ابو ہریرہ رضی اللہ عنہ سے بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قراءت کے بغیر کوئی نماز نہیں۔‘‘ ابو ہریرہ رضی اللہ عنہ نے کہا: جو (نماز) رسول اللہ صلی اللہ علیہ وسلم نے ہمارے لیے اونچی قراءت سے ادا کی ہم نے بھی تمہارے لیے وہ اونچی قراءت سے ادا کی اور جس (نماز) میں آپ نے (قراءت کو) مخفی رکھا، ہم نے بھی اسے تمہارے لیے مخفی رکھا۔"}],[813,"۔ ابن جریج نے عطا سے خبر دی ، کہا : سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : ( نماز پڑھنے والا ) پوری نماز میں ( ہر رکعت میں ) قراءت کرے ۔ رسول اللہ صلی اللہ علیہ وسلم نے جو ( قراءت ) ہمیں ( بلند آواز سے ) سنائی ، ہم نے بھی تمہیں سنائی اور جو آ پ نے ہم سے ( آواز آہستہ کر کے ) مخفی رکھی ہم نے اسے تم سے مخفی رکھا ۔ ایک آدمی نے ان سے کہا : اگر میں ام القرآن سے زیادہ نہ پڑھوں؟ تو انہوں نے کہا : اگر اس سے زیادہ پڑھو تو بہتر ہے اور اگر اس ( فاتحہ ) پر رک جاؤ تو وہ تمہیں کفایت کرے گی ۔","",{"u2":"۔ ابن جریج نے عطا سے خبر دی، کہا: سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: (نماز پڑھنے والا) پوری نماز میں (ہر رکعت میں) قراءت کرے۔ رسول اللہ صلی اللہ علیہ وسلم نے جو (قراءت) ہمیں (بلند آواز سے) سنائی، ہم نے بھی تمہیں سنائی اور جو آ پ نے ہم سے (آواز آہستہ کر کے) مخفی رکھی ہم نے اسے تم سے مخفی رکھا۔ ایک آدمی نے ان سے کہا: اگر میں ام القرآن سے زیادہ نہ پڑھوں؟ تو انہوں نے کہا: اگر اس سے زیادہ پڑھو تو بہتر ہے اور اگر اس (فاتحہ) پر رک جاؤ تو وہ تمہیں کفایت کرے گی۔"}],[814,"۔ حبیب معلم سے روایت ہے ، انہوں نے عطاء سے روایت کی ، کہا : سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : ہر نماز میں قراءت ہے ۔ تو جو ( قراءت ) نبی صلی اللہ علیہ وسلم نے ہمیں سنائی ہم نے تمہیں سنائی اور جو انہوں نے ہم سے پوشیدہ رکھی ، ہم نے وہ تم سے پوشیدہ رکھی اور جس نے ام الکتاب پڑھ لی تو اس کے لیے وہ کافی ہے اور جس نے ( اس سے ) زائد پڑھا تو وہ بہتر ہے ۔","",{"u2":"۔ حبیب معلم سے روایت ہے، انہوں نے عطاء سے روایت کی، کہا: سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: ہر نماز میں قراءت ہے۔ تو جو (قراءت) نبی صلی اللہ علیہ وسلم نے ہمیں سنائی ہم نے تمہیں سنائی اور جو انہوں نے ہم سے پوشیدہ رکھی، ہم نے وہ تم سے پوشیدہ رکھی اور جس نے ام الکتاب پڑھ لی تو اس کے لیے وہ کافی ہے اور جس نے (اس سے) زائد پڑھا تو وہ بہتر ہے۔"}],[815,"سیدنا ابوہریرہ ؓ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف فرما تھے اتنے میں ایک آدمی آیا اس نے نماز پڑھنے کے بعد آپ صلی اللہ علیہ وسلم کو سلام کیا ۔ آپ صلی اللہ علیہ وسلم نے سلام کا جواب دے کر فرمایا : ’’ جاؤ نماز پڑھو تم نے نماز نہیں پرھی ۔ “ تو اس نے واپس ہو کر پہلے کی طرح نماز پڑھی اور لوٹ کر آپ صلی اللہ علیہ وسلم کو سلام کیا ۔ آپ صلی اللہ علیہ وسلم نے وعلیکم السلام کہتے ہوئے فرمایا : ” جاؤ نماز پڑھو تم نے نماز ادا نہیں کی ۔ “ چنانچہ اسی طرح وہ نماز پڑھتا اور لوٹ کر آپ صلی اللہ علیہ وسلم کو سلام کرتا ۔ اور آپ صلی اللہ علیہ وسلم یہی فرماتے : ” جاؤ نماز پڑھو تم نے ادا نہیں کی ۔ “ آخر اس شخص نے عرض کیا : یا رسول اللہ ! قسم ہے اس ذات کی جس نے آپ کو برحق بنایا ہے ، میں اس سے زیادہ اچھے طریقے کے علاوہ مزید کسی چیز سے ناوقف ہوں ۔ براہ کرم آپ ہی مجھے بتا دیجئے ؟ تو ارشاد ہوا : ” تم جب نماز کے لیے کھڑے ہو تو پہلے اللہ اکبر کہو اور پھر جتنا قرآن کریم تم باآسانی پڑھ سکتے ہو وہ پڑھو اس کے بعد رکوع کرو اور پھر بہ آرام بالکل سیدھے کھڑے ہو جاؤ اور اس کے بعد بہ اطمینان سجدہ کرو اور پھر بہ اطمینان قعدہ میں بیٹھو اور اسی طرح اپنی پوری نماز میں کیا کرو ۔ “","",{"u2":"یحییٰ بن سعید نے عبید اللہ سے روایت کی ہے کہا مجھے سعید بن ابی سعید نے آپنے والد (کسان بن سعد)سے حدیث سنائی انہوں نے سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت کیا کہ حضور صلی اللہ علیہ وسلم مسجد میں تشریف لائے تو ایک آدمی مسجد میں نماز پڑھ رہا تھا آ کر رسول اللہ صلی اللہ علیہ وسلم کو سلام عرض کیا ’ رسول اللہ صلی اللہ علیہ وسلم نے سلام کا جواب دیا اور کہا واپس جااور نماز پڑھ کیونکہ تو نے نماز نہیں پڑھی وہ شخص واپس گیا اور پہلے کی طرح نماز ادا کی حضور صلی اللہ علیہ وسلم کے پاس آیا اور سلام عرض کیا آپ صلی اللہ علیہ وسلم نے وعلیکم السلام کہا اور کہا واپس جا اور نماز پرھ کیونکہ تو نے نماز نہیں پڑھی حتی ٰ کےچ تین دفعہ ایسا ہی حضور صلی اللہ علیہ وسلم نے کہا تو اس شخص نے کہا اس ذات کی قسم جس نے تم کو حق کے ساتھ بیجھا ہے!میں اس سے بہتر نہیں پڑھ سکتا آپ مجھے سکھلا دیں تو آپ صلی اللہ علیہ وسلم نے فرمایا ’’جب تم نماز کے لیے کھڑے ہو تو اللہ اکبر کہو اور پھر جتنا تم کو قرآن یا د ہے وہ پڑھوں پھر رکوع کرو ختیٰ کہ رکوع کرنے میں تمہیں اتمام ہو جائے پھر سر اٹھاؤں حتیٰ کہ اطمعنان سے بیٹھ جاؤں پھر پوری نماز میں اسی طرح کرو۔"}],[816,"ابو اسامہ او رعبد اللہ بن نمیر نے عبید اللہ سے ، انہوں نے سعید بن ابی سعید سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ ایک آدمی نے مسجد میں داخل ہو کر نماز پڑھی ، رسول اللہ صلی اللہ علیہ وسلم ایک جانب ( تشریف فرما ) تھے ...... پھر دونوں نے اسی واقعے کی مانند حدیث بیان کی اور ( حدیث کے حصے ) میں ان دونوں نے یہ اضافہ کیا : ’’ جب تم نماز کے لیے کھڑے ہو تو خوب اچھی طرح وضو کرو ، پھر قبلے کی طرف رخ کرو ، پھر تکبیر کہو ۔ ‘‘","",{"u2":"ابو اسامہ او رعبد اللہ بن نمیر نے عبید اللہ سے، انہوں نے سعید بن ابی سعید سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ ایک آدمی نے مسجد میں داخل ہو کر نماز پڑھی، رسول اللہ صلی اللہ علیہ وسلم ایک جانب (تشریف فرما) تھے ...... پھر دونوں نے اسی واقعے کی مانند حدیث بیان کی اور (حدیث کے حصے) میں ان دونوں نے یہ اضافہ کیا: ’’ جب تم نماز کے لیے کھڑے ہو تو خوب اچھی طرح وضو کرو، پھر قبلے کی طرف رخ کرو، پھر تکبیر کہو۔‘‘"}],[817,"ابو عوانہ نے قتادہ سے ، انہوں نے زرارہ بن اوفیٰ سے اور انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ظہر یا عصر کی نماز پڑھائی ، پھر فرمایا : ’’ تم میں سے کس نے میرے پیچھے ﴿سبح اسم ربك الأعلى﴾ پڑھی؟ ‘‘ تو ایک آدمی نے کہا : میں نے ، اور خیر کے سوا اس سے میں اور کچھ نہیں چاہتا تھا ۔ آپ نے فرمایا : ’’مجھے علم ہو گیا کہ تم میں سے کوئی مجھے اس ( یعنی قراءت ) میں الجھا رہا ہے ۔ ‘‘","",{"u2":"ابو عوانہ نے قتادہ سے، انہوں نے زرارہ بن اوفیٰ سے اور انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ظہر یا عصر کی نماز پڑھائی، پھر فرمایا: ’’ تم میں سے کس نے میرے پیچھے ﴿سبح اسم ربک الأعلی﴾ پڑھی؟‘‘ تو ایک آدمی نے کہا: میں نے، اور خیر کے سوا اس سے میں اورکچھ نہیں چاہتا تھا۔ آپ نے فرمایا: ’’مجھے علم ہو گیا کہ تم میں سے کوئی مجھے اس (یعنی قراءت) میں الجھا رہا ہے۔‘‘"}],[818,"شعبہ نے قتادہ سے روایت کی ، انہوں نے زرارہ بن اوفیٰ سے سنا ، وہ سیدنا عمران بن حصین رضی اللہ عنہ سے بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھی تو ایک آدمی نے آپ کے پیچھے ﴿سبح اسم ربك الأعلى﴾ پڑھی شروع کر دی ۔ جب آپ صلی اللہ علیہ وسلم نے اسلام پھیرا تو فرمایا : ’’تم میں سے کس نے پڑھا ‘‘ یا ( فرمایا : ) ’’تم میں سے پڑھنے والا کون ہے؟ ‘‘ ایک آدمی نے کہا : میں ہوں ۔ آپ نے فرمایا : ’’ میں سمجھا کہ تم میں سے کوئی مجھے اس میں الجھا رہا ہے","",{"u2":"شعبہ نے قتادہ سے روایت کی، انہوں نے زرارہ بن اوفیٰ سے سنا، وہ سیدنا عمران بن حصین رضی اللہ عنہ سے بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھی تو ایک آدمی نے آپ کے پیچھے ﴿سبح اسم ربک الأعلی﴾ پڑھی شروع کر دی۔ جب آپ صلی اللہ علیہ وسلم نے اسلام پھیرا تو فرمایا: ’’تم میں سے کس نے پڑھا‘‘ یا (فرمایا:) ’’تم میں سے پڑھنے والا کون ہے؟ ‘‘ ایک آدمی نے کہا: میں ہوں۔ آپ نے فرمایا: ’’ میں سمجھا کہ تم میں سے کوئی مجھے اس میں الجھا رہا ہے"}],[819,"۔ قتادہ کے ایک اور شاگرد ابن ابی عروبہ نے اسی سند کے ساتھ ( مذکورہ بالا ) روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھائی اور فرمایا : ’’ میں جان گیا کہ تم میں سے کوئی مجھے اس میں الجھا رہا ہے","",{"u2":"۔ قتادہ کے ایک اور شاگرد ابن ابی عروبہ نے اسی سند کے ساتھ (مذکورہ بالا) روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھائی اور فرمایا: ’’ میں جان گیا کہ تم میں سے کوئی مجھے اس میں الجھا رہا ہے"}],[820,"ہم سے محمد بن جعفر نے حدیث بیان کی ، ( کہا : ) ہم سے شعبہ نے بیان کیا ، کہا : میں نے قتادہ کو سیدنا انس رضی اللہ عنہ سے روایت کرتے ہوئے سنا ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم ، ابو بکر ، عمر اور عثمان رضی اللہ عنہ کے ساتھ نماز پڑھی ، میں نے ان میں سے کسی کو بسم اللہ الرحمن الرحیم پڑھتے نہیں سنا ۔","",{"u2":"ہم سے محمد بن جعفر نے حدیث بیان کی، (کہا:) ہم سے شعبہ نے بیان کیا، کہا: میں نے قتادہ کو سیدنا انس رضی اللہ عنہ سے روایت کرتے ہوئے سنا، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم، ابو بکر، عمر اور عثمان رضی اللہ عنہما کے ساتھ نماز پڑھی، میں نے ان میں سے کسی کو بسم اللہ الرحمن الرحیم پڑھتے نہیں سنا۔"}],[821,"محمد بن ( جعفر کے بجائے ) ابو داؤد نے شعبہ سے اسی سند سے روایت کی اور یہ اضافہ کیا کہ شعبہ نے کہا : میں نے قتادہ سے کہا : کیا آپ نے یہ روایت انس رضی اللہ عنہ سے سنی ہے؟ انہوں نے کہا : ہاں ، کہا : ہاں ، ہم نے سے اس کے بارے میں پوچھا تھا ۔","",{"u2":"محمد بن (جعفر کے بجائے) ابو داؤد نے شعبہ سے اسی سند سے روایت کی اور یہ اضافہ کیا کہ شعبہ نے کہا: میں نے قتادہ سے کہا: کیا آپ نے یہ روایت انس رضی اللہ عنہ سے سنی ہے؟ انہوں نے کہا: ہاں، کہا: ہاں، ہم نے سے اس کے بارے میں پوچھا تھا۔"}],[822,"وزاعی نے عبدہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ یہ کلمات بلند آواز سے پڑھتے تھے : سبحانك اللهم! وبحمدك ، تبارك اسمك وتعالى جدك ، ولا إله غيرك ’’اے اللہ! تو اپنی حمد کے ساتھ پاک ہے ۔ تیرا نام بڑا بابرکت ہے اور تیری عظمت وشان بڑی بلند ہے اور تیرے سوا کوئی معبود نہیں ۔ ‘‘ ( نیز اوزاعی ہی کی ) قتادہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے سیدنا انس رضی اللہ عنہ سے ( اپنی ) روایت کی خبر دیتے ہوئے ان ( اوزاعی ) کی طرف لکھ بھیجا کہ انہوں نے ( انس رضی اللہ عنہ ) نے قتادہ کو حدیث سنائی ، کہا : میں نے نبی صلی اللہ علیہ وسلم ، ابو بکر ، عمر اور عثمان رضی اللہ عنہ کے پیچھے نماز پڑھی ہے ، وہ ( نماز کا ) آغاز الحمد لله رب العالمين سے کرتے تھے ، وہ بسم اللہ الرحمن الرحيم ( بلند آواز سے ) نہیں کہتے تھے ، نہ قراءت کے شروع میں اور نہ اس کے آخر میں ہی ( دوسری سورت کے آغاز پر)","",{"u2":"وزاعی نے عبدہ سے روایت کی کہ سیدنا عمر بن خطاب رضی اللہ عنہ یہ کلمات بلند آواز سے پڑھتے تھے: سبحانک اللہم! وبحمدک، تبارک اسمک وتعالی جدک، ولا إلہ غیرک ’’اے اللہ! تو اپنی حمد کے ساتھ پاک ہے۔ تیرا نام بڑا بابرکت ہے اور تیری عظمت وشان بڑی بلند ہے اور تیرے سوا کوئی معبود نہیں۔‘‘\n(نیز اوزاعی ہی کی) قتادہ رحمہ اللہ سے روایت ہے کہ انہوں نے سیدنا انس رضی اللہ عنہ سے (اپنی) روایت کی خبر دیتے ہوئے ان (اوزاعی) کی طرف لکھ بھیجا کہ انہوں نے (انس رضی اللہ عنہ) نے قتادہ کو حدیث سنائی، کہا: میں نے نبی صلی اللہ علیہ وسلم، ابو بکر، عمر اورعثمان رضی اللہ عنہما کے پیچھے نماز پڑھی ہے، وہ (نماز کا) آغاز الحمد للہ رب العالمین سے کرتے تھے، وہ بسم اللہ الرحمن الرحیم (بلند آواز سے) نہیں کہتے تھے، نہ قراءت کے شروع میں اور نہ اس کے آخر میں ہی (دوسری سورت کے آغاز پر"}],[823,"اسحاق بن عبد اللہ بن ابی طلحہ نے بتایا کہ انہوں نے انس بن مالک رضی اللہ عنہ سنا ، وہ یہی ( سابقہ ) حدیث بیان کرتے تھے ۔","",{"u2":"اسحاق بن عبد اللہ بن ابی طلحہ نے بتایا کہ انہوں نے انس بن مالک رضی اللہ عنہ سنا، وہ یہی (سابقہ) حدیث بیان کرتے تھے۔"}],[824,"علی بن حجر سعدی اور ابو بکر بن ابی شیبہ نے ( الفاظ انہی کے ہیں ) علی بن مسہر سے روایت کی ، انہوں نے مختار بن فلفل سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : ایک روز رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان تھے جب اسی اثناء میں آپ کچھ دیر کے لیے نیند جیسی کیفیت میں چلے گئے ، پھر آپ مسکراتے ہوئے اپنا سر اٹھایا تو ہم نے کہا : اللہ کے رسول! آپ کس بات پر ہنسے؟ آپ نے فرمایا : ’’ ابھی مجھ پر ایک سورت نازل کی گئی ہے ۔ ‘‘ پھر آپ نے پڑھا : ﴿ بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ﴿<http : //tanzil.net/tanzil.net>﴾ «فَصَلِّ لِرَبِّكَ وَانْحَرْ» ﴿<http : //tanzil.net/tanzil.net>﴾ «إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ» ﴿<http : //tanzil.net/tanzil.net>﴾﴾ ’’بلاشبہ ہم آپ کو کوثر عطا کی ۔ پس آپ اپنے رب کے لیے نماز پڑھیں اور قربانی کریں ، یقیناً آپ کا دشمن ہی جڑ کٹا ہے ۔ ‘‘ پھر آپ نے کہا : ’’ کیا تم جانتے ہو کوثر کیا ہے؟ ‘‘ ہم نے کہا : اللہ اور اس کا رسول زیادہ جانتے ہیں ۔ آپ نے فرمایا : ’’ وہ ایک نہر ہے جس کا میرے رب عزوجل نے مجھ سے وعدہ فرمایا ہے ، اس پر بہت بھلائی ہے اور وہ ایک حوض ہے جس پر قیامت کے دن میری امت پانی پینے کےلیے آئے گی ، اس کے برتن ستاروں کی تعداد میں ہیں ۔ ان میں سے ایک شخص کو کھینچ لیا جائے گا تو میں عرض کروں گا : اے میرے رب! یہ میری امت سے ہے ۔ تو وہ فرمائے گا : آپ نہیں جانتے کہ انہوں نے آپ کے بعد کیا نئی باتیں نکالیں ۔ ‘‘ ( علی ) ابن حجر نے اپنی حدیث میں ( یہ ) اضافہ کیا : آپ مسجد میں ہمارے درمیان تھے اور ( أحدثوا بعدك کی جگہ ) أحدث بعدك ’’اس نے نئی بات نکالی ‘‘ کہا ۔"],[825,"علی بن حجر سعدی اور ابو بکر بن ابی شیبہ نے ( الفاظ انہی کے ہیں ) علی بن مسہر سے روایت کی ، انہوں نے مختار بن فلفل سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : ایک روز رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان تھے جب اسی اثناء میں آپ کچھ دیر کے لیے نیند جیسی کیفیت میں چلے گئے ، پھر آپ مسکراتے ہوئے اپنا سر اٹھایا تو ہم نے کہا : اللہ کے رسول! آپ کس بات پر ہنسے؟ آپ نے فرمایا : ’’ ابھی مجھ پر ایک سورت نازل کی گئی ہے ۔ ‘‘ پھر آپ نے پڑھا : ﴿ بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ﴿<http : //tanzil.net/tanzil.net>﴾ «فَصَلِّ لِرَبِّكَ وَانْحَرْ» ﴿<http : //tanzil.net/tanzil.net>﴾ «إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ» ﴿<http : //tanzil.net/tanzil.net>﴾﴾ ’’بلاشبہ ہم آپ کو کوثر عطا کی ۔ پس آپ اپنے رب کے لیے نماز پڑھیں اور قربانی کریں ، یقیناً آپ کا دشمن ہی جڑ کٹا ہے ۔ ‘‘ پھر آپ نے کہا : ’’ کیا تم جانتے ہو کوثر کیا ہے؟ ‘‘ ہم نے کہا : اللہ اور اس کا رسول زیادہ جانتے ہیں ۔ آپ نے فرمایا : ’’ وہ ایک نہر ہے جس کا میرے رب عزوجل نے مجھ سے وعدہ فرمایا ہے ، اس پر بہت بھلائی ہے اور وہ ایک حوض ہے جس پر قیامت کے دن میری امت پانی پینے کےلیے آئے گی ، اس کے برتن ستاروں کی تعداد میں ہیں ۔ ان میں سے ایک شخص کو کھینچ لیا جائے گا تو میں عرض کروں گا : اے میرے رب! یہ میری امت سے ہے ۔ تو وہ فرمائے گا : آپ نہیں جانتے کہ انہوں نے آپ کے بعد کیا نئی باتیں نکالیں ۔ ‘‘ ( علی ) ابن حجر نے اپنی حدیث میں ( یہ ) اضافہ کیا : آپ مسجد میں ہمارے درمیان تھے اور ( أحدثوا بعدك کی جگہ ) أحدث بعدك ’’اس نے نئی بات نکالی ‘‘ کہا ۔","",{"u2":"علی بن حجر سعدی اور ابو بکر بن ابی شیبہ نے (الفاظ انہی کے ہیں) علی بن مسہر سے روایت کی، انہوں نے مختار بن فلفل سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، کہا: ایک روز رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان تھے جب اسی اثناء میں آپ کچھ دیر کے لیے نیند جیسی کیفیت میں چلے گئے، پھر آپ مسکراتے ہوئے اپنا سر اٹھایا تو ہم نے کہا: اللہ کے رسول! آپ کس بات پر ہنسے؟ آپ نے فرمایا: ’’ ابھی مجھ پر ایک سورت نازل کی گئی ہے۔‘‘ پھر آپ نے پڑھا: ﴿ بِسْمِ اللَّـہِ الرَّحْمَـٰنِ الرَّحِیمِ إِنَّا أَعْطَیْنَاکَ الْکَوْثَرَ ﴿<http://tanzil.net/tanzil.net>﴾ فَصَلِّ لِرَبِّکَ وَانْحَرْ ﴿<http://tanzil.net/tanzil.net>﴾ إِنَّ شَانِئَکَ ہُوَ الْأَبْتَرُ ﴿<http://tanzil.net/tanzil.net>﴾﴾ ’’بلاشبہ ہم آپ کو کوثر عطا کی۔ پس آپ اپنے رب کے لیے نماز پڑھیں اور قربانی کریں، یقیناً آپ کا دشمن ہی جڑ کٹا ہے۔‘‘ پھر آپ نے کہا: ’’ کیا تم جانتے ہو کوثر کیا ہے؟ ‘‘ ہم نے کہا: اللہ اور اس کا رسول زیادہ جانتے ہیں۔ آپ نے فرمایا: ’’ وہ ایک نہر ہے جس کا میرے رب عزوجل نے مجھ سے وعدہ فرمایا ہے، اس پر بہت بھلائی ہے اور وہ ایک حوض ہے جس پر قیامت کے دن میری امت پانی پینے کےلیے آئے گی، اس کے برتن ستاروں کی تعداد میں ہیں۔ ان میں سے ایک شخص کو کھینچ لیا جائے گا تو میں عرض کروں گا: اے میرے رب! یہ میری امت سے ہے۔ تو وہ فرمائے گا: آپ نہیں جانتے کہ انہوں نے آپ کے بعد کیا نئی باتیں نکالیں۔‘‘\n(علی) ابن حجر نے اپنی حدیث میں (یہ) اضافہ کیا: آپ مسجد میں ہمارے درمیان تھے اور (أحدثوا بعدک کی جگہ) أحدث بعدک ’’اس نے نئی بات نکالی‘‘ کہا۔"}],[826,"ابن فضیل نے مختار بن فلفل سے روایت کی ، انہوں نے کہا : میں نے سیدنا انس بن مالک رضی اللہ عنہ سے سنا ، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نیند جیسی کیفیت میں چلے گئے ، ( آگے ) جس طرح ابن مسہر کی حدیث ہے ، البتہ انہوں ( ابن فضیل ) نے یہ الفاظ کہے : ’’ ایک نہر ہے جس کا میرے رب نے میرے ساتھ وعدہ کیا ہے اور اس پر ایک حوض ہے ۔ ‘‘ اور یہ نہیں کہا : ’’ اس کے برتنوں کی تعداد ستاروں کے برابر ہے ۔ ‘‘","",{"u2":"ابن فضیل نے مختار بن فلفل سے روایت کی، انہوں نے کہا: میں نے سیدنا انس بن مالک رضی اللہ عنہ سے سنا، کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نیند جیسی کیفیت میں چلے گئے، (آگے) جس طرح ابن مسہر کی حدیث ہے، البتہ انہوں (ابن فضیل) نے یہ الفاظ کہے: ’’ ایک نہر ہے جس کا میرے رب نے میرے ساتھ وعدہ کیا ہے اور اس پر ایک حوض ہے۔‘‘ اور یہ نہیں کہا: ’’ اس کے برتنوں کی تعداد ستاروں کے برابر ہے۔‘‘"}],[827,"ہمام نے کہا : ہمیں محمد بن جحادہ نے حدیث سنائی ، کہا : مجھے عبد الجبار بن وائل نے حدیث سنائی ، انہوں نے علقمہ بن وائل اور ان کے آزادہ کردہ غلام سے روایت کی کہ ان دونوں نے ان کے والد سیدنا وائل بن حجر رضی اللہ عنہ سے حدیث بیان کی کہ انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ، آپ نے نماز میں جاتے وقت اپنے دونوں ہاتھ بلند کیے ، تکبیر کہی ( ہمام نے بیان کیا : کانوں کے برابر بلند کیے ) پھر اپنا کپڑا اوڑھ لیا ( دونوں ہاتھ کپڑے کے اندر لے گئے ) ، پھر اپنا دایاں ہاتھ بائیں پر رکھا ، پھر جب رکوع کرنا چاہا تو اپنے دونوں ہاتھ کپڑے سے نکالے ، پھر انہیں بلند کیا ، پھر تکبیر کہی اور رکوع کیا ، پھر جب سمع اللہ لمن حمده کہا تو اپنے دونوں ہاتھ بلند کیے ، پھر جب سجدہ کیا تو اپنی دونوں ہتھیلیوں کے درمیان سجدہ کیا ۔","",{"u2":"ہمام نے کہا: ہمیں محمد بن جحادہ نے حدیث سنائی، کہا: مجھے عبد الجبار بن وائل نے حدیث سنائی، انہوں نے علقمہ بن وائل اور ان کے آزادہ کردہ غلام سے روایت کی کہ ان دونوں نے ان کے والد سیدنا وائل بن حجر رضی اللہ عنہ سے حدیث بیان کی کہ انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا، آپ نے نماز میں جاتے وقت اپنے دونوں ہاتھ بلند کیے، تکبیر کہی (ہمام نے بیان کیا: کانوں کے برابر بلند کیے) پھر اپنا کپڑا اوڑھ لیا (دونوں ہاتھ کپڑے کے اندر لے گئے)، پھر اپنا دایاں ہاتھ بائیں پر رکھا، پھر جب رکوع کرنا چاہا تو اپنے دونوں ہاتھ کپڑے سے نکالے، پھر انہیں بلند کیا، پھر تکبیر کہی اور رکوع کیا، پھر جب سمع اللہ لمن حمدہ کہا تو اپنے دونوں ہاتھ بلند کیے، پھر جب سجدہ کیا تو اپنی دونوں ہتھیلیوں کے درمیان سجدہ کیا۔"}],[828,"۔ جریر نے منصور سے ، انہوں نے ابو وائل سے اور انہوں نے سیدنا عبد اللہ ( بن مسعود ) رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہم نماز میں رسول اللہ صلی اللہ علیہ وسلم کے پیچھے کہتے تھے : اللہ پر سلام ہو ، فلاں پر سلام ہو ۔ ( بخاری کی روایت میں جبریل پر میکائیل پر سلام ہو ۔ ) تو ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا : ’’بلاشبہ اللہ خود سلام ہے ، لہٰذا جب تم میں سے کوئی نماز میں بیٹھے تو کہے : بقا وبادشاہت ، اختیار وعظمت اللہ ہی کےلیے ہے ، اور ساری دعائیں اور ساری پاکیزہ چیزیں ( بھی اسی کےلیے ہیں ) ، اے نبی! آپ پر سلام ہو اور اللہ کی رحمت اور اس کی برکتیں ہوں ۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو ۔ جب کوئی شخص یہ ( دعائیہ ) کلمات کہے گا تو یہ آسمان و زمین میں اللہ کے ہر نیک بندے تک پہنچیں گے ۔ ( پھر کہے : ) میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد اس کےبندے اور رسول ہیں ، پھر جو مانگنا چاہے اس کا انتخاب کر لے ۔ ‘‘","",{"u2":"۔ جریر نے منصور سے، انہوں نے ابو وائل سے اور انہوں نے حضرت عبد اللہ (بن مسعود) رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہم نماز میں رسول اللہ صلی اللہ علیہ وسلم کے پیچھے کہتے تھے: اللہ پر سلام ہو، فلاں پر سلام ہو۔ (بخاری کی روایت میں جبریل پر میکائیل پر سلام ہو۔) تو ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا: ’’بلاشبہ اللہ خود سلام ہے، لہٰذا جب تم میں سے کوئی نماز میں بیٹھے تو کہے: بقا وبادشاہت، اختیار وعظمت اللہ ہی کےلیے ہے، اور ساری دعائیں اور ساری پاکیزہ چیزیں (بھی اسی کےلیے ہیں)، اے نبی! آپ پر سلام ہو اور اللہ کی رحمت اور اس کی برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو۔ جب کوئی شخص یہ (دعائیہ) کلمات کہے گا تو یہ آسمان و زمین میں اللہ کے ہر نیک بندے تک پہنچیں گے۔ (پھر کہے:) میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد اس کےبندے اور رسول ہیں، پھر جو مانگنا چاہے اس کا انتخاب کر لے۔‘‘"}],[829,"(جریر کے بجائے ) شعبہ نے منصور سے باقی ماندہ اسی سند کے ساتھ اسی طرح حدیث بیان کی اور انہوں ( شعبہ ) نے ’’پھر جو مانگنا چاہے اس کا انتخاب کر لے ‘‘ ( کے کلمات ) بیان نہیں کیے ۔","",{"u2":"(جریر کے بجائے) شعبہ نے منصور سے باقی ماندہ اسی سند کے ساتھ اسی طرح حدیث بیان کی اور انہوں (شعبہ) نے ’’پھر جو مانگنا چاہے اس کا انتخاب کر لے‘‘ (کے کلمات) بیان نہیں کیے۔"}],[830,"منصور کے ایک اور شاگرد زائدہ نے ان سے اسی سند کے ساتھ ان دونوں ( جریر اور شعبہ ) کی حدیث کی طرح حدیث بیان کی ، لیکن آخری کلمات میں ماشاء ( جو چاہے ) کی جگہ ما أحب ( جو پسند کرے ) کے الفاظ کہے ۔","",{"u2":"منصور کے ایک اور شاگرد زائدہ نے ان سے اسی سند کے ساتھ ان دونوں (جریر اور شعبہ) کی حدیث کی طرح حدیث بیان کی، لیکن آخری کلمات میں ماشاء (جو چاہے) کی جگہ ما أحب (جو پسند کرے) کے الفاظ کہے۔"}],[831,"اعمش نے ( ابو وائل ) شقیق سے اور انہوں نے سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : جب ہم نماز میں نبی صلی اللہ علیہ وسلم کے ساتھ بیٹھتے تھے .... ( آگے ) منصور کی حدیث کی طرح ( ہے ) اور کہا : ’’ اس کے بعد دعا کا انتخاب کر لے ۔ ‘‘","",{"u2":"اعمش نے (ابو وائل) شقیق سے اور انہوں نے سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت کی، انہوں نے کہا: جب ہم نماز میں نبی صلی اللہ علیہ وسلم کے ساتھ بیٹھتے تھے .... (آگے) منصور کی حدیث کی طرح (ہے) اور کہا: ’’ اس کے بعد دعا کا انتخاب کر لے۔‘‘"}],[832,"۔ عبد اللہ بن سخبرہ نے کہا : میں نے سیدنا ابن مسعود سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے مجھے تشہد سکھایا ، میری ہتھیلی آپ کی دونوں ہتھیلیوں کے درمیان تھی ، ( بالکل اسی طرح ) جیسے آپ مجھے قرآنی سورت کی تعلیم دیتے تھے ۔ اور انہوں نے ( ابن سخبرہ ) نے تشہد اسی طرح بیان کیا جس طرح سابقہ راویوں نے بیان کیا ۔","",{"u2":"۔ عبد اللہ بن سخبرہ نے کہا: میں نے حضرت ابن مسعود سے سنا، کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے مجھے تشہد سکھایا، میری ہتھیلی آپ کی دونوں ہتھیلیوں کے درمیان تھی، (بالکل اسی طرح) جیسے آپ مجھے قرآنی سورت کی تعلیم دیتے تھے۔ اور انہوں نے (ابن سخبرہ) نے تشہد اسی طرح بیان کیا جس طرح سابقہ راویوں نے بیان کیا۔"}],[833,"امام مسلم نے قتیبہ بن سعید اور محمد بن رمح بن مہاجر کی سندوں سے لیث سے ، انہوں نے ابو زبیر سے ، انہوں نے سعید بن جبیر اور طاؤس سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد اسی طرح سکھاتے جس طرح قرآن کی کوئی سورت سکھاتے تھے ، چنانچہ آپ فرماتے تھے : ’’بقا وبادشاہت ، عظمت و اختیار اور کثرت خیر ، ساری دعائیں اور ساری پاکیزہ چیزیں اللہ ہی کےلیے ہیں ۔ آپ پر سلام ہو اے نبی! اور اللہ کی رحمت اور اس کی برکتیں ہوں ۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو ۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں ۔ ‘‘","",{"u2":"امام مسلم نے قتیبہ بن سعید اور محمد بن رمح بن مہاجر کی سندوں سے لیث سے، انہوں نے ابو زبیر سے، انہوں نے سعید بن جبیر اور طاؤس سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد اسی طرح سکھاتے جس طرح قرآن کی کوئی سورت سکھاتے تھے، چنانچہ آپ فرماتے تھے: ’’بقا وبادشاہت، عظمت و اختیار اور کثرت خیر، ساری دعائیں اور ساری پاکیزہ چیزیں اللہ ہی کےلیے ہیں۔ آپ پر سلام ہو اے نبی! اور اللہ کی رحمت اور اس کی برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔‘‘"}],[834,"عبد الرحمن بن حمید نے کہا : مجھے ابو زبیر نے طاؤس کے حوالے سے سیدنا ابن عباس رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد یوں سکھاتے تھے جیسے آپ ہمیں قرآن کی سورت سکھاتے تھے ۔","",{"u2":"عبد الرحمن بن حمید نے کہا: مجھے ابو زبیر نے طاؤس کے حوالے سے سیدنا ابن عباس رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد یوں سکھاتے تھے جیسے آپ ہمیں قرآن کی سورت سکھاتے تھے۔"}],[835,"ابو عوانہ نے قتادہ سے ، انہوں نے یونس بن جبیر سے اور انہوں نے حطان بن عبد اللہ رقاشی سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابو موسیٰ اشعری رضی اللہ عنہ کے ساتھ ایک نماز پڑھی ، جب وہ قعدہ ( نماز میں تشہد کے لیے بیٹھنے ) کے قریب تھے تو لوگوں میں سے ایک شخص نے کہا : نماز کو نیکی اور زکاۃ کے ساتھ رکھا گیا ہے؟ جب ابو موسیٰ رضی اللہ عنہ نے نماز پوری کر لی تو مڑے اور کہا : تم میں سے یہ یہ بات کہنے والا کون تھا؟ تو سب لوگ مارے ہیبت کے چپ رہے ، انہوں نے پھر کہا : تم میں سے یہ یہ بات کہنے والا کون تھا؟ تو لوگ ہیبت کے مارے پھر چپ رہے تو انہوں نے کہا : اے حطان! لگتا ہے تو نے یہ بات کہی؟ انہوں نے کہا : میں نے یہ نہیں کہا ، البتہ مجھے ڈر تھا کہ آپ اس کے سبب میری سرزنش کریں گے ۔ تو لوگوں میں سے ایک آدمی نے کہا : میں نے یہ بات کہی تھی اور میں نے اس سے بھلائی کے سوا اور کچھ نہ چاہا تھا ۔ تو ابو موسیٰ رضی اللہ عنہ نے کہا : کیا تم نہیں جانتے کہ تمہیں اپنی نماز میں کیسے کہنا چاہیے؟ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا ، آپ نے ہمارے لیے ہمارا طریقہ واضح کیا اور ہمیں ہماری نماز سکھائی ۔ آپ نے فرمایا : ’’جب تم نماز پڑھو تو اپنی صفوں کو سیدھا کرو ، پھر تم میں سے ایک شخص تمہاری امامت کرائے ، جب وہ تکبیر کہے تو تم تکبیر کہو اور جب وہ ﴿غير المغضوب عليهم والا الضالين﴾ کہے تو تم آمین کہو ، اللہ تمہاری دعا قبول فرمائے گا ۔ پھر جب وہ تکبیر کہے اور رکوع کرے تو تم تکبیر کہو اور رکوع کرو ، امام تم سے پہلے رکوع میں جائے گا اور تم سے پہلے سر اٹھائے گا ۔ ‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ تو ( مقتدی کی طرف سے رکوع میں جانے کی ) یہ ( تاخیر ) اس ( تاخیر ) کا بدل ہو کی ( جو رکوع سے سر اٹھانے میں ہو گی ) اور جب امام سمع اللہ لمن حمده کہے تو تم اللهم ربنا لك الحمد کہو ، اللہ تمہاری ( بات ) سنے گا ، کیونکہ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کی زبان سے فرمایا ہے : اللہ نے اسے سن لیا جس نے اس کی حمد بیان کی اور جب امام تکبیر کہے اور سجدہ کرے تو تم تکبیر کہو اور سجدہ کرو ، امام تم سے پہلے سجدہ کرے گا اور تم سے پہلے سر اٹھائے گا ۔ ‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ تو یہ ( تاخیر ) اس ( تاخیر ) کابدل ہو گی اور جب وہ قعدہ میں ہو تو تمہارا پہلا بول ( یہ ) ہو : بقا وبادشاہت ، اختیار وعظمت ، سب پاک چیزیں اور ساری دعائیں اللہ کےلیے ہیں ۔ اے نبی! آپ پر سلام اور اللہ کی رحمت اور اس کی برکتیں ہوں ۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو ۔ میں گواہی دیتا ہوں کہ اللہ کےسوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں ۔ ‘‘","",{"u2":"ابو عوانہ نے قتادہ سے، انہوں نے یونس بن جبیر سے اور انہوں نے حطان بن عبد اللہ رقاشی سے روایت کی، انہوں نے کہا: میں نے سیدنا ابو موسیٰ اشعری رضی اللہ عنہ کے ساتھ ایک نماز پڑھی، جب وہ قعدہ (نماز میں تشہد کے لیے بیٹھنے) کے قریب تھے تو لوگوں میں سے ایک شخص نے کہا: نماز کو نیکی اور زکاۃ کے ساتھ رکھا گیا ہے؟ جب ابو موسیٰ رضی اللہ عنہ نے نماز پوری کر لی تو مڑے اور کہا: تم میں سے یہ یہ بات کہنے والا کون تھا؟ تو سب لوگ مارے ہیبت کے چپ رہے، انہوں نے پھر کہا: تم میں سے یہ یہ بات کہنے والا کون تھا؟ تو لوگ ہیبت کے مارے پھر چپ رہے تو انہوں نے کہا: اے حطان! لگتا ہے تو نے یہ بات کہی؟ انہوں نے کہا: میں نے یہ نہیں کہا، البتہ مجھے ڈر تھا کہ آپ اس کے سبب میری سرزنش کریں گے۔ تو لوگوں میں سے ایک آدمی نے کہا: میں نے یہ بات کہی تھی اور میں نے اس سے بھلائی کے سوا اور کچھ نہ چاہا تھا۔ تو ابو موسیٰ رضی اللہ عنہ نے کہا: کیا تم نہیں جانتے کہ تمہیں اپنی نماز میں کیسے کہنا چاہیے؟ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا، آپ نے ہمارے لیے ہمارا طریقہ واضح کیا اور ہمیں ہماری نماز سکھائی۔ آپ نے فرمایا: ’’جب تم نماز پڑھو تو اپنی صفوں کو سیدھا کرو، پھر تم میں سے ایک شخص تمہاری امامت کرائے، جب وہ تکبیر کہے تو تم تکبیر کہو اور جب وہ ﴿غیر المغضوب علیہم والا الضالین﴾ کہے تو تم آمین کہو، اللہ تمہاری دعا قبول فرمائے گا۔ پھر جب وہ تکبیر کہے اور رکوع کرے تو تم تکبیر کہو اور رکوع کرو، امام تم سے پہلے رکوع میں جائے گا اور تم سے پہلے سر اٹھائے گا۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ تو (مقتدی کی طرف سے رکوع میں جانےکی) یہ (تاخیر) اس (تاخیر) کا بدل ہو کی (جو رکوع سے سر اٹھانے میں ہو گی) اور جب امام سمع اللہ لمن حمدہ کہے تو تم اللہم ربنا لک الحمد کہو، اللہ تمہاری (بات) سنے گا، کیونکہ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کی زبان سے فرمایا ہے: اللہ نے اسے سن لیا جس نے اس کی حمد بیان کی اور جب امام تکبیر کہے اور سجدہ کرے تو تم تکبیر کہو اور سجدہ کرو، امام تم سے پہلے سجدہ کرے گا اور تم سے پہلے سر اٹھائے گا۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ تو یہ (تاخیر) اس (تاخیر) کابدل ہو گی اور جب وہ قعدہ میں ہو تو تمہارا پہلا بول (یہ) ہو: بقا وبادشاہت، اختیار وعظمت، سب پاک چیزیں اور ساری دعائیں اللہ کےلیے ہیں۔ اے نبی! آپ پر سلام اور اللہ کی رحمت اور اس کی برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کےسوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں۔‘‘"}],[836,"ابو اسامہ نے سعید بن ابی عروبہ سے حدیث بیان کی ، نیز معاذ بن ہشام نے اپنے والد سے حدیث بیان کی ، اسی طرح جریر نے سلیمان تیمی سے خبر دی ، ان سب ( ابن ابی عروبہ ، ہشام اور سلیمان ) نے قتادہ سے اسی ( سابقہ ) حدیث کے مانند روایت کی ، البتہ قتادہ سے سلیمان اور ان سے جریر کی بیان کردہ حدیث میں یہ اضافہ ہے : ’’ جب امام پڑھے تو تم غور سے سنو ۔ ‘‘ اور ابو عوانہ کے شاگرد کامل کی حدیث کے علاوہ ان میں سے کسی کی حدیث میں : ’’اللہ عزوجل نے اپنے نبی صلی اللہ علیہ وسلم کی زبان سے فرمایا ہے : ’’ اللہ نے اسے سن لیا جس نے اس کی حمد کی ۔ ‘‘ کے الفاظ نہیں ہیں ۔ ابو اسحاق نے کہا : ابو نضر کے بھانجے ابو بکر نے اس حدیث کے متعلق بات کی تو امام مسلم نے کہا : آپ کو سلیمان سے بڑا حافظ چاہیے؟ اس پر ابو بکر نے امام مسلم سے کہا : ابو ہریرہ رضی اللہ عنہ کی حدیث؟ پھر ( ابو بکر نے ) کہا : وہ صحیح ہے ، یعنی ( یہ اضافہ کہ ) جب امام پڑھے تو تم خاموش رہو ۔ امام مسلم نے ( جوابا ) کہا : وہ میرے نزدیک بھی صحیح ہے ۔ تو ابو بکر نے کہا : آپ نے اسے یہاں کیوں نہ رکھا ( درج کیا ) ؟ ( امام مسلم نے جواباً ) کہا : ہر وہ چیز جو میرے نزدیک صحیح ہے ، میں نے اسے یہاں نہیں رکھا ۔ یہاں میں نے صرف ان ( احادیث ) کو رکھا جن ( کی صحت ) پر انہوں ( محدثین ) نے اتفاق کیا ہے ۔","",{"u2":"ابو اسامہ نے سعید بن ابی عروبہ سے حدیث بیان کی، نیز معاذ بن ہشام نے اپنے والد سے حدیث بیان کی، اسی طرح جریر نے سلیمان تیمی سے خبر دی، ان سب (ابن ابی عروبہ، ہشام اور سلیمان) نے قتادہ سے اسی (سابقہ) حدیث کے مانند روایت کی، البتہ قتادہ سے سلیمان اور ان سے جریر کی بیان کردہ حدیث میں یہ اضافہ ہے: ’’ جب امام پڑھے تو تم غور سے سنو۔‘‘ اور ابو عوانہ کے شاگرد کامل کی حدیث کے علاوہ ان میں سے کسی کی حدیث میں: ’’اللہ عزوجل نے اپنے نبی صلی اللہ علیہ وسلم کی زبان سے فرمایا ہے: ’’ اللہ نے اسے سن لیا جس نے اس کی حمد کی۔‘‘ کے الفاظ نہیں ہیں۔\nابو اسحاق نے کہا: ابو نضر کے بھانجے ابو بکر نے اس حدیث کے متعلق بات کی تو امام مسلم نے کہا: آپ کو سلیمان سے بڑا حافظ چاہیے؟ اس پر ابو بکر نے امام مسلم سے کہا: ابو ہریرہ رضی اللہ عنہ کی حدیث؟ پھر (ابو بکر نے) کہا: وہ صحیح ہے، یعنی (یہ اضافہ کہ) جب امام پڑھے تو تم خاموش رہو۔ امام مسلم نے (جوابا) کہا: وہ میرے نزدیک بھی صحیح ہے۔ تو ابو بکر نے کہا: آپ نے اسے یہاں کیوں نہ رکھا (درج کیا)؟ (امام مسلم نے جواباً) کہا: ہر وہ چیز جو میرے نزدیک صحیح ہے، میں نے اسے یہاں نہیں رکھا۔ یہاں میں نے صرف ان (احادیث) کو رکھا جن (کی صحت) پر انہوں (محدثین) نے اتفاق کیا ہے۔"}],[837,"قتادہ کے ایک اور شاگرد معمر نے اسی سند کے ساتھ مذکورہ بالا حدیث روایت کی اور ( اپنی ) حدیث میں کہا : ’’چنانچہ اللہ نے اپنے نبی صلی اللہ علیہ وسلم کی زبان سے فیصلہ کر دیا : ( کہ ) اللہ نے اسے سن لیا جس نے اس کی حمد بیان کی ( قال کے بجائے قضى کالفظ روایت کیا ۔)","",{"u2":"قتادہ کے ایک اور شاگرد معمر نے اسی سند کے ساتھ مذکورہ بالا حدیث روایت کی اور (اپنی) حدیث میں کہا: ’’چنانچہ اللہ نے اپنے نبی صلی اللہ علیہ وسلم کی زبان سے فیصلہ کر دیا: (کہ) اللہ نے اسے سن لیا جس نے اس کی حمد بیان کی (قال کے بجائے قضی کالفظ روایت کیا۔)"}],[838,"نعیم بن عبد اللہ مجمر سے روایت ہے کہ محمد بن عبد اللہ بن زید انصاری نے ( محمد کے والد عبد اللہ بن زید وہی ہیں جن کو نماز کے لیے اذان خواب میں دکھائی گئی تھی ) انہیں ابو مسعود انصاری رضی اللہ عنہ کے متعلق بتایا کہ انہوں نے کہا : ہم سعد بن عبادہ رضی اللہ عنہ کی مجلس میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے ، چنانچہ بشیر بن سعد رضی اللہ عنہ نے آپ سے عرض کی : اللہ کے رسول! اللہ تعالیٰ نے ہمیں آپ پر درود بھیجنے کا حکم دیا ہے تو ہم آپ پر درود کیسے بھیجیں؟ انہوں نے کہا : اس پر رسول اللہ صلی اللہ علیہ وسلم خاموش ہوگئے حتیٰ کہ ہم نے تمنا کی کہ انہوں نے آپ سے یہ سوال نہ کیا ہوتا ، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ کہو : اے اللہ! رحمت فرما محمد اور محمد کی آل پر ، جیسے تو نے رحمت فرمائی ابراہیم کی آل پر اور برکت نازل فرما محمد اور محمد کی آل پر ، جیسے تو نے سب جہانوں میں برکت نازل فرمائی ابراہیم کی آل پر ، بلاشبہ تو سزا وار حمد ہے ، عظمتوں والا ہے اور سلام اسی طرح ہے جیسے تم ( پہلے ) جان چکے ہو ۔ ‘‘","",{"u2":"نعیم بن عبد اللہ مجمر سے روایت ہے کہ محمد بن عبد اللہ بن زید انصاری نے (محمد کے والد عبد اللہ بن زید وہی ہیں جن کو نماز کے لیے اذان خواب میں دکھائی گئی تھی) انہیں ابو مسعود انصاری رضی اللہ عنہ کے متعلق بتایا کہ انہوں نے کہا: ہم سعد بن عبادہ رضی اللہ عنہ کی مجلس میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، چنانچہ بشیر بن سعد رضی اللہ عنہ نے آپ سے عرض کی: اللہ کے رسول! اللہ تعالیٰ نے ہمیں آپ پر درود بھیجنے کا حکم دیا ہے تو ہم آپ پر درود کیسے بھیجیں؟ انہوں نے کہا: اس پر رسول اللہ صلی اللہ علیہ وسلم خاموش ہوگئے حتیٰ کہ ہم نے تمنا کی کہ انہوں نے آپ سے یہ سوال نہ کیا ہوتا، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ کہو:اے اللہ! رحمت فرما محمد اور محمد کی آل پر، جیسے تو نے رحمت فرمائی ابراہیم کی آل پر اور برکت نازل فرما محمد اور محمد کی آل پر، جیسے تو نے سب جہانوں میں برکت نازل فرمائی ابراہیم کی آل پر، بلاشبہ تو سزا وار حمد ہے، عظمتوں والا ہے اور سلام اسی طرح ہے جیسے تم (پہلے) جان چکے ہو۔‘‘"}],[839,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حَکم سے حدیث سنائی ، انہوں نے کہا : میں نے ابن ابی لیلیٰ سے سنا ، انہوں نے کہا : مجھے سیدنا کعب بن عجرہ رضی اللہ عنہ ملے اور کہنے لگے : کیا میں تمہیں ایک تحفہ نہ دوں؟ رسول اللہ صلی اللہ علیہ وسلم ہماری طرف تشریف لائے تو ہم نے عرض کی : ہم تو جان چکے ہیں کہ ہم آپ پر سلام کیسے بھیجیں ، ( یہ بتائیں ) ہم آپ پر صلاۃ کیسے بھیجیں؟ آپ نے فرمایا : ’’کہو : اے اللہ! محمد اور محمد کی آل پر رحمت فرما ، جیسے تو نے ابراہیم کی آل پر رحمت فرمائی ، بلاشبہ تو سزاوار حمد ، عظمتوں والا ہے ۔ اے اللہ! محمد پر اور محمد کی آل پر برکت نازل فرما ، جیسے تو نے ابراہیم کی آل پر برکت نازل فرمائی ، بلاشبہ تو سزاوار حمد ہے ، عظمتوں والا ہے ۔ ‘‘","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے حَکم سے حدیث سنائی، انہوں نے کہا: میں نے ابن ابی لیلیٰ سے سنا، انہوں نے کہا: مجھے سیدنا کعب بن عجرہ رضی اللہ عنہ ملے اور کہنے لگے: کیا میں تمہیں ایک تحفہ نہ دوں؟ رسول اللہ صلی اللہ علیہ وسلم ہماری طرف تشریف لائے تو ہم نے عرض کی: ہم تو جان چکے ہیں کہ ہم آپ پر سلام کیسے بھیجیں، (یہ بتائیں) ہم آپ پر صلاۃ کیسے بھیجیں؟ آپ نے فرمایا: ’’کہو: اے اللہ! محمد اور محمد کی آل پر رحمت فرما، جیسے تو نے ابراہیم کی آل پر رحمت فرمائی، بلاشبہ تو سزاوار حمد، عظمتوں والا ہے۔ اے اللہ! محمد پر اور محمد کی آل پر برکت نازل فرما، جیسے تو نے ابراہیم کی آل پر برکت نازل فرمائی، بلاشبہ تو سزاوار حمد ہے، عظمتوں والا ہے۔‘‘"}],[840,"۔ وکیع نے شعبہ اور مسعر سے اسی سند کے ساتھ حکم سے اسی کی مانند روایت کی اور مسعر کی حدیث میں یہ جملہ نہیں ہے : کیا میں تمہیں ایک تحفہ نہ دوں؟","",{"u2":"۔ وکیع نے شعبہ اور مسعر سے اسی سند کے ساتھ حکم سے اسی کی مانند روایت کی اور مسعر کی حدیث میں یہ جملہ نہیں ہے: کیا میں تمہیں ایک تحفہ نہ دوں؟"}],[841,"اسماعیل بن زکریا نے اعمش ، مسعر اور مالک بن مغول سے روایت کی اور ان سب نے حکم سے اسی سند کے ساتھ سابقہ حدیث کی مانند روایت کی ، البتہ اسماعیل نے کہا : وبارك على محمد اور ( اس سے پہلے ) اللهم نہیں کہا ۔","",{"u2":"اسماعیل بن زکریا نے اعمش، مسعر اور مالک بن مغول سے روایت کی اور ان سب نے حکم سے اسی سند کے ساتھ سابقہ حدیث کی مانند روایت کی، البتہ اسماعیل نے کہا: وبارک علی محمد اور (اس سے پہلے) اللہم نہیں کہا۔"}],[842,"عمرو بن سلیم نے کہا : مجھے سیدنا ابو حمید ساعدی رضی اللہ عنہ نے بتایا کہ انہوں ( صحابہ ) نے کہا : اے اللہ کے رسول! ہم آپ پر صلاۃ کیسے بھیجیں؟ آپ نے فرمایا : ’’کہو : اے اللہ! رحمت فرما محمد پر اور آپ کی ازواج اور آپ کی اولاد پر ، جیسے تو نے ابراہیم کی آل پر رحمت فرمائی اور برکت نازل فرما محمد پر اور آپ کی ازواج اور آپ کی اولاد پر ، جیسے تو نے برکت نازل فرمائی ابراہیم کی آل پر ، بلاشبہ تو سزا وار حمد ہے ، عظمتوں والا ہے ۔ ‘‘","",{"u2":"عمرو بن سلیم نے کہا: مجھے سیدنا ابو حمید ساعدی رضی اللہ عنہ نے بتایا کہ انہوں (صحابہ) نے کہا: اے اللہ کے رسول! ہم آپ پر صلاۃ کیسے بھیجیں؟ آپ نے فرمایا: ’’کہو: اے اللہ! رحمت فرما محمد پر اور آپ کی ازواج اور آپ کی اولاد پر، جیسے تو نے ابراہیم کی آل پر رحمت فرمائی اور برکت نازل فرما محمد پر اور آپ کی ازواج اور آپ کی اولاد پر، جیسے تو نے برکت نازل فرمائی ابراہیم کی آل پر، بلاشبہ تو سزا وار حمد ہے، عظمتوں والا ہے۔‘‘"}],[843,"۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : جس نے مجھ پر ایک بار درود بھیجا اللہ تعالیٰ اس پر دس بار رحمت نازل فرمائے گا ۔","",{"u2":"۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: جس نے مجھ پر ایک بار درود بھیجا اللہ تعالیٰ اس پر دس بار رحمت نازل فرمائے گا۔"}],[844,"سمی نے ابو صالح سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب امام سمع اللہ لمن حمده ( اللہ نے سن لیا جس نے اس کی تعریف کی ) کہے تو تم کہو : اللهم ، ربنا لك الحمد ( اے اللہ! ہمارے رب! سب تعریف تیرے لیے ہے ) کیونکہ جس کا قول فرشتوں کے قول کے موافق ہو گیا اس کے گزشتہ گناہ معاف کر دیے جائیں گے ۔ ‘‘","",{"u2":"سمی نے ابو صالح سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب امام سمع اللہ لمن حمدہ (اللہ نے سن لیا جس نے اس کی تعریف کی) کہے تو تم کہو: اللہم، ربنا لک الحمد (اے اللہ! ہمارے رب! سب تعریف تیرے لیے ہے) کیونکہ جس کا قول فرشتوں کے قول کے موافق ہو گیا اس کے گزشتہ گناہ معاف کر دیے جائیں گے۔‘‘"}],[845,"۔ سہیل نے اپنے والد ( ابو صالح ) سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ( مذکورہ بالا راوی ) سمی کی حدیث کے مانند روایت کی ۔","",{"u2":"۔ سہیل نے اپنے والد (ابو صالح) سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے (مذکورہ بالا راوی) سمی کی حدیث کے مانند روایت کی۔"}],[846,"مالک نے ابن شہاب سے ، انہوں نے سعید بن مسیب اور ابو سلمہ بن عبد الرحمن سے روایت کی کہ ان دونوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب امام آمین کہے تو تم بھی آمین کہو کیونکہ جس کی آمین فرشتوں کی آمین کے موافق ہو جائے گی ، اس کے سابقہ گناہ معاف کر دیے جائیں گے ۔ ‘‘","",{"u2":"مالک نے ابن شہاب سے، انہوں نے سعید بن مسیب اور ابو سلمہ بن عبد الرحمن سے روایت کی کہ ان دونوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب امام آمین کہے تو تم بھی آمین کہو کیونکہ جس کی آمین فرشتوں کی آمین کے موافق ہو جائے گی، اس کے سابقہ گناہ معاف کر دیے جائیں گے۔‘‘"}],[847,"۔ ( مالک کے بجائے ) یونس نے ابن شہاب سے ، انہوں نے ابن مسیب اور ابو سلمہ بن عبد الرحمن سے روایت کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ... ( آگے ) مالک کی مذکورہ بالا روایت کی طرح ہے ، البتہ یونس نے ابن شہاب کا قول بیان نہیں کیا ۔","",{"u2":"۔ (مالک کے بجائے) یونس نے ابن شہاب سے، انہوں نے ابن مسیب اور ابو سلمہ بن عبد الرحمن سے روایت کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ... (آگے) مالک کی مذکورہ بالا روایت کی طرح ہے، البتہ یونس نے ابن شہاب کا قول بیان نہیں کیا۔"}],[848,"ابو یونس ( سلیم بن جبیر ) نے سیدنا ابو ہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے کوئی نماز میں آمین کہے اور فرشتے آسمان میں آمین کہیں اور ایک آمین دوسری کے موافق ہو جائے تو اس کے پچھلے گناہ معاف کر دیے جاتے ہیں ۔ ‘‘","",{"u2":"ابو یونس (سلیم بن جبیر) نے سیدنا ابو ہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب تم میں سے کوئی نماز میں آمین کہے اور فرشتے آسمان میں آمین کہیں اور ایک آمین دوسری کے موافق ہو جائے تو اس کے پچھلے گناہ معاف کر دیے جاتے ہیں۔‘‘"}],[849,"سیدنا ابو ہریرہ رضی اللہ عنہ کے ایک اور شاگرد اعرج کے حوالے سے روایت ہے کہ ابو ہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے ایک شخص آمین کہے اور فرشتے آسمان میں آمین کہیں اور آمین دوسری کے موافق ہو جائے تو اس شخص کے پچھلے گناہ معاف کر دیے جاتے ہیں","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ کے ایک اور شاگرد اعرج کے حوالے سے روایت ہے کہ ابو ہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب تم میں سے ایک شخص آمین کہے اور فرشتے آسمان میں آمین کہیں اور آمین دوسری کے موافق ہو جائے تو اس شخص کے پچھلے گناہ معاف کر دیے جاتے ہیں"}],[850,"ہمام بن منبہ نے ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی ( گزشتہ حدیث ) کی طرح حدیث بیان کی ۔","",{"u2":"ہمام بن منبہ نے ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی (گزشتہ حدیث) کی طرح حدیث بیان کی۔"}],[851,"سہیل کے والد ابو صالح نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب قاری ﴿غير المغضوب عليهم والا الضالين﴾ کہے اور جو اس کے پیچھے ہے وہ ( بھی ) آمین کہے اور اس کا کہنا آسمان والوں کی کہی ہوئی ( آمین ) کے موافق ہو جائے تو اس کے پچھلے گناہ معاف کر دیے جاتے ہیں ۔ ‘‘","",{"u2":"سہیل کے والد ابو صالح نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب قاری ﴿غیر المغضوب علیہم والا الضالین﴾ کہے اور جو اس کے پیچھے ہے وہ (بھی) آمین کہے اور اس کا کہنا آسمان والوں کی کہی ہوئی (آمین) کے موافق ہو جائے تو اس کے پچھلے گناہ معاف کر دیے جاتے ہیں۔‘‘"}],[852,"سفیان بن عیینہ نے زہری سے حدیث بیان کی ، انہوں نے کہا کہ میں نے سیدنا انس بن مالک رضی اللہ عنہ سے سنا ، وہ کہتے تھے کہ نبی صلی اللہ علیہ وسلم گھوڑے سے گر گئے تو آپ کا دایاں پہلو چھل گیا ، ہم آپ کے ہاں آپ کی عیادت کے لیے حاضر ہوئے ، نماز کا وقت ہو گیا تو آپ نے ہمیں بیٹھ کر نماز پڑھائی ، چنانچھ ہم نے ( آپ کے اشارے پر ، حدیث 926 ۔ 928 ) آپ کے پیچھے بیٹھ کر نماز پڑھی ، پھر جب آپ نے نماز پوری کی تو فرمایا : ’’امام اسی لیے بنایا گیا کہ اس کی اقتدا کی جائے ، چنانچہ جب وہ تکبیر کہے تو تم تکبیر کہو ، جب وہ سجدہ کرے تو تم سجدہ کرو ، جب وہ ( سر ) اٹھائے تو تم ( سر ) اٹھاؤ اور جب وہ سمع اللہ لمن حمده ( اللہ نے اسے سن لیا جس نے اس کی حمد بیان کی ) کہے تو تم ربنا لك الحمد ( اے ہمارے رب! تیری ہی لیے سب تعریف ہے ) کہو اور جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو ۔ ‘‘","",{"u2":"سفیان بن عیینہ نے زہری سے حدیث بیان کی، انہوں نے کہا کہ میں نے سیدنا انس بن مالک رضی اللہ عنہ سے سنا، وہ کہتے تھے کہ نبی صلی اللہ علیہ وسلم گھوڑے سے گر گئے تو آپ کا دایاں پہلو چھل گیا، ہم آپ کے ہاں آپ کی عیادت کے لیے حاضر ہوئے، نماز کا وقت ہو گیا تو آپ نے ہمیں بیٹھ کر نماز پڑھائی، چنانچھ ہم نے (آپ کے اشارے پر، حدیث 926۔928) آپ کے پیچھے بیٹھ کر نماز پڑھی، پھر جب آپ نے نماز پوری کی تو فرمایا: ’’امام اسی لیے بنایا گیا کہ اس کی اقتدا کی جائے، چنانچہ جب وہ تکبیر کہے تو تم تکبیر کہو، جب وہ سجدہ کرے تو تم سجدہ کرو، جب وہ (سر) اٹھائے تو تم (سر) اٹھاؤ اور جب وہ سمع اللہ لمن حمدہ (اللہ نے اسے سن لیا جس نے اس کی حمد بیان کی) کہے تو تم ربنا لک الحمد (اے ہمارے رب! تیری ہی لیے سب تعریف ہے) کہو اور جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو۔‘‘"}],[853,"۔ ( سفیان کے بجائے ) لیث نے ابن شہاب ( زہری ) سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے سے گر گئے اور آپ کا ایک پہلو چھل گیا تو آپ نے ہمیں بیٹھ کر نماز پڑھائی .... آگے سابقہ حدیث کی طرح بیان کیا ۔","",{"u2":"۔ (سفیان کے بجائے) لیث نے ابن شہاب (زہری) سے، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے سے گر گئے اور آپ کا ایک پہلو چھل گیا تو آپ نے ہمیں بیٹھ کر نماز پڑھائی .... آگے سابقہ حدیث کی طرح بیان کیا۔"}],[854,"یونس نے ابن شہاب ( زہری ) سے روایت کی ، انہوں نے کہا : مجھے سیدنا انس رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے سے گر گئے اور آپ کا دایاں پہلو چھل گیا ... پھر ان دونوں حضرات ( سفیان اور لیث ) کی روایت کے مانند روایت کی ، البتہ یونس نے یہ اضافہ کیا : ’’ اور جب وہ ( امام ) کھڑا ہو کر نماز پڑھے تو تم بھی کھڑے ہو کر نماز پڑھو","",{"u2":"یونس نے ابن شہاب (زہری) سے روایت کی، انہوں نے کہا: مجھے سیدنا انس رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے سے گر گئے اور آپ کا دایاں پہلو چھل گیا ... پھر ان دونوں حضرات (سفیان اور لیث) کی روایت کے مانند روایت کی، البتہ یونس نے یہ اضافہ کیا: ’’ اور جب وہ (امام) کھڑا ہو کر نماز پڑھے تو تم بھی کھڑے ہو کر نماز پڑھو"}],[855,"مالک بن انس نے زہری سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے پر سوار ہوئے اور اس سے گر پڑے ، اس سے آپ کا دایاں پہلو چھل گیا .... آگے مذکورہ بالا تینوں راویوں کی طرح روایت کی اور اس میں ( بھی یہ ) ہے : ’’ جب وہ ( امام ) کھڑا ہو کر نماز پڑھے تو تم بھی کھڑے ہو کر نماز پڑھو ۔ ‘‘","",{"u2":"مالک بن انس نے زہری سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے پر سوار ہوئے اور اس سے گر پڑے، اس سے آپ کا دایاں پہلو چھل گیا .... آگے مذکورہ بالا تینوں راویوں کی طرح روایت کی اور اس میں (بھی یہ) ہے: ’’ جب وہ (امام) کھڑا ہو کر نماز پڑھے تو تم بھی کھڑے ہو کر نماز پڑھو۔‘‘"}],[856,"معمر نے زہری سے روایت کی ، انہوں نے کہا : مجھے سیدنا انس رضی اللہ عنہ نے خبر دی کہ نبی صلی اللہ علیہ وسلم گھوڑے سے گر پڑے جس سے آپ کا دایاں پہلو چھل گیا ... آگے سابقہ حدیث کے مانند حدیث بیان کی ، اس میں یونس اور مالک والا اضافہ نہیں ہے ۔","",{"u2":"معمر نے زہری سے روایت کی، انہوں نے کہا: مجھے سیدنا انس رضی اللہ عنہ نے خبر دی کہ نبی صلی اللہ علیہ وسلم گھوڑے سے گر پڑے جس سے آپ کا دایاں پہلو چھل گیا ... آگے سابقہ حدیث کے مانند حدیث بیان کی، اس میں یونس اور مالک والا اضافہ نہیں ہے۔"}],[857,"عبدہ بن سلیمان نے ہشام ( بن عروہ ) سے روایت کی ، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بیمار ہو گئے ، آپ کے صحابہ میں سے کچھ لوگ آپ کے پاس آپ کی بیمار پرسی کے لیے حاضر ہوئے ۔ رسول اللہ صلی اللہ علیہ وسلم نے بیٹھ کر نماز پڑھی تو انہوں نے آپ کی اقتدا میں کھڑے ہو کر نماز پڑھنی شروع کی ۔ آپ نے انہیں اشارہ کیا کہ بیٹھ جاؤ تو وہ بیٹھ گئے ۔ جب آپ نماز سے فارغ ہو گئے تو آپ نے فرمایا : ’’ امام اسی لیے بنایا جاتا ہے کہ اس کی اقتدا کی جائے ، جب وہ رکوع کرے تو تم رکوع کرو اور جب وہ ( رکوع وسجود سے سر ) اٹھائے تو ( پھر ) تم ( بھی سر ) اٹھاؤ اور جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو ۔ ‘‘","",{"u2":"عبدہ بن سلیمان نے ہشام (بن عروہ) سے روایت کی، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بیمار ہو گئے، آپ کے صحابہ میں سے کچھ لوگ آپ کے پاس آپ کی بیمار پرسی کے لیے حاضر ہوئے۔ رسول اللہ صلی اللہ علیہ وسلم نے بیٹھ کر نماز پڑھی تو انہوں نے آپ کی اقتدا میں کھڑے ہو کر نماز پڑھنی شروع کی۔ آپ نے انہیں اشارہ کیا کہ بیٹھ جاؤ تو وہ بیٹھ گئے۔ جب آپ نماز سے فارغ ہو گئے تو آپ نے فرمایا: ’’ امام اسی لیے بنایا جاتا ہے کہ اس کی اقتدا کی جائے، جب وہ رکوع کرے تو تم رکوع کرو اور جب وہ (رکوع وسجود سے سر) اٹھائے تو (پھر) تم (بھی سر) اٹھاؤ اور جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو۔‘‘"}],[858,"۔ حماد بن زید اور عبد اللہ بن نمیر نے ہشام بن عروہ سے باقی ماندہ سابقہ سند کے ساتھ اسی کے مانند روایت بیان کی ۔","",{"u2":"۔ حماد بن زید اور عبد اللہ بن نمیر نے ہشام بن عروہ سے باقی ماندہ سابقہ سند کے ساتھ اسی کے مانند روایت بیان کی۔"}],[859,"۔ لیث نے ابو زبیر سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم كی بیماری میں ہم نے آپ كے پیچھے اس طرح نماز پڑھی كہ آپ نے بیٹھ كر نماز پڑھائی اور سیدنا صدیق اكبر رضی اللہ عنہ مكبر كی حیثیت میں تكبیرات كہتے تھے . نماز میں ہمیں كھڑا دیكھ كر آپ صلی اللہ علیہ وسلم نے ہمیں بیٹھنے كا حكم دیا تو ہم بیٹھ گئے پھر بعد فراغت نماز ارشاد عالی ہوا تم نے اس وقت وہ كام كیا جیسا كہ فارس اور روم والے اپنے بادشاہ كے سامنے كھڑے رہتے ہیں اور بادشاہ بیٹھا رہتا ہے . اب آئندہ ایسا نہ كرنا بلكہ ہمیشہ اپنے امام كی پیروی كرو اگر وہ بیٹھ كر نماز پڑھائے تو تم بھی بیٹھ كر نماز پڑھو ","",{"u2":"۔ لیث نے ابو زبیر سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بیمار پڑ گئے اور ہم نے آپ کی اقتدا میں نماز پڑھی جبکہ آ ý ÈیŠªÿ ÀæÆÿ Êªÿ ÇæÑ ÇÈæ È˜Ñ رضی اللہ عنہ Â ˜ی Ê˜ÈیÑ áææŸ ˜æ ÓäÇ ÑÀÿ Êªÿ۔ Â äÿ ÀãÇÑی ØÑÝ ÊæÌÀ ÝÑãÇÆی ÇæÑ ÀãیŸ ˜ªšÿ ÀæÆÿ Ïی˜ªÇ Êæ Â äÿ ÀãیŸ ÇÔÇÑÀ ÝÑãÇیÇ (ÌÓ Ñ) Àã ÈیŠª Æÿ ÇæÑ Àã äÿ Â ˜ی ÇÞÊÏÇء میں بیٹھ کر نماز پڑھی۔ جب آپ نے سلام پھیرا تو فرمایا: ’’ تم ابھی وہ کام کرنے لگے جو فارسی اور رومی کرتے ہیں، وہ اپنے بادشاہوں کے سامنے کھڑے ہوتے ہیں، حالانکہ وہ (بادشاہ) بیٹھے ہوتے ہیں۔ ایسا نہ کیا کرو، اپنے ائمہ کی اقتدا کرو، (امام) اگر کھڑا ہو کر نماز پڑھے تو تم بھی کھڑے ہو کر نماز پڑھو اور اگر وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو۔‘‘"}],[860,"۔ سیدنا جابر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی اور ابو بکر رضی اللہ عنہ آپ کے پیچھے تھاے ۔ جب رسول اللہ صلی اللہ علیہ وسلم تکبیر کہتے تو ابو بکر رضی اللہ عنہ بھی تکبیر کہتے تاکہ ہمیں سنائیں .... پھر لیث کی مذکورہ بالا روایت کی طرح بیان کیا ۔","",{"u2":"۔ عبد الرحمان رؤاسی نے ابو زبیر سے اور انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی اور ابو بکر رضی اللہ عنہ آپ کے پیچھے تھاے۔ جب رسول اللہ صلی اللہ علیہ وسلم تکبیر کہتے تو ابو بکر رضی اللہ عنہ بھی تکبیر کہتے تاکہ ہمیں سنائیں .... پھر لیث کی مذکورہ بالا روایت کی طرح بیان کیا۔"}],[861,"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’امام اقتدا ہی کے لیے بنایا گیا ہے ، اس لیے اس کی مخالفت نہ کرو ، چنانچہ جب وہ تکبیر کہے تو تم تکبیر کہو اور جب وہ رکوع کرے تو تم رکوع کرو اور جب وہ سمع اللہ لمن حمده كہے تو تم اللهم ، ربنا لك الحمد کہو اور جب وہ سجدہ کرے تو تم سجدہ کرو اور جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو ۔ ‘‘","",{"u2":"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’امام اقتدا ہی کے لیے بنایا گیا ہے، اس لیے اس کی مخالفت نہ کرو، چنانچہ جب وہ تکبیر کہے تو تم تکبیر کہو اور جب وہ رکوع کرے تو تم رکوع کرو اور جب وہ سمع اللہ لمن حمدہ کہے تو تم اللہم، ربنا لک الحمد کہو اور جب وہ سجدہ کرے تو تم سجدہ کرو اور جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو۔‘‘"}],[862,"ہمام بن منبہ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی ( سابقہ حدیث ) کے مانند روایت بیان کی ۔","",{"u2":"ہمام بن منبہ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی (سابقہ حدیث) کے مانند روایت بیان کی۔"}],[863,"اعمش نے ابو صالح سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ہمیں تعلیم دیتے تھے ، فرماتے تھے : ’’ امام سے آگے نہ بڑھو ، جب وہ تکبیر کہے تو تم تکبیر کہو ، جب وہ ﴿ولا الضالين﴾ کہے تو تم آمین کہو اور جب وہ رکوع کرے تو تم رکوع کرو اور جب وہ سمع اللہ لمن حمده کہے تو تم اللهم ، ربنا لك الحمد کہو ۔ ‘‘","",{"u2":"اعمش نے ابو صالح سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں تعلیم دیتے تھے، فرماتے تھے: ’’ امام سے آگے نہ بڑھو، جب وہ تکبیر کہے تو تم تکبیر کہو، جب وہ ﴿ولا الضالین﴾ کہے تو تم آمین کہو اور جب وہ رکوع کرے تو تم رکوع کرو اور جب وہ سمع اللہ لمن حمدہ کہے تو تم اللہم، ربنا لک الحمد کہو۔‘‘"}],[864,"۔ سہیل بن ابی صالح نے اپنے والد ( ابو صالح ) سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی ( سابقہ حدیث ) کے ہم معنیٰ روایت کی ، سوائے اس حصے کے : ’’ جب وہ ﴿ولا الضالين﴾ کہے تو تم آمین کہو ‘‘ اور یہ حصہ بڑھایا : ’’ اور تم اس سے پہلے ( سر ) نہ اٹھاؤ ۔ ‘‘","",{"u2":"۔ سہیل بن ابی صالح نے اپنے والد (ابو صالح) سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی (سابقہ حدیث) کے ہم معنیٰ روایت کی، سوائے اس حصے کے: ’’ جب وہ ﴿ولا الضالین﴾ کہے تو تم آمین کہو‘‘ اور یہ حصہ بڑھایا: ’’ اور تم اس سے پہلے (سر) نہ اٹھاؤ۔‘‘"}],[865,"ابو علقمہ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ یقینا امام ایک ڈھال ہے ( تم اس کے پیچھے پیچھے رہو ) ، چنانچہ جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو اور جب وہ سمع اللہ لمن حمده كہے تو تم اللهم ، ربنا لك الحمد کہو کیونکہ جب زمین والے کا کہا ہوا آسمان والوں کے کہنے کے موافق ہو جائے گا تو اس کے سابقہ گناہ بخش دیے جائیں گے ۔ ‘‘","",{"u2":"ابو علقمہ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ یقینا امام ایک ڈھال ہے (تم اس کے پیچھے پیچھے رہو)، چنانچہ جب وہ بیٹھ کر نماز پڑھے تو تم بھی بیٹھ کر نماز پڑھو اور جب وہ سمع اللہ لمن حمدہ کہے تو تم اللہم، ربنا لک الحمد کہو کیونکہ جب زمین والے کا کہا ہوا آسمان والوں کے کہنے کے موافق ہو جائے گا تو اس کے سابقہ گناہ بخش دیے جائیں گے۔‘‘"}],[866,"(ابو علقمہ کے بجائے ) ابو ہریرہ رضی اللہ عنہ کے آزاد کردہ غلام ابو یونس نے حدیث بیان کی ، کہا : میں نے ابو ہریرہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے سنا کہ آپ صلی اللہ علیہ وسلم نے فرمایا : ’’امام اس لیے بنایا گیا ہے کہ اس کی پیروی کی جائے ، جب وہ تکبیر کہے تو تم تکبیر کہو اور جب وہ رکوع کرے تو تم رکوع اور جب وہ سمع اللہ لمن حمده کہے تو تم اللهم ، ربنا لك الحمد کہو ، اور جب وہ کھڑا ہو کر نماز پڑھے تو تم بھی کھڑے ہو کر پڑھو اور جب وہ بیٹھ کر پڑھے تو تم بھی سب کے سب بیٹھ کر نماز پڑھو ۔ ‘‘"],[867,"موسیٰ بن ابی عائشہ نے عبید اللہ بن عبد اللہ سے روایت کی ، انہوں نے کہا : میں سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوا اور ان سے کہا : کیا آپ مجھے رسول اللہ صلی اللہ علیہ وسلم کی بیماری کے بارے میں نہیں بتائیں گی؟ انہوں نے کہا : کیوں نہیں! جب ( بیماری کے سبب ) نبی ( کے حرکات وسکنات ) بوجھل ہونے لگے تو آپ نے فرمایا : ’’ کیا لوگوں نے نماز پڑھ لی؟ ‘‘ ہم نے عرض کی : اللہ کے رسول! نہیں ، وہ سب آپ کا انتظار کر رہے ہیں ۔ آپ نے فرمایا : میرے لیے بڑے طشت میں پانی رکھو ۔ ‘‘ ہم نے پانی رکھا تو آپ نے غسل فرمایا : پھر آپ نے اٹھنے کی کوشش کی تو آپ پر بے ہوشی طاری ہو گئی ، پھر آپ کو افاقہ ہوا تو فرمایا : ’’ کیا لوگوں نے نماز پڑھی لی؟ ‘‘ ہم نے کہا : نہیں ، اللہ کے رسول! وہ آپ کے منتظر ہیں ۔ آپ نے فرمایا : ’’ میرے لیے بڑے طشت میں پانی رکھو ۔ ‘‘ ہم نے رکھا تو آپ نے غسل فرمایا : پھر آپ اٹھنے لگے توآپ پر غشی طاری ہو کئی ، پھر ہوش میں آئے تو فرمایا : ’’ کیا لوگوں نے نماز پڑھ لی ہے؟ ‘‘ ہم نے کہا : نہیں ، اللہ کے رسول! وہ آپ کا انتظار کر رہے ہیں ۔ آپ نے فرمایا : ’’میرے لیے بڑے طشت میں پانی رکھو ۔ ‘‘ ہم نے رکھا تو آپ نے غسل فرمایا : پھر اٹھنے لگے تو بے شہوش ہو گئے ، پھر ہوش میں آئے تو فرمایا : ’’ کیا لوگوں نے نماز پڑھ لی؟ ‘‘ ہم نے کہا : نہیں ، اللہ کے رسول! وہ رسول اللہ صلی اللہ علیہ وسلم کا انتظار کرر ہے ہیں ۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا : لوگ مسجد میں اکٹھے بیٹھے ہوئے عشاء کی نماز کے لیے رسول اللہ صلی اللہ علیہ وسلم کا انتظار کر رہے تھے ۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا : پھر رسول اللہ صلی اللہ علیہ وسلم نے ابو بکر رضی اللہ عنہ کی طرف پیغام بھیجا کہ وہ لوگوں کو نماز پڑھائیں ۔ پیغام لانے والا ان کے پاس آیا اور بولا : رسول اللہ صلی اللہ علیہ وسلم آپ کو حکم دے رہے ہیں کہ آپ لوگوں کو نماز پڑھائیں ۔ ابو بکر رضی اللہ عنہ نے کہا ، اور وہ بہت نرم دل انسان تھے : عمر! آپ لوگوں کو نماز پڑھائیں ۔ عمر رضی اللہ عنہ نے کہا : آپ ہی اس کے زیادہ حقدار ہیں ۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا : ان دنوں ابو بکر رضی اللہ عنہ نے لوگوں کو نماز پڑھائی ، پھر یہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ تخفیف محسوس فرمائی تو دو مردوں کا سہارا لے کر ، جن میں سے ایک عباس رضی اللہ عنہ تھے ، نماز ظہر کے لیے نکلے ، ( اس وقت ) ابو بکر رضی اللہ عنہ لوگوں کو نماز پڑھا رہے تھے ، جب ابوبکر رضی اللہ عنہ نے آپ کو دیکھا تو پیچھے ہٹنے لگے ، اس پر نبی صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ پیچھے نہ ہٹیں اور آپ نے ان دونوں سے فرمایا : ’’ مجھے ان کے پہلو میں بٹھا دو ۔ ‘‘ ان دونوں نے آپ کو ابوبکر رضی اللہ عنہ کے پہلو میں بٹھا دیا ، ابو بکر رضی اللہ عنہ کھڑے ہو کر نبی صلی اللہ علیہ وسلم کی اقتدا میں نماز پڑھ رہے تھے اور لوگ ابو بکر رضی اللہ عنہ کی نماز کی اقتدا کر رہے تھے اور نبی صلی اللہ علیہ وسلم بیٹھے ہوئے تھے ۔ ( سیدہ عائشہ رضی اللہ عنہا سے روایت کرنے والے راوی ) عبید اللہ نے کہا : پھر میں سیدنا عبد اللہ بن عباس رضی اللہ عنہ کی خدمت میں حاضر ہوا اور ان سے عرض کی : کیا میں آپ کے سامنے وہ حدیث پیش نہ کروں ، جو سیدہ عائشہ رضی اللہ عنہا نے مجھے نبی صلی اللہ علیہ وسلم کی بیماری کے بارے میں بیان کی ہے؟ انہوں نے کہا : لاؤ ۔ تو میں نے ان کے سامنے عائشہ رضی اللہ عنہا کی حدیث پیش کی ، انہوں نے اس میں سے کسی بات کا انکار نہ کیا ، ہاں! اتنا کہا : کیا سیدہ عائشہ رضی اللہ عنہ نے تمہیں اس آدمی کا نام بتایا جو عباس رضی اللہ عنہ کے ساتھ تھے؟ میں نے کہا : نہیں ۔ انہوں نے کہا : وہ سیدنا علی رضی اللہ عنہ تھے ۔","",{"u2":"موسیٰ بن ابی عائشہ نے عبید اللہ بن عبد اللہ سے روایت کی، انہوں نے کہا: میں سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوا اور ان سے کہا: کیا آپ مجھے رسول اللہ صلی اللہ علیہ وسلم کی بیماری کے بارے میں نہیں بتائیں گی؟ انہوں نے کہا: کیوں نہیں! جب (بیماری کے سبب) نبی (کے حرکات وسکنات) بوجھل ہونے لگے تو آپ نے فرمایا: ’’ کیا لوگوں نے نماز پڑھ لی؟‘‘ ہم نے عرض کی: اللہ کے رسول! نہیں، وہ سب آپ کا انتظار کر رہے ہیں۔ آپ نے فرمایا: میرے لیے بڑے طشت میں پانی رکھو۔‘‘ ہم نے پانی رکھا تو آپ نے غسل فرمایا: پھر آپ نے اٹھنے کی کوشش کی تو آپ پر بے ہوشی طاری ہو گئی، پھر آپ کو افاقہ ہوا تو فرمایا: ’’ کیا لوگوں نے نماز پڑھی لی؟‘‘ ہم نے کہا: نہیں، اللہ کے رسول! وہ آپ کے منتظر ہیں۔ آپ نے فرمایا: ’’ میرے لیے بڑے طشت میں پانی رکھو۔‘‘ ہم نے رکھا تو آپ نے غسل فرمایا: پھر آپ اٹھنے لگے توآپ پر غشی طاری ہو کئی، پھر ہوش میں آئے تو فرمایا: ’’ کیا لوگوں نے نماز پڑھ لی ہے؟‘‘ ہم نے کہا: نہیں، اللہ کے رسول! وہ آپ کا انتظار کر رہے ہیں۔ آپ نے فرمایا: ’’میرے لیے بڑے طشت میں پانی رکھو۔‘‘ ہم نے رکھا تو آپ نے غسل فرمایا: پھر اٹھنے لگے تو بے شہوش ہو گئے، پھر ہوش میں آئے تو فرمایا: ’’ کیا لوگوں نے نماز پڑھ لی؟‘‘ ہم نے کہا: نہیں، اللہ کے رسول! وہ رسول اللہ صلی اللہ علیہ وسلم کا انتظار کرر ہے ہیں۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: لوگ مسجد میں اکٹھے بیٹھے ہوئے عشاء کی نماز کے لیے رسول اللہ صلی اللہ علیہ وسلم کا انتظار کر رہے تھے۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: پھر رسول اللہ صلی اللہ علیہ وسلم نے ابو بکر رضی اللہ عنہ کی طرف پیغام بھیجا کہ وہ لوگوں کو نماز پڑھائیں۔ پیغام لانے والا ان کے پاس آیا اور بولا: رسول اللہ صلی اللہ علیہ وسلم آپ کو حکم دے رہے ہیں کہ آپ لوگوں کو نماز پڑھائیں۔ ابو بکر رضی اللہ عنہ نے کہا، اور وہ بہت نرم دل انسان تھے: عمر! آپ لوگوں کو نماز پڑھائیں۔ عمر رضی اللہ عنہ نے کہا: آپ ہی اس کے زیادہ حقدار ہیں۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: ان دنوں ابو بکر رضی اللہ عنہ نے لوگوں کو نماز پڑھائی، پھر یہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ تخفیف محسوس فرمائی تو دو مردوں کا سہارا لے کر، جن میں سے ایک عباس رضی اللہ عنہ تھے، نماز ظہر کے لیے نکلے، (اس وقت) ابو بکر رضی اللہ عنہ لوگوں کو نماز پڑھا رہے تھے، جب ابوبکر رضی اللہ عنہ نے آپ کو دیکھا تو پیچھے ہٹنے لگے، اس پر نبی صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ پیچھے نہ ہٹیں اور آپ نے ان دونوں سے فرمایا: ’’ مجھے ان کے پہلو میں بٹھا دو۔‘‘ ان دونوں نے آپ کو ابوبکر رضی اللہ عنہ کے پہلو میں بٹھا دیا، ابو بکر رضی اللہ عنہ کھڑے ہو کر نبی صلی اللہ علیہ وسلم کی اقتدا میں نماز پڑھ رہے تھے اور لوگ ابو بکر رضی اللہ عنہ کی نماز کی اقتدا کر رہے تھے اور نبی صلی اللہ علیہ وسلم بیٹھے ہوئے تھے۔\n(سیدہ عائشہ رضی اللہ عنہا سے روایت کرنے والے راوی) عبید اللہ نے کہا: پھر میں سیدنا عبد اللہ بن عباس رضی اللہ عنہ کی خدمت میں حاضر ہوا اور ان سے عرض کی: کیا میں آپ کے سامنے وہ حدیث پیش نہ کروں، جو سیدہ عائشہ رضی اللہ عنہا نے مجھے نبی صلی اللہ علیہ وسلم کی بیماری کے بارے میں بیان کی ہے؟ انہوں نے کہا: لاؤ۔ تو میں نے ان کے سامنے عائشہ رضی اللہ عنہا کی حدیث پیش کی، انہوں نے اس میں سے کسی بات کا انکار نہ کیا، ہاں! اتنا کہا: کیا سیدنا عائشہ رضی اللہ عنہ نے تمہیں اس آدمی کا نام بتایا جو عباس رضی اللہ عنہ کے ساتھ تھے؟ میں نے کہا: نہیں۔ انہوں نے کہا: وہ سیدنا علی رضی اللہ عنہ تھے۔"}],[868,"معمر نے بیان کیا کہ زہری نے کہا : مجھے عبید اللہ بن عبد اللہ بن عتبہ نے خبر دی کہ سیدہ عائشہ رضی اللہ عنہا نے اسے خبر کہ رسول اللہ صلی اللہ علیہ وسلم کی بیماری کا آغاز میمونہ رضی اللہ عنہا کے گھر سے ہوا ، آپ نے اپنی بیویوں سے اجازت مانگی کہ آپ کی تیمار داری میرے گھر میں کی جائے ، انہوں نے اجازت دے دی ۔ ( عائشہ رضی اللہ عنہا نے ) فرمایا : آپ اس طرح نکلے کہ آپ کا ایک ہاتھ فضل بن عباس رضی اللہ عنہ ( کے کندھے ) پر اور دوسرا ہاتھ ایک دوسرے آدمی پر تھا اور ( نقاہت کی وجہ سے ) آپ اپنے باؤں سے زمین پر لکیر بناتے جا رہے تھے ۔ عبید اللہ نے بیان کیا کہ میں نے یہ حدیث ابن عباس رضی اللہ عنہ کو سنائی تو انہوں نے کہا : کیا تم جانتے ہو وہ آدمی ، جس کا سیدہ عائشہ رضی اللہ عنہا نے نام نہیں لیا ، کون تھے؟ وہ علی رضی اللہ عنہ تھا","",{"u2":"معمر نے بیان کیا کہ زہری نے کہا: مجھے عبید اللہ بن عبد اللہ بن عتبہ نے خبر دی کہ سیدہ عائشہ رضی اللہ عنہا نے اسے خبر کہ رسول اللہ صلی اللہ علیہ وسلم کی بیماری کا آغاز میمونہ رضی اللہ عنہا کے گھر سے ہوا، آپ نے اپنی بیویوں سے اجازت مانگی کہ آپ کی تیمار داری میرے گھر میں کی جائے، انہوں نے اجازت دے دی۔ (عائشہ رضی اللہ عنہا نے) فرمایا: آپ اس طرح نکلے کہ آپ کا ایک ہاتھ فضل بن عباس رضی اللہ عنہ (کے کندھے) پر اور دوسرا ہاتھ ایک دوسرے آدمی پر تھا اور (نقاہت کی وجہ سے) آپ اپنے باؤں سے زمین پر لکیر بناتے جا رہے تھے۔ عبید اللہ نے بیان کیا کہ میں نے یہ حدیث ابن عباس رضی اللہ عنہ کو سنائی تو انہوں نے کہا: کیا تم جانتے ہو وہ آدمی، جس کا سیدہ عائشہ رضی اللہ عنہا نے نام نہیں لیا، کون تھے؟ وہ علی رضی اللہ عنہ تھا"}],[869,"عقیل بن خالد نے کہا : ابن شہاب ( زہری ) نے کہا : مجھے عبید اللہ بن عبد اللہ بن عتبہ بن مسعود نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم کی بیماری شدت اختیار کر گئی اور آپ کی تکلیف میں اضافہ ہو گیا تو آپ نے اپنی بیویوں سے اجازت طلب کی کہ ان کی تیمار داری میرے گھر میں ہو ، انہوں نے اجازت دے دی ، پھر آپ دو آدمیوں کے درمیان ( ان کا سہارا لے کر ) نکلے ، آپ کے دونوں پاؤں زمین پر لکیر بناتے جا رہے تھے ( اور آپ ) عباس بن عبد المطلب رضی اللہ عنہ اور ایک دوسرے آدمی کے درمیان تھے ۔ ( حدیث کے راوی ) عبید اللہ نے کہا : عائشہ رضی اللہ عنہا نے جو کچھ کہا تھا ، میں نے اس کا تذکرہ عبد اللہ ( بن عباس ) رضی اللہ عنہما سے کیا تو انہوں نے مجھ سے کہا : کیا تم جانتے ہو وہ آدمی کون تھا جس کا سیدہ عائشہ رضی اللہ عنہا نے نام نہیں لیا؟ انہوں نے کہا : میں نے کہا : نہیں ۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا : وہ سیدنا علی بن ابی طالب رضی اللہ عنہ تھے ۔","",{"u2":"عقیل بن خالد نے کہا: ابن شہاب (زہری) نے کہا: مجھے عبید اللہ بن عبد اللہ بن عتبہ بن مسعود نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم کی بیماری شدت اختیار کر گئی اور آپ کی تکلیف میں اضافہ ہو گیا تو آپ نے اپنی بیویوں سے اجازت طلب کی کہ ان کی تیمار داری میرے گھر میں ہو، انہوں نے اجازت دے دی، پھر آپ دو آدمیوں کے درمیان (ان کا سہارا لے کر) نکلے، آپ کے دونوں پاؤں زمین پر لکیر بناتے جا رہے تھے (اور آپ) عباس بن عبد المطلب رضی اللہ عنہ اور ایک دوسرے آدمی کے درمیان تھے۔\n(حدیث کے راوی) عبید اللہ نے کہا: عائشہ رضی اللہ عنہا نے جو کچھ کہا تھا، میں نے اس کا تذکرہ عبد اللہ (بن عباس) رضی اللہ عنہما سے کیا تو انہوں نے مجھ سے کہا: کیا تم جانتے ہو وہ آدمی کون تھا جس کا سیدہ عائشہ رضی اللہ عنہا نے نام نہیں لیا؟ انہوں نے کہا: میں نے کہا: نہیں۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا: وہ سیدنا علی بن ابی طالب رضی اللہ عنہ تھے۔"}],[870,"۔ عبید اللہ بن عبد اللہ بن عتبہ بن مسعود نے خبر دی کہ نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا نے کہا کہ میں نے ( سیدنا ابو بکر رضی اللہ عنہ کو امام بنانے کے ) اس معاملے میں رسول اللہ صلی اللہ علیہ وسلم سے بار بار بات کی ۔ میں نے اتنی بار آپ سے صرف اس لیے رجوع کیا کہ میرے دل میں یہ بات بیٹھتی نہ تھی کہ لوگ آپ کے بعد کبھی اس شخص سے محبت کریں گے جو آپ کا قائم مقام ہو گا اور اس کے برعکس میرا خیال یہ تھا کہ آپ کی جگہ پر جو شخص بھی کھڑا ہو گا لوگ اسے برا ( برے شگون کا حامل ) سمجھیں گے ، اس لیے میں چاہتی تھی کہ رسول اللہ صلی اللہ علیہ وسلم امامت ( کی ذمہ داری ) ابو بکر سے ہٹا دیں ۔","",{"u2":"۔ عبید اللہ بن عبد اللہ بن عتبہ بن مسعود نے خبر دی کہ نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا نے کہا کہ میں نے (سیدنا ابو بکر رضی اللہ عنہ کو امام بنانے کے) اس معاملے میں رسول اللہ صلی اللہ علیہ وسلم سے بار بار بات کی۔ میں نے اتنی بار آپ سے صرف اس لیے رجوع کیا کہ میرے دل میں یہ بات بیٹھتی نہ تھی کہ لوگ آپ کے بعد کبھی اس شخص سے محبت کریں گے جو آپ کا قائم مقام ہو گا اور اس کے برعکس میرا خیال یہ تھا کہ آپ کی جگہ پر جو شخص بھی کھڑا ہو گا لوگ اسے برا (برے شگون کا حامل) سمجھیں گے، اس لیے میں چاہتی تھی کہ رسول اللہ صلی اللہ علیہ وسلم امامت (کی ذمہ داری) ابو بکر سے ہٹا دیں۔"}],[871,"۔ ( عبید اللہ بن عبد اللہ کے بجائے ) حمزہ بن عبد اللہ بن عمر نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا کہ جب رسول اللہ صلی اللہ علیہ وسلم ( بیماری کے دوران میں ) میرے گھر تشریف لے آئے تو آپ نے فرمایا : ’’ابو بکر کو حکم پہنچاؤ کہ وہ لوگوں کو نماز پڑھائیں ۔ ‘‘ وہ کہتی ہیں : میں نے عرض کی : اے اللہ کے رسول! ابو بکر نرم دل انسان ہیں ، جب وہ قرآن پڑھیں گے تو اپنے آنسوؤں پر قابو نہیں رکھ سکیں گے ، لہٰذا اگر آپ ابو بکر رضی اللہ عنہ کے بجائے کسی اور کو حکم دیں ( تو بہتر ہو گا ۔ ) عائشہ رضی اللہ عنہا فرماتی ہیں : اللہ کی قسم! میرے دل میں اس چیز کو ناپسند کرنے کی اس کے علاوہ اور کوئی بات نہ تھی کہ جو شخص سب سے پہلے آپ کی جگہ کھڑا ہو گا لوگ اسے برا سمجھیں گے ، اس لیے میں نے دو یا تین دفعہ اپنی بات دہرائی تو آپ نے فرمایا : ’’ابو بکر ہی لوگوں کو نماز پڑھائیں ، بلاشبہ تم یوسف رضی اللہ عنہ کے ساتھ ( معاملہ کرنے ) والی عورتیں ہی ہو ۔ ‘‘","",{"u2":"۔ (عبید اللہ بن عبد اللہ کے بجائے) حمزہ بن عبد اللہ بن عمر نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا کہ جب رسول اللہ صلی اللہ علیہ وسلم (بیماری کے دوران میں) میرے گھر تشریف لے آئے تو آپ نے فرمایا: ’’ابو بکر کو حکم پہنچاؤ کہ وہ لوگوں کو نماز پڑھائیں۔‘‘ وہ کہتی ہیں: میں نے عرض کی: اے اللہ کے رسول! ابو بکر نرم دل انسان ہیں، جب وہ قرآن پڑھیں گے تو اپنے آنسوؤں پر قابو نہیں رکھ سکیں گے، لہٰذا اگر آپ ابو بکر رضی اللہ عنہ کے بجائے کسی اور کو حکم دیں (تو بہتر ہو گا۔) عائشہ رضی اللہ عنہا فرماتی ہیں: اللہ کی قسم! میرے دل میں اس چیز کو ناپسند کرنے کی اس کے علاوہ اور کوئی بات نہ تھی کہ جو شخص سب سے پہلے آپ کی جگہ کھڑا ہو گا لوگ اسے برا سمجھیں گے، اس لیے میں نے دو یا تین دفعہ اپنی بات دہرائی تو آپ نے فرمایا: ’’ابو بکر ہی لوگوں کو نماز پڑھائیں، بلاشبہ تم یوسف علیہ السلام کے ساتھ (معاملہ کرنے) والی عورتیں ہی ہو۔‘‘"}],[872,"ابو معاویہ اور وکیع نے اعمش سے ، انہوں نے ابراہیم سے ، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کہ جب رسول اللہ صلی اللہ علیہ وسلم کی بیماری شدت اختیار کر گئی تو بلال رضی اللہ عنہ آپ کو نماز کی اطلاع دینے کے لیے حاضر ہوئے ۔ آپ نے فرمایا : ’’ ابو بکر سے کہو وہ نماز پڑھائیں ۔ ‘‘ عائشہ رضی اللہ عنہا کہتی ہیں : میں نے عرض کی : اے اللہ کے رسول! ابو بکر جلد غم زدہ ہو جانے والے انسان ہیں اور وہ جب آپ کی جگہ کھڑے ہوں گے تو لوگوں کو ( قراءت بھی ) نہیں سنا سکیں گے ، لہٰذا اگر آپ عمر رضی اللہ عنہ کو حکم دے دیں ( تو بہتر بہتر ہو گا ۔ ) آپ صلی اللہ علیہ وسلم نے ( پھر ) فرمایا : ’’ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں ۔ ‘‘ میں نے حفصہ رضی اللہ عنہا سے کہا : نم نبی اکرم صلی اللہ علیہ وسلم سے کہو کہ ابو بکر جلد غمزدہ ہونے والے انسان ہیں ، جب وہ آپ کی جگہ پر کھڑے ہوں گے تو لوگوں کو ( قراءت ) نہ سنا سکیں ، چنانچہ اگر آپ عمر رضی اللہ عنہ کو حکم دیں ( تو بہتر ہو گا ۔ ) سیدہ حفصہ رضی اللہ عنہا نے آپ سے کہہ دیا تو آپ نے فرمایا : ’’تم یوسف رضی اللہ عنہ کے ساتھ ( معاملہ کرنے ) والی عورتوں ہی طرح ہو ، ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں ۔ ‘‘ عائشہ رضی اللہ عنہا فرماتی ہیں : لوگوں نے ابو بکر رضی اللہ عنہ کو حکم پہنچا دیا تو انہوں نے لوگوں کو نماز پڑھائی ۔ جب ابو بکر رضی اللہ عنہ نے نماز شروع کر دی تو رسول اللہ صلی اللہ علیہ وسلم نے طبیعت میں قدرے تخفیف محسوس کی ، آپ اٹھے ، دو آدمی آپ کو سہارا دیے ہوئے تھے اور آپ کے پاؤں زمین پر لکیر کھینچتے جا رہے تھے ۔ وہ فرماتی ہیں : جب آپ مسجد میں داخل ہوئے تو ابو بکر رضی اللہ عنہ نے آپ کی آہٹ سن لی ، وہ پیچھے ہٹنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ اپنی جگہ کھڑے رہو ، پھر رسول اللہ صلی اللہ علیہ وسلم آگے بڑے اور ابو بکر رضی اللہ عنہ کی بائیں جانب بیٹھ گئے ۔ عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر لوگوں کو نماز پڑھا رہے تھے اور ابو بکر رضی اللہ عنہ کھڑے ہو کر ۔ ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی نماز کی اقتدا کر رہے تھے اور لوگ ابو بکر رضی اللہ عنہ کی اقتدا کر رہے تھے ۔","",{"u2":"ابو معاویہ اور وکیع نے اعمش سے، انہوں نے ابراہیم سے، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کہ جب رسول اللہ صلی اللہ علیہ وسلم کی بیماری شدت اختیار کر گئی تو بلال رضی اللہ عنہ آپ کو نماز کی اطلاع دینے کے لیے حاضر ہوئے۔ آپ نے فرمایا: ’’ ابو بکر سے کہو وہ نماز پڑھائیں۔‘‘ عائشہ رضی اللہ عنہا کہتی ہیں: میں نے عرض کی: اے اللہ کے رسول! ابو بکر جلد غم زدہ ہو جانے والے انسان ہیں اور وہ جب آپ کی جگہ کھڑے ہوں گے تو لوگوں کو (قراءت بھی) نہیں سنا سکیں گے، لہٰذا اگر آپ عمر رضی اللہ عنہ کو حکم دے دیں (تو بہتر بہتر ہو گا۔) آپ صلی اللہ علیہ وسلم نے (پھر) فرمایا: ’’ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔‘‘ میں نے حفصہ رضی اللہ عنہا سے کہا: نم نبی اکرم صلی اللہ علیہ وسلم سے کہو کہ ابو بکر جلد غمزدہ ہونے والے انسان ہیں، جب وہ آپ کی جگہ پر کھڑے ہوں گے تو لوگوں کو (قراءت) نہ سنا سکیں، چنانچہ اگر آپ عمر رضی اللہ عنہ کو حکم دیں (تو بہتر ہو گا۔) سیدہ حفصہ رضی اللہ عنہا نے آپ سے کہہ دیا تو آپ نے فرمایا: ’’تم یوسف علیہ السلام کے ساتھ (معاملہ کرنے) والی عورتوں ہی طرح ہو، ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔‘‘\nعائشہ رضی اللہ عنہا فرماتی ہیں: لوگوں نے ابو بکر رضی اللہ عنہ کو حکم پہنچا دیا تو انہوں نے لوگوں کو نماز پڑھائی۔ جب ابو بکر رضی اللہ عنہ نے نماز شروع کر دی تو رسول اللہ صلی اللہ علیہ وسلم نے طبیعت میں قدرے تخفیف محسوس کی، آپ اٹھے، دو آدمی آپ کو سہارا دیے ہوئے تھے اور آپ کے پاؤں زمین پر لکیر کھینچتے جا رہے تھے۔ وہ فرماتی ہیں: جب آپ مسجد میں داخل ہوئے تو ابو بکر رضی اللہ عنہ نے آپ کی آہٹ سن لی، وہ پیچھے ہٹنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ اپنی جگہ کھڑے رہو، پھر رسول اللہ صلی اللہ علیہ وسلم آگے بڑے اور ابو بکر رضی اللہ عنہ کی بائیں جانب بیٹھ گئے۔ عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر لوگوں کو نماز پڑھا رہے تھے اور ابو بکر رضی اللہ عنہ کھڑے ہو کر۔ ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی نماز کی اقتدا کر رہے تھے اور لوگ ابو بکر رضی اللہ عنہ کی اقتدا کر رہے تھے۔"}],[873,"۔ علی بن مسہر اور عیسیٰ بن یونس نے اعمش سے اسی سند کے ساتھ مذکورہ بالا روایت بیان کی ۔ ان دونوں کی حدیث میں ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم اس مرض میں مبتلا ہوئے جس میں آپ نے وفات پائی ۔ ابن مسہر کی روایت میں ہے : رسول اللہ صلی اللہ علیہ وسلم کو لایا گیا یہاں تک کہ انہیں ابو بکر رضی اللہ عنہ کے پہلو میں بٹھا دیا گیا ۔ رسول اللہ صلی اللہ علیہ وسلم لوگوں کو نماز پڑھا رہے تھے اور ابو بکر رضی اللہ عنہ لوگوں کو تکبیر سنا رہے تھے ۔ عیسیٰ کی روایت میں ہے : رسول اللہ صلی اللہ علیہ وسلم بیٹھ گئے اور لوگوں کو نماز پڑھانے لگے ، ابو بکر رضی اللہ عنہ آپ کے پہلو میں تھے اور لوگوں کو ( آپ کی تکبیر ) سنا رہے تھے ۔","",{"u2":"۔ علی بن مسہر اور عیسیٰ بن یونس نے اعمش سے اسی سند کے ساتھ مذکورہ بالا روایت بیان کی۔ ان دونوں کی حدیث میں ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم اس مرض میں مبتلا ہوئے جس میں آپ نے وفات پائی۔ ابن مسہر کی روایت میں ہے: رسول اللہ صلی اللہ علیہ وسلم کو لایا گیا یہاں تک کہ انہیں ابو بکر رضی اللہ عنہ کے پہلو میں بٹھا دیا گیا۔ رسول اللہ صلی اللہ علیہ وسلم لوگوں کو نماز پڑھا رہے تھے اور ابو بکر رضی اللہ عنہ لوگوں کو تکبیر سنا رہے تھے۔ عیسیٰ کی روایت میں ہے: رسول اللہ صلی اللہ علیہ وسلم بیٹھ گئے اور لوگوں کو نماز پڑھانے لگے، ابو بکر رضی اللہ عنہ آپ کے پہلو میں تھے اور لوگوں کو (آپ کی تکبیر) سنا رہے تھے۔"}],[874,"ایک اور سند کے ساتھ ہشام نے اپنے والد ( عروہ ) سے روایت کی اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے فرمایا : رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیماری میں ابو بکر رضی اللہ عنہ کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں تو وہ ان کو نماز پڑھاتے رہے ۔ عروہ نے کہا : پھر رسول اللہ صلی اللہ علیہ وسلم نے اپنی طبیعت میں کچھ ہلکا پن محسوس کیا ، تو آپ باہر تشریف لائے ، اس وقت ابو بکر رضی اللہ عنہ لوگوں کی امت کر رہے تھے ۔ جب ابو بکر رضی اللہ عنہ نے آپ کو دیکھا تو پیچھے ہٹنے لگے ۔ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ جیسے ہو ویسے ہی رہو ۔ رسول اللہ صلی اللہ علیہ وسلم ابو بکر رضی اللہ عنہ کے برابر ان کے پہلو میں بیٹھ گئے تو ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی امامت میں نماز ادا کر رہے تھے اور لوگ ابو بکر رضی اللہ عنہ کی اقتدا میں نماز پڑھ رہے تھے ۔","",{"u2":"ایک اور سند کے ساتھ ہشام نے اپنے والد (عروہ) سے روایت کی اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیماری میں ابو بکر رضی اللہ عنہ کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں تو وہ ان کو نماز پڑھاتے رہے۔\nعروہ نے کہا: پھر رسول اللہ صلی اللہ علیہ وسلم نے اپنی طبیعت میں کچھ ہلکا پن محسوس کیا، تو آپ باہر تشریف لائے، اس وقت ابو بکر رضی اللہ عنہ لوگوں کی امت کر رہے تھے۔ جب ابو بکر رضی اللہ عنہ نے آپ کو دیکھا تو پیچھے ہٹنے لگے۔ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ جیسے ہو ویسے ہی رہو۔ رسول اللہ صلی اللہ علیہ وسلم ابو بکر رضی اللہ عنہ کے برابر ان کے پہلو میں بیٹھ گئے تو ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی امامت میں نماز ادا کر رہے تھے اور لوگ ابو بکر رضی اللہ عنہ کی اقتدا میں نماز پڑھ رہے تھے۔"}],[875,"صالح نے ابن شہاب سے روایت کی ، انہوں نے کہا : سیدنا انس بن مالک رضی اللہ عنہ نے مجھے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی بیماری دوران ، جس میں آپ نے وفات پائی ، ابو بکر رضی اللہ عنہ لوگوں کو نماز پڑھاتے تھے حتیٰ کہ جب سوموار کا دن آیا اور صحابہ کرام رضی اللہ عنہ نماز میں صف بستہ تھے تو رسول اللہ صلی اللہ علیہ وسلم نے حجرے کا پردہ اٹھایا اور ہماری طرف دیکھا ، اس وقت آپ کھڑے ہوئے تھے ، ایسا لگتا تھا کہ آپ کا رخ انور مصحف کا ایک ورق ہے ، پھر آپ نے ہنستے ہوئے تبسم فرمایا ۔ انس رضی اللہ عنہ کہتے ہیں کہ ہم نماز ہی میں اس خوشی کے سبب جو رسول اللہ صلی اللہ علیہ وسلم کے باہر آنے سے ہوئی تھی مبہوت ہو کر رہ گئے ۔ ابو بکر رضی اللہ عنہ الٹے پاؤں لوٹے تالکہ صف میں مل جائیں ، انہوں نے سمجھا کہ نبی صلی اللہ علیہ وسلم نماز کے لیے باہر تشریف لا رہے ہیں ۔ نبی صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اشارہ فرمایا کہ اپنی نماز مکمل کرو ، پھر آپ واپس حجرے میں داخل ہو گئے اور پردہ لٹکا دیا ۔ اسی دن رسول اللہ صلی اللہ علیہ وسلم وفات پا گئے","",{"u2":"صالح نے ابن شہاب سے روایت کی، انہوں نے کہا: سیدنا انس بن مالک رضی اللہ عنہ نے مجھے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کی بیماری دوران، جس میں آپ نے وفات پائی، ابو بکر رضی اللہ عنہ لوگوں کو نماز پڑھاتے تھے حتیٰ کہ جب سوموار کا دن آیا اور صحابہ کرام رضی اللہ عنہم نماز میں صف بستہ تھے تو رسول اللہ صلی اللہ علیہ وسلم نے حجرے کا پردہ اٹھایا اور ہماری طرف دیکھا، اس وقت آپ کھڑے ہوئے تھے، ایسا لگتا تھا کہ آپ کا رخ انور مصحف کا ایک ورق ہے، پھر آپ نے ہنستے ہوئے تبسم فرمایا۔ انس رضی اللہ عنہ کہتے ہیں کہ ہم نماز ہی میں اس خوشی کے سبب جو رسول اللہ صلی اللہ علیہ وسلم کے باہر آنے سے ہوئی تھی مبہوت ہو کر رہ گئے۔ ابو بکر رضی اللہ عنہ الٹے پاؤں لوٹے تالکہ صف میں مل جائیں، انہوں نے سمجھا کہ نبی صلی اللہ علیہ وسلم نماز کے لیے باہر تشریف لا رہے ہیں۔ نبی صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اشارہ فرمایا کہ اپنی نماز مکمل کرو، پھر آپ واپس حجرے میں داخل ہو گئے اور پردہ لٹکا دیا۔ اسی دن رسول اللہ صلی اللہ علیہ وسلم وفات پا گئے"}],[876,"سفیان بن عیینہ نے ( ابن شہاب ) زہری سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم کی طرف میں نے جو آخری نظر ڈالی ( وہ اس طرح تھی کہ ) سوموار کے دن آپ نے ( حجرے کا ) پردہ اٹھایا .... جس طرح اوپر واقعہ ( بیان ہوا ) ہے ۔ ( امام مسلم فرماتے ہیں : ) صالح کی حدیث کامل اور سیر حاصل ہے ۔","",{"u2":"سفیان بن عیینہ نے (ابن شہاب) زہری سے، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم کی طرف میں نے جو آخری نظر ڈالی (وہ اس طرح تھی کہ) سوموار کے دن آپ نے (حجرے کا) پردہ اٹھایا .... جس طرح اوپر واقعہ (بیان ہوا) ہے۔ (امام مسلم فرماتے ہیں:) صالح کی حدیث کامل اور سیر حاصل ہے۔"}],[877,"معمر نے زہری کے حوالے سے خبر دی ، انہوں نے کہا : مجھے سیدنا انس رضی اللہ عنہ نے خبر دی کہ جب سوموار کا دن آیا .... اوپر والے دونوں راویوں کے مطابق ۔","",{"u2":"معمر نے زہری کے حوالے سے خبر دی، انہوں نے کہا: مجھے سیدنا انس رضی اللہ عنہ نے خبر دی کہ جب سوموار کا دن آیا .... اوپر والے دونوں راویوں کے مطابق۔"}],[878,"۔ عبد العزیز نے سیدنا انس رضی اللہ عنہ سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم ( بیماری کے ایام میں ) تین دن ہماری طرف تشریف نہ لائے ، ( انہی دنوں میں سے ) ایک دن نماز کھڑی کی گئی اور ابو بکر رضی اللہ عنہ آگے بڑھنے لگے تو نبی صلی اللہ علیہ وسلم ( کمرے کے ) پردے کی طرف بڑھے اور اسے اٹھا دیا ، جب ہمارے سامنے نبی صلی اللہ علیہ وسلم کا رخ انور کھلا تو ہم نے کبھی ایسا منظر نہ دیکھا تھا جو ہمارے لیے ، نبی صلی اللہ علیہ وسلم کے چہرہ مبارک کے نظارے سے ، جو ہمارے سامنے تھا ، زیادہ حسین اور پسندیدہ ہو ۔ وہ کہتے ہیں : پھر آپ صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ کو ہاتھ سے اشارہ کیا کہ وہ آگے بڑھیں اور آپ نے پردہ گرا دیا ، پھر آپ وفات تک ایسا نہ کر سکے ۔","",{"u2":"۔ عبد العزیز نے سیدنا انس رضی اللہ عنہ سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم (بیماری کے ایام میں) تین دن ہماری طرف تشریف نہ لائے، (انہی دنوں میں سے) ایک دن نماز کھڑی کی گئی اور ابو بکر رضی اللہ عنہ آگے بڑھنے لگے تو نبی صلی اللہ علیہ وسلم (کمرے کے) پردے کی طرف بڑھے اور اسے اٹھا دیا، جب ہمارے سامنے نبی صلی اللہ علیہ وسلم کا رخ انور کھلا تو ہم نے کبھی ایسا منظر نہ دیکھا تھا جو ہمارے لیے، نبی صلی اللہ علیہ وسلم کے چہرہ مبارک کے نظارے سے، جو ہمارے سامنے تھا، زیادہ حسین اور پسندیدہ ہو۔ وہ کہتے ہیں: پھر آپ صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ کو ہاتھ سے اشارہ کیا کہ وہ آگے بڑھیں اور آپ نے پردہ گرا دیا، پھر آپ وفات تک ایسا نہ کر سکے۔"}],[879,"سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم بیمار ہو گئے اور آپ کی بیماری نے شدت اختیار کی تو آپ نے فرمایا : ’’ ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں ۔ ‘‘ اس پر عائشہ رضی اللہ عنہا نے عرض کی : وہ نرم دل آدمی ہیں ، جب آپ کی جگہ کھڑے ہوں گے تو لوگوں کو نماز نہ پڑھا سکیں گے ۔ آپ نے فرمایا : ’’ ( اے عائشہ! ) ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں ، تم تو یوسف رضی اللہ عنہ کے ساتھ ( معاملہ کرنے ) والیوں کی طرح ہو ۔ ‘‘ انہوں ( ابو موسیٰ علیہ السلام ) نے کہا : اس طرح ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں لوگوں کو نماز پڑھانے لگے ۔","",{"u2":"سیدنا ابو موسیٰ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم بیمار ہو گئے اور آپ کی بیماری نے شدت اختیار کی تو آپ نے فرمایا: ’’ ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں۔‘‘ اس پر عائشہ رضی اللہ عنہا نے عرض کی: وہ نرم دل آدمی ہیں، جب آپ کی جگہ کھڑے ہوں گے تو لوگوں کو نماز نہ پڑھا سکیں گے۔ آپ نے فرمایا: ’’ (اے عائشہ!) ابو بکر سے کہو کہ وہ لوگوں کو نماز پڑھائیں، تم تو یوسف علیہ السلام کے ساتھ (معاملہ کرنے) والیوں کی طرح ہو۔‘‘\nانہوں (ابو موسیٰ رضی اللہ عنہ) نے کہا: اس طرح ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں لوگوں کو نماز پڑھانے لگے۔"}],[880,"امام مالک نے ابو حازم سے اور انہوں نے سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بنوعمرو بن عوف کے ہاں ، ان کے درمیان صلح کرانے کے لیے تشریف لے گئے ۔ اس دوران میں نماز کا وقت ہو گیا تو مؤذن ابو بکر رضی اللہ عنہ کے پاس آیا اور کہا : کیا آپ لوگوں کو نماز پڑھائیں گے تاکہ میں تکبیر کہوں؟ ابو بکر رضی اللہ عنہ نے کہا : ہاں ۔ انہوں ( سہل بن سعد ) نے کہا : اس طرح ابو بکر رضی اللہ عنہ نے نماز شروع کر دی ، اتنے میں رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے جب کہ لوگ نماز میں تھے ، آپ بچ کر گزرتے ہوئے ( پہلی ) صف میں پہنچ کر کھڑے ہو گئے ۔ اس پر لوگوں نے ہاتھوں کو ہاتھوں پر مار کر آواز کرنی شروع کر دی ۔ ابو بکر رضی اللہ عنہ اپنی نماز میں کسی اور طرف توجہ نہیں دیتے تھے ۔ جب لوگوں نے مسلسل ہاتھوں سے آواز کی تو وہ متوجہ ہوئے اور رسول اللہ صلی اللہ علیہ وسلم کو دیکھا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ اپنی جگہ کھڑے رہیں ، اس پر ابو بکر رضی اللہ عنہ نے اپنے دونوں ہاتھ اٹھائے اور اللہ کا شکر ادا کیا کہ رسول اللہ رضی اللہ عنہ نے ان کو اس بات کا حکم دیا ، پھر اس کے بعد ابو بکر رضی اللہ عنہ پیچھے ہٹ کر صف میں صحیح طرح کھڑے ہو گئے اور رسول اللہ صلی اللہ علیہ وسلم آگے بڑھے اور آپ نے نماز پڑھائی ۔ جب آپ فارغ ہوئے تو فرمایا : ’’اے ابو بکر! جب میں نے تمہیں حکم دیا تو اپنی جگہ ٹکے رہنے سے تمہیں کس چیز نے روک دیا؟ ‘‘ ابو بکر رضی اللہ عنہ نے کہا : ابو قحافہ کے بیٹے کے لیے زیبا نہ تھا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے آگے ( کھڑے ہو کر ) جماعت کرائے ، پھر رسول اللہ صلی اللہ علیہ وسلم نے ( صحابہ کرام رضی اللہ عنہ کی طرف متوجہ ہو کر ) فرمایا : ’’ کیا ہوا؟ میں نے تم لوگوں کو دیکھا کہ تم بہت تالیاں بجا رہے تھے؟ جب نماز میں تمہیں کوئی ایسی بات پیش آ جائے ( جس پر توجہ دلانا ضروری ہو ) تو سبحان اللہ کہو ، جب کہو سبحان اللہ کہے گا تواس کی طرف توجہ کی جائے گی ، ہاتھ پر ہاتھ مارنا ، صرف عورتوں کےلیے ہے ۔ ‘‘","",{"u2":"امام مالک نے ابو حازم سے اور انہوں نے سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم بنوعمرو بن عوف کے ہاں، ان کے درمیان صلح کرانے کے لیے تشریف لے گئے۔ اس دوران میں نماز کا وقت ہو گیا تو مؤذن ابو بکر رضی اللہ عنہ کے پاس آیا اور کہا: کیا آپ لوگوں کو نماز پڑھائیں گے تاکہ میں تکبیر کہوں؟ ابو بکر رضی اللہ عنہ نے کہا: ہاں۔ انہوں (سہل بن سعد) نے کہا: اس طرح ابو بکر رضی اللہ عنہ نے نماز شروع کر دی، اتنے میں رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے جب کہ لوگ نماز میں تھے، آپ بچ کر گزرتے ہوئے (پہلی) صف میں پہنچ کر کھڑے ہو گئے۔ اس پر لوگوں نے ہاتھوں کو ہاتھوں پر مار کر آواز کرنی شروع کر دی۔ ابو بکر رضی اللہ عنہ اپنی نماز میں کسی اور طرف توجہ نہیں دیتے تھے۔ جب لوگوں نے مسلسل ہاتھوں سے آواز کی تو وہ متوجہ ہوئے اور رسول اللہ صلی اللہ علیہ وسلم کو دیکھا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ اپنی جگہ کھڑے رہیں، اس پر ابو بکر رضی اللہ عنہ نے اپنے دونوں ہاتھ اٹھائے اور اللہ کا شکر ادا کیا کہ رسول اللہ رضی اللہ عنہ نے ان کو اس بات کا حکم دیا، پھر اس کے بعد ابو بکر رضی اللہ عنہ پیچھے ہٹ کر صف میں صحیح طرح کھڑے ہو گئے اور رسول اللہ صلی اللہ علیہ وسلم آگے بڑھے اور آپ نے نماز پڑھائی۔ جب آپ فارغ ہوئے تو فرمایا: ’’اے ابو بکر! جب میں نے تمہیں حکم دیا تو اپنی جگہ ٹکے رہنے سے تمہیں کس چیز نے روک دیا؟‘‘ ابو بکر رضی اللہ عنہ نے کہا: ابو قحافہ کے بیٹے کے لیے زیبا نہ تھا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے آگے (کھڑے ہو کر) جماعت کرائے، پھر رسول اللہ صلی اللہ علیہ وسلم نے (صحابہ کرام رضی اللہ عنہم کی طرف متوجہ ہو کر) فرمایا: ’’ کیا ہوا؟ میں نے تم لوگوں کو دیکھا کہ تم بہت تالیاں بجا رہے تھے؟ جب نماز میں تمہیں کوئی ایسی بات پیش آ جائے (جس پر توجہ دلانا ضروری ہو) تو سبحان اللہ کہو، جب کہو سبحان اللہ کہے گا تواس کی طرف توجہ کی جائے گی، ہاتھ پر ہاتھ مارنا، صرف عورتوں کےلیے ہے۔‘‘"}],[881,"عبد العزیز بن ابی حازم اور یعقوب بن عبد الرحمن القادری دونوں نے ابو حازم سے اور انہوں نے سہل بن سعد رضی اللہ عنہ سے امام مالک کی روایت کی طرح روایت بیان کی ۔ ان دونوں کی حدیث میں یہ ہے کہ ابو بکر رضی اللہ عنہ نے اپنے دونوں ہاتھ بلند کیے ، اللہ تعالیٰ کا شکریہ ادا کیا اور الٹے پاؤں واپس ہوئے حتیٰ کہ صف میں آ کھڑے ہوئے ۔","",{"u2":"عبد العزیز بن ابی حازم اور یعقوب بن عبد الرحمن القادری دونوں نے ابو حازم سے اور انہوں نے سہل بن سعد رضی اللہ عنہ سے امام مالک کی روایت کی طرح روایت بیان کی۔ ان دونوں کی حدیث میں یہ ہے کہ ابو بکر رضی اللہ عنہ نے اپنے دونوں ہاتھ بلند کیے، اللہ تعالیٰ کا شکریہ ادا کیا اور الٹے پاؤں واپس ہوئے حتیٰ کہ صف میں آ کھڑے ہوئے۔"}],[882,"عبید اللہ نے ابو حازم سے اور انہوں نے سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم قبیلہ بنو عمرو بن عوف کے درمیان صلح کرانے تشریف لے گئے .... آگے مذکورہ بالا راویوں کے مانند ( حدیث بیان کی ) اور اس میں یہ اضافہ کیا کہ رسول اللہ صلی اللہ علیہ وسلم آئے اور صفوں کو چیرتے ہوئے پہلی صف کے قریب کھڑے ہو گئے ۔ اس میں یہ الفاظ بھی ہیں کہ ابو بکر رضی اللہ عنہ الٹے پاؤں پیچھے لوٹ آئے ۔","",{"u2":"عبید اللہ نے ابو حازم سے اور انہوں نے سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم قبیلہ بنو عمرو بن عوف کے درمیان صلح کرانے تشریف لے گئے .... آگے مذکورہ بالا راویوں کے مانند (حدیث بیان کی) اور اس میں یہ اضافہ کیا کہ رسول اللہ صلی اللہ علیہ وسلم آئے اور صفوں کو چیرتے ہوئے پہلی صف کے قریب کھڑے ہو گئے۔ اس میں یہ الفاظ بھی ہیں کہ ابو بکر رضی اللہ عنہ الٹے پاؤں پیچھے لوٹ آئے۔"}],[883,"۔ عباد بن زیاد کو عروہ بن مغیرہ بن شعبہ خبر دی کہ مغیرہ بن شعبہ رضی اللہ عنہ نے انہیں بتایا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غز وہ تبوک میں شریک ہوئے ۔ مغیرہ نے کہا : صبح کی نماز سے پہلے رسول اللہ صلی اللہ علیہ وسلم قضائے حاجت کے لیے باہر نکلے اور میں نے آپ کے ہمراہ پانی کا ایک برتن اٹھا لیا ۔ جب رسول اللہ صلی اللہ علیہ وسلم میر ی طرف لوٹے تو میں برتن سے آپ کے ہاتھوں پر پانی ڈالنے لگا ، آپ نے اپنے دونوں ہاتھ تین بار دھوئے ، پھر اپنا چہرہ دھویا ، اس کے بعد اپنے دونوں ہاتھوں سے جبہ نکالنے لگے ، جبے کی دونوں آستینیں تنگ ہوئیں تو آپ نے اپنے ہاتھ جبے کے اندر کر لیے حتیٰ کہ آپ نے اپنے بازور جبے کے نیچے سے نکال لیے اور دونوں ہاتھ کہنیوں تک دھوئے ، پھر اپنے دونوں موزوں پر مسح ( کر کے ) وضو ( مکمل ) کیا ، پھر آپ آگے بڑھے ۔ مغیرہ رضی اللہ عنہ نے کہا : میں بھی آپ کے ساتھ آگے بڑھا یہاں تک کہ ہم لوگوں کو اس حال میں پایا کہ وہ عبد الرحمن بن عوف رضی اللہ عنہ کو آگے کر چکے تھے ، انہوں نے نماز پڑھائی اور رسول اللہ صلی اللہ علیہ وسلم کو دو رکعتوں میں سے ایک ملی ۔ آپ نے آخری رکعت لوگوں کے ساتھ ادا کی ، چنانچہ جب سیدنا عبد الرحمن بن عوف رضی اللہ عنہ نے سلام پھیرا تو رسول اللہ صلی اللہ علیہ وسلم اپنی نماز کی تکمیل کے لیے کھڑے ہو گئے ، اس بات نے مسلمانوں کو گھبراہٹ میں مبتلا کر دیا اور انہوں نے کثرت سے سبحان اللہ کہنا شروع کر دیا ، جب نبی صلی اللہ علیہ وسلم نے اپنی نماز پوری کر لی تو ان کی طرف متوجہ ہوئے اور فرمایا : ’’ تم نے اچھا کیا ۔ ‘‘ یا فرمایا : ’’تم نے ٹھیک کیا ۔ ‘‘ آپ نے ان کی تحسین فرمائی کہ انہوں نے وقت پر نماز پڑھ لی تھی ۔","",{"u2":"۔ عباد بن زیاد کو عروہ بن مغیرہ بن شعبہ خبر دی کہ مغیرہ بن شعبہ رضی اللہ عنہ نے انہیں بتایا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غز وہ تبوک میں شریک ہوئے۔ مغیرہ نے کہا: صبح کی نماز سے پہلے رسول اللہ صلی اللہ علیہ وسلم قضائے حاجت کے لیے باہر نکلے اور میں نے آپ کے ہمراہ پانی کا ایک برتن اٹھا لیا۔ جب رسو ل اللہ صلی اللہ علیہ وسلم میر ی طرف لوٹے تو میں برتن سے آپ کے ہاتھوں پر پانی ڈالنے لگا، آپ نے اپنے دونوں ہاتھ تین بار دھوئے، پھر اپنا چہرہ دھویا، اس کے بعد اپنے دونوں ہاتھوں سے جبہ نکالنے لگے، جبے کی دونوں آستینیں تنگ ہوئیں تو آپ نے اپنے ہاتھ جبے کے اندر کر لیے حتیٰ کہ آپ نے اپنے بازور جبے کے نیچے سے نکال لیے اور دونوں ہاتھ کہنیوں تک دھوئے، پھر اپنے دونوں موزوں پر مسح (کر کے) وضو (مکمل) کیا، پھر آپ آگے بڑھے۔\nمغیرہ رضی اللہ عنہ نے کہا: میں بھی آپ کے ساتھ آگے بڑھا یہاں تک کہ ہم لوگوں کو اس حال میں پایا کہ وہ عبد الرحمن بن عوف رضی اللہ عنہ کو آگے کر چکے تھے، انہوں نے نماز پڑھائی اور رسول اللہ صلی اللہ علیہ وسلم کو دو رکعتوں میں سے ایک ملی۔ آپ نے آخری رکعت لوگوں کے ساتھ ادا کی، چنانچہ جب سیدنا عبد الرحمن بن عوف رضی اللہ عنہ نے سلام پھیرا تو رسول اللہ صلی اللہ علیہ وسلم اپنی نماز کی تکمیل کے لیے کھڑے ہو گئے، اس بات نے مسلمانوں کو گھبراہٹ میں مبتلا کر دیا اور انہوں نے کثرت سے سبحان اللہ کہنا شروع کر دیا، جب نبی صلی اللہ علیہ وسلم نے اپنی نماز پوری کر لی تو ان کی طرف متوجہ ہوئے اور فرمایا: ’’ تم نے اچھا کیا۔‘‘ یا فرمایا: ’’تم نے ٹھیک کیا۔‘‘ آپ نے ان کی تحسین فرمائی کہ انہوں نے وقت پر نماز پڑھ لی تھی۔"}],[884,"اسماعیل بن محمد بن سعد نے حمزہ بن مغیرہ سے روایت کی جو عباد کی روایت کی طرح ہے ۔ ( اس میں یہ بھی ہے کہ ) مغیرہ رضی اللہ عنہ نے کہا : میں نے عبد الرحمن بن عوف کو پیچھے کرنا چاہا تو نبی صلی اللہ علیہ وسلم نے فرمایا : ’’اسے ( آگے ) رہنے دو ۔ ‘‘","",{"u2":"اسماعیل بن محمد بن سعد نے حمزہ بن مغیرہ سے روایت کی جو عباد کی روایت کی طرح ہے۔ (اس میں یہ بھی ہے کہ) مغیرہ رضی اللہ عنہ نے کہا: میں نے عبد الرحمن بن عوف کو پیچھے کرنا چاہا تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اسے (آگے) رہنے دو۔‘‘"}],[885,"ابو بکر بن ابی شیبہ ، عمرو ناقد اور زہیر بن حرب نے کہا : ہمیں سفیان بن عیینہ نے زہری سے حدیث سنائی ، انہوں نے ابو سلمہ سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، نیز ہارون بن معروف اور حرملہ بن یحییٰ نے کہا : ہمیں ابن وہب نے بتایا ، انہوں نے کہا : مجھے یونس نے ابن شہاب کے حوالے سے خبر دی کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ ( امام و متنبہ کرنے کا طریقہ ) مردوں کے لیے تسبیح ( سبحان اللہ کہنا ) ہے اور عورتوں کے ہاتھ پر ہاتھ مارنا ہے ۔ ‘‘ حرملہ نے اپنی روایت میں یہ اضافہ کیا کہ ابن شہاب نے کہا : میں نے علم والے لوگوں کو دیکھا ، وہ تسبیح کہتے تھے او ر اشارہ کرتے تھے"],[886,"ابو بکر بن ابی شیبہ ، عمرو ناقد اور زہیر بن حرب نے کہا : ہمیں سفیان بن عیینہ نے زہری سے حدیث سنائی ، انہوں نے ابو سلمہ سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، نیز ہارون بن معروف اور حرملہ بن یحییٰ نے کہا : ہمیں ابن وہب نے بتایا ، انہوں نے کہا : مجھے یونس نے ابن شہاب کے حوالے سے خبر دی کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ ( امام و متنبہ کرنے کا طریقہ ) مردوں کے لیے تسبیح ( سبحان اللہ کہنا ) ہے اور عورتوں کے ہاتھ پر ہاتھ مارنا ہے ۔ ‘‘ حرملہ نے اپنی روایت میں یہ اضافہ کیا کہ ابن شہاب نے کہا : میں نے علم والے لوگوں کو دیکھا ، وہ تسبیح کہتے تھے او ر اشارہ کرتے تھے",""],[887,"ابو صالح نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی ( سابقہ روایت ) کے مانند روایت بیان کی ہے ۔","",{"u2":"ابو صالح نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی (سابقہ روایت) کے مانند روایت بیان کی ہے۔"}],[888,"ہمام نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی ( مذکورہ بالا حدیث ) کے مانند روایت بیان کی اور اس میں اضافہ کیا : ’’نماز میں ( متنبہ کرنے کے لیے ۔ ) ‘‘","",{"u2":"ہمام نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی (مذکورہ بالا حدیث) کے مانند روایت بیان کی اور اس میں اضافہ کیا: ’’نماز میں (متنبہ کرنے کے لیے۔)‘‘"}],[889,"سعید کے والد ابو سعید مقبری نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، کہا : ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ( ہمیں ) نماز پڑھائی ، پھر سلام پھیرا اور فرمایا : ’’اے فلاں! تم اپنی نماز اچھی طرح نہیں پڑھ سکتے؟ کیا نمازی نماز پڑھتے وقت یہ نہیں دیکھتا ( غور کرتا ) کہ وہ نماز کیسے پڑھتا ہے؟ وہ اپنے ہی لیے نماز پڑھتا ہے ( کسی دوسرے کےلیے نہیں ۔ ) اللہ کی قسم! میں اپنے پیچھے بھی اسی طرح دیکھتا ہون جس طرح سامنے دیکھتا ہوں","",{"u2":"سعید کے والد ابو سعید مقبری نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، کہا: ایک دن رسول اللہ صلی اللہ علیہ وسلم نے (ہمیں) نماز پڑھائی، پھر سلام پھیرا اور فرمایا: ’’اے فلاں! تم اپنی نماز اچھی طرح نہیں پڑھ سکتے؟ کیا نمازی نماز پڑھتے وقت یہ نہیں دیکھتا (غور کرتا) کہ وہ نماز کیسے پڑھتا ہے؟ وہ اپنے ہی لیے نماز پڑھتا ہے (کسی دوسرے کےلیے نہیں۔) اللہ کی قسم! میں اپنے پیچھے بھی اسی طرح دیکھتا ہون جس طرح سامنے دیکھتا ہوں"}],[890,"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’کیا تم سمجھتے ہو کہ میرا رخ ادھر ( سامنے ) ہی ہے؟ اللہ کی قسم! مجھ پر نہ تمہارا رکوع مخفی ہے اور نہ تمہارا سجدہ ، یقینا میں تمہیں اپنے پیچھے بھی دیکھتا ہوں ۔ ‘‘","",{"u2":"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا تم سمجھتے ہو کہ میرا رخ ادھر (سامنے) ہی ہے؟ اللہ کی قسم! مجھ پر نہ تمہارا رکوع مخفی ہے اور نہ تمہارا سجدہ، یقینا میں تمہیں اپنے پیچھے بھی دیکھتا ہوں۔‘‘"}],[891,"۔ شعبہ نے کہا : میں نے قتادہ سے سنا ، وہ سیدنا انس بن مالک رضی اللہ عنہ سے روایت کر رہے تھے کہ نبی صلی اللہ علیہ وسلم نے فرمایا : ’’ رکوع اور سجدہ پوری طرح کیا کرو ، اللہ کی قسم! میں تمہیں اپنے پیچھے ( بھی ) دیکھتا ہوں ۔ ‘‘ ( بلکہ ) غالباً آپ نے اس طرح فرمایا : ’’ جب تم رکوع اور سجدہ کرتے ہو تو میں تمہیں اپنی پیٹھ پیچھے بھی دیکھتا ہوں ۔ ‘‘"],[892,"قتادہ سے ( شعبہ کے بجائے دستوائی والے ) ہشام اور سعید نے اپنی اپنی سند کے ساتھ سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’ رکوع اور سجدہ کو مکمل کرو ، اللہ کی قسم! جب بھی تم رکوع کرتے ہو اور جب بھی تم سجدہ کرتے ہو تو میں اپنی پیٹھ پیچھے تمہیں دیکھتا ہوں ۔ ‘‘ اور سعید کی روایت میں ( إذا ما ركعتم وإذا ما سجدتم کے بجائے ) إذا ركعتم وسجدتم ’’جب تم رکوع اور سجدہ کرتے ہو ۔ ‘‘ کے الفاظ ہیں ۔ یعنی سعید کی روایت میں اذا کے بعد دونوں جگہ ما کا لفظ نہیں ہے ۔","",{"u2":"۔ شعبہ نے کہا: میں نے قتادہ سے سنا، وہ سیدنا انس بن مالک رضی اللہ عنہ سے روایت کر رہے تھے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ رکوع اور سجدہ پوری طرح کیا کرو، اللہ کی قسم! میں تمہیں اپنے پیچھے (بھی) دیکھتا ہوں۔‘‘ (بلکہ) غالباً آپ نے اس طرح فرمایا: ’’ جب تم رکوع اور سجدہ کرتے ہو تو میں تمہیں اپنی پیٹھ پیچھے بھی دیکھتا ہوں۔‘‘\nقتادہ سے (شعبہ کے بجائے دستوائی والے) ہشام اور سعید نے اپنی اپنی سند کے ساتھ سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’ رکوع اور سجدہ کو مکمل کرو، اللہ کی قسم! جب بھی تم رکوع کرتے ہو اور جب بھی تم سجدہ کرتے ہو تو میں اپنی پیٹھ پیچھے تمہیں دیکھتا ہوں۔‘‘ اور سعید کی روایت میں (إذا ما رکعتم وإذا ما سجدتم کے بجائے) إذا رکعتم وسجدتم ’’جب تم رکوع اور سجدہ کرتے ہو۔‘‘ کے الفاظ ہیں۔ یعنی سعید کی روایت میں اذا کے بعد دونوں جگہ ما کا لفظ نہیں ہے۔"}],[893,"‏‏‏‏ سیدنا انس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دن نماز پڑھانے کے فوراً ہی بعد ہماری طرف متوجہ ہو کر فرمایا: ”لوگو! میں تمہارا امام ہوں۔ اس لئے مجھ سے پہلے رکوع، سجدہ، قومہ اور سلام نہ پھیرو۔ میں آگے اور پیچھے سے تم کو دیکھتا ہوں۔ اور قسم ہے اس ذات کی جس کے قبضہ میں میری جان ہے جو چیزیں میں دیکھتا ہوں اگر تم انہیں دیکھ لو تو ہنسو کم اور روؤ زیادہ“، لوگوں نے پوچھا: یا رسول اللہ! آپ نے کیا دیکھا ہے؟ ارشاد ہوا ”میں نے جنت اور دوزخ دیکھی ہے۔“","",{"u2":"علی بن مسہر نے مختار بن فلفل سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ایک دن رسو ل اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی، اور نماز سے فراغت کے بعد ہماری طرف رخ کیا اور فرمایا: ’’لوگو! میں تمہارا امام ہوں، نہ قیام میں اور نہ سلام پھیرنے میں کیونکہ میں تمہیں اپنے سامنے اور اپنے پیچھے دیکھتا ہوں۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس ذات کی قسم جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم) کی جان ہے! اگر تم ان (تمام چیزوں) کو دیکھو جو میں نے دیکھیں تو تم کم ہنسو اور زیادہ رؤو۔‘‘ صحابہ کرام رضی اللہ عنہم نے عرض کی: اے اللہ کے رسول! آپ نے کیا دیکھا ہے؟ آپ نے فرمایا: ’’میں نے جنت اور دوزخ کو دیکھا ہے۔‘‘"}],[894,"۔ ( علی بن مسہر کے بجائے ) جریر اور ابن فضیل دونوں نے اپنی اپنی سند سے مختار بن فلفل سے روایت کی ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی اور انہوں نے نبی صلی اللہ علیہ وسلم سے مذکورہ بالا روایت بیان کی ، جریر کی حدیث میں ’’نہ سلام پھیرنے میں ‘‘ کے الفاظ نہیں ۔","",{"u2":"۔ (علی بن مسہر کے بجائے) جریر اور ابن فضیل دونوں نے اپنی اپنی سند سے مختار بن فلفل سے روایت کی، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی اور انہوں نے نبی صلی اللہ علیہ وسلم سے مذکورہ بالا روایت بیان کی، جریر کی حدیث میں ’’نہ سلام پھیرنے میں‘‘ کے الفاظ نہیں۔"}],[895,"۔ حماد بن زید نے محمد بن زیاد سے حدیث بیان کی ، انہوں نے کہا : ہمیں سیدنا ابو ہریرہ رضی اللہ عنہ نے حدیث سنائی کہ محمد صلی اللہ علیہ وسلم نے فرمایا : ’’جو شخص امام سے پہلے ( رکوع وسجود سے ) سر اٹھاتا ہے کیا وہ اس بات سے نہیں ڈرتا کہ اللہ تعالیٰ اس کے سرکو گدھے کے سر جیسا بنا دے؟ ‘‘","",{"u2":"۔ حماد بن زید نے محمد بن زیاد سے حدیث بیان کی، انہوں نے کہا: ہمیں سیدنا ابو ہریرہ رضی اللہ عنہ نے حدیث سنائی کہ محمد صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص امام سے پہلے (رکوع وسجود سے) سر اٹھاتا ہے کیا وہ اس بات سے نہیں ڈرتا کہ اللہ تعالیٰ اس کے سرکو گدھے کے سر جیسا بنا دے؟‘‘"}],[896,"۔ یونس نے محمد بن زیاد سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جو شخص اپنی نماز میں امام سے پہلے سر اٹھاتا ہے وہ اس بات سے محفوظ نہیں کہ اللہ تعالیٰ اس کی صورت گدھے کی صورت میں بدل دے","",{"u2":"۔ یونس نے محمد بن زیاد سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جو شخص اپنی نماز میں امام سے پہلے سر اٹھاتا ہے وہ اس بات سے محفوظ نہیں کہ اللہ تعالیٰ اس کی صورت گدھے کی صورت میں بدل دے"}],[897,"۔ ربیع بن مسلم ، شعبہ اور حماد بن سلمہ سب نے مختلف سندوں سے محمد بن زیاد سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی اور انہوں نے یہی روایت نبی صلی اللہ علیہ وسلم سے بیان کی ۔ ( ان راویوں میں سے ) ربیع بن مسلم کی حدیث میں ( اس کی صورت بدل دے کے بجائے ) ’’اور اللہ اس کا چہرہ گدھے کا چہرہ بنا دے ‘‘ کے الفاظ ہیں ۔","",{"u2":"۔ ربیع بن مسلم، شعبہ اور حماد بن سلمہ سب نے مختلف سندوں سے محمد بن زیاد سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی اور انہوں نے یہی روایت نبی صلی اللہ علیہ وسلم سے بیان کی۔ (ان راویوں میں سے) ربیع بن مسلم کی حدیث میں (اس کی صورت بدل دے کے بجائے) ’’اور اللہ اس کا چہرہ گدھے کا چہرہ بنا دے‘‘ کے الفاظ ہیں۔"}],[898,"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جو لوگ نماز میں اپنی نظریں آسمان کی طرف اٹھاتے ہیں وہ ہر صورت ( اپنی اس حرکت سے ) باز آ جائیں ورنہ ( ہو سکتا ہے ان کی نظر ) ان کی طرف نہ لوٹے ( سلب کر لی جائے ۔ ) ‘‘","",{"u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو لوگ نماز میں اپنی نظریں آسمان کی طرف اٹھاتے ہیں وہ ہر صورت (اپنی اس حرکت سے) باز آ جائیں ورنہ (ہو سکتا ہے ان کی نظر) ان کی طرف نہ لوٹے (سلب کر لی جائے۔)‘‘"}],[899,"۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ لوگ نماز میں دعا کے وقت اپنی نظریں آسمان کی طرف بلند کرنے سے لازما باز آ جائیں یا ( پھر ایسا ہو سکتا ہے کہ ) ان کی نظریں اچک لی جائیں ۔ ‘‘","",{"u2":"۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ لوگ نماز میں دعا کے وقت اپنی نظریں آسمان کی طرف بلند کرنے سے لازما باز آ جائیں یا (پھر ایسا ہو سکتا ہے کہ) ان کی نظریں اچک لی جائیں۔‘‘"}],[900,"ابو معاویہ نے اعمش سے ، انہوں نے مسیب بن رافع سے ، انہوں نے تمیم بن طرفہ سے اور انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہما سے روایت کی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نکل کر ہمارے پاس تشریف لائے اور فرمایا : ’’ کیا وجہ ہے کہ میں تمہیں نماز میں اس طرح ہاتھ اٹھاتے دیکھ رہا ہوں ، جیسے وہ بدکتے ہوئے سرکش گھوڑوں کی دُمیں ہوں؟ ( ہاتھ اٹھا کر دائیں بائیں گھوڑے کی دم کی طرح کیوں ہلاتے ہو ۔ دیکھیے ، حدیث : 970 ۔ 971 ) نماز میں پرسکون رہو ۔ ‘‘ انہوں نے کہا : پھر آپ ( ایک اور موقع پر ) تشریف لائے اور ہمیں مختلف حلقوں میں بیٹھے دیکھا تو فرمایا : ’’ کیا وجہ ہے کہ تمہیں ٹولیوں میں ( بٹا ہوا ) دیکھ رہا ہوں؟ ‘‘ پھر ( ایک اور موقع پر ) تشریف لائے تو فرمایا : ’’ تم اس طرح صف بندی کیوں نہیں کرتے جس طرح بارگاہ الٰہی میں فرشتے صف بستہ ہوتے ہیں؟ ‘‘ ہم نے پوچھا : اے اللہ کے رسول! فرشتے صف بستہ ہوتے ہیں؟ ‘‘ ہم نے پوچھا : اے اللہ کے رسول! فرشتے اللہ تعالیٰ کی بارگاہ میں کس طرح صف بندی کرتے ہیں؟ آپ نے فرمایا : ’’ وہ پہلی صفوں کو مکمل کرتے ہیں اور صف میں ایک دوسرے کے ساتھ جڑ کر کھڑے ہوتے ہیں ۔ ‘‘","",{"u2":"ابو معاویہ نے اعمش سے، انہوں نے مسیب بن رافع سے، انہوں نے تمیم بن طرفہ سے اور انہوں نے حضرت جابر بن سمرہ رضی اللہ عنہما سے روایت کی، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نکل کر ہمارے پاس تشریف لائے اور فرمایا: ’’ کیا وجہ ہے کہ میں تمہیں نماز میں اس طرح ہاتھ اٹھاتے دیکھ رہا ہوں، جیسے وہ بدکتے ہوئے سرکش گھوڑوں کی دُمیں ہوں؟ (ہاتھ اٹھا کر دائیں بائیں گھوڑے کی دم کی طرح کیوں ہلاتے ہو۔ دیکھیے، حدیث: 970۔971) نماز میں پرسکون رہو۔‘‘ انہوں نے کہا: پھر آپ (ایک اور موقع پر) تشریف لائے اور ہمیں مختلف حلقوں میں بیٹھے دیکھا تو فرمایا: ’’ کیا وجہ ہے کہ تمہیں ٹولیوں میں (بٹا ہوا) دیکھ رہا ہوں؟‘‘ پھر (ایک اور موقع پر) تشریف لائے تو فرمایا: ’’ تم اس طرح صف بندی کیوں نہیں کرتے جس طرح بارگاہ الٰہی میں فرشتے صف بستہ ہوتے ہیں؟‘‘ ہم نے پوچھا: اے اللہ کے رسول! فرشتے صف بستہ ہوتے ہیں؟‘‘ ہم نے پوچھا: اے اللہ کے رسول! فرشتے اللہ تعالیٰ کی بارگاہ میں کس طرح صف بندی کرتے ہیں؟ آپ نے فرمایا: ’’ وہ پہلی صفوں کو مکمل کرتے ہیں اور صف میں ایک دوسرے کے ساتھ جڑ کر کھڑے ہوتے ہیں۔‘‘"}],[901,"وکیع اور عیسیٰ بن یونس نے ( اپنی اپنی سند سے روایت کرتے ہوئے ) کہا : ہمیں اعمش نے اسی سند کے ساتھ مذکورہ بالا حدیث بیان کی","",{"u2":"وکیع اور عیسیٰ بن یونس نے (اپنی اپنی سند سے روایت کرتے ہوئے) کہا: ہمیں اعمش نے اسی سند کے ساتھ مذکورہ بالا حدیث بیان کی"}],[902,"۔ مسعر نے کہا : مجھ سے عبید اللہ ابن قبطیہ نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت بیان کی ، انہوں نے کہا کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تو ہم کہتے : السلام عليكم ورحمة الله ، السلام عليكم ورحمة الله اور انہوں نے اپنے ہاتھ سے دونوں جانب اشارہ کیا ، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اپنے ہاتھوں کے ساتھ اشارہ کیوں کرتے ہو ، جیسے وہ بدکتے ہوئے سرکش گھوڑوں کی دُمیں ہوں؟ تم میں سے ( ہر ) ایک کے لیے بس یہی کافی ہے کہ اپنے ہاتھ اپنی ران پر رکھے ، پھر اپنے بھائی کو سلام کرے جو دائیں جانب ہے اور ( جو ) بائیں جانب ( ہے ۔ ) ‘‘","",{"u2":"۔ مسعر نے کہا: مجھ سے عبید اللہ ابن قبطیہ نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت بیان کی، انہوں نے کہا کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تو ہم کہتے: السلام علیکم ورحمۃ اللہ، السلام علیکم ورحمۃ اللہ اور انہوں نے اپنے ہاتھ سے دونوں جانب اشارہ کیا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اپنے ہاتھوں کے ساتھ اشارہ کیوں کرتے ہو، جیسے وہ بدکتے ہوئے سرکش گھوڑوں کی دُمیں ہوں؟ تم میں سے (ہر) ایک کے لیے بس یہی کافی ہے کہ اپنے ہاتھ اپنی ران پر رکھے، پھر اپنے بھائی کو سلام کرے جو دائیں جانب ہے اور (جو) بائیں جانب (ہے۔)‘‘"}],[903,"۔ فرات قزاز نے عبید اللہ سے اور انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی ہم لوگ جب سلام پھیرتے تو ہاتھوں کے اشارے سے السلام عليكم ، السلام عليكم کہتے تھے ، رسول اللہ صلی اللہ علیہ وسلم نے ہماری طرف دیکھا اور فرمایا : ’’کیا وجہ ہے کہ تم ہاتھوں سے اس طرح اشارہ کرتے ہو ، جیسے وہ بدکتے ہوئے سرکش گھوڑوں کی دمیں ہوں؟ تم میں سے کوئی جب سلام پھیرے تو اپنے ساتھی کی طرف رخ کرے اور ہاتھ سے اشارہ نہ کرے ۔ ‘‘","",{"u2":"۔ فرات قزاز نے عبید اللہ سے اور انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی ہم لوگ جب سلام پھیرتے تو ہاتھوں کے اشارے سے السلام علیکم، السلام علیکم کہتے تھے، رسول اللہ صلی اللہ علیہ وسلم نے ہماری طرف دیکھا اور فرمایا: ’’کیا وجہ ہے کہ تم ہاتھوں سے اس طرح اشارہ کرتے ہو، جیسے وہ بدکتے ہوئے سرکش گھوڑوں کی دمیں ہوں؟ تم میں سے کوئی جب سلام پھیرے تو اپنے ساتھی کی طرف رخ کرے اور ہاتھ سے اشارہ نہ کرے۔‘‘"}],[904,"عبد اللہ بن ادریس ، ابو معاویہ اور وکیع نے اعمش سے روایت کی ، انہوں نے عمارہ بن عمیر تیمی سے ، انہوں نے ابو معمر سے اور انہوں نے سیدنا ابو مسعود رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نماز میں ( ہمیں برابر کھڑا کرنے کے لیے ) ہمارے کندھوں کو ہاتھ لگا کر فرماتے : ’’برابر ہو جاؤ اور جدا جدا کھڑے نہ ہو کہ اس سے تمہارے دل باہم مختلف ہو جائیں ، میرے ساتھ تم میں سے پختہ عقل والے دانش مند ( کھڑے ) ہوں ، ان کے بعد وہ جو ( دانش مندی میں ) ان کے قریب ہوں ، پھر وہ جو ان کے قریب ہوں ۔ ‘‘ ابو مسعود رضی اللہ عنہ نے فرمایا : آج تم ایک دوسرے سے شدید ترین اختلاف رکھتے ہو ۔","",{"u2":"عبد اللہ بن ادریس، ابو معاویہ اور وکیع نے اعمش سے روایت کی، انہوں نے عمارہ بن عمیر تیمی سے، انہوں نے ابو معمر سے اور انہوں نے سیدنا ابو مسعود رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نماز میں (ہمیں برابر کھڑا کرنے کے لیے) ہمارے کندھوں کو ہاتھ لگا کر فرماتے: ’’برابر ہو جاؤ اور جدا جدا کھڑے نہ ہو کہ اس سے تمہارے دل باہم مختلف ہو جائیں، میرے ساتھ تم میں سے پختہ عقل والے دانش مند (کھڑے) ہوں، ان کے بعد وہ جو (دانش مندی میں) ان کے قریب ہوں، پھر وہ جو ان کے قریب ہوں۔‘‘ ابو مسعود رضی اللہ عنہ نے فرمایا: آج تم ایک دوسرے سے شدید ترین اختلاف رکھتے ہو۔"}],[905,"جریر ، عیسیٰ بن یونس اور سفیان بن عیینہ نے ( اعمش سے ) باقی ماندہ اسی سند کے ساتھ مذکورہ بالا روایت بیان کی ۔","",{"u2":"جریر، عیسیٰ بن یونس اور سفیان بن عیینہ نے (اعمش سے) باقی ماندہ اسی سند کے ساتھ مذکورہ بالا روایت بیان کی۔"}],[906,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ میرے ساتھ تم میں سے پختہ عقل والے اور دانش مند کھڑے ہوں ، پھر وہ جو ( اس میں ) ان کے قریب ہوں ( پھر وہ جو ان کے قریب ہوں ، پھر وہ جو ان کے قریب ہوں ) تین بار فرمایا : اور تم بازاروں کے گڈ مڈ گروہ ( بننے ) سے بچو ۔ ‘‘","",{"u2":"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ میرے ساتھ تم میں سے پختہ عقل والے اور دانش مند کھڑے ہوں، پھر وہ جو (اس میں) ان کے قریب ہوں (پھر وہ جو ان کے قریب ہوں، پھر وہ جو ان کے قریب ہوں) تین بار فرمایا: اور تم بازاروں کے گڈ مڈ گروہ (بننے) سے بچو۔‘‘"}],[907,"قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’اپنی صفوں کو برابر کیا کرو کیونکہ صفوں کا برابر کرنا نماز کی تکمیل کا حصہ ہے <ہیڈنگ 2> </ہیڈنگ 2>","",{"u2":"قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنی صفوں کو برابر کیا کرو کیونکہ صفوں کا برابر کرنا نماز کی تکمیل کا حصہ ہے <ہیڈنگ 2> </ہیڈنگ 2>"}],[908,"عبد العزیز نے ، جو صہیب کے بیٹے ہیں ، سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’صفیں پوری کرو ، میں اپنی پیٹھ پیچھے تمہیں دیکھتا ہوں ۔ ‘‘","",{"u2":"عبد العزیز نے، جو صہیب کے بیٹے ہیں، سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صفیں پوری کرو، میں اپنی پیٹھ پیچھے تمہیں دیکھتا ہوں۔‘‘"}],[909,"ہمام بن منبہ نے کہا : یہ ہے جو ہمیں سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیا ، پھر انہوں نے ان میں سے متعدد احادیث بیان کیں اور کہا : ’’نماز میں صف سیدھی رکھو کیونکہ صف کو سیدھا رکھنا نماز کے حسن ( ادائیگی ) کا حصہ ہے ۔ ‘‘","",{"u2":"ہمام بن منبہ نے کہا: یہ ہے جو ہمیں سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیا، پھر انہوں نے ان میں سے متعدد احادیث بیان کیں اور کہا: ’’نماز میں صف سیدھی رکھو کیونکہ صف کو سیدھا رکھنا نماز کے حسن (ادائیگی) کا حصہ ہے۔‘‘"}],[910,"سالم بن ابی جعد غطفانی نے کہا : میں ن ے سیدنا نعمان بن بشیر رضی اللہ عنہ سے سنا ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : ’’تم ہر صورت اپنی صفوں کو برابر رکھو ورنہ اللہ تعالیٰ لازماً تمہارے رخ ایک دوسرے کی مخالف سمتوں میں کر دے گا ۔ ‘‘","",{"u2":"سالم بن ابی جعد غطفانی نے کہا: میں ن ے سیدنا نعمان بن بشیر رضی اللہ عنہ سے سنا، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’تم ہر صورت اپنی صفوں کو برابر رکھو ورنہ اللہ تعالیٰ لازماً تمہارے رخ ایک دوسرے کی مخالف سمتوں میں کر دے گا۔‘‘"}],[911,"ابو خیثمہ نے سماک بن حرب سے روایت کی ، انہوں نے کہا : میں نے سیدنا نعمان بن بشیر رضی اللہ عنہما سے سنا ، وہ کہتے تھے : رسول اللہ صلی اللہ علیہ وسلم ہماری صفوں کو ( اس قدر ) سیدھا اور برابر کراتے تھے ، گویا آپ ان کے ذریعے سے تیروں کو سیدھا کر رہے ہیں ، حتیٰ کہ جب آپ کو یقین ہو گیا کہ ہم نے آپ سے ( اس بات کو ) اچھی طرح سمجھ لیا ہے تو اس کے بعد ایک دن آپ گھر سے نکل کر تشریف لائے اور ( نماز پڑھانے کی جگہ ) کھڑے ہو گئے اور قریب تھا کہ آپ تکبیر کہیں ( اور نماز شروع فرما دیں کہ ) آپ نے ایک آدمی کو دیکھا ، اس کا سینہ صف سے کچھ آگے نکلا ہوا تھا ، آپ نے فرمایا : ’’ اللہ کے بندو! تم لازمی طور پر اپنی صفوں کو سیدھا کرو ورنہ اللہ تمہارے رخ ایک دوسرے کے خلاف مور دے گا ۔ ‘‘","",{"u2":"ابو خیثمہ نے سماک بن حرب سے روایت کی، انہوں نے کہا: میں نے حضرت نعمان بن بشیر رضی اللہ عنہما سے سنا، وہ کہتے تھے: رسول اللہ صلی اللہ علیہ وسلم ہماری صفوں کو (اس قدر) سیدھا اور برابر کراتے تھے، گویا آپ ان کے ذریعے سے تیروں کو سیدھا کر رہے ہیں، حتیٰ کہ جب آپ کو یقین ہو گیا کہ ہم نے آپ سے (اس بات کو) اچھی طرح سمجھ لیا ہے تو اس کے بعد ایک دن آپ گھر سے نکل کر تشریف لائے اور (نماز پڑھانے کی جگہ) کھڑے ہو گئے اور قریب تھا کہ آپ تکبیر کہیں (اور نماز شروع فرما دیں کہ) آپ نے ایک آدمی کو دیکھا، اس کا سینہ صف سے کچھ آگے نکلا ہوا تھا، آپ نے فرمایا: ’’ اللہ کے بندو! تم لازمی طور پر اپنی صفوں کو سیدھا کرو ورنہ اللہ تمہارے رخ ایک دوسرے کے خلاف مور دے گا۔‘‘"}],[912,"ابو احوص اور ابو عوانہ نے اپنی اپنی سند کے ساتھ ( سماک سے ) مذکورہ بالا روایت کے ہم معنیٰ روایت بیان کی ۔","",{"u2":"ابو احوص اورابو عوانہ نے اپنی اپنی سند کے ساتھ (سماک سے) مذکورہ بالا روایت کے ہم معنیٰ روایت بیان کی۔"}],[913,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اگر لوگ جان لیں کہ اذان ( کہنے ) اور پہلی صف ( کا حصہ بننے ) میں کیا ( خیر وبرکت ) ہے ، پھر وہ اس کی خاطر قرعہ اندازی کرنے کے سوا کوئی چارہ نہ پائیں تو وہ اس کے لیے قرعہ اندازی ( بھی ) کریں اور اگر وہ جان لیں کہ ظہر ( کی نماز ) جلدی ادا کرنے میں کتنا اجر وثواب ملتا ہے تو اس کے لیے ایک دوسرے سے سبقت لے جانے کی کوشش کریں گے اور اگر انہیں معلوم ہو جائے کہ عشاء اور صبح کی نمازوں میں کتنا ثواب ہے تو ان دونوں نمازوں میں ( ہر صورت ) پہنچیں چاہے گھسٹ گھسٹ کر آنا پڑے ۔ ‘‘","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اگر لوگ جان لیں کہ اذان (کہنے) اور پہلی صف (کا حصہ بننے) میں کیا (خیر وبرکت) ہے، پھر وہ اس کی خاطر قرعہ اندازی کرنے کے سوا کوئی چارہ نہ پائیں تو وہ اس کے لیے قرعہ اندازی (بھی) کریں اور اگر وہ جان لیں کہ ظہر (کی نماز) جلدی ادا کرنے میں کتنا اجر وثواب ملتا ہے تو اس کے لیے ایک دوسرے سے سبقت لے جانے کی کوشش کریں گے اور اگر انہیں معلوم ہو جائے کہ عشاء اور صبح کی نمازوں میں کتنا ثواب ہے تو ان دونوں نمازوں میں (ہر صورت) پہنچیں چاہے گھسٹ گھسٹ کر آنا پڑے۔‘‘"}],[914,"ابو اشہب نے ابو نضرہ عبدی سے اور انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں کو ( صف بندی میں ) پیچھے رہتے دیکھا تو ان سے کہا : ’’ آگے بڑھو اور ( براہ راست ) میری اقتدا کرو اور جو لوگ تمہارے بعد ہوں وہ تمہاری اقتدا کریں ، کچھ لوگ مسلسل پیچھے رہتے جائیں حتیٰ کہ اللہ تعالیٰ ان کو پیچھے کر دے گا ۔ ‘‘","",{"u2":"ابو اشہب نے ابو نضرہ عبدی سے اور انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ساتھیوں کو (صف بندی میں) پیچھے رہتے دیکھا تو ان سے کہا: ’’ آگے بڑھو اور (براہ راست) میری اقتدا کرو اور جو لوگ تمہارے بعد ہوں وہ تمہاری اقتدا کریں، کچھ لوگ مسلسل پیچھے رہتے جائیں حتیٰ کہ اللہ تعالیٰ ان کو پیچھے کر دے گا۔‘‘"}],[915,"۔ جریری نے ابو نضرہ سے اور انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو مسجد کے پچھلے حصے میں دیکھا ... آگے اسی طرح روایت بیان کی ۔","",{"u2":"۔ جریری نے ابو نضرہ سے اور انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو مسجد کے پچھلے حصے میں دیکھا ... آگے اسی طرح روایت بیان کی۔"}],[916,"ابراہیم بن دینار اور محمد بن حرب واسطی نے کہا : ہمیں ابو قطن عمرو بن ہیثم نے حدیث سنائی ، کہا : ہمیں شعبہ نے قتادہ سے حدیث سنائی ، انہوں نے خلاس سے ، انہوں نے ابو رافع سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا : ’’ اگر تم جان لو ، یا لوگ جان لیں کہ اگلی صف میں کیا ( فضیلت ) ہے تو اس پر قرعہ اندازی ہو ۔ ‘‘ ابن حرب نے ( في الصف المقدم لكانت قرعة کے بجائے ) في الصف الأول ما كانت إلا قرعة ’’پہلی صف میں کیا ہے تو قرعہ کے سوا کچھ نہ ہو ‘‘ کہا ۔","",{"u2":"ابراہیم بن دینار اور محمد بن حرب واسطی نے کہا: ہمیں ابو قطن عمرو بن ہیثم نے حدیث سنائی، کہا: ہمیں شعبہ نے قتادہ سے حدیث سنائی، انہوں نے خلاس سے، انہوں نے ابو رافع سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ اگر تم جان لو، یا لوگ جان لیں کہ اگلی صف میں کیا (فضیلت) ہے تو اس پر قرعہ اندازی ہو۔‘‘\nابن حرب نے (فی الصف المقدم لکانت قرعۃ کے بجائے) فی الصف الأول ما کانت إلا قرعۃ ’’پہلی صف میں کیا ہے تو قرعہ کے سوا کچھ نہ ہو‘‘ کہا۔"}],[917,"جریر نے سہیل سے انہوں نے اپنے والد سے انہوں نے سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت کی ہے انہوں نے کہا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا’’مردو کی بہترین صف پہلی اور بدترین صف آخری ہے جبکہ عورتوں کی بہترین صف آخری اور بدترین صف پہلی ہے ۔","",{"u2":"جریر نے سہیل سے انہوں نے اپنے والد سے انہوں نے سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت کی ہے انہوں نے کہا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا’’مردو کی بہترین صف پہلی اور بدترین صف آخری ہے جبکہ عورتوں کی بہترین صف آخری اور بدترین صف پہلی ہے۔"}],[918,"عبد العزیز ، یعنی دراوردی نے سہیل سے اسی سند کے ساتھ ( یہی ) روایت بیان کی ہے ۔","",{"u2":"عبد العزیز، یعنی دراوردی نے سہیل سے اسی سند کے ساتھ (یہی) روایت بیان کی ہے۔"}],[919,"سیدنا سہل بن سعد رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : میں نے مردوں کو دیکھا کہ چادریں تنگ ہونے کی وجہ سے وہ بچوں کی طرح اپنی چادریں گردنوں میں باندھے ہوئے نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھ رہے تھے ، اس پر کسی کہنے والے نے کہا : اے عورتوں کی جماعت! تم اس وقت تک اپنے سروں کو ( سجدے سے ) نہ اٹھانا جب تک مرد ( سر نہ ) اٹھا لیں ۔ ( خدانخواستہ کسی مرد کے ستر کا کوئی حصہ کھلا ہوا نہ ہو ۔ یہ بات آپ صلی اللہ علیہ وسلم کی موجودگی میں کہی گئی اور آپ نے کہنے والے کو نہ ٹوکا ۔)","",{"u2":"سیدنا سہل بن سعد رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: میں نے مردوں کو دیکھا کہ چادریں تنگ ہونے کی وجہ سے وہ بچوں کی طرح اپنی چادریں گردنوں میں باندھے ہوئے نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھ رہے تھے، اس پر کسی کہنے والے نے کہا: اے عورتوں کی جماعت! تم اس وقت تک اپنے سروں کو (سجدے سے) نہ اٹھانا جب تک مرد (سر نہ) اٹھا لیں۔ (خدانخواستہ کسی مرد کے ستر کا کوئی حصہ کھلا ہوا نہ ہو۔ یہ بات آپ صلی اللہ علیہ وسلم کی موجودگی میں کہی گئی اور آپ نے کہنے والے کو نہ ٹوکا۔)"}],[920,"سفیان بن عیینہ نے زہری سے حدیث بیان کی ، انہوں نے سالم سے سنا ، وہ اپنے والد سے روایت بیان کر رہے تھے اور وہ ( اس کی سند میں ) رسول اللہ صلی اللہ علیہ وسلم تک پہنچتے تھے ( کہ ) آپ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے کسی سے اس کی بیوی مسجد جانے کی اجازت مانگے تو وہ اسے نہ روکے ۔ ‘‘","",{"u2":"سفیان بن عیینہ نے زہری سے حدیث بیان کی، انہوں نے سالم سے سنا، وہ اپنے والد سے روایت بیان کر رہے تھے اور وہ (اس کی سند میں) رسول اللہ صلی اللہ علیہ وسلم تک پہنچتے تھے (کہ) آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب تم میں سے کسی سے اس کی بیوی مسجد جانے کی اجازت مانگے تو وہ اسے نہ روکے۔‘‘"}],[921,"یونس نے ابن شہاب ( زہری ) سے روایت کی ، کہا : مجھے سالم بن عبد اللہ نے خبر دی کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : ’’ اپنی عورتوں کو جب وہ تم سے مسجدوں میں جانے کی اجازت طلب کریں تو انہیں ( وہاں جانے سے ) نہ روکو ۔ ‘‘ ( سالم نے ) کہا : تو ( ابن عمر کے دوسرے بیٹے ) بلال بن عبد اللہ نے کہا : اللہ کی قسم! ہم تو ان کو ضرور روکیں گے ۔ اس پر سیدنا عبد اللہ رضی اللہ عنہ نے اس کی طرف رخ کیا اور اس کو سخت برا بھلا کہا ، میں نے انہیں کبھی ( کسی کو ) اتنا برا بھلا کہتے نہیں سنا اور کہا : میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کا فرمان بتا رہا ہوں اور تم کہتے ہو : اللہ کی قسم! ہم انہیں ضرور روکیں گے ۔","",{"u2":"یونس نے ابن شہاب (زہری) سے روایت کی، کہا: مجھے سالم بن عبد اللہ نے خبر دی کہ حضرت عبد اللہ بن عمر رضی اللہ عنہما نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’ اپنی عورتوں کو جب وہ تم سے مسجدوں میں جانے کی اجازت طلب کریں تو انہیں (وہاں جانے سے) نہ روکو۔‘‘\n(سالم نے) کہا: تو (ابن عمر کے دوسرے بیٹے) بلال بن عبد اللہ نے کہا: اللہ کی قسم! ہم تو ان کو ضرور روکیں گے۔ اس پرسیدنا عبد اللہ رضی اللہ عنہ نے اس کی طرف رخ کیا اور اس کو سخت برا بھلا کہا، میں نے انہیں کبھی (کسی کو) اتنا برا بھلا کہتے نہیں سنا اور کہا: میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کا فرمان بتا رہا ہوں اور تم کہتے ہو: اللہ کی قسم! ہم انہیں ضرور روکیں گے۔"}],[922,"۔ نافع نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اللہ کی باندیوں کو اللہ کی مساجد سے نہ روکو ۔ ‘‘","",{"u2":"۔ نافع نے حضرت ابن عمر رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اللہ کی باندیوں کو اللہ کی مساجد سے نہ روکو۔‘‘"}],[923,"۔ حنظہ نے کہا : میں نے سالم سے سنا ، کہہ رہے تھے : میں نے سیدنا ابن عمر رضی اللہ عنہما سے سنا ، وہ کہتے تھے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : ’’ جب تمہاری عورتیں تم سے مساجد میں جانے کی اجازت مانگیں تو انہیں اجازت دے دو","",{"u2":"۔ حنظہ نے کہا: میں نے سالم سے سنا، کہہ رہے تھے: میں نے حضرت ابن عمر رضی اللہ عنہما سے سنا، وہ کہتے تھے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’ جب تمہاری عورتیں تم سے مساجد میں جانے کی اجازت مانگیں تو انہیں اجازت دے دو"}],[924,"ابو معاویہ نے اعمش سے ، انہوں نے مجاہد سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’رات کو عورتوں کو مسجدوں میں جانے سے نہ روکو ۔ ‘‘ تو عبد اللہ بن عمر رضی اللہ عنہما کے ایک بیٹے نے کہا : ہم ان کو نہیں چھوڑیں گے کہ وہ جائیں اور اسے خرابی اور بگار ( کا ذریعہ ) بنا لیں ۔ ( مجاہد نے ) کہا : ابن عمر رضی اللہ عنہما نے اسے سخت ڈانٹا او ر کہا : میں کہتا ہوں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور تو کہتا ہے ہم انہیں نہیں چھوڑیں گے","",{"u2":"ابو معاویہ نے اعمش سے، انہوں نے مجاہد سے اور انہوں نے حضرت ابن عمر رضی اللہ عنہما سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کو عورتوں کو مسجدوں میں جانے سے نہ روکو۔‘‘ تو عبد اللہ بن عمر رضی اللہ عنہما کے ایک بیٹے نے کہا: ہم ان کو نہیں چھوڑیں گے کہ وہ جائیں اور اسے خرابی اور بگار (کا ذریعہ) بنا لیں۔\n(مجاہد نے) کہا: ابن عمر رضی اللہ عنہما نے اسے سخت ڈانٹا او ر کہا: میں کہتا ہوں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور تو کہتا ہے ہم انہیں نہیں چھوڑیں گے"}],[925,"(دوسرے شاگرد ) عیسیٰ نے اعمش سے اسی سند کے ساتھ اسی کے مانند خبر دی","",{"u2":"دوسرے شاگرد) عیسیٰ نے اعمش سے اسی سند کے ساتھ اسی کے مانند خبر دی"}],[926,"(اعمش کے بجائے ) عمرو ( بن دینار جحمی ) نے مجاہد سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’عورتوں کو رات کے وقت مسجدوں کی طرف نکلنے کی اجازت دو ۔ ‘‘ تو ان کے بیٹے نے ، جس کو واقد کہا جاتا تھا ، کہا : تب وہ اس کو خرابی و بگاڑ بنا لیں گی ۔ ( مجاہد نے ) کہا : ابن عمر رضی اللہ عنہما نے اس کے سینے پر مارا اور کہا : میں تمہیں رسول اللہ صلی اللہ علیہ وسلم سے حدیث سنا رہا ہوں اور تو کہتا ہے : نہیں","",{"u2":"(اعمش کے بجائے) عمرو (بن دینار جحمی) نے مجاہد سے اور انہوں نے حضرت ابن عمر رضی اللہ عنہما سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’عورتوں کو رات کے وقت مسجدوں کی طرف نکلنے کی اجازت دو۔‘‘ تو ان کے بیٹے نے، جس کو واقد کہا جاتا تھا، کہا: تب وہ اس کو خرابی و بگاڑ بنا لیں گی۔\n(مجاہد نے) کہا: ابن عمر رضی اللہ عنہما نے اس کے سینے پر مارا اور کہا: میں تمہیں رسول اللہ صلی اللہ علیہ وسلم سے حدیث سنا رہا ہوں اور تو کہتا ہے: نہیں!"}],[927,"(خود ) بلال بن عبد اللہ بن عمر نے اپنے والد سیدنا ابن عمر رضی اللہ عنہما سے روایت کی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ عورتوں کو ، جب وہ تم سے اجازت طلب کریں تو مسجدوں میں جو ان کے حصے ہیں ان ( کے حصول ) سے ( انہیں ) نہ روکو ۔ ‘‘ بلال نے کہا : اللہ کی قسم! ہم ان کو ضرور روکیں گے ۔ عبد اللہ بن عمر رضی اللہ عنہما نے فرمایا اور تو کہتا ہے : ہم انہیں ضرور روکیں گے","",{"u2":"(خود) بلال بن عبد اللہ بن عمر نے اپنے والد حضرت ابن عمر رضی اللہ عنہما سے روایت کی، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ عورتوں کو، جب وہ تم سے اجازت طلب کریں تو مسجدوں میں جو ان کے حصے ہیں ان (کے حصول) سے (انہیں) نہ روکو۔‘‘ بلال نے کہا: اللہ کی قسم! ہم ان کو ضرور روکیں گے۔ عبد اللہ بن عمر رضی اللہ عنہما نے فرمایا اور تو کہتا ہے: ہم انہیں ضرور روکیں گے!"}],[928,"مخرمہ نے اپنے والد ( بکیر ) سے ، انہوں نے بسر بن سعید روایت کی کہ سیدہ زینب ثقفیہ رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم سے ( یہ ) حدیث بیان کرتی تھیں ، آپ نے فرمایا : ’’ جب تم عورتوں میں سے کوئی عشا کی نماز میں شامل ہو تو وہ اس رات خوشبو نہ لگائے ۔ ‘‘","",{"u2":"مخرمہ نے اپنے والد (بکیر) سے، انہوں نے بسر بن سعید روایت کی کہ حضرت زینب ثقفیہ رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم سے (یہ) حدیث بیان کرتی تھیں، آپ نے فرمایا: ’’ جب تم عورتوں میں سے کوئی عشا کی نماز میں شامل ہو تو وہ اس رات خوشبو نہ لگائے۔‘‘"}],[929,"(مخرمہ کے بجائے ) محمد بن عجلان نے بکیر بن عبد اللہ بن اشج سے ، انہوں نے بسر بن سعید سے ، انہوں نے سیدنا عبد اللہ ( بن مسعود ) رضی اللہ عنہ کی بیوی زینب رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا تھا : ’’ جب تم میں سے کوئی مسجد میں جائے تو وہ خوشبو کو ہاتھ نہ لگائے ۔ ‘‘","",{"u2":"(مخرمہ کے بجائے) محمد بن عجلان نے بکیر بن عبد اللہ بن اشج سے، انہوں نے بسر بن سعید سے، انہوں نے حضرت عبد اللہ (بن مسعود) رضی اللہ عنہ کی بیوی زینب رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا تھا: ’’ جب تم میں سے کوئی مسجد میں جائے تو وہ خوشبو کو ہاتھ نہ لگائے۔‘‘"}],[930,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس عورت کو ( بخور ) خوشبودار دھواں لگ جائے ، وہ ہمارے ساتھ عشاء کی نماز میں حاضر نہ ہو ۔ ‘‘","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جس عورت کو (بخور) خوشبودار دھواں لگ جائے، وہ ہمارے ساتھ عشاء کی نماز میں حاضر نہ ہو۔‘‘"}],[931,"سلیمان بن بلال نے یحییٰ بن سعید سے اور انہوں نے عمرہ بنت عبد الرحمان سے روایت کی کہ انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا سے سنا ، وہ فرماتی تھیں کہ عورتوں نے ( بناؤ سنگھار کے ) جو نئے انداز نکال لیے ہیں اگر رسول اللہ صلی اللہ علیہ وسلم دیکھ لیتے تو انہیں مسجد میں آنے سے روک دیتے ، جس طرح بنی اسرائیل کی عورتوں کو روک دیا گیا تھا ۔ میں نے عمرہ سے پوچھا : کیا بنی اسرائیل کی عورتوں کو مسجد میں آنے سے روک دیا گیا تھا؟ انہوں نے کہا : ہاں ۔","",{"u2":"سلیمان بن بلال نے یحییٰ بن سعید سے اور انہوں نے عمرہ بنت عبد الرحمان سے روایت کی کہ انہوں نے نبی صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا سے سنا، وہ فرماتی تھیں کہ عورتوں نے (بناؤ سنگھار کے) جو نئے انداز نکال لیے ہیں اگر رسول اللہ صلی اللہ علیہ وسلم دیکھ لیتے تو انہیں مسجد میں آنے سے روک دیتے، جس طرح بنی اسرائیل کی عورتوں کو روک دیا گیا تھا۔ میں نے عمرہ سے پوچھا: کیا بنی اسرائیل کی عورتوں کو مسجد میں آنے سے روک دیا گیا تھا؟ انہوں نے کہا: ہاں۔"}],[932,"(سلیمان بن بلال کے بجائے ) عبد الوہاب ثقفی ، سفیان بن عیینہ ، ابو خالد احمر اورعیسیٰ بن یونس سبھی نے یحییٰ بن سعید سے ( باقی ماندہ ) اسی سند کے ساتھ اسی کے مانند حدیث روایت کی ہے","",{"u2":"(سلیمان بن بلال کے بجائے) عبد الوہاب ثقفی، سفیان بن عیینہ، ابو خالد احمر اورعیسیٰ بن یونس سبھی نے یحییٰ بن سعید سے (باقی ماندہ) اسی سند کے ساتھ اسی کے مانند حدیث روایت کی ہے"}],[933,"سعید بن جبیر نے سیدنا ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے فرمان : ﴿ولا تجهر بصلاتك ولا تخافت بها﴾ ’’ اور اپنی نماز نہ بلند آواز سے پڑھیں اور نہ اسے پست کریں ‘‘ کے بارے میں روایت کی ، انہوں نے کہا : یہ آیت اس وقت اتری جب رسول اللہ صلی اللہ علیہ وسلم مکہ میں پوشیدہ ( عبادت کرتے ) تھے ۔ جب آپ اپنے ساتھیوں کو جماعت کراتے تو قراءت بلند آواز سے کرتے تھے ، مشرک جب یہ قراءت سنتے تو قرآن کو ، اس کے نازل کرنے والے کو اور اس کے لانے والے کو برا بھلا کہتے ۔ اس پر اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو ہدایت کی : ’’ اپنی نماز میں ( آواز کو اس قدر ) بلند نہ کریں ‘‘ کہ آپ کی قراءت مشرکوں کو سنائی دے ’’ اور نہ اس ( کی آواز ) کو پست کریں ‘‘ اپنے ساتھیوں سے ، انہیں قرآن سنائیں اور آواز اتنی زیاد اونچی نہ کریں ’’اور ان ( دونوں ) کے درمیان کی راہ اختیار کریں ۔ ‘‘ ( اللہ تعالیٰ ) فرماتا ہے : بلند اور آہستہ کے درمیان ( میں رہیں ۔)","",{"u2":"سعید بن جبیر نے حضرت ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے فرمان: ﴿ولا تجہر بصلاتک ولا تخافت بہا﴾ ’’ اور اپنی نماز نہ بلند آواز سے پڑھیں اور نہ اسے پست کریں‘‘ کے بارے میں روایت کی، انہوں نے کہا: یہ آیت اس وقت اتری جب رسول اللہ صلی اللہ علیہ وسلم مکہ میں پوشیدہ (عبادت کرتے) تھے۔ جب آپ اپنے ساتھیوں کو جماعت کراتے تو قراءت بلند آواز سے کرتے تھے، مشرک جب یہ قراءت سنتے تو قرآن کو، اس کے نازل کرنے والے کو اور اس کے لانے والے کو برا بھلا کہتے۔ اس پر اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کو ہدایت کی: ’’ اپنی نماز میں (آواز کو اس قدر) بلند نہ کریں‘‘ کہ آپ کی قراءت مشرکوں کو سنائی دے ’’ اور نہ اس (کی آواز) کو پست کریں‘‘ اپنے ساتھیوں سے، انہیں قرآن سنائیں اور آواز اتنی زیاد اونچی نہ کریں ’’اور ان (دونوں) کے درمیان کی راہ اختیار کریں۔‘‘ (اللہ تعالیٰ) فرماتا ہے: بلند اور آہستہ کے درمیان (میں رہیں۔)"}],[934,"یحییٰ بن زکریا نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اللہ تعالیٰ کے اسی فرمان : ’’ نہ اپنی نماز میں ( قراءت ) بلند کریں اور نہ آہستہ ‘‘ کے بارے میں روایت کی کہ انہوں نے ( عائشہ رضی اللہ عنہا ) نے کہا کہ یہ آیت دعا کے بارے میں اتری ہے ۔","",{"u2":"یحییٰ بن زکریا نے ہشام بن عروہ سے، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اللہ تعالیٰ کے اسی فرمان: ’’ نہ اپنی نماز میں (قراءت) بلند کریں اور نہ آہستہ‘‘ کے بارے میں روایت کی کہ انہوں نے (عائشہ رضی اللہ عنہا) نے کہا کہ یہ آیت دعا کے بارے میں اتری ہے۔"}],[935,"حماد بن زید ، ابو اسامہ ، وکیع اور ابو معاویہ نے اپنی اپنی سند کے ساتھ ہشام سے اسی سابقہ سند کے ساتھ یہی حدیث روایت کی ہے ۔","",{"u2":"حماد بن زید، ابو اسامہ، وکیع اور ابو معاویہ نے اپنی اپنی سند کے ساتھ ہشام سے اسی سابقہ سند کے ساتھ یہی حدیث روایت کی ہے۔"}],[936,"جریر بن عبد الحمید نے موسیٰ بن ابی عائشہ سے ، انہوں نے سعید بن جبیر سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے فرمان : ﴿ولا تحرك به لسانك لتعجل به﴾ ’’آپ اس کے ساتھ اپنی زبان کو حرکت نہ دیں تاکہ اسے جلدی حاصل کر لیں ۔ ‘‘ کے بارے میں روایت بیان کی کہا : جب جبرائیل رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس وحی لے کر آتے تو آپ ( اس کو پڑھنے کے لیے ساتھ ساتھ ) اپنی زبان اور اپنے ہونٹوں کو حرکت دیتے تھے ، ایسا کرنا آپ پر گراں گزرتا تھا اور یہ آپ ( کے چہرے ) سے معلوم ہو جاتا ۔ اس پر اللہ تعالیٰ نے یہ آیات اتاریں : ’’ آپ اس ( وحی کے پڑھنے ) کے لیے اپنی زبان کو نہ ہلائیں کہ آپ اسے جلد سیکھ لیں ۔ بے شک اس کو ( آپ کے دل میں ) سمیٹ رکھنا اور ( آپ کی زبان سے ) اس کی قراءت ہمارا ذمہ ہے ۔ ‘‘ یعنی ہمارا ذمہ ہے کہ ہم اسے آپ کو سینۂ مبارک میں جمع کریں اور اس کی قراءت ( بھی ہمارے ذمے ہے ) تاکہ آپ قراءت کریں ۔ ’’پھر جب ہم اسے پڑھیں ( فرشتہ ہماری طرف سے تلاوت کرے ) تو آپ اس کے پڑھنے کی اتباع کریں ۔ ‘‘ فرمایا : یعنی ہم اس کو نازل کریں تو آپ اس کو غور سے سنیں ۔ ’’ اس کا واضح کر دینا بھی یقیناً ہمارے ذمے ہے ‘‘ کہ آ پ کی زبان س ( لوگوں کے سامنے ) بیان کر دیں ، پھر جب جبرائیل رضی اللہ عنہ آپ کے پاس ( وحی لے کر ) آتے تو آپ سر جھکا کر غور سے سنتے اور جب وہ چلے جاتے تو اللہ کے وعدے کے مطابق آپ اس کی قراءت فرماتے ۔","",{"u2":"جریر بن عبد الحمید نے موسیٰ بن ابی عائشہ سے، انہوں نے سعید بن جبیر سے اور انہوں نے حضرت ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے فرمان: ﴿ولا تحرک بہ لسانک لتعجل بہ﴾ ’’آپ اس کے ساتھ اپنی زبان کو حرکت نہ دیں تاکہ اسے جلدی حاصل کر لیں۔‘‘ کے بارے میں روایت بیان کی کہا: جب جبرائیل علیہ السلام نبی صلی اللہ علیہ وسلم کے پاس وحی لے کر آتے تو آپ (اس کو پڑھنے کے لیے ساتھ ساتھ) اپنی زبان اور اپنے ہونٹوں کو حرکت دیتے تھے، ایسا کرنا آپ پر گراں گزرتا تھا اور یہ آپ (کے چہرے) سے معلوم ہو جاتا۔ اس پر اللہ تعالیٰ نے یہ آیات اتاریں: ’’ آپ اس (وحی کے پڑھنے) کے لیے اپنی زبان کو نہ ہلائیں کہ آپ اسے جلد سیکھ لیں۔ بے شک اس کو (آپ کے دل میں) سمیٹ رکھنا اور (آپ کی زبان سے) اس کی قراءت ہمارا ذمہ ہے۔‘‘ یعنی ہمارا ذمہ ہے کہ ہم اسے آپ کو سینۂ مبارک میں جمع کریں اور اس کی قراءت (بھی ہمارے ذمے ہے) تاکہ آپ قراءت کریں۔ ’’پھر جب ہم اسے پڑھیں (فرشتہ ہماری طرف سے تلاوت کرے) تو آپ اس کے پڑھنے کی اتباع کریں۔‘‘ فرمایا: یعنی ہم اس کو نازل کریں تو آپ اس کو غور سے سنیں۔ ’’ اس کا واضح کر دینا بھی یقیناً ہمارے ذمے ہے‘‘ کہ آ پ کی زبان س (لوگوں کے سامنے) بیان کر دیں، پھر جب جبرائیل علیہ السلام آپ کے پاس (وحی لے کر) آتے تو آپ سر جھکا کر غور سے سنتے اور جب وہ چلے جاتے تو اللہ کے وعدے کے مطابق آپ اس کی قراءت فرماتے۔"}],[937,"۔ ( جریر بن عبد الحمید کے بجائے ) ابو عوانہ نے موسیٰ بن ابی عائشہ سے ، انہوں نے سعید بن جبیر سے اور انہوں سیدنا ابن عباس رضی اللہ عنہ سے اللہ کے فرمان : ’’آپ اس ( وحی کو پڑھنے ) کے لیے اپنی زبان کو نہ ہلائیں کہ آپ اسے جلد سیکھ لیں ‘‘ کے بارے میں روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم وحی کے نزول کی وجہ سے بہت مشقت برداشت کرتے ، آپ ( ساتھ ساتھ ) اپنے ہونٹ ہلاتے تھے ( ابن عباس رضی اللہ عنہ نے مجھے کہا : میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی طرح ہونٹ ہلا کر دکھاتا ہوں ، تو انہوں نے اپنے ہونٹوں کو حرکت دی اور سعید بن جبیر نے ( اپنے شاگرد سے ) کہا : میں اپنے ہونٹوں کو اسی طرح ہلاتا ہوں جس طرح ابن عباس رضی اللہ عنہ انہیں ہلاتے تھے ، پھر اپنے ہونٹ ہلائے ) اس پر اللہ تعالیٰ یہ آیت اتاری : ’’ آپ اس ( وحی کو پڑھنے ) کے لیے اپنی زبان کو نہ ہلائیں کہ آپ اسے جلد سیکھ لیں ۔ بےشک ہمارا ذمہ ہے اس کو ( آپ کے دل میں ) سمیٹ کر رکھنا اور ( آپ کی زبان سے ) اس کی قراءت ۔ ‘‘ کہا : آپ کے سینے میں اسے جمع کرنا ، پھر یہ کہ آپ اسے پڑھیں ۔ ’’ پھر جب ہم پڑھیں ( فرشتہ ہماری طرف سے تلاوت کرے ) تو آپ اس کے پڑھنے کی اتباع کریں ۔ ‘‘ ابن عباس رضی اللہ عنہما نے کہا : یعنی اس کو غور سےسنیں اور خاموش رہیں ، پھر ہمارے ذمے ہے کہ آپ اس کی قراءت کریں ۔ ابن عباس رضی اللہ عنہما نے کہا : اس کے بعد جب آپ کے پاس جبرائیل رضی اللہ عنہ ( وحی لے کر ) آتے تو آپ غور سے سنتے اور جب جبرائیل رضی اللہ عنہ چلے جاتے تو اسے آپ اسی طرح پڑھتے جس طرح انہوں نے آپ کو پڑھایا ہوتا ۔","",{"u2":"۔ (جریر بن عبد الحمید کے بجائے) ابو عوانہ نے موسیٰ بن ابی عائشہ سے، انہوں نے سعید بن جبیر سے اور انہوں سیدنا ابن عباس رضی اللہ عنہ سے اللہ کے فرمان: ’’آپ اس (وحی کو پڑھنے) کے لیے اپنی زبان کو نہ ہلائیں کہ آپ اسے جلد سیکھ لیں‘‘ کے بارے میں روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم وحی کے نزول کی وجہ سے بہت مشقت برداشت کرتے، آپ (ساتھ ساتھ) اپنے ہونٹ ہلاتے تھے(ابن عباس رضی اللہ عنہ نے مجھے کہا: میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی طرح ہونٹ ہلا کر دکھاتا ہوں، تو انہوں نے اپنے ہونٹوں کو حرکت دی اور سعید بن جبیر نے (اپنے شاگرد سے) کہا: میں اپنے ہونٹوں کو اسی طرح ہلاتا ہوں جس طرح ابن عباس رضی اللہ عنہ انہیں ہلاتے تھے، پھر اپنے ہونٹ ہلائے) اس پر اللہ تعالیٰ یہ آیت اتاری: ’’ آپ اس (وحی کو پڑھنے) کے لیے اپنی زبان کو نہ ہلائیں کہ آپ اسے جلد سیکھ لیں۔ بےشک ہمارا ذمہ ہے اس کو (آپ کے دل میں) سمیٹ کر رکھنا اور (آپ کی زبان سے) اس کی قراءت۔‘‘ کہا: آپ کے سینے میں اسے جمع کرنا، پھر یہ کہ آپ اسے پڑھیں۔ ’’ پھر جب ہم پڑھیں (فرشتہ ہماری طرف سے تلاوت کرے) تو آپ اس کے پڑھنے کی اتباع کریں۔‘‘ ابن عباس رضی اللہ عنہما نے کہا: یعنی اس کو غور سےسنیں اور خاموش رہیں، پھر ہمارے ذمے ہے کہ آپ اس کی قراءت کریں۔ ابن عباس رضی اللہ عنہما نے کہا: اس کے بعد جب آپ کے پاس جبرائیل علیہ السلام (وحی لے کر) آتے تو آپ غور سے سنتے اور جب جبرائیل علیہ السلام چلے جاتے تواسے آپ اسی طرح پڑھتے جس طرح انہوں نے آپ کو پڑھایا ہوتا۔"}],[938,"سعید نے جبیر نے سیدنا ابن عباس رضی اللہ عنہما سے روایت کی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے جنوں کو قرآن سنایا نہ ان کو دیکھا ۔ ( اصل واقعہ یہ ہے کہ ) رسول اللہ صلی اللہ علیہ وسلم اپنے چند ساتھیوں کو ساتھ عکاظ کے بازار کی طرف جانے کے ارادے سے چلے ( ان دنوں ) آسمانی خبر اور شیطانوں کے درمیان رکاوٹ پیدا کر دی گئی تھی ( شیطان آسمانی خبریں نہ سن سکتے تھے ) اور ان پر انگارے پھینکے جانے لگے تھے تو شیاطین ( خبریں حاصل کیے بغیر ) اپنی قوم کے پاس واپس آئے ۔ اس پر انہوں نے پوچھا : تمہارے ساتھ کیا ہوا؟ انہوں ( واپس آنے والوں ) نے کہا : ہمیں آسمان کی خبریں لینے سے روک دیا گیا اور ہم پر انگارے پھینکے گئے ۔ انہوں نے کہا : اس کے سوا یہ کسی اور سبب سے نہیں ہوا کہ کوئی نئی بات ظہور پذیر ہوئی ہے ، اس لیے تم زمین کے مشر ق ومغرب میں پھیل جاؤ اور دیکھو کہ ہمارے آسمانی خبر کے درمیان حائل ہونے والی چیز ( کی حقیقت ) کیا ہے؟ وہ نکل کر زمین کے مشرق اور مغرب میں پہنچے ۔ وہ نفری جس نے تہامہ کا رخ کیا تھا ، گزری ، تو آپ عکاظ کی طرف جاتے ہوئے کجھوروں ( والے مقام نخلہ ) میں تھے ، اپنے ساتھیوں کو صبح کی نماز پڑھا رہے تھے ، جب جنوں نے قرآن سنا تو اس پر کان لگا دیے اور کہنے لگے : یہ ہے جو ہمارے اور آسمانوں کی خبر کے درمیان حائل ہو گیا ہے ۔ اس کے بعد وہ اپنی قوم کی طرف لوٹے اور کہا : اے ہماری قوم! ہم نے عجیب قرآن سنا ہے جو حق کی طرف رہنمائی کرتا ہے ، اس لیے ہم اس پر ایمان لے آئے ہیں اور ہم اپنے رب کے ساتھ ہرگز کسی کو شریک نہیں ٹھہرائیں گے ۔ اس پر اللہ تعالیٰ نے اپنے نبی محمد صلی اللہ علیہ وسلم پر یہ آیت نازل فرمائی : ’’ کہہ دیجیئے : میری طرف یہ وحی کی گئی ہے کہ جنوں کی ایک جماعت نے کان لگا کر سنا ۔ ‘‘","",{"u2":"سعید نے جبیر نے حضرت ابن عباس رضی اللہ عنہما سے روایت کی، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے جنوں کو قرآن سنایا نہ ان کو دیکھا۔ (اصل واقعہ یہ ہے کہ) رسول اللہ صلی اللہ علیہ وسلم اپنے چند ساتھیوں کو ساتھ عکاظ کے بازار کی طرف جانے کے ارادے سے چلے (ان دنوں) آسمانی خبر اور شیطانوں کے درمیان رکاوٹ پیدا کر دی گئی تھی (شیطان آسمانی خبریں نہ سن سکتے تھے) اور ان پر انگارے پھینکے جانے لگے تھے تو شیاطین (خبریں حاصل کیے بغیر) اپنی قوم کے پاس واپس آئے۔ اس پر انہوں نے پوچھا: تمہارے ساتھ کیا ہوا؟ انہوں (واپس آنے والوں) نے کہا: ہمیں آسمان کی خبریں لینے سے روک دیا گیا اور ہم پر انگارے پھینکے گئے۔ انہوں نے کہا: اس کے سوا یہ کسی اور سبب سے نہیں ہوا کہ کوئی نئی بات ظہور پذیر ہوئی ہے، اس لیے تم زمین کے مشر ق ومغرب میں پھیل جاؤ اور دیکھو کہ ہمارے آسمانی خبر کے درمیان حائل ہونے والی چیز (کی حقیقت) کیا ہے؟ وہ نکل کر زمین کے مشرق اور مغرب میں پہنچے۔ وہ نفری جس نے تہامہ کا رخ کیا تھا، گزری، تو آپ عکاظ کی طرف جاتے ہوئے کجھوروں (والے مقام نخلہ) میں تھے، اپنے ساتھیوں کو صبح کی نماز پڑھا رہے تھے، جب جنوں نے قرآن سنا تو اس پر کان لگا دیے اور کہنے لگے: یہ ہے جو ہمارے اور آسمانوں کی خبر کے درمیان حائل ہو گیا ہے۔ اس کے بعد وہ اپنی قوم کی طرف لوٹے اور کہا: اے ہماری قوم! ہم نے عجیب قرآن سنا ہے جو حق کی طرف رہنمائی کرتا ہے، اس لیے ہم اس پر ایمان لے آئے ہیں اور ہم اپنے رب کے ساتھ ہرگز کسی کو شریک نہیں ٹھہرائیں گے۔ اس پر اللہ تعالیٰ نے اپنے نبی محمد صلی اللہ علیہ وسلم پر یہ آیت نازل فرمائی: ’’ کہہ دیجیئے: میری طرف یہ وحی کی گئی ہے کہ جنوں کی ایک جماعت نے کان لگا کر سنا۔‘‘"}],[939,"۔ عبد الاعلیٰ نے داؤد سے اور انہوں نے عامر ( بن شراحیل ) سے روایت کی ، کہا : میں نے علقمہ سے پوچھا : کیا جنوں ( سے ملاقات ) کی رات عبد اللہ بن مسعود رضی اللہ عنہ رسول اللہ کے ساتھ تھے؟ کہا : علقمہ نے جواب دیا : میں نے خود ابن مسعود رضی اللہ عنہ سے پوچھا : کیا آپ لوگوں میں سے کوئی لیلۃ الجن میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ موجود تھا؟ انہوں نے کہا : نہیں ، لیکن ایک رات ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے تو ہم نے آپ کو گم پایا ، ہم نے آپ کو وادیوں اور گھاٹیوں میں تلاش کیا ، ( آپ نہ ملے ) تو ہم نے کہا کہ آپ کو اڑا لیا گیا ہے یا آپ کو بے خبری میں قتل کر دیا گیا ہے ، کہا : ہم نے بدترین رات گزاری جو کسی قوم نے ( کبھی ) گزاری ہو گی ۔ جب ہم نے صبح کی تو اچانک دیکھا کہ آپ حراء کی طرف سے تشریف لا رہے ہیں ، انہوں نے کہا کہ ہم نے عرض کی : اے اللہ کے رسول! ہم نے آپ کوگم پایا تو آپ کی تلاش شروع کر دی لیکن آپ نہ ملے ، اس لیے ہم نے وہ بدترین رات گزاری جو کوئی قوم ( کبھی ) گزار سکتی ہے ۔ اس پر آپ نے فرمایا : ’’ میرے پاس جنوں کی طرف سے دعوت دینے والا آیا تو میں اس کے ساتھ گیا اور میں نے ان کے سامنت قرآن کی قراءت کی ۔ ‘‘ انہوں نے کہا : پھر آپ ( صلی اللہ علیہ وسلم ) ہمیں لے کر گئے اور ہمیں ان کے نقوش قدم اور ان کی آگ کے نشانات دکھائے ۔ جنوں نے آپ سے زاد ( خوراک ) کا سوال کیا تو آپ نے فرمایا : ’’تمہارے لیے ہر وہ ہڈی ہے جس ( کے جانور ) پر اللہ کا نام لیا گیا ہو اور تمہارے ہاتھ لگ جائے ، ( اس پر لگا ہوا ) گوشت جتنا زیادہ سے زیادہ ہو اور ( ہر نرم قدموں والے اونٹ اور کٹے سموں والے ) جانور کی لید تمہارے جانوروں کا چارہ ہے ۔ ‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے ( انسانوں سے ) فرمایا : ’’ تم ان دونوں چیزوں سے استنجا نہ کیا کرو کیونکہ یہ دونوں ( دین میں ) تمہارے بھائیوں ( جنوں اور ان کے جانوروں ) کا کھانا ہیں ۔ ‘‘","",{"u2":"۔ عبد الاعلیٰ نے داؤد سے اور انہوں نے عامر (بن شراحیل) سے روایت کی، کہا: میں نے علقمہ سے پوچھا: کیا جنوں (سے ملاقات) کی رات عبد اللہ بن مسعود رضی اللہ عنہ رسول اللہ کے ساتھ تھے؟ کہا: علقمہ نے جواب دیا: میں نے خود ابن مسعود رضی اللہ عنہ سے پوچھا: کیا آپ لوگوں میں سے کوئی لیلۃ الجن میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ موجود تھا؟ انہوں نے کہا: نہیں، لیکن ایک رات ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے تو ہم نے آپ کو گم پایا، ہم نے آپ کو وادیوں اور گھاٹیوں میں تلاش کیا، (آپ نہ ملے) تو ہم نے کہا کہ آپ کو اڑا لیا گیا ہے یا آپ کو بے خبری میں قتل کر دیا گیا ہے، کہا: ہم نے بدترین رات گزاری جو کسی قوم نے (کبھی) گزاری ہو گی۔ جب ہم نے صبح کی تو اچانک دیکھا کہ آپ حراء کی طرف سے تشریف لا رہے ہیں، انہوں نے کہا کہ ہم نے عرض کی: اے اللہ کے رسول! ہم نے آپ کوگم پایا تو آپ کی تلاش شروع کر دی لیکن آپ نہ ملے، اس لیے ہم نے وہ بدترین رات گزاری جو کوئی قوم (کبھی) گزار سکتی ہے۔ اس پر آپ نے فرمایا: ’’ میرے پاس جنوں کی طرف سے دعوت دینے والا آیا تو میں اس کے ساتھ گیا اور میں نے ان کے سامنت قرآن کی قراءت کی۔‘‘ انہوں نے کہا: پھر آپ(صلی اللہ علیہ وسلم) ہمیں لے کر گئے اور ہمیں ان کے نقوش قدم اور ان کی آگ کے نشانات دکھائے۔ جنوں نے آپ سے زاد (خوراک) کا سوال کیا تو آپ نے فرمایا: ’’تمہارے لیے ہر وہ ہڈی ہے جس (کے جانور) پر اللہ کا نام لیا گیا ہو اور تمہارے ہاتھ لگ جائے، (اس پر لگا ہوا) گوشت جتنا زیادہ سے زیادہ ہو اور (ہر نرم قدموں والے اونٹ اور کٹے سموں والے) جانور کی لید تمہارے جانوروں کا چارہ ہے۔‘‘\nپھر رسول اللہ صلی اللہ علیہ وسلم نے (انسانوں سے) فرمایا: ’’ تم ان دونوں چیزوں سے استنجا کیا کرو کیونکہ یہ دونوں (دین میں) تمہارے بھائیوں (جنوں اور ان کے جانوروں) کا کھانا ہیں۔‘‘"}],[940,"۔ اسماعیل بن ابراہیم نے داؤد سے اسی سند کے ساتھ وآثار نيرانهم ( ان کی آگ کے نشانات ) تک بیان کیا ۔ شعبی نے کہا : جنوں نے آپ سے خوراک کا سوار کیا اور وہ جزیرہ کے جنوں میں سے تھے ... حدیث کے آخری حصے تک جو شعبی کا قول ہے ، عبد اللہ بن مسعود رضی اللہ عنہ کی حدیث سے الگ ہے ۔","",{"u2":"۔ اسماعیل بن ابراہیم نے داؤد سے اسی سند کے ساتھ وآثار نیرانہم (ان کی آگ کے نشانات) تک بیان کیا۔\nشعبی نے کہا: جنوں نے آپ سے خوراک کا سوار کیا اور وہ جزیرہ کے جنوں میں سے تھے ... حدیث کے آخری حصے تک جو شعبی کا قول ہے، عبد اللہ بن مسعود رضی اللہ عنہ کی حدیث سے الگ ہے۔"}],[941,"عبد اللہ بن ادریس نے داؤد سے باقی ماندہ سابقہ سند کے ساتھ نبی صلی اللہ علیہ وسلم سے وآثار نيرانهم تک روایت کیا اور بعد والا حصہ بیان نہیں کیا ۔","",{"u2":"عبد اللہ بن ادریس نے داؤد سے باقی ماندہ سابقہ سند کے ساتھ نبی صلی اللہ علیہ وسلم سے وآثار نیرانہم تک روایت کیا اور بعد والا حصہ بیان نہیں کیا۔"}],[942,"(شعبی کے بجائے ) ابراہیم ( نخعی ) نے علقمہ سے اور انہوں نے عبد اللہ سے روایت کی ، کہا : میں لیلۃ الجن کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نہ تھا اور میری خواہش تھی کہ میں آپ کے ساتھ ہوتا","",{"u2":"شعبی کے بجائے) ابراہیم (نخعی) نے علقمہ سے اور انہوں نے عبد اللہ سے روایت کی، کہا: میں لیلۃ الجن کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نہ تھا اور میری خواہش تھی کہ میں آپ کے ساتھ ہوتا"}],[943,"معن ( بن عبد الرحمن بن عبد اللہ بن مسعود ہذلی ) سے روایت ہے ، کہا : میں نے اپنے والد سے سنا ، کہا : میں نے مسروق سے پوچھا : جس رات جنوں نے کان لگا کر ( قرآن ) سنا ، اس کی اطلاع نبی صلی اللہ علیہ وسلم کو کس نے دی؟ انہوں نے کہا : مجھے تمہارے والد ( ابن مسعود رضی اللہ عنہ ) نے بتایا کہ آپ کو ان جنوں کی اطلاع ایک درخت نے دی تھی ۔ ( یہ آپ صلی اللہ علیہ وسلم کا معجزہ تھا ۔)","",{"u2":"معن (بن عبد الرحمن بن عبد اللہ بن مسعود ہذلی) سے روایت ہے، کہا: میں نے اپنے والد سے سنا، کہا: میں نے مسروق سے پوچھا: جس رات جنوں نے کان لگا کر (قرآن) سنا، اس کی اطلاع نبی صلی اللہ علیہ وسلم کو کس نے دی؟ انہوں نے کہا: مجھے تمہارے والد (ابن مسعود رضی اللہ عنہ) نے بتایا کہ آپ کو ان جنوں کی اطلاع ایک درخت نے دی تھی۔ (یہ آپ صلی اللہ علیہ وسلم کا معجزہ تھا۔)"}],[944,"حجاج صواف نے یحییٰ بن ابی کثیر سے ، انہوں نے عبد اللہ بن ابی قتادہ اور ابو سلمہ سے اور انہوں نے سیدنا ابو قتادہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ہمیں نماز پڑھاتے تو ظہر اور عصر کی پہلی دو رکعتوں میں سورہ فاتحہ اور دو سورتیں ( ہر رکعت میں فاتحہ کے بعد ایک سورت ) پڑھتے اور کبھی کبھار ہمیں کوئی آیت سنا دیتے ۔ ظہر کی پہلی رکعت لمبی کرتے اور دوسری رکعت مختصر کرتے اور صبح کی نماز میں بھی ایسا ہی کرتے ۔","",{"u2":"حجاج صواف نے یحییٰ بن ابی کثیر سے، انہوں نے عبد اللہ بن ابی قتادہ اور ابو سلمہ سے اور انہوں نے سیدنا ابو قتادہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں نماز پڑھاتے تو ظہر اور عصر کی پہلی دو رکعتوں میں سورہ فاتحہ اور دو سورتیں (ہر رکعت میں فاتحہ کے بعد ایک سورت) پڑھتے اور کبھی کبھار ہمیں کوئی آیت سنا دیتے۔ ظہر کی پہلی رکعت لمبی کرتے اور دوسری رکعت مختصر کرتے اور صبح کی نماز میں بھی ایسا ہی کرتے۔"}],[945,"(حجاج کے بجائے ) ہمام اور ابان بن یزید نے یحییٰ بن ابی کثیر سے ، انہوں نے عبد اللہ بن ابی قتادہ سے اور انہوں نے اپنے والد سے روایت کی کہ نبی صلی اللہ علیہ وسلم ظہر اور عصر کی پہلی دو رکعتوں میں ( سے ہر رکعت میں ) سورۃ فاتحہ اور ایک سورت پڑھتے اور کبھی کبھار ہمیں بھی کوئی آیت سنا دیتے اور آخری دو رکعتوں میں سورۃ فاتحہ پڑھا کرتے تھے ۔","",{"u2":"حجاج کے بجائے) ہمام اور ابان بن یزید نے یحییٰ بن ابی کثیر سے، انہوں نے عبد اللہ بن ابی قتادہ سے اور انہوں نے اپنے والد سے روایت کی کہ نبی صلی اللہ علیہ وسلم ظہر اور عصر کی پہلی دو رکعتوں میں(سے ہر رکعت میں) سورۃ فاتحہ اور ایک سورت پڑھتے اور کبھی کبھار ہمیں بھی کوئی آیت سنا دیتے اور آخری دو رکعتوں میں سورۃ فاتحہ پڑھا کرتے تھے۔"}],[946,"یحییٰ بن یحییٰ اور ابو بکر بن ابی شیبہ نے ہشیم سے ، انہوں نے منصور سے ، انہوں نے ولید بن مسلم سے ، انہوں نے ابو صدیق ( ناجی ) سے اور انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے ر وایت کی ، انہوں نے کہا : ہم ظہر اور عصر میں رسول اللہ صلی اللہ علیہ وسلم کے قیام کا اندازہ لگاتے تھے تو ہم نے ظہر کی پہلی دو رکعتوں میں قیام کا اندازہ ﴿الم 0 تنزيل﴾ ( السجدہ ) کی قراءت کے بقدر لگایا اور اس کی آخری دو رکعتوں کے قیام کا اندازہ اس سے نصف کے بقدر لگایا اور ہم نے عصر کی پہلی دو رکعتوں کے قیام کا اندازہ لگایا کہ وہ ظہر کی آخری دو رکعتوں کے برابر تھا اور عصر کی دو رکعتوں کا قیام اس سے آدھا تھا ۔ امام مسلم رضی اللہ عنہ کے استادہ ابو بکر بن ابی شیبہ نے اپنی روایت میں ﴿الم 0 تنزيل﴾ ( کا نام ) ذکر نہیں کیا ، انہوں نے کہا : تیس آیات کےبقدر","",{"u2":"یحییٰ بن یحییٰ اور ابو بکر بن ابی شیبہ نے ہشیم سے، انہوں نے منصور سے، انہوں نے ولید بن مسلم سے، انہوں نے ابو صدیق (ناجی) سے اور انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے ر وایت کی، انہوں نے کہا: ہم ظہر اور عصر میں رسول اللہ صلی اللہ علیہ وسلم کے قیام کا اندازہ لگاتے تھے تو ہم نے ظہر کی پہلی دو رکعتوں میں قیام کا اندازہ ﴿الم 0 تنزیل﴾ (السجدہ) کی قراءت کے بقدر لگایا اور اس کی آخری دو رکعتوں کے قیام کا اندازہ اس سے نصف کے بقدر لگایا اور ہم نے عصر کی پہلی دو رکعتوں کے قیام کا اندازہ لگایا کہ وہ ظہر کی آخری دو رکعتوں کے برابر تھا اور عصر کی دو رکعتوں کا قیام اس سے آدھا تھا۔\nامام مسلم رحمہ اللہ کے استادہ ابو بکر بن ابی شیبہ نے اپنی روایت میں ﴿الم 0 تنزیل﴾ (کا نام) ذکر نہیں کیا، انہوں نے کہا: تیس آیات کےبقدر"}],[947,"۔ ابو عوانہ نے منصور سے باقی ماندہ سابقہ سند سے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز میں پہلی دو رکعتوں میں سے ہر رکعت میں تیس آیات کے بقدر قراءت فرماتے تھے اور آخری دو میں پندرہ آیتوں کے بقدر یا یہ کہا : اس ( پہلی دو ) سے نصف ۔ اور عصر کی پہلی دو رکعتوں میں سے ہر رکعت میں پندرہ آیتوں کے برابر اور آخری دو میں اس سے نصف ۔","",{"u2":"۔ ابو عوانہ نے منصور سے باقی ماندہ سابقہ سند سے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز میں پہلی دو رکعتوں میں سے ہر رکعت میں تیس آیات کے بقدر قراءت فرماتے تھے اور آخری دو میں پندرہ آیتوں کے بقدر یا یہ کہا: اس (پہلی دو) سے نصف۔ اور عصر کی پہلی دو رکعتوں میں سے ہر رکعت میں پندرہ آیتوں کے برابر اور آخری دو میں اس سے نصف۔"}],[948,"ہشیم نے عبد الملک بن عمیر سے اور انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی کہ کوفہ والوں نے سیدنا عمر رضی اللہ عنہ سے سیدنا سعد رضی اللہ عنہ کی شکایت کی اور ( اس میں ) ان کی نماز کا بھی ذکر کیا ۔ سیدنا عمر رضی اللہ عنہ نے ان کی طرف پیغام بھیجا ، وہ آئے تو سیدنا عمر رضی اللہ عنہ نے ان سے ، کوفہ والوں نے ان کی نماز پر جو اعتراض کیا تھا ، اس کا تذکرہ کیا ، تو انہوں نے کہا : یقیناً میں انہیں رسول اللہ صلی اللہ علیہ وسلم کی نماز کی طرف نماز پڑھاتا ہوں ، اس میں کمی نہیں کرتا ۔ میں انہیں پہلی دو رکعتوں لمبی پڑھاتا ہوں اور آخری میں دو تخفیف کرتا ہوں ۔ اس پر عمر رضی اللہ عنہ نے فرمایا : اے ابو اسحاق! آپ کے بارے میں گمان ( بھی ) یہی ہے ۔","",{"u2":"ہشیم نے عبد الملک بن عمیر سے اور انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی کہ کوفہ والوں نے سیدنا عمر رضی اللہ عنہ سے سیدنا سیدنا سعد رضی اللہ عنہ کی شکایت کی اور (اس میں) ان کی نماز کا بھی ذکر کیا۔ سیدنا عمر رضی اللہ عنہ نے ان کی طرف پیغام بھیجا، وہ آئے تو سیدنا عمر رضی اللہ عنہ نے ان سے، کوفہ والوں نے ان کی نماز پر جو اعتراض کیا تھا، اس کا تذکرہ کیا، تو انہوں نے کہا: یقیناً میں انہیں رسول اللہ صلی اللہ علیہ وسلم کی نماز کی طرف نماز پڑھاتا ہوں، اس میں کمی نہیں کرتا۔ میں انہیں پہلی دو رکعتوں لمبی پڑھاتا ہوں اور آخری میں دو تخفیف کرتا ہوں۔ اس پر عمر رضی اللہ عنہ نے فرمایا: اے ابو اسحاق! آپ کے بارے میں گمان (بھی) یہی ہے۔"}],[949,"(ہشیم کے بجائے ) جریر نے عبد الملک بن عمیر سے اسی سند کے ساتھ یہی روایت بیان کی ۔","",{"u2":"ہشیم کے بجائے) جریر نے عبد الملک بن عمیر سے اسی سند کے ساتھ یہی روایت بیان کی۔"}],[950,"شعبہ نے ابوعون سے روایت کی ، انہوں نے کہا کہ میں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے سنا کہ سیدنا عمر رضی اللہ عنہ نے سیدنا سعد رضی اللہ عنہ سے کہا : لوگوں نے آپ کی ہر چیز حتیٰ کہ نماز کی بھی شکایت کی ہے ۔ سیدنا سعد رضی اللہ عنہ نے کہا : میں ( یہ کہتا ہوں کہ میں ) پہلی دو رکعتوں میں ( قیام کو ) طول دیتا ہوں اور آخری دو رکعتوں میں تخفیف کرتا ہوں ، میں نے جس طرح رسول اللہ صلی اللہ علیہ وسلم کی اقتدا میں نماز پڑھی تھی ، اس میں کوئی کوتاہی نہیں کرتا ۔ تو عمر رضی اللہ عنہ نے کہا : آپ کے بارے میں یہی گمان ہے یا آپ کے بارے میں میرا گمان یہی ہے ۔","",{"u2":"شعبہ نے ابوعون سے روایت کی، انہوں نے کہا کہ میں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے سنا کہ سیدنا عمر رضی اللہ عنہ نے سیدنا سعد رضی اللہ عنہ سے کہا: لوگوں نے آپ کی ہر چیز حتیٰ کہ نماز کی بھی شکایت کی ہے۔ سیدنا سعد رضی اللہ عنہ نے کہا: میں (یہ کہتا ہوں کہ میں) پہلی دو رکعتوں میں (قیام کو) طول دیتا ہوں اور آخری دو رکعتوں میں تخفیف کرتا ہوں، میں نے جس طرح رسول اللہ صلی اللہ علیہ وسلم کی اقتدا میں نماز پڑھی تھی، اس میں کوئی کوتاہی نہیں کرتا۔ تو عمر رضی اللہ عنہ نے کہا: آپ کے بارے میں یہی گمان ہے یا آپ کے بارے میں میرا گمان یہی ہے۔"}],[951,"۔ مسعر نے عبد الملک ( بن عمیر ) اور ابو عون سے روایت کی ، انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے ان کی حدیث کے ہم معنیٰ روایت بیان کی اور اس میں یہ اضافہ کیا ہے کہ سعد رضی اللہ عنہ نے کہا : بدوی مجھے نماز سکھائیں گے؟ ( میں نے تو خود رسول اللہ صلی اللہ علیہ وسلم سے نماز سیکھی ہے)","",{"u2":"۔ مسعر نے عبد الملک (بن عمیر) اور ابو عون سے روایت کی، انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے ان کی حدیث کے ہم معنیٰ روایت بیان کی اور اس میں یہ اضافہ کیا ہے کہ سعد رضی اللہ عنہ نے کہا: بدوی مجھے نماز سکھائیں گے؟ (میں نے تو خود رسول اللہ صلی اللہ علیہ وسلم سے نماز سیکھی ہے"}],[952,"۔ عطیہ بن قیس نے قزعہ سے ، انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ظہر کی نماز اقامت کہی جاتی اور کوئی جانے والا بقیع جاتا ، اپنی ضرورت سے فارغ ہو کر وضو کرتا ، پھر ( مسجد میں ) آتا اور رسول اللہ صلی اللہ علیہ وسلم اسے لمبا کرنے کی وجہ سے ابھی پہلی رکعت میں ہوتے ۔","",{"u2":"۔ عطیہ بن قیس نے قزعہ سے، انہوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ظہر کی نماز اقامت کہی جاتی اور کوئی جانے والا بقیع جاتا، اپنی ضرورت سے فارغ ہو کر وضو کرتا، پھر (مسجد میں) آتا اور رسول اللہ صلی اللہ علیہ وسلم اسے لمبا کرنے کی وجہ سے ابھی پہلی رکعت میں ہوتے۔"}],[953,"ربیعہ نے کہا : قزعہ نے مجھے حدیث سنائی ، کہا : میں ابو سعید خدری رضی اللہ عنہ کی خدمت میں حاضر ہوا ، ان کے پاس ( استفادے کے لیے ) کثرت سے لوگ موجود تھے ۔ جب یہ لوگ ان سے ( رخصت ہو کر ) منتشر ہو گئے تو میں نے عرض کی : میں آپ سے ان چیزوں کے بارے میں سوال نہیں کروں گا جن کے بارے میں لوگ آپ سے سوال کر رہے تھے ۔ میں نے کہا : میں آپ سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھتا ہوں ۔ انہوں نے کہا : اس سوال میں تیرے لیے بھلائی نہیں ہے ( کیونکہ تم نماز پڑھانے والے حکمرانوں کے پیچھے ایسے نماز نہیں پڑھ سکو گے ) انہوں نے ان کے سامنے دوبارہ اپنا مسئلہ پیش کیا تو ابو سعید خدری رضی اللہ عنہ نے کہا : ظہر کی نماز کھڑی کی جاتی اور ہم میں سے کوئی بقیع کی طرف جاتا ، اپنی ضرورت پوری کرتا ، پھر اپنے گھر آ کر وضو کرتا ، اس کے بعد واپس مسجد میں آتا تو رسول اللہ صلی اللہ علیہ وسلم ابھی پہلی رکعت میں ہوتے تھے ۔","",{"u2":"ربیعہ نے کہا: قزعہ نے مجھے حدیث سنائی، کہا: میں ابو سعید خدری رضی اللہ عنہ کی خدمت میں حاضر ہوا، ان کے پاس (استفادے کے لیے) کثرت سے لوگ موجود تھے۔ جب یہ لوگ ان سے (رخصت ہو کر) منتشر ہو گئے تو میں نے عرض کی: میں آپ سے ان چیزوں کے بارے میں سوال نہیں کروں گا جن کے بارے میں لوگ آپ سے سوال کر رہے تھے۔ میں نے کہا: میں آپ سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھتا ہوں۔ انہوں نے کہا: اس سوال میں تیرے لیے بھلائی نہیں ہے (کیونکہ تم نماز پڑھانے والے حکمرانوں کے پیچھے ایسے نماز نہیں پڑھ سکو گے) انہوں نے ان کے سامنے دوبارہ اپنا مسئلہ پیش کیا تو ابو سعید خدری رضی اللہ عنہ نے کہا: ظہر کی نماز کھڑی کی جاتی اور ہم میں سے کوئی بقیع کی طرف جاتا، اپنی ضرورت پوری کرتا، پھر اپنے گھر آ کر وضو کرتا، اس کے بعد واپس مسجد میں آتا تو رسول اللہ صلی اللہ علیہ وسلم ابھی پہلی رکعت میں ہوتے تھے۔"}],[954,"حجاج بن محمد نے ابن جریج سے روایت کی ، نیز عبد الرزاق نے ہمیں حدیث بیان کی ، کہا : ابن جریج نے ہمیں بتایا ، کہا : میں نے محمد بن عباد بن جعفر سے سنا ، کہہ رہے تھے : مجھے ابو سلمہ بن سفیان ، عبد اللہ بن عمرو بن عاص اور عبد اللہ بن مسیب سے عابدی نے سیدنا عبد اللہ بن سائب رضی اللہ عنہ سے روایت کرتے ہوئے خبر دی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم نے ہمیں مکہ میں صبح کی نماز پڑھائی تو سورہ مومنون کی قراءت شروع کی حتیٰ کہ موسیٰ اور ہارون علیہ السلام کا ذکر آیا یا عیسیٰ رضی اللہ عنہ کا ذکر آیا ( محمد بن عبادہ کو شک ہے یا راویوں نے اس کے سامنے ( بیان کرتے ہوئے ) اختلاف کیا ہے ) ( اس وقت ) رسول اللہ صلی اللہ علیہ وسلم کو کھانسی آنے لگی تو آپ رکوع میں چلے گئے ۔ عبد اللہ بن سائب رضی اللہ عنہ بھی اس نماز میں موجود تھے ۔ عبد الرزاق کی روایت میں ہے : آپ نے قراءت قطع کر دی اور رکوع میں چلے گئے ۔ اور ان کی حدیث میں ( راوی کا نام ) عبد اللہ بن عمرو ہے ، آگے ابن عاص نہیں کہا ۔","",{"u2":"حجاج بن محمد نے ابن جریج سے روایت کی، نیز عبد الرزاق نے ہمیں حدیث بیان کی، کہا: ابن جریج نے ہمیں بتایا، کہا: میں نے محمد بن عباد بن جعفر سے سنا، کہہ رہے تھے: مجھے ابو سلمہ بن سفیان، عبد اللہ بن عمرو بن عاص اور عبد اللہ بن مسیب سے عابدی نے سیدنا عبد اللہ بن سائب رضی اللہ عنہ سے روایت کرتے ہوئے خبر دی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم نے ہمیں مکہ میں صبح کی نماز پڑھائی تو سورہ مومنون کی قراءت شروع کی حتیٰ کہ موسیٰ اور ہارون﷩ کا ذکر آیا یا عیسیٰ علیہ السلام کا ذکر آیا (محمد بن عبادہ کو شک ہے یا راویوں نے اس کے سامنے (بیان کرتے ہوئے) اختلاف کیا ہے) (اس وقت) رسو ل اللہ صلی اللہ علیہ وسلم کو کھانسی آنے لگی تو آپ رکوع میں چلے گئے۔ عبد اللہ بن سائب رضی اللہ عنہ بھی اس نماز میں موجود تھے۔ عبد الرزاق کی روایت میں ہے: آپ نے قراءت قطع کر دی اور رکوع میں چلے گئے۔\nاور ان کی حدیث میں (راوی کا نام) عبد اللہ بن عمرو ہے، آگے ابن عاص نہیں کہا۔"}],[955,"سیدنا عمرو بن حریث رضی اللہ عنہ سے روایت کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فجر کی نماز میں ﴿واليل إذا عسعس﴾ ( قسم ہے رات کی! جب وہ جانے لگتی ہے ) پڑھتے ہوئے سنا","",{"u2":"سیدنا عمرو بن حریث رضی اللہ عنہ سے روایت کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فجر کی نماز میں ﴿والیل إذا عسعس﴾ (قسم ہے رات کی! جب وہ جانے لگتی ہے) پڑھتے ہوئے سنا"}],[956,"ابو عوانہ نے زیاد بن علاقہ سے اور انہوں نے سیدنا قطبہ نے مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے نماز پڑھی اور ہمیں رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی ، آپ ﴿ق والقرآن المجيد﴾ پڑھی حتی کہ آپ نے ﴿والنخل باسقت﴾ ( اور کجھور کے بلند وبالا درخت ) پڑھا تو میں اس آیت کو بار بار ( ذہن میں ) دہرانے لگا اور آپ نے جو کہا مجھے اس ( کے مفہوم ) کا پتہ نہ چلا ۔","",{"u2":"ابو عوانہ نے زیاد بن علاقہ سے اور انہوں نے حضرت قطبہ نے مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے نماز پڑھی اور ہمیں رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی، آپ ﴿ق والقرآن المجید﴾ پڑھی حتی کہ آپ نے ﴿والنخل باسقت﴾ (اور کجھور کے بلند وبالا درخت) پڑھا تو میں اس آیت کو بار بار (ذہن میں) دہرانے لگا اور آپ نے جو کہا مجھے اس (کے مفہوم) کا پتہ نہ چلا۔"}],[957,"(ابو عوانہ کے بجائے ) شریک اور سفیان بن عیینہ نے زیاد بن علاقہ سے اور انہوں نے سیدنا قطبہ بن مالک رضی اللہ عنہ سے روایت کی کہ انہوں نے فجر کی نماز میں نبی اکرم صلی اللہ علیہ وسلم کو ﴿والنخل باسقت لها طلع نضيد﴾ ( اور کجھور کے بلند وبالا درخت ( پیدا کیے ) جن کے خوشے تہ بہ تہ ہیں ) کی قراءت کرتے ہوئے سنا","",{"u2":"(ابو عوانہ کے بجائے) شریک اور سفیان بن عیینہ نے زیاد بن علاقہ سے اور انہوں نے سیدنا قطبہ بن مالک رضی اللہ عنہ سے روایت کی کہ انہوں نے فجر کی نماز میں نبی اکرم صلی اللہ علیہ وسلم کو ﴿والنخل باسقت لہا طلع نضید﴾ (اور کجھور کے بلند وبالا درخت (پیدا کیے) جن کے خوشے تہ بہ تہ ہیں) کی قراءت کرتے ہوئے سنا"}],[958,"(ابو عوانہ ، شریک اور ابن عیینہ کے بجائے ) شعبہ نے زیادہ بن علاقہ سے اور انہوں نے اپنے چچا ( سیدنا قطبہ بن مالک رضی اللہ عنہ ) سے روایت کی کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ صبح کی نماز پڑھی تو آپ نے پہلی رکعت میں ﴿والنخل باسقت طلع نضيد﴾ پڑھا اور بعض اوقات ( یہی بات سناتے ہوئے ) کہا : سورہ ق پڑھی ۔","",{"u2":"(ابو عوانہ، شریک اور ابن عیینہ کے بجائے) شعبہ نے زیادہ بن علاقہ سے اور انہوں نے اپنے چچا (سیدنا قطبہ بن مالک رضی اللہ عنہ) سے روایت کی کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ صبح کی نماز پڑھی تو آپ نے پہلی رکعت میں ﴿والنخل باسقت طلع نضید﴾ پڑھا اور بعض اوقات (یہی بات سناتے ہوئے) کہا: سورہ ق پڑھی۔"}],[959,"زائدہ نے کہا : ہمیں سماک بن حرب نے سیدنا جابر بن سمرہ رضی اللہ عنہما سے حدیث بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم فجر کی نماز میں ﴿ق والقرآن المجيد﴾ پڑھا کرتے تھے ، اس کے باوجود آپ کی نماز ہلکی تھی","",{"u2":"زائدہ نے کہا: ہمیں سماک بن حرب نے حضرت جابر بن سمرہ رضی اللہ عنہما سے حدیث بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم فجر کی نماز میں ﴿ق والقرآن المجید﴾ پڑھا کرتے تھے، اس کے باوجود آپ کی نماز ہلکی تھی"}],[960,"(زائدہ کے بجائے ) زہیر نے سماک سے روایت کی ، انہوں نے کہا : میں نے جابر بن سمرہ رضی اللہ عنہ سے نبی اکرم صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا تو انہوں نے جواب دیا : آپ ہلکی نماز پڑھاتے تھے اور ان لوگوں کی طرح نماز نہیں پڑھاتے تھے ۔ اور ( سماک نے ) کہا : مجھے انہوں ( جابر رضی اللہ عنہ ) نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم کی صبح کی نماز میں ﴿ق والقرآن﴾ اور ( طوالت میں ) اس جیسی سورتیں پڑھا کرتے تھے","",{"u2":"(زائدہ کے بجائے) زہیر نے سماک سے روایت کی، انہوں نے کہا: میں نے جابر بن سمرہ رضی اللہ عنہ سے نبی اکرم صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا تو انہوں نے جواب دیا: آپ ہلکی نماز پڑھاتے تھے اور ان لوگوں کی طرح نماز نہیں پڑھاتے تھے۔\nاور (سماک نے) کہا: مجھے انہوں (جابر رضی اللہ عنہ) نے بتایا کہ رسو ل اللہ صلی اللہ علیہ وسلم کی صبح کی نماز میں ﴿ق والقرآن﴾ اور (طوالت میں) اس جیسی سورتیں پڑھا کرتے تھے"}],[961,"عبد الرحمن بن مہدی نے کہا : ہمیں شعبہ نے سماک سے حدیث سنائی ، انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز میں ﴿واليل اذا يغشى﴾ ( اور رات کی قسم جب چھا جائے ) پڑھتے ، عصر میں بھی ایسی ہی کوئی سورت پڑھتے اور فجر کی نماز میں اس سے لمبی ( سورت پڑھتے ۔)","",{"u2":"عبد الرحمن بن مہدی نے کہا: ہمیں شعبہ نے سماک سے حدیث سنائی، انہوں نے حضرت جابر بن سمرہ رضی اللہ عنہما سے روایت کی، انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز میں ﴿والیل اذا یغشی﴾ (اور رات کی قسم جب چھا جائے) پڑھتے، عصر میں بھی ایسی ہی کوئی سورت پڑھتے اور فجر کی نماز میں اس سے لمبی (سورت پڑھتے۔)"}],[962,"ابو داؤد طیالسی نے شعبہ سے ، انہوں نے سماک سے اور انہوں نے سیدنا جابر بن سمرہ رضی اللہ عنہما سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز میں ﴿سبح اسم ربك الأعلى﴾ ( اور اپنے پروردگار کے اونچے نام کی تسبیح کر ) پڑھتے اور صبح کی نماز میں اس سے لمبی قراءت کرتے تھے ۔","",{"u2":"ابو داؤد طیالسی نے شعبہ سے، انہوں نے سماک سے اور انہوں نے حضرت جابر بن سمرہ رضی اللہ عنہما سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز میں ﴿سبح اسم ربک الأعلی﴾ (اور اپنے پروردگار کے اونچے نام کی تسبیح کر) پڑھتے اور صبح کی نماز میں اس سے لمبی قراءت کرتے تھے۔"}],[963,"(سلیمان ) تیمی نے ابو منہال سے اور انہوں نے سیدنا ابو برزہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز میں ساٹھ سے سو آیات تک پڑھا کرتے تھے ۔","",{"u2":"سلیمان) تیمی نے ابو منہال سے اور انہوں نے سیدنا ابو برزہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز میں ساٹھ سے سو آیات تک پڑھا کرتے تھے۔"}],[964,"(تیمی کے بجائے ) خالد حذاء نے ابو منہال سے ، انہوں نے سیدنا ابو برزہ اسلمی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی نماز میں ساٹھ سے سو تک آیتیں پڑھا کرتے تھے ۔","",{"u2":"تیمی کے بجائے) خالد حذاء نے ابو منہال سے، انہوں نے سیدنا ابو برزہ اسلمی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی نماز میں ساٹھ سے سو تک آیتیں پڑھا کرتے تھے۔"}],[965,"۔ مالک نے ابن شہاب ( زہری ) سے ، انہوں نے عبید اللہ بن عبد اللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ام فضل بنت حارث رضی اللہ عنہا نے مجھے ﴿والمرسلات عرفا﴾ پڑھتے ہوئے سنا تو کہنے لگیں : بیٹا! تم نے یہ سورت پڑھ کر مجھے یاد کرا دیا کہ بے شک یہ آخری سورت ہے جو میں نے رسول اللہ صلی اللہ علیہ وسلم کو مغرب کی نماز میں تلاوت کرتے ہوئے سنی ۔","",{"u2":"۔ مالک نے ابن شہاب (زہری) سے، انہوں نے عبید اللہ بن عبد اللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ام فضل بنت حارث رضی اللہ عنہا نے مجھے ﴿والمرسلات عرفا﴾ پڑھتے ہوئے سنا تو کہنے لگیں: بیٹا! تم نے یہ سورت پڑھ کر مجھے یاد کرا دیا کہ بے شک یہ آخری سورت ہے جو میں نے رسول اللہ صلی اللہ علیہ وسلم کو مغرب کی نماز میں تلاوت کرتے ہوئے سنی۔"}],[966,"(امام مالک کے بجائے ) سفیان ( بن عیینہ ) ، یونس ، معمر اور صالح نے زہری سے اسی سابقہ سند کے ساتھ روایت کی اور صالح کی حدیث میں یہ اضافہ ہے : پھر آپ نے اس کے بعد نماز نہیں پڑھائی یہاں تک کہ اللہ تعالیٰ نے آپ کو اپنے پاس بلا لیا","",{"u2":"(امام مالک کے بجائے) سفیان (بن عیینہ)، یونس، معمر اور صالح نے زہری سے اسی سابقہ سند کے ساتھ روایت کی اور صالح کی حدیث میں یہ اضافہ ہے: پھر آپ نے اس کے بعد نماز نہیں پڑھائی یہاں تک کہ اللہ تعالیٰ نے آپ کو اپنے پاس بلا لیا"}],[967,"مالک نے ابن شہاب ( زہری ) سے ، انہوں نے محمد بن جبیر بن مطعم سے اور انہوں نے اپنے والد ( جبیر بن مطعم رضی اللہ عنہ ) سے روایت کی ، انہوں نے کہا کہ میں نے مغرب کی نماز میں رسول اللہ صلی اللہ علیہ وسلم کو سورہ طہ پڑھتے ہوئے سنا ۔","",{"u2":"مالک نے ابن شہاب (زہری) سے، انہوں نے محمد بن جبیر بن مطعم سے اور انہوں نے اپنے والد (جبیر بن مطعم رضی اللہ عنہ) سے روایت کی، انہوں نے کہا کہ میں نے مغرب کی نماز میں رسول اللہ صلی اللہ علیہ وسلم کو سورہ طہ پڑھتے ہوئے سنا۔"}],[968,"سفیان ، یونس اور معمر نے اپنی اپنی سند سے زہری سے اسی سابقہ سند کے ساتھ اس جیسی روایت بیان کی ۔","",{"u2":"سفیان، یونس اور معمر نے اپنی اپنی سند سے زہری سے اسی سابقہ سند کے ساتھ اس جیسی روایت بیان کی۔"}],[969,"۔ شعبہ نے عدی سے روایت کی ، انہوں نے کہا : میں نے سیدنا براء رضی اللہ عنہ کو نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کرتے ہوئے سنا کہ آپ صلی اللہ علیہ وسلم سفر میں تھے ، آپ نے عشاء کی پڑھائی تو اس کی ایک رکعت میں ﴿والتين والزيتون﴾ پڑھی ۔","",{"u2":"۔ شعبہ نے عدی سے روایت کی، انہوں نے کہا: میں نے سیدنا براء رضی اللہ عنہ کو نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کرتے ہوئے سنا کہ آپ صلی اللہ علیہ وسلم سفر میں تھے، آپ نے عشاء کی پڑھائی تو اس کی ایک رکعت میں ﴿والتین والزیتون﴾ پڑھی۔"}],[970,"(شعبہ کے بجائے ) یحییٰ بن سعید نے عدی بن ثابت سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھی تو آپ نے ﴿والتين والزيتون﴾ کی قراءت کی ۔","",{"u2":"(شعبہ کے بجائے) یحییٰ بن سعید نے عدی بن ثابت سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھی تو آپ نے ﴿والتین والزیتون﴾ کی قراءت کی۔"}],[971,"(شعبہ اور یحییٰ کے بجائے ) مسعر نے عدی بن ثابت سے روایت کی ، انہوں نے کہا : میں نے سیدنا براء بن عازب رضی اللہ عنہ سے سنا ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو عشاء کی نماز میں ﴿والتين والزيتون﴾ کی قراءت کرتے ہوئے سنا ، میں نے کسی کو نہیں سنا جس کی آواز آپ سے زیادہ اچھی ہو ۔","",{"u2":"(شعبہ اور یحییٰ کے بجائے) مسعر نے عدی بن ثابت سے روایت کی، انہوں نے کہا: میں نے سیدنا براء بن عازب رضی اللہ عنہ سے سنا، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو عشاء کی نماز میں ﴿والتین والزیتون﴾ کی قراءت کرتے ہوئے سنا، میں نے کسی کو نہیں سنا جس کی آواز آپ سے زیادہ اچھی ہو۔"}],[972,"سفیان نے عمرو سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : سیدنا معاذ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھا کرتے تھے ، پھر آ کر اپنے قبیلے کی ( مسجد میں ) امامت کراتے ، ایک رات انہوں نے عشاء کی نماز رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پڑھی ، پھر اپنی قوم کے پاس آئے ، ان کی امامت اور ( سورۃ فاتحہ کے بعد ) سورۃ بقرہ پڑھنی شروع کر دی ۔ ایک شخص الگ ہو گیا ، ( نماز سے ، سلام پھیرا ، پھر اکیلے نماز پڑھی اور چلا گیا تو لوگوں نے اس سے کہا : اے فلاں! کیا تو منافق ہو گیا ہے؟ اس نے جواب دیا : اللہ کی قسم! نہیں ، میں ضرور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر آپ کو اس معاملے سے آگاہ کروں گا ، چنانچہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی : اے اللہ کے رسول! ہم ان اونٹوں والے ہیں جو پانی ڈھوتے ہیں ، دن بھر کام کرتے ہیں اور معاذ رضی اللہ عنہ نے عشاء کی نماز آپ کے ساتھ پڑھی ، پھر آ کر سورۃ بقرہ کے ساتھ نماز شروع کر دی ۔ رسول اللہ صلی اللہ علیہ وسلم نے ( یہ سن کر ) سیدنا معاذ رضی اللہ عنہ کی طرف رخ کیا اور فرمایا : ’’اے معاذ! کیا لوگوں کو فتنے میں مبتلا کرنے والے ہو؟ فلاں سورت پڑھا کرو اور فلاں سورت پڑھا کرو ۔ ‘‘ سفیان نے کہا : میں نے عمرو سے کہا : ابو زبیر نے ہمیں جابر رضی اللہ عنہ سے بیان کیا کہ آپ نے فرمایا : ﴿والشمس وضحاها﴾ ﴿والضحى﴾ ، ﴿واليل إذا يغشى﴾ اور ﴿سبح اسم ربك الأعلى﴾ پڑھا کرو ۔ اور عمرو نے کہا : اس جیسی ( سورتیں پڑھا کرو)","",{"u2":"سفیان نے عمرو سے، انہوں نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: سیدنا معاذ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھا کرتے تھے، پھر آ کر اپنے قبیلے کی (مسجد میں) امامت کراتے، ایک رات انہوں نے عشاء کی نماز رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پڑھی، پھر اپنی قوم کے پاس آئے، ان کی امامت اور (سورۃ فاتحہ کے بعد) سورۃ بقرہ پڑھنی شروع کر دی۔ ایک شخص الگ ہو گیا، (نماز سے، سلام پھیرا، پھر اکیلے نماز پڑھی اور چلا گیا تو لوگوں نے اس سے کہا: اے فلاں! کیا تو منافق ہو گیا ہے؟ اس نے جواب دیا: اللہ کی قسم! نہیں، میں ضرور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر آپ کو اس معاملے سے آگاہ کروں گا، چنانچہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی: اے اللہ کے رسول! ہم ان اونٹوں والے ہیں جو پانی ڈھوتے ہیں، دن بھر کام کرتے ہیں اور معاذ رضی اللہ عنہ نے عشاء کی نماز آپ کے ساتھ پڑھی، پھر آ کر سورۃ بقرہ کے ساتھ نماز شروع کر دی۔ رسول اللہ صلی اللہ علیہ وسلم نے (یہ سن کر) سیدنا معاذ رضی اللہ عنہ کی طرف رخ کیا اور فرمایا: ’’اے معاذ! کیا لوگوں کو فتنے میں مبتلا کرنے والے ہو؟ فلاں سورت پڑھا کرو اور فلاں سورت پڑھا کرو۔‘‘\nسفیان نے کہا: میں نے عمرو سے کہا: ابو زبیر نے ہمیں جابر رضی اللہ عنہ سے بیان کیا کہ آپ نے فرمایا: ﴿والشمس وضحاہا﴾ ﴿والضحی﴾، ﴿والیل إذا یغشی﴾ اور ﴿سبح اسم ربک الأعلی﴾ پڑھا کرو۔ اور عمرو نے کہا: اس جیسی (سورتیں پڑھا کرو"}],[973,"ابو زبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ معاذ بن جبل انصاری رضی اللہ عنہ نے اپنے ساتھیوں کو عشاء کی نماز پڑھائی اور اس میں طویل قراءت کی ۔ ہم میں سے ایک آدمی نکلا اور الگ نماز پڑھ لی ۔ معاذ رضی اللہ عنہ کو اس کے بارے میں بتایا گیا تو انہوں نے کہا : وہ منافق ہے ۔ جب اس آدمی تک یہ بات پہنچی تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آ پ کو بتایا کہ معاذ نے کیا کہا ، اس پر رسول اللہ صلی اللہ علیہ وسلم نے معاذ رضی اللہ عنہ سے فرمایا : ’’اے معاذ! کیا تم فتنہ ڈالنے والے بننا چاہتے ہو؟ جب لوگوں کی امامت کراؤ تو ﴿والشمس وضحها﴾ ، ﴿سبح اسم ربك الأعلى﴾ ، ﴿اقرأ باسم ربك الذي خلق﴾ اور ﴿واليل إذا يغشى﴾ پڑھا کرو ۔ ‘‘","",{"u2":"ابو زبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ معاذ بن جبل انصاری رضی اللہ عنہ نے اپنے ساتھیوں کو عشاء کی نماز پڑھائی اور اس میں طویل قراءت کی۔ ہم میں سے ایک آدمی نکلا اور الگ نماز پڑھ لی۔ معاذ رضی اللہ عنہ کو اس کے بارے میں بتایا گیا تو انہوں نے کہا: وہ منافق ہے۔ جب اس آدمی تک یہ بات پہنچی تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آ پ کو بتایا کہ معاذ نے کیا کہا، اس پر رسول اللہ صلی اللہ علیہ وسلم نے معاذ رضی اللہ عنہ سے فرمایا: ’’اے معاذ! کیا تم فتنہ ڈالنے والے بننا چاہتے ہو؟ جب لوگوں کی امامت کراؤ تو ﴿والشمس وضحہا﴾، ﴿سبح اسم ربک الأعلی﴾، ﴿اقرأ باسم ربک الذی خلق﴾ اور ﴿والیل إذا یغشی﴾ پڑھا کرو۔‘‘"}],[974,"منصور نے عمرو بن دینار سے اور انہوں نے سیدنا جابربن عبد اللہ رضی اللہ عنہما سے روایت کی کہ معاذ بن جبل رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھا کرتے تھے ، پھر اپنی قوم میں آ کر یہی نماز ان کو پڑھاتے تھے ۔","",{"u2":"منصور نے عمرو بن دینار سے اور انہوں نے حضرت جابربن عبد اللہ رضی اللہ عنہما سے روایت کی کہ معاذ بن جبل رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھا کرتے تھے، پھر اپنی قوم میں آ کر یہی نماز ان کو پڑھاتے تھے۔"}],[975,"(منصور کے بجائے ) ایوب نے عمرو بن دینار سے اور انہوں نے سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت کی کہ معاذ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھا کرتے تھے ، پھر اپنی قوم کی مسجد میں آ کر ان کو نماز پڑھاتے تھے ۔","",{"u2":"(منصور کے بجائے) ایوب نے عمرو بن دینار سے اور انہوں نے حضرت جابر بن عبد اللہ رضی اللہ عنہما سے روایت کی کہ معاذ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھا کرتے تھے، پھر اپنی قوم کی مسجد میں آ کر ان کو نماز پڑھاتے تھے۔"}],[976,"ہشیم نے اسماعیل بن ابی خالد سے ، انہوں نے قیس سے اور انۂں نے سیدنا ابو مسعود انصاری رضی اللہ عنہ سے روایت کی کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی : بے شک میں فلاں آدمی کی وجہ سے صبح کی نماز سے پیچھے رہتا ہوں کیونکہ وہ ہمیں بہت لمبی نماز پڑھاتا ہے ۔ ابو مسعود رضی اللہ عنہ بیان کرتے ہیں : میں نے نبی اکرم صلی اللہ علیہ وسلم کو کبھی نہیں دیکھا کہ پند ونصیحت کرتے وقت ، آپ کبھی اس دن سے زیادہ غضب ناک ہوئے ہوں ۔ آپ نے فرمایا : ’’لوگو! تم میں سے بعض ( دوسروں کو نماز سے ) متنفر کرنے والے ہیں ۔ تم میں سے جو بھی لوگوں کی امامت کرائے وہ اختصار سے کام لے کیونکہ اس کے پیچھے بوڑھے ، کمزور اور حاجت مند لوگ ہوتے ہیں ۔ ‘‘","",{"u2":"ہشیم نے اسماعیل بن ابی خالد سے، انہوں نے قیس سے اور انۂں نے سیدنا ابو مسعود انصاری رضی اللہ عنہ سے روایت کی کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی: بے شک میں فلاں آدمی کی وجہ سے صبح کی نماز سے پیچھے رہتا ہوں کیونکہ وہ ہمیں بہت لمبی نماز پڑھاتا ہے۔ ابو مسعود رضی اللہ عنہ بیان کرتے ہیں: میں نے نبی اکرم صلی اللہ علیہ وسلم کو کبھی نہیں دیکھا کہ پند ونصیحت کرتے وقت، آپ کبھی اس دن سے زیادہ غضب ناک ہوئے ہوں۔ آپ نے فرمایا: ’’لوگو! تم میں سے بعض (دوسروں کو نماز سے) متنفر کرنے والے ہیں۔ تم میں سے جو بھی لوگوں کی امامت کرائے وہ اختصار سے کام لے کیونکہ اس کے پیچھے بوڑھے، کمزور اور حاجت مند لوگ ہوتے ہیں۔‘‘"}],[977,"۔ ہشیم ، وکیع ، عبد اللہ بن نمیر اور سفیان نے اسماعیل ( بن ابی خالد ) سے اسی سند کے ساتھ ہشیم کی حدیث کی طرح روایت کی ۔","",{"u2":"۔ ہشیم، وکیع، عبد اللہ بن نمیر اور سفیان نے اسماعیل (بن ابی خالد) سے اسی سند کے ساتھ ہشیم کی حدیث کی طرح روایت کی۔"}],[978,"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی فرد لوگوں کی امامت کرائے تو وہ ہلکی نماز پڑھائے کیونکہ ان ( نمازیوں ) میں بچے ، بوڑھے ، کمزور اور بیمار بھی ہوتے ہیں اور جب اکیلا پڑھے تو جیسے چاہے پڑھے ۔ ‘‘","",{"u2":"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی فرد لوگوں کی امامت کرائے تو وہ ہلکی نماز پڑھائے کیونکہ ان (نمازیوں) میں بچے، بوڑھے، کمزور اور بیمار بھی ہوتے ہیں اور جب اکیلا پڑھے تو جیسے چاہے پڑھے۔‘‘"}],[979,"ہمام بن منبہ سے روایت ہے ، انہوں نے کہا : ہمیں یہ احادیث ابو ہریرہ رضی اللہ عنہ نے محمد رسو اللہ صلی اللہ علیہ وسلم سے بیان کیں ، انہوں نے متعدد احادیث بیان کیں اور کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے کوئی لوگوں کا امام بنے تو وہ نماز میں تخفیف کرے کیونکہ لوگوں میں بوڑھے بھی ہوتے ہیں اور ان میں کمزور بھی ہوتے ہیں اور جب اکیلا پڑھے تو اپنی نماز جتنی چاہے طویل کر لے ۔ ‘‘ <ہیڈنگ 1> </ہیڈنگ 1>","",{"u2":"ہمام بن منبہ سے روایت ہے، انہوں نے کہا: ہمیں یہ احادیث ابو ہریرہ رضی اللہ عنہ نے محمد رسو اللہ صلی اللہ علیہ وسلم سے بیان کیں، انہوں نے متعدد احادیث بیان کیں اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب تم میں سے کوئی لوگوں کا امام بنے تو وہ نماز میں تخفیف کرے کیونکہ لوگوں میں بوڑھے بھی ہوتے ہیں اور ان میں کمزور بھی ہوتے ہیں اور جب اکیلا پڑھے تو اپنی نماز جتنی چاہے طویل کر لے۔‘‘ <ہیڈنگ 1> </ہیڈنگ 1>"}],[980,"۔ ابو سلمہ بن عبد الرحمن نے خبر دی کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی شخص لوگوں کو نماز پڑھائے تو وہ تخفیف کرے کیونکہ لوگوں میں کمزور ، بیمار اور ضرورت مند بھی ہوتے ہیں ۔ ‘‘","",{"u2":"۔ ابو سلمہ بن عبد الرحمن نے خبر دی کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص لوگوں کو نماز پڑھائے تو وہ تخفیف کرے کیونکہ لوگوں میں کمزور، بیمار اور ضرورت مند بھی ہوتے ہیں۔‘‘"}],[981,"(ابو سلمہ کے بجائے ) ابو بکر بن عبد الرحمن نے حدیث بیان کی کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : .... اسی کے مانند ، البتہ اس میں سقیم ( بیمار ) کی جگہ کبیر ( بوڑھا ) کہا ہے ۔","",{"u2":"ابو سلمہ کے بجائے) ابو بکر بن عبد الرحمن نے حدیث بیان کی کہ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: .... اسی کے مانند، البتہ اس میں سقیم (بیمار) کی جگہ کبیر (بوڑھا) کہا ہے۔"}],[982,"موسیٰ بن طلحہ نے کہا : مجھے سیدنا عثمان بن ابو عاص ثقفی رضی اللہ عنہ نے حدیث سنائی کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا : ’’ اپنی قوم کی امامت کراؤ ۔ ‘‘ میں نے عرض کی : اے اللہ کے رسول! میں اپنے دل میں کچھ محسوس کرتا ہوں ۔ آپ نے فرمایا : ’’میرے قریب ہو جاؤ ۔ ‘‘ آپ نے مجھے اپنے سامنے بٹھا لیا ، پھر اپنی ہتھیلی میر ی دونوں چھاتیوں کے درمیان رکھی ، اس کے بعد فرمایا : ’’رخ پھیرو ۔ ‘‘ اس کے بعد آپ نے ہتھیلی میری پشت میرے دونوں کندھوں کے درمیان رکھی ، پھر فرمایا : ’’ اپنی قوم کی امامت کراؤ اور جو لوگوں کا امام بنے ، وہ تخفیف کرے کیونکہ ان میں بوڑھے ہوتے ہیں ، ان میں بیمار ہوتے ہیں ، ان میں کمزور ہوتے ہیں اور ان میں ضرورت مند ہوتے ہیں ، جب تم میں سے کوئی اکیلا نماز پڑھے تو جیسے چاہے پڑھے ۔ ‘‘","",{"u2":"موسیٰ بن طلحہ نے کہا: مجھے سیدنا عثمان بن ابو عاص ثقفی رضی اللہ عنہ نے حدیث سنائی کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: ’’ اپنی قوم کی امامت کراؤ۔‘‘ میں نے عرض کی: اے اللہ کے رسول! میں اپنے دل میں کچھ محسوس کرتا ہوں۔ آپ نے فرمایا: ’’میرے قریب ہو جاؤ۔‘‘ آپ نے مجھے اپنے سامنے بٹھا لیا، پھر اپنی ہتھیلی میر ی دونوں چھاتیوں کے درمیان رکھی، اس کے بعد فرمایا: ’’رخ پھیرو۔‘‘ اس کے بعد آپ نے ہتھیلی میری پشت میرے دونوں کندھوں کے درمیان رکھی، پھر فرمایا: ’’ اپنی قوم کی امامت کراؤ اور جو لوگوں کا امام بنے، وہ تخفیف کرے کیونکہ ان میں بوڑھے ہوتے ہیں، ان میں بیمار ہوتے ہیں، ان میں کمزور ہوتے ہیں اور ان میں ضرورت مند ہوتے ہیں، جب تم میں سے کوئی اکیلا نماز پڑھے تو جیسے چاہے پڑھے۔‘‘"}],[983,"سعید بن مسیب نے کہا : سیدنا عثمان بن ابی عاص رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے آخری بات جو میرے ذمے لگائی یہ تھی : ’’ جب تم لوگوں کی امامت کراؤ تو انہیں نماز ہلکی پڑھاؤ","",{"u2":"سعید بن مسیب نے کہا: سیدنا عثمان بن ابی عاص رضی اللہ عنہ نے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے آخری بات جو میرے ذمے لگائی یہ تھی: ’’ جب تم لوگوں کی امامت کراؤ تو انہیں نماز ہلکی پڑھاؤ"}],[984,"عبد العزیز بن صہیب نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نماز میں تخفیف کرتے اور مکمل ادا کرتے تھے ۔","",{"u2":"عبد العزیز بن صہیب نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نماز میں تخفیف کرتے اور مکمل ادا کرتے تھے۔"}],[985,"قتادہ نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ( سب سے زیادہ ) مکمل صورت میں سب سے زیادہ تخفیف کے ساتھ نماز پڑھانے والے تھے ۔","",{"u2":"قتادہ نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم (سب سے زیادہ) مکمل صورت میں سب سے زیادہ تخفیف کے ساتھ نماز پڑھانے والے تھے۔"}],[986,"شریک بن عبد اللہ ابی نمر نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ میں نے کبھی کسی ایسے امام کے پیچھے نماز نہیں پڑھی جو رسول اللہ صلی اللہ علیہ وسلم کی نماز سے زیادہ ہلکی اور زیادہ مکمل نماز پڑھانے والا ہو ۔","",{"u2":"شریک بن عبد اللہ ابی نمر نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ میں نے کبھی کسی ایسے امام کے پیچھے نماز نہیں پڑھی جو رسول اللہ صلی اللہ علیہ وسلم کی نماز سے زیادہ ہلکی اور زیادہ مکمل نماز پڑھانے والا ہو۔"}],[987,"۔ ثابت بنانی نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ماں کے ساتھ ( آئے ہوئے ) بچے کا رونا سنتے اور آپ نماز میں ہوتے تو ہلکی سورت یا ( کہا ) چھوٹی سورت پڑھ لیتے ۔","",{"u2":"۔ ثابت بنانی نے سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ماں کے ساتھ (آئے ہوئے) بچے کا رونا سنتے اور آپ نماز میں ہوتے تو ہلکی سورت یا (کہا) چھوٹی سورت پڑھ لیتے۔"}],[988,"قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ میں نماز شروع کرتا ہوں ، میرا ارادہ لمبی نماز ( پڑھنے ) کا ہوتا ہے ، پھر بچے کا رونا سنتا ہوں تو بچے پر ماں کے غم کی شدت کی وجہ سے ( نماز میں ) تخفیف کر دیتا ہوں ۔ ‘‘","",{"u2":"قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ میں نماز شروع کرتا ہوں، میرا ارادہ لمبی نماز (پڑھنے) کا ہوتا ہے، پھر بچے کا رونا سنتا ہوں تو بچے پر ماں کے غم کی شدت کی وجہ سے (نماز میں) تخفیف کر دیتا ہوں۔‘‘"}],[989,"ہلال بن ابی حمید نے عبد الرحمن بن ابی لیلیٰ سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی کہ میں نے محمد صلی اللہ علیہ وسلم کی معیت میں ( پڑھی جانے والی ) نماز کو غور سے دیکھا تو میں نے آپ کے قیام ، رکوع ، رکوع کے بعد اعتدال اور آپ کے سجدے ، دونوں سجدوں کے درمیان جلسے ( بیٹھنا ) اور آپ کے دوسرے سجدے اور اس کے بعد سلام اور رخ پھیرنے کے درمیان وقفے کو تقریبا برابر پایا ۔","",{"u2":"ہلال بن ابی حمید نے عبد الرحمن بن ابی لیلیٰ سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی کہ میں نے محمد صلی اللہ علیہ وسلم کی معیت میں (پڑھی جانے والی) نماز کو غور سے دیکھا تو میں نے آپ کے قیام، رکوع، رکوع کے بعد اعتدال اور آپ کے سجدے، دونوں سجدوں کے درمیان جلسے (بیٹھنا) اور آپ کے دوسرے سجدے اور اس کے بعد سلام اور رخ پھیرنے کے درمیان وقفے کو تقریبا برابر پایا۔"}],[990,"۔ عبید اللہ کے والجد معاذ عنبری نے کہا : ہمیں شعبہ نے حکم سے حدیث سنائی ، انہوں نے کہا کہ ابن اشعث کے زمانے میں ایک شخص ( حکم نے اس کا نام لیا ) کوفہ ( کے اقتدار ) پر قابض ہو گیا ، اس نے ابو عبیدہ بن عبد اللہ ( بن مسعود ) کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں ، وہ نماز پڑھاتے تھے ، جب وہ رکوع سے سر اٹھاتے تو اتنی دیر کھڑے ہوتے کہ میں یہ دعا پڑھ لیتا : ’’ اے اللہ! ہمارب ! حمد تیرے ہی لیے ہے جس سے آسمان و زمین بھر جائیں اور کے سوا جو چیز تو چاہے بھر جائے ۔ اے عظمت وثنا کے سزا وار! جو تو دے اس کو کوئی روکنے والا نہیں اور جو تو روک لے اسے کوئی بھی دینے والا نہیں اور نہ ہی کسی مرتبے والے کو تیرے سامنے اس کا مرتبہ نفع دے سکتا ہے ۔ ‘‘ ( صرف تیری رحمت ہے جو فائدہ دے سکتی ہے ۔ ) حکم نے کہا : میں نے عبد الرحمن بن ابی لیلیٰ سے اس کا ذکر کیا تو انہوں نے کہا : میں نے براء بن عازب رضی اللہ عنہ کو یہ کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم کی نماز ( قیام ) ، آپ کا رکوع اور جب آپ رکوع سے سر اٹھاتے ، آپ کے سجدے اور دونوں سجدوں کے درمیان ( والا بیٹھنے ) کا وقفہ تقریباً برابر تھے ۔ شعبہ نے کہا : میں نے اس کا ذکر عمرو بن مرہ سے کیا تو انہوں نے کہا : میں نے عبد الرحمان بن ابی لیلیٰ کو دیکھا ہے ، ان کی نماز اس طرح نہیں ہوتی تھی ۔ ( وہ ثقہ تھے ۔ ان کی روایت قابل اعتماد ہے چاہے وہ اس پر پوری طرح عمل نہ کر سکتے ہوں)","",{"u2":"۔ عبید اللہ کے والجد معاذ عنبری نے کہا: ہمیں شعبہ نے حکم سے حدیث سنائی، انہوں نے کہا کہ ابن اشعث کے زمانے میں ایک شخص (حکم نے اس کا نام لیا) کوفہ (کے اقتدار) پر قابض ہو گیا، اس نے ابو عبیدہ بن عبد اللہ (بن مسعود) کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں، وہ نماز پڑھاتے تھے، جب وہ رکوع سے سر اٹھاتے تو اتنی دیر کھڑے ہوتے کہ میں یہ دعا پڑھ لیتا: ’’ اے اللہ! ہمارب! حمد تیرے ہی لیے ہے جس سے آسمان و زمین بھر جائیں اور کے سوا جو چیز تو چاہے بھر جائے۔ اے عظمت وثنا کے سزا وار! جو تو دے اس کو کوئی روکنے والا نہیں اور جو تو روک لے اسے کوئی بھی دینے والا نہیں اور نہ ہی کسی مرتبے والے کو تیرے سامنے اس کا مرتبہ نفع دے سکتا ہے۔‘‘ (صرف تیری رحمت ہے جو فائدہ دے سکتی ہے۔)\nحکم نے کہا: میں نے عبد الرحمن بن ابی لیلیٰ سے اس کا ذکر کیا تو انہوں نے کہا: میں نے براء بن عازب رضی اللہ عنہ کو یہ کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم کی نماز (قیام)، آپ کا رکوع اور جب آپ رکوع سے سر اٹھاتے، آپ کے سجدے اور دونوں سجدوں کے درمیان (والا بیٹھنے) کا وقفہ تقریباً برابر تھے۔\nشعبہ نے کہا: میں نے اس کا ذکر عمرو بن مرہ سے کیا تو انہوں نے کہا: میں نے عبد الرحمان بن ابی لیلیٰ کو دیکھا ہے، ان کی نماز اس طرح نہیں ہوتی تھی۔ (وہ ثقہ تھے۔ ان کی روایت قابل اعتماد ہے چاہے وہ اس پر پوری طرح عمل نہ کر سکتے ہوں"}],[991,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حکم سے حدیث بیان کی کہ جب مطر بن ناجیہ کوفہ پر قابض ہو گیا تو اس نے ابو عبیدہ کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں ... اور ( پوری ) حدیث بیان کی ۔","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے حکم سے حدیث بیان کی کہ جب مطر بن ناجیہ کوفہ پر قابض ہو گیا تو اس نے ابو عبیدہ کو حکم دیا کہ وہ لوگوں کو نماز پڑھائیں ... اور (پوری) حدیث بیان کی۔"}],[992,"۔ خلف بن ہشام نے حماد بن زید سے حدیث بیان کی ، انہوں نے ثابت سے اور انہوں نے کہا : ہمیں ثابت نے سیدنا انس رضی اللہ عنہ سے خبر دی ، انہوں نے کہا : میں تمہیں ایسی نماز پڑھانے میں کوتاہی نہیں کرتا ، جیسی میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ( کہ وہ ) ہمیں پڑھاتے تھے ۔ ثابت نے کہا : انس رضی اللہ عنہ ایک ایسا کام کیا کرتے تھے جو میں تمہیں کرتے ہوئے نہیں دیکھتا ۔ جب وہ رکوع سے اپنا سر اٹھاتے تو سیدھے کھڑے ہو جاتے حتیٰ کہ کہنے والا کہتا کہ وہ بھول گئے ہیں اور جب وہ سجدہ سے اپنا سر اٹھاتے تو ٹھہرے رہتے حتیٰ کہ کہنے والا کہتا : وہ بھول گئے ہیں ۔","",{"u2":"۔ خلف بن ہشام نے حماد بن زید سے حدیث بیان کی، انہوں نے ثابت سے اور انہوں نے کہا: ہمیں ثابت نے سیدنا انس رضی اللہ عنہ سے خبر دی، انہوں نے کہا: میں تمہیں ایسی نماز پڑھانے میں کوتاہی نہیں کرتا، جیسی میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا (کہ وہ) ہمیں پڑھاتے تھے۔\nثابت نے کہا: انس رضی اللہ عنہ ایک ایسا کام کیا کرتے تھے جو میں تمہیں کرتے ہوئے نہیں دیکھتا۔ جب وہ رکوع سے اپنا سر اٹھاتے تو سیدھے کھڑے ہو جاتے حتیٰ کہ کہنے والا کہتا کہ وہ بھول گئے ہیں اور جب وہ سجدہ سے اپنا سر اٹھاتے تو ٹھہرے رہتے حتیٰ کہ کہنے والا کہتا: وہ بھول گئے ہیں۔"}],[993,"۔ بہز بن حماد سے حدیث بیان کی ، انہوں نے کہا : ہمیں ثابت نے سیدنا انس رضی اللہ عنہ سے خبر دی ، انہوں نے کہا : میں نے کسی کے پیچھے نبی اکرم صلی اللہ علیہ وسلم سے زیادہ ہلکی نماز نہیں پڑھی جو کامل ہو ۔ رسول اللہ صلی اللہ علیہ وسلم کی نماز ( میں ارکان کی طوالت ) قریب قریب تھی اور ابو بکر رضی اللہ عنہ کی نماز بھی قریب قریب ہوتی تھی ۔ جب عمر رضی اللہ عنہ ( امیر مقرر ) ہوئے تو انہوں نے نماز فجر ( میں قراءت ) لمبی کر دی ۔ اور رسول اللہ صلی اللہ علیہ وسلم جب سمع اللہ لمن حمده کہتے تو کھڑے رہتے حتیٰ کہ ہم کہتے : آپ ( شاید سر اٹھانا ) بھول گئے ہیں ، پھر سجدہ کرتے اور دو سجدوں کے درمیان بیٹھے رہتے حتیٰ کہ ہم سمجھتے ( کہ شاید ) آپ بھول گئے ہیں ۔","",{"u2":"۔ بہز بن حماد سے حدیث بیان کی، انہوں نے کہا: ہمیں ثابت نے سیدنا انس رضی اللہ عنہ سے خبر دی، انہوں نے کہا: میں نے کسی کے پیچھے نبی اکرم صلی اللہ علیہ وسلم سے زیادہ ہلکی نماز نہیں پڑھی جو کامل ہو۔ رسول اللہ صلی اللہ علیہ وسلم کی نماز (میں ارکان کی طوالت) قریب قریب تھی اور ابو بکر رضی اللہ عنہ کی نماز بھی قریب قریب ہوتی تھی۔ جب عمر رضی اللہ عنہ (امیر مقرر) ہوئے تو انہوں نے نماز فجر (میں قراءت) لمبی کر دی۔ اور رسول اللہ صلی اللہ علیہ وسلم جب سمع اللہ لمن حمدہ کہتے تو کھڑے رہتے حتیٰ کہ ہم کہتے: آپ (شاید سر اٹھانا) بھول گئے ہیں، پھر سجدہ کرتے اور دو سجدوں کے درمیان بیٹھے رہتے حتیٰ کہ ہم سمجھتے (کہ شاید) آپ بھول گئے ہیں۔"}],[994,"زہیر اور ابو خیثمہ نے اپنی اپنی سند کے ساتھ ابو اسحاق سے اور انہوں نے عبد اللہ بن یزید سے روایت کی ، انہوں نے کہا : مجھے سیدنا براء رضی اللہ عنہ نے حدیث بیان کی اور وہ جھوٹ نہیں بولتے تھے کہ وہ لوگ ( صحابہ کرام ) رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تھے ۔ جب آپ رکوع سے اپنا سر اٹھا لیتے تو میں کسی کو نہ دیکھتا کہ وہ اپنی پشت جھکاتا ہو یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم اپنی پیشانی زمین پر رکھ دیتے ، اس کے بعد آپ کے پیچھے والے سجدے میں گرتے ۔","",{"u2":"زہیر اور ابو خیثمہ نے اپنی اپنی سند کے ساتھ ابو اسحاق سے اور انہوں نے عبد اللہ بن یزید سے روایت کی، انہوں نے کہا: مجھے سیدنا براء رضی اللہ عنہ نے حدیث بیان کی اور وہ جھوٹ نہیں بولتے تھے کہ وہ لوگ (صحابہ کرام) رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تھے۔ جب آپ رکوع سے اپنا سر اٹھا لیتے تو میں کسی کو نہ دیکھتا کہ وہ اپنی پشت جھکاتا ہو یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم اپنی پیشانی زمین پر رکھ دیتے، اس کے بعد آپ کے پیچھے والے سجدے میں گرتے۔"}],[995,"سفیان نے ابو اسحاق سے ، انہوں نے عبد اللہ بن یزید سے اور انہوں نے سیدنا براء رضی اللہ عنہ سے حدیث بیان کی اور وہ جھوٹ بولنے والے نہ تھے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب سمع اللہ لمن حمدہ کہتے تو ہم میں سے کوئی ایک بھی اس وقت تک اپنی پشت نہ جھکاتا جب تک رسول اللہ صلی اللہ علیہ وسلم سجدے میں نہ چلے جاتے ، پھر ہم آپ کے بعد سجدے میں جاتے","",{"u2":"سفیان نے ابو اسحاق سے، انہوں نے عبد اللہ بن یزید سے اور انہوں نے سیدنا براء رضی اللہ عنہ سے حدیث بیان کی اور وہ جھوٹ بولنے والے نہ تھے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب سمع اللہ لمن حمدہ کہتے تو ہم میں سے کوئی ایک بھی اس وقت تک اپنی پشت نہ جھکاتا جب تک رسول اللہ صلی اللہ علیہ وسلم سجدے میں نہ چلے جاتے، پھر ہم آپ کے بعد سجدے میں جاتے"}],[996,"محارب بن دثار نے کہا کہ میں نے عبد اللہ بن یزید کو منبر پر بیان کرتے ہوئے سنا ، وہ کہہ رہے تھے : براء رضی اللہ عنہ نے ہمیں بتایا کہ وہ لوگ ( صحابہ کرام ) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے ، جب آپ رکوع میں چلے جاتے تو وہ رکوع کرتے اور جب آپ اپنا سر رکوع سے اٹھاتے تو آپ سمع اللہ لمن حمده کہتے ، ہم کھڑے رہتے یہاں تک کہ ہم آپ کو دیکھتے کہ آپ نے اپنا چہرہ مبارک زمین پر رکھ دیا ہے ، پھر ہم آپ کی پیروی کرتے ( سجدے میں جاتے ۔)","",{"u2":"محارب بن دثار نے کہا کہ میں نے عبد اللہ بن یزید کو منبر پر بیان کرتے ہوئے سنا، وہ کہہ رہے تھے: براء رضی اللہ عنہ نے ہمیں بتایا کہ وہ لوگ (صحابہ کرام) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے، جب آپ رکوع میں چلے جاتے تو وہ رکوع کرتے اور جب آپ اپنا سر رکوع سے اٹھاتے تو آپ سمع اللہ لمن حمدہ کہتے، ہم کھڑے رہتے یہاں تک کہ ہم آپ کو دیکھتے کہ آپ نے اپنا چہرہ مبارک زمین پر رکھ دیا ہے، پھر ہم آپ کی پیروی کرتے (سجدے میں جاتے۔)"}],[997,"۔ زہیر بن حرب اور ابن نمیر نے کہا : ہم سے سفیان بن عیینہ نے حدیث بیان کی ، کہا : ہمیں ابان وغیرہ نے حکم سے حدیث سنائی ، انہوں نے عبد الرحمن بن ابی لیلیٰ سے اور انہوں نے سیدنا براء رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ہم ( نماز میں ) نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ہوتے ، ہم میں سے کوئی ایک بھی اپنی پشت نہ جھکاتا یہاں تک کہ ہم آپ کو دیکھ لیتے کہ آپ سجدے میں جا چکے ہیں ۔","",{"u2":"۔ زہیر بن حرب اور ابن نمیر نے کہا: ہم سے سفیان بن عیینہ نے حدیث بیان کی، کہا: ہمیں ابان وغیرہ نے حکم سے حدیث سنائی، انہوں نے عبد الرحمن بن ابی لیلیٰ سے اور انہوں نے سیدنا براء رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ہم (نماز میں) نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ہوتے، ہم میں سے کوئی ایک بھی اپنی پشت نہ جھکاتا یہاں تک کہ ہم آپ کو دیکھ لیتے کہ آپ سجدے میں جا چکے ہیں۔"}],[998,"سیدنا عمرو بن حریث رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : میں نے نبی اکرم صلی اللہ علیہ وسلم کے پیچھے فجر کی نماز پڑھی تو میں نے آپ کو ﴿فلا أقسم بالخنس0 الجوار الكنس﴾ ’’میں قسم کھاتا ہوں پیچھے ہٹنے والے ، سیدھے چلنے ، دبک جانے والے ( ستاروں ) کی ‘‘ پڑھتے ہوئے سنا اور ہم میں سے کوئی آدمی اپنی پشت نہیں جھکاتا تھا حتیٰ کہ آپ پوری طرح سجدے میں چلے جاتے تھے ۔","",{"u2":"سیدنا عمرو بن حریث رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم کے پیچھے فجر کی نماز پڑھی تو میں نے آپ کو ﴿فلا أقسم بالخنس0 الجوار الکنس﴾ ’’میں قسم کھاتا ہوں پیچھے ہٹنے والے، سیدھے چلنے، دبک جانے والے (ستاروں) کی‘‘ پڑھتے ہوئے سنا اور ہم میں سے کوئی آدمی اپنی پشت نہیں جھکاتا تھا حتیٰ کہ آپ پوری طرح سجدے میں چلے جاتے تھے۔"}],[999,"اعمش نے عبید بن حسن سے اور انہوں نے سیدنا ابن ابی اوفیٰ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب رکوع سے اپنی پشت اٹھاتے تو کہتے ، ’’ اللہ نے سن لی جس نے اس کی حمد کی ، اے اللہ ہمارے رب! تیرے ہی لیے تعریف وتوصیف ہے آسمان بھر ، زمین بھر اور ان کے سوا جو تو چاہے اس کی وسعت بھر ۔ ‘‘","",{"u2":"اعمش نے عبید بن حسن سے اور انہوں نے حضرت ابن ابی اوفیٰ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب رکوع سے اپنی پشت اٹھاتے تو کہتے، ’’ اللہ نے سن لی جس نے اس کی حمد کی، اے اللہ ہمارے رب! تیرے ہی لیے تعریف وتوصیف ہے آسمان بھر، زمین بھر اور ان کے سوا جو تو چاہے اس کی وسعت بھر۔‘‘"}],[1000,"شعبہ نے عبیدبن حسن سے انہوں نے عبد اللہ بن اوفیٰ سے روایت ےکی ہے انہوں نے کہا رسول اللہ صلی اللہ علیہ وسلم یہ دعا مانگا کیا کرتے تھے’’اے اللہ ہمارے رب تیر ی ہی تعریف ہے آسمان اور زمین تک اور اس علاوہ جہاں تک تو چاہے اس چیز کی وسعت تک ۔","",{"u2":"شعبہ نے عبیدبن حسن سے انہوں نے عبد اللہ بن اوفیٰ سے روایت ےکی ہے انہوں نے کہا رسو ل اللہ صلی اللہ علیہ وسلم یہ دعا مانگا کیا کرتے تھے’’اے اللہ ہمارے رب تیر ی ہی تعریف ہےآسمان اور زمین تک اور اس علاوہ جہاں تک تو چاہے اس چیز کی وسعت تک۔"}],[1001,"محمد بن جعفر نے شعبہ سے ، انہوں نے مجزاہ بن زاہر سے روایت کی ، کہا : میں نے سیدنا عبد اللہ بن ابی اوفیٰ رضی اللہ عنہ سے سنا ، وہ نبی اکرم صلی اللہ علیہ وسلم سے بیان کر رہے تھے کہ آپ فرمایا کرتے تھے : ’’اے اللہ! تیرے لیے ہے حمد آسمان بھر ، زمین بھر اور ان کے سوا جو چیز تو چاہے اس کی وسعت بھر ۔ اے اللہ! مجھے پاک کر دے برف کے ساتھ ، اولوں کے ساتھ اور ٹھنڈے پانی کے ساتھ ۔ اے اللہ! مجھے گناہوں اور خطاؤں سے اس طرح صاف کر دے جس طرح سفید کپڑا میل کچیل سے صاف کیا جاتا ہے ۔ ‘‘","",{"u2":"محمد بن جعفر نے شعبہ سے، انہوں نے مجزاہ بن زاہر سے روایت کی، کہا: میں نے سیدنا عبد اللہ بن ابی اوفیٰ رضی اللہ عنہ سے سنا، وہ نبی اکرم صلی اللہ علیہ وسلم سے بیان کر رہے تھے کہ آپ فرمایا کرتے تھے: ’’اے اللہ! تیرے لیے ہے حمد آسمان بھر، زمین بھر اور ان کے سوا جو چیز تو چاہے اس کی وسعت بھر۔ اے اللہ! مجھے پاک کر دے برف کے ساتھ، اولوں کے ساتھ اور ٹھنڈے پانی کے ساتھ۔ اے اللہ! مجھے گناہوں اور خطاؤں سے اس طرح صاف کر دے جس طرح سفید کپڑا میل کچیل سے صاف کیا جاتا ہے۔‘‘"}],[1002,"عبید اللہ کے والد معاذ عنبری اور یزید بن ہارون دونوں نے شعبہ سے اسی سند کے ساتھ مذکورہ بالا روایت بیان کی ۔ معاذ کی روایت میں ( من الوسخ کے بجائے ) من الدرن اور یزید کی روایت میں من الدنس کے الفاظ ہیں ( تینوں لفظوں کے معنیٰ ایک ہی ہیں ۔)","",{"u2":"عبید اللہ کے والد معاذ عنبری اور یزید بن ہارون دونوں نے شعبہ سے اسی سند کے ساتھ مذکورہ بالا روایت بیان کی۔ معاذ کی روایت میں (من الوسخ کے بجائے) من الدرن اور یزید کی روایت میں من الدنس کے الفاظ ہیں (تینوں لفظوں کے معنیٰ ایک ہی ہیں۔)"}],[1003,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم جب رکوع سے اپنا سر اٹھاتے تو فرماتے : ’’اے ہمارے رب! تیرے ہی لیے تعریف ہے آسمان بھر ، زمین بھر اور ان کے سوا جو چیز تو چاہے اس کی وسعت بھر ۔ ثنا اورعظمت کے حق دار! ( یہی ) صحیح ترین بات ہے جو بندہ کہہ سکتا ہے اور ہم سب تیری ہی بندے ہیں ۔ اے اللہ! جو کچھ تو عنایت فرمانا چاہے ، اسے کوئی روک نہیں سکتا اور جس سےتو محروم کر دے ، وہ کوئی دے نہیں سکتا اور نہ ہی کسی مرتبہ والے کو تیرے سامنے اس کا مرتبہ نفع دے سکتا ہے ۔ ‘‘"],[1004,"۔ ہشیم نے بشیر نے بیان کیا : ہمیں ہشام بن حسان نے قیس بن سعد سے خبر دی ، انہوں نے عطاء سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جب رکوع سے سر اٹھاتے تو فرماتے : ’’اے اللہ ، اے ہمارے رب! تیرے ہی لیے تمام تعریف ہے آسمان اور زمین بھر اور ان دونوں کے درمیان کی وسعت بھر اور ان کی بعد جو تو چاہے اس کی وسعت بھر ۔ اے تعریف اور بزرگی کے سزاوار! جو تو عنایت فرمائے اسے کوئی چھین نہیں سکتا اور جس سے تو محروم کر دے وہ کوئی دے نہیں سکتا اور نہ کسی مرتبے والے کو تیرے سامنے اس کا مرتبہ نفع دے سکتا ہے ۔ ‘‘","",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم جب رکوع سے اپنا سر اٹھاتے تو فرماتے: ’’اے ہمارے رب! تیرے ہی لیے تعریف ہے آسمان بھر، زمین بھر اور ان کے سوا جو چیز تو چاہے اس کی وسعت بھر۔ ثنا اورعظمت کے حق دار! (یہی) صحیح ترین بات ہے جو بندہ کہہ سکتا ہے اور ہم سب تیری ہی بندے ہیں۔ اے اللہ! جو کچھ تو عنایت فرمانا چاہے، اسے کوئی روک نہیں سکتا اور جس سےتو محروم کر دے، وہ کوئی دے نہیں سکتا اور نہ ہی کسی مرتبہ والے کو تیرے سامنے اس کا مرتبہ نفع دے سکتا ہے۔‘‘\n۔ ہشیم نے بشیر نے بیان کیا: ہمیں ہشام بن حسان نے قیس بن سعد سے خبر دی، انہوں نے عطاء سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم جب رکوع سے سر اٹھاتے تو فرماتے: ’’اے اللہ، اے ہمارے رب! تیرے ہی لیے تمام تعریف ہے آسمان اور زمین بھر اور ان دونوں کے درمیان کی وسعت بھر اور ان کی بعد جو تو چاہے اس کی وسعت بھر۔ اے تعریف اور بزرگی کے سزاوار! جو توعنایت فرمائے اسے کوئی چھین نہیں سکتا اور جس سے تو محروم کر دے وہ کوئی دے نہیں سکتا اور نہ کسی مرتبے والے کو تیرے سامنے اس کا مرتبہ نفع دے سکتا ہے۔‘‘"}],[1005,"حفص نے حدیث بیان کی ، کہا : ہمیں ہشام بن حسان نے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابن عباس رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے ان الفاظ تک روایت کی : ’’اور ان کے بعد جو تو چاہے اس کی وعست بھر ۔ ‘ انہوں ( حفص ) نے آگے کا حصہ بیان نہیں کیا ۔","",{"u2":"حفص نے حدیث بیان کی، کہا: ہمیں ہشام بن حسان نے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابن عباس رضی اللہ عنہ سے حدیث بیان کی، انہوں نے نبی صلی اللہ علیہ وسلم سے ان الفاظ تک روایت کی: ’’اور ان کے بعد جو تو چاہے اس کی وعست بھر۔‘ انہوں (حفص) نے آگے کا حصہ بیان نہیں کیا۔"}],[1006,"سعید بن منصور ، ابو بکر بن ابی شیبہ اور زہیر بن حرب نے کہا : ہمیں سفیان بن عیینہ نے حدیث بیان کی کہ مجھے سلیمان بن سحیم نے خبر دی ، انہوں نے ابراہیم بن عبد اللہ بن معبد سے ، انہوں نے اپنے والد سے اور انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ( دروازے کا ) پردہ اٹھایا ( اس وقت ) لوگ ابو بکر رضی اللہ عنہ کے پیچھے صف بستہ تھے ۔ آپ نے فرمایا : ’’لوگو! نبوت کی بشارتوں میں سے اب صرف سچے خواب باقی رہ گئے ہیں جو مسلمان خود دیکھے گا یا اس کے لیے کسی دوسرے کو ) دکھایا جائے گا ۔ خبردار رہو! بلاشبہ مجھے رکوع اور سجدے کی حالت میں قرآن پڑھنے سے منع کیا گیا ہے ، جہاں تک رکوع کا تعلق ہے اس میں اپنے رب عزوجل کی عظمت وکبریائی بیان کرو اور جہاں تک سجدے کا تعلق ہے اس میں خوب دعا کرو ، ( یہ دع اس ) لائق ہے کہ تمہارے حق میں قبول کر لی جائے ۔ ‘‘ امام مسلم کے اساتذہ میں سے ایک استاد ابو بکر بن ابی شیبہ نے حدیث یبان کرتے ہوئے ( ’’مجھے سلیمان نے خبر دی ‘‘ کے بجائے ) سلیمان سے روایت ہے ، کہا ۔ ‘‘","",{"u2":"سعید بن منصور، ابو بکر بن ابی شیبہ اور زہیر بن حرب نے کہا: ہمیں سفیان بن عیینہ نے حدیث بیان کی کہ مجھے سلیمان بن سحیم نے خبر دی، انہوں نے ابراہیم بن عبد اللہ بن معبد سے، انہوں نے اپنے والد سے اور انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے (دروازے کا) پردہ اٹھایا (اس وقت) لوگ ابو بکر رضی اللہ عنہ کے پیچھے صف بستہ تھے۔ آپ نے فرمایا: ’’لوگو! نبوت کی بشارتوں میں سے اب صرف سچے خواب باقی رہ گئے ہیں جو مسلمان خود دیکھے گا یا اس کے لیے کسی دوسرے کو) دکھایا جائے گا۔ خبردار رہو! بلاشبہ مجھے رکوع اور سجدے کی حالت میں قرآن پڑھنے سے منع کیا گیا ہے، جہاں تک رکوع کا تعلق ہے اس میں اپنے رب عزوجل کی عظمت وکبریائی بیان کرو اور جہاں تک سجدے کا تعلق ہے اس میں خوب دعا کرو، (یہ دع اس) لائق ہے کہ تمہارے حق میں قبول کر لی جائے۔‘‘\nامام مسلم کے اساتذہ میں سے ایک استاد ابو بکر بن ابی شیبہ نے حدیث یبان کرتے ہوئے (’’مجھے سلیمان نے خبر دی‘‘ کے بجائے) سلیمان سے روایت ہے، کہا۔‘‘"}],[1007,"۔ اسماعیل بن جعفر نے سلیمان سے باقی ماندہ سابقہ سند سے سیدنا عبد اللہ بن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے پردہ اٹھایا ، اس مرض کے عالم میں جس میں آپ کا انتقال ہوا ، آپ کا سر پٹی سے بندھا ہوا تھا ، آپ نے فرمایا : ’’اے اللہ! کیا میں نے پیغام پہنچا دیا؟ ‘‘ تین بار ( یہ الفاظ کہے ، پھر فرمایا : ) ’’نبوت کی بشارتوں میں سے اب صرف سچے خواب باقی رہ گئے ہیں جو کوئی نیک انسان خود دیکھے گا یا اس کے لیے ( دوسرے کو ) دکھائے جائیں گے ... ‘‘ اس کے بعد اسماعیل نے سفیان کی حدیث کی طرح بیان کیا ۔","",{"u2":"۔ اسماعیل بن جعفر نے سلیمان سے باقی ماندہ سابقہ سند سے سیدنا عبد اللہ بن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے پردہ اٹھایا، اس مرض کے عالم میں جس میں آپ کا انتقال ہوا، آپ کا سر پٹی سے بندھا ہوا تھا، آپ نے فرمایا: ’’اے اللہ! کیا میں نے پیغام پہنچا دیا؟‘‘ تین بار (یہ الفاظ کہے، پھر فرمایا:) ’’نبوت کی بشارتوں میں سے اب صرف سچے خواب باقی رہ گئے ہیں جو کوئی نیک انسان خود دیکھے گا یا اس کے لیے (دوسرے کو) دکھائے جائیں گے ...‘‘ اس کے بعد اسماعیل نے سفیان کی حدیث کی طرح بیان کیا۔"}],[1008,"۔ ابن شہاب زہری نے کہا : مجھے ابراہیم بن عبد اللہ بن حنین نے حدیث سنائی کہ ان کے والد نے ان سے بیان کیا ، انہوں نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے سنا ، انہوں نے کہا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع اور سجدے میں قرآن پڑھنے سے منع فرمایا ۔"],[1009,"ولید بن کثیر سے روایت ہے کہ مجھے ابراہیم بن عبد اللہ بن حنین نے اپنے والد سے بیان کیا ، انہوں نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے سنا ، کہہ رہے تھے : مجھے رسول اللہ صلی اللہ علیہ وسلم نے ، جب میں رکوع یا سجدے میں ہوں ، قرآن پڑھنے سے روکا ۔","",{"u2":"۔ ابن شہاب زہری نے کہا: مجھے ابراہیم بن عبد اللہ بن حنین نے حدیث سنائی کہ ان کے والد نے ان سے بیان کیا، انہوں نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے سنا، انہوں نے کہا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع اور سجدے میں قرآن پڑھنے سے منع فرمایا۔\nولید بن کثیر سے روایت ہے کہ مجھے ابراہیم بن عبد اللہ بن حنین نے اپنے والد سے بیان کیا، انہوں نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے سنا، کہہ رہے تھے: مجھے رسول اللہ صلی اللہ علیہ وسلم نے، جب میں رکوع یا سجدے میں ہوں، قرآن پڑھنے سے روکا۔"}],[1010,"زید بن اسلم نے ابراہیم بن عبد اللہ بن حنین سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع اور سجدے میں ( قرآن کی ) قراءت کرنے سے منع کیا ۔ میں ( یہ ) نہیں کہتا : تمہیں منع کیا ۔ ( سیدنا علی نے اپنے حوالےا سے جو سنا وہی بتایا ۔ پچھلی احادیث سے واضح ہوتا ہے کہ حکم سب کے لیے ہے ۔)","",{"u2":"زید بن اسلم نے ابراہیم بن عبد اللہ بن حنین سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت کی، انہوں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع اور سجدے میں (قرآن کی) قراءت کرنے سے منع کیا۔ میں (یہ) نہیں کہتا: تمہیں منع کیا۔ (حضرت علی نے اپنے حوالےا سے جو سنا وہی بتایا۔ پچھلی احادیث سے واضح ہوتا ہے کہ حکم سب کے لیے ہے۔)"}],[1011,"داؤد بن قیس نے کہا : مجھے ابراہیم بن عبد اللہ بن حنین نے اپنے والد ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کی ، انہوں نے کہا کہ میرے حبیب صلی اللہ علیہ وسلم نے مجھے اس بات سے منع فرمایا تھا کہ میں رکوع یا سجدے میں قرآن پڑھوں ۔","",{"u2":"داؤد بن قیس نے کہا: مجھے ابراہیم بن عبد اللہ بن حنین نے اپنے والد، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کی، انہوں نے کہا کہ میرے حبیب صلی اللہ علیہ وسلم نے مجھے اس بات سے منع فرمایا تھا کہ میں رکوع یا سجدے میں قرآن پڑھوں۔"}],[1012,"نافع ، یزید بن ابی حبیب ، ضحاک بن عثمان ، ابن عجلان ، اسامہ بن زید ، محمد بن عمرو اور محمد بن اسحاق سب نے مختلف سندوں سے ابراہیم بن عبد اللہ حنین سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا علی رضی اللہ عنہ روایت کی ، البتہ ان میں ضحاک اور ابن عجلان نے اضافہ کرتے ہوئے کہا : سیدنا ابن عباس سے روایت ہے ، انہوں نے سیدنا علی سے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے مجھے رکوع کی حالت میں قرآن کی قراءت سے روکا اور ان میں سے کسی نے اپنی روایت میں ( ابراہیم کے پچھلی روایتوں : 1076 ۔ 1079 میں مذکورہ شاگردوں ) زہری ، زید بن اسلم ، ولید بن کثیر اور داؤد بن قیس کی روایات کی طرح سجدے میں قراءت کرنے سے روکنے کا ذکر نہیں کیا","",{"u2":"نافع، یزید بن ابی حبیب، ضحاک بن عثمان، ابن عجلان، اسامہ بن زید، محمد بن عمرو اور محمد بن اسحاق سب نے مختلف سندوں سے ابراہیم بن عبد اللہ حنین سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا علی رضی اللہ عنہ روایت کی، البتہ ان میں ضحاک اور ابن عجلان نے اضافہ کرتے ہوئے کہا: حضرت ابن عباس سے روایت ہے، انہوں نے حضرت علی سے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے مجھے رکوع کی حالت میں قرآن کی قراءت سے روکا اور ان میں سے کسی نے اپنی روایت میں (ابراہیم کے پچھلی روایتوں: 1076۔1079 میں مذکورہ شاگردوں) زہری، زید بن اسلم، ولید بن کثیر اور داؤد بن قیس کی روایات کی طرح سجدے میں قراءت کرنے سے روکنے کا ذکر نہیں کیا"}],[1013,"۔ عبد اللہ بن حنین کے ایک اور شاگرد محمد بن مکندر نے یہی حدیث سیدنا علی رضی اللہ عنہ سے روایت کی لیکن سجدے میں قراءت کا ذکر نہیں کیا ۔","",{"u2":"۔ عبد اللہ بن حنین کے ایک اور شاگرد محمد بن مکندر نے یہی حدیث سیدنا علی رضی اللہ عنہ سے روایت کی لیکن سجدے میں قراءت کا ذکر نہیں کیا۔"}],[1014,"عبد اللہ بن حنین نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا : مجھے رکوع کی حالت میں قراءت سے منع کیا گیا ہے ۔ اس سند میں سیدنا علی رضی اللہ عنہ کا ذکر نہیں کیا ۔","",{"u2":"عبد اللہ بن حنین نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: مجھے رکوع کی حالت میں قراءت سے منع کیا گیا ہے۔ اس سند میں سیدنا علی رضی اللہ عنہ کا ذکر نہیں کیا۔"}],[1015,"۔ ذکوان نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’بندہ اپنے رب کے سب سے زیادہ قریب اس حالت میں ہوتا ہے جب وہ سجدے میں ہوتا ہے ، لہٰذا اس میں کثرت سے دعا کرو ۔ ‘‘","",{"u2":"۔ ذکوان نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بندہ اپنے رب کے سب سے زیادہ قریب اس حالت میں ہوتا ہے جب وہ سجدے میں ہوتا ہے، لہٰذا اس میں کثرت سے دعا کرو۔‘‘"}],[1016,"ابو صالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سجدے میں کہا کرتے تھے : ’’ اللہ! میرے سارے گناہ بخش دے ، چھوٹے بھی اور بڑے بھی ، پہلے بھی اور پچھلے بھی ، کھلے بھی اور چھپے بھی ۔ ‘‘","",{"u2":"ابو صالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سجدے میں کہا کرتے تھے: ’’ اللہ! میرے سارے گناہ بخش دے، چھوٹے بھی اور بڑے بھی، پہلے بھی اور پچھلے بھی، کھلے بھی اور چھپے بھی۔‘‘"}],[1017,"منصور نے ابو ضحیٰ ( مسلم بن صبیح القرشی ) سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : : رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں بکثرت ( یہ کلمات ) کہا کرتے تھے : ’’تیری پاکیزگی بیان کرتا ہوں اے میرے اللہ! ہمارے رب! تیری حمد کے ساتھ ، اے میرے اللہ! مجھے بخش دے ۔ ‘‘ آپ ( یہ کلمات ) قرآن مجید کی تاویل ( حکم کی تعمیل ) کے طور پر فرمایا کرتے تھے ۔","",{"u2":"منصور نے ابو ضحیٰ (مسلم بن صبیح القرشی) سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا:: رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں بکثرت (یہ کلمات) کہا کرتے تھے: ’’تیری پاکیزگی بیان کرتا ہوں اے میرے اللہ! ہمارے رب! تیری حمد کے ساتھ، اے میرے اللہ! مجھے بخش دے۔‘‘ آپ (یہ کلمات) قرآن مجید کی تاویل (حکم کی تعمیل) کے طور پر فرمایا کرتے تھے۔"}],[1018,"ابو معاویہ نے اعمش سے ، انہوں نے مسلم ( بن صبیح سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول لالہ صلی اللہ علیہ وسلم وفات سے پہلے بکثرت یہ فرماتے تھے : ’’ ( اے اللہ! ) میں تیری حمد ے ساتھ تیری ستائش کرتاہوں ، تجھ سے بخشش طلب کرتا ہوں اور تیری طرف رجوع کرتا ہوں ۔ ‘‘ عائشہ رضی اللہ عنہا نے کہا : میں نے پوچھا : اے اللہ کے رسول! یہ کلمے کیا ہیں جو میں دیکھتی ہوں کہ آپ نے اب کہنے شروع کر دیے ہیں؟ آپ نے فرمایا : ’’میرے لیے میری امت میں ایک علامت مقرر کر دی گئی ہے کہ جب میں اسے دیکھ لوں تو یہ ( کلمے ) کہوں : ’’جب اللہ کی نصرت اور فتح آ پہنچے .... ) ‘‘ سورت کے آخر تک","",{"u2":"ابو معاویہ نے اعمش سے، انہوں نے مسلم (بن صبیح سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول لالہ صلی اللہ علیہ وسلم وفات سے پہلے بکثرت یہ فرماتے تھے: ’’ (اے اللہ!) میں تیری حمد ے ساتھ تیری ستائش کرتاہوں، تجھ سے بخشش طلب کرتا ہوں اور تیری طرف رجوع کرتا ہوں۔‘‘ عائشہ رضی اللہ عنہا نے کہا: میں نے پوچھا: اے اللہ کے رسول! یہ کلمے کیا ہیں جو میں دیکھتی ہوں کہ آپ نے اب کہنے شروع کر دیے ہیں؟ آپ نے فرمایا: ’’میرے لیے میری امت میں ایک علامت مقرر کر دی گئی ہے کہ جب میں اسے دیکھ لوں تو یہ (کلمے) کہوں: ’’جب اللہ کی نصرت اور فتح آ پہنچے ....)‘‘ سورت کے آخر تک"}],[1019,"مفضل نے اعمش سے باقی ماندہ سابقہ سند کےساتھ سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : جب سے آپ پر ﴿إذا جاء نصر الله والفتح﴾ اتری ، اس وقت سے میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے جو بھی نماز پڑھی اس میں یہ دعا مانگی یا یہ کہا : ’’اے میرے رب! میں تیری پاکیزگی بیان کرتا ہوں تیری حمد کے ساتھ ، اے میرے اللہ! مجھے بخش دے ۔ ‘‘","",{"u2":"مفضل نے اعمش سے باقی ماندہ سابقہ سند کےساتھ سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: جب سے آپ پر ﴿إذا جاء نصر اللہ والفتح﴾ اتری، اس وقت سے میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے جو بھی نماز پڑھی اس میں یہ دعا مانگی یا یہ کہا: ’’اے میرے رب! میں تیری پاکیزگی بیان کرتا ہوں تیری حمد کے ساتھ، اے میرے اللہ! مجھے بخش دے۔‘‘"}],[1020,"عامر ( شعبی ) نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کثرت سے یہ فرمایا کرتے تھے : ’’میں اللہ کی پاکیزگی بیان کرتا ہوں اس کی حمد کے ساتھ ، میں اللہ سے بخشش کا طلب گار ہوں اور اسی کی طرف رجوع کرتا ہوں ۔ ‘‘ سیدہ عائشہ رضی اللہ نے کہا : میں نے پوچھا : اے اللہ کے رسول! میں آپ کو دیکھتی ہوں کہ آپ بکثرت کہتے ہیں : سبحان اللہ وبحمده ، أستغفر اللہ وأتوب إليه عائشہ رضی اللہ عنہا نے کہا تو آپ نے فرمایا : ’’میرے رب نے مجھے خبر دی ہے کہ میں جلدی ہی اپنی امت میں ایک نشانی دیکھوں گا اور جب میں اس کو دیکھ لوں توبکثرت کہوں : سبحان اللہ وبحمده ، أستغفر اللہ وأتوب إليه تو ( وہ نشانی ) میں دیکھ چکا ہوں ۔ ’’جب اللہ کی نصرت اور فتح آ پہنچے ‘‘ ( یعنی ) فتح مکہ ’’ اور آپ لوگوں کو اللہ کے دین میں جوق در جوق داخل ہوتے دیکھ لیں تو اپنے پروردگار کی حمد کے ساتھ اس کی پاکیزگی بیان کریں اور اس سے بخشش طلب کریں بلاشبہ وہ توبہ قبول فرمانے والا ہے ۔ ‘‘","",{"u2":"عامر (شعبی) نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کثرت سے یہ فرمایا کرتے تھے: ’’میں اللہ کی پاکیزگی بیان کرتا ہوں اس کی حمد کے ساتھ، میں اللہ سے بخشش کا طلب گار ہوں اور اسی کی طرف رجوع کرتا ہوں۔‘‘ حضرت عائشہ رضی اللہ نے کہا: میں نے پوچھا: اے اللہ کے رسول! میں آپ کو دیکھتی ہوں کہ آپ بکثرت کہتے ہیں: سبحان اللہ وبحمدہ، أستغفر اللہ وأتوب إلیہ عائشہ رضی اللہ عنہا نے کہا تو آپ نے فرمایا: ’’میرے رب نے مجھے خبر دی ہے کہ میں جلدی ہی اپنی امت میں ایک نشانی دیکھوں گا اور جب میں اس کو دیکھ لوں توبکثرت کہوں: سبحان اللہ وبحمدہ، أستغفر اللہ وأتوب إلیہ تو (وہ نشانی) میں دیکھ چکا ہوں۔ ’’جب اللہ کی نصرت اور فتح آ پہنچے‘‘ (یعنی) فتح مکہ ’’ اور آپ لوگوں کو اللہ کے دین میں جوق در جوق داخل ہوتے دیکھ لیں تو اپنے پروردگار کی حمد کے ساتھ اس کی پاکیزگی بیان کریں اور اس سے بخشش طلب کریں بلاشبہ وہ توبہ قبول فرمانے والا ہے۔‘‘"}],[1021,"۔ ابن جریج نے کہا : میں نے عطاء سے پوچھا : آپ رکوع میں کہتے ہیں؟ انہوں نے کہا : جہاں تک ( دعا ) سبحانك وبحمدك ، لا إله إلا أنت ’’تو پاک ہے ( اے اللہ! ) اپنی حمد کے ساتھ ، کوئی معبود برحق نہیں تیرے سوا ‘‘ کا تعلق ہے تو مجھے ابن ملیکہ نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی ، انہوں نے کہا : ایک رات میں نے نبی صلی اللہ علیہ وسلم کو گم پایا تو میں نے یہ گمان کیا کہ آپ اپنی کسی ( اور ) بیوی کے پاس چلے گئے ہیں ، میں نے تلاش کیا ، پھر آپ رکوع یا سجدے میں تھے ، کہہ رہے تھے : سبحانك وبحمدك ، لا إله إلا أنت میں نے کہا : آپ پہ میرے ماں باپ قربان! میں ایک کیفیت میں تھی اور آپ ایک ہی کیفیت میں تھے ۔","",{"u2":"۔ ابن جریج نے کہا: میں نے عطاء سے پوچھا: آپ رکوع میں کہتے ہیں؟ انہوں نے کہا: جہاں تک (دعا) سبحانک وبحمدک، لا إلہ إلا أنت ’’تو پاک ہے (اے اللہ!) اپنی حمد کے ساتھ، کوئی معبود برحق نہیں تیرے سوا‘‘ کا تعلق ہے تو مجھے ابن ملیکہ نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی، انہوں نے کہا: ایک رات میں نے نبی صلی اللہ علیہ وسلم کو گم پایا تو میں نے یہ گمان کیا کہ آپ اپنی کسی (اور) بیوی کے پاس چلے گئے ہیں، میں نے تلاش کیا، پھر آپ رکوع یا سجدے میں تھے، کہہ رہے تھے: سبحانک وبحمدک، لا إلہ إلا أنت میں نے کہا: آپ پہ میرے ماں باپ قربان! میں ایک کیفیت میں تھی اور آپ ایک ہی کیفیت میں تھے۔"}],[1022,"سیدنا ابو ہریرہ رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کو بستر پر نہ پایا تو آپ کو ٹٹولنے لگی ، میرا ہاتھ آپ کے پاؤں کے تلوے پر پڑا ، اس وقت آپ سجدے میں تھے ، آپ کے دونوں پاؤں کھڑے تھے اور آپ کہہ رہے تھے : ’’اے اللہ! میں تیری ناراضی سے تیری رضا مندی کی پناہ میں آتا ہوں اور تیری سزا سے تیری معافی کی پناہ میں آتا ہوں اور تجھ سے تیری ہی پناہ میں آتا ہوں ، میں تیری ثنا پوری طرح بیان نہیں کر سکتا ، تو ویسا ہی ہے جیسے تو نے اپنی تعریف خود بیان کی ۔ ‘‘","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کو بستر پر نہ پایا تو آپ کو ٹٹولنے لگی، میرا ہاتھ آپ کے پاؤں کے تلوے پر پڑا، اس وقت آپ سجدے میں تھے، آپ کے دونوں پاؤں کھڑے تھے اور آپ کہہ رہے تھے: ’’اے اللہ! میں تیری ناراضی سے تیری رضا مندی کی پناہ میں آتا ہوں اور تیری سزا سے تیری معافی کی پناہ میں آتا ہوں اور تجھ سے تیری ہی پناہ میں آتا ہوں، میں تیری ثنا پوری طرح بیان نہیں کر سکتا، تو ویسا ہی ہے جیسے تو نے اپنی تعریف خود بیان کی۔‘‘"}],[1023,"سعید بن ابی عروبہ نے قتادہ سے اور انہوں نے مطرف بن عبد اللہ بن شخیر سے روایت کی کہ سیدہ عائشہ رضی اللہ عنہا نے انہیں خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں ( یہ کلمات ) کہتے تھے : ’’نہایت پاک ہے ، مقدس ہے فرشتوں اور روح ( جبریل علیہ السلام ) کا پروردگار ۔ ‘‘","",{"u2":"سعید بن ابی عروبہ نے قتادہ سے اور انہوں نے مطرف بن عبد اللہ بن شخیر سے روایت کی کہ سیدہ عائشہ رضی اللہ عنہا نے انہیں خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں (یہ کلمات) کہتے تھے: ’’نہایت پاک ہے، مقدس ہے فرشتوں اور روح (جبریل علیہ السلام) کا پروردگار۔‘‘"}],[1024,"ہمیں ابوداؤد ( طیالسی ) نے شعبہ سے حدیث سنائی کہ قتادہ نے کہا : میں نے مطرف بن عبد اللہ بن شخیر سے سنا ۔ ابوداؤد نے ( مزید ) کہا : اور ہشام نے مجھے حدیث سنائی انہوں نے قتادہ سے ، انہوں نے مطرف سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے یہ حدیث روایت کی ۔","",{"u2":"ہمیں ابوداؤد (طیالسی) نے شعبہ سے حدیث سنائی کہ قتادہ نے کہا: میں نے مطرف بن عبد اللہ بن شخیر سے سنا۔ ابوداؤد نے (مزید) کہا: اور ہشام نے مجھے حدیث سنائی انہوں نے قتادہ سے، انہوں نے مطرف سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے یہ حدیث روایت کی۔"}],[1025,"۔ معدان بن ابی طلحہ یعمری نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ثوبان رضی اللہ عنہ سے ملا تو میں نے کہا : مجھے کوئی ایسا عمل بتائیے جسے کروں تو اللہ اس کی وجہ سے مجھے جنت میں داخل فرما دے ، یا انہوں نے کہا : میں نے پوچھا : جو عمل اللہ کو سب سے زیادہ محبوب ہو ، تو ثوبان رضی اللہ عنہ نے خاموشی اختیار فرمائی ( اور میری بات کا کوئی جواب نہ دیا ) پھر میں نے دوبارہ ان سے سوال کیا ، انہوں نے خاموشی اختیار کر لی ، پھر میں نے ان سے تیسری دفعہ یہی سوال کیا تو انہوں نے کہا : میں نے یہی سوال رسول اللہ صلی اللہ علیہ وسلم سے کیا تھا تو آپ نے فرمایا تھا : ’’تم اللہ کے حضور کثرت سے سجدے کیا کرو کیونکہ تم اللہ کے لیے جو بھی سجدہ کرو گے اللہ اس کے نتیجے میں تمہارا درجہ ضرور بلند کرے گا اور تمہارا کوئی گناہ معاف کر دے گا ۔ ‘‘ معدان نے کہا : پھر میں ابو درداء رضی اللہ عنہ سے ملا تو ان سے ( یہی ) سوال کیا ، انہوں نے بھی مجھ س وہی کہا جو ثوبان رضی اللہ عنہ نے کہا تھا ۔","",{"u2":"۔ معدان بن ابی طلحہ یعمری نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام ثوبان رضی اللہ عنہ سے ملا تو میں نے کہا: مجھے کوئی ایسا عمل بتائیے جسے کروں تو اللہ اس کی وجہ سے مجھے جنت میں داخل فرما دے، یا انہوں نے کہا: میں نے پوچھا: جو عمل اللہ کو سب سے زیادہ محبوب ہو، تو ثوبان رضی اللہ عنہ نے خاموشی اختیار فرمائی (اور میری بات کا کوئی جواب نہ دیا) پھر میں نے دوبارہ ان سے سوال کیا، انہوں نے خاموشی اختیار کر لی، پھر میں نے ان سے تیسری دفعہ یہی سوال کیا تو انہوں نے کہا: میں نے یہی سوال رسول اللہ صلی اللہ علیہ وسلم سے کیا تھا تو آپ نے فرمایا تھا: ’’تم اللہ کے حضور کثرت سے سجدے کیا کرو کیونکہ تم اللہ کے لیے جو بھی سجدہ کرو گے اللہ اس کے نتیجے میں تمہارا درجہ ضرور بلند کرے گا اور تمہارا کوئی گناہ معاف کر دے گا۔‘‘\nمعدان نے کہا: پھر میں ابو درداء رضی اللہ عنہ سے ملا تو ان سے (یہی) سوال کیا، انہوں نے بھی مجھ س وہی کہا جو ثوبان رضی اللہ عنہ نے کہا تھا۔"}],[1026,"سیدہ ربیعہ بن کعب ( بن مالک ) اسلمی رضی اللہ عنہ نے کہا : میں ( خدمت کے لیے ) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ( صفہ میں آپ کے قریب ) رات گزارا کرتا تھا ، ( جب آپ تہجد کے لیے اٹھتے تو ) میں وضو کا پانی اور دوسری ضروریات لے کر آپ کی خدمت میں حاضر ہوتا ۔ ( ایک مرتبہ ) آپ نے مجھے فرمایا : ’’ ( کچھ ) مانگو ۔ ‘‘ تو میں نے عرض کی : میں آپ سے یہ چاہتا ہوں کہ جنت میں بھی آپ کی رفاقت نصیب ہو ۔ آپ نے فرمایا : ’’یا اس کے سوا کچھ اور؟ ‘‘ میں نے عرض کی : بس یہی ۔ تو آپ نے فرمایا : ’’تم اپنے معاملے میں سجدوں کی کثرت سے میری مدد کرو ۔ ‘‘","",{"u2":"حضرت ربیعہ بن کعب (بن مالک) اسلمی رضی اللہ عنہ نے کہا: میں (خدمت کے لیے) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (صفہ میں آپ کے قریب) رات گزارا کرتا تھا، (جب آپ تہجد کے لیے اٹھتے تو) میں وضو کا پانی اور دوسری ضروریات لے کر آپ کی خدمت میں حاضر ہوتا۔ (ایک مرتبہ) آپ نے مجھے فرمایا: ’’ (کچھ) مانگو۔‘‘ تو میں نے عرض کی: میں آپ سے یہ چاہتا ہوں کہ جنت میں بھی آپ کی رفاقت نصیب ہو۔ آپ نے فرمایا: ’’یا اس کے سوا کچھ اور؟‘‘ میں نے عرض کی: بس یہی۔ تو آپ نے فرمایا: ’’تم اپنے معاملے میں سجدوں کی کثرت سے میری مدد کرو۔‘‘"}],[1027,"یحییٰ اور ابو ربیع نے حدیث بیان کی ، یحییٰ نے کہا : حماد بن زید نے ’’ہمیں خبر دی ‘‘ اور ابو ربیع نے کہا : ’’ہمیں حدیث سنائی ‘‘ انہوں نے عمرو بن دینار سے ، انہوں نے طاؤس سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا گیا کہ آپ سات ہڈیوں ( والے اعضاء ) پر سجدہ کیا کریں ارو آپ کو بالوں اور کپڑوں کو اڑسنے سے منع کیا گیا ۔ یہ یحییٰ کی حدیث ہے اور ابو ربیع نے کہا : سات ہڈیوں ( والے اعضاء ) پر سجدہ کرنے کا حکم دیا گیا اور اپنے بالوں اور اپنے کپڑوں کو اڑسنے سے منع کیا گیا ( سات اعضاء سے ) دونوں ہتھیلیاں ، دونوں گھٹنے ، دونوں قدم اور پیشانی ( مراد ہیں ۔)","",{"u2":"یحییٰ اور ابو ربیع نے حدیث بیان کی، یحییٰ نے کہا: حماد بن زید نے ’’ہمیں خبر دی‘‘ اور ابو ربیع نے کہا: ’’ہمیں حدیث سنائی‘‘ انہوں نے عمرو بن دینار سے، انہوں نے طاؤس سے اور انہوں نے حضرت ابن عباس رضی اللہ عنہما سے روایت کی، انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا گیا کہ آپ سات ہڈیوں (والے اعضاء) پر سجدہ کیا کریں ارو آپ کو بالوں اور کپڑوں کو اڑسنے سے منع کیا گیا۔ یہ یحییٰ کی حدیث ہےاور ابو ربیع نے کہا: سات ہڈیوں (والے اعضاء) پر سجدہ کرنے کا حکم دیا گیا اور اپنے بالوں اور اپنے کپڑوں کو اڑسنے سے منع کیا گیا (سات اعضاء سے) دونوں ہتھیلیاں، دونوں گھٹنے، دونوں قدم اور پیشانی (مراد ہیں۔)"}],[1028,"شعبہ نے عمرو بن دینار سے ، انہوں نے طاؤس اور انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’مجھے حکم دیا گیا کہ میں سات ہڈیوں ( والے اعضاء ) پر سجدہ کروں اور یہ کہ میں ( نماز میں ) نہ کپڑا اڑسوں اور نہ بال ۔ ‘‘","",{"u2":"شعبہ نے عمرو بن دینار سے، انہوں نے طاؤس اور انہوں نے حضرت ابن عباس رضی اللہ عنہما سے روایت کی، انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے حکم دیا گیا کہ میں سات ہڈیوں (والے اعضاء) پر سجدہ کروں اور یہ کہ میں (نماز میں) نہ کپڑا اڑسوں اور نہ بال۔‘‘"}],[1029,"سفیان بن عیینہ نے ( عبد اللہ ) بن طاؤس سے اور انہوں نے اپنے والد کے حوالے سے سیدنا ابن عباس رضی اللہ عنہما سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا گیا کہ سات ( اعضاء ) پر سجدہ کریں اور بالوں کو اور کپڑوں کو اڑسنے سے روکا گیا ہے ۔","",{"u2":"سفیان بن عیینہ نے (عبد اللہ) بن طاؤس سے اور انہوں نے اپنے والد کے حوالے سے حضرت ابن عباس رضی اللہ عنہما سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا گیا کہ سات (اعضاء) پر سجدہ کریں اور بالوں کو اور کپڑوں کو اڑسنے سے روکا گیا ہے۔"}],[1030,"وہیب نے عبد اللہ بن طاؤس سے حدیث بیان کی ، انہوں نے ( اپنے والد ) طاؤس سے انہوں نے عبداللہ بن عباس رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’مجھے سات ہڈیوں : پیشانی ، اور ( ساتھ ہی ) آپ نے اپنے ہاتھ سے اپنی ناک کی طرف اشارہ کیا ، دونوں ہاتھوں ، دونوں ٹانگوں ( گھٹنوں ) اور دونوں پاؤں کے کناروں پر سجدہ کرنے کا حکم دیا گیا ہے اور یہ کہ ہم ( نماز پڑھتے ہوئے ) کپڑوں اور بالوں کو نہ اڑسیں ۔ ‘‘","",{"u2":"وہیب نے عبد اللہ بن طاؤس سے حدیث بیان کی، انہوں نے (اپنے والد) طاؤس سےý¡ ÇäÀæŸ äÿ ÍÖÑÊ ÇÈä Úباس رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے سات ہڈیوں: پیشانی، اور (ساتھ ہی) آپ نے اپنے ہاتھ سے اپنی ناک کی طرف اشارہ کیا، دونوں ہاتھوں، دونوں ٹانگوں (گھٹنوں) اور دونوں پاؤں کے کناروں پر سجدہ کرنے کا حکم دیا گیا ہے اور یہ کہ ہم (نماز پڑھتے ہوئے) کپڑوں اور بالوں کو نہ اڑسیں۔‘‘"}],[1031,"ابن جریح نے عبد اللہ بن طاؤس سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’مجھے حکم دیا گیا ہے کہ میں سات ( اعضاء ) پر سجدہ کروں ، بالوں اور کپڑوں کو اکٹھا نہ کروں ، ( سجدہ ) پیشانی اور ناک ، دونوں ہاتھوں ، دونوں گھٹنوں اور دونوں پاؤں پر ( کروں ۔ ) ‘‘","",{"u2":"ابن جریح نے عبد اللہ بن طاؤس سے، انہوں نے اپنے والد سے اور انہوں نے حضرت عبد اللہ بن عباس رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے حکم دیا گیا ہے کہ میں سات (اعضاء) پر سجدہ کروں، بالوں اور کپڑوں کو اکٹھا نہ کروں، (سجدہ) پیشانی اور ناک، دونوں ہاتھوں، دونوں گھٹنوں اور دونوں پاؤں پر (کروں۔)‘‘"}],[1033,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے عبد اللہ بن حارث ( بن نوفل رضی اللہ عنہ بن عبد المطلب ) کو نماز پڑھتے دیکھا ، ان کے سر پر پیچھے سے بالوں کو جوڑا بنا ہوا تھا ، عبد اللہ بن عباس رضی اللہ عنہ کھڑے ہو کر اس کو کھولنے لگے ، جب ابن حارث نے سلام پھیرا تو ابن عباس رضی اللہ عنہما کی طرف متوجہ ہوئے اور کہا : میرے سر کے ساتھ آپ کا کیا معاملہ ہے ( میرے بال کیوں کھولے؟ ) انہوں نے جواب دیا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : ’’اس طرح ( جوڑا باندھ کر ) نماز پڑھنے والے کی مثال اس انسان کی طرح ہے جو اس حال میں نماز پڑھتا ہے کہ اس کی مشکیں کسی ہوئی ہوں ۔ ‘‘","",{"u2":"حضرت عبد اللہ بن عباس رضی اللہ عنہما نے عبد اللہ بن حارث (بن نوفل رضی اللہ عنہما بن عبد المطلب) کو نماز پڑھتے دیکھا، ان کے سر پر پیچھے سے بالوں کو جوڑا بنا ہوا تھا، عبد اللہ بن عباس رضی اللہ عنہ کھڑے ہو کر اس کو کھولنے لگے، جب ابن حارث نے سلام پھیرا تو ابن عباس رضی اللہ عنہما کی طرف متوجہ ہوئے اور کہا: میرے سر کے ساتھ آپ کا کیا معاملہ ہے(میرے بال کیوں کھولے؟) انہوں نے جواب دیا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ’’اس طرح (جوڑا باندھ کر) نماز پڑھنے والے کی مثال اس انسان کی طرح ہے جو اس حال میں نماز پڑھتا ہے کہ اس کی مشکیں کسی ہوئی ہوں۔‘‘"}],[1034,"وکیع نے شعبہ سے ، انہوں نے قتادہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ سجدے میں اعتدال اختیار کرو اور کوئی شخص اس طرح اپنے بازور ( زمین پر ) نہ بچھائے جس طرح کتا بچھاتا ہے ۔ ‘‘","",{"u2":"وکیع نے شعبہ سے، انہوں نے قتادہ سے اور انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ سجدے میں اعتدال اختیار کرو اور کوئی شخص اس طرح اپنے بازور (زمین پر) نہ بچھائے جس طرح کتا بچھاتا ہے۔‘‘"}],[1035,"محمد بن جعفر اور خالد بن حارث نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ روایت کی ہے ۔ ابن جعفر کی روایت میں ہے : ’’کوئی شخص تکلف کر کے اپنے بازو اس طرح نہ بچھائے جس طرح کتا بچھاتا ہے ۔ ‘‘","",{"u2":"محمد بن جعفر اور خالد بن حارث نے کہا: ہمیں شعبہ نے اسی سند کے ساتھ روایت کی ہے۔ ابن جعفر کی روایت میں ہے: ’’کوئی شخص تکلف کر کے اپنے بازو اس طرح نہ بچھائے جس طرح کتا بچھاتا ہے۔‘‘"}],[1036,"سیدنا براء رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم سجدہ کرو تو اپنی ہتھیلیاں ( زمین پر ) رکھو اور اپنی کہنیاں اوپر اٹھاؤ"],[1037,"بکر بن مضر نے جعفر بن ربیعہ سے ، انہوں نے اعرج سے اور انہوں نے سیدنا عبد اللہ بن ملک سے ، جو ابن بحینہ رضی اللہ عنہ ہیں ، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز پڑھتے تو اپنے ہاتھوں کو اچھی طرح کھول دیتے ( اپنے پہلوؤں سے الگ کر لیتے تھے ) یہاں تک کہ آپ کی بغلوں کی سفیدی ظاہر ہو جاتی تھی ۔","",{"u2":"بکر بن مضر نے جعفر بن ربیعہ سے، انہوں نے اعرج سے اور انہوں نے حضرت عبد اللہ بن ملک سے، جو ابن بحینہ رضی اللہ عنہ ہیں، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز پڑھتے تو اپنے ہاتھوں کو اچھی طرح کھول دیتے (اپنے پہلوؤں سے الگ کر لیتے تھے) یہاں تک کہ آپ کی بغلوں کی سفیدی ظاہر ہو جاتی تھی۔"}],[1038,"عمرو بن حارث اور لیث بن سعد دونوں نے جعفر بن ربیعہ سے اسی سند کے ساتھ ( مذکورہ حدیث ) بیان کی ۔ عمرو بن حارث کی روایت میں ہے : رسول اللہ صلی اللہ علیہ وسلم جب سجدہ فرماتے تو سجدے میں اپنے بازو ( اس طرح ) پھیلا لیتے حتیٰ کہ آپ کی بغلوں کی سفیدی نظر آ جاتی ۔ اور لیث کی روایت میں ہے : رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے ہاتھ بغلوں سے جدا ر کھتے حتیٰ کہ میں آپ کی بغلوں کی سفیدی دیکھ لیتا ۔","",{"u2":"عمرو بن حارث اور لیث بن سعد دونوں نے جعفر بن ربیعہ سے اسی سند کے ساتھ (مذکورہ حدیث) بیان کی۔\nعمرو بن حارث کی روایت میں ہے: رسول اللہ صلی اللہ علیہ وسلم جب سجدہ فرماتے تو سجدے میں اپنے بازو (اس طرح) پھیلا لیتے حتیٰ کہ آپ کی بغلوں کی سفیدی نظر آ جاتی۔\nاور لیث کی روایت میں ہے: رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے ہاتھ بغلوں سے جدا ر کھتے حتیٰ کہ میں آپ کی بغلوں کی سفیدی دیکھ لیتا۔"}],[1039,"سفیان بن عیینہ نے عبید اللہ بن عبد اللہ بن اصم سے ، انہوں نے اپنے چچا یزید بن اصم سے ، انہوں نے سیدہ میمونہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم سجدہ کرتے تو بکری کا بچہ اگر آپ کے دونوں ہاتھوں کے درمیان سے گزرنا چاہتا تو گزر سکتا تھا ۔","",{"u2":"سفیان بن عیینہ نے عبید اللہ بن عبد اللہ بن اصم سے، انہوں نے اپنے چچا یزید بن اصم سے، انہوں نے سیدہ میمونہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم سجدہ کرتے توبکری کا بچہ اگر آپ کے دونوں ہاتھوں کے درمیان سے گزرنا چاہتا توگزر سکتا تھا۔"}],[1040,"مروان بن معاویہ فزاری نے ہمیں خبر دی ، کہا : عبید اللہ بن عبد اللہ بن اصم نے یزید بن اصم سے حدیث بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا نے انہیں خبر دی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے ہاتھوں کے درمیان فاصلہ کرتے ، ان کا مطلب تھا انہیں پھیلا لیتے یہاں تک کہ پیچھے سے آپ کی بغلوں کی سفیدی دیکھی جا سکتی تھی اور جب بیٹھتے تو بائیں ران پر اطیمنان سے بیٹھتے ۔","",{"u2":"مروان بن معاویہ فزاری نے ہمیں خبر دی، کہا: عبید اللہ بن عبد اللہ بن اصم نے یزید بن اصم سے حدیث بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا نے انہیں خبر دی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے ہاتھوں کے درمیان فاصلہ کرتے، ان کا مطلب تھا انہیں پھیلا لیتے یہاں تک کہ پیچھے سے آپ کی بغلوں کی سفیدی دیکھی جا سکتی تھی اور جب بیٹھتے تو بائیں ران پر اطیمنان سے بیٹھتے۔"}],[1041,"وکیع نے کہا : ہمیں جعفر بن برقان نے یزید بن اصم سے حدیث سنائی ، انہوں نے سیدہ میمونہ بنت حارث رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو ( دونوں ہاتھوں کو پہلوؤں سے ) دور رکھتے یہاں تک کہ جو آپ کے پیچھے ہوتا وہ آپ کی بغلوں کی سفیدی دیکھ سکتا تھا ۔ وکیع نے کہا : ( وضح سے ) مراد بغلوں کی سفیدی ہے ۔","",{"u2":"وکیع نے کہا: ہمیں جعفر بن برقان نے یزید بن اصم سے حدیث سنائی، انہوں نے سیدہ میمونہ بنت حارث رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو (دونوں ہاتھوں کو پہلوؤں سے) دور رکھتے یہاں تک کہ جو آپ کے پیچھے ہوتا وہ آپ کی بغلوں کی سفیدی دیکھ سکتا تھا۔\nوکیع نے کہا: (وضح سے) مراد بغلوں کی سفیدی ہے۔"}],[1042,"محمد بن عبد اللہ بن نمیر نے ہمیں حدیث بیان کی ، کہا : ہمیں ابو خالد احمر نے حسین معلم سے حدیث سنائی ، نیز اسحاق بن ابراہیم نے کہا : ( الفاظ انہی کے ہیں ) ، ہمیں عیسیٰ بن یونس نے خبر دی ، کہا : ہمیں حسین معلم نے حدیث بیان کی ، انہوں نے بدیل بن میسرہ سے ، انہوں نے ابو جوزاء سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نماز کا آغاز تکبیر سے اور قراءت کا آغاز ﴿الحمد لله رب العالمين﴾ سے کرتے اور جب رکوع کرتے تو اپنا سر نہ پشت سے اونچا کرتے اور نہ اسے نیچے کرتے بلکہ درمیان میں رکھتے اور جب رکوع سے اپنا سر اٹھاتے تو سجدے میں نہ جاتے حتیٰ کہ سیدھے کھڑے ہو جاتے اور جب سجدہ سے اپنا سر اٹھاتے تو ( دوسرا ) سجدہ نہ کرتے حتیٰ کہ سیدھے بیٹھ جاتے ۔ اور ہر دو رکعتوں کے بعد التحیات پڑھتے اور اپنا بایاں پاؤں بچھا لیتے اور دایاں پاؤں کھڑا رکھتے اور شیطان کی طرح ( دونوں پنڈلیاں کھڑی کر کے ) پچھلے حصے پر بیٹھنے سے منع فرماتے اور اس سے بھی منع فرماتے اور اس سے بھی منع فرماتے کہ انسان اپنے بازو اس طرح بچھا دے جس طرح درندہ بچھاتا ہے ، اور نماز کا اختتام سلام سے کرتے ۔","",{"u2":"محمد بن عبد اللہ بن نمیر نے ہمیں حدیث بیان کی، کہا: ہمیں ابو خالد احمر نے حسین معلم سے حدیث سنائی، نیز اسحاق بن ابراہیم نے کہا: (الفاظ انہی کے ہیں)، ہمیں عیسیٰ بن یونس نے خبر دی، کہا: ہمیں حسین معلم نے حدیث بیان کی، انہوں نے بدیل بن میسرہ سے، انہوں نے ابو جوزاء سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نماز کا آغاز تکبیر سے اور قراءت کا آغاز ﴿الحمد للہ رب العالمین﴾ سے کرتے اور جب رکوع کرتے تو اپنا سر نہ پشت سے اونچا کرتے اور نہ اسے نیچے کرتے بلکہ درمیان میں رکھتے اور جب رکوع سے اپنا سر اٹھاتے تو سجدے میں نہ جاتے حتیٰ کہ سیدھے کھڑے ہو جاتے اور جب سجدہ سے اپنا سر اٹھاتے تو (دوسرا) سجدہ نہ کرتے حتیٰ کہ سیدھے بیٹھ جاتے۔ اور ہر دو رکعتوں کے بعد التحیات پڑھتے اور اپنا بایاں پاؤں بچھا لیتے اور دایاں پاؤں کھڑا رکھتے اور شیطان کی طرح (دونوں پنڈلیاں کھڑی کر کے) پچھلے حصے پر بیٹھنے سے منع فرماتے اور اس سے بھی منع فرماتے اور اس سے بھی منع فرماتے کہ انسان اپنے بازو اس طرح بچھا دے جس طرح درندہ بچھاتا ہے، اور نماز کا اختتام سلام سے کرتے۔"}],[1043,"ابو احوص نے سماک ( بن حرب ) سے ، انہوں نے موسیٰ بن طلحہ سے اور انہوں نے اپنے والد سیدنا طلحہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی اپنا سامنے پالان کی پچھلی لکڑی کے برابر کوئی چیز رکھ لے تو نماز پڑھتا رہے اور اس سے آگے سے گزرنے والے کی پروا نہ کرے ۔ ‘‘","",{"u2":"ابو احوص نے سماک (بن حرب) سے، انہوں نے موسیٰ بن طلحہ سے اور انہوں نے اپنے والد سیدنا طلحہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی اپنا سامنے پالان کی پچھلی لکڑی کے برابر کوئی چیز رکھ لے تو نماز پڑھتا رہے اور اس سے آگے سے گزرنے والے کی پروا نہ کرے۔‘‘"}],[1044,"محمد بن عبد اللہ بن نمیر اور اسحاق بن ابراہیم نے حدیث بیان کی ، اسحاق نے کہا : ’’عمر بن عبید طنافسی نے ہمیں خبر دی ‘‘ اور ابن نمیر نے کہا : ’’ہمیں حدیث سنائی ‘‘ انہوں نے سماک سے ، انہوں نے موسیٰ بن طلحہ سے اور انہوں نے اپنے والد ( سیدنا طلحہ رضی اللہ عنہ ) سے روایت کی ، انہوں نے کہا : ہم نماز پڑھ رہے ہوتے اور جاندار ہمارے سامنے گزرتے ہم نے اس کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا : ’’ تم میں سے کسی شخص کے آگے پالان کی پچھلی لکڑی کے برابر کوئی چیز ہو تو پھر جو چیز بھی اس کے سامنے سے گزرے گی اسے اس کا کوئی نقصان نہیں ۔ ‘‘ ابن نمیر نے ، پھر جو چیز بھی اس کے سامنے سے گزرے گی ، کے بجائے ’’ تو جو کوئی بھی اس کے سامنے سے گزرے گی اسے اس کا کوئی نقصان نہیں ، کے الفاظ بیان کیے ۔","",{"u2":"محمد بن عبد اللہ بن نمیر اور اسحاق بن ابراہیم نے حدیث بیان کی، اسحاق نے کہا: ’’عمر بن عبید طنافسی نے ہمیں خبر دی‘‘ اور ابن نمیر نے کہا: ’’ہمیں حدیث سنائی‘‘ انہوں نے سماک سے، انہوں نے موسیٰ بن طلحہ سے اور انہوں نے اپنے والد (سیدنا طلحہ رضی اللہ عنہ) سے روایت کی، انہوں نے کہا: ہم نماز پڑھ رہے ہوتے اور جاندار ہمارے سامنے گزرتے ہم نے اس کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: ’’ تم میں سے کسی شخص کے آگے پالان کی پچھلی لکڑی کے برابر کوئی چیز ہو تو پھر جو چیز بھی اس کے سامنے سے گزرے گی اسے اس کا کوئی نقصان نہیں۔‘‘\nابن نمیر نے، پھر جو چیز بھی اس کے سامنے سے گزرے گی، کے بجائے ’’ تو جو کوئی بھی اس کے سامنے سے گزرے گی اسے اس کا کوئی نقصان نہیں، کے الفاظ بیان کیے۔"}],[1045,"۔ سعید بن ابی ایوب نے ابو اسود سے ، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم سے نمازی کے سترے کے بارے میں پوچھا گیا تو آپ نے فرمایا : ’’پالان کی پچھلی لکڑی کے مثل ہو ۔ ‘‘","",{"u2":"۔ سعید بن ابی ایوب نے ابو اسود سے، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم سے نمازی کے سترے کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’پالان کی پچھلی لکڑی کے مثل ہو۔‘‘"}],[1046,"حیوہ نے ابو اسود محمد بن عبد الرحمن سے ، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے غزوہ تبوک میں نمازی کے سترے کے بارے میں سوال کیا گیا تو آپ نے فرمایا : ’’پالان کی پچھلی لکڑی کے مانند ہو ۔ ‘‘","",{"u2":"حیوہ نے ابو اسود محمد بن عبد الرحمن سے، انہوں نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے غزوہ تبوک میں نمازی کے سترے کے بارے میں سوال کیا گیا تو آپ نے فرمایا: ’’پالان کی پچھلی لکڑی کے مانند ہو۔‘‘"}],[1047,"عبد اللہ بن نمیر نے عبید اللہ سے ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم عید کے دن نکلتے تو نیزے کا حکم دیتے ، وہ آپ کے آگے گاڑ دیا جاتا ، آپ اس کی طرف رخ کر کے نماز پڑھتے اور لوگ آپ کے پیچھے ہوتے ، سفر میں بھی آپ ایسا ہی کرتے ، اس بنا پر حکام نے اس ( نیزہ گاڑنے ) کو اپنا لیا ہے ۔","",{"u2":"عبد اللہ بن نمیر نے عبید اللہ سے، انہوں نے نافع سے اور انہوں نے حضرت ابن عمر رضی اللہ عنہما سے روایت کی کہ جب رسول اللہ صلی اللہ علیہ وسلم عید کے دن نکلتے تو نیزے کا حکم دیتے، وہ آپ کے آگے گاڑ دیا جاتا، آپ اس کی طرف رخ کر کے نماز پڑھتے اور لوگ آپ کے پیچھے ہوتے، سفر میں بھی آپ ایسا ہی کرتے، اس بنا پر حکام نے اس (نیزہ گاڑنے) کو اپنا لیا ہے۔"}],[1048,"ابو بکر بن ابی شیبہ نے اور ابن نمیر نے کہا : ہمیں محمد بن بشر نے حدیث سنائی ، کہا : ہمیں عبید اللہ نے نافع سے حدیث سنائی اور انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نیزہ گاڑتے اور اس کی طرف رخ کر کے نماز پڑھتے ۔ امام مسلم رضی اللہ عنہ کے استد ابن نمیر نے يركز اور ابو بکر بن ابی شیبہ نے يغزر کا لفظ استعمال کیا ( دونوں کے معنیٰ ہیں : آپ گاڑتے تھے ۔ ) اور ابن ابی شیبہ کی روایت میں یہ اضافہ ہے : عبید اللہ نے کہا : اس ( عنزة ) سے مراد حربة ( برچھی ) ہے ۔","",{"u2":"ابو بکر بن ابی شیبہ نے اور ابن نمیر نے کہا: ہمیں محمد بن بشر نے حدیث سنائی، کہا: ہمیں عبید اللہ نے نافع سے حدیث سنائی اور انہوں نے حضرت ابن عمر رضی اللہ عنہما سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نیزہ گاڑتے اور اس کی طرف رخ کر کے نماز پڑھتے۔ امام مسلم رحمہ اللہ کے استد ابن نمیر نے یرکز اور ابو بکر بن ابی شیبہ نے یغزر کا لفظ استعمال کیا (دونوں کے معنیٰ ہیں: آپ گاڑتے تھے۔)\nاور ابن ابی شیبہ کی روایت میں یہ اضافہ ہے: عبید اللہ نے کہا: اس (عنزۃ) سے مراد حربۃ (برچھی) ہے۔"}],[1049,"معتمر بن سلیمان نے عبید اللہ سے ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم ( بوقت ضرورت ) اپنی سواری کو سامنے کر کے ( بٹھا لیتے اور ) اس کی طرف ( منہ کر کے ) نماز پڑھ لیتے","",{"u2":"معتمر بن سلیمان نے عبید اللہ سے، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم (بوقت ضرورت) اپنی سواری کو سامنے کر کے (بٹھا لیتے اور) اس کی طرف (منہ کر کے) نماز پڑھ لیتے"}],[1050,"ابو بکر بن ابی شیبہ اور ابن نمیر نے کہا : ہمیں ابو خالد احمر نے عبید اللہ سے ، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم ( کبھی کبھی ) اپنی سواری کو سامنے رکھتے ہوئے نماز پڑھ لیتے تھے ۔ اور ( محمد ) بن نمیر نے کہا : نبی اکرم صلی اللہ علیہ وسلم نے اونٹ کو سامنے رکھتے ہوئے ( قبلہ رو ہو کر ) نماز پڑھی ۔","",{"u2":"ابو بکر بن ابی شیبہ اور ابن نمیر نے کہا: ہمیں ابو خالد احمر نے عبید اللہ سے، انہوں نے نافع سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم (کبھی کبھی) اپنی سواری کو سامنے رکھتے ہوئے نماز پڑھ لیتے تھے۔\nاور (محمد) بن نمیر نے کہا: نبی اکرم صلی اللہ علیہ وسلم نے اونٹ کو سامنے رکھتے ہوئے (قبلہ رو ہو کر) نماز پڑھی۔"}],[1051,"۔ سفیان نے بیان کیا : ہمیں عون بن ابی جحیفہ نے اپنے والد ( سیدنا ابو جحیفہ رضی اللہ عنہ ) سے حدیث بیان کی ، انہوں نے کہا : میں مکہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا ، آپ ابطح کے مقام پر چمڑے کے ایک سرخ خیمے میں ( قیام پذیر ) تھے ۔ ( ابو جحیفہ نے ) کہا : بلال رضی اللہ عنہ آپ کے وضو کا پانی لے کر باہر آئے ( بعد ازاں جب آپ نے وضو کر لیا تو ) اس میں سے کسی کو پانی مل گیا اور کسی نے ( دوسرے سے اس کی ) نمی لے لی ۔ انہوں نے کہا : پھر نبی اکرم صلی اللہ علیہ وسلم سرخ حلہ ( لباس کے اوپر لمبا چوغہ ) پہنے ہوئے نکلے ، ( ایسا لگتا ہے ) جیسے ( آج بھی ) میں آپ کی پنڈلیوں کی سفیدی کو دیکھ رہا ہوں ۔ آپ نے وضو کیا اور بلال رضی اللہ عنہ نے اذان کہی ، انہوں نے کہا : میں بھی ان کے منہ پیچھے اس طرح اور اس طرف رخ کرنے لگا ، ( جب ) وہ حي على الصلاة اور حي على الفلاح کہہ رہے تھے تو انہوں نے دائیں بائیں رخ کیا ، کہا : پھر آپ کے لیے نیزہ گاڑا گیا اور آپ نے آگے بڑھ کر ظہری کی دو رکعتیں ( قصر ) پڑھائیں ، آپ کے آگے سے گدھا اور کتا گزر تا تھا ، انہیں روکا نہ جاتا تھا ، پھر آپ نے عصر کی دو رکعتیں پڑھائیں اور پھر مدینہ واپسی تک مسلسل دو رکعتیں ہی پڑھاتے رہے ۔",""],[1052,"۔ عمر بن ابی زائدہ سے روایت ہے کہ مجھے عون بن ابی جحیفہ نے حدیث بیان کی کہ ان کے والد نے رسول اللہ صلی اللہ علیہ وسلم کو چمڑے کے سرخ خیمے میں دیکھا ( کہا : ) اور میں نے بلال رضی اللہ عنہ کو دیکھا وہ آپ کے وضو کا پانی باہر لے آئے تو میں نے دیکھا لوگ اس پانی کو لینے کے لیے ایک دوسرے سے سبقت لے جانے کی کوشش کر رہے ہیں ، جس کو اس سے کچھ پانی مل گیا اس نے اس کو بدن پر مل لیا اور جس کو اس سے نہ ملا تو اس نے اپنے ساتھ کے ہاتھ کی نمی سے نمی حاصل کر لی ، پھر میں نے بلال کو دیکھا انہوں نے ایک نیزہ نکالا اور کو گاڑ دیا ، رسول اللہ صلی اللہ علیہ وسلم سرخ حلہ پہنے ہوئے نکلے جو آپ نے پنڈلیوں تک اونچا کیا ہوا تھا ، آپ نے نیزے کی طرف رخ کر کے لوگوں کو دو رکعت نماز پڑھائی اور میں نے لوگوں اور چوپایوں کو نیزے کے سامنے سے گزرتے ہوئے دیکھا ۔","",{"u2":"۔ عمر بن ابی زائدہ سے روایت ہے کہ مجھے عون بن ابی جحیفہ نے حدیث بیان کی کہ ان کے والد نے رسول اللہ صلی اللہ علیہ وسلم کو چمڑے کے سرخ خیمے میں دیکھا (کہا:) اور میں نے بلال رضی اللہ عنہ کو دیکھا وہ آپ کے وضو کا پانی باہر لے آئے تو میں نے دیکھا لوگ اس پانی کو لینے کے لیے ایک دوسرے سے سبقت لے جانے کی کوشش کر رہے ہیں، جس کو اس سے کچھ پانی مل گیا اس نے اس کو بدن پر مل لیا اور جس کو اس سے نہ ملا تو اس نے اپنے ساتھ کے ہاتھ کی نمی سے نمی حاصل کر لی، پھر میں نے بلال کو دیکھا انہوں نے ایک نیزہ نکالا اور کو گاڑ دیا، رسول اللہ صلی اللہ علیہ وسلم سرخ حلہ پہنے ہوئے نکلے جو آپ نے پنڈلیوں تک اونچا کیا ہوا تھا، آپ نے نیزے کی طرف رخ کر کے لوگوں کو دو رکعت نماز پڑھائی اور میں نے لوگوں اور چوپایوں کو نیزے کے سامنے سے گزرتے ہوئے دیکھا۔"}],[1053,"ابو عمیس نے اور مالک بن مغول دونوں نے اپنی اپنی سند سے عون بن ابی جحفہ سے ، انہوں نے اپنے والد سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے سفیان اور عمرو بن ابی زائدہ کی حدیث کی طرح بیان کیا ہے ۔ ان ( چاروں سفیان ، عمر ، ابو عمیس اور مالک ) میں بعض دوسروں سے زائد الفاظ بیان کرتے ہیں ۔ مالک بن مغول کی حدیث میں ہے : جب دوپہر کا وقت ہوا تو بلال نکلے اور نماز کے لیے اذان دی ۔","",{"u2":"ابو عمیس نے اور مالک بن مغول دونوں نے اپنی اپنی سند سے عون بن ابی جحفہ سے، انہوں نے اپنے والد سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے سفیان اور عمرو بن ابی زائدہ کی حدیث کی طرح بیان کیا ہے۔ ان (چاروں سفیان، عمر، ابو عمیس اور مالک) میں بعض دوسروں سے زائد الفاظ بیان کرتے ہیں۔\nمالک بن مغول کی حدیث میں ہے: جب دوپہر کا وقت ہوا تو بلال نکلے اور نماز کے لیے اذان دی۔"}],[1054,"۔ محمد بن جعفر نے کہا : ہمیں شعبہ نے حکم سے حدیث سنائی ، انہوں نے کہا : میں نے سیدنا ابو جحیفہ رضی اللہ عنہ سے سنا ، انہوں نے کہا : سخت گرمی کے وقت رسول اللہ صلی اللہ علیہ وسلم بطحا کی طرف نکلے ، وضو کر کے اس عالم میں ظہر اور عصر کی دو دو رکعتیں پڑھیں اور آپ کے سامنے نیزہ تھا ۔ شعبہ نے کہا : عون نے اپنے والد ابو جحیفہ سے ( روایت کرتے ہوئے ) یہ اضافہ کیا کہ نیزے کی دوسری طرف سے عورتیں اور گدھے گزر رہے تھے ۔","",{"u2":"۔ محمد بن جعفر نے کہا: ہمیں شعبہ نے حکم سے حدیث سنائی، انہوں نے کہا: میں نے سیدنا ابو جحیفہ رضی اللہ عنہ سے سنا، انہوں نے کہا: سخت گرمی کے وقت رسول اللہ صلی اللہ علیہ وسلم بطحا کی طرف نکلے، وضو کر کے اس عالم میں ظہر اور عصر کی دو دو رکعتیں پڑھیں اور آپ کے سامنے نیزہ تھا۔\nشعبہ نے کہا: عون نے اپنے والد ابو جحیفہ سے (روایت کرتے ہوئے) یہ اضافہ کیا کہ نیزے کی دوسری طرف سے عورتیں اور گدھے گزر رہے تھے۔"}],[1055,"۔ ( عبد الرحمان ) بن مہدی نے ہمیں حدیث بیان کی ، ( کہا : ) شعبہ نے ہمیں ( حکم اور عون کی ) دونوں سندوں کے ساتھ سابقہ حدیث کی مانند حدیث بیان کی اور انہوں نے ( ابن مہدی ) نے حکم کی حدیث میں یہ اضافہ کیا : تو لوگ آپ کے وضو کے بچے ہوئے پانی میں سے ( پانی ) لینے لگے ۔","",{"u2":"۔ (عبد الرحمان) بن مہدی نے ہمیں حدیث بیان کی، (کہا:) شعبہ نے ہمیں (حکم اور عون کی) دونوں سندوں کے ساتھ سابقہ حدیث کی مانند حدیث بیان کی اور انہوں نے (ابن مہدی) نے حکم کی حدیث میں یہ اضافہ کیا: تو لوگ آپ کے وضو کے بچے ہوئے پانی میں سے (پانی) لینے لگے۔"}],[1056,"مالک نے ابن شاب سے ، انہوں نے عبید اللہ بن عبد اللہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : میں گدھی پر سوار ہو کر آیا ، ان دنوں میں بلوغت کے قریب تھا ، رسول اللہ صلی اللہ علیہ وسلم منیٰ میں لوگوں کو نماز پڑھا رہے تھے ، میں صف کے سامنے سے گزرا اور اتر کر گدھی کو چرنے کے لیے چھوڑ دیا اور صف میں داخل ہو گیا تو مجھے کسی نے اس پر نہیں ٹوکا ۔","",{"u2":"مالک نے ابن شاب سے، انہوں نے عبید اللہ بن عبد اللہ سے اور انہوں نے حضرت ابن عباس رضی اللہ عنہما سے روایت کی، انہوں نے کہا: میں گدھی پر سوار ہو کر آیا، ان دنوں میں بلوغت کے قریب تھا، رسول اللہ صلی اللہ علیہ وسلم منیٰ میں لوگوں کو نماز پڑھا رہے تھے، میں صف کے سامنے سے گزرا اور اتر کر گدھی کو چرنے کے لیے چھوڑ دیا اور صف میں داخل ہو گیا تو مجھے کسی نے اس پر نہیں ٹوکا۔"}],[1057,"۔ یونس نے ابن شہاب سے روایت کی ، کہا : مجھے عبید اللہ بن عبد اللہ بن عتبہ نے خبر دی کہ انہیں سیدنا عباس رضی اللہ عنہما نے خبر دی کہ وہ گدھے پر سوار ہو کر آئے جبکہ رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع کے موقع پر منیٰ میں لوگوں کو نماز پڑھا رہے تھے ، انہوں نے کہا : گدھا صف کے کچھ حصے کے آگے سے گزرا ، پھر وہ اس سے اتر کر لوگوں کے ساتھ صف میں مل گئے","",{"u2":"۔ یونس نے ابن شہاب سے روایت کی، کہا: مجھے عبید اللہ بن عبد اللہ بن عتبہ نے خبر دی کہ انہیں حضرت عباس رضی اللہ عنہما نے خبر دی کہ وہ گدھے پر سوار ہو کر آئے جبکہ رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع کے موقع پر منیٰ میں لوگوں کو نماز پڑھا رہے تھے، انہوں نے کہا: گدھا صف کے کچھ حصے کے آگے سے گزرا، پھر وہ اس سے اتر کر لوگوں کے ساتھ صف میں مل گئے"}],[1058,"سفیان بن عیینہ نے زہری سے اسی سند کے ساتھ مذکورہ روایت بیان کی ، کہا : نبی اکرم صلی اللہ علیہ وسلم عرفہ میں نماز پڑھا رہے تھے ۔ ( ابن عباس اپنی سواری پر حج کر رہے تھے ۔ یہ واقعہ ان کے ساتھ غالبا منیٰ اور عرفہ دونوں مقامات پر پیش آیا ۔ اس سے ثابت ہوتا ہے کہ آپ صلی اللہ علیہ وسلم کےلیے ہر جگہ سترے کا اہتمام کیا جاتا تھا ۔)","",{"u2":"سفیان بن عیینہ نے زہری سے اسی سند کے ساتھ مذکورہ روایت بیان کی، کہا: نبی اکرم صلی اللہ علیہ وسلم عرفہ میں نماز پڑھا رہے تھے۔ (ابن عباس اپنی سواری پر حج کر رہے تھے۔ یہ واقعہ ان کے ساتھ غالبا منیٰ اور عرفہ دونوں مقامات پر پیش آیا۔ اس سے ثابت ہوتا ہے کہ آپ صلی اللہ علیہ وسلم کےلیے ہر جگہ سترے کا اہتمام کیا جاتا تھا۔)"}],[1059,"معمر نے بھی زہری سے اسی سند کے ساتھ یہی حدیث بیان کی ہے اوراس میں منیٰ یا عرفہ کا تذکرہ کرنے کے بجائے حجۃ الوداع یا فتح مکہ کے دن کا ذکر کیا ہے","",{"u2":"معمر نے بھی زہری سے اسی سند کے ساتھ یہی حدیث بیان کی ہے اوراس میں منیٰ یا عرفہ کا تذکرہ کرنے کے بجائے حجۃ الوداع یا فتح مکہ کے دن کا ذکر کیا ہے"}],[1060,"عبد الرحمان بن ابی سعید نے ( اپنے والد ) سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی نماز پڑھ رہا ہو تو کسی کو آگے سے نہ گزرنے دے اور جہاں تک ممکن ہو اس کو ہٹائے اگر وہ نہ مانے تو اس سے لڑے کیونکہ وہ شیطان ہے ۔ ‘‘ ( مقصود یہ تھا کہ لوگوں کو اس گناہ سے ہر قیمت پر بچایا جائے اور نماز کی حرمت کا اہتمام کیا جائے ۔)","",{"u2":"عبد الرحمان بن ابی سعید نے (اپنے والد) سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی نماز پڑھ رہا ہو تو کسی کو آگے سے نہ گزرنے دے اور جہاں تک ممکن ہو اس کو ہٹائے اگر وہ نہ مانے تو اس سے لڑے کیونکہ وہ شیطان ہے۔‘‘ (مقصود یہ تھا کہ لوگوں کو اس گناہ سے ہر قیمت پر بچایا جائے اور نماز کی حرمت کا اہتمام کیا جائے۔)"}],[1061,"۔ ابن ہلال ، یعنی حمید نے کہا : ایک دن میں اور میرا ایک ساتھی ایک حدیث کے بارے میں مذاکرہ کر رہے تھے کہ ابو صالح سمان کہنے لگے : میں تمہیں حدیث بیان کرتا ہوں جو میں نے ابو سعید رضی اللہ عنہ سے سنی اور ( ان کا عمل ) جو ان سے دیکھا ۔ کہا : ایک موقع پر ، جب میں سیدنا ابو سعید رضی اللہ عنہ کےساتھ تھا اور وہ جمعہ کے دن کسی چیز کی طرف ( رخ کر کے ) ، جو انہیں لوگوں سے ستر ہ مہیا کر رہی تھی ، نماز پڑھ رہے تھے ، اتنے میں ابو معیط کے خاندان کا ایک نوجوان آیا ، اس نے ان کے آگے سے گزرنا چاہا تو انہوں نے اسے اس کے سینے سے ( پیچھے ) دھکیلا ۔ اس نے نظر دوڑائی ، اسے ابو سعید رضی اللہ عنہ کے سامنے سے ( گزرنے ) کے سوا کوئی راستہ نہ ملا ، اس نے دوبارہ گزرنا چاہا تو انہوں نے اسے پہلی دفعہ سے زیادہ شدت کے ساتھ اس کے سینے سے پیچھے دھکیلا ، وہ سیدھا کھڑا ہو گیا اور ابو سعید رضی اللہ عنہ کو برا بھلا کہا ، پھر لوگوں کی بھیڑ میں گھستا ہوا نکل کر مروان کےسامنے پہنچ گیا اور جو ان کے ساتھ بیتی تھی اس کی شکایت کی ، کہا : ابو سعید رضی اللہ عنہ بھی مروان کے پاس پہنچ گئے تو اس نے ان سے کہا : آپ کا اپنے بھتیجے کا ساتھ کیا معاملہ ہے؟ وہ آ کر آپ کی شکایت کر رہا ہے ۔ ابو سعید رضی اللہ عنہ نے جواب دیا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے : ’’ جب تم میں سے کوئی لوگوں سے کسی چیز کی اوٹ میں نماز پڑھے اور کوئی اس کے آگے سے گزرنا چاہے تو وہ اسے اس کے سینے سے دھکیلے اگر وہ نہ مانے تو اس سے لڑے کیونکہ وہ یقیناً شیطان ہے ۔ ‘‘","",{"u2":"۔ ابن ہلال، یعنی حمید نے کہا: ایک دن میں اور میرا ایک ساتھی ایک حدیث کے بارے میں مذاکرہ کر رہے تھے کہ ابو صالح سمان کہنے لگے: میں تمہیں حدیث بیان کرتا ہوں جو میں نے ابو سعید رضی اللہ عنہ سے سنی اور (ان کا عمل) جو ان سے دیکھا۔ کہا: ایک موقع پر، جب میں سیدنا ابو سعید رضی اللہ عنہ کےساتھ تھا اور وہ جمعہ کے دن کسی چیز کی طرف (رخ کر کے)، جو انہیں لوگوں سے ستر ہ مہیا کر رہی تھی، نماز پڑھ رہے تھے، اتنے میں ابو معیط کے خاندان کا ایک نوجوان آیا، اس نے ان کے آگے سے گزرنا چاہا تو انہوں نے اسے اس کے سینے سے (پیچھے) دھکیلا۔ اس نے نظر دوڑائی، اسے ابو سعید رضی اللہ عنہ کے سامنے سے (گزرنے) کے سوا کوئی راستہ نہ ملا، اس نے دوبارہ گزرنا چاہا تو انہوں نے اسے پہلی دفعہ سے زیادہ شدت کے ساتھ اس کے سینے سے پیچھے دھکیلا، وہ سیدھا کھڑا ہو گیا اور ابو سعید رضی اللہ عنہ کو برا بھلا کہا، پھر لوگوں کی بھیڑ میں گھستا ہوا نکل کر مروان کےسامنے پہنچ گیا اور جو ان کے ساتھ بیتی تھی اس کی شکایت کی، کہا: ابو سعید رضی اللہ عنہ بھی مروان کے پاس پہنچ گئے تو اس نے ان سے کہا: آپ کا اپنے بھتیجے کا ساتھ کیا معاملہ ہے؟ وہ آ کر آپ کی شکایت کر رہا ہے۔ ابو سعید رضی اللہ عنہ نے جواب دیا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے:’’ جب تم میں سے کوئی لوگوں سے کسی چیز کی اوٹ میں نماز پڑھے اور کوئی اس کے آگے سے گزرنا چاہے تو وہ اسے اس کے سینے سے دھکیلے اگر وہ نہ مانے تو اس سے لڑے کیونکہ وہ یقیناً شیطان ہے۔‘‘"}],[1062,"اسماعیل بن ابی فدیک نے ضحاک بن عثمان سے ، انہوں نے صدقہ بن یسار سے ، اور انہوں نے سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی نماز پڑھ رہا ہو تو کسی کو اپنے آگے سے نہ گزرنے دے ، اگر وہ نہ مانے تو اس سے لڑے کیونکہ اس کی معیت میں ( اس کا ) ہمراہی ( شیطان ) ہے ۔","",{"u2":"اسماعیل بن ابی فدیک نے ضحاک بن عثمان سے، انہوں نے صدقہ بن یسار سے، اور انہوں نے حضرت عبد اللہ بن عمر رضی اللہ عنہما سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی نماز پڑھ رہا ہو تو کسی کو اپنے آگے سے نہ گزرنے دے، اگر وہ نہ مانے تو اس سے لڑے کیونکہ اس کی معیت میں (اس کا) ہمراہی (شیطان) ہے۔"}],[1063,"۔ ( ابن ابی فدیک کے بجائے ) ابو بکر حنفی نے ضحاک بن عثمان سے اسی ( مذکورہ ) سند کےساتھ روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ... آگے سابقہ حدیث کے مانند ہے","",{"u2":"۔ (ابن ابی فدیک کے بجائے) ابو بکر حنفی نے ضحاک بن عثمان سے اسی (مذکورہ) سند کےساتھ روایت کی کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا: ... آگے سابقہ حدیث کے مانند ہے"}],[1064,"۔ امام مالک کے ابو نضر سے اور انہوں نے بسر بن سعید سے روایت کی کہ زید بن خالد جہنی رضی اللہ عنہ نے انہیں ابو جہیم رضی اللہ عنہ کی خدمت میں بھیجا تاکہ ان سے پوچھیں کہ انہوں نے نمازی کے آگے سے گزرنے والے کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کیا سنا تھا؟ ابو جہیم رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اگر نمازی کے آگے سے گزرنے والا جان لے کہ اس پر کس قدر ( گناہ ) ہے تو اسے چالیس ( سال ) تک کھڑے رہنا ، اس کے آگے گزرنے سے بہتر ( معلوم ) ہو ۔ ‘‘ ابو نضر نے کہا : مجھے معلوم نہیں ، انہوں نے چالیس دن کہا یا ماہ یا سال ۔ ( مسند بزار میں چالیس سال کے الفاظ ہیں ۔)","",{"u2":"۔ امام مالک کے ابو نضر سے اور انہوں نے بسر بن سعید سے روایت کی کہ زید بن خالد جہنی رضی اللہ عنہ نے انہیں ابو جہیم رضی اللہ عنہ کی خدمت میں بھیجا تاکہ ان سے پوچھیں کہ انہوں نے نمازی کے آگے سے گزرنے والے کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے کیا سنا تھا؟ ابو جہیم رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اگر نمازی کے آگے سے گزرنے والا جان لے کہ اس پر کس قدر (گناہ) ہے تو اسے چالیس (سال) تک کھڑے رہنا، اس کے آگے گزرنے سے بہتر (معلوم) ہو۔‘‘\nابو نضر نے کہا: مجھے معلوم نہیں، انہوں نے چالیس دن کہا یا ماہ یا سال۔\n(مسند بزار میں چالیس سال کے الفاظ ہیں۔)"}],[1065,"سفیان نے ابو نضر سالم سے اور انہوں نے بسر بن سعید سے روایت کی کہ زید بن خالد جہنی رضی اللہ عنہ نے ( انہیں ) ابو جہیم انصاری رضی اللہ عنہ کے پاس بھیجا ( تاکہ پوچھے ) کہ آپ نے نبی اکرم صلی اللہ علیہ وسلم کو کیا فرماتے سنا .... پھر ( سفیان نے ) مالک کی روایت کے ہم معنیٰ حدیث بیان کی ۔","",{"u2":"سفیان نے ابو نضر سالم سے اور انہوں نے بسر بن سعید سے روایت کی کہ زید بن خالد جہنی رضی اللہ عنہ نے (انہیں) ابو جہیم انصاری رضی اللہ عنہ کے پاس بھیجا (تاکہ پوچھے) کہ آپ نے نبی اکرم صلی اللہ علیہ وسلم کو کیا فرماتے سنا .... پھر (سفیان نے) مالک کی روایت کے ہم معنیٰ حدیث بیان کی۔"}],[1066,"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے سجدے کی جگہ اور دیوار کی درمیان بکری گزرنے کے برابر فاصلہ تھا ۔","",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے سجدے کی جگہ اور دیوار کی درمیان بکری گزرنے کے برابر فاصلہ تھا۔"}],[1067,"۔ حماد بن مسعدہ نے یزید بن ابی عبید سے اور انہوں نے سیدنا سلمہ بن اکوع رضی اللہ عنہ سے روایت کی کہ وہ ( سلمہ رضی اللہ عنہ ) کوشش کر کے ( مسجد نبوی میں ) اس جگہ نفلی نماز پڑھتے جہاں مصحف ( رکھا ہوا ) تھا اور انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم اسی جگہ کی کوشش فرماتے تھے اور ( یہاں ) منبر اور قبلے کی دیوار کے درمیان بکری کے راستے کے برابر فاصلہ تھا ۔","",{"u2":"۔ حماد بن مسعدہ نے یزید بن ابی عبید سے اور انہوں نے سیدنا سلمہ بن اکوع رضی اللہ عنہ سے روایت کی کہ وہ (سلمہ رضی اللہ عنہ) کوشش کر کے (مسجد نبوی میں) اس جگہ نفلی نماز پڑھتے جہاں مصحف (رکھا ہوا) تھا اور انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم اسی جگہ کی کوشش فرماتے تھے اور (یہاں) منبر اور قبلے کی دیوار کے درمیان بکری کے راستے کے برابر فاصلہ تھا۔"}],[1068,"۔ مکی ( بن ابراہیم ) نے کہا : ہمیں یزید بن ابی عبید نے خبر دی ، انہوں نے کہا : سیدنا سلمہ ( بن اکوع ) رضی اللہ عنہ اس ستون کے پاس نماز پڑھنے کی جستجو کرتے جو مصحف کے پاس تھا ۔ میں نے ان سے کہا : اے ابو مسلم! میں دیکھتا ہوں کہ آپ اس ستون کے پاس نماز پڑھنے کا اہتمام کرتے ہیں ۔ انہوں نے کہا : میں نے نبی اکرم صلی اللہ علیہ وسلم کو اس کے قریب نماز پڑھنے کا اہتمام کرتے دیکھا ہے","",{"u2":"۔ مکی (بن ابراہیم) نے کہا: ہمیں یزید بن ابی عبید نے خبر دی، انہوں نے کہا: حضرت سلمہ (بن اکوع) رضی اللہ عنہ اس ستون کے پاس نماز پڑھنے کی جستجو کرتے جو مصحف کے پاس تھا۔ میں نے ان سے کہا: اے ابو مسلم! میں دیکھتا ہوں کہ آپ اس ستون کے پاس نماز پڑھنے کا اہتمام کرتے ہیں۔ انہوں نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم کو اس کے قریب نماز پڑھنے کا اہتمام کرتے دیکھا ہے"}],[1069,"۔ یونس نے حمید بن ہلال سے ، انہوں نے عبد اللہ بن صامت سے اور انہوں نے سیدنا ابو ذر ( غفاری ) رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے کوئی نماز کے لیے کھڑا ہو جب اس کے سامنے پالان کی پچھلی لکڑی کے برابر کوئی چیز ہو گی تو وہ اسے سترہ مہیا کرے گی ، اور جب اس کے سامنے پالان کی پچھلی لکڑی کے برابر کوئی چیز نہ ہو گی تو گدھا ، عورت اور سیاہ کتا اس کی نماز کو قطع کریں گے ۔ ‘‘ میں نے کہا : اے ابو ذر! سیاہ کتے کی لال کتے یا زرد کتے سے تخصیص کیوں ہے؟ انہوں نے کہا : بھتیجے! میں نے بھی رسول اللہ صلی اللہ علیہ وسلم سے یہی سوال کیا تھا جو تم نے مجھ سے کیا ہے تو آپ نے فرمایا تھا : ’’ سیاہ کتا شیطان ہوتا ہے ۔ ‘‘","",{"u2":"۔ یونس نے حمید بن ہلال سے، انہوں نے عبد اللہ بن صامت سے اور انہوں نے حضرت ابو ذر (غفاری) رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جب تم میں سے کوئی نماز کے لیے کھڑا ہو جب اس کے سامنے پالان کی پچھلی لکڑی کے برابر کوئی چیز ہو گی تو وہ اسے سترہ مہیا کرے گی، اور جب اس کے سامنے پالان کی پچھلی لکڑی کے برابر کوئی چیز نہ ہو گی تو گدھا، عورت اور سیاہ کتا اس کی نماز کو قطع کریں گے۔‘‘\nمیں نے کہا: اے ابو ذر! سیاہ کتے کی لال کتے یا زرد کتے سے تخصیص کیوں ہے؟ انہوں نے کہا: بھتیجے! میں نے بھی رسول اللہ صلی اللہ علیہ وسلم سے یہی سوال کیا تھا جو تم نے مجھ سے کیا ہے تو آپ نے فرمایا تھا: ’’ سیاہ کتا شیطان ہوتا ہے۔‘‘"}],[1070,"سلیمان بن مغیرہ ، شعبہ ، جریر ، سلم بن ابو ذیال اور عاصم احول سب نے حمید بن ہلال سے یونس کی سند کے ساتھ اس کی حدیث کی مانند حدیث بیان کی ہے ۔","",{"u2":"سلیمان بن مغیرہ، شعبہ، جریر، سلم بن ابو ذیال اور عاصم احول سب نے حمید بن ہلال سے یونس کی سند کے ساتھ اس کی حدیث کی مانند حدیث بیان کی ہے۔"}],[1071,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ عورت ، گدھا اور کتا نماز قطع کر دیتے ہیں اور پالان کی پچھلی لکڑی کے برابر کوئی چیز اسے بچاتی ہے ۔ ‘‘","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ عورت، گدھا اور کتا نماز قطع کر دیتے ہیں اور پالان کی پچھلی لکڑی کے برابر کوئی چیز اسے بچاتی ہے۔‘‘"}],[1072,"زہری نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم رات کو نماز پڑھتے تھے ، میں جنازے کی طرح آپ کے اور قبلے کے درمیان چوڑائی میں لیٹی ہوتی تھی","",{"u2":"زہری نے عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم رات کو نماز پڑھتے تھے، میں جنازے کی طرح آپ کے اور قبلے کے درمیان چوڑائی میں لیٹی ہوتی تھی"}],[1073,"۔ ہشام نے اپنے والد عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم رات کو اپنی پوری نماز پڑھتے اور میں آپ کے اور قبلے کے درمیان لیٹی ہوتی تھی اور جب آپ وتر پڑھنا چاہتے ، مجھے جگا دیتے تو میں بھی وتر پڑھ لیتی","",{"u2":"۔ ہشام نے اپنے والد عروہ سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم رات کو اپنی پوری نماز پڑھتے اور میں آپ کے اور قبلے کے درمیان لیٹی ہوتی تھی اور جب آپ وتر پڑھنا چاہتے، مجھے جگا دیتے تو میں بھی وتر پڑھ لیتی"}],[1074,"ابو بکر بن حفص نے عروہ سے روایت کی ، انہوں نے کہا : سیدہ عائشہ رضی اللہ عنہا نے پوچھا : کون سی چیز نماز قطع کر دیتی ہے؟ تو ہم نے کہا : عورت اور گدھا ۔ اس پر انہوں نے کہا : عورت برا چوپایہ ہے! میں نے اپنے آپ کو دیکھا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے چوڑائی رخ جنازے کی طرح لیٹی ہوتی تھی جبکہ آپ نماز پڑھ رہے تھے ۔","",{"u2":"ابو بکر بن حفص نے عروہ سے روایت کی، انہوں نے کہا: سیدہ عائشہ رضی اللہ عنہا نے پوچھا: کون سی چیز نماز قطع کر دیتی ہے؟ تو ہم نے کہا: عورت اور گدھا۔ اس پر انہوں نے کہا: عورت برا چوپایہ ہے! میں نے اپنے آپ کو دیکھا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے چوڑائی رخ جنازے کی طرح لیٹی ہوتی تھی جبکہ آپ نماز پڑھ رہے تھے۔"}],[1075,"اعمش نے ہمیں حدیث سنائی ، کہا : مجھے ابراہیم نے حدیث بیان کی ، انہوں نے اسود سے اور اسود نے عائشہ رضی اللہ عنہا سے روایت کی ۔ اعمش نے ( مزید ) کہا : مجھے مسلم بن صبیح نے مسروق سے حدیث بیان کی اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، ان کے سامنے ان چیزوں کا تذکرہ کیا گیا جو نماز قطع کرتی ہیں ( یعنی ) کتا ، گدھا اور عورت ۔ تو عائشہ رضی اللہ عنہا نے فرمایا : تم نے ہمیں گدھوں اور کتوں کے مشابہ بنا دیا ہے! اللہ کی قسم! میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس حال میں نماز پڑھتے دیکھا کہ میں چار پائی پر آپ کے اور قبلے کے درمیان لیٹی ہوتی تھی ، مجھے ضرورت پیش آتی تو میں بیٹھ کر رسول اللہ صلی اللہ علیہ وسلم کو تکلیف دینا پسند نہ کرتی ، اس لیے میں اس ( چار پائی یا بستر ) کے پایوں ( والی جگہ کی طرف ) سے کھسک جاتی ۔","",{"u2":"اعمش نے ہمیں حدیث سنائی، کہا: مجھے ابراہیم نے حدیث بیان کی، انہوں نے اسود سے اور اسود نے عائشہ رضی اللہ عنہا سے روایت کی۔ اعمش نے (مزید) کہا: مجھے مسلم بن صبیح نے مسروق سے حدیث بیان کی اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، ان کے سامنے ان چیزوں کا تذکرہ کیا گیا جو نماز قطع کرتی ہیں (یعنی) کتا، گدھا اور عورت۔ تو عائشہ رضی اللہ عنہا نے فرمایا: تم نے ہمیں گدھوں اور کتوں کے مشابہ بنا دیا ہے! اللہ کی قسم! میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس حال میں نماز پڑھتے دیکھا کہ میں چار پائی پر آپ کے اور قبلے کے درمیان لیٹی ہوتی تھی، مجھے ضرورت پیش آتی تو میں بیٹھ کر رسول اللہ صلی اللہ علیہ وسلم کو تکلیف دینا پسند نہ کرتی، اس لیے میں اس (چار پائی یا بستر) کے پایوں (والی جگہ کی طرف) سے کھسک جاتی۔"}],[1076,"منصور نے ابراہیم ( نخعی ) سے ، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے فرمایا : تم نے ہمیں کتوں اور گدھوں کے برابر کر دیا ہے ، حالانکہ میں نے اپنے آپ کو ( اس طرح ) دیکھا ہے کہ میں چار پائی پر لیٹی ہوتی تھی ، رسول اللہ صلی اللہ علیہ وسلم تشریف لاتے اور چارپائی کے وسط میں کھڑے ہو کر نماز پڑھتے ، میں آپ کے سامنے ہونا پسند نہ کرتی ، اس لیے میں چار پائی کے پایوں کی طرف سے کھسکتی یہاں تک کہ اپنے لحاف سے نکل جاتی ۔","",{"u2":"منصور نے ابراہیم (نخعی) سے، انہوں نے اسود سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے فرمایا: تم نے ہمیں کتوں اورگدھوں کے برابر کر دیا ہے، حالانکہ میں نے اپنے آپ کو (اس طرح) دیکھا ہے کہ میں چار پائی پر لیٹی ہوتی تھی، رسول اللہ صلی اللہ علیہ وسلم تشریف لاتے اور چارپائی کے وسط میں کھڑے ہو کر نماز پڑھتے، میں آپ کے سامنے ہونا پسند نہ کرتی، اس لیے میں چار پائی کے پایوں کی طرف سے کھسکتی یہاں تک کہ اپنے لحاف سے نکل جاتی۔"}],[1077,"ابو سلمہ بن عبد الرحمن نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے سو جاتی اور میرے پاؤں آپ کے قبلے ( والے حصے ) میں ہوتے ، جب آپ سجدہ کرتے تو ( پاؤں پر ہاتھ لگا کر ) مجھے اشارہ کر دیتے تو میں اپنے دونوں پاؤں سکیٹر لیتی اور جب آپ کھڑے ہو جاتے تو میں ان کو پھیلا لیتی ۔ انہوں ( عائشہ رضی اللہ عنہا ) نے کہا : گھر ان دنوں ایسے تھے کہ ان میں چراغ نہیں ہوتے تھے ۔","",{"u2":"ابو سلمہ بن عبد الرحمن نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے سو جاتی اور میرے پاؤں آپ کے قبلے (والے حصے) میں ہوتے، جب آپ سجدہ کرتے تو (پاؤں پر ہاتھ لگا کر) مجھے اشارہ کر دیتے تو میں اپنے دونوں پاؤں سکیٹر لیتی اور جب آپ کھڑے ہو جاتے تو میں ان کو پھیلا لیتی۔ انہوں (عائشہ رضی اللہ عنہا) نے کہا: گھر ان دنوں ایسے تھے کہ ان میں چراغ نہیں ہوتے تھے۔"}],[1078,"۔ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نماز پڑھتے اور میں حیض کی حالت میں آپ کے سامنے ہوتی ، بسا اوقات آپ سجدہ کرتے تو آپ کا کپڑا مجھ سے لگ رہا ہوتا","",{"u2":"۔ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ میمونہ رضی اللہ عنہا سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نماز پڑھتے اور میں حیض کی حالت میں آپ کے سامنے ہوتی، بسا اوقات آپ سجدہ کرتے تو آپ کا کپڑا مجھ سے لگ رہا ہوتا"}],[1079,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم رات کو نماز پڑھتے اور میں حیض کی حالت میں آپ کے پہلو کی جانب ہوتی ۔ مجھ پر چادر ہوتی اور اس چادر کا کچھ حصہ آپ کے پہلو ( کی طرف ) سے آپ پر ( بھی ) ہوتا ۔","",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم رات کو نماز پڑھتے اور میں حیض کی حالت میں آپ کے پہلو کی جانب ہوتی۔ مجھ پر چادر ہوتی اور اس چادر کا کچھ حصہ آپ کے پہلو (کی طرف) سے آپ پر (بھی) ہوتا۔"}],[1080,"۔ امام مالک نے ابن شہاب ( زہری ) سے ، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ ایک سائل نے رسول اللہ صلی اللہ علیہ وسلم سے ایک کپڑے میں نماز پڑھنے کے بارے میں سوال کیا تو آپ نے فرمایا : ’’ کیا تم میں سے ہر ایک کے پاس دو کپڑے ہیں؟ ‘‘","",{"u2":"۔ امام مالک نے ابن شہاب (زہری) سے، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ ایک سائل نے رسول اللہ صلی اللہ علیہ وسلم سے ایک کپڑے میں نماز پڑھنے کے بارے میں سوال کیا تو آپ نے فرمایا: ’’ کیا تم میں سے ہر ایک کے پاس دو کپڑے ہیں؟‘‘"}],[1081,"۔ یونس اور عقیل بن خالد دونوں نے ابن شہاب ( زہری ) سے ، انہوں نے سعید بن مسیب اور ابو سلمہ سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے سابقہ حدیث کے مانند روایت بیان کی","",{"u2":"۔ یونس اور عقیل بن خالد دونوں نے ابن شہاب (زہری) سے، انہوں نے سعید بن مسیب اور ابو سلمہ سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے سابقہ حدیث کے مانند روایت بیان کی"}],[1082,"۔ محمد بن سیرین نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : ایک آدمی نے نبی صلی اللہ علیہ وسلم کو پکار کر پوچھا : کیا ہم میں سے کوئی شخص صرف ایک کپڑے میں نماز پڑھ سکتا ہے؟ تو آپ نے فرمایا : ’’ کیا تم میں سے ہر ایک کے پاس دو کپڑے ہیں؟ ‘‘","",{"u2":"۔ محمد بن سیرین نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: ایک آدمی نے نبی صلی اللہ علیہ وسلم کو پکار کر پوچھا: کیا ہم میں سے کوئی شخص صرف ایک کپڑے میں نماز پڑھ سکتا ہے؟ تو آپ نے فرمایا: ’’ کیا تم میں سے ہر ایک کے پاس دو کپڑے ہیں؟‘‘"}],[1083,"۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ تم میں سے کوئی شخص ایک کپڑے میں نماز اس طرح نہ پڑھے کہ اس کے کندھوں پر اس کا کوئی حصہ نہ ہو ۔ ‘‘","",{"u2":"۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ تم میں سے کوئی شخص ایک کپڑے میں نماز اس طرح نہ پڑھے کہ اس کے کندھوں پر اس کا کوئی حصہ نہ ہو۔‘‘"}],[1084,"ابو اسامہ نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا عمر بن ابی سلمہ رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو ام سلمہ رضی اللہ عنہا کے گھر میں ایک کپڑے میں نماز پڑھتے دیکھا ، آپ اسے لپیٹے ہوئے تھے اور اس کے دونوں کنارے اپنے کندھوں پر رکھے ہوئے تھے","",{"u2":"ابو اسامہ نے ہشام بن عروہ سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا عمر بن ابی سلمہ رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ام سلمہ رضی اللہ عنہا کے گھر میں ایک کپڑے میں نماز پڑھتے دیکھا، آپ اسے لپیٹے ہوئے تھے اور اس کے دونوں کنارے اپنے کندھوں پر رکھے ہوئے تھے"}],[1085,"۔ وکیع نے ہشام بن عروہ کی مذکورہ بالا سند سے حدیث سنائی ، ہاں یہ فرق ہے کہ اس نے متوشحا کہا مشتملا نہ کہا","",{"u2":"۔ وکیع نے ہشام بن عروہ کی مذکورہ بالا سند سے حدیث سنائی، ہاں یہ فرق ہے کہ اس نے متوشحا کہا مشتملا نہ کہا"}],[1086,"حماد بن زید نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا عمر بن ابی سلمہ رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو ام سلمہ رضی اللہ عنہا کے گھر میں ایک کپڑے میں نماز پڑھتے دیکھا ، آپ نے اس کے دونوں کناروں کو ادل بدل کر رکھا تھا ، یعنی دائیں کنارے کو بائیں طرف اور بائیں کنارے کو دائیں طرف لے گئے تھے","",{"u2":"حماد بن زید نے ہشام بن عروہ سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا عمر بن ابی سلمہ رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ام سلمہ رضی اللہ عنہا کے گھر میں ایک کپڑے میں نماز پڑھتے دیکھا، آپ نے اس کے دونوں کناروں کو ادل بدل کر رکھا تھا، یعنی دائیں کنارے کو بائیں طرف اور بائیں کنارے کو دائیں طرف لے گئے تھے"}],[1087,"قتیبہ بن سعید اور عیسیٰ بن حماد نے کہا : ہمیں لیث نے یحییٰ بن سعید سے حدیث سنائی انہوں نے ابو امامہ بن سہل بن حنیف سے اور انہوں نے سیدنا عمر بن ابی سلمہ رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک کپڑے میں نماز پڑھتے دیکھا : آپ نے اس کو لپیٹا ہوا تھا اور اس کے دونوں کناروں کو مخالف سمت میں ڈالا ہوا تھا ۔ عیسیٰ بن حماد نے اپنی روایت میں یہ اضافہ کیا : اپنے کندھوں پر ڈالے ہوئے تھے ۔","",{"u2":"قتیبہ بن سعید اور عیسیٰ بن حماد نے کہا: ہمیں لیث نے یحییٰ بن سعید سے حدیث سنائی انہوں نے ابو امامہ بن سہل بن حنیف سے اور انہوں نے سیدنا عمر بن ابی سلمہ رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک کپڑے میں نماز پڑھتے دیکھا: آپ نے اس کو لپیٹا ہوا تھا اور اس کے دونوں کناروں کو مخالف سمت میں ڈالا ہوا تھا۔\nعیسیٰ بن حماد نے اپنی روایت میں یہ اضافہ کیا: اپنے کندھوں پر ڈالے ہوئے تھے۔"}],[1088,"۔ وکیع نے کہا : ہمیں سفیان نے ابو زبیر سے حدیث سنائی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، کہا : میں نے نبی اکرم صلی اللہ علیہ وسلم کو ایک کپڑے میں نماز پڑھتے دیکھا ، آپ اس کو پٹکے کی طرح لپیٹا ہوا تھا ۔","",{"u2":"۔ وکیع نے کہا: ہمیں سفیان نے ابو زبیر سے حدیث سنائی، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم کو ایک کپڑے میں نماز پڑھتے دیکھا، آپ اس کو پٹکے کی طرح لپیٹا ہوا تھا۔"}],[1089,"۔ محمد بن عبد اللہ بن نمیر نے اپنے والد سے حدیث بیان کی ، نیز محمد بن مثنیٰ نے عبد الرحمان سے حدیث بیان کی ، ان دونوں ( ابن نمیر اور عبد الرحمان ) نے سفیان سے اسی سند کے ساتھ یہی روایت بیان کی ۔ اور ابن نمیر کی حدیث میں ہے ، کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر ہوا ۔","",{"u2":"۔ محمد بن عبد اللہ بن نمیر نے اپنے والد سے حدیث بیان کی، نیز محمد بن مثنیٰ نے عبد الرحمان سے حدیث بیان کی، ان دونوں (ابن نمیر اور عبد الرحمان) نے سفیان سے اسی سند کے ساتھ یہی روایت بیان کی۔\nاور ابن نمیر کی حدیث میں ہے، کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر ہوا۔"}],[1090,"عمرو نے کہا کہ ابو زبیر مکی نے مجھے حدیث سنائی کہ انہوں نے جابر بن عبد اللہ رضی اللہ عنہما کو ایک کپڑے میں نماز پڑھتے دیکھا ، وہ اس کو پٹکے کی طرح لپیٹے ہوئے تھے اور ان کے پاس ان کے کپڑے موجود تھے اور جابر رضی اللہ عنہ نے بتایا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے کرتے دیکھا ہے ۔","",{"u2":"عمرو نے کہا کہ ابو زبیر مکی نے مجھے حدیث سنائی کہ انہوں نے جابر بن عبد اللہ رضی اللہ عنہما کو ایک کپڑے میں نماز پڑھتے دیکھا، وہ اس کو پٹکے کی طرح لپیٹے ہوئے تھے اور ان کے پاس ان کے کپڑےموجود تھے اور جابر رضی اللہ عنہ نے بتایا کہ انہوں نے رسو ل اللہ صلی اللہ علیہ وسلم کو ایسے کرتے دیکھا ہے۔"}],[1091,"۔ عیسیٰ بن یونس نے کہا : ہمیں اعمش نے ابو سفیان سے حدیث سنائی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا ، مجھے سیدنا ابو سعید خدری رضی اللہ عنہ نے حدیث سنائی کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے ہاں حاضر ہوئے ، کہا : تو میں نے آپ کو ایک چٹائی پر نماز پڑھتے دیکھا اس پر آپ سجدہ کرتے تھے اور میں نے آپ کو دیکھا آپ ایک کپڑے میں اس کو پٹکے کی طرح لپیٹ کر نماز پڑھ رہے تھے ۔","",{"u2":"۔ عیسیٰ بن یونس نے کہا: ہمیں اعمش نے ابو سفیان سے حدیث سنائی، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی، انہوں نے کہا، مجھے سیدنا ابو سعید خدری رضی اللہ عنہ نے حدیث سنائی کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے ہاں حاضر ہوئے، کہا: تو میں نے آپ کو ایک چٹائی پر نماز پڑھتے دیکھا اس پر آپ سجدہ کرتے تھے اور میں نے آپ کو دیکھا آپ ایک کپڑے میں اس کو پٹکے کی طرح لپیٹ کر نماز پڑھ رہے تھے۔"}],[1092,"۔ ابو بکر بن ابی شیبہ اور ابو کریب نے کہا : ہم سے ابو معاویہ نے بیان کیا ، نیز سوید بن سعید نے کہا : ہم سے علی بن مسہر نے روایت کی ، دونوں نے اعمش سے اسی طرح روایت کی ۔ ابو کریب کی روایت میں ہے : آپ نے اس کے دونوں کنارے اپنے کندھوں پر ڈالے ہوئے تھے ۔ اور ابو بکر اور سوید کی روایت میں ہے : آپ اس کو پٹکے کی طرح لپیٹے ہوئے تھے ۔","",{"u2":"۔ ابو بکر بن ابی شیبہ اور ابو کریب نے کہا: ہم سے ابو معاویہ نے بیان کیا، نیز سوید بن سعید نے کہا: ہم سے علی بن مسہر نے روایت کی، دونوں نے اعمش سے اسی طرح روایت کی۔\nابو کریب کی روایت میں ہے: آپ نے اس کے دونوں کنارے اپنے کندھوں پر ڈالے ہوئے تھے۔ اور ابو بکر اور سوید کی روایت میں ہے: آپ اس کو پٹکے کی طرح لپیٹے ہوئے تھے۔"}],[1093,"ابو کامل جحدری نے کہا : ہمیں عبد الواحد نے اعمش سے حدیث بیان کی ، نیز ابو بکر بن ابی شیبہ اور ابو کریب نے کہا : ہمیں ابو معاویہ نے اعمش سے حدیث سنائی ، انہوں نے حضرت ابراہیم تیمی سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابو ذر رضی اللہ عنہ سے روایت کی ، کہا : میں نے عرض کی : اے اللہ کے رسول! کون سی مسجد جو زمین میں بنائی گئی پہلی ہے؟ آپ نے فرمایا : ’’ مسجد حرام ۔ ‘‘ میں نے پوچھا : پھر کون سی؟ فرمایا : ’’مسجد اقصیٰ ۔ ‘‘ میں نے ( پھر ) پوچھا : دونوں ( کی تعمیر ) کے مابین کتنا زمانہ تھا؟ آپ نے فرمایا : ’’چالیس برس ۔ اور جہاں بھی تمہارے لیے نماز کا وقت ہو جائے ، نماز پڑھ لو ، وہی ( جگہ ) مسجد ہے ۔ ‘‘ ابو کامل کی حدیث میں ہے : ’’ پھر جہاں بھی تمہاری نماز کا وقت ہو جائے ، اسے پڑھ لو ، بلاشبہ وہی جگہ مسجد ہے","",{"u2":"ابو کامل جحدری نے کہا: ہمیں عبد الواحد نے اعمش سے حدیث بیان کی، نیز ابو بکر بن ابی شیبہ اور ابو کریب نے کہا: ہمیں ابو معاویہ نے اعمش سے حدیث سنائی، انہوں نے حضرت ابراہیم تیمی سے، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابو ذر رضی اللہ عنہ سے روایت کی، کہا: میں نے عرض کی: اے اللہ کے رسول! کون سی مسجد جو زمین میں بنائی گئی پہلی ہے؟ آپ نے فرمایا: ’’ مسجد حرام۔‘‘ میں نے پوچھا: پھر کون سی؟ فرمایا: ’’مسجد اقصیٰ۔‘‘ میں نے (پھر) پوچھا: دونوں (کی تعمیر) کے مابین کتنا زمانہ تھا؟ آپ نے فرمایا: ’’چالیس برس۔ اور جہاں بھی تمہارے لیے نماز کا وقت ہو جائے، نماز پڑھ لو، وہی (جگہ) مسجد ہے۔‘‘\nابو کامل کی حدیث میں ہے: ’’ پھر جہاں بھی تمہاری نماز کا وقت ہو جائے، اسے پڑھ لو، بلاشبہ وہی جگہ مسجد ہے"}],[1094,"علی بن مسہر نے کہا : ہمیں اعمش نے ابراہیم بن یزید تیمی سے حدیث سنائی ، کہا : میں مسجد کے باہر کھلی جگہ ( صحن ) میں اپنے والد کو قرآن مجید سنایا کرتا تھا ، جب میں ( آیت ) سجدہ کی تلاوت کرتا تو وہ سجدہ کر لیتے ۔ میں نے ان سے پوچھا : ابا جان! کیا آپ راستے ہی میں سجدہ کر لیتے ہیں؟ انہوں نے جواب دیا : میں نے ابو ذر رضی اللہ عنہ کو یہ کہتے ہوئے سنا وہ بیان کر رہے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے روئے زمین پر سب سے پہلی بنائی جانے والی مسجد کے بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا : ’’ مسجد حرام ۔ ‘‘ میں نے عرض کی : پھر کون سی؟ آپ نے فرمایا ، ’’ مسجد اقصیٰ ۔ ‘‘ میں نے پوچھا : دونوں ( کی تعمیر ) کے درمیان کتنا عرصہ تھا؟ آپ نے فرمایا : ’’ چالیس سال ، پھر ساری زمین ( ہی ) تمہارے لیے مسجد ہے ، جہاں بھی تمہاری نماز کا وقت آ جائے وہیں نماز پڑھ لو ۔ ‘‘","",{"u2":"علی بن مسہر نے کہا: ہمیں اعمش نے ابراہیم بن یزید تیمی سے حدیث سنائی، کہا: میں مسجد کے باہر کھلی جگہ (صحن) میں اپنے والد کو قرآن مجید سنایا کرتا تھا، جب میں (آیت) سجدہ کی تلاوت کرتا تو وہ سجدہ کر لیتے۔ میں نے ان سے پوچھا: ابا جان! کیا آپ راستے ہی میں سجدہ کر لیتے ہیں؟ انہوں نے جواب دیا: میں نے ابو ذر رضی اللہ عنہ کو یہ کہتے ہوئے سنا وہ بیان کر رہے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے روئے زمین پر سب سے پہلی بنائی جانے والی مسجد کے بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ مسجد حرام۔‘‘ میں نے عرض کی: پھر کون سی؟ آپ نے فرمایا، ’’ مسجد اقصیٰ۔‘‘ میں نے پوچھا: دونوں (کی تعمیر) کے درمیان کتنا عرصہ تھا؟ آپ نے فرمایا: ’’ چالیس سال، پھر ساری زمین (ہی) تمہارے لیے مسجد ہے، جہاں بھی تمہاری نماز کا وقت آ جائے وہیں نماز پڑھ لو۔‘‘"}],[1095,"یحییٰ بن یحییٰ نے بیان کیا کہ ہمیں ہشیم نے سیا ر سے خبر دی ، انہوں نے یزید الفقیر سے اور انہوں نے سیدنا جابر بن عبد اللہ انصاری رضی اللہ عنہما سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ مجھے پانچ چیزیں عطا کی گئی ہیں جو مجھ سے پہلے کسی کو نہیں دی گئیں : ہر نبی خاص اپنی قوم ہی کی طرف بھیجا جاتا تھا اور مجھے ہر سرخ وسیاہ کی طرف بھیجا گیا ، میرے لیے اموال غنیمت حلال قرار دیے گئے ، مجھ سے پہلے وہ کسی کے لیے حلال نہیں کیے گئے ۔ میرے لیے زمین کو پاک کرنے والی اور سجدہ گاہ بنایا گیا ، لہٰذا جس شخص کے لیے نماز کا وقت ہو جائے وہ جہاں بھی ہو ، وہیں نماز پڑھ لے ، اور مہینہ بھر کی مسافت سے دشمنوں پر طاری ہو جانے والے رعب سے میری نصرت کی گئی اور مجھے شفاعت ( کا منصب ) عطا کیا گیا ۔ ‘‘","",{"u2":"یحییٰ بن یحییٰ نے بیان کیا کہ ہمیں ہشیم نے سیا ر سے خبر دی، انہوں نے یزید الفقیر سے اور انہوں نے حضرت جابر بن عبد اللہ انصاری رضی اللہ عنہما سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ مجھے پانچ چیزیں عطا کی گئی ہیں جو مجھ سے پہلے کسی کو نہیں دی گئیں: ہر نبی خاص اپنی قوم ہی کی طرف بھیجا جاتا تھا اور مجھے ہر سرخ وسیاہ کی طرف بھیجا گیا، میرے لیے اموال غنیمت حلال قرار دیے گئے، مجھ سے پہلے وہ کسی کے لیے حلال نہیں کیے گئے۔ میرے لیے زمین کو پاک کرنے والی اور سجدہ گاہ بنایا گیا، لہٰذا جس شخص کے لیے نماز کا وقت ہو جائے وہ جہاں بھی ہو، وہیں نماز پڑھ لے، اور مہینہ بھر کی مسافت سے دشمنوں پر طاری ہو جانے والے رعب سے میری نصرت کی گئی اور مجھے شفاعت (کا منصب) عطا کیا گیا۔‘‘"}],[1096,"۔ ابو بکر بن ابی شیبہ نے ہشیم سے اسی سابقہ سند سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فمرایا : ..... پھر اسی طرح بیان کیا ۔","",{"u2":"۔ ابو بکر بن ابی شیبہ نے ہشیم سے اسی سابقہ سند سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فمرایا: ..... پھر اسی طرح بیان کیا۔"}],[1097,"حذیفہ رضی اللہ عنہ سے روایت ہے كہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہم لوگوں كو اور لوگوں پر فضیلت ملی تین باتوں كی وجہ سے ہماری صفیں فرشتوں كی صفوں كی طرح كی گئی اور ہمارے لیے ساری زمین نماز كی جگہ ہے اور زمین كی خاك ہم كو پاك كرنے والی ہے جب پانی نہ ملے اور ایك بات اور بیان كی ۔"],[1098,"۔ ابن ابی زائد نے ( ابو مالک ) سعد بن طارق ( اشجعی ) سے روایت کی ، کہا : مجھے ربعی بن حراش نے سیدنا حذیفہ رضی اللہ عنہ سے حدیث سنائی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ......... آگے سابقہ حدیث کے مانند ہے ۔","",{"u2":"۔ ابن ابی زائد نے (ابو مالک) سعد بن طارق (اشجعی) سے روایت کی، کہا: مجھے ربعی بن حراش نے سیدنا حذیفہ رضی اللہ عنہ سے حدیث سنائی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ......... آگے سابقہ حدیث کے مانند ہے۔"}],[1099,"عبد الرحمان بن یعقوب نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ مجھے دوسرے انبیاء پر چھ چیزوں کے ذریعے سے فضیلت دی گئی ہے : مجھے جامع کلمات عطا کیے گئے ہیں ، ( دشمنوں پر ) رعب ودبدے کے ذریعے سے میری مدد کی گئی ہے ، میرے لیے اموال غنیمت حلال کر دیے گئے ہیں ، زمین میرے لیے پاک کرنے اور مسجد قرار دی گئی ہے ، مجھے تمام مخلوق کی طرف ( رسول بنا کر ) بھیجا گیا ہے اور میرے ذریعے سے ( نبوت کو مکمل کر کے ) انبیاء ختم کر دیے گئے ہیں","",{"u2":"عبد الرحمان بن یعقوب نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ مجھے دوسرے انبیاء پر چھ چیزوں کے ذریعے سے فضیلت دی گئی ہے: مجھے جامع کلمات عطا کیے گئے ہیں، (دشمنوں پر) رعب ودبدے کے ذریعے سے میری مدد کی گئی ہے، میرے لیے اموال غنیمت حلال کر دیے گئے ہیں، زمین میرے لیے پاک کرنے اور مسجد قرار دی گئی ہے، مجھے تمام مخلوق کی طرف (رسول بنا کر) بھیجا گیا ہے اور میرے ذریعے سے (نبوت کو مکمل کر کے) انبیاء ختم کر دیے گئے ہیں"}],[1100,"۔ یونس نے ابن شہاب سے ، انہوں نے سعید بن مسیب سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ مجھے جامع کلمات دے کر بھیجا گیا ہے اور رعب کے ذریعے میری نصرت کی گئی ہے ، میں نیند کے عالم میں تھا کہ زمین کے خزانوں کی کنجیاں میرے پاس لا کر میرے ہاتھوں میں رکھ دی گئیں ۔ ‘‘ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم تو ( اپنے رب کے پاس ) جا چکے ہیں اور تم ان ( خزانوں ) کو کھود کر نکال رہے ہو"],[1101,"۔ زبیدی نے ( ابن شہاب ) زہری سے روایت کی ، انہوں نے کہا : مجھے سعید بن مسیب اور ابو سلمہ بن عبد الرحمٰن نے خبر دی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہا تھے .... ( بقیہ ) یونس کی حدیث کے مانند ہے ۔","",{"u2":"۔ زبیدی نے (ابن شہاب) زہری سے روایت کی، انہوں نے کہا: مجھے سعید بن مسیب اور ابو سلمہ بن عبد الرحمٰن نے خبر دی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہا تھے .... (بقیہ) یونس کی حدیث کے مانند ہے۔"}],[1102,"معمر نے زہری سے ، انہوں نے ابن مسیب اور ابو سلمہ ( بن عبد الرحمن ) سے ، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح بیان کیا ۔","",{"u2":"معمر نے زہری سے، انہوں نے ابن مسیب اور ابو سلمہ (بن عبد الرحمن) سے، انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح بیان کیا۔"}],[1103,"۔ ابو ہریرہ رضی اللہ عنہ کے آزاد کردہ غلام ابو یونس سے روایت ہے ۔ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے حدیث سنائی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : ’’ دشمن پر رعب طاری کر کے میرے مدد کی گئی ، مجھے جامع کلمات سے نوازا گیا اور میں نیند کے عالم میں تھا کہ زمین کے خزانوں کی کنجیاں میرے پاس لائی گئیں اور انہیں میرے ہاتھوں میں دے دیا گیا ۔ ‘‘","",{"u2":"۔ ابو ہریرہ رضی اللہ عنہ کے آزاد کردہ غلام ابو یونس سے روایت ہے۔ انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے حدیث سنائی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: ’’ دشمن پر رعب طاری کر کے میرے مدد کی گئی، مجھے جامع کلمات سے نوازا گیا اور میں نیند کے عالم میں تھا کہ زمین کے خزانوں کی کنجیاں میرے پاس لائی گئیں اور انہیں میرے ہاتھوں میں دے دیا گیا۔‘‘"}],[1104,"ہمام بن منبہ سے روایت ہے ، کہا : یہ احادیث ہیں جو سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ہمیں بیان کی ، انہوں نے متعدد احادیث بیان کیں ، ان میں سے یہ ( بھی ) تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’رعب کے ذریعے میری مدد کی گئی ہے اور مجھے جامع کلمات عنایت کیے گئے ہیں","",{"u2":"ہمام بن منبہ سے روایت ہے، کہا: یہ احادیث ہیں جو سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ہمیں بیان کی، انہوں نے متعدد احادیث بیان کیں، ان میں سے یہ (بھی) تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رعب کے ذریعے میری مدد کی گئی ہے اور مجھے جامع کلمات عنایت کیے گئے ہیں"}],[1105,"۔ عبد الوارث بن سعید نے ہمیں ابو تیاح صبعی سے خبر دی ، انہوں نے کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ تشریف لائے تو مدینہ کے بالائی حصے میں اس قبیلے میں فروکش ہوئے جنہیں بنو عمرو بن عوف کہا جاتا تھا اور وہاں چودہ راتیں قیام فرمایا ، پھر آپ نے بنو نجار کے سرداروں کی طرف پیغام بھیجا تو وہ لوگ ( پورے اہتمام سے ) تلواریں لٹکائے ہوئے حاضر ہوئے ۔ ( انس رضی اللہ عنہ نے ) کہا : گویا میں رسول اللہ صلی اللہ علیہ وسلم کو آپ کی سواری پر دیکھ رہا ہوں ، ابو بکر رضی اللہ عنہ آپ کے پیچھے سوار ہیں اور بنو نجار کے لوگ آپ کے ارد گرد ہیں یہاں تک کہ آپ نے سواری کا پالان ابو ایوب رضی اللہ عنہ کے آنگن میں ڈال دیا ۔ ( انس رضی اللہ عنہ نے ) کہا : ( اس وقت تک ) رسول اللہ صلی اللہ علیہ وسلم کو جہاں بھی نماز کا وقت ہو جاتا آپ وہیں نماز ادا کر لیتے تھے ۔ آپ بکریوں کے باڑے میں بھی نماز پڑھ لیتے تھے ۔ پھر آپ صلی اللہ علیہ وسلم کو مسجد بنانے کا حکم دیا گیا ۔ ( انس رضی اللہ عنہ نے ) کہا : چنانچہ آپ نے بنو نجار کے لوگوں کی طرف پیغام بھیجا ، وہ حاضر ہو گئے ۔ آپ نے فرمایا : ’’ اے بنی نجار! مجھ سے اپنے اس باغ کی قیمت طے کرو ۔ ‘‘ انہوں نے جواب دیا : نہیں ، اللہ کی قسم! ہم اس کی قیمت صرف اللہ تعالیٰ سے مانگتے ہیں ۔ انس رضی اللہ عنہ نے کہا : اس جگہ وہی کچھ تھا جو میں تمہیں بتا رہا ہوں ، اس میں کجھوروں کے کچھ درخت ، مشرکوں کی چند قبریں اور ویرانہ تھا ، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا ، کجھوریں کاٹ دی گئیں ، مشرکوں کی قبریں اکھیڑی گئیں اور ویرانے کو ہموار کر دیا گیا ، اور لوگوں نے کجھوروں ( کے تنوں ) کو ایک قطار میں قبلے کی جانب گاڑ دیا اور دروازے کے ( طور پر ) دونوں جانب پتھر لگا دیے گئے ۔ ( انس رضی اللہ عنہ نے ) کہا : اور لوگ ( صحابہ ) رجزیہ اشعار پڑھ رہے تھے اور رسول اللہ صلی اللہ علیہ وسلم ان کے ساتھ تھے ، وہ کہتے تھے : اے اللہ! بے شک آخرت کی بھلائی کے سوا کوئی بھلائی نہیں ، اس لیے تو انصار اور مہاجرین کی نصرت فرما ۔","",{"u2":"۔ عبد الوارث بن سعید نے ہمیں ابو تیاح صبعی سے خبر دی، انہوں نے کہا: ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ تشریف لائے تو مدینہ کے بالائی حصے میں اس قبیلے میں فروکش ہوئے جنہیں بنو عمرو بن عوف کہا جاتا تھا اور وہاں چودہ راتیں قیام فرمایا، پھر آپ نے بنو نجار کے سرداروں کی طرف پیغام بھیجا تو وہ لوگ (پورے اہتمام سے) تلواریں لٹکائے ہوئے حاضر ہوئے۔ (انس رضی اللہ عنہ نے) کہا: گویا میں رسول اللہ صلی اللہ علیہ وسلم کو آپ کی سواری پر دیکھ رہا ہوں، ابو بکر رضی اللہ عنہ آپ کے پیچھے سوار ہیں اور بنو نجار کے لوگ آپ کے ارد گرد ہیں یہاں تک کہ آپ نے سواری کا پالان ابو ایوب رضی اللہ عنہ کے آنگن میں ڈال دیا۔ (انس رضی اللہ عنہ نے) کہا: (اس وقت تک) رسول اللہ صلی اللہ علیہ وسلم کو جہاں بھی نماز کا وقت ہو جاتا آپ وہیں نماز ادا کر لیتے تھے۔ آپ بکریوں کے باڑے میں بھی نماز پڑھ لیتے تھے۔ پھر آپ صلی اللہ علیہ وسلم کو مسجد بنانے کا حکم دیا گیا۔ (انس رضی اللہ عنہ نے) کہا: چنانچہ آپ نے بنو نجار کے لوگوں کی طرف پیغام بھیجا، وہ حاضر ہو گئے۔ آپ نے فرمایا: ’’ اے بنی نجار! مجھ سے اپنے اس باغ کی قیمت طے کرو۔‘‘ انہوں نے جواب دیا: نہیں، اللہ کی قسم! ہم اس کی قیمت صرف اللہ تعالیٰ سے مانگتے ہیں۔ انس رضی اللہ عنہ نے کہا: اس جگہ وہی کچھ تھا جو میں تمہیں بتا رہا ہوں، اس میں کجھوروں کے کچھ درخت، مشرکوں کی چند قبریں اور ویرانہ تھا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا، کجھوریں کاٹ دی گئیں، مشرکوں کی قبریں اکھیڑی گئیں اور ویرانے کو ہموار کر دیا گیا، اور لوگوں نے کجھوروں (کے تنوں) کو ایک قطار میں قبلے کی جانب گاڑ دیا اور دروازے کے (طور پر) دونوں جانب پتھر لگا دیے گئے۔ (انس رضی اللہ عنہ نے) کہا: اور لوگ (صحابہ) رجزیہ اشعار پڑھ رہے تھے اور رسول اللہ صلی اللہ علیہ وسلم ان کے ساتھ تھے، وہ کہتے تھے: اے اللہ! بے شک آخرت کی بھلائی کے سوا کوئی بھلائی نہیں، اس لیے تو انصار اور مہاجرین کی نصرت فرما۔"}],[1106,"معاذ عنبری نے کہا : ہمیں شعبہ نے حدیث سنائی ، انہوں نے کہا : مجھے ابوتیاح نے سیدنا انس رضی اللہ عنہ سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم مسجد بنانے سے پہلے بکریوں کے باڑے میں نماز پڑھ لیا کرتے تھے ۔","",{"u2":"معاذ عنبری نے کہا: ہمیں شعبہ نے حدیث سنائی، انہوں نے کہا: مجھے ابوتیاح نے سیدنا انس رضی اللہ عنہ سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم مسجد بنانے سے پہلے بکریوں کے باڑے میں نماز پڑھ لیا کرتے تھے۔"}],[1107,"۔ ( معاذ کے بجائے ) خالد ، یعنی ابن حارث نے روایت کی ، کہا : ہمیں شعبہ نے ابو تیاح سے حدیث سنائی ، انہوں نے کہا : میں نے سیدنا انس رضی اللہ عنہ سے سنا ، وہ فرما رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم .... ( آگے ) سابقہ حدیث کے مانند ہے ۔","",{"u2":"۔ (معاذ کے بجائے) خالد، یعنی ابن حارث نے روایت کی، کہا: ہمیں شعبہ نے ابو تیاح سے حدیث سنائی، انہوں نے کہا: میں نے سیدنا انس رضی اللہ عنہ سے سنا، وہ فرما رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم.... (آگے) سابقہ حدیث کے مانند ہے۔"}],[1108,"ابو احوص نے ابو اسحاق سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی ، کہا : میں نے نبی صلی اللہ علیہ وسلم کے ساتھ سولہ ماہ تک بیت المقدس کی طرف ( رخ کر کے ) نماز پڑھی یہاں تک کہ سورہ بقرۃ کی آیت : ’’اور تم جہاں کہیں بھی ہو اپنے رخ کعبہ کی طرف کرو ۔ ‘‘ اتری ۔ یہ آیت اس وقت اتری جب نبی صلی اللہ علیہ وسلم نماز پڑھ چکے تھے ۔ لوگوں میں سے ایک آدمی ( یہ حکم سن ) چلا تو انصار کے کچھ لوگوں کے پاس سے گزرا ، وہ ( مسجد بنی حارثہ میں ، جس کا نام اس واقعے کے بعد مسجد قبلتین پڑ گیا ) نماز پڑھ رہے تھے ، اس نے انہیں یہ ( حکم ) بتایا تو انہوں نے ( اثنائے نماز ہی میں ) اپنے چہرے بیت اللہ کی طرف کر لیے ۔","",{"u2":"ابو احوص نے ابو اسحاق سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی، کہا: میں نے نبی صلی اللہ علیہ وسلم کے ساتھ سولہ ماہ تک بیت المقدس کی طرف (رخ کر کے) نماز پڑھی یہاں تک کہ سورہ بقرۃ کی آیت: ’’اور تم جہاں کہیں بھی ہو اپنے رخ کعبہ کی طرف کرو۔‘‘ اتری۔ یہ آیت اس وقت اتری جب نبی صلی اللہ علیہ وسلم نماز پڑھ چکے تھے۔ لوگوں میں سے ایک آدمی (یہ حکم سن) چلا تو انصار کے کچھ لوگوں کے پاس سے گزرا، وہ (مسجد بنی حارثہ میں، جس کا نام اس واقعے کے بعد مسجد قبلتین پڑ گیا) نماز پڑھ رہے تھے، اس نے انہیں یہ (حکم) بتایا تو انہوں نے (اثنائے نماز ہی میں) اپنے چہرے بیت اللہ کی طرف کر لیے۔"}],[1109,"سفیان ( ثوری ) سے روایت ہے ، کہا : مجھے ابو اسحاق نے حدیث سنائی ، کہا : میں نے سیدنا براء رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سولہ یا سترہ ماہ بیت المقدس کی طرف رخ کر کے نماز پڑھی ، پھر ہمارا رخ کعبہ کی طرف پھیر دیا گیا ۔","",{"u2":"سفیان (ثوری) سے روایت ہے، کہا: مجھے ابو اسحاق نے حدیث سنائی، کہا: میں نے سیدنا براء رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سولہ یا سترہ ماہ بیت المقدس کی طرف رخ کر کے نماز پڑھی، پھر ہمارا رخ کعبہ کی طرف پھیر دیا گیا۔"}],[1110,"۔ عبد العزیز بن مسلم اور مالک بن انس نے اپنی اپنی سندوں سے عبد اللہ بن دینار سے روایت کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : لوگ قباء میں صبح کی نماز پڑھ رہے تھے ، اسی اثناء میں ان کے پاس آنے والا ایک شخص ( عباد بن بشر رضی اللہ عنہ ) آیا اور اس نے کہا : بلاشبہ رات ( گزشتہ دن کے آخری حصے میں ) رسول اللہ صلی اللہ علیہ وسلم پر قرآن اترا ۔ اور آپ کو حکم دیا گیا کہ آپ کعبہ کی طرف رخ کریں ، لہٰذا تم لوگ بھی اس کی طرف رخ کر لو ۔ ان کے رخ شام کی طرف تھے تو ( اسی وقت ) وہ سب کعبہ کی طرف گھوم گئے ۔ 1179 ۔ موسیٰ بن عقبہ نے نافع اور عبد اللہ بن دینار سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : لوگ صبح کی نماز پڑھ رہے تھے ، ان کے پاس ایک آدمی آیا .... باقی حدیث امام مالک کی ( سابقہ ) روایت کی طرح ہے ۔"],[1111,"۔ عبد العزیز بن مسلم اور مالک بن انس نے اپنی اپنی سندوں سے عبد اللہ بن دینار سے روایت کی ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : لوگ قباء میں صبح کی نماز پڑھ رہے تھے ، اسی اثناء میں ان کے پاس آنے والا ایک شخص ( عباد بن بشر رضی اللہ عنہ ) آیا اور اس نے کہا : بلاشبہ رات ( گزشتہ دن کے آخری حصے میں ) رسول اللہ صلی اللہ علیہ وسلم پر قرآن اترا ۔ اور آپ کو حکم دیا گیا کہ آپ کعبہ کی طرف رخ کریں ، لہٰذا تم لوگ بھی اس کی طرف رخ کر لو ۔ ان کے رخ شام کی طرف تھے تو ( اسی وقت ) وہ سب کعبہ کی طرف گھوم گئے ۔ 1179 ۔ موسیٰ بن عقبہ نے نافع اور عبد اللہ بن دینار سے اور انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی ، انہوں نے کہا : لوگ صبح کی نماز پڑھ رہے تھے ، ان کے پاس ایک آدمی آیا .... باقی حدیث امام مالک کی ( سابقہ ) روایت کی طرح ہے ۔",""],[1112,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیت المقدس کی طرف منہ کر کے نماز پڑھا کرتے تھے ، پھر یہ آیت : ’’ ہم آپ کا چہرہ آسمان کی طرف پھرتا ہوا دیکھ رہے ہیں ، ہم ضرور آپ کا رخ اس قبلے کی طرف پھیر دیں گے جسے آپ پسند کرتے ہیں ، لہٰذا آپ اپنا چہرہ مسجد حرام کی طرف پھیر لیجئے ۔ ‘‘ بنو سلمہ کا ایک آدمی ( عباد بن بشر رضی اللہ عنہ ) گزرا ، ( اس وقت ) لوگ ( مسجد قباء میں ) صبح کی نماز میں رکوع کر رہے تھے اور ایک رکعت اس سے پہلے پڑھ چکے تھے ، اس نے آواز دی : سنو! قبلہ تبدیل کیا جا چکا ہے ۔ چنانچہ وہ جس حالت میں تھے اسی میں ( رکوع ہی کے عالم میں ) قبلے کی طرف پھر گئے ۔","",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیت المقدس کی طرف منہ کر کے نماز پڑھا کرتے تھے، پھر یہ آیت: ’’ ہم آپ کا چہرہ آسمان کی طرف پھرتا ہوا دیکھ رہے ہیں، ہم ضرور آپ کا رخ اس قبلے کی طرف پھیر دیں گے جسے آپ پسند کرتے ہیں، لہٰذا آپ اپنا چہرہ مسجد حرام کی طرف پھیر لیجئے۔ ‘‘ بنو سلمہ کا ایک آدمی (عباد بن بشر رضی اللہ عنہ) گزرا، (اس وقت) لوگ (مسجد قباء میں) صبح کی نماز میں رکوع کر رہے تھے اور ایک رکعت اس سے پہلے پڑھ چکے تھے، اس نے آواز دی: سنو! قبلہ تبدیل کیا جا چکا ہے۔ چنانچہ وہ جس حالت میں تھے اسی میں (رکوع ہی کے عالم میں) قبلے کی طرف پھر گئے۔"}],[1113,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیت المقدس کی طرف منہ کر کے نماز پڑھا کرتے تھے ، پھر یہ آیت : ’’ ہم آپ کا چہرہ آسمان کی طرف پھرتا ہوا دیکھ رہے ہیں ، ہم ضرور آپ کا رخ اس قبلے کی طرف پھیر دیں گے جسے آپ پسند کرتے ہیں ، لہٰذا آپ اپنا چہرہ مسجد حرام کی طرف پھیر لیجئے ۔ ‘‘ بنو سلمہ کا ایک آدمی ( عباد بن بشر رضی اللہ عنہ ) گزرا ، ( اس وقت ) لوگ ( مسجد قباء میں ) صبح کی نماز میں رکوع کر رہے تھے اور ایک رکعت اس سے پہلے پڑھ چکے تھے ، اس نے آواز دی : سنو! قبلہ تبدیل کیا جا چکا ہے ۔ چنانچہ وہ جس حالت میں تھے اسی میں ( رکوع ہی کے عالم میں ) قبلے کی طرف پھر گئے ۔","",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیت المقدس کی طرف منہ کر کے نماز پڑھا کرتے تھے، پھر یہ آیت: ’’ ہم آپ کا چہرہ آسمان کی طرف پھرتا ہوا دیکھ رہے ہیں، ہم ضرور آپ کا رخ اس قبلے کی طرف پھیر دیں گے جسے آپ پسند کرتے ہیں، لہٰذا آپ اپنا چہرہ مسجد حرام کی طرف پھیر لیجئے۔ ‘‘ بنو سلمہ کا ایک آدمی (عباد بن بشر رضی اللہ عنہ) گزرا، (اس وقت) لوگ (مسجد قباء میں) صبح کی نماز میں رکوع کر رہے تھے اور ایک رکعت اس سے پہلے پڑھ چکے تھے، اس نے آواز دی: سنو! قبلہ تبدیل کیا جا چکا ہے۔ چنانچہ وہ جس حالت میں تھے اسی میں (رکوع ہی کے عالم میں) قبلے کی طرف پھر گئے۔"}],[1114,"۔ یحییٰ بن سعید قطان نے حدیث بیان کی ، کہا : ہمیں ہشام نے حدیث سنائی ، کہا : مجھے میرے والد ( عروہ ) نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی کہ ام حبیبہ اور ام سلمہ رضی اللہ عنہما نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے اس گرجے کا تذکرہ ، جو انہوں نے حبشہ میں دیکھا تھا اور اس میں تصویریں آویزاں تھیں ، کہا : ’’بلاشبہ وہ لوگ ( قدیم سے ایسے ہی تھے کہ ) جب ان میں کوئی نیک آدمی فوت ہو جاتا تو وہ اس کی قبر پر مسجد بنا دیتے اور اس میں یہ تصویریں بنا دیتے ۔ یہ لوگ قیامت کے روز اللہ عزوجل کے نزدیک بدترین مخلوق ہوں گے ۔ ‘‘","",{"u2":"۔ یحییٰ بن سعید قطان نے حدیث بیان کی، کہا: ہمیں ہشام نے حدیث سنائی، کہا: مجھے میرے والد (عروہ) نے سیدہ عائشہ رضی اللہ عنہا سے خبر دی کہ ام حبیبہ اور ام سلمہ رضی اللہ عنہما نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے اس گرجے کا تذکرہ، جو انہوں نے حبشہ میں دیکھا تھا اور اس میں تصویریں آویزاں تھیں، کہا: ’’بلاشبہ وہ لوگ (قدیم سے ایسے ہی تھے کہ) جب ان میں کوئی نیک آدمی فوت ہو جاتا تو وہ اس کی قبر پر مسجد بنا دیتے اور اس میں یہ تصویریں بنا دیتے۔ یہ لوگ قیامت کے روز اللہ عزوجل کے نزدیک بدترین مخلوق ہوں گے۔‘‘"}],[1115,"۔ وکیع نے کہا : ہمیں ہشام بن عروہ نے اپنے والد عروہ کے حوالے سے سیدہ عائشہ رضی اللہ عنہا سے حدیث روایت کی کہ آپ کے مرض الموت میں لوگوں نے آپ کے سامنے آپس میں بات چیت کی تو ام سلمہ اور ام حبیبہ رضی اللہ عنہما نے ایک گرجے کا ذکر کیا ..... پھر اسی کے مانند بیان کیا","",{"u2":"۔ وکیع نے کہا: ہمیں ہشام بن عروہ نے اپنے والد عروہ کے حوالے سے سیدہ عائشہ رضی اللہ عنہا سے حدیث روایت کی کہ آپ کے مرض الموت میں لوگوں نے آپ کے سامنے آپس میں بات چیت کی تو ام سلمہ اور ام حبیبہ رضی اللہ عنہما نے ایک گرجے کا ذکر کیا ..... پھر اسی کے مانند بیان کیا"}],[1116,"۔ ( یحییٰ اور وکیع کے بجائے ) ابو معاویہ نے کہا : ہمیں ہشام نے اپنے والد سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے حدیث سنائی ، انہوں نے کہا : ازواج نبی صلی اللہ علیہ وسلم نے ایک کنیسے کا ذکر کیا جو انہوں نے حبشہ کی سرزمین میں دیکھا تھا ، اسے ( کنیسۂ ) ماریہ کہا جاتا تھا .... ( آگے ) ان ( پہلے راویوں ) کی حدیث کی طرح ہے ۔","",{"u2":"۔ (یحییٰ اور وکیع کے بجائے) ابو معاویہ نے کہا: ہمیں ہشام نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے حدیث سنائی، انہوں نے کہا: ازواج نبی صلی اللہ علیہ وسلم نے ایک کنیسے کا ذکر کیا جو انہوں نے حبشہ کی سرزمین میں دیکھا تھا، اسے (کنیسۂ) ماریہ کہا جاتا تھا .... (آگے) ان (پہلے راویوں) کی حدیث کی طرح ہے۔"}],[1117,"۔ ابوبکر ابی شیبہ او رعمرو ناقد نے کہا : ہم سے ہاشم بن قاسم نے حدیث بیان کی ، انہوں نے کہا : ہمیں شیبان نے ہلال بن ابی حمید سے حدیث سنائی ، انہوں نے عروہ بن زبیر سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے اپنی اس بیماری میں جس سے آپ اٹھ نہ سکے ( جاں بر نہ ہوئے ) فرمایا : ’’ اللہ تعالیٰ یہود اور نصاریٰ پر لعنت کرے! انہوں نے اپنے انبیاء کی قبروں کو مسجدیں بنا لیا ۔ ‘‘ سیدہ عائشہ رضی اللہ عنہا نے ) کہا : اس لیے اگر یہ اندیشہ نہ ہوتا تو آپ کی قبر کو ظاہر رکھا جاتا لیکن یہ ڈر تھا کہ اسے مسجد بنا لیا جائے گا ۔ ( اس لیے اللہ کی مشیت سے وہ حجرہ مبارکہ میں بنائی گئی ۔ ) ابن ابی شیبہ کی روایت میں فلو لا کی جگہ ولو لا ( اور اگر ) کے الفاظ ہیں اور اس سے پہلے قالت ( انہوں نے کہا ) کا لفظ نہیں کہا","",{"u2":"۔ ابوبکر ابی شیبہ او رعمرو ناقد نے کہا: ہم سے ہاشم بن قاسم نے حدیث بیان کی، انہوں نے کہا: ہمیں شیبان نے ہلال بن ابی حمید سے حدیث سنائی، انہوں نے عروہ بن زبیر سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اپنی اس بیماری میں جس سے آپ اٹھ نہ سکے (جاں بر نہ ہوئے) فرمایا: ’’ اللہ تعالیٰ یہود اور نصاریٰ پر لعنت کرے! انہوں نے اپنے انبیاء کی قبروں کو مسجدیں بنا لیا۔‘‘\nسیدہ عائشہ رضی اللہ عنہا نے) کہا: اس لیے اگر یہ اندیشہ نہ ہوتا تو آپ کی قبر کو ظاہر رکھا جاتا لیکن یہ ڈر تھا کہ اسے مسجد بنا لیا جائے گا۔ (اس لیے اللہ کی مشیت سے وہ حجرہ مبارکہ میں بنائی گئی۔)\nابن ابی شیبہ کی روایت میں فلو لا کی جگہ ولو لا (اور اگر) کے الفاظ ہیں اور اس سے پہلے قالت (انہوں نے کہا) کا لفظ نہیں کہا"}],[1118,"سعید بن مسیب نے حدیث بیان کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اللہ یہود کو ہلاک کرے! انہوں نے اپنے انبیاء کی قبروں کو سجدہ گاہ بنا لیا ۔ ‘‘","",{"u2":"سعید بن مسیب نے حدیث بیان کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اللہ یہود کو ہلاک کرے! انہوں نے اپنے انبیاء کی قبروں کو سجدہ گاہ بنا لیا۔‘‘"}],[1119,"(سعید کے بجائے ) یزید بن اصم نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اللہ یہود ونصاریٰ پر لعنت کرے! انہوں نے اپنے انبیاء کی قبروں کو مسجدیں بنا لیا ۔ ‘‘","",{"u2":"(سعید کے بجائے) یزید بن اصم نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اللہ یہود ونصاریٰ پر لعنت کرے! انہوں نے اپنے انبیاء کی قبروں کو مسجدیں بنا لیا۔‘‘"}],[1120,"۔ عبید اللہ بن عبد اللہ ( بن مسعود ) نے خبر دی کہ سیدہ عائشہ اور سیدنا عبد اللہ بن عباس رضی اللہ عنہ دونوں نے کہا کہ جب رسول اللہ صلی اللہ علیہ وسلم پر ( وفات کے لمحے ) طاری ہوئے تو آپ اپنی ایک چادر اپنے چہرے پر ڈالتے تھے اور جب جی گھبراتا تو اسے چہرے سے ہٹا لیتے تھے ، آپ اسی حالت میں تھے کہ آپ نے فرمایا : ’’ یہود ونصاریٰ پر اللہ کی لعنت ہو! انہوں نے اپنے انبیاء کی قبروں کو مساجد بنا لیا ۔ ‘‘ آپ ان جیسا عمل کرنے سے ڈرا رہے تھے ۔","",{"u2":"۔ عبید اللہ بن عبد اللہ (بن مسعود) نے خبر دی کہ حضرت عائشہ اور حضرت عبد اللہ بن عباس رضی اللہ عنہما دونوں نے کہا کہ جب رسول اللہ صلی اللہ علیہ وسلم پر (وفات کے لمحے) طاری ہوئے تو آپ اپنی ایک چادر اپنےچہرے پر ڈالتے تھے اور جب جی گھبراتا تو اسے چہرے سے ہٹا لیتے تھے، آپ اسی حالت میں تھے کہ آپ نے فرمایا: ’’ یہود ونصاریٰ پر اللہ کی لعنت ہو! انہوں نے اپنے انبیاء کی قبروں کو مساجد بنا لیا۔‘‘ آپ ان جیسا عمل کرنے سے ڈرا رہے تھے۔"}],[1121,"۔ سیدنا جندب رضی اللہ عنہ نے کہا : میں نے نبی صلی اللہ علیہ وسلم کو آپ کی وفات سے پانچ دن پہلے یہ کہتے ہوئے سنا : ’’ میں اللہ تعالیٰ کے حضور اس چیز سے براءت کا اظہار کرتا ہوں کہ تم میں سے کوئی میرا خلیل ہو کیونکہ اللہ تعالیٰ نے مجھے اپنا خلیل بنا لیا ہے ، جس طرح اس نے ابراہیم علیہ السلام کو اپنا خلیل بنایا تھا ، اگر میں اپنی امت میں سے کسی کو اپنا خلیل بناتا تو ابو بکر کو خلیل بناتا ، خبردار! تم سے پہلے لوگ اپنے انبیاء اور نیک لوگوں کی قبروں کو سجدہ گاہیں بنا لیا کرتے تھے ، خبردار! تم قبروں کو سجدہ گاہیں نہ بنانا ، میں تم کو اس سے روکتا ہوں ۔ ‘‘","",{"u2":"۔ سیدنا جندب رضی اللہ عنہ نے کہا: میں نے نبی صلی اللہ علیہ وسلم کو آپ کی وفات سے پانچ دن پہلے یہ کہتے ہوئے سنا: ’’ میں اللہ تعالیٰ کے حضور اس چیز سے براءت کا اظہار کرتا ہوں کہ تم میں سے کوئی میرا خلیل ہو کیونکہ اللہ تعالیٰ نے مجھے اپنا خلیل بنا لیا ہے، جس طرح اس نے ابراہیم علیہ السلام کو اپنا خلیل بنایا تھا، اگر میں اپنی امت میں سے کسی کو اپنا خلیل بناتا تو ابو بکر کو خلیل بناتا، خبردار! تم سے پہلے لوگ اپنے انبیاء اور نیک لوگوں کی قبروں کو سجدہ گاہیں بنا لیا کرتے تھے، خبردار! تم قبروں کو سجدہ گاہیں نہ بنانا، میں تم کو اس سے روکتا ہوں۔‘‘"}],[1122,"۔ ہارون بن سعید ایلی اور احمد بن عیسیٰ دونوں نے ہمیں حدیث بیان کی ۔ ( کہا : ) ہم سے ابن وہب نے حدیث بیان کی ، انہوں نے کہا : مجھے عمرو نے خبر دی کہ بکیر نے ان سے حدیث بیان کی ، انہیں عاصم بن عمر بن قتادہ نے حدیث بیان کی کہ انہوں نے عبید اللہ خولانی سے سنا ، وہ بیان کر رہے تھے کہ انہوں نے سیدنا عثمان بن عفان رضی اللہ عنہ کو ، جب رسول اللہ صلی اللہ علیہ وسلم کی مسجد کی نئے سے سے تعمیر کے وقت لوگوں نے ان کے بارے میں باتیں کیں ، یہ کہتے سنا : تم نے بہت بتایں کی ہیں ، حالانکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا تھا : ’’جس نے اللہ کے لیے مسجد بنائی ‘‘ بکیر نے کہا : میرا خیال ہے ، انہوں نے یہ کہا : ’’ اس سے وہ اللہ تعالیٰ کی رضا اور خوشنودی چاہتا ہے تو اللہ اس کے لیے جنت میں گھر بنائے گا ۔ ‘‘ احمد بن عیسیٰ نے اپنی روایت میں مثله في الجنة ’’جنت میں اس جیسا ( گھر ) ‘‘ کہا ۔","",{"u2":"۔ ہارون بن سعید ایلی اور احمد بن عیسیٰ دونوں نے ہمیں حدیث بیان کی۔ (کہا:) ہم سے ابن وہب نے حدیث بیان کی، انہوں نے کہا: مجھے عمرو نے خبر دی کہ بکیر نے ان سے حدیث بیان کی، انہیں عاصم بن عمر بن قتادہ نے حدیث بیان کی کہ انہوں نے عبید اللہ خولانی سے سنا، وہ بیان کر رہے تھے کہ انہوں نے سیدنا عثمان بن عفان رضی اللہ عنہ کو، جب رسول اللہ صلی اللہ علیہ وسلم کی مسجد کی نئے سے سے تعمیر کے وقت لوگوں نے ان کے بارے میں باتیں کیں، یہ کہتے سنا: تم نے بہت بتایں کی ہیں، حالانکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا تھا: ’’جس نے اللہ کے لیے مسجد بنائی‘‘ بکیر نے کہا: میرا خیال ہے، انہوں نے یہ کہا: ’’ اس سے وہ اللہ تعالیٰ کی رضا اور خوشنودی چاہتا ہے تو اللہ اس کے لیے جنت میں گھر بنائے گا۔‘‘\nاحمد بن عیسیٰ نے اپنی روایت میں مثلہ فی الجنۃ ’’جنت میں اس جیسا (گھر)‘‘ کہا۔"}],[1123,"سیدنا محمود بن لبید رضی اللہ عنہ سے روایت ہے کہ سیدنا عثمان بن عفان رضی اللہ عنہ نے مسجد نبوی کو نئے سرے سے تعمیر کرنا چاہا تو لوگوں نے اسے پسند نہ کیا ، ان کی خواہش تھی کہ وہ اسے اس کی حالت پر رہنے دیں ، اس پر سیدنا عثمان رضی اللہ عنہ نے فرمایا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ’’ جس شخص نے اللہ کی خاطر کوئی مسجد بنائی ، اللہ اس کے لیے جنت میں اس جیسا ( گھر ) تعمیر کر ے گا ۔ ‘‘","",{"u2":"سیدنا محمود بن لبید رضی اللہ عنہ سے روایت ہے کہ سیدنا عثمان بن عفان رضی اللہ عنہ نے مسجد نبوی کو نئے سرے سے تعمیر کرنا چاہا تو لوگوں نے اسے پسند نہ کیا، ان کی خواہش تھی کہ وہ اسے اس کی حالت پر رہنے دیں، اس پر سیدنا عثمان رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’ جس شخص نے اللہ کی خاطر کوئی مسجد بنائی، اللہ اس کے لیے جنت میں اس جیسا (گھر) تعمیر کر ے گا۔‘‘"}],[1124,"ابو معاویہ نے ہمیں اعمش سے حدیث بیان کی ، انہوں نے ابراہیم سے اور انہوں نے اسود اور علقمہ سے روایت کی ، ان دونوں نے کہا : ہم عبد اللہ بن مسعود رضی اللہ عنہ کے گھر ان کی خدمت میں حاضر ہوئے تو وہ پوچھنے لگے : جو ( حکمران اور ان کے ساتھ تاخیر سے نماز پڑھنے والے ان کے پیروکار ) تم سے پیچھے ہیں ، انہوں نے نماز پڑھ لی ہے؟ ہم نے عرض کی : نہیں ۔ انہوں نے کہا : اٹھو اور نماز پڑھو ۔ انہوں نے ہمیں اذان اور اقامت کہنے کا حکم نہ دیا ہم ان کے پیچھے کھڑے ہونے لگے تو انہوں نے ہمارے ہاتھ پکڑ کر ایک کو اپنے دائیں اور دوسرے کو اپنے بائیں طرف کر دیا ۔ جب انہوں نے رکوع کیا تو ہم نے اپنے ہاتھ اپنے گھٹنوں پر رکھے ، انہوں نے ہمارے ہاتھوں پر ہلکا سا مارا اور اپنی دونوں ہتھیلیوں کو جوڑ کر اپنی دونوں رانوں کے درمیان رکھ لیا ۔ انہوں نے جب نماز پڑھ لی تو کہا : یقیناً آیندہ تمہارے ایسے حکمران ہوں گے جو نمازوں کو ان کے اوقات سے مؤخر کر یں گے اور ان کے اوقات کو مرنے والوں کو آخری جھلملاہٹ کی طرح تنگ کر دیں گے ۔ جب تم ان کو دیکھو کہ انہوں نے یہ ( کام شروع ) کر لیا ہے تو تم ( ہر ) نماز اس وقت کے پر پڑھ لینا اور ان کے ساتھ اپنی نماز کو نفل بنا لینا ۔ اور جب تم تین آدمی ہو تو اکٹھے کھڑے ہو کر نماز پڑھو اور جب تم تین زیادہ ہو تو تم میں سے ایک امام بن جائے اور جب تم میں سے کوئی رکوع کرے تو اپنے بازو اپنی رانوں پر پھیلا دے اور جھکے اور اپنی ہتھیلیاں جوڑ لے ، ( ایسا لگتا ہے ) جیسے میں ( اب بھی ) رسول اللہ صلی اللہ علیہ وسلم کی ( ایک دوسری میں ) پیوستہ انگلیوں کو دیکھ رہا ہوں ۔ اور ( انگلیاں پیوست کر کے ) انہیں دکھائیں ۔","",{"u2":"ابو معاویہ نے ہمیں اعمش سے حدیث بیان کی، انہوں نے ابراہیم سے اور انہوں نے اسود اور علقمہ سے روایت کی، ان دونوں نے کہا: ہم عبد اللہ بن مسعود رضی اللہ عنہ کے گھر ان کی خدمت میں حاضر ہوئے تو وہ پوچھنے لگے: جو (حکمران اور ان کے ساتھ تاخیر سے نماز پڑھنے والے ان کے پیروکار) تم سے پیچھے ہیں، انہوں نے نماز پڑھ لی ہے؟ ہم نے عرض کی: نہیں۔ انہوں نے کہا: اٹھو اور نماز پڑھو۔ انہوں نے ہمیں اذان اور اقامت کہنے کا حکم نہ دیا ہم ان کے پیچھے کھڑے ہونے لگے تو انہوں نے ہمارے ہاتھ پکڑ کر ایک کو اپنے دائیں اور دوسرے کو اپنے بائیں طرف کر دیا۔ جب انہوں نے رکوع کیا تو ہم نے اپنے ہاتھ اپنے گھٹنوں پر رکھے، انہوں نے ہمارے ہاتھوں پر ہلکا سا مارا اور اپنی دونوں ہتھیلیوں کو جوڑ کر اپنی دونوں رانوں کے درمیان رکھ لیا۔ انہوں نے جب نماز پڑھ لی تو کہا: یقیناً آیندہ تمہارے ایسے حکمران ہوں گے جو نمازوں کو ان کے اوقات سے مؤخر کر یں گے اور ان کے اوقات کو مرنے والوں کو آخری جھلملاہٹ کی طرح تنگ کر دیں گے۔ جب تم ان کو دیکھو کہ انہوں نے یہ (کام شروع) کر لیا ہے تو تم (ہر) نماز اس وقت کے پر پڑھ لینا اور ان کے ساتھ اپنی نماز کو نفل بنا لینا۔ اور جب تم تین آدمی ہو تو اکٹھے کھڑے ہو کر نماز پڑھو اور جب تم تین زیادہ ہو تو تم میں سے ایک امام بن جائے اور جب تم میں سے کوئی رکوع کرے تو اپنے بازو اپنی رانوں پر پھیلا دے اور جھکے اور اپنی ہتھیلیاں جوڑ لے، (ایسا لگتا ہے) جیسے میں (اب بھی) رسول اللہ صلی اللہ علیہ وسلم کی (ایک دوسری میں) پیوستہ انگلیوں کو دیکھ رہا ہوں۔ اور (انگلیاں پیوست کر کے) انہیں دکھائیں۔"}],[1125,"یہ روایت بھی ایك دوسری سند سے اسی طرح مروی ہے سوا‎ئے ان الفاظ كے وَهُوَ رَاكِعٌ ‏.‏"],[1126,"۔ ( اعمش ےکے بجائے ) منصور ابراھیم سے اور انھوں نے علقمہ اور اسود سے روایت کی کہ وہ دونوں سیدنا عبد اللہ ( بن مسعود رضی اللہ عنہ ) کے ہاں حاضر ہوئے تو انھوں نے پوچھا : جو تمہارے پیچھے ہیں انھوں نے نماز پڑھ لی ؟دونوں نے کہا : جی ہاں ۔ پھر وہ دونوں کے درمیان کھڑے ہوئے ‘ ان میں سے ایک کو اپنی دائیں طرف اور دوسرے کو اپنی بائیں طرف ( کھڑا ) کیا پھر ہم نے رکوع کیا تو ہم اپنے ہاتھ اپنے گٹھنوں پر رکھے ‘ انھو ں نے ہمارے ہاتھوں پر ( ہلکا سا ) مارا ‘ پھر اپنے دونوں ہاتھ جوڑ لیے اور ان کو اپنی رانوں کے درمیان رکھا ‘ جب نماز پڑھ چکے تو کہا : رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح کیا ۔","",{"u2":"۔(اعمش ےکے بجائے)منصور ابراھیم سے اور انھوں نے علقمہ اور اسود سے روایت کی کہ وہ دونوں حضرت عبد اللہ (بن مسعود رضی اللہ عنہ)کے ہاں حاضر ہوئے تو انھوں نے پوچھا:جو تمہارے پیچھے ہیں انھوں نے نماز پڑھ لی؟دونوں نے کہا:جی ہاں۔ پھر وہ دونوں کے درمیان کھڑے ہوئے ‘ان میں سےایک کو اپنی دائیں طرف اور دوسرے کو اپنی بائیں طرف(کھڑا)کیا پھر ہم نےرکوع کیاتو ہم اپنے ہاتھ اپنے گٹھنوں پر رکھے‘انھو ں نے ہمارے ہاتھوں پر (ہلکا سا)مارا‘پھر اپنے دونوں ہاتھ جوڑ لیے اور ان کو اپنی رانوں کے درمیان رکھا ‘جب نماز پڑھ چکے تو کہا:رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح کیا۔"}],[1127,"میں غالباً ابراھیم نخعی سے نیچے کسی راوی کو وہم ہوا ہے ۔ اسی لیے امام مسلم رضی اللہ عنہ مفصل اور صحیح روایت کو پہلے لائے ہیں ۔ بعض شارحین نے اسے متعدد واقعات پر بھی محمول کیا ہے ۔ واللہ اعلم بالصواب","",{"u2":"1193میں غالباً ابراھیم نخعی سے نیچے کسی راوی کو وہم ہوا ہے۔اسی لیے امام مسلم رحمہ اللہ مفصل اور صحیح روایت کو پہلے لائے ہیں۔بعض شارحین نے اسے متعدد واقعات پر بھی محمول کیا ہے۔ واللہ اعلم بالصواب ."}],[1128,"ابو عوانہ نے ابو یعفور سے اور انھوں نے مصعب بن سعد سے روایت کی ‘ انھوں نے کہا : میں نے اپنے والد ( سعد بن ابی وقاص رضی اللہ عنہ ) کے پہلو میں نماز پڑھی اور اپنے دونوں ہاتھ اپنے گٹھنوں کے درمیان رکھے تو مجھے میرے والد نے کہا : اپنی دونوں ہتھیلیاں اپنے گٹھنوں پر رکھو ۔ انھوں ( مصعب ) نے کہا : میں نے دوبارہ یہی کام کیا تو انہوں میرے ہاتھوں پر مارا اور کہا : ہمیں اس سے روک دیا گیا تھا اور حکم دیا گیا تھا کہ ہم ہتھیلیاں گٹھنوں پر ٹکائیں ۔","",{"u2":"ابو عوانہ نے ابو یعفور سے اور انھوں نے مصعب بن سعد سے روایت کی ‘انھوں نے کہا:میں نےاپنے والد (سعد بن ابی وقاص رضی اللہ عنہ) کے پہلو میں نماز پڑھی اور اپنے دونوں ہاتھ اپنے گٹھنوں کے درمیان رکھے تو مجھے میرے والد نے کہا:اپنی دونوں ہتھیلیاں اپنے گٹھنوں پر رکھو۔انھوں (مصعب)نے کہا:میں نے دوبارہ یہی کام کیا تو انہوں میرے ہاتھوں پر مارا اور کہا:ہمیں اس سے روک دیا گیا تھا اور حکم دیا گیا تھا کہ ہم ہتھیلیاں گٹھنوں پر ٹکائیں۔"}],[1129,"ابو احوص اور سفیان نے ابو یعفور سے مذکورہ بالاسند کے ساتھ’’ہمیں روک دیا گیا ‘‘ تک حدیث بیان کی ہے ‘ ان دونوں نے اس کے بعد والا جملہ بیان نہیں کیا ۔","",{"u2":"ابو احوص اورسفیان نے ابو یعفور سے مذکورہ بالاسند کے ساتھ’’ہمیں روک دیا گیا ‘‘تک حدیث بیان کی ہے ‘ان دونوں نے اس کے بعد والا جملہ بیان نہیں کیا۔"}],[1130,"وکیع نے اسماعیل بن ابی خالد سے ‘ انھوں نے زبیر بن عدی سے اور انھوں نے مصعب بن سعد سے روایت کی ‘ کہا : میں نے رکوع کیا اور اپنے ہاتھوں کو اس طرح کر لیا ‘ یعنی ان کو جوڑکر اپنی رانوں کے درمیان رکھ لیا تو میرے والد نے مجھ سے کہا : ہم اسی طرح کیا کرتے تھے ‘ پھر ہمیں گھنٹوں ( پر ہاتھ رکھنے ) کا حکم دیا گیا ۔","",{"u2":"وکیع نے اسماعیل بن ابی خالد سے ‘انھوں نے زبیر بن عدی سے اور انھوں نے مصعب بن سعد سے روایت کی ‘کہا:میں نے رکوع کیا اور اپنے ہاتھوں کو اس طرح کر لیا‘یعنی ان کو جوڑکر اپنی رانوں کے درمیان رکھ لیا تو میرے والد نے مجھ سے کہا:ہم اسی طرح کیا کرتے تھے ‘پھر ہمیں گھنٹوں (پرہاتھ رکھنے)کا حکم دیا گیا۔"}],[1131,"سیدنا طاوس بیان کرتے ہیں کہ ہم نے ابن عباس رضی اللہ عنھماسےدونوں پیروں پر بیٹھنے کے بارے میں پو چھا تو انھوں نے جواب دیا : یہ سنت ہے ۔ ہم نے ان سے عرض کی : ہمارا تو خیال ہے کہ یہ انسان ( یا اگر را کی زیر کے ساتھ رجل پڑھا جائے تو پاؤں ) پرزیاتی ہے ۔ ابن عباس صلی اللہ علیہ وسلم نے کہا : ( نہیں ) بلکہ یہ تمہارے بنی صلی اللہ علیہ وسلم کی سنت ہے ۔","",{"u2":"حضرت طاوس بیان کرتے ہیں کہ ہم نے ابن عباس رضی اللہ عنھماسےدونوں پیروں پربیٹھنے کے بارے میں پو چھا تو انھوں نے جواب دیا:یہ سنت ہے۔ہم نے ان سے عرض کی:ہمارا تو خیال ہے کہ یہ انسان (یا اگر را کی زیرکے ساتھ رجل پڑھا جائے تو پاؤں)پرزیاتی ہے۔ابن عباس صلی اللہ علیہ وسلم نے کہا:(نہیں)بلکہ یہ تمہارے بنی صلی اللہ علیہ وسلم کی سنت ہے۔"}],[1132,"ہم سے ابو جعفر محمد بن صباح اور ابو بکر بن ابی شیبہ نے حدیث بیان کی ۔ حدیث کے لفظوں میں بھی دونوں ایک دوسرے کے قریب ہیں ۔ دونوں نے کہا : ہم سے اسماعیل بن ابراہیم نے حدیث بیان کی ‘ انھوں نے حجاج صوّاف سے انھوں نے یحییٰ بن ابی کثیر سے ‘ انھوں نے ہلال بن ابی میمونہ سے ‘ انھوں نے عطاء بن یسار سے اور انھوں نے سیدنا معاویہ بن ابی حکم سلمی رضی اللہ عنہ سے روایت کی انھوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑ ھ رہاتھا کہ لوگوں میں سے ایک آدمی کو چھینک آئی تو میں نے کہا : یرحمک اللہ’’اللہ تجھ پر رحم کرے ۔ ‘‘ لوگوں نے مجھے گھورنا شروع کر دیا ۔ میں نے ( دل میں ) کہا : میری ماں مجھے گم پائے ‘ تم سب کو کیا ہو گیا؟ کہ مجھے گھور رہے ہو پھروہ اپنے ہاتھ اپنی رانوں پر مارنے لگے ۔ جب میں نے انھیں دیکھا کہ وہ مجھے چپ کرا رہے ہیں ( تو مجھے عجیب لگا ) لیکن میں خاموش رہا ‘ جب رسول اللہ نماز سے فارغ ہوئے ‘ میرے ماں باپ آپ پر قربان !میں نے آپ سے پہلے اور آپکے بعدآپ سے بہتر کوئی معلم ( سکھانےوالا ) نہیں دیکھا!اللہ کی قسم !نہ تو آپنے مجھے ڈانٹا ‘ نہ مجھے مارا اور نہ مجھے برا بھلا کہا ۔ آپنے فرمایا : ’’یہ نماز ہے اس میں کسی قسم کی گفتگو روانہیں ہے ‘ یہ تو بس تسبیح و تکبیر اور قرآن کی تلاوت ہے ۔ ‘‘ یا جیسے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ میں نے عرض کی اے اللہ کے رسول اللہ !ابھی تھوڑا عرصہ پہلے جاہلیت میں تھا ‘ اور اللہ نے اسلام سے نوازدیا ہے ‘ ہم میں سے کچھ لوگ ہیں جو کاہنوں ( پیش گوئی کرنے والے ) کے پاس جاتے ہیں ۔ آپنے فرمایا : ’’تم ان کے پاس نہ جانا ۔ ‘‘ میں نے عرض کی : ہم میں سے کچھ لوگ ایسے ہیں جو بدشگونی لیتے ہیں ۔ آپن فرمایا : ’’یہ ایسی بات ہے جو وہ اپنے دلوں میں پاتے ہیں ( ایک طرح کا وہم ہے ) یہ ( وہم ) انھیں ( ان کے ) کسی کام سے نہ روکے ۔ ‘‘ ( محمد ) ابن صباح نے روایت کی : ’’یہ تمہیں کسی صورت ( اپنے کاموں سے ) نہ رزکے ۔ ‘‘ میں نے عرض کی : ہم میں سے کچھ لوگ لکیریں کھینچھنے ہیں ۔ ‘‘ آپنے فرمایا : ’’سابقہ انبیاء میں سے ایک بنی لکیریں کھینچا کرتے تھے تو جس کی لکیریں ان کے موافق ہو جائیں وہ تو صحیح ہو سکتی ہیں ‘‘ ( لیکن اب اس کا جاننا مشکل ہے ۔ ) ( معاویہ بن حکم رضی اللہ عنہ نے ) کہا : میری ایک لونڈی تھی جو احد اور جوانیہ کے اطراف میں میری بکریا چراتی تھی ‘ ایک دن میں اس طرف جاانکلاتو بھیڑیا اس کی بکری لے جا چکا تھا ۔ میں بھی بنی آدم میں سے ایک آدمی ہوں ‘ مجھے بھی اسی طرح افسوس ہوتا ہے جس طرح ان کو ہوتا ہے ( مجھے صبر کرنا چاہیے تھا ) لیکن میں نے اسے زور سے ایک تھپڑجڑدیا اس کے بعد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو اآپنے میری اس حرکت کو میرے لیے بڑی ( غلط ) حرکت قرار دیا ۔ میں نے عرض کی : اے اللہ کے رسول !کیا میں اسے آزادنہ کردوں؟آپ نےفرمایا : ’’اسے میرے پاس لے آؤ ۔ ‘‘ میں اسے لےکر آپ کے پاس حاضر ہوا ، آپ نےاس سے پوچھا : ’’اللہ کہا ں ہے؟ ‘‘ اس نےکہا : آسمان میں ۔ آپ نے پوچھا : ’’میں کون ہوں؟ ‘‘ اس نےکہا : آپ اللہ کے رسول ہیں ۔ تو آپ نے فرمایا : ’’اسے آزاد کردو ، یہ مومنہ ہے","",{"u2":"ہم سے ابو جعفرمحمد بن صباح اور ابو بکر بن ابی شیبہ نے حدیث بیان کی۔حدیث کے لفظوں میں بھی دونوں ایک دوسرے کے قریب ہیں۔دونوں نے کہا:ہم سے اسماعیل بن ابراہیم نے حدیث بیان کی ‘انھوں نے حجاج صوّاف سے انھوں نے یحییٰ بن ابی کثیر سے ‘انھوں نے ہلال بن ابی میمونہ سے ‘انھوں نے عطاء بن یسار سے اور انھوں نے سیدنا معاویہ بن ابی حکم سلمی رضی اللہ عنہ سے روایت کی انھوں نے کہا:میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑ ھ رہاتھا کہ لوگوں میں سے ایک آدمی کو چھینک آئی تو میں نے کہا:یرحمک اللہ’’اللہ تجھ پر رحم کرے۔‘‘لوگوں نے مجھے گھورنا شروع کر دیا۔میں نے (دل میں)کہا:میری ماں مجھے گم پائے ‘تم سب کو کیا ہو گیا؟ کہ مجھے گھور رہے ہو پھروہ اپنے ہاتھ اپنی رانوں پر مارنے لگے۔جب میں نے انھیں دیکھا کہ وہ مجھے چپ کرا رہے ہیں (تو مجھے عجیب لگا)لیکن میں خاموش رہا ‘جب رسو ل اللہ نماز سے فارغ ہوئے ‘میرے ماں باپ آپ پرقربان!میں نے آپ سےپہلے اور آپکے بعدآپ سے بہتر کوئی معلم (سکھانےوالا)نہیں دیکھا!اللہ کی قسم!نہ تو آپنے مجھے ڈانٹا ‘نہ مجھے مارا اور نہ مجھے برا بھلا کہا۔ آپنے فرمایا:’’یہ نماز ہے اس میں کسی قسم کی گفتگو روانہیں ہے ‘یہ تو بس تسبیح و تکبیر اور قرآن کی تلاوت ہے۔‘‘یا جیسے رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا۔میں نے عرض کی اے اللہ کے رسول اللہ!ابھی تھوڑا عرصہ پہلے جاہلیت میں تھا ‘اور اللہ نے اسلام سے نوازدیا ہے ‘ہم میں سے کچھ لوگ ہیں جو کاہنوں (پیش گوئی کرنے والے)کے پاس جاتے ہیں۔آپنے فرمایا:’’تم ان کے پاس نہ جانا۔‘‘میں نے عرض کی:ہم میں سے کچھ لوگ ایسے ہیں جو بدشگونی لیتےہیں۔آپن فرمایا:’’یہ ایسی بات ہے جو وہ اپنے دلوں میں پاتے ہیں (ایک طرح کا وہم ہے)یہ (وہم)انھیں (ان کے)کسی کام سے نہ روکے۔‘‘(محمد)ابن صباح نے روایت کی:’’یہ تمہیں کسی صورت (اپنے کاموں سے) نہ رزکے۔‘‘میں نے عرض کی:ہم میں سے کچھ لوگ لکیریں کھینچھنے ہیں۔‘‘آپنے فرمایا:’’سابقہ انبیاء میں سے ایک بنی لکیریں کھینچا کرتے تھے تو جس کی لکیریں ان کے موافق ہو جائیں وہ تو صحیح ہو سکتی ہیں ‘‘(لیکن اب اس کا جاننا مشکل ہے۔)(معاویہ بن حکم رضی اللہ عنہ نے)کہا:میری ایک لونڈی تھی جو احد اور جوانیہ کے اطراف میں میری بکریا چراتی تھی ‘ایک دن میں اس طرف جاانکلاتو بھیڑیا اس کی بکری لے جا چکا تھا۔میں بھی بنی آدم میں سے ایک آدمی ہوں‘مجھے بھی اسی طرح افسوس ہوتا ہے جس طرح ان کو ہوتا ہے (مجھے صبر کرناچاہیے تھا)لیکن میں نے اسے زور سے ایک تھپڑجڑدیا اس کے بعد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو اآپنے میری اس حرکت کو میرے لیے بڑی (غلط)حرکت قرار دیا۔میں نے عرض کی:اے اللہ کے رسول!کیا میں اسے آزادنہ کردوں؟آپ نےفرمایا:’’اسے میرےپاس لے آؤ۔‘‘ میں اسے لےکر آپ کےپاس حاضر ہوا،آپ نےاس سے پوچھا:’’اللہ کہا ں ہے؟ ‘‘ اس نےکہا: آسمان میں۔ آپ نےپوچھا: ’’میں کون ہوں؟‘‘ اس نےکہا: آپ اللہ کےرسول ہیں۔ تو آپ نے فرمایا:’’اسے آزاد کردو، یہ مومنہ ہے"}],[1133,"اوزاعی نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی ہے ۔","",{"u2":"اوزاعی نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی ہے۔"}],[1134,"ابن فضیل نے ہمیں حدیث بیان کی ، کہا : ہمیں اعمش نے ابراہیم سے حدیث سنائی ، انھوں نے علقمہ سے اور انھوں نے سیدنا عبدااللہ ( بن مسعود ) رضی اللہ تعالی عنہ سے روایت کی ، انھوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کو ، جب آب نماز میں ہوتے تھے سلام کہا کرتے تھے اور آپ ہمار ے سلام کا جواب دیتے تھے جب ہم نجاشی کے ہاں سے واپس آئے ، ہم نے آپ کو ( نماز میں ) سلام کہا تو آپ نے ہمیں جواب نہ دیا ۔ ہم نے عرض کی : اے اللہ کے رسول ! ہم نماز میں آپ کو سلام کہا کرتے تھے اور آ پ ہمیں جواب دیا کرتے تھے ۔ آپ نے فرمایا : ’’ نماز میں ( اس کی اپنی ) مشغولیت ہوتی ہے ۔ ‘‘","",{"u2":"ابن فضیل نے ہمیں حدیث بیان کی،کہا: ہمیں اعمش نے ابراہیم سے حدیث سنائی، انھوں نے علقمہ سے اور انھوں نے حضرت عبدااللہ (بن مسعود)رضی اللہ تعالی عنہ سے روایت کی، انھوں نے کہا:ہم رسول اللہ صلی اللہ علیہ وسلم کو،جب آب نماز میں ہوتے تھے سلام کہا کرتے تھے اور آپ ہمار ے سلام کا جواب دیتے تھے جب ہم نجاشی کے ہاں سے واپس آئے، ہم نے آپ کو (نماز میں)سلام کہا تو آپ نے ہمیں جواب نہ دیا۔ہم نے عرض کی: اے اللہ کے رسول! ہم نماز میں آپ کو سلام کہا کرتے تھے اور آ پ ہمیں جواب دیا کرتے تھے۔آپ نے فرمایا:’’ نماز میں (اس کی اپنی)مشغولیت ہوتی ہے۔‘‘"}],[1135,"اعمش سے ( ابن فضیل کے بجائے ) ہریم بن سفیان نے مذکورہ بالا سند کے ساتھ اسی کے مثل حدیث بیان کی","",{"u2":"اعمش سے (ابن فضیل کے بجائے)ہریم بن سفیان نے مذکورہ بالا سند کے ساتھ اسی کے مثل حدیث بیان کی"}],[1136,"ہشیم نے اسماعیل بن ابی خالد سے ، انھوں نے حارث بن شبیل سے ، انھوں نے ابوعمر و شیبانی سے اور انھوں نے سیدنا زید بن ارقم رضی اللہ عنہ رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم نماز میں بات چیت کر لیا کرتے تھے ، ایک آدمی نماز میں اپنے ساتھی سے گفتگو کرلیتا تھا یہاں تک کہ یہ آیت اتری ، ( وقوم للہ قنتین ) ’’ اللہ کے حضور انتہائی خشوع و خضوع کے عالم میں کھٹرے ہو’’ تو ہمیں خاموش رہنے کا حاکم دیا گیا ہمیں گفتگو کرنے سے روک دیا گیا ۔","",{"u2":"ہشیم نے اسماعیل بن ابی خالد سے،انھوں نے حارث بن شبیل سے،انھوں نے ابوعمر و شیبانی سے اور انھوں نے سیدنا زید بن ارقم رضی اللہ عنہ رضی اللہ تعالیٰ عنہ سے روایت کی، انھوں نے کہا: ہم نماز میں بات چیت کر لیا کرتے تھے، ایک آدمی نماز میں اپنے ساتھی سے گفتگو کرلیتا تھا یہاں تک کہ یہ آیت اتری، (وقوم للہ قنتین)’’ اللہ کے حضور انتہائی خشوع و خضوع کے عالم میں کھٹرے ہو’’ تو ہمیں خاموش رہنے کاحاکم دیا گیا ہمیں گفتگوکرنے سے روک دیا گیا۔"}],[1137,"(ہشیم کے بجائے ) عبداللہ بن نمیر ، وکیع اور عیسیٰ بن یونس نے اسماعیل بن ابی خالد سے اسی سند کے ساتھ اسی طرح روایت کی ۔","",{"u2":"ہشیم کے بجائے) عبداللہ بن نمیر،وکیع اور عیسیٰ بن یونس نے اسماعیل بن ابی خالد سے اسی سند کے ساتھ اسی طرح روایت کی۔"}],[1138,"قتیبہ بن سیعد اور محمد بن رمح نے اپنی اپنی سند کے ساتھ لیث ( بن سعد ) سے حدیث بیان کی ، انھوں نے ابوزبیر سے اور انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہما سے روایت کی کہ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی ضرورت ے لیے بیھجا ، پھر میں آپ کو آ کر ملا ، آپ سفر میں تھے قتیبہ نے کہا : آپ نے نماز پڑھ رہے تھے میں نے آپ کو سلام کہا ، آ پ نے مجھے اشارہ فرمایا ۔ جب آپ نماز سے فارغ ہوئے تو مجھے بلوایا اور فرمایا : ‘‘ ابھی تم نے سلام کہا جبکہ میں نماز پڑھ رہا تھا ۔ ’’ اور اس وقت ( ساری پر نماز پڑھتے ہوئے ) آپ کا رخ مشرق کی طرف تھا ۔","",{"u2":"قتیبہ بن سیعد اور محمد بن رمح نے اپنی اپنی سند کے ساتھ لیث(بن سعد)سے حدیث بیان کی،انھوں نے ابوزبیر سے اور انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہما سے روایت کی کہ انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی ضرورت ے لیے بیھجا،پھر میں آپ کو آ کر ملا، آپ سفر میں تھے قتیبہ نے کہا: آپ نے نماز پڑھ رہے تھے میں نے آپ کو سلام کہا، آ پ نے مجھے اشارہ فرمایا۔ جب آپ نماز سے فارغ ہوئے تو مجھے بلوایا اور فرمایا:‘‘ ابھی تم نے سلام کہا جبکہ میں نماز پڑھ رہا تھا۔’’ اور اس وقت (ساری پر نماز پڑھتے ہوئے)آپ کا رخ مشرق کی طرف تھا۔"}],[1139,"زہیر نے کہا : مجھے ابو زبیر نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے حدیث سنائی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھے کا کے لیے بھیجا اور آپ بنو مصطلق کی طرف جا رہے تھے ، میں واپسی پر آپ کے پاس آیا تو آٖپ اونٹ پر نماز پڑھ رہے تھے ، میں نے آپ سے بات کی تو آپ نے مجھے ہاتھ سے اس طرح اشا رہ کیا ۔ زہیر نے اپنے ہاتھ سے اشارہ کر کے دکھایا ۔ میں نے دوبارہ بات کی تو مجھے اس طرح ( اشارے سے کچھ ) کہا ۔ زہیر نے بھی اپنے ہاتھ سے زمین کی طرف اشارہ کیا ۔ اور میں سن رہا تھا کہ آپ قراءت فرما رہے ہیں ، آپ ( رکوع و سجود کے لیے ) سر سے اشارہ فرماتے تھے ، جب آپ فارغ ہو ئے تو پوچھا ‘‘ جس کا م کے لیے میں بھیجا تھا تم نے ( اس کے بارے میں ) کیا کیا ؟ مجھے تم سے گفتگو کرنے سے اس کے سوا کسی چیز نے نہیں روکا کہ میں نماز پڑھ رہا تھا ۔ ’’ زہیر نے کہا : ابو زبیر کعبہ کی طرف رخ کر کے بیٹھے ہوئے تھے ، ابو زبیر نے بنو مصطلق کی طرف اشارہ کیا اور انھوں ( ابوزبیر ) نے ہاتھ سے قبلے کی دوسری سمت کی طرف اشارہ کیا ( سواری پر نماز کے دوران میں آپ کا رخ کعبہ کی طرف نہیں تھا ۔)","",{"u2":"زہیر نے کہا:مجھے ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے حدیث سنائی،انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے مجھے کا کے لیے بھیجا اور آپ بنو مصطلق کی طرف جا رہے تھے، میں واپسی پر آپ کے پاس آیا تو آٖپ اونٹ پر نماز پڑھ رہے تھے، میں نے آپ سے بات کی تو آپ نے مجھے ہاتھ سے اس طرح اشا رہ کیا۔ زہیر نے اپنے ہاتھ سے اشارہ کر کے دکھایا۔ میں نے دوبارہ بات کی تو مجھے اس طرح (اشارے سے کچھ) کہا۔ زہیر نے بھی اپنے ہاتھ سے زمین کی طرف اشارہ کیا۔ اور میں سن رہا تھا کہ آپ قراءت فرما رہے ہیں، آپ (رکوع و سجود کے لیے)سر سے اشارہ فرماتے تھے، جب آپ فارغ ہو ئے تو پوچھا ‘‘جس کا م کے لیے میں بھیجا تھا تم نے (اس کے بارے میں)کیا کیا؟ مجھے تم سے گفتگو کرنے سے اس کے سوا کسی چیز نے نہیں روکا کہ میں نماز پڑھ رہا تھا۔’’ زہیر نے کہا:ابو زبیر کعبہ کی طرف رخ کر کے بیٹھے ہوئے تھے، ابو زبیر نےبنو مصطلق کی طرف اشارہ کیا اور انھوں (ابوزبیر)نے ہاتھ سے قبلے کی دوسری سمت کی طرف اشارہ کیا (سواری پر نماز کے دوران میں آپ کا رخ کعبہ کی طرف نہیں تھا۔)"}],[1140,"حماد بن زید نے کثیر ( بن شنظیر ) سے ، انھوں نے عطاء سے اور انھوں سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : ہم نبی صلی اللہ علیہ وسلم کے ہمراہ سفر میں تھے ، آپ نے مجھے کسی کام سے بھیجا ، میں واپس آبا تو اپنی سواری پر نماز پڑھ رہے تھے اور آپ کا رخ قبلے کی بجائے دوسری طرف تھا ، میں نے آپ کو سلام کہا تو آپ نے مجھے سلام کا جواب نہ دیا ، جب آپ نے سلام پھیر لیا تو فرمایا : ‘‘ تمھارے سلام کا جواب دینے سے مجھے صرف اس بات نے روکا کہ میں نماز پڑھ رہا تھا ۔ ’’","",{"u2":"حماد بن زید نے کثیر (بن شنظیر)سے، انھوں نے عطاء سے اور انھوں حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، انھوں نے کہا: ہم نبی صلی اللہ علیہ وسلم کے ہمراہ سفر میں تھے، آپ نے مجھے کسی کام سے بھیجا، میں واپس آبا تو اپنی سواری پر نماز پڑھ رہے تھے اور آپ کا رخ قبلے کی بجائے دوسری طرف تھا،میں نے آپ کو سلام کہا تو آپ نے مجھے سلام کا جواب نہ دیا، جب آپ نے سلام پھیر لیا تو فرمایا: ‘‘ تمھارے سلام کا جواب دینے سے مجھے صرف اس بات نے روکا کہ میں نماز پڑھ رہا تھا۔’’"}],[1141,"عبدالوارث بن سعید نے کہا : ہمیں کثر بن شنظیر نے حدیث سنائی ، انھوں نے عطاء سے اور انھوں نے سیدنا جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی کام کی غرض سے بھیجا .........آگے حماد بن زید کی حدیث کے ہم معنی حدیث بیان کی ۔","",{"u2":"عبدالوارث بن سعید نے کہا: ہمیں کثر بن شنظیر نے حدیث سنائی، انھوں نے عطاء سے اور انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی کام کی غرض سے بھیجا .........آگے حماد بن زید کی حدیث کے ہم معنی حدیث بیان کی۔"}],[1142,"اسحاق بن ابراہیم اور اسحاق بن منصور نے کہا : ہمیں نضر بن شمیل نے خبر دی ، انھوں نے کہا : ہمیں شعبہ نے خبر دی ، انھوں نے کہا : ہمیں شعبہ نے خبر دی ، انھوں نے کہا : ہمیں محمد نے ، جو ابن زیاد ہے ، حدیث سنائی ، انھوں نے کہا ، میں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ‘‘ گزشتہ رات ایک سرکش جن مجھ پر حملے کرنے لگا تا کہ میری نماز توڑ دے ۔ اللہ تعالیٰ نے اسے میرے قابو میں کر دیا تو میں نے زور سے اس کا گلا گھونٹا اور یہ ارادہ کیا کہ اسے مسجد کے ستونوں میں سے کسی ستون کے ساتھ باندھ دوں تاکہ صبح کو تم سب دیکھ سکو ، پھر مجھے اپنے بھائی سلیمان علیہ السلام کا یہ قول یاد آگیا : ‘‘ اے میرے رب! مجھے بخش دے اور مجھے ایسی حکومت دے جو میرے بعد کسی کے لائق نہ ہو ’’ ( تو میں نے اسے چھوڑ دیا ) اور اللہ نے اس ( جن ) کو رسوا کر کے لوٹا دیا ۔ ’’ ابن منصور نے کہا : شعبہ نے محمد بن زیاد سے روایت کی ۔","",{"u2":"اسحاق بن ابراہیم اور اسحاق بن منصور نے کہا: ہمیں نضر بن شمیل نے خبر دی، انھوں نے کہا: ہمیں شعبہ نے خبر دی، انھوں نے کہا:ہمیں شعبہ نے خبر دی، انھوں نے کہا: ہمیں محمد نے، جو ابن زیاد ہے، حدیث سنائی، انھوں نے کہا، میں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:‘‘گزشتہ رات ایک سرکش جن مجھ پر حملے کرنے لگا تا کہ میری نماز توڑ دے۔ اللہ تعالیٰ نے اسے میرے قابو میں کر دیا تو میں نے زور سے اس کا گلا گھونٹا اور یہ ارادہ کیا کہ اسے مسجد کے ستونوں میں سے کسی ستون کے ساتھ باندھ دوں تاکہ صبح کو تم سب دیکھ سکو، پھر مجھے اپنے بھائی سلیمان علیہ السلام کا یہ قول یاد آگیا:‘‘ اے میرے رب! مجھے بخش دے اور مجھے ایسی حکومت دے جو میرے بعد کسی کے لائق نہ ہو ’’ (تو میں نے اسے چھوڑ دیا)اور اللہ نے اس (جن) کو رسوا کر کے لوٹا دیا۔’’ ابن منصور نے کہا:شعبہ نے محمد بن زیاد سے روایت کی۔"}],[1143,"محمد بن بشار نے کہا : ہمیں محمد بن جعفر نے حدیث سنائی ۔ اور ابو بکر بن ابی شیبہ نے کہا : ہمیں شبابہ نے حدیث سنائی ، ان دونوں ( ابن جعفر اور شبابہ ) نے شعبہ سے اسی سند کے ساتھ حدیث روایت کی ۔ ابن جعفر کی روایت میں ‘‘ میں نے اس کا گلا گھونٹا ’’ کے الفاظ نہیں جبکہ ابن ابی شبیہ نے اپنی روایت میں کہا : ‘‘ میں نے اسے پیچھے دھکا دیا ۔ ’’","",{"u2":"محمد بن بشار نے کہا: ہمیں محمد بن جعفر نے حدیث سنائی۔ اور ابو بکر بن ابی شیبہ نے کہا: ہمیں شبابہ نے حدیث سنائی، ان دونوں (ابن جعفر اور شبابہ)نے شعبہ سے اسی سند کے ساتھ حدیث روایت کی۔ابن جعفر کی روایت میں ‘‘ میں نے اس کا گلا گھونٹا ’’ کے الفاظ نہیں جبکہ ابن ابی شبیہ نے اپنی روایت میں کہا:‘‘ میں نے اسے پیچھے دھکا دیا۔’’"}],[1144,"سیدنا ابو درداء رضی اللہ تعالیٰ عنہ سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم قیام ( کی حالت ) میں تھے کہ ہم نے آپ کو یہ کہتے ہوئے سنا : ‘‘ میں تجھ سے اللہ کی پنا میں آتا ہوں ۔ ’’ پھر آپ نے فرمایا : ‘‘ میں تجھ پر اللہ کی لعنت بھیجتا ہوں ۔ ’’ آپ نے یہ تین بار کہا اور آپ نے اپنا ہاتھ بڑھایا ، گویا کہ آپ کسی چیز کو پکڑ رہے ہیں ، جب آپ نماز سے فارغ ہوئے تو ہم نے پوچھا : اے اللہ کے رسول ! ہم نے آب کو نماز میں کچھ کہتے سنا ہے جو اس سے پہلے آب کو کبھی کہتے نہیں سنا اور ہم نے آپ کو دیکھا کہ آپ نے اپنا ہاتھ ( آگے ) بڑھایا ۔ آب نے فرمایا ‘‘ اللہ دشمن ابلیس آگ کا ایک شعلہ لے کر آیا تھا تا کہ اسے میرے چہرے پر ڈال دے ، میں نے تین دفعہ اعوذ باللہ منک ‘‘ میں تجھ سے اللہ کی پنا ہ مانگتا ہوں’’ کہا ، پھر میں نے تین بار کہا : میں تجھ پر اللہ کی کامل لعنت بھیجتا ہوں ۔ وہ پھر بھی پیچھے نہ ہٹا تو میں نے اسے پکڑ نے کا ارادہ کر لیا ۔ اللہ کی قسم ! اگر ہمارے بھائی سلیمان علیہ السلام کی دعا نہ ہوتی تو وہ صبح تک بندھا رہتا اور مدینہ والوں کے بچے اس کے ساتھ کھیلتے ۔ ’’","",{"u2":"حضرت ابو درداء رضی اللہ تعالیٰ عنہ سے روایت ہے، انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم قیام (کی حالت) میں تھے کہ ہم نے آپ کو یہ کہتے ہوئے سنا: ‘‘ میں تجھ سے اللہ کی پنا میں آتا ہوں۔’’ پھر آپ نے فرمایا:‘‘ میں تجھ پر اللہ کی لعنت بھیجتا ہوں۔’’ آپ نے یہ تین بار کہا اور آپ نے اپنا ہاتھ بڑھایا، گویا کہ آپ کسی چیز کو پکڑ رہے ہیں، جب آپ نماز سے فارغ ہوئے تو ہم نے پوچھا: اے اللہ کے رسول! ہم نے آب کو نماز میں کچھ کہتے سنا ہے جو اس سے پہلے آب کو کبھی کہتے نہیں سنا اور ہم نے آپ کو دیکھا کہ آپ نے اپنا ہاتھ (آگے)بڑھایا۔ آب نے فرمایا ‘‘ اللہ دشمن ابلیس آگ کا ایک شعلہ لے کر آیا تھا تا کہ اسے میرے چہرے پر ڈال دے، میں نے تین دفعہ اعوذ باللہ منک ‘‘ میں تجھ سے اللہ کی پنا ہ مانگتا ہوں’’ کہا، پھر میں نے تین بار کہا: میں تجھ پر اللہ کی کامل لعنت بھیجتا ہوں۔ وہ پھر بھی پیچھے نہ ہٹا تو میں نے اسے پکڑ نے کا ارادہ کر لیا۔ اللہ کی قسم! اگر ہمارے بھائی سلیمان علیہ السلام کی دعا نہ ہوتی تو وہ صبح تک بندھا رہتا اور مدینہ والوں کے بچے اس کے ساتھ کھیلتے۔’’"}],[1145,"عبداللہ بن مسلمہ بن مسلمہ بن قعنب اور قتیبہ بن سعید نے کہا : ہمیں امام مالک نے حدیث سنائی ۔ دوسری سند میں یحیٰی بن یحییٰ نے کہا : میں نے امام مالک سے کہا : کہا آپ کو عامر بن عبداللہ بن زبیر نے عمر و بن سلیم زرقی سے اور انھوں نے سیدنا ابو قتادہ رضی اللہ تعالیٰ عنہ سے روایت کرتے ہوئے یہ حدیث سنائی تھی کہ رسول اللہ صلی اللہ علیہ وسلم اپنی صاحبزادی زینب اور ابو العاص بن ربیع رضی اللہ تعالی عنہما کی بیٹی امامہ رضی اللہ تعالیٰ عنہا کو اٹھا کر نماز پڑھ لیتے تھے ، جب آپ کھڑے ہوتے تو اسے اٹھا لیتے اور جب سجدہ کرتے تو اسے ( زمین پر ) بٹھا دیتے تھے ؟ یحیٰی نے کہا : امام مالک نے جواب دیا : ہاں ( یہ روایت مجھے سنائی تھی ۔)","",{"u2":"عبداللہ بن مسلمہ بن مسلمہ بن قعنب اور قتیبہ بن سعید نے کہا: ہمیں امام مالک نے حدیث سنائی۔ دوسری سند میں یحیٰی بن یحییٰ نے کہا: میں نے امام مالک سے کہا: کہا آپ کو عامر بن عبداللہ بن زبیر نے عمر و بن سلیم زرقی سے اور انھوں نے حضرت ابو قتادہ رضی اللہ تعالیٰ عنہ سے روایت کرتے ہوئے یہ حدیث سنائی تھی کہ رسول اللہ صلی اللہ علیہ وسلم اپنی صاحبزادی زینب اور ابو العاص بن ربیع رضی اللہ تعالی عنہما کی بیٹی امامہ رضی اللہ تعالیٰ عنہا کو اٹھا کر نماز پڑھ لیتے تھے، جب آپ کھڑے ہوتے تو اسے اٹھا لیتے اور جب سجدہ کرتے تو اسے (زمین پر)بٹھا دیتے تھے؟ یحیٰی نے کہا: امام مالک نے جواب دیا:ہاں (یہ روایت مجھے سنائی تھی۔)"}],[1146,"عثمان بن ابی سلیمان اور ابن عجلان دونوں نے عامر بن عبداللہ بن زبیر کو عمرو سلیم زرقی سے حدیث بیان کرتے ہوئے سنا ، انھوں نے سیدنا ابو قتادہ انصاری رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا ۔ آپ لوگوں کی امات کر رہے تھے ، اور ابو العاص رضی اللہ تعالیٰ عنہ کی بیٹی امامہ رضی اللہ تعالیٰ عنہا جو نبی اکرم صلی اللہ علیہ وسلم کی صاحبزادی زینب رضی اللہ عنہا کی بیٹی تھیں ، آپ کے کندے پر تھیں ، جب آپ رکوع میں جاتے تو انھیں کندھے سے اتار دیتے اور جب سجدے سے اٹھتے تو پھر سے انھیں اٹھا لیتے ۔","",{"u2":"عثمان بن ابی سلیمان اور ابن عجلان دونوں نے عامر بن عبداللہ بن زبیر کو عمرو سلیم زرقی سے حدیث بیان کرتے ہوئے سنا، انھوں نے حضرت ابو قتادہ انصاری رضی اللہ تعالیٰ عنہ سے روایت کی، کہا میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا۔ آپ لوگوں کی امات کر رہے تھے، اور ابو العاص رضی اللہ تعالیٰ عنہ کی بیٹی امامہ رضی اللہ تعالیٰ عنہا جو نبی اکرم صلی اللہ علیہ وسلم کی صاحبزادی زینب رضی اللہ عنہا کی بیٹی تھیں، آپ کے کندے پر تھیں، جب آپ رکوع میں جاتے تو انھیں کندھے سے اتار دیتے اور جب سجدے سے اٹھتے تو پھر سے انھیں اٹھا لیتے۔"}],[1147,"بکیر ( بن عبداللہ ) نے عمرو بن سلیم زرقی سے روایت کی ، انھوں نے کہا : میں نے سیدنا ابو قتادہ انصاری رضی اللہ تعالیٰ عنہ سے سنا ، وہ کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، آپ لوگوں کو نماز پڑھا رہے تھے اور ابو العاص رضی اللہ تعالیٰ عنہ کی بیٹی امامہ رضی اللہ تعالیٰ عنہا آپ کی گردن پر تھیں ، جب آپ سجدہ کرتے تو انھیں اتار دیتے ۔","",{"u2":") بکیر (بن عبداللہ)نے عمرو بن سلیم زرقی سے روایت کی، انھوں نے کہا: میں نے حضرت ابو قتادہ انصاری رضی اللہ تعالیٰ عنہ سے سنا، وہ کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، آپ لوگوں کو نماز پڑھا رہے تھے اور ابو العاص رضی اللہ تعالیٰ عنہ کی بیٹی امامہ رضی اللہ تعالیٰ عنہا آپ کی گردن پر تھیں، جب آپ سجدہ کرتے تو انھیں اتار دیتے۔"}],[1148,"سعید مقبری نے عمر و بن سلیم زرقی سے روایت کی ، انھوں نے سیدنا ابو قتادہ رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا : ہم مسجد میں بیٹھے ہوئے تھے کہ اسی اثنا میں رسول اللہ صلی اللہ علیہ وسلم ( گھر سے ) نکل کر ہمارے پاس تشریف لائے ...... ( آگے ) مذکورہ بالا روایوں کی حدیث کے مانند حدیث بیان کی ، مگر انھوں ( سعید مقبری ) نے یہ بیان نہیں کیا کہ اس نما میں آپ لوگوں کی امامت فرمائی تھی ۔","",{"u2":"سعید مقبری نے عمر و بن سلیم زرقی سے روایت کی، انھوں نے حضرت ابو قتادہ رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا: ہم مسجد میں بیٹھے ہوئے تھے کہ اسی اثنا میں رسول اللہ صلی اللہ علیہ وسلم (گھر سے)نکل کر ہمارے پاس تشریف لائے ......(آگے)مذکورہ بالا روایوں کی حدیث کے مانند حدیث بیان کی، مگر انھوں (سعید مقبری)نے یہ بیان نہیں کیا کہ اس نما میں آپ لوگوں کی امامت فرمائی تھی۔"}],[1149,"عبدالعزیز بن ابی حازم نے اپنے والد سے خبر دی کہ کچھ لوگ سیدنا سہل بن سعد رضی اللہ تعالیٰ عنہ کی خدمت میں حاضر ہوئے اور انھوں نے منبر نبوی کے بارے میں میں بخث کی تھی کہ وہ کس لکڑی سے بنا ہے ؟ انھوں ( سہل رضی اللہ تعالیٰ عنہ ) نے کہا : ہاں! اللہ کی قسم ! میں اچھی طرح جانتا ہوں کہ وہ کس لکڑی ہے اور اسے کس نے بنایا تھا ۔ رسول اللہ صلی اللہ علیہ وسلم جب پہلے دن اس پر بیٹھے تھے ، میں نے آپ کو دیکھا تھا ۔ میں ( ابو حازم ) نے کہا : ابو عباس ! پھر تو ( آپ ) ہمیں ( اس کی ) تفصیل بتائیے ۔ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ایک عورت کی طرف پیغام بھیجا ۔ ابو حازم نے کہا : وہ اس دن اس کا نام بھی بتارے تھے اور کہا ۔ ‘‘ اپنے بڑھئی غلام کو دیکھو ( اور کہو ) وہ میرے لیے لکڑیا ں ( جوڑکر منبر ) بنا دے تا کہ میں اس پر سے لوگوں سے گفتگو کیا کروں ۔ تو اس نے یہ تین سٹرھیاں بنائیں ، پھر رسول للہ صلی اللہ علیہ وسلم نے اس کے بارے میں حکم دیا اور اسے اس جگہ رکھ دیا گیا اور یہ مدینہ کے جنگل کے درخت جھاؤ ( کی لکڑی ) سے بنا تھا ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، آپ اس پر کھڑے ہوئے اور تکبیر کہی ، لوگوں نے بھی آپ کے پیچھے تکبیر کہی جبکہ آپ منبر ہی پر تھے ، پھر آپ ( نے رکوع سے سر اٹھایا ) اٹھے اور الٹے پاؤں نیچے اترے اور منبر کی جڑ میں ( جہاں وہ رکھا ہوا تھا ) سجدہ کیا ، پھر دوبارہ وہی کیا ( منبر پر کھڑے ہو گئے ) حتی کہ نماز پوری کر کے فارغ ہوئے ، پھر لوگوں کی طرف متوجہ ہوئے اور فرمایا : ‘‘ لوگو! میں نے یہ کام اس لیے کیا ہے تاکہ تم ( مجھے دیکھتے ہوئے ) میری پیروی کرو اور میری نماز سیکھ لو ۔ ’’","",{"u2":"عبدالعزیز بن ابی حازم نے اپنے والد سے خبر دی کہ کچھ لوگ حضرت سہل بن سعد رضی اللہ تعالیٰ عنہ کی خدمت میں حاضر ہوئے اور انھوں نے منبر نبوی کے بارے میں میں بخث کی تھی کہ وہ کس لکڑی سے بنا ہے؟ انھوں (سہل رضی اللہ تعالیٰ عنہ)نے کہا: ہاں! اللہ کی قسم! میں اچھی طرح جانتا ہوں کہ وہ کس لکڑی ہے اور اسے کس نے بنایا تھا۔ رسول اللہ صلی اللہ علیہ وسلم جب پہلے دن اس پر بیٹھے تھے،میں نے آپ کو دیکھا تھا۔ میں (ابو حازم)نے کہا: ابو عباس! پھر تو (آپ)ہمیں (اس کی)تفصیل بتائیے۔ انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک عورت کی طرف پیغام بھیجا۔ ابو حازم نے کہا: وہ اس دن اس کا نام بھی بتارے تھے اور کہا۔‘‘ اپنے بڑھئی غلام کو دیکھو (اور کہو)وہ میرے لیے لکڑیا ں (جوڑکر منبر)بنا دے تا کہ میں اس پر سے لوگوں سے گفتگو کیا کروں۔ تو اس نے یہ تین سٹرھیاں بنائیں،پھر رسول للہ صلی اللہ علیہ وسلم نے اس کے بارے میں حکم دیا اور اسے اس جگہ رکھ دیا گیا اور یہ مدینہ کے جنگل کے درخت جھاؤ (کی لکڑی)سے بنا تھا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، آپ اس پر کھڑے ہوئے اور تکبیر کہی، لوگوں نے بھی آپ کے پیچھے تکبیر کہی جبکہ آپ منبر ہی پر تھے، پھر آپ (نے رکوع سے سر اٹھایا)اٹھے اور الٹے پاؤں نیچے اترے اور منبر کی جڑ میں (جہاں وہ رکھا ہوا تھا)سجدہ کیا، پھر دوبارہ وہی کیا (منبر پر کھڑے ہو گئے)حتی کہ نماز پوری کر کے فارغ ہوئے،پھر لوگوں کی طرف متوجہ ہوئے اور فرمایا:‘‘لوگو! میں نے یہ کام اس لیے کیا ہےتاکہ تم (مجھے دیکھتے ہوئے)میری پیروی کرو اور میری نماز سیکھ لو۔’’"}],[1150,"یعقوب بن عبدالرحمن بن محمد بن عبداللہ بن عبد ، قار ی قرشی نے کہا : مجھے ابو حازم نے حدیث سنائی کہ کچھ لوگ سیدنا سہل بن سعد ساعدی رضی اللہ تعالیٰ عنہ کے پاس آئے ، نیز سفیان بن عیینہ نے ابو حازم سے حدیث سنائی کہ لوگ سہل بن سعد رضی اللہ تعالیٰ عنہ کے پاس آئے اور ان سے پوچھا : نبی اکرم صلی اللہ علیہ وسلم کا منبر کس ( لکڑی ) سے ( بنا ہوا ) ہے ....... ( آگے ) ابن ابی حازم کی روایت کی حدیث کی طرح ہے ۔"],[1151,"یعقوب بن عبدالرحمن بن محمد بن عبداللہ بن عبد ، قار ی قرشی نے کہا : مجھے ابو حازم نے حدیث سنائی کہ کچھ لوگ سیدنا سہل بن سعد ساعدی رضی اللہ تعالیٰ عنہ کے پاس آئے ، نیز سفیان بن عیینہ نے ابو حازم سے حدیث سنائی کہ لوگ سہل بن سعد رضی اللہ تعالیٰ عنہ کے پاس آئے اور ان سے پوچھا : نبی اکرم صلی اللہ علیہ وسلم کا منبر کس ( لکڑی ) سے ( بنا ہوا ) ہے ....... ( آگے ) ابن ابی حازم کی روایت کی حدیث کی طرح ہے ۔",""],[1152,"حکم بن موسیٰ قنطری نے کہا : ہمیں عبداللہ بن مبارک نے حدیث سنائی ، نیز ابو بکر ابن ابی شیبہ نے کہا : ہمیں ابو خالد اور ابو اسامہ نے حدیث سنائی ، ان سب نے ہشام سے ، انھوں نے محمد ( بن سیرین ) سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے س بات سے منع فرمایا کہ کوئی آدمی پہلو پر ہاتھ رکھے ہوئے نماز پڑھے ۔ امام مسلم کے استاد ابو بکر کی روایت میں ( نبی صلی اللہ علیہ وسلم کے بجائے ) ‘‘ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ’’ کے الفاظ ہیں ۔","",{"u2":"حکم بن موسیٰ قنطری نے کہا: ہمیں عبداللہ بن مبارک نے حدیث سنائی، نیز ابو بکر ابن ابی شیبہ نے کہا: ہمیں ابو خالد اور ابو اسامہ نے حدیث سنائی، ان سب نے ہشام سے، انھوں نے محمد (بن سیرین)سے،انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے س بات سے منع فرمایا کہ کوئی آدمی پہلو پر ہاتھ رکھے ہوئے نماز پڑھے۔ امام مسلم کے استاد ابو بکر کی روایت میں (نبی صلی اللہ علیہ وسلم کے بجائے)‘‘ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ’’ کے الفاظ ہیں۔"}],[1153,"ہمیں وکیع نے حدیث سنائی ، کہا : ہمیں ہشام دستوائی نے حدیث سنائی ، انھوں نے یحییٰ بن ابی کثیر سے ، انھوں نے ابو سلمہ سے اور انھوں نے سیدنا معیقیب رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے مسجد میں ہاتھ سے کنکریاں صاف کرنے کا تذکروہ کیا اور فرمایا : ‘‘ اگر تمھارے لیے اسے کیے بغیر چارہ نہ ہو تو ایک بار ( کر لو ۔ ) ’’","",{"u2":"ہمیں وکیع نے حدیث سنائی، کہا: ہمیں ہشام دستوائی نے حدیث سنائی، انھوں نے یحییٰ بن ابی کثیر سے، انھوں نے ابو سلمہ سے اور انھوں نے حضرت معیقیب رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے مسجد میں ہاتھ سے کنکریاں صاف کرنے کا تذکروہ کیا اور فرمایا:‘‘ اگر تمھارے لیے اسے کیے بغیر چارہ نہ ہو تو ایک بار (کر لو۔)’’"}],[1154,"یحییٰ بن سعید نے ہشام سے اسی سند کے ساتھ سیدنا معیقیب رضی اللہ تعالیٰ عنہ سے روایت کی کہ لوگوں نے نبی اکرم صلی اللہ علیہ وسلم سے نماز ( کے دوران ) میں ہاتھ سے ( کنکریاں وغیرہ ) صاف کرنے کے بارےمیں سوال کیا تو آپ نے فرمایا : ‘‘ ایک بار ( کی جاسکتی ہیں ۔ ) ’’","",{"u2":"یحییٰ بن سعید نے ہشام سے اسی سند کے ساتھ حضرت معیقیب رضی اللہ تعالیٰ عنہ سے روایت کی کہ لوگوں نے نبی اکرم صلی اللہ علیہ وسلم سے نماز (کے دوران)میں ہاتھ سے (کنکریاں وغیرہ)صاف کرنے کے بارےمیں سوال کیا تو آپ نے فرمایا: ‘‘ ایک بار (کی جاسکتی ہیں۔)’’"}],[1155,"یحییٰ بن سعید نے ہشام سے اسی سند کے ساتھ سیدنا معیقیب رضی اللہ تعالیٰ عنہ سے روایت کی کہ لوگوں نے نبی اکرم صلی اللہ علیہ وسلم سے نماز ( کے دوران ) میں ہاتھ سے ( کنکریاں وغیرہ ) صاف کرنے کے بارےمیں سوال کیا تو آپ نے فرمایا : ‘‘ ایک بار ( کی جاسکتی ہیں ۔ ) ’’","",{"u2":"خالد بن حارث نے کہا: ہمیں ہشام نے اسی سند سے حدیث سنائی اور (عن معیقیب کے بجائے) حدثنی معیقیب کہا۔"}],[1156,"یحییٰ بن سعید نے ہشام سے اسی سند کے ساتھ سیدنا معیقیب رضی اللہ تعالیٰ عنہ سے روایت کی کہ لوگوں نے نبی اکرم صلی اللہ علیہ وسلم سے نماز ( کے دوران ) میں ہاتھ سے ( کنکریاں وغیرہ ) صاف کرنے کے بارےمیں سوال کیا تو آپ نے فرمایا : ‘‘ ایک بار ( کی جاسکتی ہیں ۔ ) ’’","",{"u2":"ہشام کے بجائے)شیبان نے یحییٰ سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے اس آدمی کے بارے میں جو سجدے کی جگہ کی مٹی برابر کرتا ہے، فرمایا: ‘‘ اگر تم نے ایسا کرنا ہی ہے تو ایک بار کرو۔’’"}],[1157,"امام مالک نے نافع سے اور انھوں سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ( مسجد کی ) قبلے والی دیوار ( کی سمت ) میں بلغم ملا تھوک لگا ہو ا دیکھا تو اسے کھرچ دیا ، پھر لوگوں کی طرف متوجہ ہو کر فرمایا : ‘‘ جب تم میں سے کوئی نماز میں ہو تو اپنے سامنے نہ تھوکے کیونکہ جب وہ وہ نماز پڑھتا ہے تو اللہ اس کے سامنے ہوتا ہے ۔ ’’","",{"u2":"امام مالک نے نافع سے اور انھوں حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے (مسجد کی)قبلے والی دیوار (کی سمت)میں بلغم ملا تھوک لگا ہو ا دیکھا تو اسے کھرچ دیا، پھر لوگوں کی طرف متوجہ ہو کر فرمایا: ‘‘ جب تم میں سے کوئی نماز میں ہو تو اپنے سامنے نہ تھوکے کیونکہ جب وہ وہ نماز پڑھتا ہے تو اللہ اس کے سامنے ہوتا ہے۔’’"}],[1158,"عبید اللہ ، لیث بن سعد ، ایوب ، ضحاک بن عثمان اور موسیٰ بن عقبہ سب نے نافع سے ، انھوں نے سیدنا ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے مسجد کے قبلے ( کی سمت ) میں بلغم دیکھا ۔ سوائے ضحاک کے کہ ان کی روایت میں ( مسجد کے قبلے کے بجائے ) ‘‘ قبلے ( کی سمت ) میں ’’ کے الفاظ ہیں ..... ( آگے ) امام مالک کی حدیث کے ہم معنی روایت ہے ۔","",{"u2":") عبید اللہ، لیث بن سعد، ایوب، ضحاک بن عثمان اور موسیٰ بن عقبہ سب نے نافع سے، انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے مسجد کے قبلے (کی سمت)میں بلغم دیکھا۔ سوائے ضحاک کے کہ ان کی روایت میں (مسجد کے قبلے کے بجائے) ‘‘ قبلے (کی سمت)میں ’’ کے الفاظ ہیں .....(آگے)امام مالک کی حدیث کے ہم معنی روایت ہے۔"}],[1159,"سفیان بن عیینہ نے زہری سے ، انھوں نے حمید بن عبدالرحمن سے اور انھوں نے سیدنا ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے مسجد کے قبلے ( کی سمت ) میں بلغم دیکھا تو آپ نے اسے ایک کنکر کے ذریعے سے کھر چ ڈالا ، پھر آپ نے اس بات سے منع فرمایا کہ کوئی شخص اپنے دائیں یا سامنے تھوکے ، البتہ وہ ( اگر کچی زمین یا ریت پر نماز پڑ ھ رہا ہے تو ) اپنی بائیں جانب یا بائیں پاؤں کے نیچے تھوک سکتا ہے ۔","",{"u2":") سفیان بن عیینہ نے زہری سے، انھوں نے حمید بن عبدالرحمن سے اور انھوں نے حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے مسجد کے قبلے (کی سمت)میں بلغم دیکھا تو آپ نے اسے ایک کنکر کے ذریعے سے کھر چ ڈالا، پھر آپ نے اس بات سے منع فرمایا کہ کوئی شخص اپنے دائیں یا سامنے تھوکے، البتہ وہ (اگر کچی زمین یا ریت پر نماز پڑ ھ رہا ہے تو) اپنی بائیں جانب یا بائیں پاؤں کے نیچے تھوک سکتا ہے۔"}],[1160,"(سفیان کے بجائے ) یونس اور ابراہیم نے ابن شہاب سے ، انھوں نے حمید بن عبدالرحمن سے روایت کی کہ سیدنا ابو ہریرہ اور ابو سعید رضی اللہ تعالیٰ عنہما دونوں نے انھیں خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے بلغم ملا تھوک دیکھا ........ ( ٖآگے ) ابن عینہ کی حدیث کے مانند ہے ۔","",{"u2":"(سفیان کے بجائے)یونس اور ابراہیم نے ابن شہاب سے، انھوں نے حمید بن عبدالرحمن سے روایت کی کہ حضرت ابو ہریرہ اور ابو سعید رضی اللہ تعالیٰ عنہما دونوں نے انھیں خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے بلغم ملا تھوک دیکھا ........(ٖآگے)ابن عینہ کی حدیث کے مانند ہے۔"}],[1161,"سیدہ عائشہ رضی اللہ تعالی عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے قبلے کی دیوار پر تھوک یا رینٹ یا بلغم دیکھا تو کھرچ ڈالا ۔","",{"u2":"حضرت عائشہ رضی اللہ تعالی عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے قبلے کی دیوار پر تھوک یا رینٹ یا بلغم دیکھا تو کھرچ ڈالا۔"}],[1162,"ابن علیہ نے ہمیں حدیث بیان کی ، انھوں قاسم بن مہران سے ، انھوں نے ابو رافع سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مسجد کے قبلے ( کی سمت ) میں بلغم دیکھا تو لوگوں کی طرف متوجہ ہوئے اور فرمایا : ’’ تم میں سے کسی ایک کو کیا ( ہو جاتا ) ہے ، وہ اپنے رب کی طرف منہ کر کے کھڑا ہوتا ہے ، پھر اپنے سامنے بلغم پھینک دیتا ہے ؟ کیا تم میں سے کسی کو یہ پسند ہے کہ اس کی طرف رخ کیا جائے ، اس کے منہ کے سامنے تھوک دیا جائے ؟ چنانچہ جب تم میں سے کوئی شخص کھنگار پھینکنا چاہے تو وہ اپنی جائیں جانب قدم کے نیچے پھینکے ، اگر اس کی گنجائش نہ پائے تو ایسے کر لے ۔ ‘‘ قاسم نے اس ک وضاحت میں اپنے کپڑے میں تھوکا ، پھر اس کے ایک حصے کو دوسرے پر رگڑ دیا","",{"u2":"ابن علیہ نے ہمیں حدیث بیان کی، انھوں قاسم بن مہران سے،انھوں نے ابو رافع سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مسجد کے قبلے (کی سمت)میں بلغم دیکھا تو لوگوں کی طرف متوجہ ہوئے اور فرمایا:’’ تم میں سے کسی ایک کو کیا (ہو جاتا) ہے، وہ اپنے رب کی طرف منہ کر کے کھڑا ہوتا ہے، پھر اپنے سامنے بلغم پھینک دیتا ہے؟ کیا تم میں سے کسی کو یہ پسند ہے کہ اس کی طرف رخ کیا جائے، اس کے منہ کے سامنے تھوک دیا جائے؟ چنانچہ جب تم میں سے کوئی شخص کھنگار پھینکنا چاہے تو وہ اپنی جائیں جانب قدم کے نیچے پھینکے، اگر اس کی گنجائش نہ پائے تو ایسے کر لے۔‘‘ قاسم نے اس ک وضاحت میں اپنے کپڑے میں تھوکا، پھر اس کے ایک حصے کو دوسرے پر رگڑ دیا"}],[1163,"(ابن علیہ کے بجائے ) عبدالوارث ، ہشیم اور شعبہ نے قاسم بن مہران سے حدیث بیان کی ۔ انھوں نے ابو رافع سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے ، انھوں نے نبی صلی اللہ علیہ وسلم سے ابن علیہ کی حدیث کی طرح ( روایت بیان کی ۔ ) ہشیم کی حدیث میں یہ اضافہ کیا : ابو ہریرہ رضی اللہ عنہ نے کہا : جیسے میں دیکھ رہا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم کپڑے کا ایک حصہ دوسرے پر لوٹا ( رگڑ ) رہے ہیں ۔ ( اس طرح مسجد میں گندگی نہیں پھیلتی اور کپڑے کو باہر لے جا کر دھویا جاسکتا ہے ۔)","",{"u2":"ابن علیہ کے بجائے)عبدالوارث،ہشیم اورشعبہ نے قاسم بن مہران سے حدیث بیان کی۔ انھوں نے ابو رافع سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے، انھوں نے نبی صلی اللہ علیہ وسلم سے ابن علیہ کی حدیث کی طرح (روایت بیان کی۔)ہشیم کی حدیث میں یہ اضافہ کیا: ابو ہریرہ رضی اللہ عنہ نے کہا: جیسے میں دیکھ رہا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم کپڑے کا ایک حصہ دوسرے پر لوٹا (رگڑ)رہے ہیں۔ (اس طرح مسجد میں گندگی نہیں پھیلتی اور کپڑے کو باہر لے جا کر دھویا جاسکتا ہے۔)"}],[1164,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی نماز میں ہوتا ہے تو وہ اپنے رب سے راز و نیاز کرتا ہے ، اس لیے وہ نہ اپنے سامنے تھوکے نہ ہی دائیں طرف ، البتہ بائیں طرف پاؤں کے نیچے ( تھوک لے ۔ ) ‘‘","",{"u2":") سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی نماز میں ہوتا ہے تو وہ اپنے رب سے راز و نیاز کرتا ہے، اس لیے وہ نہ اپنے سامنے تھوکے نہ ہی دائیں طرف، البتہ بائیں طرف پاؤں کے نیچے (تھوک لے۔)‘‘"}],[1165,"ابو عوانہ نے قتادہ سے اور انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’مسجد میں تھوکنا ایک گنا ہ ہے اور اس کا کفارہ یہ ہے کہ ( اگر فرش کچا ہےتو ) اسے دفن کر دیا جائے ۔ ‘‘","",{"u2":"ابو عوانہ نے قتادہ سے اور انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’مسجد میں تھوکنا ایک گنا ہ ہے اور اس کا کفارہ یہ ہے کہ (اگر فرش کچا ہےتو)اسے دفن کر دیا جائے۔‘‘"}],[1166,"(ابو عوانہ کے بجائے ) شعبہ نے کہا : میں نے قتادہ سے مسجد میں تھوکنے کے بارے میں پوچھا تو انھوں نے کہا : میں نے سیدنا انس بن مالک رضی اللہ عنہ سے سنا ، وہ کہتے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ’’ مسجد میں تھوکنا ایک گنا ہ ہے اور اس کا کفارہ اسے دفن کرنا ہے ۔ ‘‘","",{"u2":")(ابو عوانہ کے بجائے)شعبہ نے کہا: میں نے قتادہ سے مسجد میں تھوکنے کے بارے میں پوچھا تو انھوں نے کہا: میں نے سیدنا انس بن مالک رضی اللہ عنہ سے سنا، وہ کہتے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:’’ مسجد میں تھوکنا ایک گنا ہ ہے اور اس کا کفارہ اسے دفن کرنا ہے۔‘‘"}],[1167,"سیدنا ابو ذر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’ میرے سامنے میری امت کے اچھے اور برے اعمال پیش کیے گئے ، میں نے اس کے اچھے اعمال میں راستے سے تکلیف دہ چیز ہٹانے کو دیکھا ، اس کے برے اعمال میں بلغم کو پا یا جو مسجد میں ہوتا ہے اور اسے دفن نہیں کیا جاتا ۔ ‘‘","",{"u2":"سیدنا ابو ذر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا:’’ میرے سامنے میری امت کے اچھے اور برے اعمال پیش کیے گئے، میں نے اس کے اچھے اعمال میں راستے سے تکلیف دہ چیز ہٹانے کو دیکھا، اس کے برے اعمال میں بلغم کو پا یا جو مسجد میں ہوتا ہے اور اسے دفن نہیں کیا جاتا۔‘‘"}],[1168,"کہمس نے یزید بن عبداللہ بن شخیر سے ، انھوں نے اپنے والد سےروایت کی ، انھوں نےکہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ( آپ کی اقتدا میں ) نماز ادا کی ، میں نے آپ کو دیکھا کہ آپ نے ( گلے سے ) بلغم نکالا اور ( چونکہ پاؤں کے نیچے ریت تھی اس لیے ) اسے اپنے جوتے سے مسل دیا ۔","",{"u2":"کہمس نے یزید بن عبداللہ بن شخیر سے، انھوں نے اپنے والد سےروایت کی، انھوں نےکہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (آپ کی اقتدا میں)نماز ادا کی، میں نے آپ کو دیکھا کہ آپ نے (گلے سے)بلغم نکالا اور (چونکہ پاؤں کے نیچے ریت تھی اس لیے)اسے اپنے جوتے سے مسل دیا۔"}],[1169,"جریری نے ابو علاء یزید بن عبداللہ بن شخیر سے اور انھوں نے اپنے والد سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں نماز پڑھی ۔ کہا : آپ نے گلے سے بلغم نکالا اور اسے اپنے بائیں جوتے سے مسل ڈالا ۔","",{"u2":") جریری نے ابو علاء یزید بن عبداللہ بن شخیر سے اور انھوں نے اپنے والد سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں نماز پڑھی۔کہا: آپ نے گلے سے بلغم نکالا اور اسے اپنے بائیں جوتے سے مسل ڈالا۔"}],[1170,"بشر بن مفضل نے ہمیں ابو مسلمہ سعید بن یزید سے خبر دی ، انھوں نے کہا : میں نے انس بن مالک رضی اللہ عنہ سے پوچھا : کیا رسول اللہ صلی اللہ علیہ وسلم جوتے پہن کر نماز پڑھتے تھے ؟ انھوں نے جواب دیا : ہاں ۔","",{"u2":"بشر بن مفضل نے ہمیں ابو مسلمہ سعید بن یزید سے خبر دی، انھوں نے کہا: میں نے انس بن مالک رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم جوتے پہن کر نماز پڑھتے تھے؟ انھوں نے جواب دیا:ہاں۔"}],[1171,"(بشر کے بجائے ) عباد بن عوام نے کہا : ہمیں ابو مسلمہ سعید بن یزید نے حدیث سنائی ، انھوں نے کہا : میں نے سیدنا انس رضی اللہ عنہ سے سوال کیا ..... ( آگے ) پہلی روایت کی طرح ہے","",{"u2":"بشر کے بجائے)عباد بن عوام نے کہا: ہمیں ابو مسلمہ سعید بن یزید نے حدیث سنائی، انھوں نے کہا: میں نے سیدنا انس رضی اللہ عنہ سے سوال کیا .....(آگے)پہلی روایت کی طرح ہے"}],[1172,"سفیان بن عیینہ نے ہمیں حدیث بیان کی ، انھوں نے زہری سے ، انھوں نعروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے بیل بوٹوں والی ایک منقش چادر میں نماز پڑھی اور فرمایا : ’’ اس کے بیل بوٹوں نے مجھے مشغول کر دیا تھا ، اسے ابو جہم کے پاس لے جاؤ اور ( اس کے بدلے ) مجھے انبجانی چادر لا دو ۔ ‘‘","",{"u2":") سفیان بن عیینہ نے ہمیں حدیث بیان کی، انھوں نے زہری سے، انھوں نعروہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے بیل بوٹوں والی ایک منقش چادر میں نماز پڑھی اور فرمایا:’’ اس کے بیل بوٹوں نے مجھے مشغول کر دیا تھا، اسے ابو جہم کے پاس لے جاؤ اور (اس کے بدلے)مجھے انبجانی چادر لا دو۔‘‘"}],[1173,"یونس نے ابن شہاب ( زہری ) سے خبر دی ، انھوں نے کہا : مجھے عروہ بن زبیر نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے خبر دی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم ایک بیل بوٹوں والی منقش چادر پر نماز پڑھنے کے لیے کھڑے ہوئے تو اس کے نقش و نگار پر آپ کی نظر پڑی ، جب آپ اپنی نماز سے فارغ ہوئے تو فرمایا : ’’یہ منقش چادر ابو جہم بن حذیفہ کے پاس لے جاؤ اور مجھے اس کی ( سادہ ) انبجانی چادر لادو کیونکہ اس نے ابھی میر نماز سے میری توجہ ہٹا دی تھی ۔ ‘‘","",{"u2":"یونس نے ابن شہاب (زہری)سے خبر دی، انھوں نے کہا: مجھے عروہ بن زبیر نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے خبر دی، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایک بیل بوٹوں والی منقش چادر پر نماز پڑھنے کے لیے کھڑے ہوئے تو اس کے نقش و نگار پر آپ کی نظر پڑی، جب آپ اپنی نماز سے فارغ ہوئے تو فرمایا: ’’یہ منقش چادر ابو جہم بن حذیفہ کے پاس لے جاؤ اور مجھے اس کی (سادہ)انبجانی چادر لادو کیونکہ اس نے ابھی میر نماز سے میری توجہ ہٹا دی تھی۔‘‘"}],[1174,"(ابن شہاب زہری کے بجائے ) ہشام نے اپنے والد عروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالی عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک منقش چادر تھی جس پر بیل بوٹے بنے ہوئے تھے ، نماز میں آپ کا خیال اس کی طرف چلا جاتا تھا ، آپ نے وہ ابو جہم کو دے دی اور اس کی ( بیل بوٹوں کے بغیر سادہ ) انبجانی چادر اس سے لے لی ۔ ( یہ چادر آذر بیجان کے ایک شہر انبجان کی طرف منسوب تھی ۔)","",{"u2":"ابن شہاب زہری کے بجائے)ہشام نے اپنے والد عروہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالی عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک منقش چادر تھی جس پر بیل بوٹے بنے ہوئے تھے، نماز میں آپ کا خیال اس کی طرف چلا جاتا تھا، آپ نے وہ ابو جہم کو دے دی اور اس کی (بیل بوٹوں کے بغیر سادہ)انبجانی چادر اس سے لے لی۔ (یہ چادر آذر بیجان کے ایک شہر انبجان کی طرف منسوب تھی۔)"}],[1175,"سفیان بن عیینہ نے زہری سے ، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’ جب رات کا کھا نا آ جائے اور نماز کے لیے تکبیر ( بھی ) کہہ دی جائے تو پہلے کھانا کھا لو","",{"u2":"سفیان بن عیینہ نے زہری سے، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا:’’ جب رات کا کھا نا آ جائے اور نماز کے لیے تکبیر (بھی)کہہ دی جائے تو پہلے کھانا کھا لو"}],[1176,"عمرو ( بن حارث ) نے ابن شہاب ( زہری ) سے خبر دی ، انھوں نے کہا : مجھے سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب رات کا کھانا پیش کر دیا جائے اور نماز کا ( بھی ) وقت ہو جائے تو مغرب کی نماز پڑھنے سے پہلے کھانے کی ابتدا کرو اور ( نماز کے لیے ) اپنا رات کا کھانا چھوڑ نے میں عجلت نہ کرو ۔ ‘‘ ( اس زمانے میں رات کا کھانا مغرب کے قریب ہی کھا یا جاتا تھا ۔)","",{"u2":"عمرو (بن حارث)نے ابن شہاب (زہری)سے خبر دی، انھوں نے کہا: مجھے سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب رات کا کھانا پیش کر دیا جائے اور نماز کا (بھی)وقت ہو جائے تو مغرب کی نماز پڑھنے سے پہلے کھانے کی ابتدا کرو اور (نماز کے لیے)اپنا رات کا کھانا چھوڑ نے میں عجلت نہ کرو۔‘‘ (اس زمانے میں رات کا کھانا مغرب کے قریب ہی کھا یا جاتا تھا۔)"}],[1177,"ابن نمیر ، حفص اور وکیع نے ہشام سے ، انھوں نے اپنے والد سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے واسطے سے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی جس طرح ابن عیینہ نے زہر ی سے اور انھوں نےسیدنا انس رضی اللہ عنہ سے بیان کی ۔","",{"u2":"ابن نمیر، حفص اور وکیع نے ہشام سے، انھوں نے اپنے والد سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا کے واسطے سے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی جس طرح ابن عیینہ نے زہر ی سے اور انھوں نےسیدنا انس رضی اللہ عنہ سے بیان کی۔"}],[1178,"سیدنا عبداللہ بن عمر ؓ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ” جب تم میں سے کسی کے سامنے شام کا کھانا رکھا جائے ادھر نماز کھڑی ہو تو پہلے کھانا کھا لے اور نماز کے لئے جلدی نہ کرے جب تک کھانے سے فارغ نہ ہو ۔ “","",{"u2":"عبد اللہ نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ‘انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب تم میں ےسے کسی کا رات کا کھانا لگا دیا جائے اور نماز کے لیے اقامت ہو جائے تو کھانے سے ابتدا کرو اوروہ (شخص)نماز کےلیے ہرگز جلدی نہ کرےیہاں تک کہ اس کھانے سے فارغ ہو جائے۔‘‘"}],[1179,"موسیٰ بن عقبہ ، ابن جریج اور ایوب سب نے نافع سے ، انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے مذکورہ بالا روایت کی طرح روایت بیان کی ۔","",{"u2":"موسیٰ بن عقبہ، ابن جریج اور ایوب سب نے نافع سے، انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے مذکورہ بالا روایت کی طرح روایت بیان کی۔"}],[1180,"حاتم بن اسماعیل نے ( ابو حزرہ ) یعقوب بن مجاہد سے ، انھوں ابن ابی عتیق ( عبداللہ بن محمد بن عبدالرحمان بن ابی بکر صدیق ) سے روایت کی ، کہا : میں نے اور قاسم ( بن محمد بن ابی بکر صدیق ) نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا کے پاس ( بیٹھے ہوئے ) گفتگو کی ۔ قاسم زبان کی شدید غلطیاں کرنے والے انسان تھے ، وہ ایک کنیز کے بیٹے تھے ، سیدہ عائشہ رضی اللہ تعالی عنہا نے اس سے کہا : کیا بات ہے تم میرے اس بھتیجے کی طرح کیوں گفتگو نہیں کرتے ؟ ہا ں ، میں جانتی ہوں ( تم میں ) یہ بات کہاں سے آئی ہے ، اس کو اس کی ماں نے ادب ( گفتگو کا طریقہ ) سکھایا اورتمھیں تمھاری ماں نے سکھایا ۔ اس پر قاسم ناراض ہو گئے اور ان کے خلاف دل میں غصہ کیا ، پھر جب انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا کا دسترخوان آتے دیکھا تو اٹھ کھڑے ہوئے ۔ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے پوچھا : کہاں جاتے ہو؟ انھوں نے کہا : میں نماز پڑھنے لگا ہوں ۔ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : بیٹھ جاؤ ۔ انھوں نے کہا : میں نے نماز پڑھنی ہے ۔ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : بیٹھ جاؤ ، دھوکےباز! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ’’کھانا سامنے آجائے تو نماز نہیں ۔ اور نہ وہ ( شخص نماز پڑھے ) جس پر پیشاب پاخانہ کی ضرورت غالب آرہی ہو ۔ ‘‘","",{"u2":"حاتم بن اسماعیل نے (ابو حزرہ) یعقوب بن مجاہد سے، انھوں ابن ابی عتیق (عبداللہ بن محمد بن عبدالرحمان بن ابی بکر صدیق)سے روایت کی، کہا: میں نے اور قاسم (بن محمد بن ابی بکر صدیق)نے حضرت عائشہ رضی اللہ تعالیٰ عنہا کے پاس (بیٹھے ہوئے)گفتگو کی۔ قاسم زبان کی شدید غلطیاں کرنے والے انسان تھے، وہ ایک کنیز کے بیٹے تھے، حضرت عائشہ رضی اللہ تعالی عنہا نے اس سے کہا: کیا بات ہے تم میرے اس بھتیجے کی طرح کیوں گفتگو نہیں کرتے؟ ہا ں، میں جانتی ہوں (تم میں)یہ بات کہاں سے آئی ہے، اس کو اس کی ماں نے ادب (گفتگو کا طریقہ)سکھایا اورتمھیں تمھاری ماں نے سکھایا۔ اس پر قاسم ناراض ہو گئے اور ان کے خلاف دل میں غصہ کیا، پھر جب انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا کا دسترخوان آتے دیکھا تو اٹھ کھڑے ہوئے۔ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے پوچھا: کہاں جاتے ہو؟ انھوں نے کہا: میں نماز پڑھنے لگا ہوں۔ عائشہ رضی اللہ تعالیٰ عنہا نے کہا: بیٹھ جاؤ۔ انھوں نے کہا: میں نے نماز پڑھنی ہے۔ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا: بیٹھ جاؤ، دھوکےباز! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:’’کھانا سامنے آجائے تو نماز نہیں۔ اور نہ وہ (شخص نماز پڑھے)جس پر پیشاب پاخانہ کی ضرورت غالب آرہی ہو۔‘‘"}],[1181,"اسماعیل بن جعفر نے کہا : مجھے ابو حزرہ القاص ( یققوب بن مجاہد ) نے عبداللہ بن ابی عتیق سے خبر دی ، انھوں نے سیدہ عائشہ رضی اللہ تعالی عنہا سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی اور حدیث میں قاسم کا واقعہ بیان نہ کیا ۔","",{"u2":"اسماعیل بن جعفر نے کہا: مجھے ابو حزرہ القاص (یققوب بن مجاہد)نے عبداللہ بن ابی عتیق سے خبر دی، انھوں نے حضرت عائشہ رضی اللہ تعالی عنہا سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی اور حدیث میں قاسم کا واقعہ بیان نہ کیا۔"}],[1182,"محمد بن مثنیٰ اور زہیر بن حرب دونوں نے کہا : یحییٰ قطان نے ہمیں عبیداللہ سے حدیث بیان کی ، انھوں نے کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوؤ خیبر کے موقع پر فرمایا : ’’جس نے اس پودے ۔ آپ کی مراد لہسن تھا ۔ میں سے کچھ کھایا ہو وہ مسجدوں میں ہرگز نہ آئے ۔ ‘‘ زہیر نے صرف غزوہ کہا ، خیبر کا نام نہیں لیا ۔","",{"u2":"محمد بن مثنیٰ اور زہیر بن حرب دونوں نے کہا: یحییٰ قطان نے ہمیں عبیداللہ سے حدیث بیان کی، انھوں نے کہا: مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوؤ خیبر کے موقع پر فرمایا: ’’جس نے اس پودے۔ آپ کی مراد لہسن تھا۔ میں سے کچھ کھایا ہو وہ مسجدوں میں ہرگز نہ آئے۔‘‘\nزہیر نے صرف غزوہ کہا، خیبر کا نام نہیں لیا۔"}],[1183,"عبداللہ بن نمیر نے کہا : ہم سے عبید اللہ نے حدیث بیان کی ، انھوں نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس نے اس ترکاری میں سے کچھ کھایا ہو وہ ہماری مسجدوں کے قریب نہ آئے یہاں تک کہ اس کی بوچلی جائے ۔ ‘‘ آپ کی مراد لہسن سے تھی ۔","",{"u2":"عبداللہ بن نمیر نے کہا: ہم سے عبید اللہ نے حدیث بیان کی، انھوں نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے اس ترکاری میں سے کچھ کھایا ہو وہ ہماری مسجدوں کے قریب نہ آئے یہاں تک کہ اس کی بوچلی جائے۔ ‘‘ آپ کی مراد لہسن سے تھی۔"}],[1184,"عبدالعزیز سے ، جو صہیب کے بیٹے ہیں ، روایت ہے کہ سیدنا انس رضی اللہ عنہ سے لہسن کے بارے میں پوچھا گیا تو انھوں نے جواب دیا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس نے اس پودے میں سے کچھ کھایا ہو وہ ہرگز ہمارے قریب نہ آئے اور نہ ہمارے ساتھ نماز پڑھے ۔ ‘‘","",{"u2":") عبدالعزیز سے، جو صہیب کے بیٹے ہیں، روایت ہے کہ سیدنا انس رضی اللہ عنہ سے لہسن کے بارے میں پوچھا گیا تو انھوں نے جواب دیا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے اس پودے میں سے کچھ کھایا ہو وہ ہرگز ہمارے قریب نہ آئے اور نہ ہمارے ساتھ نماز پڑھے۔‘‘"}],[1185,"ابو زبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے پیاز اور گندنا کھا نے سے منع فرمایا ۔ سو ( ایک مرتبہ ) ہم ضرورت سے مجبور ہو گئے اور انھیں کھا لیا تو آپ نے فرمایا : ’’جس نے اس بدبودار سبزی میں سے کچھ کھایا ہو وہ ہرگز ہماری مسجد کے قریب نہ آئے ، فرشتے بھی یقیناً اس چیز سے تکلیف محسوس کرتے ہیں جس سے انسان تکلیف محسوس کرتے ہیں ۔ ‘‘","",{"u2":"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے اس پودے میں سے کچھ کھایا ہو وہ ہرگز ہماری مسجد کے قریب نہ آئے اور نہ ہمیں لہسن کی بو سے تکلیف دے۔‘‘"}],[1186,"ابو طاہر اور حرملہ نے کہا : ہمیں ابن وہب نے خبر دی ، کہا : مجھے یونس نے ابن شہاب سے خبر دی ، انھوں نے کہا : مجھے عطاء بن ابی رباح نے حدیث بیان کی کہ سیدنا جابر بن عبداللہ رضی اللہ عنہ نےکہا ۔ حرملہ کی روایت میں ہے ، ان ( جابر رضی اللہ عنہ ) کو یقین تھا ۔ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس نے لہسن یا پیاز کھایا وہ ہم سے دور رہے یا ہماری مسجدوں سے دور رہے اور اپنے گھر بیٹھے ۔ ‘‘ اور ایسا ہو ا کہ ( ایک دفعہ ) آپ کے پاس ایک ہانڈی لائی گئی جس میں کچھ سبز ترکاریاں تھیں ، آپ نے ان سے کچھ بو محسوس کی تو ان کے متعلق پوچھا ۔ آپ کو ان ترکاریوں کے بارے میں بتایا گیا جو اس میں ( ڈالی گئی ) تھیں تو آپ نے اسے ، اپنے ساتھیوں میں سے ایک کے پاس لے جانے کو کہا ۔ جب اس نے بھی اسے دیکھ کر ( آپ کی ناپسندیدگی کی بنا پر ) اس کو ناپسند کیا تو آپ نے فرمایا : ’’تم کھا لو کیونکہ میں ان سے سرگوشی کرتا ہوں جن سے تم سرگوشی نہیں کرتےہو ۔ ‘‘ ( اس سے فرشتے مراد ہیں ۔ صحیح ابن خزیمہ اور صحیح ابن حبان کی روایت میں اس بات کی صراحت موجود ہے ۔)","",{"u2":"ابو زبیر نے سیدنا جابر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے پیاز اور گندنا کھا نے سے منع فرمایا۔ سو (ایک مرتبہ)ہم ضرورت سے مجبور ہو گئے اور انھیں کھا لیا تو آپ نے فرمایا: ’’جس نے اس بدبودار سبزی میں سے کچھ کھایا ہو وہ ہرگز ہماری مسجد کے قریب نہ آئے، فرشتے بھی یقیناً اس چیز سے تکلیف محسوس کرتے ہیں جس سے انسان تکلیف محسوس کرتے ہیں۔‘‘"}],[1187,"یحییٰ بن سعید نے ابن جریج سے حدیث بیان کی ، انھوں کہا : مجھے عطاء نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے یہ ترکاری لہسن کھا یا ۔ ‘‘ اور ایک دفعہ فرمایا : ’’ جس نے پیاز ، لہسن اور گندنا کھایا ۔ تو وہ ہر گز ہماری مسجد کے قریب نہ آئے کیونکہ فرشتے ( بھی ) ان چیزوں سے اذیت محسوس کرتے ہیں جس جن سے آدم کے بیٹے اذیت محسوس کرتے ہیں ۔ ‘‘","",{"u2":"ابو طاہر اور حرملہ نے کہا: ہمیں ابن وہب نے خبر دی، کہا: مجھے یونس نے ابن شہاب سے خبر دی، انھوں نے کہا: مجھے عطاء بن ابی رباح نے حدیث بیان کی کہ سیدنا جابر بن عبداللہ رضی اللہ عنہ نےکہا۔ حرملہ کی روایت میں ہے، ان (جابر رضی اللہ عنہ)کو یقین تھا۔ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے لہسن یا پیاز کھایا وہ ہم سے دور رہے یا ہماری مسجدوں سے دور رہے اور اپنے گھر بیٹھے۔‘‘ اور ایسا ہو ا کہ (ایک دفعہ)آپ کے پاس ایک ہانڈی لائی گئی جس میں کچھ سبز ترکاریاں تھیں، آپ نے ان سے کچھ بو محسوس کی تو ان کے متعلق پوچھا۔ آپ کو ان ترکاریوں کے بارے میں بتایا گیا جو اس میں (ڈالی گئی)تھیں تو آپ نے اسے، اپنے ساتھیوں میں سے ایک کے پاس لے جانے کو کہا۔ جب اس نے بھی اسے دیکھ کر (آپ کی ناپسندیدگی کی بنا پر)اس کو ناپسند کیا تو آپ نے فرمایا: ’’تم کھا لو کیونکہ میں ان سے سرگوشی کرتا ہوں جن سے تم سرگوشی نہیں کرتےہو۔ ‘‘ (اس سے فرشتے مراد ہیں۔ صحیح ابن خزیمہ اور صحیح ابن حبان کی روایت میں اس بات کی صراحت موجود ہے۔)"}],[1189,"محمد بن بکر اور عبدالرزاق نے ( دو مختلف سندوں سے روایت کرتے ہوئے ) کہا : ہمیں ابن جریج نے اسی ( سابقہ ) سند کے ساتھ خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس نے اس پودے ۔ آپ کی مراد لہسن سے تھی ۔ میں سے کچھ کھایا ہو وہ ہماری مسجد میں ہمارے پاس نہ آئے ۔ ‘‘ اور انھوں ( ابن جریج ) نے پیاز اور گندنے کا ذکر نہیں کیا ۔","",{"u2":"محمد بن بکر اور عبدالرزاق نے (دو مختلف سندوں سے روایت کرتے ہوئے)کہا: ہمیں ابن جریج نے اسی (سابقہ)سند کے ساتھ خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے اس پودے۔ آپ کی مراد لہسن سے تھی۔ میں سے کچھ کھایا ہو وہ ہماری مسجد میں ہمارے پاس نہ آئے۔‘‘ اور انھوں (ابن جریج)نے پیاز اور گندنے کا ذکر نہیں کیا۔"}],[1190,"سیدنا ابو سعید رضی اللہ عنہ سے روایت ہے ، انھون نے کہا : ہم خیبر کی فتح سے فارغ نہیں ہوئے تھے کہ ہم ، رسول اللہ صلی اللہ علیہ وسلم کے ساتھی ، اس ترکاری ۔ لہسن ۔ پر جا پڑے ، لوگ بھوکے تھے اورہم نے اسے خوب اچھی طرح کھایا ، پھر ہم مسجد کی طرف گئے تو رسول اللہ صلی اللہ علیہ وسلم نے بومحسوس کی ۔ آپ نے فرمایا : ’’جس نے اس بدبودار پودے میں سے کچھ کھایا ہے وہ مسجد میں ہمارے قر یب نہ آئے ۔ ‘‘ اس پر لوگ کہنے لگے : ( لہسن ) حرام ہو گیا ، حرام ہو گیا ۔ یہ بات نبی صلی اللہ علیہ وسلم تک پہنچی تو آپ نے فرمایا : ’’ اے لوگو! ایسی چیز کو حرام کرنا میرے ہاتھ میں نہیں جسے اللہ نے میرے لیے حلال کر دیا ہے لیکن یہ ایسا پودا ہے جس کی بو مجھے ناپسند ہے ۔ ‘‘","",{"u2":"سیدنا ابو سعید رضی اللہ عنہ سے روایت ہے، انھون نے کہا: ہم خیبر کی فتح سے فارغ نہیں ہوئے تھے کہ ہم، رسول اللہ صلی اللہ علیہ وسلم کے ساتھی، اس ترکاری۔ لہسن۔ پر جا پڑے، لوگ بھوکے تھے اورہم نے اسے خوب اچھی طرح کھایا، پھر ہم مسجد کی طرف گئے تو رسول اللہ صلی اللہ علیہ وسلم نے بومحسوس کی۔ آپ نے فرمایا: ’’جس نے اس بدبودار پودے میں سے کچھ کھایا ہے وہ مسجد میں ہمارے قر یب نہ آئے۔‘‘ اس پر لوگ کہنے لگے: (لہسن)حرام ہو گیا، حرام ہو گیا۔ یہ بات نبی صلی اللہ علیہ وسلم تک پہنچی تو آپ نے فرمایا: ’’ اے لوگو! ایسی چیز کو حرام کرنا میرے ہاتھ میں نہیں جسے اللہ نے میرے لیے حلال کر دیا ہے لیکن یہ ایسا پودا ہے جس کی بو مجھے ناپسند ہے۔‘‘"}],[1191,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ ( ایک دفعہ ) پیاز کے ایک کھیت کے پاس سے گزرے ۔ ان میں سے کچھ لوگ اترے اور اس میں سے کچھ کھا لیا ، اور دوسروں نے نہ کھایا ۔ ہم آپ کے پاس گئے تو آپ نے ان لوگوں کو ( قریب ) بلا لیا جنھوں نے پیاز نہیں کھا یا تھا اور دوسرے ( جنھوں نے پیاز کھایا تھا ) انھیں پیچھے کر دیا یہاں تک کہ اس کی بو ختم ہو گئی ۔","",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ (ایک دفعہ)پیاز کے ایک کھیت کے پاس سے گزرے۔ ان میں سے کچھ لوگ اترے اور اس میں سے کچھ کھا لیا، اور دوسروں نے نہ کھایا۔ ہم آپ کے پاس گئے تو آپ نے ان لوگوں کو (قریب)بلا لیا جنھوں نے پیاز نہیں کھا یا تھا اور دوسرے (جنھوں نے پیاز کھایا تھا) انھیں پیچھے کر دیا یہاں تک کہ اس کی بو ختم ہو گئی۔"}],[1192,"ہشام نےکہا : ہم سے قتادہ نے حدیث بیان کی ، انھوں نے سالم بن ابی جعد سے اور انھوں نے سیدنا معد ان بن ابی طلحہ رضی اللہ عنہ سے روایت کی کہ عمر بن خطاب رضی اللہ عنہ نے جمعے کے دن خطبہ دیا اور نبی اکرم صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کا تذکرہ کیا ، کہا : میں نے خواب دیکھا ہے ، جیسے ایک مرغ نے مجھے تین ٹھونگیں ماری ہیں اور اس کو میں اپنی موت قریب آنے کے سوا اور کچھ نہیں سمجھتا ۔ اور کچھ قبائل مجھ سے مطالبہ کر رہے ہیں کہ میں کسی کو اپنا جانشین بنادو ں ۔ بلا شبہ اللہ تعالیٰ اپنے دین کو ضائع نہیں ہونے دے گا ، نہ اپنی خلافت کو اور نہ اس شریعت کو جس کے ساتھ اس نے اپنے نبی صلی اللہ علیہ وسلم کو مبعوث فرمایا ۔ اگر مجھے جلد موت آجائے تو خلافت ان چھ حضرات کے باہیم مشورے سے طے ہو گی جن سے رسول اللہ صلی اللہ علیہ وسلم اپنی وفات کے وقت خوش تھے ۔ اور میں جانتا ہوں کہ کچھ لوگ جن کو میں نے اسلام کی خاطر اپنے اس ہاتھ سے مارا ہے ، وہ اس امر ( خلافت ) پر اعتراض کریں گے ، اگر وہ ایسا کریں گے تو وہ اللہ کے دشمن ، کافر اور گمراہ ہوں گے ، پھر میں اپنے بعد جو ( حل طلب ) چیزیں چھوڑ کر جارہا ر ہوں ان میں سے میرے نزدیک کلالہ کی وراثت کے مسئلے سے بڑھ کر کوئی مسئلہ زیادہ اہم نہیں ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کسی مسئلے کے بارے میں اتنی دفعہ رجوع نہیں کیا جتنی دفعہ کلالہ کے بارے میں کیا اور آپ نے ( بھی ) میرے ساتھ کسی مسئلے میں اس قدر سختی نہیں برتی جتنی میرے ساتھ آپ نے اس مسئلے میں سختی کی حتیٰ کہ آپ نے انگلی میرے سینے میں چبھو کر فرمایا : ’’اے عمر ! کیا گرمی کے موسم میں اترنے والی آیت تمھارے لیے کافی نہیں جو سورۃ نساء کے آخر میں ہے ؟ ‘‘ میں اگر زندہ رہا تو میں اس مسئلے ( کلالہ ) کے بارے میں ایسا فیصلہ کروں گا کہ ( ہر انسان ) جو قرآن پڑھتا ہے یا نہیں پڑھتا ہے اس کے مطابق فیصلہ کر سکے گا ، پھر آپ نے فرمایا : اے اللہ ! میں شہروں کے گورنرون کے بارے میں تجھے گواہ بناتا ہوں کہ میں نے لوگوں پر انھیں صرف اس لیے مقرر کر کے بھیجا کہ وہ ان سے انصاف کریں اور لوگوں کو ان کے دین اور ان کے نبی صلی اللہ علیہ وسلم کی سنت کی تعلیم دیں اور ان کے اموال فے ان میں تقسیم کریں اور اگر لوگوں کے معاملات میں انھیں کوئی مشکل پیش آئے تو اسے میرے سامنے پیش کریں ۔ پھر اے لوگو! تم دو پودے کھا تے ہو ، میں انھیں ( بو کے اعتبار سے ) برے پودے ہی سمجھتا ہوں ، یہ پیاز اور لہسن ہیں ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، جب مسجد میں آپ کو کسی آدمی سے ان کی بوآتی تو آپ اسے بقیع کی طرف نکال دینے کا حکم صادر فرماتے ، لہٰذا جو شخص انھیں کھانا چاہتا ہے وہ انھیں پکاکر ان کی بو مار دے ۔","",{"u2":"ہشام نےکہا: ہم سے قتادہ نے حدیث بیان کی، انھوں نے سالم بن ابی جعد سے اور انھوں نے سیدنا معد ان بن ابی طلحہ رضی اللہ عنہ سے روایت کی کہ عمر بن خطاب رضی اللہ عنہ نے جمعے کے دن خطبہ دیا اور نبی اکرم صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کا تذکرہ کیا، کہا: میں نے خواب دیکھا ہے، جیسے ایک مرغ نے مجھے تین ٹھونگیں ماری ہیں اور اس کو میں اپنی موت قریب آنے کے سوا اور کچھ نہیں سمجھتا۔ اور کچھ قبائل مجھ سے مطالبہ کر رہے ہیں کہ میں کسی کو اپنا جانشین بنادو ں۔ بلا شبہ اللہ تعالیٰ اپنے دین کو ضائع نہیں ہونے دے گا، نہ اپنی خلافت کو اور نہ اس شریعت کو جس کے ساتھ اس نے اپنے نبی صلی اللہ علیہ وسلم کو مبعوث فرمایا۔ اگر مجھے جلد موت آجائے تو خلافت ان چھ حضرات کے باہیم مشورے سے طے ہو گی جن سے رسول اللہ صلی اللہ علیہ وسلم اپنی وفات کے وقت خوش تھے۔ اور میں جانتا ہوں کہ کچھ لوگ جن کو میں نے اسلام کی خاطر اپنے اس ہاتھ سے مارا ہے، وہ اس امر (خلافت)پر اعتراض کریں گے، اگر وہ ایسا کریں گے تو وہ اللہ کے دشمن، کافر اور گمراہ ہوں گے، پھر میں اپنے بعد جو (حل طلب)چیزیں چھوڑ کر جارہا ر ہوں ان میں سے میرے نزدیک کلالہ کی وراثت کےمسئلے سے بڑھ کر کوئی مسئلہ زیادہ اہم نہیں۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کسی مسئلے کے بارے میں اتنی دفعہ رجوع نہیں کیا جتنی دفعہ کلالہ کے بارے میں کیا اور آپ نے (بھی)میرے ساتھ کسی مسئلے میں اس قدر سختی نہیں برتی جتنی میرے ساتھ آپ نے اس مسئلے میں سختی کی حتیٰ کہ آپ نے انگلی میرے سینے میں چبھو کر فرمایا: ’’اے عمر! کیا گرمی کے موسم میں اترنے والی آیت تمھارے لیے کافی نہیں جو سورۃ نساء کے آخر میں ہے؟ ‘‘ میں اگر زندہ رہا تو میں اس مسئلے (کلالہ)کے بارے میں ایسا فیصلہ کروں گا کہ (ہر انسان)جو قرآن پڑھتا ہے یا نہیں پڑھتا ہے اس کے مطابق فیصلہ کر سکے گا، پھر آپ نے فرمایا: اے اللہ! میں شہروں کے گورنرون کے بارے میں تجھے گواہ بناتا ہوں کہ میں نے لوگوں پر انھیں صرف اس لیے مقرر کر کے بھیجا کہ وہ ان سے انصاف کریں اور لوگوں کو ان کے دین اور ان کے نبی صلی اللہ علیہ وسلم کی سنت کی تعلیم دیں اور ان کے اموال فے ان میں تقسیم کریں اور اگر لوگوں کے معاملات میں انھیں کوئی مشکل پیش آئے تو اسے میرے سامنے پیش کریں۔ پھر اے لوگو! تم دو پودے کھا تے ہو، میں انھیں (بو کے اعتبار سے) برے پودے ہی سمجھتا ہوں، یہ پیاز اور لہسن ہیں۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، جب مسجد میں آپ کو کسی آدمی سے ان کی بوآتی تو آپ اسے بقیع کی طرف نکال دینے کا حکم صادر فرماتے، لہذا جو شخص انھیں کھانا چاہتا ہے وہ انھیں پکاکر ان کی بو مار دے۔"}],[1193,"سعید بن ابی عروبہ اور شعبہ نے قتادہ سے اسی سند کے ساتھی اسی کے مانند روایت کی","",{"u2":"سعید بن ابی عروبہ اور شعبہ نے قتادہ سے اسی سند کے ساتھی اسی کے مانند روایت کی"}],[1194,"ابن وہب نےہمیں حدیث سنائی ، انھوں نے حیوہ سے ، انھوں نے محمد بن عبدالرحمن سے ، انھوں نے شدادبن ہاد کے آزاد کردہ غلام ابو عبداللہ سے روایت کی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جوشخص کسی آدمی کو مسجد میں کسی گم شدہ جانور کے بارے میں اعلان کرتے ہوئے سنے تو وہ کہے : اللہ تمھارا جانور تمھیں نہ لوٹائے کیونکہ مسجدیں اس کام کے لیے نہیں بنائی گئیں ۔ ‘‘","",{"u2":"ابن وہب نےہمیں حدیث سنائی، انھوں نے حیوہ سے، انھوں نے محمد بن عبدالرحمن سے، انھوں نے شدادبن ہاد کے آزاد کردہ غلام ابو عبداللہ سے روایت کی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جوشخص کسی آدمی کو مسجد میں کسی گم شدہ جانور کے بارے میں اعلان کرتے ہوئے سنے تو وہ کہے: اللہ تمھارا جانور تمھیں نہ لوٹائے کیونکہ مسجدیں اس کام کے لیے نہیں بنائی گئیں۔‘‘"}],[1195,"(ابن وہب کے بجائے ) مقری نے حیوہ سے باقی ماندہ اسی سند کےساتھ اسی کے مانند حدیث بیان کی","",{"u2":")(ابن وہب کے بجائے)مقری نے حیوہ سے باقی ماندہ اسی سند کےساتھ اسی کے مانند حدیث بیان کی"}],[1196,"سفیان ثوری نے ہمیں خبر دی ، انھوں نے علقمہ بن مرثد سے ، انھوں نے سلیمان بن بریدہ سے اور انھوں نے اپنے والد ( بریدہ بن حصیب اسلمی رضی اللہ عنہ ) سے روایت کی کہ ایک آدمی نے مسجد میں اعلان کیا اور کہا : جو سرخ اونٹ ( کی نشاندہی ) کے لیے آواز دے گا ۔ تو نبی صلی اللہ علیہ وسلم فرمانے لگے : ’’تجھے ( تیرا اونٹ ) نہ ملے ، مسجدیں صرف انھی کاموں کے لیے بنائی گئی ہیں جن کے لیے انھیں بنایا گیا ۔ ‘‘ ( یعنی عبادت اور اللہ کے ذکر کے لیے ۔)","",{"u2":"سفیان ثوری نے ہمیں خبر دی، انھوں نے علقمہ بن مرثد سے، انھوں نے سلیمان بن بریدہ سے اور انھوں نے اپنے والد (بریدہ بن حصیب اسلمی رضی اللہ عنہ)سے روایت کی کہ ایک آدمی نے مسجد میں اعلان کیا اور کہا: جو سرخ اونٹ(کی نشاندہی)کے لیے آواز دے گا۔ تو نبی صلی اللہ علیہ وسلم فرمانے لگے: ’’تجھے (تیرا اونٹ)نہ ملے، مسجدیں صرف انھی کاموں کے لیے بنائی گئی ہیں جن کے لیے انھیں بنایا گیا۔ ‘‘ (یعنی عبادت اور اللہ کے ذکر کے لیے۔)"}],[1197,"ابو سنان نے علقمہ بن مرثد سے ، انھوں نے سلیمان بن بریدہ سے اور انھوں نے اپنے والد سے روایت کی کہ ( ایک بار ) جب نبی صلی اللہ علیہ وسلم نے نماز پڑھائی تو ایک آدمی نے کھڑے ہو کر کہا : جو سرخ اونٹ ( کی نشاندہی ) کے لیے آواز دے گل ۔ تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’تم ( اپنا اونٹ ) نہ پاؤ ، مساجد صرف انھی کاموں کے لیے بنائی گئی ہیں جن کے لیے انھیں بنایا گیا ۔ ‘‘","",{"u2":"ابو سنان نے علقمہ بن مرثد سے، انھوں نے سلیمان بن بریدہ سے اور انھوں نےاپنے والد سے روایت کی کہ (ایک بار)جب نبی صلی اللہ علیہ وسلم نے نمازپڑھائی تو ایک آدمی نے کھڑے ہو کر کہا: جو سرخ اونٹ (کی نشاندہی)کے لیے آواز دے گل۔ تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’تم (اپنا اونٹ)نہ پاؤ، مساجد صرف انھی کاموں کے لیے بنائی گئی ہیں جن کے لیے انھیں بنایا گیا۔‘‘"}],[1198,"محمد بن شیبہ نے علقمہ بن مرثد سے ، انھوں نے ( سلیمان ) بن بریدہ سے اور انھوں نے اپنے والد سے روایت کی کہ جب نبی اکرم صلی اللہ علیہ وسلم صبح کی نماز پڑھ چکے تو ایک بدوی آیا اور مسجد کے دروازے سے اپنا سر اندر کیا ......پھر ان دونوں کی حدیث کی طرح بیان کیا ۔ امام مسلم رضی اللہ عنہ نے کہا : محمد بن شیبہ سے مراد ابو نعامہ شیبہ بن نعامہ ہے جس سے مسعر ، ہشیم ، جریر اور دوسرے کوفی راویوں نے روایت کی ۔","",{"u2":"محمد بن شیبہ نے علقمہ بن مرثد سے، انھوں نے (سلیمان)بن بریدہ سے اور انھوں نے اپنے والد سے روایت کی کہ جب نبی اکرم صلی اللہ علیہ وسلم صبح کی نماز پڑھ چکے تو ایک بدوی آیا اور مسجد کے دروازے سے اپنا سر اندر کیا ......پھر ان دونوں کی حدیث کی طرح بیان کیا۔\nامام مسلم رحمہ اللہ نے کہا: محمد بن شیبہ سے مراد ابو نعامہ شیبہ بن نعامہ ہے جس سے مسعر، ہشیم، جریر اور دوسرے کوفی راویوں نے روایت کی۔"}],[1199,"امام مالک نے ابن شہاب ( زہری ) سے ، انھوں نے ابوسلمہ بن عبدالرحمن سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’بلا شبہ تم میں سے کوئی جب نماز پڑھنے کے لیے کھڑا ہوتا ہے تو شیطان آکر اسے التباس ( شبہ ) میں ڈالتا ہے حتی کہ وہ نہیں جانتا کہ اس نے کتنی ( رکعتیں ) پڑھی ہیں ۔ تم میں سے کوئی جب یہ ( کیفیت ) پائے تووہ ( آخری تشہد میں ) بیٹھے ہوئے دو سجدے کر لے ۔ ‘‘","",{"u2":"امام مالک نے ابن شہاب (زہری)سے، انھوں نے ابوسلمہ بن عبدالرحمن سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلا شبہ تم میں سے کوئی جب نماز پڑھنے کے لیے کھڑا ہوتا ہے تو شیطان آکر اسے التباس (شبہ)میں ڈالتا ہے حتی کہ وہ نہیں جانتا کہ اس نے کتنی (رکعتیں)پڑھی ہیں۔ تم میں سے کوئی جب یہ (کیفیت) پائے تووہ (آخری تشہد میں)بیٹھے ہوئے دو سجدے کر لے۔‘‘"}],[1200,"سفیان بن عیینہ اور لیث بن سعد نے زہری سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ہے ۔","",{"u2":"سفیان بن عیینہ اور لیث بن سعد نے زہری سے اسی سند کے ساتھ اسی طرح حدیث بیان کی ہے۔"}],[1201,"یحییٰ بن ابی کثیر سے روایت ہے ، کہا : ہمیں ابو سلمہ بن عبدالرحمن نے حدیث سنائی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے انھیں حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب اذان کہی جاتی ہے تو شیطان پیٹھ پھیر کر بھاگتا ہے گوزمار رہا ہوتا ہے تاکہ اذان ( کی آواز ) نہ سنے ۔ جب اذان ختم ہو جاتی ہے تو ( واپس ) آتا ہے ، پھر جب نماز کے لیے تکبیر کہی جاتی ہے تو پیٹھ پھیر کر بھاگ جاتا ہے ، جب تکبیر ختم ہو جاتی ہے تو آجاتا ہے تاکہ انسان اور اس کے دل کے درمیان خیال آرائی شروع کروائے ، وہ کہتا ہے : فلاں بات یاد کرو ، فلاں چیز یاد کرو ۔ وہ چیزیں ( اسے یاد کراتا ہے ) جو اسے یاد نہیں ہوتیں حتی کہ وہ شخص یوں ہو جاتا ہے کہ اسے یا د نہیں رہتا اس نے کتنی رکعتیں پڑھی ہیں ، چنانچہ جب تم میں سے کسی کو یاد نہ رہے کہ اس نے کتنی رکعتیں پڑھی ہیں تو وہ ( تشہد میں ) بیٹھے بیٹھے دو سجدے کر لے ۔ ‘‘","",{"u2":") یحییٰ بن ابی کثیر سے روایت ہے، کہا: ہمیں ابو سلمہ بن عبدالرحمن نے حدیث سنائی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے انھیں حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب اذان کہی جاتی ہے تو شیطان پیٹھ پھیر کر بھاگتا ہے گوزمار رہا ہوتا ہے تاکہ اذان (کی آواز)نہ سنے۔ جب اذان ختم ہو جاتی ہے تو (واپس)آتا ہے، پھر جب نماز کے لیےتکبیر کہی جاتی ہے تو پیٹھ پھیر کر بھاگ جاتا ہے، جب تکبیر ختم ہو جاتی ہے تو آجاتا ہے تاکہ انسان اور اس کے دل کے درمیان خیال آرائی شروع کروائے، وہ کہتا ہے:فلاں بات یاد کرو، فلاں چیز یاد کرو۔ وہ چیزیں (اسے یاد کراتا ہے)جو اسے یاد نہیں ہوتیں حتی کہ وہ شخص یوں ہو جاتا ہے کہ اسے یا د نہیں رہتا اس نے کتنی رکعتیں پڑھی ہیں، چنانچہ جب تم میں سے کسی کو یاد نہ رہے کہ اس نے کتنی رکعتیں پڑھی ہیں تو وہ (تشہد میں)بیٹھے بیٹھے دو سجدے کر لے۔‘‘"}],[1202,"عبدالرحمن اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : ’’جب نماز کے لیے تکبیر کہی جاتی ہے تو شیطان پیٹھ پھیر کر گوز مارتا ہوا بھاگتا ہے ...... ‘‘ آگے اوپر کی روایت کی طرح ذکر کیا اور یہ اضافہ کیا : ’’اسے رغبت اور امید دلاتا ہے اور اسے اس کی ایسی ضرورتیں یاد دلاتا ہے جو اسے یاد نہیں ہوتیں ۔ ‘‘","",{"u2":"عبدالرحمن اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: ’’جب نماز کے لیے تکبیر کہی جاتی ہے تو شیطان پیٹھ پھیر کر گوز مارتا ہوا بھاگتا ہے ......‘‘ آگے اوپر کی روایت کی طرح ذکر کیا اور یہ اضافہ کیا: ’’اسے رغبت اور امید دلاتا ہے اور اسے اس کی ایسی ضرورتیں یاد دلاتا ہے جو اسے یاد نہیں ہوتیں۔‘‘"}],[1203,"مالک نے ابن شہاب سے ، انھوں نے عبدالرحمن اعرج سے اور انھوں نے سیدنا عبداللہ بن بحسینہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کسی ایک نماز کی دو رکعتیں پڑھائیں ، پھر ( تیسری کے لیے ) کھڑے ہو گئے اور ( درمیان کے تشہد کے لیے ) نہ بیٹھے تو لوگ بھی آپ کے ساتھ کھڑے ہو گئے ، جب آپ نے نماز پوری کر لی اور ہم آپ کے سلام کے انتظار مین تھے توآپ نے تکبیر کہی اور بیٹھے بیٹھے سلام سے پہلے دو سجدے کیے ، پھر سلام پھیر دیا ۔","",{"u2":"مالک نے ابن شہاب سے، انھوں نے عبدالرحمن اعرج سے اور انھوں نے سیدنا عبداللہ بن بحسینہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کسی ایک نماز کی دو رکعتیں پڑھائیں، پھر (تیسری کے لیے)کھڑے ہو گئے اور (درمیان کے تشہد کے لیے)نہ بیٹھے تو لوگ بھی آپ کے ساتھ کھڑے ہو گئے، جب آپ نے نماز پوری کر لی اور ہم آپ کے سلام کے انتظار مین تھے توآپ نے تکبیر کہی اور بیٹھے بیٹھے سلام سے پہلے دو سجدے کیے، پھر سلام پھیر دیا۔"}],[1204,"لیث نے ابن شہاب سے ، انھوں نے اعرج سے اور انھوں نے سیدنا عبداللہ بن بحسینہ اسدی رضی اللہ عنہ سے ، جو بنو بعدالمطلب کے حلیف تھے ، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ظہر کی نماز میں ، جب آپ کو ( دوسری رکعت کےبعد ) بیٹھنا تھا ، کھڑے ہوگئے ، پھر جب آپ نے اپنی نماز مکمل کر لی تو آپ نے بیٹھے بیٹھے ہر سجدے کے لیے تکبیر کہتے ہوئے سلام سے پہلے دو سجدے کیے ، اور لوگوں نے بھی ( تشہد کے لیے ) بیٹھے کی جگہ ، جو آپ بھول گئے تھے ، آپ کے ساتھ د و سجدے کیے ۔","",{"u2":"لیث نے ابن شہاب سے، انھوں نےاعرج سے اور انھوں نے سیدنا عبداللہ بن بحسینہ اسدی رضی اللہ عنہ سے، جو بنو بعدالمطلب کے حلیف تھے، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ظہر کی نماز میں، جب آپ کو (دوسری رکعت کےبعد)بیٹھنا تھا، کھڑے ہوگئے، پھر جب آپ نے اپنی نماز مکمل کر لی تو آپ نے بیٹھے بیٹھے ہر سجدے کے لیے تکبیر کہتےہوئے سلام سے پہلے دو سجدے کیے، اور لوگوں نے بھی (تشہد کے لیے)بیٹھے کی جگہ، جو آپ بھول گئے تھے، آپ کے ساتھ د و سجدے کیے۔"}],[1205,"(ابن شہاب کے بجائے ) یحییٰ بن سعید نے عبدالرحمن اعرج سے اور انھوں نے سیدنا عبداللہ بن مالک ابن بحسینہ ازدی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم دو رکعتوں کےبعد جہاں نماز میں آپ کا بیٹھنے کا ارادہ تھا ، ( وہاں ) کھڑے ہو گئے ، آپ نے اپنی نماز جاری رکھی ۔ پھر جب نماز کے آخرمیں پہنچے تو سلا م سے پہلے سجدے کیے ، اس کے بعد سلام پھیرا ۔","",{"u2":"ابن شہاب کے بجائے)یحییٰ بن سعید نے عبدالرحمن اعرج سے اور انھوں نے سیدنا عبداللہ بن مالک ابن بحسینہ ازدی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم دو رکعتوں کےبعد جہاں نماز میں آپ کا بیٹھنے کا ارادہ تھا، (وہاں)کھڑے ہو گئے، آپ نے اپنی نماز جاری رکھی۔پھر جب نماز کے آخرمیں پہنچے تو سلا م سے پہلے سجدے کیے، اس کے بعد سلام پھیرا۔"}],[1206,"سلیمان بن بلال نے زید بن اسلم سے ، انھوں نے عطاء بن یسار سے اور انھوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کسی کو اپنی نماز میں شک ہو جائے اور اسے معلوم نہ ہو کہ اس نے کتنی رکعتیں پڑھ لی ہیں ؟ تین یا چار ؟ تو وہ شک کو چھوڑ دے اور جتنی رکعتوں پر اسے یقین ہے ان پر بنیاد رکھے ( تین یقینی ہیں تو چوتھی پڑھ لے ) پھر سلام سے پہلے دو سجدے کر لے ، اگر اس نے پانچ رکعتیں پڑھ لی ہیں تو یہ سجدے اس کی نماز کو جفت ( چھ رکعتیں ) کر دیں گے ارو اگر اس نے چار کی تکمیل کر لی تھی تو یہ سجدے شیطان کی ذلت و رسوائی کا باعث ہوں گے ۔ ‘‘","",{"u2":"سلیمان بن بلال نے زید بن اسلم سے، انھوں نے عطاء بن یسار سے اور انھوں نے سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو اپنی نماز میں شک ہو جائے اور اسے معلوم نہ ہو کہ اس نے کتنی رکعتیں پڑھ لی ہیں؟ تین یا چار؟ تو وہ شک کو چھوڑ دے اور جتنی رکعتوں پر اسے یقین ہے ان پر بنیاد رکھے (تین یقینی ہیں تو چوتھی پڑھ لے)پھر سلام سے پہلے دو سجدے کر لے، اگر اس نے پانچ رکعتیں پڑھ لی ہیں تو یہ سجدے اس کی نماز کو جفت (چھ رکعتیں)کر دیں گے ارو اگر اس نے چار کی تکمیل کر لی تھی تو یہ سجدے شیطان کی ذلت و رسوائی کا باعث ہوں گے۔‘‘"}],[1207,"داؤد بن قیس نے زید بن اسلم سے اسی سند کے ساتھ روایت کی اور اس کے معنی کے مطابق یہ کہا : وہ ’’ ( نمازی ) سلام پھیرنے سے پہلے دو سجدے کر لے ۔ ‘‘ جس طرح سلیمان بن بلال نے کہا ۔","",{"u2":"داؤد بن قیس نے زید بن اسلم سے اسی سند کے ساتھ روایت کی اور اس کے معنی کے مطابق یہ کہا: وہ ’’(نمازی)سلام پھیرنے سے پہلے دو سجدے کر لے۔‘‘ جس طرح سلیمان بن بلال نے کہا۔"}],[1208,"جریر نے ہمیں حدیث بیان کی ، انھوں نے منصور سے ، انھوں نے ابراہیم سے اور انھوں نے علقمہ سے روایت کی ، کہا : سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی ۔ ابراہیم نے کہا : آپ نے اس میں زیادتی یا کمی کر دی ۔ پھر جب آپ نے سلام پھرا تو آپ سے عرض کی گئی : اے اللہ کے رسول ! کیا نماز میں کوئی نئی چیز ( تبدیلی ) آگئی ہے ؟ آپ نے پوچھا : ’’وہ کیا ؟ ‘‘ صحابہ نے عرض کی : آپ نے اتنی اتنی رکعتیں پڑھائی ہیں ۔ ( راوی نے کہا : ) آپ نے اپنے پاؤں موڑے ، قبلہ کی طرف رخ کیا اور دو سجدے کیے ، پھر سلام پھیرا ، پھر آپ نے ہماری طرف رخ کیا اور فرمایا : ’’اگر نماز میں کوئی نئی بات ہوتی تو میں تمھیں بتا دیتا ، لیکن میں ایک انسان ہوں ، جس طرح تم بھولتے ہو میں بھی بھول جاتا ہوں ، اس لیے جب میں بھول جاؤں تو مجھے یاد دلا دیا کرو اور جب تم میں سے کسی کو اپنی نماز کے بارے میں شک ہو جائے تو وہ صحیح کی جستجو کرے اور ا س کے مطابق ( نماز کی ) تکمیل کرے ، پھر ( سہو کے ) دو سجدے کر لے ۔ ‘‘","",{"u2":"جریر نے ہمیں حدیث بیان کی، انھوں نے منصور سے، انھوں نے ابراہیم سے اور انھوں نے علقمہ سے روایت کی، کہا: حضرت عبداللہ (بن مسعود رضی اللہ عنہ)نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی۔ابراہیم نے کہا: آپ نے اس میں زیادتی یا کمی کر دی۔ پھر جب آپ نے سلام پھرا تو آپ سے عرض کی گئی: اے اللہ کے رسول! کیانماز میں کوئی نئی چیز (تبدیلی)آگئی ہے؟ آپ نے پوچھا: ’’وہ کیا؟‘‘ صحابہ نے عرض کی: آپ نے اتنی اتنی رکعتیں پڑھائی ہیں۔(راوی نے کہا:)آپ نے اپنے پاؤں موڑے، قبلہ کی طرف رخ کیا اور دو سجدے کیے، پھر سلام پھیرا، پھر آپ نے ہماری طرف رخ کیا اور فرمایا:’’اگر نماز میں کوئی نئی بات ہوتی تو میں تمھیں بتا دیتا، لیکن میں ایک انسان ہوں، جس طرح تم بھولتے ہومیں بھی بھول جاتا ہوں، اس لیے جب میں بھول جاؤں تو مجھے یاد دلا دیا کرو اور جب تم میں سے کسی کو اپنی نماز کے بارے میں شک ہو جائے تو وہ صحیح کی جستجو کرے اور ا س کے مطابق (نماز کی)تکمیل کرے، پھر (سہو کے) دو سجدے کر لے۔‘‘"}],[1209,"ابن بشر اور وکیع دونوں نے مسعر سے اور انھوں نے منصور سے اسی سند کے ساتھ حدیث بیان کی ابن بشر کی روایت مین ہے : ’’وہ غور کرے کہ اس میں سے صحت کے قریب ترکیا ہے ؟ ‘‘ اور وکیع کی روایت میں ہے : ’’ وہ صحیح ( صورت کو یاد رکرنے ) کی جستجو کرے ۔ ‘‘","",{"u2":"ابن بشر اور وکیع دونوں نے مسعر سے اور انھوں نے منصور سے اسی سند کے ساتھ حدیث بیان کی ابن بشر کی روایت مین ہے: ’’وہ غور کرے کہ اس میں سے صحت کے قریب ترکیا ہے؟‘‘ اور وکیع کی روایت میں ہے: ’’ وہ صحیح (صورت کو یاد رکرنے)کی جستجو کرے۔‘‘"}],[1210,"وہیب بن خالد نے کہا : ہمیں منصور نے اسی سند کےس اتھ حدیث بیان کی ۔ منصور نے کہا : ’’وہ غور کرے کہ اس میں صحت کے قریب تر کیا ہے ۔ ‘‘"],[1211,"سفیان نے منصور سے مذکورہ سند کے ساتھ یہی حدیث بیان کی اور کہا : ’’وہ صحیح کی جستجو کرے","",{"u2":"سفیان نے منصور سے مذکورہ سند کے ساتھ یہی حدیث بیان کی اور کہا: ’’وہ صحیح کی جستجو کرے"}],[1212,"شعبہ نے منصور سے اسی سند کے ساتھ یہی حدیث بیان کی اور کہا : ’’ اس میں جو صحیح کے قریب تر ہے اس کی جستجو کرے ۔ ‘‘","",{"u2":"شعبہ نے منصور سے اسی سند کے ساتھ یہی حدیث بیان کی اور کہا:’’ اس میں جو صحیح کے قریب تر ہے اس کی جستجو کرے۔‘‘"}],[1213,"فضیل بن عیاض نے منصور سے اسی سند کے ساتھ خبر دی اور کہا : ’’وہ اس کی جستجو کرے جسے وہ صحیح سمجھتا ہے ۔ ‘‘","",{"u2":"فضیل بن عیاض نے منصور سے اسی سند کے ساتھ خبر دی اور کہا: ’’وہ اس کی جستجو کرے جسے وہ صحیح سمجھتا ہے۔‘‘"}],[1214,"عبدالعزیز بن عبد الصمد نے منصور سے ان سب راویوں کی سند کے ساتھ یہی حدیث بیان کی اور کہا : ’’وہ صحیح کی جستجو کرے","",{"u2":"عبدالعزیز بن عبد الصمد نے منصور سے ان سب راویوں کی سند کے ساتھ یہی حدیث بیان کی اور کہا:’’وہ صحیح کی جستجو کرے"}],[1215,"حکم نے ابراہیم سے ، انھوں نے علقمہ سے اور انھوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے ظہر کی نماز ( میں ) پانچ رکعات پڑھا دیں ، جب آپ نے سلام پھیر ا تو آپ سے عرض کی گئی : کیا نماز میں اضافہ کر دیا گیا ہے ؟ آپ نے فرمایا : ’’ وہ کیا ہے ؟ ‘‘ صحابہ نے کہا : آپ نے پانچ رکعات پڑھی ہیں ۔ توآپ نے دو سجدے کیے ۔","",{"u2":"حکم نے ابراہیم سے، انھوں نے علقمہ سے اور انھوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ)سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے ظہر کی نماز (میں)پانچ رکعات پڑھا دیں، جب آپ نے سلام پھیر ا تو آپ سے عرض کی گئی: کیا نماز میں اضافہ کر دیا گیا ہے؟ آپ نے فرمایا: ’’ وہ کیا ہے؟‘‘ صحابہ نے کہا: آپ نے پانچ رکعات پڑھی ہیں۔ توآپ نے دو سجدے کیے۔"}],[1216,"ابن نمیر نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن ادریس نے حسن بن عبید اللہ سے حدیث بیان کی ، انھوں نے ابراہیم ( بن سوید ) سے اور انھوں نے علقمہ سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے انھیں پانچ رکعات پڑھائیں ۔","",{"u2":"ابن نمیر نے ہمیں حدیث بیان کی، کہا: ہمیں ابن ادریس نے حسن بن عبید اللہ سے حدیث بیان کی، انھوں نے ابراہیم (بن سوید)سے اور انھوں نے علقمہ سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے انھیں پانچ رکعات پڑھائیں۔"}],[1217,"عثمان بن ابی شیبہ نے ہمیں حدیث بیان کی ۔ لفظ انھی کے ہیں ۔ انھوں نے کہا : ہمیں جریر نے حسن بن عبیداللہ سے حدیث بیان کی ، انھوں نے ابراہیم بن سوید سے روایت کی ، کہا : ہمیں علقمہ نے ظہر کی پانچ رکعتیں پڑھا دیں ۔ جب انھوں نے سلام پھیرا تو لوگوں نے کہا : ابو شبل! آپ نے پانچ رکعتیں پڑھائی ہیں ۔ انھوں نے کہا : بالکل نہیں ، میں نے ایسا نہیں کیا ۔ لوگوں نے کہا : کیوں نہیں ! ( آپ نے ایسا ہی کیا ہے ۔ ) ابراہیم نے کہا : میں لوگوں کے کنارے ( والے حصے ) میں تھا اور بچہ تھا ، میں نے کہا : ہاں !آپ نے پانچ رکعتیں پڑھی ہیں ۔ انھوں نے مجھ سے کہا : ایک آنکھ والے ! تو بھی یہی کہتا ہے ؟ میں نے کہا : جی ہاں ! تو وہ مڑے اور دو سجدے کیے ، پھر سلام پھیرا ، پھر کہا : عبداللہ رضی اللہ عنہ ( بن مسعود ) نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں پانچ رکعتیں پڑھا دیں ، جب آپ مڑے تو لوگوں نے آپس میں کھسر پھسر شروع کر دی ۔ آپ نے پوچھا : ’’ تمھیں کیا ہوا ہے ؟ ‘‘ انھوں نے کہا : اے اللہ کے رسول ! کیا نماز میں اضافہ کر دیا گیا ہے ؟آپ نے فرمایا : ’’ نہیں ۔ ‘‘ لوگوں نے کہا : آپ نے پانچ رکعتیں پڑھائی ہیں ۔ تو آپ پلٹے ، پھر دو سجدے کیے ، پھر سلام پھیرا ، پھر فرمایا : ’’ میں تمھاری ہی طرح کا انسان ہوں ، میں ( بھی ) بھول جاتا ہوں جس طرح تم لوگ بھول جاتے ہو ۔ ‘‘ ابن نمیر نے اپنی روایت میں یہ اضافہ کیا : ’’جب تم میں سے کوئی بھول جائے تو وہ دو سجدے کر لے ۔ ‘‘","",{"u2":"عثمان بن ابی شیبہ نے ہمیں حدیث بیان کی۔ لفظ انھی کے ہیں۔ انھوں نے کہا: ہمیں جریر نے حسن بن عبیداللہ سے حدیث بیان کی، انھوں نے ابراہیم بن سوید سے روایت کی، کہا: ہمیں علقمہ نے ظہر کی پانچ رکعتیں پڑھا دیں۔ جب انھوں نے سلام پھیرا تو لوگوں نے کہا: ابو شبل! آپ نے پانچ رکعتیں پڑھائی ہیں۔ انھوں نے کہا: بالکل نہیں، میں نے ایسا نہیں کیا۔ لوگوں نے کہا: کیوں نہیں!(آپ نے ایسا ہی کیا ہے۔)ابراہیم نے کہا: میں لوگوں کے کنارے (والے حصے)میں تھا اور بچہ تھا، میں نے کہا: ہاں!آپ نے پانچ رکعتیں پڑھی ہیں۔ انھوں نے مجھ سے کہا: ایک آنکھ والے! تو بھی یہی کہتا ہے؟ میں نے کہا: جی ہاں! تو وہ مڑے اور دو سجدے کیے، پھر سلام پھیرا، پھر کہا: عبداللہ رضی اللہ عنہ (بن مسعود) نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں پانچ رکعتیں پڑھا دیں، جب آپ مڑے تو لوگوں نے آپس میں کھسر پھسر شروع کر دی۔ آپ نے پوچھا: ’’ تمھیں کیا ہوا ہے؟‘‘ انھوں نے کہا: اے اللہ کے رسول! کیا نماز میں اضافہ کر دیا گیا ہے؟آپ نے فرمایا: ’’ نہیں۔‘‘ لوگوں نے کہا: آپ نے پانچ رکعتیں پڑھائی ہیں۔ تو آپ پلٹے، پھر دو سجدے کیے، پھر سلام پھیرا، پھر فرمایا: ’’ میں تمھاری ہی طرح کا انسان ہوں،میں (بھی)بھول جاتا ہوں جس طرح تم لوگ بھول جاتے ہو۔‘‘\nابن نمیر نے اپنی روایت میں یہ اضافہ کیا: ’’جب تم میں سے کوئی بھول جائے تو وہ دو سجدے کر لے۔‘‘"}],[1218,"عبدالرحمن بن اسود نے اپنے والد سے ، انھوں نےسیدنا عبداللہ ( بن مسعود ) رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں پانچ رکعتیں پڑھا دیں تو ہم نے عرض کی : اے اللہ کے رسول ! کیا نماز میں اضافہ کر دیا گیا ہے ؟ آپ نے فرمایا : ’’ وہ کیا ؟ ‘‘ صحابہ نے کہا : آپ نے پانچ رکعات پڑھائی ہیں ۔ آپ نے فرمایا : ’’ میں تمھاری طرح انسان ہوں ، میں بھی اسی طرح یا د رکھتا ہوں ، جس طرح تم یاد رکھتے ہو اور میں ( بھی ) اسی طرح بھو ل جاتا ہوں ، جس طرح تم بھول جاتے ہو ۔ ‘‘ پھر آپ نے سہو کے دو سجدے کیے ۔","",{"u2":"عبدالرحمن بن اسود نے اپنے والد سے، انھوں نےحضرت عبداللہ (بن مسعود) رضی اللہ عنہ سے روایت کی، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں پانچ رکعتیں پڑھا دیں تو ہم نے عرض کی: اے اللہ کے رسول! کیا نماز میں اضافہ کر دیا گیا ہے؟ آپ نے فرمایا: ’’ وہ کیا؟‘‘ صحابہ نے کہا: آپ نے پانچ رکعات پڑھائی ہیں۔ آپ نے فرمایا: ’’ میں تمھاری طرح انسان ہوں، میں بھی اسی طرح یا د رکھتا ہوں، جس طرح تم یاد رکھتے ہو اور میں (بھی)اسی طرح بھو ل جاتا ہوں، جس طرح تم بھول جاتے ہو۔ ‘‘ پھر آپ نے سہو کے دو سجدے کیے۔"}],[1219,"(علی ) بن مسہر نے اعمش سے ، انھوں نے ابراہیم سے ، انھوں نے علقمہ سے اور انھوں نے حضر عبداللہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی اور اس میں کچھ اضافہ کر دیا ۔ ابراہیم نے کہا کہ یہاں وہم مجھے ہوا ہے ، علقمہ کو نہیں ۔ عرض کی گئی : اللہ کے رسول ! کیا نماز مین اضافہ کر دیا گیا ہے ؟ آپ نے فرمایا : ’’ میں تمھاری طرح انسان ہی ہوں ، میں بھی بھولتا ہوں ، جیسے تم بھولتے ہو ، اس لیے جب تم میں سے کوئی بھول جائے تو وہ بیٹھے بیٹھے دو سجدے کر لے ۔ ‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے رخ ( قبلہ کی طرف ) پھیرا اور دو سجدے کیے ۔","",{"u2":"علی)بن مسہر نے اعمش سے، انھوں نے ابراہیم سے، انھوں نے علقمہ سے اور انھوں نے حضر عبداللہ رضی اللہ عنہ سے روایت کی، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی اور اس میں کچھ اضافہ کر دیا۔ ابراہیم نے کہا کہ یہاں وہم مجھے ہوا ہے، علقمہ کو نہیں۔ عرض کی گئی: اللہ کے رسول! کیا نماز مین اضافہ کر دیا گیا ہے؟ آپ نے فرمایا: ’’ میں تمھاری طرح انسان ہی ہوں، میں بھی بھولتا ہوں، جیسے تم بھولتے ہو، اس لیے جب تم میں سے کوئی بھول جائے تو وہ بیٹھے بیٹھے دو سجدے کر لے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے رخ (قبلہ کی طرف)پھیرا اور دو سجدے کیے۔"}],[1220,"حفص اور ابو معاویہ نے اعمش سے باقی ماندہ اس سند کے ساتھ سیدنا عبداللہ ( بن مسعود ) رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : نبی صلی اللہ علیہ وسلم نے سلام اور گفتگو کےبعد سہو کے دو سجدے کیے ۔","",{"u2":"حفص اور ابو معاویہ نے اعمش سے باقی ماندہ اس سند کے ساتھ حضرت عبداللہ (بن مسعود) رضی اللہ عنہ سے روایت کی، انھوں نے کہا: نبی صلی اللہ علیہ وسلم نے سلام اور گفتگو کےبعد سہو کے دو سجدے کیے۔"}],[1221,"زائدہ نے سلیمان ( اعمش ) سے باقی ماندہ اسی سند کے ساتھ سیدنا عبداللہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی ، آپ نے زیادہ پڑھا دی تھی یا کم ۔ ابراہیم نے کہا : اللہ کی قسم ! یہ ( وہم ) میری طرف سے ہے ۔ عبداللہ رضی اللہ عنہ نے کہا : تو ہم نے عرض کی : اے اللہ کے رسول ! کیا نماز میں کوئی نیا حکم آگیا ہے ؟ آپ نے فرمایا : ’’ نہیں ‘‘ تو ہم نے آپ کو جو آپ نے کیا تھا اس سے آگا ہ کیا تو آپ نے فرمایا : ’’ جب آدمی زیادتی یا کمی کر لے تو دو سجدے کر ے ۔ ‘‘ ( عبداللہ بن مسعود رضی اللہ عنہ نے ) کہا : اس کے بعد آپ نے دو سجدے کیے ۔","",{"u2":"زائدہ نے سلیمان (اعمش)سے باقی ماندہ اسی سند کے ساتھ سیدنا عبداللہ رضی اللہ عنہ سے روایت کی، انھوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، آپ نے زیادہ پڑھا دی تھی یا کم۔ ابراہیم نے کہا: اللہ کی قسم! یہ (وہم) میری طرف سے ہے۔ عبداللہ رضی اللہ عنہ نے کہا: تو ہم نے عرض کی: اے اللہ کے رسول! کیانماز میں کوئی نیا حکم آگیا ہے؟ آپ نے فرمایا: ’’ نہیں ‘‘ تو ہم نے آپ کو جو آپ نے کیا تھا اس سے آگا ہ کیا تو آپ نے فرمایا: ’’ جب آدمی زیادتی یا کمی کر لے تو دو سجدے کر ے۔‘‘ (عبداللہ بن مسعود رضی اللہ عنہ نے)کہا: اس کے بعد آپ نے دو سجدے کیے۔"}],[1222,"سفیان بن عیینہ نے کہا : ہم سے ایوب نے حدیث بیان کی ، انھوں نے کہا : میں نے محمد بن سیرین سے سنا ، وہ کہہ رہے تھے : میں نےسیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہمیں رسول اللہ صلی اللہ علیہ وسلم نے دوپہر کے بعد کی ایک نماز ظہر یا عصر پڑھائی اور دو رکعتوں کے بعد سلام پھیر دیا ، پھر قبلے کی سمت ( گڑے ہوئے ) کجھور کے ایک تنےکے پاس آئے اور غصے کی کیفیت میں اس سے ٹیک لگا لی ۔ لوگوں میں ابو بکر و عمر رضی اللہ عنہ موجود ( بھی ) تھے ، انھوں نے آپ کی ہیبت کی بنا پر گفتگو نہ کی جبکہ جلد باز لوگ ( نماز پڑھتے ہی ) نکل گئے ، اور کہنے لگے : نماز میں کمی ہو گئی ہے ۔ تو ذوالیدین ( نامی شخص ) کھڑا ہوا اور کہا : اے اللہ کے رسول ! کیا نماز مختصر کر دی گئی ہے یا آپ بھول گئے ہیں ؟ نبی اکرم صلی اللہ علیہ وسلم نے دائیں اور بائیں دیکھ کر پوچھا : ’’ ذوالیدین کیا کہہ رہا ہے ؟ ‘‘ لوگوں نے کہا : سچ کہہ رہا ہے ، آپ نے دو رکعتیں ہی پڑھی ہیں ۔ چنانچہ آپ نے دو رکعتیں ( مزید ) پڑھیں اور سلام پھیر دیا ، پھر اللہ اکبر کہا اور سجدہ کیا ، بھر اللہ اکبر کہا اور سر اٹھایا ، پھر اللہ اکبر کہا اور سجد ہ کیا ، پھر اللہ اکبر کہا اور سر اٹھایا ۔ ( محمد بن سیرین نے ) کہا : عمران بن حصین رضی اللہ عنہ کے حوالے سے مجھے بتایا گیا کہ انھوں نے کہا : اور سلام پھیرا ۔","",{"u2":"سفیان بن عیینہ نے کہا: ہم سے ایوب نے حدیث بیان کی، انھوں نے کہا: میں نے محمد بن سیرین سے سنا، وہ کہہ رہے تھے: میں نےسیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے دوپہر کے بعد کی ایک نماز ظہر یا عصر پڑھائی اور دو رکعتوں کے بعد سلام پھیر دیا، پھر قبلے کی سمت (گڑے ہوئے)کجھور کے ایک تنےکے پاس آئے اور غصے کی کیفیت میں اس سے ٹیک لگا لی۔ لوگوں میں ابو بکر و عمر رضی اللہ عنہما موجود (بھی)تھے، انھوں نے آپ کی ہیبت کی بنا پر گفتگو نہ کی جبکہ جلد باز لوگ (نماز پڑھتے ہی)نکل گئے، اور کہنے لگے: نماز میں کمی ہو گئی ہے۔ تو ذوالیدین (نامی شخص)کھڑا ہوا اور کہا: اے اللہ کے رسول! کیا نماز مختصر کر دی گئی ہے یا آپ بھول گئے ہیں؟ نبی اکرم صلی اللہ علیہ وسلم نے دائیں اور بائیں دیکھ کر پوچھا:’’ ذوالیدین کیا کہہ رہا ہے؟‘‘ لوگوں نے کہا: سچ کہہ رہا ہے، آپ نے دو رکعتیں ہی پڑھی ہیں۔ چنانچہ آپ نے دو رکعتیں (مزید)پڑھیں اور سلام پھیر دیا، پھر اللہ اکبر کہا اور سجدہ کیا، بھر اللہ اکبر کہا اور سر اٹھایا، پھر اللہ اکبر کہا اور سجد ہ کیا، پھر اللہ اکبر کہا اور سر اٹھایا۔(محمد بن سیرین نے) کہا: عمران بن حصین رضی اللہ عنہ کے حوالے سے مجھے بتایا گیا کہ انھوں نے کہا: اور سلام پھیرا۔"}],[1223,"(سفیان کے بجائے ) حماد نے ہمیں حدیث بیان کی ( کہا : ) ہمیں ایوب نے محمد بن سیرین سے حدیث سنائی ، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ہمیں دو پہر کے بعد کی دو نمازو ں میں سے ایک نماز پڑھائی ......آگے سفیان ( بن عیینہ ) کے ہم معنی حدیث ( سنائی ۔)","",{"u2":")(سفیان کے بجائے)حماد نے ہمیں حدیث بیان کی (کہا:)ہمیں ایوب نے محمد بن سیرین سے حدیث سنائی، انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں دو پہر کے بعد کی دو نمازو ں میں سے ایک نماز پڑھائی ......آگے سفیان (بن عیینہ) کے ہم معنی حدیث (سنائی۔)"}],[1224,"ابن ابی احمد کے آزاد کردہ غلام ابو سفیان سے روایت ہے کہ اس نے کہا : میں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہو ئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھائی اور دو رکعتوں میں سلام پھیر دیا ۔ ذوالیدین ( نامی شخص ) کھڑا ہوا اور کہا : اے اللہ کے رسول ! نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں ؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ ایسا کوئی کام نہیں ہوا ۔ ‘‘ اس نے عرض کی : اے اللہ کے رسول ! کوئی ایک کام تو ہوا ہے ۔ تب رسول اللہ صلی اللہ علیہ وسلم لوگوں کی طرف متوجہ ہوئے اور پوچھا : ’’ کیا ذوالیدین نے سچ کہا؟ ‘‘ انھوں کہا : جی ہاں ! اے اللہ کے رسول ! تو رسول اللہ صلی اللہ علیہ وسلم نے جو نماز رہ گئی تھی پوری کی ، پھر بیٹھے بیٹھے سلام پھیرنے کے بعد دو سجدے کیے ۔","",{"u2":") ابن ابی احمد کے آزاد کردہ غلام ابو سفیان سے روایت ہے کہ اس نے کہا: میں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہو ئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھائی اور دو رکعتوں میں سلام پھیر دیا۔ ذوالیدین (نامی شخص) کھڑا ہوا اور کہا: اے اللہ کے رسول! نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ ایسا کوئی کام نہیں ہوا۔‘‘ اس نے عرض کی: اے اللہ کے رسول! کوئی ایک کام تو ہوا ہے۔ تب رسول اللہ صلی اللہ علیہ وسلم لوگوں کی طرف متوجہ ہوئے اور پوچھا: ’’ کیا ذوالیدین نے سچ کہا؟ ‘‘ انھوں کہا: جی ہاں! اے اللہ کے رسول! تو رسول اللہ صلی اللہ علیہ وسلم نے جو نماز رہ گئی تھی پوری کی، پھر بیٹھے بیٹھے سلام پھیرنے کے بعد دو سجدے کیے۔"}],[1225,"علی بن مبارک نے ہمیں حدیث بیان کی ، کہا : ہمیں یحییٰ نے حدیث بیان کی ، انھوں نے کہا : ہمیں ابو سلمہ نے حدیث سنائی ، کہا : ہمیں سیدنا ابو ہریرہ رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی دور کعتیں پڑھائیں ، پھر سلام پھیر دیا تو بنو سلیم کا ایک آدمی آپ کے قریب آیا اور عرض یک : اے اللہ کے رسول ! نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں ؟.......اور آگے ( سابقہ ) حدیث بیان کی ۔","",{"u2":"علی بن مبارک نے ہمیں حدیث بیان کی، کہا: ہمیں یحییٰ نے حدیث بیان کی، انھوں نے کہا: ہمیں ابو سلمہ نےحدیث سنائی، کہا: ہمیں سیدنا ابو ہریرہ رضی اللہ عنہ نےحدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی دور کعتیں پڑھائیں، پھر سلام پھیر دیا تو بنو سلیم کا ایک آدمی آپ کے قریب آیا اور عرض یک: اے اللہ کے رسول! نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟.......اور آگے (سابقہ) حدیث بیان کی۔"}],[1226,"شیبان نے یحییٰ سے ، انھوں نے ابو سلمہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : میں نبی اکر صلی اللہ علیہ وسلم کے ساتھ ( اقتدا میں ) ظہر کی نماز پڑھ رہا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے دو رکعتوں پر سلام پھیر دیا ، اس پر بنی سلیم کا ایک آدمی کھڑا ہوا .......آگے ( مذکورہ بالا ) حدیث بیان کی","",{"u2":"شیبان نےیحییٰ سے، انھوں نے ابو سلمہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، انھوں نے کہا: میں نبی اکر صلی اللہ علیہ وسلم کے ساتھ (اقتدا میں)ظہر کی نماز پڑھ رہا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے دو رکعتوں پر سلام پھیر دیا، اس پر بنی سلیم کا ایک آدمی کھڑا ہوا .......آگے (مذکورہ بالا)حدیث بیان کی"}],[1227,"اسماعیل بن ابراہیم نے خالد ( حذاء ) سے ، انھوں نے ابو قلابہ سے ، انھوں نے ابو مہلب سے اور انھوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نےعصر کی نماز پڑھائی اور تین رکعات پر سلام پھیر دیا ، پھر اپنے گھر تشریف لے گئے تو ایک آدمی جسے خرباق کہا جاتا تھا اور اس کے ہاتھ لمبے تھے ، وہ آپ کی خدمت میں حاضر ہواا ور آپ سے عرض کی : اے اللہ کے رسول ! پھر آپ صلی اللہ علیہ وسلم سے جو ( سہو ) ہوا تھا اس کا آپ کے سامنے تذکرہ کیا ، آپ غصے کی حالت میں ، چادر گھسیٹتے ہوئے نکلے حتی کہ لوگوں کے پا س آ پہنچے اور پوچھا : ’’ کیا یہ سچ کہہ رہا ہے ؟ ‘‘ لوگوں نے کہا : جی ہاں ! توآپ نے ایک رکعت پڑھائی ، پھر سلام پھیرا ، پھر سہو کے دو سجدے کیے ، پھر سلام پھیرا ۔","",{"u2":") اسماعیل بن ابراہیم نے خالد (حذاء)سے، انھوں نے ابو قلابہ سے، انھوں نے ابو مہلب سے اور انھوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نےعصر کی نماز پڑھائی اور تین رکعات پر سلام پھیر دیا، پھر اپنے گھر تشریف لے گئے تو ایک آدمی جسے خرباق کہا جاتا تھا اور اس کے ہاتھ لمبے تھے، وہ آپ کی خدمت میں حاضر ہواا ور آپ سے عرض کی: اے اللہ کے رسول! پھر آپ صلی اللہ علیہ وسلم سے جو (سہو)ہوا تھا اس کا آپ کے سامنے تذکرہ کیا، آپ غصے کی حالت میں، چادر گھسیٹتے ہوئے نکلے حتی کہ لوگوں کے پا س آ پہنچے اور پوچھا:’’ کیا یہ سچ کہہ رہا ہے؟ ‘‘ لوگوں نے کہا: جی ہاں! توآپ نے ایک رکعت پڑھائی، پھر سلام پھیرا، پھر سہو کے دو سجدے کیے، پھر سلام پھیرا۔"}],[1228,"عبدالوہاب تقفی نے خالد حذاء سے باقی ماندہ اسی سند کے ساتھ سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی ، انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے عصر کی تیسری رکعت میں سلام پھیر دیا ، پھر اٹھ کر اپنے حجرے میں داخل ہو گئے ، ایک ( لمبے ) چوڑے ہاتھوں والا آدمی کھڑا ہوا اور عرض کی : اے اللہ کے رسول ! کیا نماز کم کر دی گئی ہے ؟ پھر آپ غصے کے عالم میں نکلے اور چھوڑی ہوئی رکعت پڑھائی ، پھر سلام پھیر دیا ، پھر سہو کے دو سجدے کیے ، پھر سلام پھیرا ۔","",{"u2":"عبدالوہاب تقفی نے خالد حذاء سے باقی ماندہ اسی سند کے ساتھ سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی، انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے عصر کی تیسری رکعت میں سلام پھیر دیا، پھر اٹھ کر اپنے حجرے میں داخل ہو گئے، ایک (لمبے)چوڑے ہاتھوں والا آدمی کھڑا ہوا اور عرض کی: اے اللہ کے رسول! کیا نماز کم کر دی گئی ہے؟ پھر آپ غصے کے عالم میں نکلے اور چھوڑی ہوئی رکعت پڑھائی، پھر سلام پھیر دیا، پھر سہو کے دو سجدے کیے، پھر سلام پھیرا۔"}],[1229,"یحییٰ بن سعید قطان نے عبیداللہ سے حدیث بیان کی ، انھوں نے کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی کہ نبی کریم صلی اللہ علیہ وسلم قرآن مجید کی تلاوت فرمایا کرتےتھے ۔ آپ اس سورت کی تلاوت فرماتے جس میں سجدہ ہوتا اور سجدہ کرتے تو ہم ( سب ) بھی آپ کے ساتھ سجدہ کرتے ، حتی کہ ہم میں سے بعض کو پیشانی رکھنے کے لیے بھی جگہ نہ ملتی تھی ۔","",{"u2":"یحییٰ بن سعید قطان نے عبیداللہ سے حدیث بیان کی، انھوں نے کہا: مجھے نافع نے حضرت ابن عمر رضی اللہ عنہما سے خبر دی کہ نبی کریم صلی اللہ علیہ وسلم قرآن مجید کی تلاوت فرمایا کرتےتھے۔ آپ اس سورت کی تلاوت فرماتے جس میں سجدہ ہوتا اور سجدہ کرتے تو ہم (سب)بھی آپ کے ساتھ سجدہ کرتے، حتی کہ ہم میں سے بعض کو پیشانی رکھنے کے لیے بھی جگہ نہ ملتی تھی۔"}],[1230,"محمد بن بشر نے حدیث بیان کی ، کہا : ہمیں عبیداللہ نےنافع سے حدیث بیان کی اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، انھو ں نے کہا : بسا اوقات رسول اللہ صلی اللہ علیہ وسلم قرآن پڑھتے ہوئے سجدے ( والی آیت ) سے گزرتے تو ہمارے ساتھ سجدہ کرتے ، آپ کے پاس ہماری بھیٹر لگ جاتی حتی کہ ہم میں سے بعض کو سجدہ کرنے کےلیے جگہ نہ ملیتی ( یہ سجدہ ) نماز کے علاوہ ہوتا تھا ۔","",{"u2":"محمد بن بشر نے حدیث بیان کی، کہا: ہمیں عبیداللہ نےنافع سے حدیث بیان کی اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، انھو ں نے کہا: بسا اوقات رسول اللہ صلی اللہ علیہ وسلم قرآن پڑھتے ہوئے سجدے (والی آیت) سے گزرتے تو ہمارے ساتھ سجدہ کرتے، آپ کے پاس ہماری بھیٹر لگ جاتی حتی کہ ہم میں سے بعض کو سجدہ کرنے کےلیے جگہ نہ ملیتی (یہ سجدہ)نماز کے علاوہ ہوتا تھا۔"}],[1231,"سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ آپ صلی اللہ علیہ وسلم نے سورۃ نجم کی تلاوت کی اور اس میں سجدہ کیا اور آپ کے ساتھ جتنے لوگ تھے سب نے سجدہ کیا ، مگر ایک بوڑھے ( امیہ بن خلف ) نے کنکریوں یا مٹی کی ایک مٹھی بھر کر اپنی پیشانی سے لگا لی اور کہا : میرے لیے یہی کافی ہے ۔ عبداللہ ( بن مسعود رضی اللہ عنہ ) نے کہا : میں نے بعد میں دیکھا ، اسے کفر کی حالمت میں قتل کیا گیا ۔","",{"u2":"حضرت عبداللہ (بن مسعود رضی اللہ عنہ)نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ آپ صلی اللہ علیہ وسلم نے سورۃ نجم کی تلاوت کی اور اس میں سجدہ کیا اور آپ کے ساتھ جتنے لوگ تھے سب نے سجدہ کیا، مگر ایک بوڑھے (امیہ بن خلف)نے کنکریوں یا مٹی کی ایک مٹھی بھر کر اپنی پیشانی سے لگا لی اور کہا: میرے لیے یہی کافی ہے۔ عبداللہ(بن مسعود رضی اللہ عنہ)نے کہا: میں نےبعد میں دیکھا، اسے کفر کی حالمت میں قتل کیا گیا۔"}],[1232,"عطاء بن یسار نے ( اپنے شاگرد ابن قسیط کو ) بتایا کہ انھوں نے امام کے ساتھ ( قرآن کی کسی سورت کی ) قراءت کرنے کے بارے میں سیدنا زید بن ثابت رضی اللہ عنہ سے سوال کیا ؟ انھوں نے کہا : امام کے ساتھ ( فاتحہ کے سوا ) کچھ نہ پڑھے اور کہا : انھوں ( زید رضی اللہ عنہ ) نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے ( والنجم اذا ھویٰ ) پڑھی تو آپ نے سجدہ نہ کیا ۔","",{"u2":"عطاء بن یسار نے (اپنے شاگرد ابن قسیط کو) بتایا کہ انھوں نے امام کے ساتھ (قرآن کی کسی سورت کی) قراءت کرنے کے بارے میں سیدنا زید بن ثابت رضی اللہ عنہ سے سوال کیا؟ انھوں نے کہا: امام کے ساتھ (فاتحہ کے سوا)کچھ نہ پڑھے اور کہا: انھوں (زید رضی اللہ عنہ)نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے (والنجم اذا ھویٰ)پڑھی تو آپ نے سجدہ نہ کیا۔"}],[1233,"اسود بن سفیان کے آزاد کردہ غلام عبداللہ بن یزید نے ابو سلمہ بن عبدالرحمن سے روایت کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے ان کے سامنے سورۃ ( اذاالسمآ ء النشقت ) پڑھی اور ا س میں سجدہ کیا ، پھر جب سلام پھیرا تو انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سورت میں سجدہ کیا تھا ۔","",{"u2":"اسود بن سفیان کے آزاد کردہ غلام عبداللہ بن یزید نے ابو سلمہ بن عبدالرحمن سے روایت کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نے ان کے سامنے سورۃ (اذاالسمآ ء النشقت) پڑھی اور ا س میں سجدہ کیا، پھر جب سلام پھیرا تو انھیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سورت میں سجدہ کیا تھا۔"}],[1234,"یحییٰ بن ابی کثیر نے ابو سلمہ سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مانند روایت کی","",{"u2":") یحییٰ بن ابی کثیر نے ابو سلمہ سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مانند روایت کی"}],[1235,"عطاء بن میناء نے سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت کی ‘ انھوں نے کہا : ہم نے نبی صلی اللہ علیہ وسلم کے ساتھ ( اذا السّماء انشقت ) اور ( اقرا باسم ربّک ) میں سجدہ کیا ۔","",{"u2":"عطاء بن میناء نے سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت کی ‘انھوں نے کہا:ہم نے نبی صلی اللہ علیہ وسلم کے ساتھ (اذا السّماء انشقت)اور (اقرا باسم ربّک)میں سجدہ کیا۔"}],[1236,"صفوان بن سلیم نے بنو مخزوم کے آزاد کردہ غلام عبد الرحمٰن اعرج سے روایت کی ‘ انھوں نے حصرت ابو ھریرہ رضی اللہ عنہ سے روایت کی ‘ انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ( اذا «اسّماء انشقّت» ) اور ( اقراباسم ربّک ) میں سجدہ کیا ۔ صفوان بن سلیم نے بنو مخزوم کے آزاد کردہ غلام عبد الرحمٰن اعرج سے روایت کی ‘ انھوں نے حصرت ابو ھریرہ رضی اللہ عنہ سے روایت کی ‘ انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ( اذا «اسّماء انشقّت» ) اور ( اقراباسم ربّک ) میں سجدہ کیا ۔","",{"u2":"صفوان بن سلیم نے بنو مخزوم کے آزاد کردہ غلام عبد الرحمٰن اعرج سے روایت کی ‘انھوں نے حصرت ابو ھریرہ رضی اللہ عنہ سے روایت کی ‘ انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے (اذا اسّماء انشقّت)اور(اقراباسم ربّک)میں سجدہ کیا۔\nصفوان بن سلیم نے بنو مخزوم کے آزاد کردہ غلام عبد الرحمٰن اعرج سے روایت کی ‘انھوں نے حصرت ابو ھریرہ رضی اللہ عنہ سے روایت کی ‘ انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے (اذا اسّماء انشقّت)اور(اقراباسم ربّک)میں سجدہ کیا۔"}],[1237,"۔ عبید اللہ بن ابی جعفر نے عبد الرحمٰن اعرج سے ‘ انھوں نے حصرت ابوھریرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے اسی کے مانند بیان کیا","",{"u2":"۔عبید اللہ بن ابی جعفر نے عبد الرحمٰن اعرج سے ‘انھوں نے حصرت ابوھریرہ رضی اللہ عنہ سے اور انھوں نے رسو ل اللہ صلی اللہ علیہ وسلم سے اسی کے مانند بیان کیا"}],[1238,"عبید اللہ بن معاذ غنبری ارو محمد بن عبد الاعلیٰ نے کہا : ہمیں معتمر نے اپنے والد ( سلیمان تیمی ) سے حدیث سنائی ‘ انھوں نے بکر ( بن عبد اللہ مزنی ) سے اور انھوں نے ابو رافع سے روایت کی ‘ انھوں نے کہا : میں نے سیدنا ابوھریرہ رضی اللہ عنہ کے ساتھ عشاء کی نماز پڑھی تو انھوں نے ( اذا «السّماء انشقّت» ) کی تلاوت کی اور اس میں سجدہ کیا ۔ میں نے پوچھا : یہ سجدہ کیسا ہے ؟انھوں نے جواب دیا : میں نے اس میں ابوالقاسم ( محمد رسول اللہ صلی اللہ علیہ وسلم ) کے پیچھے سجدہ کیا ‘ اس لیے میں اس میں ہمیشہ سحدہ کرتا رہوں گا یہاں تک کہ آپ ( صلی اللہ علیہ وسلم ) سے جا ملوں ۔ ( محمد ) بن عبد الاعلیٰ نے کہا : میں بھی ہمیشہ یہ سجدہ کرتا ہوں ۔","",{"u2":"عبید اللہ بن معاذ غنبری ارو محمد بن عبد الاعلیٰ نے کہا:ہمیں معتمر نے اپنے والد (سلیمان تیمی)سے حدیث سنائی ‘انھوں نے بکر (بن عبد اللہ مزنی)سے اور انھوں نے ابو رافع سے روایت کی‘انھوں نے کہا:میں نے سیدنا ابوھریرہ رضی اللہ عنہ کے ساتھ عشاء کی نماز پڑھی تو انھوں نے (اذا السّماء انشقّت)کی تلاوت کی اور اس میں سجدہ کیا۔میں نے پوچھا:یہ سجدہ کیسا ہے؟انھوں نے جواب دیا:میں نے اس میں ابوالقاسم (محمد رسو ل اللہ صلی اللہ علیہ وسلم)کے پیچھے سجدہ کیا ‘اس لیے میں اس میں ہمیشہ سحدہ کرتا رہوں گا یہاں تک کہ آپ(صلی اللہ علیہ وسلم)سے جا ملوں۔(محمد)بن عبد الاعلیٰ نے کہا:میں بھی ہمیشہ یہ سجدہ کرتا ہوں۔"}],[1239,"عیسیٰ بن یونس ‘ یزید بن زریع اور سلیم بن اخضر سب نے ( سلیمان ) تیمی سے سابقہ سند کے ساتھ روایت کی لیکن انھوں نے خلف ابی القاسم صلی اللہ علیہ وسلم ( ابوالقاسم صلی اللہ علیہ وسلم کے پیچھے ) کے الفاظ نہیں کہے ۔","",{"u2":"عیسیٰ بن یونس ‘یزید بن زریع اور سلیم بن اخضر سب نے (سلیمان)تیمی سے سابقہ سند کے ساتھ روایت کی لیکن انھوں نے خلف ابی القاسم صلی اللہ علیہ وسلم (ابوالقاسم صلی اللہ علیہ وسلم کے پیچھے)کے الفاظ نہیں کہے۔"}],[1240,"شعبہ نے عطاء بن ابی میمونہ سے انھوں نے ابو رافع سے روایت کی ‘ کہا : میں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو دیکھا ‘ وہ ( اذا «السّماء انشقّت» ) میں سجدہ کرتے تھے ۔ میں نے پوچھا : آپ اس میں سجدہ کرتے ہیں؟انھوں نے کہا : ہاں!میں نے اپنے خلیل صلی اللہ علیہ وسلم کو اس سجدہ کرتے دیکھا ‘ اس لیے میں ہمیشہ اس میں سجدہ کرتا رہو ں گا حتی کہ ان سے جا ملوں ۔ شعبہ نے کہا : میں نے ( عطاء سے ) پوچھا : ( خلیل سے مراد ) نبی اکرم صلی اللہ علیہ وسلم ہیں ؟انھوں نے کہا : ہاں ۔","",{"u2":"شعبہ نے عطاء بن ابی میمونہ سے انھوں نے ابو رافع سے روایت کی ‘کہا:میں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو دیکھا ‘وہ (اذا السّماء انشقّت)میں سجدہ کرتے تھے۔ میں نے پوچھا:آپ اس میں سجدہ کرتے ہیں؟انھوں نے کہا:ہاں!میں نے اپنے خلیل صلی اللہ علیہ وسلم کو اس سجدہ کرتے دیکھا ‘اس لیے میں ہمیشہ اس میں سجدہ کرتا رہو ں گا حتی کہ ان سے جا ملوں۔\nشعبہ نے کہا:میں نے (عطاء سے)پوچھا:(خلیل سے مراد)نبی اکرم صلی اللہ علیہ وسلم ہیں؟انھوں نے کہا:ہاں۔"}],[1241,"عثمان بن حکم نے کہا : عامر بن عبد اللہ بن زبیر رضی اللہ عنہ نے اپنے والد سے روایت کرتے ہوئے مجھے حدیث سنائی ‘ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب نماز میں بیٹھتے تو اپنا بایاں پاؤں اپنی ران اور اپنی پنڈلی کے درمیان کر لیتے اور اپنا دایاں پاؤ ں بچھا لیتے اور اپنا بایاں ہاتھ اپنے بائیں گٹھنے پر اور اپنا دایا ں ہاتھ اپنی دائیں ران پر رکھ لیتے اور اپنی انگلی سے اشارہ کر لیتے ۔","",{"u2":"عثمان بن حکم نے کہا:عامر بن عبد اللہ بن زبیر رضی اللہ عنہ نے اپنے والد سے روایت کرتے ہوئے مجھے حدیث سنائی‘انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جب نماز میں بیٹھتے تو اپنا بایاں پاؤں اپنی ران اور اپنی پنڈلی کے درمیان کر لیتے اور اپنا دایاں پاؤ ں بچھا لیتے اور اپنا بایاں ہاتھ اپنے بائیں گٹھنے پر اور اپنا دایا ں ہاتھ اپنی دائیں ران پر رکھ لیتے اور اپنی انگلی سے اشارہ کر لیتے۔"}],[1242,"۔ ابن عجلان نے عامر بن عبد اللہ بن زبیر سے اور انھوں نے اپنے والد سے روایت کی ‘ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب ( نماز میں ) بیٹھ کر دعا کرتے تو اپنا دایاں ہاتھ اپنی دائیں ران پر اور اپنا بایاں ہاتھ اپنی بائیں ران پر رکھتے اور اپنی شہادت کی انگلی سے اشارہ کرتے اور اپنا انگوٹھا اپنی د رمیانی انگلی پررکھتےاور بائیں گٹھنے کو اپنی بائیں ہتھیلی کے اندر لےلیتے ( پکڑلیتے ۔)","",{"u2":"۔ ابن عجلان نے عامر بن عبد اللہ بن زبیرسے اور انھوں نے اپنے والد سے روایت کی ‘انھوں نے کہا:رسول اللہ صلی اللہ علیہ وسلم جب(نماز میں)بیٹھ کر دعا کرتے تو اپنا دایاں ہاتھ اپنی دائیں ران پراور اپنا بایاں ہاتھ اپنی بائیں ران پر رکھتے اور اپنی شہادت کی انگلی سے اشارہ کرتے اوراپنا انگوٹھا اپنی د رمیانی انگلی پررکھتےاور بائیں گٹھنے کو اپنی بائیں ہتھیلی کے اندر لےلیتے (پکڑلیتے۔)"}],[1243,"عبید اللہ بن عمر نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم جب نماز میں بیٹھتے تو اپنے دونوں ہاتھ اپنے دونوں گٹھنوں پر رکھ لیتے اور انگوٹھے سے ملنے والی دائیں ہاتھ کی انگلی ( شہادت کی انگلی ) اٹھا کر اس سے دعا کرتے اور اس حالت میں آپکا بایاں ہاتھ آپکے بائیں گٹھنے پر ہوتا ‘ اسے ( آپ ) اس ( گٹھنے ) پر پھیلا ئے ہوتے ۔","",{"u2":"عبید اللہ بن عمر نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم جب نماز میں بیٹھتے تو اپنے دونوں ہاتھ اپنے دونوں گٹھنوں پر رکھ لیتے اور انگوٹھے سے ملنے والی دائیں ہاتھ کی انگلی (شہادت کی انگلی)اٹھا کر اس سے دعا کرتے اور اس حالت میں آپکا بایاں ہاتھ آپکے بائیں گٹھنے پرہوتا ‘اسے(آپ)اس (گٹھنے)پر پھیلا ئے ہوتے۔"}],[1244,"ایوب نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب تشہد میں بیٹھتے تو اپنا بایاں ہاتھ اپنے بائیں گٹھنے پررکھتےاوراپنا دایاں ہاتھ اپنے دائیں گٹھنے پر رکھتے اور انگلیوں سے تریپن ( 53 ) کی گرا بناتے اور انگشت شہادت سے اشارہ کرتے ۔","",{"u2":"ایوب نے نافع سے اور انھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب تشہد میں بیٹھتےتو اپنا بایاں ہاتھ اپنے بائیں گٹھنے پررکھتےاوراپنا دایاں ہاتھ اپنے دائیں گٹھنے پر رکھتے اور انگلیوں سے تریپن(53)کی گرا بناتے اور انگشت شہادت سے اشارہ کرتے۔"}],[1245,"امام مالک نے مسلم بن ابی مریم سے اور انھوں نے علی بن عبد الرحمان معادی سے روایت کی کہ انھوں نے کہا : مجھے عبد اللہ بن عمر رضی اللہ عنہ نے دیکھا کہ میں نماز کے دوران ( بے خیالی کے عالم میں نیچے پڑی ہوئی ) کنکریوں سے کھیل رہاتھا ۔ جب انھوں نے سلام پھیرا تو مجھے منع کیا اور کہا : ویسے کرو جس طرح رسول اللہ صلی اللہ علیہ وسلم کیا کرتے تھے ۔ میں نے پوچھا : رسول اللہ صلی اللہ علیہ وسلم کیا کرتے تھے ؟انھوں نے بتایا : جب آپ صلی اللہ علیہ وسلم نماز میں بیٹھنے تو ا پنی دائیں ہتھیلی اپنی دائیں ران پر رکھتے اور سب انگلیوں کو بند کر لیتے اور انگوٹھے کے ساتھ والی انگلی سے اشارہ کرتے اور اپنی بائیں ہتھیلی کو اپنی بائیں ران پر رکھتے ۔","",{"u2":"امام مالک نے مسلم بن ابی مریم سے اور انھوں نے علی بن عبد الرحمان معادی سے روایت کی کہ انھوں نے کہا:مجھے عبد اللہ بن عمر رضی اللہ عنہ نے دیکھا کہ میں نماز کے دوران (بے خیالی کے عالم میں نیچے پڑی ہوئی)کنکریوں سے کھیل رہاتھا۔جب انھوں نے سلام پھیرا تو مجھےے منع کیا اورکہا:ویسے کرو جس طرح رسول اللہ صلی اللہ علیہ وسلم کیا کرتے تھے۔میں نے پوچھا:رسول اللہ صلی اللہ علیہ وسلم کیا کرتے تھے؟انھوں نے بتایا:جب آپ صلی اللہ علیہ وسلم نماز میں بیٹھنے تو ا پنی دائیں ہتھیلی اپنی دائیں ران پر رکھتے اور سب انگلیوں کو بند کر لیتے اور انگوٹھے کے ساتھ والی انگلی سے اشارہ کرتے اور اپنی بائیں ہتھیلی کو اپنی بائیں ران پررکھتے۔"}],[1246,"ابن ابی عمر نے کہا : ہمیں سفیان نے مسلم بن ابی مریم سے حدیث سنائی ‘ انھوں نے علی بن عبد الرحمان معادی سے روایت کی ئ انھوں نے کہا : میں نے سیدنا ابن عمر رضی اللہ عنہ کے ساتھ کھڑے ہو کر نماز پڑھی ...پھر سفیان نے مالک کی حدیث کی طرح حدیث بیان کی اور ( سفیان کے شاگرد ابن ابی عمر نے ) یہ اضافہ کیا کہ سفیان نے کہا : یحییٰ بن سعید نے ہمیں یہ حدیث مسلم ( بن ابی مریم ) سے بیان کی تھی ‘ پھر مسلم ( بن ابی مریم ) نے خود مجھے یہ حدیث سنائی ۔","",{"u2":"ابن ابی عمر نے کہا:ہمیں سفیان نے مسلم بن ابی مریم سے حدیث سنائی ‘انھوں نے علی بن عبد الرحمان معادی سے روایت کی ئ انھوں نے کہا:میں نے سیدنا ابن عمر رضی اللہ عنہ کے ساتھ کھڑے ہو کر نماز پڑھی ...پھر سفیان نے مالک کی حدیث کی طرح حدیث بیان کی اور (سفیان کے شاگرد ابن ابی عمر نے)یہ اضافہ کیا کہ سفیان نے کہا:یحییٰ بن سعید نے ہمیں یہ حدیث مسلم (بن ابی مریم)سے بیان کی تھی ‘پھر مسلم (بن ابی مریم)نے خود مجھے یہ حدیث سنائی۔"}],[1247,"زہیر بن حرب نے کہا : ہمیں یحییٰ بن سعید نے شعبہ سے حدیث بیان کی ‘ انھوں نے حکم اور منصور سے ‘ انھوں نے مجاہد سے اور انھوں نے ابو معمر سے روایت کی کہ ایک حاکم جو مکہ میں تھا دو طرف سلام پھیرتا تھا ۔ سیدنا عبد اللہ ( بن مسعود رضی اللہ عنہ ) نے کہا : وہ کہا سے اس سنت سے وابستہ ہوا ہے ؟ حکم نے اپنی حدیث میں کہا : ( عبداللہ بن مسعود رضی اللہ عنہ ) نے کہا رسول اللہ صلی اللہ علیہ وسلم ایسے ہی کیا کرتے تھے ۔","",{"u2":"زہیر بن حرب نے کہا:ہمیں یحییٰ بن سعید نے شعبہ سے حدیث بیان کی ‘انھوں نے حکم اور منصور سے‘انھوں نے مجاہد سے اور انھوں نے ابو معمر سے روایت کی کہ ایک حاکم جو مکہ میں تھا دو طرف سلام پھیرتا تھا۔حضرت عبد اللہ (بن مسعود رضی اللہ عنہ)نے کہا:وہ کہا سے اس سنت سے وابستہ ہوا ہے؟\nحکم نے اپنی حدیث میں کہا:(عبداللہ بن مسعود رضی اللہ عنہ)نے کہا رسول اللہ صلی اللہ علیہ وسلم ایسے ہی کیا کرتے تھے۔"}],[1248,"احمد بن حنبل نے کہا : ہمیں یحییٰ بن سعید نے شعبہ سے حدیث سنائی ‘ انھوں نے مجاہد سے ‘ انھوں نے ابو معمر سے اور انھوں نے سیدنا عبد اللہ رضی اللہ عنہ سے روایت کی ۔ شعبہ نے کہا ۔ حکم نے ایک بار یہ روایت مرفوع بیان کی ۔ کہ ایک حاکم یا ایک آدمی نے دو طرف سلام پھیراتو عبداللہ ( بن مسعود رضی اللہ عنہ ) نے کہا : اس نے یہ ( سنت ) کہا سے اپنا لی ہے ؟ گویا اس دور کے حاکموں نے ایسی سنتیں بھی ترک کی ہوئی تھیں ۔ جس نے اہتمام کیا صحابہ نے اسے سراہا ۔ محدثین کی کاوشوں سے یہ سب سنتیں زندہ ہوئیں ۔","",{"u2":"احمد بن حنبل نے کہا:ہمیں یحییٰ بن سعید نے شعبہ سے حدیث سنائی ‘انھوں نے مجاہد سے ‘انھوں نے ابو معمر سے اور انھوں نے سیدنا عبد اللہ رضی اللہ عنہ سے روایت کی۔شعبہ نے کہا۔حکم نے ایک بار یہ روایت مرفوع بیان کی۔کہ ایک حاکم یا ایک آدمی نے دو طرف سلام پھیراتو عبداللہ(بن مسعود رضی اللہ عنہ)نے کہا:اس نے یہ (سنت)کہا سے اپنا لی ہے؟ گویا اس دور کے حاکموں نے ایسی سنتیں بھی ترک کی ہوئی تھیں۔جس نے اہتمام کیا صحابہ نے اسے سراہا۔محدثین کی کاوشوں سے یہ سب سنتیں زندہ ہوئیں۔"}],[1249,"عامر بن سعد نے اپنے وال ( سعد بن ابی وقاص رضی اللہ عنہ ) سے روایت کی ‘ انھوں نے کہا : میں رسول اللہ صلی اللہ علیہ وسلم کو اپنی دائیں اور بائیں جانب سلام پھیرتے دیکھا کرتا تھاٰحتی کہ میں آپ کے رخسار وں کی سفیدی دیکھتا تھا ۔","",{"u2":"عامر بن سعد نے اپنے وال(سعد بن ابی وقاص رضی اللہ عنہ)سے روایت کی ‘انھوں نے کہا:میں رسول اللہ صلی اللہ علیہ وسلم کو اپنی دائیں اور بائیں جانب سلام پھیرتے دیکھا کرتا تھاٰحتی کہ میں آپ کے رخسار وں کی سفیدی دیکھتا تھا۔"}],[1250,"زہیر بن حرب نے کہا : ہمیں سفیان بن عیینہ نے عمرو ( بن دینار ) سے حدیث سنائی ‘ انھوں نے کہا : مجھے ابو معبد نے ابن عباس رضی اللہ عنھما سے اس بات کی خبر دی ‘ بعد میں ( بھول جانے کی وجہ سے ) اس سے انکار کر دیا ‘ انھوں ( ابن عباس رضی اللہ عنہ ) نے کہا کہ ہمیں رسول اللہ کی نماز ختم ہونے کا پتہ تکبیر سے چلتا ہے ۔","",{"u2":"زہیر بن حرب نے کہا:ہمیں سفیان بن عیینہ نے عمرو (بن دینار)سے حدیث سنائی ‘انھوں نے کہا:مجھے ابو معبد نے ابن عباس رضی اللہ عنھما سے اس بات کی خبر دی ‘بعد میں(بھول جانے کی وجہ سے)اس سے انکار کر دیا ‘انھوں (ابن عباس رضی اللہ عنہ)نے کہا کہ ہمیں رسول اللہ کی نماز ختم ہونے کا پتہ تکبیر سے چلتا ہے۔"}],[1251,"ابن ابی عمر نے کہا : ہمیں سفیان بن عیینہ نے عمروبن دینار سے حدیث سنائی ‘ انھوں نے سیدنا ابن عباس رضی اللہ عنہ کے مولی ٰ ابو معبد کو ابن عباس کے حوالے سے بتاتے ہوئے سنا ‘ انھوں ( ابن عباس رضی اللہ عنہ ) نے کہا : ہمیں رسول اللہ صلی اللہ علیہ وسلم کی نماز ختم ہو جانے کا پتہ اللہ اکبر ہی سے لگتا تھا ۔ عمرو نےت کہا : میں نے اس روایت کا ( بعد میں ) ابو معبد کے سامنے ذکر کیا تو انھوں نے اس سے انکار کیا اور کہا : میں نے تمہیں یہ حدیث نہیں سنائی ۔ عمرو نے کہا : حالانکہ انھوں نے اس سے پہلے مجھے یہ بات بتائی تھی ۔","",{"u2":"ابن ابی عمر نے کہا:ہمیں سفیان بن عیینہ نے عمروبن دینار سے حدیث سنائی ‘ انھوں نے سیدنا ابن عباس رضی اللہ عنہ کے مولی ٰ ابو معبد کو ابن عباس کے حوالے سے بتاتے ہوئے سنا ‘ انھوں (ابن عباس رضی اللہ عنہ)نے کہا:ہمیں رسول اللہ صلی اللہ علیہ وسلم کی نماز ختم ہو جانے کا پتہ اللہ اکبر ہی سے لگتا تھا۔\nعمرو نےت کہا: میں نے اس روایت کا (بعد میں)ابو معبد کے سامنے ذکر کیا تو انھوں نے اس سے انکار کیا اور کہا: میں نے تمہیں یہ حدیثث نہیں سنائی۔ عمرو نے کہا:حالانکہ انھوں نے اس سے پہلے مجھے یہ بات بتائی تھی۔"}],[1252,"ابن جریج نے کہا : مجھے عمرو بن دینار نے بتایا کہ ابن عباس رضی اللہ عنہ کے آزاد کردہ ےغلام ابو معبد نے انھیں بتایا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے انھیں خبر دی کہ جب لوگ فرض نماز سے سلام پھیرتے تو اس کے بعد بلند آواز سے ذکر کرنا نبی اکرم صلی اللہ علیہ وسلم کے دور میں ( رائج ) تھا اور ابو معبد ) نے کہا : ابن عباس رضی اللہ عنہ نے فرمایا : جب لوگ سلام پھیرتے تو مجھے اس بات کا علم اسی ( بلند آواز کے ساتھ کیے گئے ذکر ) سے ہوتا تھا ۔","",{"u2":"ابن جریج نے کہا: مجھے عمرو بن دینار نے بتایا کہ ابن عباس رضی اللہ عنہ کے آزاد کردہ ےغلام ابو معبد نے انھیں بتایا کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے انھیں خبر دی کہ جب لوگ فرض نماز سے سلام پھیرتے تو اس کے بعد بلند آواز سے ذکر کرنا نبی اکرم صلی اللہ علیہ وسلم کے دور میں (رائج)تھا اور ابو معبد)نے کہا:ابن عباس رضی اللہ عنہ نے فرمایا:جب لوگ سلام پھیرتے تو مجھے اس بات کا علم اسی(بلندآواز کے ساتھ کیے گئے ذکر)سے ہوتا تھا۔"}],[1253,"عروہ بن زبیر نے حدیث بیان کی کہ سیدہ عائشہ رضی اللہ عنہا نے کہا : رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میرے پاس ایک یہودی عورت موجود تھی اور وہ کہہ رہی تھی : کیا تمہیں پتہ ہے کہ قبر و ں میں تمہارا امتحان ہوگا ؟عائشہ رضی اللہ عنہا کہتی ہیں : اس پر رسول اللہ صلی اللہ علیہ وسلم خوفزدہ ہو گئے اور فرمایا : ’’یہودی کی آزمائش ہو گی ۔ ‘‘ سیدہ عائشہ رضی اللہ عنہا نے بتلایا : کچھ دن گزرنے کے بعد رسو اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’کیا تمہیں پتہ چلا مجھے وحی کی گئی ہے کہ تم قبرو ں میں آزمائے جاؤ گے؟ ‘‘ سیدہ عائشہ رضی اللہ عنہا نے کہا : میں نے اس کے بعد رسول اللہ صلی اللہ علیہ وسلم کو سنا ‘ آپ عذاب قبر سے پناہ مانگتے تھے ۔","",{"u2":"عروہ بن زبیر نے حدیث بیان کی کہ سیدہ عائشہ رضی اللہ عنھانے کہا:رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے جبکہ میرے پاس ایک یہودی عورت موجود تھی اور وہ کہہ رہی تھی:کیا تمہیں پتہ ہے کہ قبر و ں میں تمہارہ امتحان ہوگا؟عائشہ رضی اللہ عنھا کہتی ہیں:اس پر رسول اللہ صلی اللہ علیہ وسلم خوفزدہ ہو گے اور فرمایا:’’یہودی کی آزمائش ہو گی۔‘‘حضرت عائشہ ررضی اللہ عنھا نے بتلایا:کچھ دن گزرنے کے بعد رسو اللہ صلی اللہ علیہ وسلم نے فرمایا:’’کیا تمہیں پتہ چلا مجھے وحی کی گئی ہے کہ تم قبرو ں میں آزمائے جاؤ گے؟‘‘سیدہ عائشہ رضی اللہ عنھا نے کہا:میں نے اس کے بعد رسو ل اللہ صلی اللہ علیہ وسلم کو سنا ‘آپعذاب قبر سے پناہ مانگتے تھے۔"}],[1254,"سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے ( یہودی عورت والے ) اس ( واقعے ) کے بعد آپ صلی اللہ علیہ وسلم سے سنا ‘ آپ قبر کے عذاب سے پناہ مانگتے تھے ۔","",{"u2":"سیدنا ابو ھریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے (یہودی عورت والے)اس (واقعے)کے بعد آپ صلی اللہ علیہ وسلم سے سنا ‘آپ قبر کے عذاب سے پناہ مانگتے تھے۔"}],[1255,"ابو وائل ( شقیق بن سلمہ ) نے مسروق سے اور انھوں نے سیدہ عائشہ ؓ سے روایت کی ، انھوں نے کہا : مدینہ کے یہودیوں کی بوڑھی عورتوں میں سے دو بوڑھیاں میرے گھر آئیں اور انھوں نے کہا : قبروں والوں کو ان کی قبروں میں عذاب دیا جاتا ہے ۔ میں نے ان دونوں کو جھٹلایا اور ان کی تصدیق کےلیے ہاں تک کہنا گوارانہ کیا ، وہ چلی گئیں اور رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے آپ سے کہا : اے اللہ کے رسول ! میرے پاس مدینہ کی بوڑھی یہودی عورتوں میں سے دو بوڑھیاں آئی تھیں ، ان کا خیا ل تھا کہ قبر والوں کو ان کی قبروں میں عذاب دیا جاتا ہے ۔ آپ نے ( کچھ دن گزر نے کے بعد ) فرمایا : ’’ان دونوں نے سچ کہا تھا ۔ ( قبروں میں ) ان ( کافروں ، گنا گاروں ) کو ایسا عذاب ہوتا ہے کہ اسے مویشی بھی سنتے ہیں ۔ ‘‘ اس کے بعد میں نے آپ کو دیکھا آپ ہر نماز میں قبر کے عذاب سے پناہ مانگتے تھے ۔","",{"u2":"ابو وائل (شقیق بن سلمہ)نے مسروق سے اور انھوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی،انھوں نے کہا:مدینہ کے یہودیوں کی بوڑھی عورتوں میں سے دو بوڑھیاں میرے گھر آئیں اور انھوں نے کہا: قبروں والوں کو ان کی قبروں میں عذاب دیا جاتا ہے۔ میں نے ان دونوں کو جھٹلایا اور ان کی تصدیق کےلیے ہاں تک کہنا گوارانہ کیا،وہ چلی گئیں اور رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے آپ سے کہا: اے اللہ کے رسول! میرے پاس مدینہ کی بوڑھی یہودی عورتوں میں سے دو بوڑھیاں آئی تھیں،ان کا خیا ل تھا کہ قبر والوں کو ان کی قبروں میں عذاب دیا جاتا ہے۔ آپ نے (کچھ دن گزر نے کے بعد)فرمایا: ’’ان دونوں نے سچ کہا تھا۔(قبروں میں)ان (کافروں،گنا گاروں)کو ایسا عذاب ہوتا ہے کہ اسے مویشی بھی سنتے ہیں۔ ‘‘ اس کے بعد میں نے آپ کو دیکھا آپ ہر نماز میں قبر کے عذاب سے پناہ مانگتے تھے۔"}],[1256,"(ابو وائل کے بجائے ) اشعث کے والد ( ابو شعثاء سلیم محاربی ) نے مسروق سے اور انھوں نے سیدہ عائشہ ؓ سے مذکورہ بالا حدیث روایت کی ۔ اور اس میں یہ ہے کہ سیدہ عائشہ ؓ نے کہا : آپ نے اس کے بعد جو نماز بھی پڑھی میں نے آپ سے سناکہ آپ اس میں قبر کے عذاب سے پناہ مانگتے تھے ۔","",{"u2":"ابو وائل کے بجائے)اشعث کے والد (ابو شعثاء سلیم محاربی)نے مسروق سے اور انھوں نے سیدہ عائشہ رضی اللہ عنہا سے مذکورہ بالا حدیث روایت کی۔ اور اس میں یہ ہے کہ سیدہ عائشہ رضی اللہ عنہا نے کہا: آپ نے اس کے بعد جو نماز بھی پڑھی میں نے آپ سے سناکہ آپ اس میں قبر کے عذاب سے پناہ مانگتے تھے۔"}],[1257,"سیدہ عائشہ ؓ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنی نماز میں ، دجال کے فتنے سے پناہ مانگتے سنا","",{"u2":"سیدہ عائشہ رضی اللہ عنہا نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنی نماز میں،دجال کے فتنے سے پناہ مانگتے سنا"}],[1258,"وکیع نے کہا : ہمیں اوزاعی نے حسان بن عطیہ سے حدیث سنائی ، انھوں نے محمد بن ابی عائشہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، نیز ( اوزاعی نے ) یحییٰ بن ابی کثیر سے ، انھوں نے ابو سلمہ سے اور انھون نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : روسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم میں سے کوئی تشہد پڑھ لے تو چار چیزوں سے اللہ کی پناہ طلب کرے ۔ ’’اے اللہ ! میں جہنم کے عذاب سے اور قبر کے عذاب سے اور زندگی اور موت میں آزمائش سے اور مسیح دجال کے فتنے کے شر سے تیری پناہ میں آتا ہوں","",{"u2":"وکیع نے کہا: ہمیں اوزاعی نے حسان بن عطیہ سے حدیث سنائی، انھوں نے محمد بن ابی عائشہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی،نیز (اوزاعی نے)یحییٰ بن ابی کثیر سے،انھوں نے ابو سلمہ سے اور انھون نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی،انھوں نے کہا: روسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب تم میں سے کوئی تشہد پڑھ لے تو چار چیزوں سے اللہ کی پناہ طلب کرے۔’’اے اللہ! میں جہنم کے عذاب سے اور قبر کے عذاب سے اور زندگی اور موت میں آزمائش سے اور مسیح دجال کے فتنے کے شر سے تیری پناہ میں آتا ہوں"}],[1259,"نبی کریم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ ؓ نے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم نماز میں ( یہ ) دعا مانگتے تھے : اے اللہ ! میں قبر کے عذاب سے تیری پنا ہ چاہتا ہوں اور مسیح دجال کے فتنے سے تیری پناہ کا طالب ہوں ، میں زندگی اور موت کے فتنے سے تیری پناہ مانگتا ہوں ، اے اللہ ! میں گناہ اور قرض ( میں پھنس جانے سے تیری پناہ چاہتا ہوں ۔ ‘‘ ) سیدہ عائشہ ؓ نے کہا : کسی کہنے والے نے کہا : اللہ رسول صلی اللہ علیہ وسلم آپ قرض سے کس قدر پناہ مانگتے ہیں ! آپ صلی اللہ علیہ وسلم نے فرمایا : ”جب آدمی مقروض ہو جائے تو بات کرتا ہے تو جھوٹ بولتا ہے اور وعدہ کرتا ہے تو اس کی خلاف ورزی کرتا ہے ‘‘","",{"u2":"نبی کریم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ عنہا نے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم نماز میں (یہ)دعا مانگتے تھے: اے اللہ! میں قبر کے عذاب سے تیری پنا ہ چاہتا ہوں اور مسیح دجال کے فتنے سے تیری پناہ کا طالب ہوں،میں زندگی اور موت کے فتنے سے تیری پناہ مانگتا ہوں،اے اللہ! میں گناہ اور قرض (میں پھنس جانے سے تیری پناہ چاہتا ہوں۔‘‘) سیدہ عائشہ رضی اللہ عنہا نے کہا: کسی کہنے والے نے کہا:اللہ رسول صلی اللہ علیہ وسلم آپ قرض سے کس قدر پناہ مانگتے ہیں! آپ صلی اللہ علیہ وسلم نے فرمایا:”جب آدمی مقروض ہو جائے تو بات کرتا ہے تو جھوٹ بولتا ہے اور وعدہ کرتا ہے تو اس کی خلاف ورزی کرتا ہے ‘‘"}],[1260,"ولید بن مسلم نےکہا : مجھے اوزاعی نے حدیث سنائی ، انہوں نے کہا : ہمیں حسان بن عطیہ نے حدیث سنائی ، کہا : مجھے محمد بن ابی عائشہ نے حدیث سنائی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے کوئی آخر ی تشہد سے فارغ ہو جائے تو چار چیزوں سے اللہ تعالیٰ کی پناہ طلب کرے : جہنم کے عذاب سے ، قبر کے عذاب سے زندگی اور موت کی آزمائش سے اور مسیح دجال کے شر سے ۔ ‘‘","",{"u2":"ولید بن مسلم نےکہا:مجھے اوزاعی نے حدیث سنائی،انہوں نے کہا:ہمیں حسان بن عطیہ نےحدیث سنائی، کہا:مجھے محمد بن ابی عائشہ نے حدیث سنائی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جب تم میں سے کوئی آخر ی تشہد سے فارغ ہو جائے تو چار چیزوں سے اللہ تعالیٰ کی پناہ طلب کرے: جہنم کے عذاب سے،قبر کے عذاب سے زندگی اور موت کی آزمائش سے اور مسیح دجال کے شر سے۔‘‘"}],[1261,"ولید بن مسلم نےکہا : مجھے اوزاعی نے حدیث سنائی ، انہوں نے کہا : ہمیں حسان بن عطیہ نے حدیث سنائی ، کہا : مجھے محمد بن ابی عائشہ نے حدیث سنائی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب تم میں سے کوئی آخر ی تشہد سے فارغ ہو جائے تو چار چیزوں سے اللہ تعالیٰ کی پناہ طلب کرے : جہنم کے عذاب سے ، قبر کے عذاب سے زندگی اور موت کی آزمائش سے اور مسیح دجال کے شر سے ۔ ‘‘","",{"u2":"ہقل بن زیاد اور عیسیٰ بن یونس دونوں نے اوزاعی کی مذکورہ سند سے یہی حدیث روایت کی،ا س میں ہے، آپ نے فرمایا: ’’جب تم میں سے کوئی تشہد سے فارغ ہو۔۔۔۔۔‘‘ انھوں نے الآخر (آخری تشہد)کے الفاظ نہیں کہے۔"}],[1262,"ہقل بن زیاد اور عیسیٰ بن یونس دونوں نے اوزاعی کی مذکورہ سند سے یہی حدیث روایت کی ، ا س میں ہے ، آپ نے فرمایا : ’’جب تم میں سے کوئی تشہد سے فارغ ہو ۔ ۔ ۔ ۔ ۔ ‘‘ انھوں نے الآخر ( آخری تشہد ) کے الفاظ نہیں کہے ۔","",{"u2":"ہشام نے یحییٰ سے اور انھوں نے ابو سلمہ سے روایت کی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہتے تھے: اللہ کے نبی صلی اللہ علیہ وسلم نے دعا کی: ’’اے اللہ! میں قبر کے عذاب سے تیری پناہ میں آتا ہوں اور آگ کے عذاب سے اور زندگی اور موت کی آزمائش سے اور مسیح دجال کے شر سے۔‘‘"}],[1263,"ہشام نے یحییٰ سے اور انھوں نے ابو سلمہ سے روایت کی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہتے تھے : اللہ کے نبی صلی اللہ علیہ وسلم نے دعا کی : ’’اے اللہ ! میں قبر کے عذاب سے تیری پناہ میں آتا ہوں اور آگ کے عذاب سے اور زندگی اور موت کی آزمائش سے اور مسیح دجال کے شر سے ۔ ‘‘","",{"u2":"عمرو (بن دینار)نے طاؤس سے روایت کی، انھوں نے کہا: میں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’اللہ کے عذاب سے اللہ کی پناہ طلب کرو، قبر کے عذاب سے اللہ کی پناہ مانگوں،مسیح دجال کے فتنے سے اللہ کی پناہ طلب کرو اور زندگی اور موت کے فتنے سے اللہ کی پناہ مانگو۔‘‘"}],[1264,"عمرو ( بن دینار ) نے طاؤس سے روایت کی ، انھوں نے کہا : میں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’اللہ کے عذاب سے اللہ کی پناہ طلب کرو ، قبر کے عذاب سے اللہ کی پناہ مانگوں ، مسیح دجال کے فتنے سے اللہ کی پناہ طلب کرو اور زندگی اور موت کے فتنے سے اللہ کی پناہ مانگو ۔ ‘‘","",{"u2":"طاوس کے بیٹے (عبداللہ)نے اپنے والد طاوس سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کی ماند روایت یک"}],[1265,"طاوس کے بیٹے ( عبداللہ ) نے اپنے والد طاوس سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کی ماند روایت یک","",{"u2":"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کی مانند روایت کی"}],[1266,"اعرج نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کی مانند روایت کی","",{"u2":"عبداللہ بن شقیق نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم قبر کے عذاب سے،جہنم کے عذاب سے اور دجال کے فتنے سے پناہ مانگا کرتے تھے۔"}],[1267,"طاوس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ان ( سب صحابہ ) کو اس دعا کی تعلیم اسی طرح دیتے تھے جس طرح انھیں قرآن مجید کی کسی سورت کی تعلیم دیتے تھے ۔ آپ فرماتے تھے : ’’سب کہو : اے اللہ ! ہم جہنم کے عذاب سے تیری پناہ مانگتے ہیں اور میں قبر کے عذاب سے تیری پناہ مانگتا ہوں اور مسیح دجال کے فتنے سے تیری پناہ مانگتا ہوں اور زندگی اور موت کے فتنے سے تیری پناہ مانگتا ہوں ۔ ‘‘ امام مسلم  نے کہا مجھے یہ بات پہنچی کہ طاوس نے اپنے بیٹے سے پوچھا : کیا تم نے اپنی نماز میں یہ دعا مانگی ہے ؟ اس نے جواب دیا : نہیں ۔ اس پرطاوس نے کہا : دوبارہ نماز پرھو کیونکہ انھوں نے ( حدیث میں مذکور ) یہ دعا تین یا چار صحابہ سے روایت کی یا جیسے انھوں نے کہا ۔ ( یعنی جتنے صحابہ سے انھوں نے کہا ۔)",""],[1268,"ولید نے اوزاعی سے ، انہوں نے ابو عمار ۔ ان کا نام شداد بن عبداللہ ہے ۔ سے ، انھوں نے ابو اسماء سے اور انھوں نے سیدنا ثوبان رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنی نماز سے فارغ ہوتے تو تین دفعہ استغفار کرتےاور اس کے بعد کہتے : اللہم انت السلام و منك السلام ، تباركت ذاالجلال والاكرام ’’ اے اللہ ! تو ہی سلام ہے اور سلامتی تیری ہی طرف سے ہے ، تو صاحب رفعت و برکت ہے ، اے جلال والے اور عزت بخشنے والے ! ‘‘ ولید نے کہا : میں نے اوزاعی سے پوچھا : استغفار کیسے کیا جائے ؟ انھوں نے کہا : استغفر اللہ ، استغفر اللہ کہے ۔","",{"u2":"ابو بکر بن ابی شبیہ اور ابن نمیر نے حدیث بیان کی،کہا ہمیں ابو معاویہ نے عاصم سے حدیث سنائی،انھوں نے عبداللہ بن حارث سے اور انھوں نے حضرت عائشہ رضی اللہ عنہم سے روایت کی، کہا رسول اللہ صلی اللہ علیہ وسلم سلام پھیرنے کے بعد صرف یہ ذکر پڑھنے تک ہی (قبلہ رخ)بیٹھتے: اللہم! انت السلام ومنک السلام تبارکت ذاالجلال والاکرام ’’اے اللہ! تو ہی سلام ہے اور سلامتی تیری ہی طرف سے ہے،تو صاحب رفعت وبرکت ہے، اے جلال والے اور عزت بخشنے والے! ‘‘ ابن نمیر کی روایت میں: یا ذالجلال والاکرام (یا کے اضافے کے ساتھ)ہے"}],[1269,"ابو بکر بن ابی شبیہ اور ابن نمیر نے حدیث بیان کی ، کہا ہمیں ابو معاویہ نے عاصم سے حدیث سنائی ، انھوں نے عبداللہ بن حارث سے اور انھوں نے سیدہ عائشہ رضی اللہ عنہم سے روایت کی ، کہا رسول اللہ صلی اللہ علیہ وسلم سلام پھیرنے کے بعد صرف یہ ذکر پڑھنے تک ہی ( قبلہ رخ ) بیٹھتے : اللہم ! انت السلام ومنک السلام تبارکت ذاالجلال والاکرام ’’اے اللہ ! تو ہی سلام ہے اور سلامتی تیری ہی طرف سے ہے ، تو صاحب رفعت وبرکت ہے ، اے جلال والے اور عزت بخشنے والے ! ‘‘ ابن نمیر کی روایت میں : یا ذالجلال والاکرام ( یا کے اضافے کے ساتھ ) ہے"],[1270,"ابو خالد احمر نے عاصم سے اسی سند کے ساتھ یہی حدیث بیان کی اور یا ذالجلال والاکرام ( یا کے اضافے کے ساتھ ) کہا ۔","",{"u2":"ابو خالد احمر نے عاصم سے اسی سند کے ساتھ یہی حدیث بیان کی اور یا ذالجلال والاکرام (یا کے اضافے کے ساتھ)کہا۔"}],[1271,"شعبہ نے عاصم اور خالد سے روایت کرتے ہوئے عبداللہ بن حارث سے حدیث بیان کی ، انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہم سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ، مگر وہ ( شعبہ یا کے اضافے کے ساتھ ) یا ذاالجلال والاکرام کہا کرتے تھے ۔","",{"u2":"شعبہ نے عاصم اور خالد سے روایت کرتے ہوئے عبداللہ بن حارث سے حدیث بیان کی، انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہم سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی،مگر وہ (شعبہ یا کے اضافے کے ساتھ)یا ذاالجلال والاکرام کہا کرتے تھے۔"}],[1272,"منصور نے مسیّب بن رافع سے ، انھوں نے مغیرہ بن شعبہ رضی اللہ عنہ کے مولیٰ وراد سے روایت کی ، انھوں نے کہا : سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے ( ان کے مطالبے پر ) معاویہ رضی اللہ عنہ کو لکھ کر بھیجا کہ جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہو کر سلام پھیرتے تو فرماتے : ’’ ایک اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ یکتا ہے ، اس کا کوئی شریک نہیں ، حکومت اور فرمانروائی اسی کی ہے ، وہی شکرو ستائش کا حقدار ہے اور ہر چیز پر قدرت رکھنے والا ہے ۔ اے اللہ ! جو کچھ تو کسی کودے اسے کوئی روک سکنے والا نہیں اورجس چیز کو تو روک لے کوئی اسے دے سکنے والا نہیں اور تیرے سامنے کسی شان والے کو اس کی شان کوئی فاعدہ نہیں دے سکتی","",{"u2":"منصور نے مسیّب بن رافع سے، انھوں نے مغیرہ بن شعبہ رضی اللہ عنہ کے مولیٰ وراد سے روایت کی، انھوں نے کہا: سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے(ان کے مطالبے پر)معاویہ رضی اللہ عنہ کو لکھ کر بھیجا کہ جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہو کر سلام پھیرتے تو فرماتے:’’ ایک اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ یکتا ہے، اس کا کوئی شریک نہیں، حکومت اور فرمانروائی اسی کی ہے، وہی شکرو ستائش کا حقدار ہے اور ہر چیز پر قدرت رکھنے والا ہے۔ اے اللہ! جو کچھ تو کسی کودے اسے کوئی روک سکنے والا نہیں اورجس چیز کو تو روک لے کوئی اسے دے سکنے والا نہیں اور تیرے سامنے کسی شان والے کو اس کی شان کوئی فاعدہ نہیں دے سکتی"}],[1273,"ابوبکر بن ابی شیبہ ، ابو کریب اور احمد بن سنان نے ہمیں حدیث بیان کی ، ان سب نے کہا : ہمیں ابو معاویہ نے اعمش سے حدیث سنائی ، انھوں نے مسیب بن رافع سے ، انھون نے مغیرہ بن شعبہ رضی اللہ عنہ کے مولیٰ وراد سے ، انھوں نےسیدنا مغیرہ بن شعبہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت بیا ن کی ۔ ابو بکر اور ابو کریب نے اپنی روایت میں : ( وراد نے ) کہا : مغیرہ رضی اللہ عنہ نے یہ بات مجھے لکھوائی اور میں نے یہ بات سیدنا معاویہ رضی اللہ عنہ کی طرف لکھ بھیجی ۔","",{"u2":"ابوبکر بن ابی شیبہ،ابو کریب اور احمد بن سنان نے ہمیں حدیث بیان کی، ان سب نے کہا: ہمیں ابو معاویہ نے اعمش سےحدیث سنائی، انھوں نے مسیب بن رافع سے، انھون نے مغیرہ بن شعبہ رضی اللہ عنہ کے مولیٰ وراد سے، انھوں نےسیدنا مغیرہ بن شعبہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت بیا ن کی۔ ابو بکر اور ابو کریب نے اپنی روایت میں: (وراد نے)کہا: مغیرہ رضی اللہ عنہ نے یہ بات مجھے لکھوائی اور میں نے یہ بات سیدنا معاویہ رضی اللہ عنہ کی طرف لکھ بھیجی۔"}],[1274,"ابن عون نے ابو سعید سے ، انھوں نے ورّاد سے ۔ جو مغیرہ بن شعبہ رضی اللہ عنہ کےکاتب تھے ۔ روایت کی ، کہا : معاویہ رضی اللہ عنہ نے مغیرہ رضی اللہ عنہ کی طرف لکھا ( مسئلہ دریافت کیا ) ۔ ۔ ۔ ۔ ۔ ۔ ( آگے ) منصور اور اعمش کی حدیث کے مطابق ( ہے ۔)","",{"u2":"ابن عون نے ابو سعید سے، انھوں نے ورّاد سے۔ جو مغیرہ بن شعبہ رضی اللہ عنہ کےکاتب تھے۔روایت کی، کہا:معاویہ رضی اللہ عنہ نےمغیرہ رضی اللہ عنہ کی طرف لکھا (مسئلہ دریافت کیا)۔۔۔۔۔۔(آگے)منصور اور اعمش کی حدیث کے مطابق (ہے۔)"}],[1275,"سفیان نے کہا : ہمیں عبدہ بن ابی لبابہ اور عبدالملک بن عمیر نے حدیث سنائی ، انھوں نے مغیرہ بن شعبہ رضی اللہ عنہ کے کاتب ورّاد سے سنا ، وہ کہتے تھے : سیدنا معاویہ رضی اللہ عنہ نے مغیرہ رضی اللہ عنہ کو خط لکھا کہ مجھے کوئی ایسی چیز لکھ بھیجیں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو ، تو انھوں نے لکھ بھیجا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، جب آپ نماز ختم کر لیتے تو فرماتے : لاإله إلا اللہ وحده لاشريك له ، له مالملك ولاه الحمد ، وهو علي كل شيء قدير ، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذالجد منك الجد ’’ اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا اور یکتا ہے ، اس کا کوئی شریک نہیں ، حکومت اور فرمانروائی اسی کی ہے ، وہی شکرو ستائش کا حقدار ہے اور وہی ہر چیز پر قدرت رکھنے والا ہے ۔ اے اللہ ! جو کچھ تو کسی کو دینا چاہے اسے کوئی روک سکنے والا نہیں اور تیرے سامنے کسی شان والے کو اس کی شان کوئی فائدہ نہیں دے سکتی ۔ ‘‘","",{"u2":"سفیان نے کہا: ہمیں عبدہ بن ابی لبابہ اور عبدالملک بن عمیر نے حدیث سنائی، انھوں نے مغیرہ بن شعبہ رضی اللہ عنہ کے کاتب ورّاد سے سنا، وہ کہتے تھے: سیدنا معاویہ رضی اللہ عنہ نے مغیرہ رضی اللہ عنہ کو خط لکھا کہ مجھے کوئی ایسی چیز لکھ بھیجیں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو، تو انھوں نے لکھ بھیجا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، جب آپ نماز ختم کر لیتے تو فرماتے: لاإلہ إلا اللہ وحدہ لاشریک لہ، لہ مالملک ولاہ الحمد، وہو علی کل شیء قدیر، اللہم لا مانع لما أعطیت ولا معطی لما منعت ولا ینفع ذالجد منک الجد ’’ اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا اور یکتا ہے، اس کا کوئی شریک نہیں، حکومت اور فرمانروائی اسی کی ہے، وہی شکرو ستائش کا حقدار ہے اور وہی ہر چیز پر قدرت رکھنے والا ہے۔ اے اللہ! جو کچھ تو کسی کو دینا چاہے اسے کوئی روک سکنے والا نہیں اور تیرے سامنے کسی شان والے کو اس کی شان کوئی فائدہ نہیں دے سکتی۔‘‘"}],[1276,"سفیان نے کہا : ہمیں عبدہ بن ابی لبابہ اور عبدالملک بن عمیر نے حدیث سنائی ، انھوں نے مغیرہ بن شعبہ رضی اللہ عنہ کے کاتب ورّاد سے سنا ، وہ کہتے تھے : سیدنا معاویہ رضی اللہ عنہ نے مغیرہ رضی اللہ عنہ کو خط لکھا کہ مجھے کوئی ایسی چیز لکھ بھیجیں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو ، تو انھوں نے لکھ بھیجا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، جب آپ نماز ختم کر لیتے تو فرماتے : لاإله إلا اللہ وحده لاشريك له ، له مالملك ولاه الحمد ، وهو علي كل شيء قدير ، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذالجد منك الجد ’’ اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا اور یکتا ہے ، اس کا کوئی شریک نہیں ، حکومت اور فرمانروائی اسی کی ہے ، وہی شکرو ستائش کا حقدار ہے اور وہی ہر چیز پر قدرت رکھنے والا ہے ۔ اے اللہ ! جو کچھ تو کسی کو دینا چاہے اسے کوئی روک سکنے والا نہیں اور تیرے سامنے کسی شان والے کو اس کی شان کوئی فائدہ نہیں دے سکتی ۔ ‘‘","",{"u2":"سفیان نے کہا: ہمیں عبدہ بن ابی لبابہ اور عبدالملک بن عمیر نے حدیث سنائی، انھوں نے مغیرہ بن شعبہ رضی اللہ عنہ کے کاتب ورّاد سے سنا، وہ کہتے تھے: سیدنا معاویہ رضی اللہ عنہ نے مغیرہ رضی اللہ عنہ کو خط لکھا کہ مجھے کوئی ایسی چیز لکھ بھیجیں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو، تو انھوں نے لکھ بھیجا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، جب آپ نماز ختم کر لیتے تو فرماتے: لاإلہ إلا اللہ وحدہ لاشریک لہ، لہ مالملک ولاہ الحمد، وہو علی کل شیء قدیر، اللہم لا مانع لما أعطیت ولا معطی لما منعت ولا ینفع ذالجد منک الجد ’’ اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا اور یکتا ہے، اس کا کوئی شریک نہیں، حکومت اور فرمانروائی اسی کی ہے، وہی شکرو ستائش کا حقدار ہے اور وہی ہر چیز پر قدرت رکھنے والا ہے۔ اے اللہ! جو کچھ تو کسی کو دینا چاہے اسے کوئی روک سکنے والا نہیں اور تیرے سامنے کسی شان والے کو اس کی شان کوئی فائدہ نہیں دے سکتی۔‘‘"}],[1277,"محمد کے والد عبداللہ بن نمیر نے کہا : ہمیں ہشام نے ابو زبیر سے حدیث سنائی ، کہا : ( عبداللہ ) زبیر رضی اللہ عنہما سلام پھیر کر ہر نماز کے بعد یہ کلمات کہتے تھے : ’’ ایک اللہ کے سوا کوئی عبادت کے لائق نہیں ، اس کا کوئی شریک نہیں ، حکومت اور فرمانروائی اسی کی ہے اور وہی شکر و ستائش کا حقدار ہے اور وہی ہر چیز پر قادر ہے ۔ گناہوں سے بچنے کی توفیق اور نیکی کرنے کی قوت اللہ ہی سے ( ملتی ) ہے ، اس کے سوا کوئی الہ و معبود نہیں ۔ ہم اس کےسوا کسی کی بندگی نہیں کرتے ، ہر طرح کی نعمت اور سارا فضل و کرم اسی کا ہے ، خوبصورت تعریف کا سزا وار بھی وہی ہے ، اللہ کے سوا کوئی معبود نہیں ، ہم اس کے لیے دین میں اخلاص رکھنے والے ہیں ، چاہے کافر اس کو ( کتنا ہی ) نا پسند کریں ۔ ‘‘ اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم ہر نماز کے بعد بلند آواز سے لا الہ الا اللہ والے یہ کلمات کہا کرتے تھے ۔","",{"u2":"محمد کے والد عبداللہ بن نمیر نے کہا: ہمیں ہشام نے ابو زبیر سے حدیث سنائی، کہا: (عبداللہ)زبیر رضی اللہ عنہما سلام پھیر کر ہر نماز کے بعد یہ کلمات کہتے تھے: ’’ ایک اللہ کے سوا کوئی عبادت کے لائق نہیں، اس کا کوئی شریک نہیں،حکومت اور فرمانروائی اسی کی ہے اور وہی شکر و ستائش کا حقدار ہے اور وہی ہر چیز پر قادر ہے۔گناہوں سے بچنے کی توفیق اور نیکی کرنے کی قوت اللہ ہی سے (ملتی)ہے، اس کے سوا کوئی الہ و معبود نہیں۔ ہم اس کےسوا کسی کی بندگی نہیں کرتے، ہر طرح کی نعمت اور سارا فضل و کرم اسی کا ہے، خوبصورت تعریف کا سزا وار بھی وہی ہے، اللہ کے سوا کوئی معبود نہیں، ہم اس کے لیے دین میں اخلاص رکھنے والے ہیں،چاہے کافر اس کو (کتنا ہی)نا پسند کریں۔ ‘‘ اور کہا کہ رسو ل اللہ صلی اللہ علیہ وسلم ہر نماز کے بعد بلند آواز سے لا الہ الا اللہ والے یہ کلمات کہا کرتے تھے۔"}],[1278,"عبدہ بن سلیمان نے ہشام بن عروہ سے اور انھوں نے اپنے خاندان کے مولیٰ ابو زبیر سے روایت کی کہ سیدنا عبداللہ بن زبیر رضی اللہ عنہ ہر نماز کے بعد بلند آواز سے پڑھتے تھے ( آگے ) ابن نمیر کی روایت کے مانند ہے اور انھوں نے اپنی حدیث کے آخر میں کہا : پھر ابن زبیر کہتےکہ رسول اللہ صلی اللہ علیہ وسلم ہر نماز کے بعد ان ( کلمات ) کو بلند آواز سے کہتے تھے ۔","",{"u2":"عبدہ بن سلیمان نے ہشام بن عروہ سے اور انھوں نے اپنے خاندان کے مولیٰ ابو زبیر سے روایت کی کہ سیدنا عبداللہ بن زبیر رضی اللہ عنہ ہر نماز کے بعد بلند آواز سے پڑھتے تھے (آگے)ابن نمیر کی روایت کے مانند ہے اور انھوں نے اپنی حدیث کے آخر میں کہا: پھر ابن زبیر کہتےکہ رسول اللہ صلی اللہ علیہ وسلم ہر نماز کے بعد ان (کلمات)کو بلند آواز سے کہتے تھے۔"}],[1279,"(ہشام کے بجائے ) حجاج بن ابی عثمان نے مجھے حدیث بیان کی ، کہا : مجھ سے ابو زبیر نے حدیث بیان کی کہا : میں نے عبداللہ بن زبیر رضی اللہ عنہ سے سنا ، وہ اس منبر پر خطبہ دے رہے تھے اور کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نماز یا نمازوں کے آخر میں سلام پھیرنے کے بعد کہا کرتے تھے ۔ ۔ ۔ ۔ ۔ ۔ ۔ ( آگے ) ہشام بن عروہ کی حدیث کی طرح بیان کیا ۔","",{"u2":"ہشام کے بجائے)حجاج بن ابی عثمان نے مجھے حدیث بیان کی، کہا:مجھ سے ابو زبیر نے حدیث بیان کی کہا: میں نے عبداللہ بن زبیر رضی اللہ عنہ سے سنا،وہ اس منبر پر خطبہ دے رہے تھے اور کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نماز یا نمازوں کے آخر میں سلام پھیرنے کے بعد کہا کرتے تھے۔۔۔۔۔۔۔(آگے)ہشام بن عروہ کی حدیث کی طرح بیان کیا۔"}],[1280,"موسیٰ بن عقبہ سے روایت ہے کہ ابو زبیر مکی نے انھیں حدیث سنائی کہ انھوں نے عبداللہ بن زبیر رضی اللہ عنہ سے سنا ، جب وہ نماز کے بعد سلام پھیرتے تو کہتے ۔ ۔ ۔ ( بقیہ روایت ) ان دونوں ( ہشام اور حجاج ) کی ( مذکورہ بالا ) روایت کے مانند ہے ، اور آخر میں کہا : وہ اسے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیا کرتے تھے","",{"u2":"موسیٰ بن عقبہ سے روایت ہے کہ ابو زبیر مکی نے انھیں حدیث سنائی کہ انھوں نے عبداللہ بن زبیر رضی اللہ عنہ سے سنا،جب وہ نماز کے بعد سلام پھیرتے تو کہتے۔۔۔(بقیہ روایت)ان دونوں (ہشام اور حجاج)کی (مذکورہ بالا)روایت کے مانند ہے، اور آخر میں کہا: وہ اسے رسو ل اللہ صلی اللہ علیہ وسلم سے بیان کیا کرتے تھے"}],[1281,"عاصم بن نضر تیمی نے کہا : ہمین معتمر نے حدیث سنائی ، کہا : ہمین عبیداللہ نے حدیث سنائی نیز ( ایک اور سند سے ) قتیبہ بن سعید نے کہا : ہمیں لیث نے ابن عجلان سے حدیث سنائی ، ان دونوں ( عبیداللہ اور ابن عجلان ) نے سًمَیّ سے ، انھوں نے ابو صالح سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ۔ ۔ یہ قتیبہ کی روایت کردہ حدیث ہے ۔ کہ کچھ تنگدست مہاجر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور گزارش کی : بلند درجے اور دائمی نعمت تو زیادہ مال والے لوگ لے گئے ! آپ نے پوچھا : ’’ وہ کیسے ؟ ‘‘ انھوں نے کہا : وہ اسی طرح نمازیں پڑھتے ہیں جس طرح ہم پڑھتے ہیں ، وہ اسی طرح روزے رکھتے ہیں جیسے ہم رکھتے ہیں اور وہ صدقہ کرتے ہیں جبکہ ہم صدقہ نہیں کر سکتے ، وہ ( بندھے ہوؤں اور غلاموں کو ) آزاد کرتے ہیں جبکہ ہم آزاد نہیں کر سکتے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’تو کیا پھر میں تمھیں اسی چیز نہ سکھاؤں جس سے تم ان لوگوں کو پالو گے جو تم سے سبقت لے گے ہیں اور اس کے ذریعے سے ان سے بھی سبقت لے جاؤ گے جو تم سے بعد ( آنے والے ) ہیں ؟ اور تم سے وہی افضل ہو گا جو تمھاری طرح عمل کرے گا ۔ ‘‘ انھوں نے کہا : کیوں نہیں اے اللہ کے رسول ! ( ضرور بتائیں ۔ ) آپ نے فرمایا : ’’تم ہر نماز کے بعد تینتیس مرتبہ تسبیح : تکبیر اور تحمید ( سبحان اللہ : اللہ اکبر ، اور الحمد اللہ ) کا ورد کیا کرو ‘‘ ابو صالح نےکہا : فقرائے مہاجرین دوبارہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور کہنے لگے : ہمارے مالدار بھائیوں نے بھی جو ہم کرتے ہیں اس کے بارے میں سن لیا ہے اور اسی طرح عمل کرنا شروع کر دیا ہے ( وہ بھی تسبیح ، تکبیر اور تحمید کرنے لگے ہیں ۔ ) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ یہ اللہ کا فضل ہے جسے چاہے عنایت فرمادے ۔ ‘‘ قتیبہ کے علاوہ لیث سے ابن عجلان کے حوالے سے دیگر روایت کرنے والوں نے یہ اضافہ کیا کہ سمی نے کہا : میں نے یہ حدیث اپنے گھر کے ایک فرد کو سنائی تو انھوں نے کہا : تمھیں وہم ہوا ہے ، انھوں ( ابو صالح ) نے تو کہا تھا : ’’تینتیس مرتبہ سبحان اللہ کہو ، تینتیس بار الحمد اللہ کہو اور تینتیس بار اللہ اکبر کہو ۔ ‘‘ میں دوبارہ ابو صالح کی خدمت میں حاضر ہوا اور انھیں یہ بتا یا تو انھوں نے میرا ہاتھ پکڑ کر کہا : اللہ اکبر ، سبحان اللہ اور الحمد اللہ ، اللہ اکبر ، سبحان اللہ اور الحمد اللہ ( اس طرح کہو ) کہ سب کی تعداد تینتیس ہو جائے ۔ ابن عجلان نے کہا : میں نے یہ حدیث رجاء بن حیوہ کو سنائی تو انھوں نے مجھے ابو صالح کے واسطے سے ابوہریرہ رضی اللہ عنہ سے ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے ( روایت کرتے ہوئے ) اسی کی مانند حدیث سنائی ۔","",{"u2":"عاصم بن نضر تیمی نے کہا:ہمین معتمر نے حدیث سنائی، کہا:ہمین عبیداللہ نے حدیث سنائی نیز (ایک اور سند سے)قتیبہ بن سعید نے کہا: ہمیں لیث نے ابن عجلان سے حدیث سنائی، ان دونوں (عبیداللہ اور ابن عجلان)نے سًمَیّ سے، انھوں نے ابو صالح سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی۔۔یہ قتیبہ کی روایت کردہ حدیث ہے۔ کہ کچھ تنگدست مہاجر رسو ل اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور گزارش کی: بلند درجے اور دائمی نعمت تو زیادہ مال والے لوگ لے گئے! آپ نے پوچھا:’’ وہ کیسے؟ ‘‘ انھوں نے کہا: وہ اسی طرح نمازیں پڑھتے ہیں جس طرح ہم پڑھتے ہیں، وہ اسی طرح روزے رکھتے ہیں جیسے ہم رکھتے ہیں اور وہ صدقہ کرتے ہیں جبکہ ہم صدقہ نہیں کر سکتے، وہ (بندھے ہوؤں اور غلاموں کو)آزاد کرتے ہیں جبکہ ہم آزاد نہیں کر سکتے تو رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا ’’تو کیا پھر میں تمھیں اسی چیز نہ سکھاؤں جس سے تم ان لوگوں کو پالو گے جو تم سے سبقت لے گے ہیں اور اس کے ذریعے سے ان سے بھی سبقت لے جاؤ گے جو تم سے بعد (آنے والے)ہیں؟ اور تم سے وہی افضل ہو گا جو تمھاری طرح عمل کرے گا۔‘‘ انھوں نے کہا:کیوں نہیں اے اللہ کے رسول! (ضرور بتائیں۔)آپ نے فرمایا:’’تم ہر نماز کے بعد تینتیس مرتبہ تسبیح:تکبیر اور تحمید (سبحان اللہ:اللہ اکبر، اور الحمد اللہ)کا ورد کیا کرو‘‘\nابو صالح نےکہا: فقرائے مہاجرین دوبارہ رسو ل اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور کہنے لگے: ہمارے مالدار بھائیوں نے بھی جو ہم کرتے ہیں اس کے بارے میں سن لیا ہے اور اسی طرح عمل کرنا شروع کر دیا ہے (وہ بھی تسبیح،تکبیر اور تحمید کرنے لگے ہیں۔)تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ یہ اللہ کا فضل ہے جسے چاہے عنایت فرمادے۔‘‘\nقتیبہ کے علاوہ لیث سے ابن عجلان کے حوالے سے دیگر روایت کرنے والوں نے یہ اضافہ کیا کہ سمی نے کہا: میں نے یہ حدیث اپنے گھر کے ایک فرد کو سنائی تو انھوں نے کہا: تمھیں وہم ہوا ہے، انھوں (ابو صالح)نے تو کہا تھا: ’’تینتیس مرتبہ سبحان اللہ کہو،تینتیس بار الحمد اللہ کہو اور تینتیس بار اللہ اکبر کہو۔ ‘‘ میں دوبارہ ابو صالح کی خدمت میں حاضر ہوا اور انھیں یہ بتا یا تو انھوں نے میرا ہاتھ پکڑ کر کہا: اللہ اکبر، سبحان اللہ اور الحمد اللہ، اللہ اکبر، سبحان اللہ اور الحمد اللہ (اس طرح کہو)کہ سب کی تعداد تینتیس ہو جائے۔\nابن عجلان نے کہا:میں نے یہ حدیث رجاء بن حیوہ کو سنائی تو انھوں نے مجھے ابو صالح کے واسطے سے ابوہریرہ رضی اللہ عنہ سے، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے (روایت کرتے ہوئے) اسی کی مانند حدیث سنائی۔"}],[1282,"امیہ بسطام عیشی نے مجھے حدیث سنائی ، کہا : ہمیں یزید بن زریع نے حدیث سنائی ، کہا ہمیں روح نے سہیل سے حدیث سنائی انھون نے اپنے والد ( ابو صالح سے ) سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھون نے رسو اللہ صلی اللہ علیہ وسلم سے روایت کی کہ لوگوں نے کہا : اے اللہ کے رسول ! بلند مراتب اور دائمی نعمتیں تو زیادہ مال والے لوگ لے گئے ۔ ۔ ۔ جس طرح لیث سے قتیبہ کی بیان کی ہوئی حدیث ہے ، مگر انھوں نے ابو ہریرہ رضی اللہ عنہ کی حدیث میں ابو صالح کا یہ قول داخل کر دیا ہے کہ پھر فقراء مہاجرین لوٹ کر آئے ، حدیث کے آخر تک ۔ اور حدیث میں اس بات کا اضافہ کیا : سہیل کہتے تھے : ( ہر کلمہ ) گیارہ گیارہ دفعہ اور یہ سب ملا کر تینتیس بار ۔ ( یہ سہیل کا اپنا فہم تھا ۔)","",{"u2":"امیہ بسطام عیشی نے مجھے حدیث سنائی، کہا: ہمیں یزید بن زریع نےحدیث سنائی، کہا ہمیں روح نے سہیل سے حدیث سنائی انھون نے اپنے والد (ابو صالح سے)سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھون نے رسو اللہ صلی اللہ علیہ وسلم سے روایت کی کہ لوگوں نے کہا: اے اللہ کے رسول! بلند مراتب اور دائمی نعمتیں تو زیادہ مال والے لوگ لے گئے۔۔۔جس طرح لیث سےقتیبہ کی بیان کی ہوئی حدیث ہے،مگر انھوں نے ابو ہریرہ رضی اللہ عنہ کی حدیث میں ابو صالح کا یہ قول داخل کر دیا ہے کہ پھر فقراء مہاجرین لوٹ کر آئے،حدیث کے آخر تک۔ اور حدیث میں اس بات کا اضافہ کیا: سہیل کہتے تھے:(ہر کلمہ)گیارہ گیارہ دفعہ اور یہ سب ملا کر تینتیس بار۔ (یہ سہیل کا اپنا فہم تھا۔)"}],[1283,"مالک بن مغول نے ہمیں خبر دی ، کہا : میں نے حکم بن عتیبہ سے سنا ، وہ عبدالرحمن بن ابی لیلیٰ سے حدیث بیان کررہے تھے ، انھوں نے سیدنا کعب بن عجرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ سے روایت کی ، آپ نے فرمایا : ’’ ( نماز کے یا ) ایک دوسرے کے پیچھے کہے جانے والے ایسے کلمات ہیں کہ ہرفرض نماز کے بعد انھیں کہنے والا ۔ ۔ یا ان کو ادا کرنے والا ۔ کبھی نامراد و ناکام نہیں رہتا ، تینتیس بار سبحان اللہ ، تینتیس بار الحمد اللہ اورچونتیس با ر اللہ اکبر ۔ ‘‘","",{"u2":"مالک بن مغول نے ہمیں خبر دی، کہا:میں نے حکم بن عتیبہ سے سنا، وہ عبدالرحمن بن ابی لیلیٰ سے حدیث بیان کررہے تھے، انھوں نے سیدنا کعب بن عجرہ رضی اللہ عنہ سے اور انھوں نے رسو ل اللہ سے روایت کی، آپ نے فرمایا:’’(نماز کے یا)ایک دوسرے کے پیچھے کہے جانے والے ایسے کلمات ہیں کہ ہرفرض نماز کے بعد انھیں کہنے والا۔۔یا ان کو ادا کرنے والا۔کبھی نامراد و ناکام نہیں رہتا، تینتیس بار سبحان اللہ،تینتیس بار الحمد اللہ اورچونتیس با ر اللہ اکبر۔‘‘"}],[1284,"حمزہ زیات نے ہمیں حکم سے حدیث بیان کی ، انھوں نے عبدالرحمن بن ابی لیلیٰ سے ، انھوں نے سیدنا کعب بن عجرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’ ایک دوسرے کےبعد کہے جانے والے ( کچھ ) کلمات ہیں ، ان کو کہنے والا ۔ یا ادا کرنے والا ۔ نا کام یا نامراد نہیں رہتا ۔ ہر ( فرض ) نماز کے بعد تینتیس دفعہ سبحان اللہ ، تینتیس مرتبہ الحمد اللہ اور چونتیس بار اللہ اکبر کہنا ۔ ‘‘","",{"u2":"حمزہ زیات نے ہمیں حکم سے حدیث بیان کی، انھوں نے عبدالرحمن بن ابی لیلیٰ سے، انھوں نے سیدنا کعب بن عجرہ رضی اللہ عنہ سے اور انھوں نے رسو ل اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا:’’ ایک دوسرے کےبعد کہے جانے والے (کچھ)کلمات ہیں، ان کو کہنے والا۔ یا ادا کرنے والا۔ نا کام یا نامراد نہیں رہتا۔ ہر (فرض)نماز کے بعد تینتیس دفعہ سبحان اللہ،تینتیس مرتبہ الحمد اللہ اور چونتیس بار اللہ اکبر کہنا۔‘‘"}],[1285,"حمزہ زیات نے ہمیں حکم سے حدیث بیان کی ، انھوں نے عبدالرحمن بن ابی لیلیٰ سے ، انھوں نے سیدنا کعب بن عجرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’ ایک دوسرے کےبعد کہے جانے والے ( کچھ ) کلمات ہیں ، ان کو کہنے والا ۔ یا ادا کرنے والا ۔ نا کام یا نامراد نہیں رہتا ۔ ہر ( فرض ) نماز کے بعد تینتیس دفعہ سبحان اللہ ، تینتیس مرتبہ الحمد اللہ اور چونتیس بار اللہ اکبر کہنا ۔ ‘‘","",{"u2":"عمرو بن قیس ملائی نے حکم سے اسی سند کے ساتھ اسی کی مانند حدیث بیان کی۔"}],[1286,"خالد بن عبداللہ نے ہمیں سہیل سے خبر دی ، انھوں نے ابو عبید مذحجی سے روایت کی ۔ امام مسلم رحمۃ اللہ نے کہا : ابو عبید سلیمان بن عبدالملک کے مولیٰ تھے ۔ انھوں نے عطاء بن یزید لیثی سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی : ’’جس نے ہر نماز کے بعد تینتیس مرتبہ سبحان اللہ تینتیس دفعہ الحمد اللہ اور تینتیس بار اللہ اکبر کہا ، یہ ننانوے ہو گے اور سو پورا کرنے کے لیے لا الہ الا اللہ وحد ہ لا شریک لہ ، لہ الملک ولاہ الحمد ، وہو علی کل شیء قدیر ‘‘ کیا اس کے گناہ معاف کر دیے جائیں گے ، چاہے وہ سمندر کے جھاگ کے برابر ہوں ۔ ‘‘","",{"u2":"خالد بن عبداللہ نے ہمیں سہیل سے خبر دی، انھوں نے ابو عبید مذحجی سے روایت کی۔امام مسلم رحمۃ اللہ نے کہا:ابو عبید سلیمان بن عبدالملک کے مولیٰ تھے۔ انھوں نے عطاء بن یزید لیثی سے،انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے رسو ل اللہ صلی اللہ علیہ وسلم سے روایت کی:’’جس نے ہر نماز کے بعد تینتیس مرتبہ سبحان اللہ تینتیس دفعہ الحمد اللہ اور تینتیس بار اللہ اکبر کہا، یہ ننانوے ہو گے اور سو پورا کرنے کے لیے لا الہ الا اللہ وحد ہ لا شریک لہ،لہ الملک ولاہ الحمد، وہو علی کل شیء قدیر ‘‘ کیا اس کے گناہ معاف کر دیے جائیں گے، چاہے وہ سمندر کے جھاگ کے برابر ہوں۔‘‘"}],[1287,"اسماعیل بن زکریا نے سہیل سے ، انھوں نے ابو عبید سے ، انھوں نے عطاء سے اور انھوں نے ابو ہریرہ رضی اللہ عنہ سے روایت کی ، کہا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، آگے ( مذکورہ بالا روایت ) کے مانند روایت کی ۔","",{"u2":"اسماعیل بن زکریا نے سہیل سے، انھوں نے ابو عبید سے، انھوں نے عطاء سے اور انھوں نے ابو ہریرہ رضی اللہ عنہ سے روایت کی، کہا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، آگے (مذکورہ بالا روایت)کے مانند روایت کی۔"}],[1288,"جریر نےعمارہ بن قعقاع سے ، انھوں نے ابوزرعہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب ( آغاز ) نماز کے لیے تکبیر کہتے تو قراءات کرنے سے پہلے کچھ دیر سکوت فرماتے ، میں نے عرض کی : اے اللہ کے رسول ! میرے ماں باپ آپ پر قربان ! دیکھیے یہ جو تکبیر اور قراءت کے درمیان آپ کی خاموشی ہے ( اس کے دوران میں ) آپ کیا کہتے ہیں ؟ آپ نے فرمایا : ’’میں کہتا ہوں : اللہم باعدبینی وبین خطایای کما باعدت بین المشرق والمغرب اللہم نقنی من خطایای کما ینقی الثوب الابیض من الدنس ، اللم اغسلنی من خطایای بالثلج والماء والبرد’’ اے اللہ! میرے اور میرے گناہوں کے درمیان اس طرح دوری ڈال دے جس طرح تونے مشرق اور مغرب کے درمیان دوری ڈالی ہے ۔ اے اللہ ! مجھے میرے گناہوں سے اس طرح پاک صاف کر دے جس طرح سفید کپڑا میل کچیل سے صاف کیا جاتا ہے ۔ اے اللہ ! مجھے میرے گناہوں سے پاک کر دے برف کے ساتھ ، پانی کےساتھ اور اولوں کے ساتھ ۔ ‘‘","",{"u2":"جریر نےعمارہ بن قعقاع سے، انھوں نے ابوزرعہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، انھوں نے کہا: رسو ل اللہ صلی اللہ علیہ وسلم جب (آغاز)نماز کے لیے تکبیر کہتے تو قراءات کرنے سے پہلے کچھ دیر سکوت فرماتے، میں نےعرض کی: اے اللہ کے رسو ل! میرے ماں باپ آپ پر قربان! دیکھیے یہ جو تکبیر اور قراءت کے درمیان آپ کی خاموشی ہے (اس کے دوران میں)آپ کیا کہتے ہیں؟ آپ نے فرمایا:’’میں کہتا ہوں: اللہم باعدبینی وبین خطایای کما باعدت بین المشرق والمغرب اللہم نقنی من خطایای کما ینقی الثوب الابیض من الدنس،اللم اغسلنی من خطایای بالثلج والماء والبرد’’ اے اللہ! میرے اور میرے گناہوں کے درمیان اس طرح دوری ڈال دے جس طرح تونے مشرق اور مغرب کے درمیان دوری ڈالی ہے۔اے اللہ! مجھے میرے گناہوں سے اس طرح پاک صاف کر دے جس طرح سفید کپڑا میل کچیل سے صاف کیا جاتا ہے۔ اے اللہ! مجھے میرے گناہوں سے پاک کر دے برف کے ساتھ،پانی کےساتھ اور اولوں کے ساتھ۔‘‘"}],[1289,"جریر نےعمارہ بن قعقاع سے ، انھوں نے ابوزرعہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم جب ( آغاز ) نماز کے لیے تکبیر کہتے تو قراءات کرنے سے پہلے کچھ دیر سکوت فرماتے ، میں نے عرض کی : اے اللہ کے رسول ! میرے ماں باپ آپ پر قربان ! دیکھیے یہ جو تکبیر اور قراءت کے درمیان آپ کی خاموشی ہے ( اس کے دوران میں ) آپ کیا کہتے ہیں ؟ آپ نے فرمایا : ’’میں کہتا ہوں : اللہم باعدبینی وبین خطایای کما باعدت بین المشرق والمغرب اللہم نقنی من خطایای کما ینقی الثوب الابیض من الدنس ، اللم اغسلنی من خطایای بالثلج والماء والبرد’’ اے اللہ! میرے اور میرے گناہوں کے درمیان اس طرح دوری ڈال دے جس طرح تونے مشرق اور مغرب کے درمیان دوری ڈالی ہے ۔ اے اللہ ! مجھے میرے گناہوں سے اس طرح پاک صاف کر دے جس طرح سفید کپڑا میل کچیل سے صاف کیا جاتا ہے ۔ اے اللہ ! مجھے میرے گناہوں سے پاک کر دے برف کے ساتھ ، پانی کےساتھ اور اولوں کے ساتھ ۔ ‘‘","",{"u2":"ابن فضیل اور عبدالواحد بن یاد دونوں نے، عمارہ بن قعقاع سے، اسی سند کے ساتھ،جریر کی حدیث کی طرح روایت کی"}],[1290,"سیدنا ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب دوسری رکعت سے اٹھتے تو ( الحمد اللہ رب العٰلمین ) سے قراءت کا آغاز کر دیتے ( کچھ دیر ) خاموشی اختیار نہ فرماتے ۔"],[1291,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک آدمی آیا اور صف میں شریک ہوا جبکہ اس کی سانس چڑھی ہوئی تھی ، اس نے کہا : الحمد اللہ حمد کثیر طیبا مبارکا فیہ ’’ تمام حمد اللہ ہی کے لیے ہے ، حمد بہت زیادہ ‘ پاک اور برکت والی حمد ۔ ‘‘ جب رسول اللہ صلی اللہ علیہ وسلم نے نماز پوری کرلی تو آپ نے پوچھا ’’تم میں سے یہ کلمات کہنے والا کون تھا ؟ ‘‘ سب لوگوں نے ہونٹ بند رکھے ۔ آپ نے دوبارہ پوچھا ’’تم میں یہ کلمات کہنے والا کون تھا؟ اس نے کوئی ممنوع بات نہیں کہی ۔ ‘‘ تب ایک شخص نے کہا : میں اس حالت میں آیا کہ میری سانس پھولی ہوئی تھی تو میں نے اس عالم میں یہ کلمات کہے ۔ آپ نے فرمایا : میں نے بارہ فرشتوں کو دیکھا جو ( اس میں ) ایک دوسرے سے سبقت لے جانے کی کوشش کر رہے تھے کہ کون اسے اوپر لے جاتا ہے ۔ ‘‘","",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک آدمی آیا اور صف میں شریک ہوا جبکہ اس کی سانس چڑھی ہوئی تھی، اس نے کہا: الحمد اللہ حمد کثیر طیبا مبارکا فیہ ’’ تمام حمد اللہ ہی کے لیے ہے،حمد بہت زیادہ ‘پاک اور برکت والی حمد۔ ‘‘ جب رسو ل اللہ صلی اللہ علیہ وسلم نےنماز پوری کرلی تو آپ نے پوچھا ’’تم میں سے یہ کلمات کہنے والا کون تھا؟‘‘ سب لوگوں نے ہونٹ بند رکھے۔ آپ نے دوبارہ پوچھا ’’تم میں یہ کلمات کہنے والا کون تھا؟ اس نے کوئی ممنوع بات نہیں کہی۔‘‘ تب ایک شخص نے کہا: میں اس حالت میں آیا کہ میری سانس پھولی ہوئی تھی تو میں نے اس عالم میں یہ کلمات کہے۔ آپ نے فرمایا: میں نے بارہ فرشتوں کو دیکھا جو (اس میں)ایک دوسرے سے سبقت لے جانے کی کوشش کر رہے تھے کہ کون اسے اوپر لے جاتا ہے۔‘‘"}],[1292,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے ، انھون نے کہا : ایک دفعہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہے تھے کہ لوگوں میں سے ایک آدمی نے کہا : اللہ اکبر کبیرا ، والحمد للہ کثیرا ، وسبحان اللہ بکرۃ واصیلا ’’اللہ سب سے بڑا ہے بہت بڑا ، اور تمام تعریف اللہ کے لیے ہے بہت زیادہ اور تسبیح اللہ ہی کے لیے ہے ، صبح و شام ۔ ‘‘ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا : ’’فلاں فلاں کلمہ کہنے والا کون ہے ؟ لوگوں میں سے ایک آدمی نے کہا : اللہ کے رسول ! میں ہوں آپ نے فرمایا ’’مجھے ان پر بہت حیرت ہوئی ، ان کے لیے آسمان کے دروازے کھول دیے گئے ۔ ‘‘ ابن عمر رضی اللہ عنہ نے کہا : میں نے جب سے آپ سے یہ بات سنی ، اس کےبعد سے ان کلمات کو کبھی ترک نہیں کیا ۔","",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے، انھون نے کہا:ایک دفعہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہے تھے کہ لوگوں میں سے ایک آدمی نے کہا: اللہ اکبر کبیرا،والحمد للہ کثیرا، وسبحان اللہ بکرۃ واصیلا ’’اللہ سب سے بڑا ہے بہت بڑا، اور تمام تعریف اللہ کے لیے ہے بہت زیادہ اور تسبیح اللہ ہی کے لیے ہے،صبح و شام۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: ’’فلاں فلاں کلمہ کہنے والا کون ہے؟ لوگوں میں سے ایک آدمی نے کہا: اللہ کےرسول! میں ہوں آپ نے فرمایا ’’مجھے ان پر بہت حیرت ہوئی، ان کے لیے آسمان کے دروازے کھول دیے گئے۔‘‘\nابن عمر رضی اللہ عنہ نے کہا: میں نے جب سے آپ سے یہ بات سنی، اس کےبعد سے ان کلمات کو کبھی ترک نہیں کیا۔"}],[1293,"مختلف سندوں سے سعید بن مسیب اور ابو سلمہ بن عبدالرحمن نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ’’جب نمازکھڑی ہو جائے تو اس کے لیے دوڑتے ہوئے نہ آؤ ، ( بلکہ اس طرح ) چلتے ہوئے آؤ کہ تم پر سکون طاری ہو ۔ ( نماز کا ) جو حصہ پالو اسے پڑھ لو اور جو رہ جائے اسے پورا کر لو ۔ ‘‘"],[1294,"مختلف سندوں سے سعید بن مسیب اور ابو سلمہ بن عبدالرحمن نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ’’جب نمازکھڑی ہو جائے تو اس کے لیے دوڑتے ہوئے نہ آؤ ، ( بلکہ اس طرح ) چلتے ہوئے آؤ کہ تم پر سکون طاری ہو ۔ ( نماز کا ) جو حصہ پالو اسے پڑھ لو اور جو رہ جائے اسے پورا کر لو ۔ ‘‘"],[1295,"مختلف سندوں سے سعید بن مسیب اور ابو سلمہ بن عبدالرحمن نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ’’جب نمازکھڑی ہو جائے تو اس کے لیے دوڑتے ہوئے نہ آؤ ، ( بلکہ اس طرح ) چلتے ہوئے آؤ کہ تم پر سکون طاری ہو ۔ ( نماز کا ) جو حصہ پالو اسے پڑھ لو اور جو رہ جائے اسے پورا کر لو ۔ ‘‘",""],[1296,"(سعید بن مسیب اور ابو سلمہ کے بجائے ) عبدالرحمان بن یعقوب نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب نماز کی تکبیر کہہ دی جائے تو تم اس کےلیے بھاگتے ہوئے مت آؤ ، اس طرح آؤ کہ تم پر سکون ہو ، ( نماز کا ) جتنا حصہ پالو ، پڑھ لو اور جو رہ جائے اسے پورا کر لو کیونکہ جب کوئی شخص نماز کا ارادہ کرکے آتا ہےتو وہ نماز ( ہی ) میں ہوتا ہے ۔ ‘‘","",{"u2":"سعید بن مسیب اور ابو سلمہ کے بجائے) عبدالرحمان بن یعقوب نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب نماز کی تکبیر کہہ دی جائے تو تم اس کےلیے بھاگتے ہوئے مت آؤ، اس طرح آؤ کہ تم پر سکون ہو،(نماز کا)جتنا حصہ پالو، پڑھ لو اور جو رہ جائے اسے پورا کر لو کیونکہ جب کوئی شخص نماز کا ارادہ کرکے آتا ہےتو وہ نماز (ہی)میں ہوتا ہے۔‘‘"}],[1297,"ہمام بن منبہ نے کہا : یہ احادیث ہیں جو ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ( سن کر ) ہمیں سنائیں ، انھوں نے متعدد احادیث ذکر کیں ، ان مین سے یہ بھی تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب نماز کے لیے بلاوا دیا جائے تو اس کے لیے چلتے ہوئے آؤ ، اور تم پر سکون ( طاری ) ہو ، جو ( نماز کا حصہ ) مل جائے ، وہ پڑھ لو اور جو رہ جائے اسے مکمل کر لو ۔ ‘‘","",{"u2":"ہمام بن منبہ نے کہا: یہ احادیث ہیں جو ابوہریرہ رضی اللہ عنہ نے رسو ل اللہ صلی اللہ علیہ وسلم سے (سن کر)ہمیں سنائیں، انھوں نے متعدد احادیث ذکر کیں، ان مین سے یہ بھی تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب نماز کے لیے بلاوا دیا جائے تو اس کے لیے چلتے ہوئے آؤ، اور تم پر سکون(طاری)ہو، جو (نماز کا حصہ)مل جائے،وہ پڑھ لو اور جو رہ جائے اسے مکمل کر لو۔‘‘"}],[1298,"محمد بن سیرین نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب نماز کے لیے اقامت کہہ دی جائے تو تم میں سے کوئی شخص اس کی طرف بھاگ کر نہ آئے بلکہ اس طرح چل کر آئے کہ اس پر سکون وقار طار ی ہو ، جتنی ( نماز ) پا لو ، پڑھ لو اور جو تمھارے ( پہنچنے ) سے پہلے گزر چکی اسے پورکر لو ۔ ‘‘","",{"u2":"محمد بن سیرین نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب نماز کے لیے اقامت کہہ دی جائے تو تم میں سے کوئی شخص اس کی طرف بھاگ کر نہ آئے بلکہ اس طرح چل کر آئے کہ اس پر سکون وقار طار ی ہو،جتنی (نماز)پا لو، پڑھ لو اور جو تمھارے (پہنچنے)سے پہلے گزر چکی اسے پورکر لو۔‘‘"}],[1299,"معاویہ بن سلام نے یحییٰ بن ابی کثیر سے روایت کی کہا : عبداللہ بن ابی قتادہ رضی اللہ عنہ نے مجھے خبر دی کہ ان کے والد نے انھیں بتایا ، کہا : ہم ( ایک بار ) جب رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہے تھے تو آپ نے ( جلدی چلنے ، دوڑ کر پہنچنے کی ) ملی جلی آواز یں سنیں ، آپ نے ( نماز کے بعد ) پوچھا : ’’تمھیں کیا ہوا ( تھا ؟ ) ‘‘ لوگوں نے جواب دیا ہم نے نماز کے لے جلید کی ۔ آپ نے فرمایا : ’’ایسے نہ کیا کرو ، جب تم نماز کے لیے آؤ تو سکون و اطمینان محلوظ رکھو ، ( نماز کا حصہ ) جو تمھیں مل جائے ، پڑھ لو ارو جو گز ر جائے اسے پورا کر لو ۔ ‘‘","",{"u2":"معاویہ بن سلام نے یحییٰ بن ابی کثیر سے روایت کی کہا: عبداللہ بن ابی قتادہ رضی اللہ عنہ نے مجھے خبر دی کہ ان کے والد نے انھیں بتایا، کہا: ہم (ایک بار)جب رسو ل اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہے تھے تو آپ نے (جلدی چلنے،دوڑ کر پہنچنے کی)ملی جلی آواز یں سنیں، آپ نے (نماز کے بعد)پوچھا: ’’تمھیں کیا ہوا (تھا؟)‘‘ لوگوں نے جواب دیا ہم نے نماز کے لے جلید کی۔ آپ نے فرمایا:’’ایسے نہ کیا کرو،جب تم نماز کے لیے آؤ تو سکون و اطمینان محلوظ رکھو، (نماز کاحصہ)جو تمھیں مل جائے، پڑھ لو ارو جو گز ر جائے اسے پورا کر لو۔‘‘"}],[1300,"(معاویہ کے بجائے ) شبیان نے ( یحییٰ سے ) اسی سند کے ساتھ یہی روایت بیان کی ۔","",{"u2":"معاویہ کے بجائے)شبیان نے (یحییٰ سے) اسی سند کے ساتھ یہی روایت بیان کی۔"}],[1301,"محمد بن حاتم اور عبیداللہ بن سعید نےکہا : ہمیں یحییٰ بن سعید نے حجاج صواف سے حدیث سنائی ، انھوں نے کہا : ہمیں یحییٰ بن ابی کثیر نے ابو سلمہ اور عبداللہ بن ابی قتادہ سے حدیث سنائی ، انھوں سیدنا ابو قتادہ رضی اللہ عنہ سے روایت کی ، انھون نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : جب نماز کے لیے اقامت کہی جائے تو اس وقت تک کھڑے نہ ہوا کرو جب تک مجھے نہ دیکھ لو ۔ ‘‘ اور ابن حاتم نے کہا : ’’جب اقامت کہی جائے یا ( جماعت کے لیے ) پکارا جائے","",{"u2":"محمد بن حاتم اور عبیداللہ بن سعید نےکہا:ہمیں یحییٰ بن سعید نےحجاج صواف سے حدیث سنائی، انھوں نے کہا: ہمیں یحییٰ بن ابی کثیر نے ابو سلمہ اور عبداللہ بن ابی قتادہ سے حدیث سنائی، انھوں سیدنا ابو قتادہ رضی اللہ عنہ سے روایت کی،انھون نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب نماز کے لیے اقامت کہی جائے تو اس وقت تک کھڑے نہ ہوا کرو جب تک مجھے نہ دیکھ لو۔‘‘\nاور ابن حاتم نے کہا:’’جب اقامت کہی جائے یا (جماعت کے لیے)پکارا جائے"}],[1302,"محمد بن حاتم اور عبیداللہ بن سعید نےکہا : ہمیں یحییٰ بن سعید نے حجاج صواف سے حدیث سنائی ، انھوں نے کہا : ہمیں یحییٰ بن ابی کثیر نے ابو سلمہ اور عبداللہ بن ابی قتادہ سے حدیث سنائی ، انھوں سیدنا ابو قتادہ رضی اللہ عنہ سے روایت کی ، انھون نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : جب نماز کے لیے اقامت کہی جائے تو اس وقت تک کھڑے نہ ہوا کرو جب تک مجھے نہ دیکھ لو ۔ ‘‘ اور ابن حاتم نے کہا : ’’جب اقامت کہی جائے یا ( جماعت کے لیے ) پکارا جائے","",{"u2":"ابو بکر بن ابی شیبہ نے کہا: ہمیں سفیان بن عیینہ نے معمر سے حدیث سنائی، ابو بکر (بن ابی شبیہ نے مزید)کہا: ہمیں ابن علیہ نے حجاج بن ابی عثمان سے حدیث سنائی، نیز اسحاق بن ابراہیم نے کہا:ہمیں عیسیٰ بن یونس اور عبدالزراق نے معمر سے خبر دی۔ اسحاق نے (مزید)کہا: ہمیں ولید بن مسلم نے شیبان سے خبر دی، ان سب (معمر،حجاج بن ابی عثمان اور شبیان)نے یحییٰ بن ابی کثیر سے روایت کی، انھوں نے عبداللہ بن ابی قتادہ سے، انھوں نے اپنے والد سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔\nاسحاق نے معمر اور شیبان سے جو حدیث روایت کی اس مین یہ اضافہ کیا ہے۔’’ یہاں تک کہ تم مجھے دیکھ لو کہ میں باہر نکل آیا ہوں۔‘‘"}],[1303,"یونس نے ابن شہاب ( زہری ) سے خبر دی ، انھوں نے کہا : مجھے ابو سلمہ عبدالرحمن بن عوف نے خبر دی ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا ، وہ کہتے تھے ، ( رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ) اقامت کہی گئی ، ہم اپنی طرف رسول اللہ کے آنے سے پہلے ہی کھڑے ہو گئے اور اپنے مصلے پر کھڑے ہو گئے آپ نے اللہ اکبر نہیں کہا تھا کہ آپ کو ( کچھ ) یاد آگیا ، اس پر آپ واپس پلٹ گئے اور ہمیں فرمایا : ’’اپنی جگہ پر رہو ۔ ‘‘ ہم آپ کے انتظار میں کھڑے رہے یہاں تک کہ آب تشریف لے آئے ، آب غسل کیے ہوئے تھے اور آب کے سر سے پانی کے قطرے ٹپک رہے تھے ، پھر آپ نے اللہ اکبر کہا اور ہمیں نماز پڑھائی ۔","",{"u2":"یونس نے ابن شہاب (زہری)سے خبر دی، انھوں نے کہا: مجھے ابو سلمہ عبدالرحمن بن عوف نے خبر دی، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے سنا، وہ کہتے تھے، (رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں)اقامت کہی گئی،ہم اپنی طرف رسول اللہ کے آنے سے پہلے ہی کھڑے ہو گئے اور اپنے مصلے پر کھڑے ہو گئے آپ نے اللہ اکبر نہیں کہا تھا کہ آپ کو (کچھ)یاد آگیا، اس پر آپ واپس پلٹ گئے اور ہمیں فرمایا: ’’اپنی جگہ پر رہو۔‘‘ ہم آپ کے انتظار میں کھڑے رہے یہاں تک کہ آب تشریف لے آئے، آب غسل کیے ہوئے تھے اور آب کے سر سے پانی کے قطرے ٹپک رہے تھے، پھر آپ نے اللہ اکبر کہا اور ہمیں نماز پڑھائی۔"}],[1304,"زہیر بن حرب نے بیان کیا کہ ہمیں ولید بن مسلم نے حدیث سنائی ، ( کہا ) : ابو عمرو ، یعنی اوزاعی نے حدیث سنائی ، کہا : ہمیں زہری نے ابو سلمہ سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہوئے حدیث سنائی کہا : نماز کی اقامت کہہ دی گئی ، لوگوں نے اپنی صفیں باندھ لیں اور رسول اللہ صلی اللہ علیہ وسلم تشریف لا کر اپنی جگہ پر کھڑے ہو گئے پھر آپ نے لوگوں کو ہاتھ کے اشارے سے فرمایا : ’’اپنی جگہ پر رہو ۔ ‘‘ اور خود ( مسجد سے ) باہر نکل گئے ، پھر ( آئے تو ) آپ غسل فرما چکے تھے اور آپ کے سر سے پانی ٹپک رہا تھا ، پھر آپ نے انھیں نماز پڑھائی ۔","",{"u2":"زہیر بن حرب نے بیان کیا کہ ہمیں ولید بن مسلم نے حدیث سنائی،(کہا): ابو عمرو، یعنی اوزاعی نے حدیث سنائی، کہا: ہمیں زہری نے ابو سلمہ سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہوئے حدیث سنائی کہا: نماز کی اقامت کہہ دی گئی، لوگوں نے اپنی صفیں باندھ لیں اور رسول اللہ صلی اللہ علیہ وسلم تشریف لا کر اپنی جگہ پر کھڑے ہو گئے پھر آپ نے لوگوں کو ہاتھ کے اشارے سے فرمایا: ’’اپنی جگہ پر رہو۔‘‘ اور خود (مسجد سے)باہر نکل گئے، پھر (آئے تو)آپ غسل فرما چکے تھے اور آپ کے سر سے پانی ٹپک رہا تھا، پھر آپ نے انھیں نماز پڑھائی۔"}],[1305,"ابراہیم بن موسیٰ نے مجھے حدیث بیان کی ، کہا ہمیں ولید بن مسلم نے باقی ماندہ اسی سند کے ساتھ خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کے لیے اقامت کہی جاتی تو اس سے پہلے کہ نبی اکرم صلی اللہ علیہ وسلم ( اپنی جگہ پر ) کھڑے ہوں لوگ صفوں میں اپنی اپنی جگہ لے لیتے ۔","",{"u2":"ابراہیم بن موسیٰ نےمجھے حدیث بیان کی، کہا ہمیں ولید بن مسلم نےباقی ماندہ اسی سند کے ساتھ خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم کے لیے اقامت کہی جاتی تو اس سے پہلے کہ نبی اکرم صلی اللہ علیہ وسلم (اپنی جگہ پر)کھڑے ہوں لوگ صفوں میں اپنی اپنی جگہ لے لیتے۔"}],[1306,"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے ، انھوں نے فرمایا ، جب سورج ڈھل جاتا تو بلال رضی اللہ عنہ ظہر کی اذان کہتے اور رسول اللہ صلی اللہ علیہ وسلم کے نکلنے تک تکبیر نہ کہتے ۔ جب آپ حجرے سے نکلتے تو آپ کو دیکھ کر اقامت کہتے ۔","",{"u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا، جب سورج ڈھل جاتا تو بلال رضی اللہ عنہ ظہر کی اذان کہتے اور رسول اللہ صلی اللہ علیہ وسلم کے نکلنے تک تکبیر نہ کہتے۔ جب آپ حجرے سے نکلتے تو آپ کو دیکھ کر اقامت کہتے۔"}],[1307,"یحییٰ بن یحییٰ نے کہا : میں نے امام مالک کے سامنے ابن شہاب زہری سے روایت کردہ حدیث پڑھی انھوں نے ابو سلمہ بن عبدالرحمن سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے نماز کی ایک رکعت پالی ، یقینا اس نے نماز پالی ۔ ‘‘","",{"u2":"یحییٰ بن یحییٰ نے کہا: میں نے امام مالک کے سامنے ابن شہاب زہری سے روایت کردہ حدیث پڑھی انھوں نے ابو سلمہ بن عبدالرحمن سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’ جس نے نماز کی ایک رکعت پالی، یقینا اس نے نماز پالی۔‘‘"}],[1308,"(امام مالک کے بجائے ) یونس نے ابن شہاب زہری سے ، انھوں نے ابو سلمہ بن عبدالرحمن سے اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے امام کے ساتھ نماز کی ایک رکعت پالی ، اس نے نماز پالی ۔ ‘‘","",{"u2":"امام مالک کے بجائے)یونس نے ابن شہاب زہری سے، انھوں نے ابو سلمہ بن عبدالرحمن سےاور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جس نے امام کے ساتھ نماز کی ایک رکعت پالی، اس نے نماز پالی۔‘‘"}],[1309,"سفیان بن عیینہ ، معمر ، اوزاعی ، یونس اور عبید اللہ سب نے زہری سے روایت کی ، انھوں نے ابو سلمہ بن عبدالرحمن سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نبی صلی اللہ علیہ وسلم سے یحییٰ کی امام مالک سے مذکورہ بالا روایت کی طرح حدیث بیان کی اور ان میں سے کسی کی حدیث میں مع الامام ( امام کے ساتھ ) کے الفاظ نہیں ہیں ۔ اور عبید اللہ کی حدیث میں ہے : ’’تو یقینا اس نے مکمل نماز پالی ۔ ‘‘","",{"u2":"سفیان بن عیینہ،معمر، اوزاعی، یونس اور عبید اللہ سب نے زہری سے روایت کی، انھوں نے ابو سلمہ بن عبدالرحمن سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نبی صلی اللہ علیہ وسلم سے یحییٰ کی امام مالک سے مذکورہ بالا روایت کی طرح حدیث بیان کی اور ان میں سے کسی کی حدیث میں مع الامام (امام کے ساتھ)کے الفاظ نہیں ہیں۔ اور عبید اللہ کی حدیث میں ہے: ’’تو یقینا اس نے مکمل نماز پالی۔‘‘"}],[1310,"امام مالک نے زید بن اسلم سے روایت کی ، انھیں عطاء بن یسار ، بسربن سعید اور اعرج نے حدیث بیان کی ، ان سب نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے سورج نکلنے سے پہلے صبح کی ایک رکعت پالی تو یقینا اس نے صبح ( کی نماز ) پالی اورجس نے سورج کے غروب ہونے پہلے عصر کی ایک رکعت پالی تو یقینا اس نے عصر ( کی نماز ) پالی ۔ ‘‘","",{"u2":") امام مالک نےزید بن اسلم سے روایت کی، انھیں عطاء بن یسار، بسربن سعید اور اعرج نے حدیث بیان کی، ان سب نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جس نے سورج نکلنے سے پہلے صبح کی ایک رکعت پالی تو یقینا اس نے صبح (کی نماز)پالی اورجس نے سورج کے غروب ہونے پہلے عصر کی ایک رکعت پالی تو یقینا اس نے عصر (کی نماز)پالی۔‘‘"}],[1311,"معمر نے زہری سے ، انھوں نے ابو سلمہ سے ، اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اسی طرح روایت کی جس طرح امام مالک نے زید بن اسلم سے روایت کی ۔"],[1312,"معمر نے زہری سے ، انھوں نے ابو سلمہ سے ، اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اسی طرح روایت کی جس طرح امام مالک نے زید بن اسلم سے روایت کی ۔",""],[1313,"سیدہ عائشہ رضی اللہ عنہ سے روایت ہے ، انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے سورج کے غروب ہونے سے پہلے عصر کی نماز کا ایک سجدہ پالیا سورج کے نکلنے سے پہلے صبح کی نماز کا تو یقینا اس نے اس نماز کو پالیا ۔ ‘‘ ( ان شہاب نے کہا : ) سجدے سے مراد رکعت ہی ہے ۔","",{"u2":"معمر نے زہری سے، انھوں نے ابو سلمہ سے، اور انھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اسی طرح روایت کی جس طرح امام مالک نے زید بن اسلم سے روایت کی۔"}],[1314,"عبداللہ بن مبارک نے معمر سے ، انھوں نے ابن طاوس سے ، انھوں نے اپنے والد سے ، انھوں نے سیدنا ( عبداللہ ) بن عباس رضی اللہ عنہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے سورج کے غروب ہونے سے پہلے عصر کی نماز میں سے ایک رکعت پالی تو یقینا اس نے ( نماز ) پالی اور جس نے سورج نکلنے سے پہلے فجر کی ایک رکعت پالی تو یقینا اس نے ( نماز ) پالی ۔ ‘‘","",{"u2":"عبداللہ بن مبارک نے معمر سے، انھوں نے ابن طاوس سے، انھوں نے اپنے والد سے، انھوں نے حضرت (عبداللہ)بن عباس رضی اللہ عنہ سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ جس نے سورج کے غروب ہونے سے پہلے عصر کی نماز میں سے ایک رکعت پالی تو یقینا اس نے (نماز)پالی اور جس نے سورج نکلنے سے پہلے فجر کی ایک رکعت پالی تو یقینا اس نے (نماز)پالی۔‘‘"}],[1315,"معتمر نے کہا : میں نے معمر سے سنا ۔ ۔ ۔ ۔ ۔ ۔ آگے اسی سند سے ( روایت کی ۔)","",{"u2":"معتمر نے کہا: میں نے معمر سے سنا۔۔۔۔۔۔آگے اسی سند سے (روایت کی۔)"}],[1316,"لیث نے ابن شہاب سے روایت کی کہ ایک دن عمر بن عبدالعزیز نےعصر کی نماز میں کچھ تاخیر کردی تو عروہ نے ان سے کہا : بات یوں ہے کہ جبریل رضی اللہ عنہ نازل ہوئے اور امام بن کر رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھائی ۔ تو عمر رضی اللہ عنہ نے ان سے کہا : اے عروہ ! جان لیں ( سمجھ لیں ) آپ کیا کہہ رہے ہیں ! انھوں نے کہا : میں نے بشیر بن ابی مسعود سے سنا ، وہ کہتے تھے : میں نے ابو مسعود رضی اللہ عنہ سے سنا ، انھوں نے کہا ، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ نے فرما رہے تھے : ’’جبرئیل اترے اور انھوں نے ( نماز میں ) میری امامت کی ، میں نے ان کے ساتھ نماز پڑھی ، پھر میں نے ان کے ساتھ نماز پڑھی ، پھر ان کے ساتھ نماز پڑھی ، پھر ان کے ساتھ نماز پڑھی ، پھر ان کے ساتھ نماز پڑھی ۔ ‘‘ وہ اپنی انگلیوں سے پانچ نمازیں شمار کرتے تھے ۔","",{"u2":") لیث نے ابن شہاب سے روایت کی کہ ایک دن عمر بن عبدالعزیز نےعصر کی نمازمیں کچھ تاخیر کردی تو عروہ نے ان سے کہا: بات یوں ہے کہ جبریل علیہ السلام نازل ہوئے اور امام بن کر رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھائی۔ تو عمر رضی اللہ عنہ نے ان سے کہا: اے عروہ! جان لیں (سمجھ لیں)آپ کیا کہہ رہے ہیں! انھوں نے کہا: میں نے بشیر بن ابی مسعود سے سنا، وہ کہتے تھے: میں نے ابو مسعود رضی اللہ عنہ سے سنا، انھوں نے کہا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ نے فرما رہے تھے:’’جبریل علیہ السلام اترے اور انھوں نے (نمازمیں)میری امامت کی، میں نے ان کے ساتھ نماز پڑھی، پھر میں نے ان کے ساتھ نماز پڑھی، پھر ان کے ساتھ نماز پڑھی،پھر ان کے ساتھ نماز پڑھی، پھر ان کے ساتھ نماز پڑھی۔‘‘ وہ اپنی انگلیوں سے پانچ نمازیں شمار کرتے تھے۔"}],[1317,"امام مالک نے ابن شہاب زہری سے روایت کی کہ ایک دن عمر بن عبدالعزیز نے نماز میں تاخیر کر دی تو عروہ بن زبیر ان کے پاس آئے اور انھیں بتایا کہ مغیر ہ بن شعبہ رضی اللہ عنہ نے ایک دن نماز دیر سے پڑھی اس وقت وہ کوفہ میں تھے ابو مسعود انصاری رحمۃ اللہ علیہ ان کے پاس آئے اور کہا : مغیرہ !یہ کیا ہے ؟ کیا آپ کو پتہ نہیں کہ جبریل علیہ السلام اترے تھے ، انھوں نے نماز پڑھائی تو رسول اللہ صلی اللہ علیہ وسلم نے ( ان کے ساتھ ) نماز پڑھی ، پھر انھوں نے نماز پڑھی تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھی ، پھر انوں نے نماز پڑھی اور رسول اللہ صلی اللہ علیہ وسلم نے ( ان کے ساتھ ) نماز پڑھی ، پھر انھوں نے نماز پڑھی تو رسول اللہ صلی اللہ علیہ وسلم نے ( ان کے ساتھ ) نماز پڑھی ، پھر ( جبرئیل نے ) کہا : مجھے اس کا حکم دیا گیا ہے ۔ تو عمر نے عروہ سے کہا : عروہ ! دیکھ لو ، کیا کہہ رہے ہو ؟ کیا جبرئیل نے خود ( آکر ) رسول ) اللہ صلی اللہ علیہ وسلم کے لیے ( ہر ) نماز کا وقت متعین کیا تھا ؟ تو عروہ نے کہا بشر بن ابی مسعود اپنے والد سے ایسے ہی بیان کرتے تھے ۔","",{"u2":"امام مالک نے ابن شہاب زہری سے روایت کی کہ ایک دن عمر بن عبدالعزیز نے نماز میں تاخیر کر دی تو عروہ بن زبیر ان کے پاس آئے اور انھیں بتایا کہ مغیر ہ بن شعبہ رضی اللہ عنہ نے ایک دن نماز دیر سے پڑھی اس وقت وہ کوفہ میں تھے ابو مسعود انصاری رحمۃ اللہ علیہ ان کے پاس آئے اور کہا: مغیرہ!یہ کیا ہے؟ کیا آپ کو پتہ نہیں کہ جبریل علیہ السلام اترے تھے، انھوں نے نماز پڑھائی تو رسول اللہ صلی اللہ علیہ وسلم نے (ان کے ساتھ)نماز پڑھی، پھر انھوں نے نماز پڑھی تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھی، پھر انوں نے نماز پڑھی اور رسول اللہ صلی اللہ علیہ وسلم نے (ان کے ساتھ)نماز پڑھی، پھر انھوں نے نماز پڑھی تو رسو ل اللہ صلی اللہ علیہ وسلم نے (ان کے ساتھ)نماز پڑھی، پھر (جبریل علیہ السلام نے)کہا: مجھے اس کا حکم دیا گیا ہے۔ تو عمر نے عروہ سے کہا: عروہ! دیکھ لو، کیا کہہ رہے ہو؟ کیا جبریل علیہ السلام نے خود (آکر)رسول)اللہ صلی اللہ علیہ وسلم کے لیے (ہر)نماز کا وقت متعین کیا تھا؟ تو عروہ نے کہا بشر بن ابی مسعود اپنے والد سے ایسے ہی بیان کرتے تھے۔"}],[1318,"ابوبکر بن ابی شبیہ اور عمرو ناقد نے حدیث سنائی ، عمرو نے کہا : سفیان نے ہمیں زہری سے حدیث سنائی ، انھوں نے عروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تھے اور سورج میرے حجرے میں چمک رہا ہوتا تھا ، ابھی ( صحن کے مشرق حصے میں ) سایہ نہ پھیلاہوتا تھا ۔ ابو بکر نے ( معنی کے وضاحت کرتے ہوئے ) کہا : ابھی ( مشرق کی طرف ) سایہ ظاہر نہ ہوا ہوتا تھا ۔","",{"u2":") ابوبکر بن ابی شبیہ اور عمرو ناقد نے حدیث سنائی،عمرو نے کہا: سفیان نے ہمیں زہری سے حدیث سنائی، انھوں نے عروہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تھے اور سورج میرےحجرے میں چمک رہا ہوتا تھا، ابھی (صحن کے مشرق حصے میں)سایہ نہ پھیلاہوتا تھا۔\nابو بکر نے (معنی کے وضاحت کرتے ہوئے)کہا: ابھی (مشرق کی طرف)سایہ ظاہر نہ ہوا ہوتا تھا۔"}],[1319,"یونس ابن شہاب سے روایت کی ، کہا مجھے عروہ بن زبیر نے بتایا کہ مجھے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز اس وقت پڑھتے تھے جبکہ دھوپ ان کےحجرے میں ہوتی ( مشرق کی طرف پھیلتا ) سایہ ان کے حجرے میں نہ پھیلا ہوتا ۔","",{"u2":"یونس ابن شہاب سے روایت کی، کہا مجھے عروہ بن زبیر نے بتایا کہ مجھے نبی اکرم صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ نے خبر دی کہ رسو ل اللہ صلی اللہ علیہ وسلم عصر کی نماز اس وقت پڑھتے تھے جبکہ دھوپ ان کےحجرے میں ہوتی (مشرق کی طرف پھیلتا)سایہ ان کے حجرے میں نہ پھیلا ہوتا۔"}],[1320,"ہشام نے اپنے والد عروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے اور دھوپ میرے حجرے میں پڑ رہی ہوتی تھی","",{"u2":"ہشام نے اپنے والد عروہ سے اور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ رسو ل اللہ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے اور دھوپ میرے حجرے میں پڑ رہی ہوتی تھی"}],[1321,"معاذ بن ہشام نے ہمیں اپنے والد سے حدیث بیان کی انھوں نے قتادہ سے ، انھوں نے ابو ایوب سے اور انھوں نے سیدنا عبداللہ بن عمرو رضی اللہ تعالیٰ عنہا سےروایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا : ’’جب تم فجر کی نماز پڑھو تو سورج کا پہلا کنارہ نمودار ہونے تک اس کا وقت ہے ، پھر جب تم ظہر پڑھو تو عصر ہونے تک اس کا وقت ہے اور جب تم عصر پڑھو تو سورج کے زرد ہونے تک اس کا وقت ہے اور جب تم مغرب پڑھو تو شفق ( سرخی ) کے ختم ہونے تک اس کا وقت ہے اور جب تم عشاء پڑھو تو آدھی رات ہونے تک اس کا وقت ہے ۔ ‘‘","",{"u2":"معاذ بن ہشام نے ہمیں اپنے والد سے حدیث بیان کی انھوں نے قتادہ سے، انھوں نے ابو ایوب سے اور انھوں نے حضرت عبداللہ بن عمرو رضی اللہ تعالیٰ عنہا سےروایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:’’جب تم فجر کی نماز پڑھو تو سورج کاپہلا کنارہ نمودار ہونے تک اس کا وقت ہے، پھر جب تم ظہر پڑھو تو عصر ہونے تک اس کا وقت ہے اور جب تم عصر پڑھو تو سورج کے زرد ہونے تک اس کا وقت ہے اور جب تم مغرب پڑھو تو شفق (سرخی)کے ختم ہونے تک اس کا وقت ہے اور جب تم عشاء پڑھو تو آدھی رات ہونے تک اس کا وقت ہے۔‘‘"}],[1322,"معاذ عنبری نے کہا : ہمیں شعب نے قتادہ سے ، انھوں نے ابو ایوب سے حدیث سنائی ۔ ابو ایوب کا نام یحییٰ بن مالک ازدی ہے ۔ ان کو مراغی بھی کہا جاتا ہے اور مراغ قبیلہ ازدہی کی ایک شاخ ہے ۔ انھوں نے سیدنا عبداللہ بن عمرو رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ظہر کا وقت تب تک ہےجب تک عصر کا وقت شروع نہ ہو ، اور عصر کا وقت ہے جب تک سورج زرد نہ ہو ، اور مغرب کا وقت ہے جب تک شفق غروب نہ ہو ، اور عشاء کا وقت آدھی رات تک ہے اور فجر کا وقت ہے جب تک سورج طلوع نہ ہو ۔ ‘‘","",{"u2":"معاذ عنبری نے کہا:ہمیں شعب نے قتادہ سے، انھوں نے ابو ایوب سے حدیث سنائی۔ ابو ایوب کا نام یحییٰ بن مالک ازدی ہے۔ ان کو مراغی بھی کہا جاتا ہے اور مراغ قبیلہ ازدہی کی ایک شاخ ہے۔ انھوں نے حضرت عبداللہ بن عمرو رضی اللہ تعالیٰ عنہا سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ظہر کا وقت تب تک ہےجب تک عصر کا وقت شروع نہ ہو، اور عصر کا وقت ہے جب تک سورج زرد نہ ہو، اور مغرب کا وقت ہے جب تک شفق غروب نہ ہو، اور عشاء کا وقت آدھی رات تک ہے اور فجر کا وقت ہے جب تک سورج طلوع نہ ہو۔‘‘"}],[1323,"ابو عامر عقدی اور یحییٰ بن ابی بکیر نے شعب سے اسی سند کے ساتھی یہی حدیث بیان کی ۔ ان دونوں کی روایت میں ، شعبہ نے کہا : انھوں ( قتادہ ) نے ایک بار اس حدیث کو مرفوع بیان کیا اور دوبار مرفوع بیان نہیں کیا ۔ ( مرفوع وہ ہے جس کی سند رسول اللہ صلی اللہ علیہ وسلم تک پہنچے ۔)","",{"u2":"ابو عامر عقدی اور یحییٰ بن ابی بکیر نے شعب سے اسی سند کے ساتھی یہی حدیث بیان کی۔ ان دونوں کی روایت میں،شعبہ نے کہا: انھوں (قتادہ)نے ایک بار اس حدیث کو مرفوع بیان کیا اور دوبار مرفوع بیان نہیں کیا۔\n(مرفوع وہ ہے جس کی سند رسو ل اللہ صلی اللہ علیہ وسلم تک پہنچے۔)"}],[1324,"ہمام نے ہمیں حدیث بیان کی ( کہا ) : ہمیں قتادہ نے اوب ایوب سے حدیث سنائی ، انھوں نے سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ ظہر کا وقت ( شروع ہوتا ہے ) جب سورج ڈھل جائے اور آدمی کا سایہ اس کے قد کے برابر ہو ( جانے تک ) ، جب تک عصر کا وقت نہیں ہو جاتا ( رہتا ہے ) اور عصر کا وقت ( ہے ) جب تک سورج زرد نہ ہو جائے اور مغر بکا وقت ( ہے ) جب تک سرغی غائب نے ہو جائے اور عشاء کی نماز کا وقت رات کے پہلے نصف تک ہے اور صبح کی نماز کا وقت طلوع فجر سے اس وقت تک ( ہے ) جب تک سورج طلوع نہیں ہوتا ، جب سورج طلوع ہو نے لگے تو نماز سے رک جاؤ کیونکہ وہ شیطان کے دو سینگوں کے درمیان نکلتا ہے ۔ ‘‘","",{"u2":"ہمام نے ہمیں حدیث بیان کی (کہا): ہمیں قتادہ نے اوب ایوب سے حدیث سنائی، انھوں نے سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ ظہر کا وقت (شروع ہوتا ہے)جب سورج ڈھل جائے اور آدمی کا سایہ اس کے قد کے برابر ہو (جانے تک)،جب تک عصر کا وقت نہیں ہو جاتا (رہتا ہے) اور عصر کا وقت (ہے)جب تک سورج زرد نہ ہو جائے اور مغر بکا وقت (ہے)جب تک سرغی غائب نے ہو جائے اور عشاء کی نماز کا وقت رات کے پہلے نصف تک ہے اور صبح کی نماز کا وقت طلوع فجر سے اس وقت تک (ہے)جب تک سورج طلوع نہیں ہوتا،جب سورج طلوع ہو نے لگے تو نماز سے رک جاؤ کیونکہ وہ شیطان کے دو سینگوں کے درمیان نکلتا ہے۔‘‘"}],[1325,"حجاج نے جو حجاج اسلمی کے بیٹے ہیں ، قتادہ سے ، انھوں نے ابو ایوب سے اور انھوں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت کی ، انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم سے نمازوں کے اوقات کے بارے میں پوچھا گیا تو آپ نے فرمایا : فجر کی نماز کا وقت اس وقت تک ہےجب تک سورج کا پہلا کنارہ نہ نکلے ، اور ظہر کا وقت ہے جب سورج آسمان کی درمیان سے مغرب کی طرف ڈھل جائے یہاں تک کہ عصر کا وقت ہو جائے اور عصر کی نماز کا وقت ہے جب تک سورج زرد نہ ہو جائے اور اس کا ( غروب ہونے والا ) پہلا کنارہ ڈوبنے لگے ، اور مغرب کی نماز کا وقت تب ہے جب سورج غروب ہو جائےجو سرخی غائب ہونے تک رہتا ہے اور عشاء کی نماز کا وقت آدھی رات تک ہے ۔ ‘‘","",{"u2":"حجاج نے جو حجاج اسلمی کے بیٹے ہیں، قتادہ سے، انھوں نے ابو ایوب سے اور انھوں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت کی، انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم سے نمازوںکے اوقات کے بارے میں پوچھا گیا تو آپ نے فرمایا: فجر کی نماز کا وقت اس وقت تک ہےجب تک سورج کا پہلا کنارہ نہ نکلے، اور ظہر کا وقت ہے جب سورج آسمان کی درمیان سے مغرب کی طرف ڈھل جائے یہاں تک کہ عصر کا وقت ہو جائے اور عصر کی نماز کا وقت ہے جب تک سورج زرد نہ ہو جائے اور اس کا (غروب ہونے والا)پہلا کنارہ ڈوبنے لگے، اور مغرب کی نماز کا وقت تب ہے جب سورج غروب ہو جائےجو سرخی غائب ہونے تک رہتا ہے اور عشاء کی نماز کا وقت آدھی رات تک ہے۔‘‘"}],[1326,"عبداللہ بن یحییٰ بن ابی کثیر نے کہا : میں نے اپنے والد کو یہ کہتے سنا : علم جسم کی راحت سے حاصل نہیں ہوسکتا ۔","",{"u2":"عبداللہ بن یحییٰ بن ابی کثیر نے کہا: میں نے اپنے والد کو یہ کہتے سنا:علم جسم کی راحت سے حاصل نہیں ہوسکتا۔"}],[1327,"سیدنا بریدہ ؓ نے کہا : کہ نبی صلی اللہ علیہ وسلم سے ایک شخص نے نماز کا وقت پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا : ” تم دو روز ہمارے ساتھ نماز پڑھو “ ۔ پھر جب آفتاب ڈھل گیا سیدنا بلال ؓ کو حکم دیا ، انہوں نے اذان دی ، پھر حکم دیا ، انہوں نے اقامت کہی ، پھر عصر پڑھی اور سورج بلند تھا سفید صاف پھر حکم دیا تو اقامت کہی مغرب کی جب آفتاب ڈوب گیا ، پھر حکم دیا تو اقامت کہی عشاء کی جب شفق ڈوب گئی ، پھر حکم دیا اقامت کہی فجر کی جب فجر طلوع ہوئی ، پھر جب دوسرا دن ہوا ، حکم کیا تو ظہر ٹھنڈے وقت پڑھی اور بہت ٹھنڈے وقت پڑھی اور عصر پڑھی اور سورج بلند تھا مگر روز اول سے ذرا تاخیر کی اور مغرب پڑھی شفق ڈوبنے سے پہلے اور عشاء پڑھائی تہائی رات کے بعد اور فجر پڑھی جب خوب روشنی ہو گئی ۔ پھر فرمایا : ” وہ سائل کہاں ہے جو نماز کا وقت پوچھتا تھا ؟ “ ، اس نے کہا : اے اللہ کے رسول ! میں حاضر ہوں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : ” یہ جو دونوں وقت تم نے دیکھا ان کے بیچ میں تمہاری نماز کا وقت ہے ۔ “","",{"u2":"سفیان نے ہمیں علقمہ بن مرثد سے حدیث بیان کی انھوں نے سلیمان بن برید سے، انھوں نے اپنے والد (بریدہ بن حصیب اسلمی رضی اللہ عنہ) سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ ایک آدمی نے آپ صلی اللہ علیہ وسلم سے نما کے وقت کے بارے میں سوال کیا تو آپ نے اس سے فرمایا:’’ ہمارے ساتھ یہ دو دن نماز پڑھو۔ ‘‘ جب سورج ڈھلا تو آپ نے بلا رضی اللہ عنہ کو اذان کہنے کا حکم دیا، انھوں نے اذان کہی، پھر آپ نے انھیں حکم دیا تو انھوں نے ظہر کی کے تکبیر کہی، پھر آپ نے انھیں حکم دیا تو انھوں نے عصر کے لیے اقامت کیہ، اور اس وقت سورج بلند،روشن غروب ہوا تو آپ نے بلا ل رضی اللہ عنہ کو حکم دیا، انھوں نے مغرب کے لیے اقامت کہی پھر نے ان کو حکم دیا تو انھوں نے عشاء کے لیے اقامت کہی،اس وقت سرخی غائب ہو گئی تھی،پھر جب فجر طلوع ہوئی تو آپ نے حکم دیا تو انھوں نے فجر کے لیے اقامت کہی،پھر جب دوسرا دن ہوا تو آپ نے انھیں (بلال رضی اللہ عنہ کو)حکم دیا تو انھوں نے ظہر کے لیے دن ٹھنڈا ہونے دیا، انھوں نے اسے ٹھنڈا کیا اور خوب ٹھنڈا کیا اور عصر کی نماز پڑھی جبکہ سورج بلند تھا (البتہ)پہلے کی نسبت زیادہ تاخیر کی اور مغرب کی نماز شفق (سرخی)کے غروب ہونے سے (کچھ ہی)پہلے پڑھی اور عشاء کی نماز تہائی رات گزر جانے کےبعد پڑھی اور فجر کی نماز پڑھی تو روشنی پھیلنے دی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا:نماز کے اوقات کے بارے میں سوال کرنے والا کہاں ہے؟’’تو اس آدمی نے کہا: اے اللہ کے رسول! میں ہو ں۔ آپ نے فرمایا: ’’تمھاری نمازوں کا وقت ان اوقات کے درمیان ہے جو تم نے دیکھے۔‘‘"}],[1328,"حرمی بن عمارہ نے کہا : ہمیں شعبہ نے علقمہ بن مرثد سے حدیث سنائی ، انھوں نے سلیمان بن بریدہ سے اور انھوں نے اپنے والد سے روایت کی کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے نمازوں کے اوقات کے بارے میں سوال کیا آب نے فرمایا’’نمازوں میں ہمارے ساتھ موجود رہو ۔ ‘‘ پھر آپ نے بلال رضی اللہ عنہ کو حکم دیا تو انھوں نے اندھیرے میں اذان کہی ، جب فجر طلوع ہوئی آب نے صبح کی نماز پڑھائی ، پھر جب سورج آسمان کے درمیان سے ڈھلا تو آپ نے انھیں ظہر کا حکم دیا ، پھر جب سورج ( ابھی ) اونچا تھا ، آپ نے انھیں عصر کا حکم دیا ، پھر جب سورج غروب ہوگیا تو آب نے انھیں مغرب کا حکم دیا ، پھر جب شفق نیچے چلی گئی تو انھوں نے صبح کو روشن ہونے دیا ( پھر فجر ادا کی ) ، پھر انھیں ظہر کا حکم دیا تو انھون نے اسے ٹھنڈا ہونے دیا ، پھر انھیں عصر کا حکم دیا جبکہ سورج ابھی سفید اور صاف تھا ، اس میں زردی کی کوئی آمیزش نہ تھی ، پہر انھیں شفق گر ( کر غائب ہو ) جانے سے قبل مغرب کے بارے میں حکم دیا ، پھر تہائی رات یا رات کا کچھ حصہ گزر جانے کے بعد انھیں عشاء کے بارے میں حکم دیا ۔ حرمی کو شک ہو ا ۔ پھر جب صبح ہوئی تو آپ نے پوچھا ۔ سائل کہاں ہے؟ جو تم نے دیکھا ، ان کے درمیان ( نمازوں کا ) وقت ہے ۔ ‘‘","",{"u2":"حرمی بن عمارہ نے کہا: ہمیں شعبہ نے علقمہ بن مرثد سے حدیث سنائی، انھوں نےسلیمان بن بریدہ سے اور انھوں نے اپنے والد سے روایت کی کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے نمازوں کے اوقات کے بارے میں سوال کیا آب نے فرمایا’’نمازوں میں ہمارے ساتھ موجود رہو۔‘‘ پھر آپ نے بلال رضی اللہ عنہ کو حکم دیا تو انھوں نے اندھیرے میں اذان کہی،جب فجر طلوع ہوئی آب نے صبح کی نماز پڑھائی، پھر جب سورج آسمان کے درمیان سے ڈھلا تو آپ نے انھیں ظہر کا حکم دیا، پھر جب سورج (ابھی)اونچا تھا، آپ نے انھیں عصر کا حکم دیا،پھر جب سورج غروب ہوگیا تو آب نے انھیں مغرب کا حکم دیا، پھر جب شفق نیچے چلی گئی تو انھوں نے صبح کو روشن ہونے دیا (پھر فجر ادا کی)،پھر انھیں ظہر کا حکم دیا تو انھون نے اسے ٹھنڈا ہونے دیا، پھر انھیں عصر کا حکم دیا جبکہ سورج ابھی سفید اور صاف تھا، اس میں زردی کی کوئی آمیزش نہ تھی، پہر انھیں شفق گر (کر غائب ہو)جانے سے قبل مغرب کے بارے میں حکم دیا، پھر تہائی رات یا رات کا کچھ حصہ گزر جانے کے بعد انھیں عشاء کے بارے میں حکم دیا۔ حرمی کو شک ہو ا۔ پھر جب صبح ہوئی تو آپ نے پوچھا۔ سائل کہاں ہے؟ جو تم نے دیکھا، ان کے درمیان (نمازوں کا)وقت ہے۔‘‘"}],[1329,"محمد بن عبداللہ بن نمیر نے ہمیں حدیث سنائی ( کہا : ) میرے والد نے ہمیں حدیث بیان کی کہا : ہمیں بدر بن عثمان نے حدیث سنائی ، کہا : ہمیں ابو بکر بن ابی موسیٰ نے اپنے والد سے حدیث سنائی ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ کے پاس ایک سائل نمازوں کے اوقات پوچھنے کے لیے حاضر ہوا تو آپ نے اسے ( زبانی ) کچھ جواب نہ دیا ۔ کہا : جب فجر کی پو پھوٹی تو آپ نے فجر کی نماز پڑھائی جبکہ لوگ ( اندھیرے کی وجہ سے ) ایک دوسرے کو پہچان نہیں پارہے تھے ، پھر جب سورج ڈھلا تو آپ نے انہیں ( بلال رضی اللہ عنہ کو ) حکم دیا اور انھون نے ظہر کی اقامت کہی جبکہ سورج ابھی بلند تھا ، پھر جب سورج نیچے چلا گیا تو آپ نے انھیں حکم دیا تو انھوں نے مغرب کے اقامت کہی ، پھر جب شفق غائب ہوئی تو آپ نے انھیں حکم دیا تو انھوں عشاء کی اقامت کہی ، پھر اگلے دن فجر میں تاخیر کی ، یہاں تک کہ اس وقت سے فارغ ہوئے جب کہنے والا کہے ، سورج نکل آیا ہے یا نکلنے کو ہے ، پھر ظہر کو مؤخر کیا حتی کہ گزشتہ کل کی عصر کے قریب کا وقت ہو گیا ، پھر عصر کو مؤخر کیا کہ جب سلام پھیرا تو کہنے والا کہے : آفتاب میں سرخی آگئی ہے ، پھر مغرب کو مؤخر کیا حتی کہ شفق غروب ہونے کے قریب ہوئی ، پھر عشاء کو مؤخر کیا حتی کہ رات کی پہلی تہائی ہوگئی پھر صبح ہوئی تو آپ نے سائل کو بلوایا اور فرمایا : ’’ ( نماز کا ) وقت ان دونوں ( وقتوں ) کے درمیان ہے ۔ ‘‘","",{"u2":"محمد بن عبداللہ بن نمیر نے ہمیں حدیث سنائی (کہا:)میرے والد نے ہمیں حدیث بیان کی کہا: ہمیں بدر بن عثمان نے حدیث سنائی، کہا: ہمیں ابو بکر بن ابی موسیٰ نے اپنے والد سے حدیث سنائی، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ کے پاس ایک سائل نمازوں کے اوقات پوچھنے کے لیے حاضر ہوا تو آپ نے اسے (زبانی)کچھ جواب نہ دیا۔ کہا: جب فجر کی پو پھوٹی تو آپ نے فجر کی نماز پڑھائی جبکہ لوگ (اندھیرے کی وجہ سے)ایک دوسرے کو پہچان نہیں پارہے تھے، پھر جب سورج ڈھلا تو آپ نے انہیں (بلال رضی اللہ عنہ کو)حکم دیا اور انھون نے ظہر کی اقامت کہی جبکہ سورج ابھی بلند تھا، پھر جب سورج نیچے چلا گیا تو آپ نے انھیں حکم دیا تو انھوں نے مغرب کے اقامت کہی،پھر جب شفق غائب ہوئی تو آپ نے انھیں حکم دیا تو انھوں عشاء کی اقامت کہی، پھر اگلے دن فجر میں تاخیر کی، یہاں تک کہ اس وقت سے فارغ ہوئے جب کہنے والا کہے، سورج نکل آیا ہے یا نکلنے کو ہے،پھر ظہر کو مؤخر کیا حتی کہ گزشتہ کل کی عصر کے قریب کا وقت ہو گیا،پھر عصر کو مؤخر کیا کہ جب سلام پھیرا تو کہنے والا کہے: آفتاب میں سرخی آگئی ہے، پھر مغرب کو مؤخر کیا حتی کہ شفق غروب ہونے کے قریب ہوئی، پھر عشاء کو مؤخر کیا حتی کہ رات کی پہلی تہائی ہوگئی پھر صبح ہوئی تو آپ نے سائل کو بلوایا اور فرمایا:’’(نماز کا) وقت ان دونوں (وقتوں)کے درمیان ہے۔‘‘"}],[1330,"وکیع نے بدر بن عثمان سے روایت کی ، انھون نے ابو بکر بن ابی موسیٰ سےسن کر یہ حدیث بیان کی ، انہون نے اپنے والد سے روایت کی کہ ایک سائل نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور آپ سے نمازوں کے اوقات کے بارے میں سوال کیا ۔ ۔ ۔ ۔ ۔ ( آگے ) ابن نمبر کی روایت کی طرح ہے ، سوائے اس کے کہ انھوں نے کہا : دوسرے دن آپ نے مغرب کی نماز شفق غائب ہونے سے پہلے پڑھی ۔","",{"u2":"وکیع نےبدر بن عثمان سے روایت کی، انھون نے ابو بکر بن ابی موسیٰ سےسن کر یہ حدیث بیان کی، انہون نے اپنے والد سے روایت کی کہ ایک سائل نبی اکرم صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور آپ سے نمازوں کے اوقات کے بارے میں سوال کیا۔۔۔۔۔(آگے)ابن نمبر کی روایت کی طرح ہے، سوائے اس کے کہ انھوں نے کہا: دوسرے دن آپ نے مغرب کی نماز شفق غائب ہونے سے پہلے پڑھی۔"}],[1331,"لیث نے ابن شہاب سے ، انھوں نے ( سعید ) بن مسیب اور ابو سلمہ بن عبدالرحمن سے اور انھوں سیدنا ابو ہریرہ صلی اللہ علیہ وسلم سے روایت کی ، انھوں نے کہا : رسول لللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جب گرمی شدید ہو جائے تو نماز ٹھنڈے وقت میں پڑھوکونکہ گرمی کی شدت دوزخ کی لپٹوں ( گرمی کے پھیلاؤ ) میں سے ہے ۔ ‘‘","",{"u2":"لیث نے ابن شہاب سے، انھوں نے (سعید)بن مسیب اور ابو سلمہ بن عبدالرحمن سے اور انھوں حضرت ابو ہریرہ صلی اللہ علیہ وسلم سے روایت کی، انھوں نے کہا: رسول لللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جب گرمی شدید ہو جائے تو نماز ٹھنڈے وقت میں پڑھوکونکہ گرمی کی شدت دوزخ کی لپٹوں (گرمی کے پھیلاؤ)میں سے ہے۔‘‘"}],[1332,"یونس نے بتایا ، انھیں ابن شہاب نے خبر دی ، انھوں نے کہا : مجھے ابو سلمہ اور سعید بن مسیب نے بتایا کہ ان کے دونون نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ۔ ۔ ۔ بالکل اسی طرح ( جیسے سابقہ حدیث میں ہے ۔)","",{"u2":"یونس نے بتایا، انھیں ابن شہاب نے خبر دی، انھوں نے کہا: مجھے ابو سلمہ اور سعید بن مسیب نے بتایا کہ ان کے دونون نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔۔ بالکل اسی طرح (جیسے سابقہ حدیث میں ہے۔)"}],[1333,"عمرو ( بن حارث بن یعقوب انصاری ) نے خبر دی کہ بکیر ( بن عبداللہ مخزومی ) نے انھیں بسر بن سعید اور سلیمان اغرّ سے حدیث سنائی اورانھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب گرم دن ہو تو نماز ٹھنڈے وقت میں ( پڑھو ) کیونکہ گرمی کی شدت دوزخ کی لپٹوں میں سے ہے ۔ ‘‘ عمرو نے کہا : اور مجھے ابو یونس نے ابو ہریرہ رضی اللہ عنہ سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’نماز کو ٹھنڈے وقت تک موخر کرو کیونکہ گرمی کی سختی جہنم کی گرمی کے پھیلاؤ ( لپٹوں ) میں سے ہے ۔ ‘‘ عمرو نے کہا : مجھے ابن شہاب نے بھی ( سعید ) بن مسیب اور ابو سلمہ سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہوئے اسی طرح اوپر ہے ۔","",{"u2":"عمرو (بن حارث بن یعقوب انصاری)نے خبر دی کہ بکیر (بن عبداللہ مخزومی) نے انھیں بسر بن سعید اور سلیمان اغرّ سے حدیث سنائی اورانھوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب گرم دن ہو تو نماز ٹھنڈے وقت میں (پڑھو)کیونکہ گرمی کی شدت دوزخ کی لپٹوں میں سے ہے۔‘‘\nعمرو نے کہا: اور مجھے ابو یونس نے ابو ہریرہ رضی اللہ عنہ سےحدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نماز کو ٹھنڈے وقت تک موخر کرو کیونکہ گرمی کی سختی جہنم کی گرمی کے پھیلاؤ (لپٹوں)میں سے ہے۔‘‘\nعمرو نے کہا: مجھے ابن شہاب نے بھی (سعید)بن مسیب اور ابو سلمہ سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہوئے اسی طرح اوپر ہے۔"}],[1334,"علاء نے اپنے والد ( عبدالرحمان بن یعقوب ) سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’یہ گرمی آتش دوزخ کی لپٹوں میں سے ہے ، اس لیے نماز ٹھنڈے وقت میں پڑھو","",{"u2":"علاء نے اپنے والد (عبدالرحمان بن یعقوب)سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’یہ گرمی آتش دوزخ کی لپٹوں میں سے ہے، اس لیے نماز ٹھنڈے وقت میں پڑھو"}],[1335,"ہمام بن منبہ نے کہا : یہ وہ احادیث ہیں جو سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، پھر انھوں نے کئی احادیث بیان کیں ، ان میں سے ( ایک ) یہ : اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’نمازوں میں گرمی سے بچنے کے لیے ( وقت ) ٹھنڈا ہونے دو کیونکہ گرمی کی شدت جہنم کی لپٹوں میں سے ہے ۔ ‘‘","",{"u2":"ہمام بن منبہ نے کہا: یہ وہ احادیث ہیں جو سیدنا ابو ہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، پھر انھوں نے کئی احادیث بیان کیں، ان میں سے (ایک)یہ: اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نمازوں میں گرمی سے بچنے کے لیے (وقت)ٹھنڈا ہونے دو کیونکہ گرمی کی شدت جہنم کی لپٹوں میں سے ہے۔‘‘"}],[1336,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے ، انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم کا مؤذن ظہر کے اذان دینے لگا تو آپ نے فرمایا : ’’ ( وقت کو ) ٹھنڈا ہونے دو ، ٹھنڈا ہونے دو ۔ ‘‘ یا فرمایا : انتظار کرو ، انتظار کر و ‘‘ ۔ اور فرمایا : ’’ بلاشبہ گرمی کی شدت جہنم کی لپٹوں میں سے ہے ، اس لیے جب گرمی شدید ہو جائے تو نماز ٹھنڈے وقت تک مؤخر کرو ۔ ‘‘ ابوذر رضی اللہ عنہ کا قول ہے : ( نماز میں اتنی تاخیر کی گئی ) حتی کہ ہم نے ٹیلوں کا سایہ دیکھا ۔","",{"u2":"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے، انھوں نے کہا رسول اللہ صلی اللہ علیہ وسلم کا مؤذن ظہر کے اذان دینے لگا تو آپ نے فرمایا:’’(وقت کو) ٹھنڈا ہونے دو، ٹھنڈا ہونے دو۔‘‘\nیا فرمایا: انتظار کرو، انتظار کر و‘‘۔ اور فرمایا:’’ بلاشبہ گرمی کی شدت جہنم کی لپٹوں میں سے ہے، اس لیے جب گرمی شدید ہو جائے تو نماز ٹھنڈے وقت تک مؤخر کرو۔‘‘\nابوذر رضی اللہ عنہ کا قول ہے:(نماز میں اتنی تاخیر کی گئی) حتی کہ ہم نے ٹیلوں کا سایہ دیکھا۔"}],[1337,"ابن شہاب سے روایت ہے ، کہا : مجھ سے ابو سلمہ بن عبدالرحمن نے حدیث نے حدیث بیان کی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’آگ نے اپنے رب کے حضور شکایت کی اور کہا : اے میرے رب ! میرا ایک حصہ دوسرے کو کھا رہا ہے ۔ تو اللہ نے اسے دو سانس لینے کی اجازت عطا کردی : ایک سانس سردی میں اور ایک سانس گرمی ، گرمی اور سردی کے موسم میں جو تم شدید ترسین گرمی اور شدید ترسین سردی محسوس کرتے ہو تو یہ وہی ( چیز ) ہے ۔ ‘‘","",{"u2":"ابن شہاب سے روایت ہے،کہا:مجھ سے ابو سلمہ بن عبدالرحمن نے حدیث نے حدیث بیان کی کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا: رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’آگ نےاپنے رب کے حضور شکایت کی اور کہا: اے میرے رب! میرا ایک حصہ دوسرے کو کھارہا ہے۔ تو اللہ نے اسے دو سانس لینے کی اجازت عطا کردی: ایک سانس سردی میں اور ایک سانس گرمی، گرمی اور سردی کے موسم میں جو تم شدید ترسین گرمی اور شدید ترسین سردی محسوس کرتے ہو تو یہ وہی (چیز)ہے۔‘‘"}],[1338,"اسود بن سفیان کے آزاد کردہ غلام عبداللہ بن یزید نے ابو سلمہ بن عبدالرحمن اور محمد بن عبدالرحمن بن ثوبان سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جب گرمی ہو تو نماز ٹھنڈے وقت تک مؤخر کر کے پڑھو کیونکہ گرمی کی شدت جہنم کی لپٹ سے ہوتی ہے ۔ ‘‘ اور آپ صلی اللہ علیہ وسلم نے یہ ( یہ بھی ذکر فرمایا : ) ’’جہنم کی ) آگ نے اپنے رب کےحضور شکایت کی تو اللہ نے اسے سال میں دو سانس لینے کی اجازت دی : ایک سانس سردی مین اور ایک سانس گرمی میں ۔ ‘‘","",{"u2":"اسود بن سفیان کے آزاد کردہ غلام عبداللہ بن یزید نے ابو سلمہ بن عبدالرحمن اور محمد بن عبدالرحمن بن ثوبان سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسو ل اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جب گرمی ہو تو نماز ٹھنڈے وقت تک مؤخر کر کے پڑھوکیونکہ گرمی کی شدت جہنم کی لپٹ سے ہوتی ہے۔‘‘ اور آپ صلی اللہ علیہ وسلم نے یہ (یہ بھی ذکر فرمایا:)’’جہنم کی)آگ نے اپنے رب کےحضور شکایت کی تو اللہ نےاسے سال میں دو سانس لینے کی اجازت دی: ایک سانس سردی مین اور ایک سانس گرمی میں۔‘‘"}],[1339,"محمد بن ابراہیم نے ابو سلمہ سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’آگ نے عرض کی : اے میرے رب ! میرا ایک حصہ دوسرے کو کھا رہا ہے ، مجھے سانس لینے کی اجازت مرحمت فرما ۔ تو ( اللہ نے ) اسے دو سانس لینے کی اجازت دی : ایک سانس سردی میں اور ایک سانس گرمی میں ۔ تم جو سردی یا ٹھنڈک کی شدت پاتے ہو ، وہ جہنم کی سانس سے ہے اور جو تم حرارت یا گرمی کی شدت پاتے ہو تو وہ ( بھی ) جہنم کی سانس سے ہے ۔ ‘‘","",{"u2":"محمد بن ابراہیم نےابو سلمہ سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا:’’آگ نے عرض کی: اے میرے رب! میرا ایک حصہ دوسرے کو کھا رہا ہے، مجھے سانس لینے کی اجازت مرحمت فرما۔ تو (اللہ نے)اسے دو سانس لینے کی اجازت دی: ایک سانس سردی میں اور ایک سانس گرمی میں۔ تم جو سردی یا ٹھنڈک کی شدت پاتے ہو، وہ جہنم کی سانس سے ہے اور جو تم حرارت یا گرمی کی شدت پاتے ہو تو وہ (بھی)جہنم کی سانس سے ہے۔‘‘"}],[1340,"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز اس وقت پڑھتے تھے جب سورج ڈھلتا تھا","",{"u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ظہر کی نماز اس وقت پڑھتے تھے جب سورج ڈھلتا تھا"}],[1341,"ابو احوص سلام بن سلیم نے ہمیں حدیث سنائی ، انھوں نے ابو اسحاق سے ، انھوں نے سعید بن وہب سے اور انھوں سیدنا خباب رضی اللہ عنہ سے روایت کی ، کہا : ہم نے رسول اللہ صلی اللہ علیہ وسلم سے شدید گرم ریت پر نماز ادا کرنے کی شکایت کی تو آپ نے ہماری شکایت کا ازالہ نہ فرمایا ۔","",{"u2":"ابو احوص سلام بن سلیم نے ہمیں حدیث سنائی، انھوں نے ابو اسحاق سے، انھوں نے سعید بن وہب سے اور انھوں سیدنا خباب رضی اللہ عنہ سے روایت کی، کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم سے شدید گرم ریت پر نماز ادا کرنے کی شکایت کی تو آپ نے ہماری شکایت کا ازالہ نہ فرمایا۔"}],[1342,"زہیر نے کہا : ہمیں ابو اسحاق نے سعید بن وہب سے حدیث سنائی اور انھوں نے سیدنا خباب رضی اللہ عنہ سے روایت کی کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ سے ریت کی گرمی کی شکایت کی تو آپ نے ہماری شکایت کا ازالہ نہ فرمایا ۔ زہیر نے کہا : میں نے ابو اسحاق سے پوچھا : کیا ظہر کے بارے میں ( شکایت کی ؟ ) انھوں نے جواب دیا : ہاں ۔ میں نےکہا : کیا اس کو جلد ی پڑھنے ( کی مشقت ) کے بارے میں ؟ انھوں نے جواب دیا : ہاں ۔","",{"u2":")زہیر نے کہا: ہمیں ابو اسحاق نے سعید بن وہب سے حدیث سنائی اور انھوں نے سیدنا خباب رضی اللہ عنہ سے روایت کی کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ سے ریت کی گرمی کی شکایت کی تو آپ نے ہماری شکایت کا ازالہ نہ فرمایا۔\nزہیر نے کہا:میں نے ابو اسحاق سے پوچھا:کیا ظہر کے بارے میں (شکایت کی؟)انھوں نے جواب دیا:ہاں۔ میں نےکہا:کیا اس کو جلد ی پڑھنے (کی مشقت)کے بارے میں؟ انھوں نے جواب دیا:ہاں۔"}],[1343,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ہم گرمی کی شدت میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے ، جب ہم میں سے کوئی اپنی پیشانی زمین پر نہ رکھ سکتا تو اپنا کپڑا پھیلا کر اس پر سجدہ کر لیتا","",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ہم گرمی کی شدت میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے،جب ہم میں سے کوئی اپنی پیشانی زمین پر نہ رکھ سکتا تو اپنا کپڑا پھیلا کر اس پر سجدہ کر لیتا"}],[1344,"قتیبہ بن سعید اور محمد بن رمح نے کہا : لیث نے ہمیں ابن شہاب سے روایت کی ، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ انھوں نے ان کو بتایا کہ رسول اللہ صلی اللہ علیہ وسلم عصرکی نماز ( ایسے وقت میں ) پڑھتے تھے جب سورج بلند اور زندہ ( روشنی میں کمی کے بغیر ) ہوتا تھا ، عوالی کی طرف جانے والا ( عصر پڑھ کر ) چلتا اور عوالی ( مدینہ کے بالائی حصے کی بستیوں میں ) پہنچتا تو سورج ابھی بلند ہوتا تھا ۔ یہ بستیاں مدینہ سے دو تا آٹھ میل کی میل کی مسافت پر تھیں ۔ قتیبہ نے ( اپنی حدیث میں ) عوالی پہنچنے کا ذکر نہیں کیا ۔","",{"u2":"قتیبہ بن سعید اور محمد بن رمح نے کہا: لیث نے ہمیں ابن شہاب سے روایت کی، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ انھوں نے ان کو بتایا کہ رسول اللہ صلی اللہ علیہ وسلم عصرکی نماز (ایسے وقت میں)پڑھتے تھے جب سورج بلند اور زندہ (روشنی میں کمی کے بغیر)ہوتا تھا،عوالی کی طرف جانے والا (عصر پڑھ کر)چلتا اور عوالی (مدینہ کے بالائی حصے کی بستیوں میں)پہنچتا تو سورج ابھی بلند ہوتا تھا۔یہ بستیاں مدینہ سے دو تا آٹھ میل کی میل کی مسافت پر تھیں۔\nقتیبہ نے (اپنی حدیث میں)عوالی پہنچنے کا ذکر نہیں کیا۔"}],[1345,"عمرو نے ابن شہاب سے ، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تھے ۔ ۔ ۔ ( آگے ) بالکل ( اوپر کی روایت ) کے مطابق ہے ۔","",{"u2":"عمرو نے ابن شہاب سے، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تھے۔۔۔(آگے)بالکل (اوپرکی روایت)کے مطابق ہے۔"}],[1346,"امام مالک نے ابن شہاب سے ، انھوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ ہم عصر کی نماز پڑھتے تھے ، پھر جانے والا قباء جاتا ، ان لوگوں کے پاس پہنچتا اور سورج ابھی اونچا ہوتا ۔ ( قباء مدینہ سے دو میل کی مسافت پر ہے ۔)","",{"u2":"امام مالک نے ابن شہاب سے، انھوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ ہم عصر کی نماز پڑھتے تھے، پھر جانے والا قباء جاتا، ان لوگوں کے پاس پہنچتا اور سورج ابھی اونچا ہوتا۔(قباء مدینہ سے دو میل کی مسافت پر ہے۔)"}],[1347,"اسحاق بن عبداللہ بن ابی طلحہ نے سیدنا اسن بن مالک رضی اللہ عنہ سے روایت کی کہ ، کہا ہم عصر کی نماز پڑھتے ، پھر ایک انسان بنو عمرو بن عوف کے محلے ( قباء میں ) جاتا تو انھیں عصر کی نماز پڑھتے ہوئے پاتا ۔","",{"u2":"اسحاق بن عبداللہ بن ابی طلحہ نے سیدنا اسن بن مالک رضی اللہ عنہ سے روایت کی کہ، کہا ہم عصر کی نماز پڑھتے، پھر ایک انسان بنو عمرو بن عوف کے محلے (قباء میں)جاتا تو انھیں عصر کی نماز پڑھتے ہوئے پاتا۔"}],[1348,"علاء بن عبدالرحمان سے روایت ہے کہ وہ نماز ظہر سے فارغ ہو کر سیدنا انس رضی اللہ عنہ کے ہاں بصرہ میں ان کے گھر حاضر ہوئے ، ان کا گھر مسجد کے پہلو میں تھا ، جب ہم ان کی خدمت میں پہنچے تو انھوں نے پوچھا : کیا تم لوگوں نے عصر کی نماز پڑھ لی ہے ؟ ہم نے ان سے عرض کی : ہم تو ابھی ظہر کی نماز پڑھ کر لوٹے ہیں ۔ انھوں نے فرمایا : تو عصر پڑھ لو ۔ ہم نے اٹھ کر ( عصر کی ) نماز پڑھ لی ، جب ہم فارغ ہوئے تو انھوں نےکہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ’’ یہ منافق کی نماز ہے ، وہ بیٹھا ہوا سورج کو دیکھتا رہتا ہے یہاں تک کہ ( جب وہ زرد پڑ کر ) شیطان کے دو سنگوں کے درمیان چلا جاتا ہے تو کھڑا ہو کر اس ( نماز ) کی چار ٹھونگیں مار دیتا ہے اور اس میں اللہ کو بہت ہی کم یاد کرتا ہے ۔ ‘‘","",{"u2":"علاء بن عبدالرحمان سے روایت ہے کہ وہ نماز ظہر سے فارغ ہو کر سیدنا انس رضی اللہ عنہ کے ہاں بصرہ میں ان کے گھر حاضر ہوئے، ان کا گھر مسجد کے پہلو میں تھا، جب ہم ان کی خدمت میں پہنچے تو انھوں نے پوچھا: کیا تم لوگوں نے عصر کی نماز پڑھ لی ہے؟ ہم نے ان سے عرض کی: ہم تو ابھی ظہر کی نماز پڑھ کر لوٹے ہیں۔ انھوں نے فرمایا: تو عصر پڑھ لو۔ ہم نے اٹھ کر (عصر کی)نماز پڑھ لی، جب ہم فارغ ہوئے تو انھوں نےکہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ’’ یہ منافق کی نماز ہے،وہ بیٹھا ہوا سورج کو دیکھتا رہتا ہے یہاں تک کہ (جب وہ زرد پڑ کر) شیطان کے دو سنگوں کے درمیان چلا جاتا ہے تو کھڑا ہو کر اس (نماز)کی چار ٹھونگیں مار دیتا ہے اور اس میں اللہ کو بہت ہی کم یاد کرتا ہے۔‘‘"}],[1349,"سیدنا ابو اامامہ بن سہل رضی اللہ عنہ بیان کرتے ہیں : ہم نے عمر بن عبدالعزیز رحمۃ اللہ علیہ کے ساتھ ظہر کی نماز پڑھی ، پھر ہم باہر نکلے اور انس بن مالک رضی اللہ عنہ کی خدمت میں حاضر ہوئے تو ہم نے انھیں حاصر کی نماز پڑھتے ہوئے پایا ، میں نے پوچھا : چچا جان! یہ کون سی نماز ہےجو آپ نے پڑھی ہے ؟ انھوں نے جواب دیا : عصر کی ہے ، اور یہی رسول اللہ صلی اللہ علیہ وسلم کی نماز ہے جو ہم آپ کے ساتھ پڑھا کرتے تھے ۔","",{"u2":"سیدنا ابو اامامہ بن سہل رضی اللہ عنہ بیان کرتے ہیں: ہم نے عمر بن عبدالعزیز رحمۃ اللہ علیہ کے ساتھ ظہر کی نماز پڑھی، پھر ہم باہر نکلے اور انس بن مالک رضی اللہ عنہ کی خدمت میں حاضر ہوئے تو ہم نے انھیں حاصر کی نماز پڑھتے ہوئے پایا، میں نے پوچھا:چچا جان! یہ کون سی نماز ہےجو آپ نے پڑھی ہے؟ انھوں نے جواب دیا: عصر کی ہے، اور یہی رسول اللہ صلی اللہ علیہ وسلم کی نماز ہے جو ہم آپ کے ساتھ پڑھا کرتے تھے۔"}],[1350,"عمرو بن سواد عامری ، محمد بن سلمہ مرادی اور احم د بن عیسیٰ نےہمیں حدیث بیان کی ۔ اس سب کے الفاظ ملتے جلتے ہیں ۔ عمرو نے کیا : ہمیں خبر دی اور باقی دونوں نے کہا : ہمیں حدیث سنائی ابن وہب نے ، کہا : مجھے عمرو بن حارث نے یزید بن ابی حبیب سے خبر دی کہ موسیٰ بن سعد انصاری نے انھیں حدیث بیان کی ، انھوں نے حفص بن عبید اللہ سے اورانھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھا ئی تو جب آپ فارغ ہوئے ، آپ کے پاس بنو سلمہ کا ایک آدمی آیا اور کہا : اللہ کے رسول ! ہم اپنا اونٹ نحر کرنے کا اردہ رکھتے ہیں ۔ اور ہم چاہتے ہیں آپ بھی اس موقع پر موجود ہوں ۔ آپ نے فرمایا : ’’ اچھا ۔ ‘‘ آپ نکل پڑے ، ہم بھی آپ کے ساتھ چل پڑے ، ہم نے دیکھا ، اونٹ ابھی ذبح نہیں کیا گیا تھا ، اسے ذبح کیا گیا ، پھر اس کا گوشت کاٹا گیا ، پھر اس میں سے کچھ پکایا گیا ، پھر ہم نے سورج غروب ہونے سے پہلے ( اسے ) کھا لیا ۔ مرادی کا قول ہے کہ ہمیں یہ حدیث ابن وہب نے ابن لہیعہ اورعمروبن حارث دونوں سے روایت کرتے ہوئے سنائی ۔","",{"u2":"عمرو بن سواد عامری، محمد بن سلمہ مرادی اور احم د بن عیسیٰ نےہمیں حدیث بیان کی۔ اس سب کے الفاظ ملتے جلتے ہیں۔ عمرو نے کیا: ہمیں خبر دی اور باقی دونوں نے کہا: ہمیں حدیث سنائی ابن وہب نے،کہا:مجھے عمرو بن حارث نے یزید بن ابی حبیب سے خبر دی کہ موسیٰ بن سعد انصاری نےانھیں حدیث بیان کی، انھوں نے حفص بن عبید اللہ سے اورانھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھا ئی تو جب آپ فارغ ہوئے،آپ کے پاس بنو سلمہ کا ایک آدمی آیا اور کہا: اللہ کے رسول! ہم اپنا اونٹ نحر کرنے کا اردہ رکھتے ہیں۔ اور ہم چاہتے ہیں آپ بھی اس موقع پر موجود ہوں۔ آپ نے فرمایا:’’ اچھا۔‘‘ آپ نکل پڑے، ہم بھی آپ کے ساتھ چل پڑے،ہم نے دیکھا، اونٹ ابھی ذبح نہیں کیا گیا تھا، اسے ذبح کیا گیا، پھر اس کا گوشت کاٹا گیا، پھر اس میں سے کچھ پکایا گیا، پھر ہم نے سورج غروب ہونے سے پہلے (اسے)کھا لیا۔مرادی کا قول ہے کہ ہمیں یہ حدیث ابن وہب نے ابن لہیعہ اورعمروبن حارث دونوں سے روایت کرتے ہوئے سنائی۔"}],[1351,"ہمیں ولید بن مسلم نے حدیث سنائی ، کہا : اوزاعی نےہمیں حدیث بیان کی ، انھوں نے ابو نجاشی سے روایت کی ، انھوں نے کہا : میں نےسیدنا رافع بن خدیج رضی اللہ عنہ سے سنا ، کہہ رہے تھے : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز عصر پڑھتے ، پھر اونٹ ذبح کیا جاتا ، اس کے دس حصے کیے جاتے ، پھر ہم اسے پکاتے اور سورج کے غروب ہونے سے پہلے ہم اچھی طرح پکا ہوا گوشت کھا لیتے ۔","",{"u2":"ہمیں ولید بن مسلم نےحدیث سنائی، کہا:اوزاعی نےہمیں حدیث بیان کی، انھوں نے ابو نجاشی سے روایت کی، انھوں نے کہا: میں نےسیدنا رافع بن خدیج رضی اللہ عنہ سے سنا، کہہ رہے تھے: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز عصر پڑھتے، پھر اونٹ ذبح کیا جاتا، اس کے دس حصے کیے جاتے، پھر ہم اسے پکاتے اور سورج کےغروب ہونے سے پہلے ہم اچھی طرح پکا ہوا گوشت کھا لیتے۔"}],[1352,"اسحاق بن ابراہیم نے کہا : ہمیں عیسیٰ بن یونس اور شعیب بن اسحاق دمشقی نے خبر دی ، ان دونوں نے کہا : ہمیں اوزاعی نے اسی سند کے ساتھ یہی حدیث بیان کی ، البتہ انھوں ( اسحاق ) نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کےعہدمیں عصر کے بعد اونٹ ذبح کرتےتھے ، نہیں کہا : ہم آپ کے ساتھ نماز پڑھتے تھے ۔","",{"u2":"اسحاق بن ابراہیم نے کہا:ہمیں عیسیٰ بن یونس اور شعیب بن اسحاق دمشقی نے خبر دی، ان دونوں نے کہا: ہمیں اوزاعی نے اسی سند کے ساتھ یہی حدیث بیان کی، البتہ انھوں(اسحاق)نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کےعہدمیں عصر کے بعد اونٹ ذبح کرتےتھے، نہیں کہا: ہم آپ کے ساتھ نماز پڑھتے تھے۔"}],[1353,"نافع نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس شخص کی نماز عصر رہ گئی تو گیا اس کے اہل وعیال اور اس کا مال تباہ وبرباد ہو گئے ۔ ‘‘","",{"u2":"نافع نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کی نماز عصر رہ گئی تو گیا اس کے اہل وعیال اور اس کا مال تباہ وبرباد ہو گئے۔‘‘"}],[1354,"ابو بکر بن ابی شبیہ اور عمرو الناقد نے کہا : ہمیں سفیان نے زہر سے ، انھوں نے سالم سے اور انھوں نے اپنے والد ( ابن عمر رضی اللہ عنہ ) سے حدیث بیان کی ۔ عمرو نے کہا : ( ابن عمر رضی اللہ عنہ ) اس حدیث کی سند کو ( رسول اللہ صلی اللہ علیہ وسلم تک ) پہنچاتے تھے ۔ ابو بکر نے کہا : ( انھوں نے ) اس حدیث کو مرفوعا بیان کیا ۔","",{"u2":"ابو بکر بن ابی شبیہ اور عمرو الناقد نے کہا: ہمیں سفیان نے زہر سے، انھوں نے سالم سے اور انھوں نے اپنے والد (ابن عمر رضی اللہ عنہ) سے حدیث بیان کی۔\nعمرو نے کہا: (ابن عمر رضی اللہ عنہ)اس حدیث کی سند کو (رسول اللہ صلی اللہ علیہ وسلم تک) پہنچاتے تھے۔ ابو بکر نے کہا: (انھوں نے)اس حدیث کو مرفوعا بیان کیا۔"}],[1355,"عمرو بن حارث نے ابن شہاب سے ، انھوں نے سالم بن عبداللہ سے اور انھوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس شخص کی عصر کی نماز رہ گئی تو گویا اس کے ہل وعیال اور اسکا مال بتاہ و برباد ہو گئے ۔ ‘‘","",{"u2":"عمرو بن حارث نے ابن شہاب سے، انھوں نے سالم بن عبداللہ سے اور انھوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس شخص کی عصر کی نماز رہ گئی تو گویا اس کے ہل وعیال اور اسکا مال بتاہ و برباد ہو گئے۔‘‘"}],[1356,"ابوسامہ نے ہمیں حدیث سنائی ، انھوں نے ہشام سے ، انھوں نے محمد سے انھوں نے عبیدہ سے اور انھوں نےسیدنا علی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ احزاب کےدن فرمایا : ’’اللہ تعالٰی ان ( مشرکین ) کی قبروں اور گھروں کو آگ سے بھر دے ، جس طرح انھوں نے ہمیں درمیانی نماز ( عصر ) سے روکا اور ( جنگ میں ) مشغول کیے رکھا حتی کہ سورج غروب ہو گیا ۔ ‘‘","",{"u2":"ابوسامہ نے ہمیں حدیث سنائی، انھوں نے ہشام سے، انھوں نے محمد سے انھوں نے عبیدہ سے اور انھوں نےسیدنا علی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ احزاب کےدن فرمایا: ’’اللہ تعالٰی ان (مشرکین)کی قبروں اور گھروں کو آگ سے بھر دے، جس طرح انھوں نے ہمیں درمیانی نماز (عصر)سے روکا اور (جنگ میں)مشغول کیے رکھا حتی کہ سورج غروب ہو گیا۔‘‘"}],[1357,"یحیی بن سعید نے اور معتمر بن سلیمان نے ہشام سے یہ حدیث ( باقی ماندہ ) اسی سند کے ساتھ روایت کی ۔","",{"u2":"یحیی بن سعید نے اور معتمر بن سلیمان نے ہشام سے یہ حدیث (باقی ماندہ)اسی سند کے ساتھ روایت کی۔"}],[1358,"شعبہ نے کہے : ہمیں قتادہ سے سنا ، وہ ابو حسان سے حدیث بیان کررہےتھے ، انھوں نے عبیدہ سے اور انھوں سیدنا علی رضی اللہ عنہ سے روایت کی کہا : رسول اللہ صلی اللہ علیہ وسلم نے جنگ احزاب کے دن فرمایا : ’’ان لوگوں نے ہمیں درمیانی نماز سے مشغول کیے رکھا حتی کہ سورج غروب ہو گیا ‘ اللہ تعالیٰ ان کی قبروں کو اور گھروں کو یا ( فرمایا : ) ان کے پیٹوں کو آگ سے بھر دے ۔ ’’گھروں یا پیٹوں کے بارےمیں شعبہ کو شک ہوا ۔","",{"u2":"شعبہ نے کہے: ہمیں قتادہ سے سنا، وہ ابو حسان سے حدیث بیان کررہےتھے، انھوں نے عبیدہ سے اور انھوں سیدنا علی رضی اللہ عنہ سے روایت کی کہا: رسول اللہ صلی اللہ علیہ وسلم نے جنگ احزاب کے دن فرمایا: ’’ان لوگوں نے ہمیں درمیانی نماز سے مشغول کیے رکھا حتی کہ سورج غروب ہو گیا ‘اللہ تعالیٰ ان کی قبروں کو اور گھروں کو یا (فرمایا:)ان کے پیٹوں کو آگ سے بھر دے۔ ’’گھروں یا پیٹوں کے بارےمیں شعبہ کو شک ہوا۔"}],[1359,"سعید نے قتادہ سے اسی سند کے ساتھ مذکورہ بالا روایت بیان کی اور انھوں نے بغیر شک کے بیوتہم و قبورہم ( ان کے گھروں اور قبروں کو ) کہا ۔","",{"u2":"سعید نے قتادہ سے اسی سند کے ساتھ مذکورہ بالا روایت بیان کی اور انھوں نے بغیر شک کے بیوتہم و قبورہم (ان کے گھروں اور قبروں کو)کہا۔"}],[1360,"یحییٰ بن جزار نے سیدنا علی رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے غزوہ احزاب کے موقع پر جب آپ خندق کی گزر گاہوں میں سے کسی گزر گا ہ پر تشریف فرما تھے ، فرمایا : انھوں نے ہمیں درمیانی نما ( عصر ) سے مشغول کر دیا حتی کہ سورج ڈوب گیا ، اللہ تعالیٰ ان کی قبروں اور گھروں کو یا فرمایا : ان کی قبروں او ر پیٹوں کو آگ سے بھر دے ۔ ‘‘"],[1361,"یحییٰ بن جزار نے سیدنا علی رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے غزوہ احزاب کے موقع پر جب آپ خندق کی گزر گاہوں میں سے کسی گزر گا ہ پر تشریف فرما تھے ، فرمایا : انھوں نے ہمیں درمیانی نما ( عصر ) سے مشغول کر دیا حتی کہ سورج ڈوب گیا ، اللہ تعالیٰ ان کی قبروں اور گھروں کو یا فرمایا : ان کی قبروں او ر پیٹوں کو آگ سے بھر دے ۔ ‘‘",""],[1362,"شتیر بن شکل نےسیدنا علی رضی اللہ عنہ سےروایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نےاحزاب کے دن فرمایا : ’’انھوں نے ہمیں درمیانی نماز ( یعنی ) عصر کی نماز سے مشغول رکھا ، اللہ تعالیٰ ان کے گھروں اور قبروں کو آگ سے بھر دے ۔ ‘‘ پھر آپ نے اسے رات کے دونوں نمازوں مغرب اور عشاء کے درمیان پڑھا ۔ ( مغرب کا وقت جارہا تھا اس لیے آخری وقت میں پہلے مغرب پڑھی ، پھر عصر کی قضا پڑھی ، پھر عشاء پڑھی ۔)","",{"u2":"شتیر بن شکل نےسیدنا علی رضی اللہ عنہ سےروایت کی، کہا:رسول اللہ صلی اللہ علیہ وسلم نےاحزاب کے دن فرمایا: ’’انھوں نے ہمیں درمیانی نماز (یعنی)عصر کی نماز سے مشغول رکھا، اللہ تعالیٰ ان کے گھروں اور قبروں کو آگ سے بھر دے۔‘‘پھر آپ نے اسے رات کے دونوں نمازوں مغرب اور عشاء کے درمیان پڑھا۔ (مغرب کا وقت جارہا تھا اس لیے آخری وقت میں پہلے مغرب پڑھی،پھر عصر کی قضا پڑھی، پھر عشاء پڑھی۔)"}],[1363,"سیدنا عبداللہ ( بن مسعود ) رضی اللہ عنہ سے روایت ہے ، انھوں نے کہا : مشرکوں نے ( جنگ میں مشغول رکھ کر ) رسول اللہ صلی اللہ علیہ وسلم کو عصر کی نماز سے روکے رکھا یہاں تک کہ سورج سرخ یا زرد ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’انھوں نےہمیں درمیانی نماز ، عصر کی نماز سے مشغول رکھا ، اللہ تعالیٰ ان کے پیٹوں اور قبروں میں آگ بھر دے ۔ ‘‘ یا فرمایا : ’’ اللہ تعالیٰ ان کے پیٹوں اور قبروں کو آگ سے بھر دے ۔ ‘‘ ( ملأ کی جگہ حشا کا لظف ارشاد فرمایا ، مفہوم دونوں کا ایک ہی ہے ۔ ) فائدہ : نبی کریم صلی اللہ علیہ وسلم کی نظرمیں نماز عصرکی اہمیت کس قدر تھی ، ان احادیث سے اس کا بخوبی اندازہ لگایا جا سکتا ہے ۔ نیز یہ کہ آپ صلی اللہ علیہ وسلم نے طائف میں سنگ باری برداشت کی لیکن بد دعا نہ دی ، احد میں جسم مبارک زخمی ہوا ، دندان مبارک شہید ہوئے ، ستر صحابہ کرام رضی اللہ عنہ نے جام شہادت نوش کیا جن میں آپ کے چچا سید الشہداء سیدنا حمزہ رضی اللہ عنہ بھی تھے لیکن بد دعا نہ دی ۔ جنگ خندق میں ناز عصر فوت ہو گئی تو کافروں کو بد دعا دی ۔ ہر مسلمان کو چاہیے کہ وہ نفع و نقصان کا یہی معیار پیش نظر رکھے ۔","",{"u2":"حضرت عبداللہ (بن مسعود) رضی اللہ عنہ سے روایت ہے، انھوں نے کہا: مشرکوں نے (جنگ میں مشغول رکھ کر)رسو ل اللہ صلی اللہ علیہ وسلم کو عصر کی نمازسے روکے رکھا یہاں تک کہ سورج سرخ یا زرد ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’انھوں نےہمیں درمیانی نماز، عصر کی نماز سے مشغول رکھا، اللہ تعالیٰ ان کے پیٹوں اور قبروں میں آگ بھر دے۔‘‘ یا فرمایا:’’ اللہ تعالیٰ ان کے پیٹوں اور قبروں کو آگ سے بھر دے۔‘‘ (ملأ کی جگہ حشا کا لظف ارشاد فرمایا، مفہوم دونوں کا ایک ہی ہے۔)\nفائدہ:نبی کریم صلی اللہ علیہ وسلم کی نظرمیں نماز عصرکی اہمیت کس قدر تھی، ان احادیث سے اس کا بخوبی اندازہ لگایا جا سکتا ہے۔ نیز یہ کہ آپ صلی اللہ علیہ وسلم نے طائف میں سنگ باری برداشت کی لیکن بد دعا نہ دی، احد میں جسم مبارک زخمی ہوا،دندان مبارک شہید ہوئے،ستر صحابہ کرام رضی اللہ عنہم نے جام شہادت نوش کیا جن میں آپ کے چچا سید الشہداء سیدنا حمزہ رضی اللہ عنہ بھی تھے لیکن بد دعا نہ دی۔ جنگ خندق میں ناز عصرفوت ہو گئی تو کافروں کو بد دعا دی۔ ہر مسلمان کو چاہیے کہ وہ نفع و نقصان کا یہی معیار پیش نظر رکھے۔"}],[1364,"سیدہ عائشہ رضی اللہ عنہ کے آزاد کردہ غلام ابو یونس سے روایت ہے ، کہا سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے مجھے حکم دیا کہ ان کے لیے قرآن مجید لکھوں فرمایا : جب تم اس آیت پر پہنچوں ( حفظو علی الصلوت والصلوۃ الوسطی ) تو مجھے بتانا چنانچہ جب میں آیت پر پہنچا تو انھیں آگاہ کیا ، انھوں نے مجھے لکھوایا : حافظ علی الصلوت والصلاۃ الوسطی وصلاۃ العصر ، قوموا اللہ قانتین ’’ نمازوں کی حفاظت کرو اور ( خاص کر ) درمیانی نماز کی ، یعنی نماز عصر کی اور اللہ کے حضور عاجزانہ قیام کرو ۔ ‘‘ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے فرمایا : میں نے اسے رسول اللہ صلی اللہ علیہ وسلم سے ایسے ہی سنا ۔","",{"u2":"سیدہ عائشہ رضی اللہ عنہا کے آزاد کردہ غلام ابو یونس سے روایت ہے، کہا حضرت عائشہ رضی اللہ تعالیٰ عنہا نے مجھے حکم دیا کہ ان کے لیے قرآن مجید لکھوں فرمایا: جب تم اس آیت پر پہنچوں (حفظو علی الصلوت والصلوۃ الوسطی)تو مجھے بتانا چنانچہ جب میں آیت پر پہنچا تو انھیں آگاہ کیا، انھوں نے مجھے لکھوایا: حافظ علی الصلوت والصلاۃ الوسطی وصلاۃ العصر، قوموا اللہ قانتین ’’ نمازوں کی حفاظت کرو اور (خاص کر)درمیانی نماز کی، یعنی نماز عصر کی اور اللہ کے حضور عاجزانہ قیام کرو۔‘‘حضرت عائشہ رضی اللہ تعالیٰ عنہانے فرمایا: میں نے اسے رسول اللہ صلی اللہ علیہ وسلم سےایسے ہی سنا۔"}],[1366,"معاذ بن ہشام نے حدیث بیان کی ، کہا : ہمیں میرے والد نے یحییٰ بن ابی کثیر سے حدیث سنائی ، انھوں نے کہا : ہمیں ابو سلمہ بن عبدالرحمن نےسیدنا جابر بن عبداللہ رضی اللہ تعالیٰ عنہا سے روایت کرتے ہوئے حدیث بیان کی کہ خندق کے روز سیدنا عمر بن خطاب رضی اللہ عنہ کفار قریش کو برا بھلا کہنے لگے اور عرض کی : اے اللہ کے رسول ! اللہ کی قسم ! میں عصر کی نماز نہیں پڑھ سکا تھا یہاں تک کہ سورج غروب ہونے کو آگیا ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ اللہ کی قسم ! میں نے ( بھی ) نہیں پڑھی ۔ ‘‘ پھر ہم ( وادی ) بطحان میں اترے ، رسول اللہ صلی اللہ علیہ وسلم نے وضول کیا اور ہم نے بھی وضو کیا ، پھر رسول اللہ صلی اللہ علیہ وسلم نے سورج کے غروب ہو جانے کے بعد عصرکی نماز پڑھی ، پھر اس کے بعد مغرب کی نماز ادا کی ۔","",{"u2":"معاذ بن ہشام نے حدیث بیان کی، کہا:ہمیں میرے والد نے یحییٰ بن ابی کثیر سے حدیث سنائی، انھوں نے کہا: ہمیں ابو سلمہ بن عبدالرحمن نےحضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہا سے روایت کرتے ہوئے حدیث بیان کی کہ خندق کے روز سیدنا عمر بن خطاب رضی اللہ عنہ کفار قریش کو برا بھلا کہنے لگے اور عرض کی: اے اللہ کےرسول! اللہ کی قسم! میں عصر کی نماز نہیں پڑھ سکا تھا یہاں تک کہ سورج غروب ہونے کو آگیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ اللہ کی قسم! میں نے (بھی)نہیں پڑھی۔‘‘ پھر ہم (وادی)بطحان میں اترے، رسول اللہ صلی اللہ علیہ وسلم نے وضول کیا اور ہم نے بھی وضو کیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے سورج کے غروب ہو جانے کے بعد عصرکی نماز پڑھی، پھر اس کے بعد مغرب کی نماز ادا کی۔"}],[1367,"علی بن مبارک نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کی مانند حدیث بیان کی","",{"u2":"علی بن مبارک نے یحییٰ بن ابی کثیر سے اسی سند کے ساتھ اسی کی مانند حدیث بیان کی"}],[1368,"ابو زناد نے اعراج سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’رات کے فرشتے اور دن کے فرشتے ایک دوسرے کے پیچھے تمھارے درمیان آتے ہیں اور فجر کی نماز اور عصری نماز کے وقت وہ اکٹھے ہو جاتے ہیں ، پھر جنھوں نے تمھارے درمیان رات گزاری ہوتی ہے وہ اوپر چلے جاتے ہیں ، ان سے ان کا رب پوچھتا ہے ، حالانکہ وہ ان سے زیادہ جانتا ہے : تم میرے بندوں کو کس حال میں چھوڑ کر آئے ہو ؟ وہ جواب دیتے ہیں : ہم انھیں ( اس حالت میں ) چھوڑ کر آئے ہیں کہ وہ نماز پڑھ رہے تھے اور ہم ان کے پاس ( کل عصر کے وقت ) اس حالت میں پہنچے تھے کہ وہ نماز پڑھ رہے تھے","",{"u2":"ابو زناد نے اعراج سے، انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کے فرشتے اور دن کے فرشتے ایک دوسرے کے پیچھے تمھارے درمیان آتے ہیں اور فجر کی نماز اور عصری نماز کے وقت وہ اکٹھے ہو جاتے ہیں، پھر جنھوں نے تمھارے درمیان رات گزاری ہوتی ہے وہ اوپر چلے جاتےہیں، ان سے ان کا رب پوچھتا ہے، حالانکہ وہ ان سے زیادہ جانتا ہے: تم میرے بندوں کو کس حال میں چھوڑ کر آئے ہو؟ وہ جواب دیتےہیں: ہم انھیں(اس حالت میں) چھوڑ کر آئے ہیں کہ وہ نماز پڑھ رہے تھے اور ہم ان کے پاس (کل عصر کے وقت)اس حالت میں پہنچے تھے کہ وہ نماز پڑھ رہے تھے"}],[1369,"ہمام بن منبہ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’فرشتے ایک دوسرے کے پیچھے تمھار ے پاس آتے ہیں ۔ ‘‘ ( اس حدیث میں ملائکہ کا لفظ یتعاقبون سے پہلے ہے ۔ ) ۔ ۔ ۔ ۔ ۔ ( باقی روایت ) ابو زناد کی روایت کے مانند ہے","",{"u2":"ہمام بن منبہ نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: ’’فرشتے ایک دوسرے کے پیچھے تمھار ے پاس آتے ہیں۔‘‘ (اس حدیث میں ملائکہ کا لفظ یتعاقبون سے پہلے ہے۔)۔۔۔۔۔(باقی روایت)ابو زناد کی روایت کے مانند ہے"}],[1370,"زہیر بن حرب نے کہا : ہمیں مروان بن معاویہ فزاری نے حدیث سنائی ، انھوں کہا : ہمیں اسماعیل بن ابی خالد نے خبر دی ، انھوں نے کہا : ہمیں قیس بن ابی حازم نے حدیث سنائی ، انھوں نے کہا : میں نے سیدنا جریر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہے رہے تھے : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بیٹھے ہوئے تھے کہ آپ نے چودھویں رات کے چاند کی طرف نظر کی اور فرمایا : ’’سنو! تم لوگ اپنے رب کو اس طرح دیکھوں گے ، جس طرح اس پورے چاند کو دیکھ رہےہو ، اس کے دیکھنے میں تم بھیٹر نہ لگا ؤ گے ، اگر تم یہ کر سکو کہ سورج نکلنے سے پہلے کی اور سورج غروب ہونے سے پہلے کی نماز میں ( مصروفیت ، سستی وغیرہ سے ) مغلوب نہ ہو ( تو تمہیں یہ نعمت عظمیٰ مل جائے گئی ۔ ) ‘‘ آپ کی مراد عصر اور فجر کی نماز سے تھی ، پھر جرییر رضی اللہ عنہ نے یہ آیت پڑھی ( وسبح بحمد ربک قبل طلوع الشمس وقبل غروبہا ) اور اپنے رب کی حمد کی تسبیح بیان کرو ، سورج کے نکلنے سے پہلے اور اس کے غروب ہونے سے پہلے ۔ ‘‘","",{"u2":"زہیر بن حرب نے کہا: ہمیں مروان بن معاویہ فزاری نے حدیث سنائی،انھوں کہا: ہمیں اسماعیل بن ابی خالد نے خبر دی، انھوں نے کہا: ہمیں قیس بن ابی حازم نے حدیث سنائی، انھوں نے کہا: میں نے سیدنا جریر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہے رہے تھے: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بیٹھے ہوئے تھے کہ آپ نے چودھویں رات کے چاند کی طرف نظر کی اور فرمایا: ’’سنو! تم لوگ اپنے رب کو اس طرح دیکھوں گے، جس طرح اس پورے چاند کو دیکھ رہےہو، اس کے دیکھنے میں تم بھیٹر نہ لگا ؤ گے، اگر تم یہ کر سکو کہ سورج نکلنے سے پہلے کی اور سورج غروب ہونے سے پہلے کی نماز میں (مصروفیت،سستی وغیرہ سے)مغلوب نہ ہو (تو تمہیں یہ نعمت عظمیٰ مل جائے گئی۔)‘‘ آپ کی مراد عصر اور فجر کی نماز سے تھی، پھر جرییر رضی اللہ عنہ نے یہ آیت پڑھی (وسبح بحمد ربک قبل طلوع الشمس وقبل غروبہا)اور اپنے رب کی حمد کی تسبیح بیان کرو،سورج کے نکلنے سے پہلے اور اس کے غروب ہونے سے پہلے۔‘‘"}],[1371,"ابو بکر بن ابی شیبہ نے عبداللہ بن نمیر ، ابو اسامہ اور وکیع سے باقی ماندہ اسی سند کے ساتھ روایت کی ، اس میں ہے : سنو ! تم لوگ یقینا اپنے رب کے سامنے پیش کیے جاؤ گے اور اس کو اسی طرح دیکھوں گے ، جس طرح اس پور ے چا ند کو دیکھتے ہو ۔ ‘‘ پھر روای نے ( ثم قراء جریر کے بجائے ) ثم قراء ( پھر انھوں پڑھا ) کہا اور جریر رضی اللہ عنہ کا نام نہیں لیا ۔","",{"u2":"ابو بکر بن ابی شیبہ نےعبداللہ بن نمیر، ابو اسامہ اور وکیع سے باقی ماندہ اسی سند کے ساتھ روایت کی، اس میں ہے: سنو! تم لوگ یقینا اپنے رب کے سامنے پیش کیے جاؤ گے اور اس کو اسی طرح دیکھوں گے، جس طرح اس پور ے چا ند کو دیکھتے ہو۔‘‘ پھر روای نے (ثم قراء جریر کے بجائے) ثم قراء (پھر انھوں پڑھا)کہا اور جریر رضی اللہ عنہ کا نام نہیں لیا۔"}],[1372,"(اسماعیل ) ابن ابی خالد ، مسعر اور بختری بن مختار نےیہ روایت ابو بکر بن عمارہ بن رویبہ سے سنی ، انھوں نے اپنے والد ( سیدنا عمارہ بن رویبہ ثقفی رضی اللہ عنہ ) سے روایت کی ، انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کویہ فرماتے ہوئے سنا : ’’ وہ شخص ہرگز آگ میں داخل نہیں ہو گا جو سورج نکلنے اور اس کے غروب ہونے سے پہلے نماز پڑھتا ہے ۔ ‘‘ یعنی فجر اور عصر کی نمازیں ۔ اس پر بصرہ کے ایک آدمی نے ان سے کہا : کیا آپ نے یہ روایت رسول للہ صلی اللہ علیہ وسلم سے سنی تھی ؟ انھوں نے کہا : ہا ں ۔ اس آدمی نے کہا : میں شہادت دیتا ہوں کہ میں نے بھی یہ روایت رسول اللہ صلی اللہ علیہ وسلم سے سنی ۔ میرے دونوں کانوں نے اسے سنا اور میرے دل نے اسے یاد رکھا ۔","",{"u2":"(اسماعیل)ابن ابی خالد، مسعر اور بختری بن مختار نےیہ روایت ابو بکر بن عمارہ بن رویبہ سے سنی، انھوں نے اپنے والد (سیدنا عمارہ بن رویبہ ثقفی رضی اللہ عنہ) سے روایت کی، انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کویہ فرماتے ہوئے سنا:’’ وہ شخص ہرگز آگ میں داخل نہیں ہو گا جو سورج نکلنے اور اس کے غروب ہونے سے پہلے نماز پڑھتا ہے۔‘‘ یعنی فجر اور عصر کی نمازیں۔ اس پر بصرہ کے ایک آدمی نے ان سے کہا: کیا آپ نے یہ روایت رسول للہ صلی اللہ علیہ وسلم سے سنی تھی؟ انھوں نے کہا: ہا ں۔ اس آدمی نے کہا: میں شہادت دیتا ہوں کہ میں نے بھی یہ روایت رسول اللہ صلی اللہ علیہ وسلم سے سنی۔ میرے دونوں کانوں نے اسے سنا اور میرے دل نے اسے یاد رکھا۔"}],[1373,"عبدالملک بن عمیر نے سیدنا عمارۃ بن رویبہ کے بیٹے سے اور انھوں نے اپنے والد سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جو انسان سورج نکلنے اور اس کے غروب ہونے سے پہلے نماز پڑھتا ہے وہ آگ میں داخل نہیں ہو گا ۔ ‘‘ اور ان کے پاس بصرہ کا ایک باشندہ بھی موجود تھا ، اس نے پوچھا : کیا آپ نے یہ حدیث براہ راست نبی اکرم صلی اللہ علیہ وسلم سے سنی ؟ تو انھوں نے کہا : ہاں ، اور میں اس کی شہادت دیتا ہوں ۔ اس آدمی نے کہا : اور میں بھی شہادت دیتا ہوں کہ میں نے اسی جگہ ان کو یہ فرماتے ہوئے سنا جہاں آپ نے ان سے سنا تھا ۔","",{"u2":"عبدالملک بن عمیر نے حضرت عمارۃ بن رویبہ کے بیٹے سے اور انھوں نے اپنے والد سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’ جو انسان سورج نکلنے اور اس کے غروب ہونے سے پہلے نماز پڑھتا ہے وہ آگ میں داخل نہیں ہو گا۔‘‘ اور ان کے پاس بصرہ کا ایک باشندہ بھی موجود تھا، اس نے پوچھا: کیا آپ نے یہ حدیث براہ راست نبی اکرم صلی اللہ علیہ وسلم سے سنی؟ تو انھوں نے کہا: ہاں، اور میں اس کی شہادت دیتا ہوں۔ اس آدمی نے کہا: اور میں بھی شہادت دیتا ہوں کہ میں نے اسی جگہ ان کو یہ فرماتے ہوئے سنا جہاں آپ نے ان سے سنا تھا۔"}],[1374,"ہدّاب بن خالد ازدی نے کہا : ہمیں ہمام بن یحییٰ نے حدیث سنائی ، کہا : مجھے ابو جمرہ ضبعی نے ابوبکر ( بن ابی موسیٰ اشعری رضی اللہ عنہ ) سے حدیث سنائی اور انھوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’جس نے دو ٹھنڈے وقتوں کی نمازیں ادا کیں ، وہ جنت میں داخل ہو گا ۔ ‘‘ ( دن کا ٹھنڈا وقت عصر کا اور رات کا سب سے ٹھنڈا وقت فجر کا ہوتا ہے ۔)","",{"u2":"ہدّاب بن خالد ازدی نے کہا: ہمیں ہمام بن یحییٰ نے حدیث سنائی، کہا: مجھے ابو جمرہ ضبعی نے ابوبکر (بن ابی موسیٰ اشعری رضی اللہ عنہ) سے حدیث سنائی اور انھوں نے اپنے والد سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’جس نے دو ٹھنڈے وقتوں کی نمازیں ادا کیں، وہ جنت میں داخل ہو گا۔ ‘‘ (دن کا ٹھنڈا وقت عصر کا اور رات کا سب سے ٹھنڈا وقت فجر کا ہوتا ہے۔)"}],[1375,"بشر بن سریّ اور عمر و بن عاصم دونوں نے کہا : ہم سے ہمام نے اسی سند کے ساتھ حدیث بیان کی اور انھوں نے ابوبکر کا نسب بیان کیا اور کہا : ابن ابی موسیٰ","",{"u2":"بشر بن سریّ اور عمر و بن عاصم دونوں نے کہا: ہم سے ہمام نے اسی سند کے ساتھ حدیث بیان کی اور انھوں نے ابوبکر کا نسب بیان کیا اور کہا: ابن ابی موسیٰ"}],[1376,"سیدنا سلمہ بن اکوع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مغرب کی نماز اس وقت پڑھتے جب سورج غروب ہوتا اور پردے کی اوٹ میں چلا جاتا","",{"u2":"سیدنا سلمہ بن اکوع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مغرب کی نماز اس وقت پڑھتے جب سورج غروب ہوتا اور پردے کی اوٹ میں چلا جاتا"}],[1377,"ولید بن مسلم نے کہا : ہم سے اوزاعی نے حدیث بیان کی ، کہا : ہم سے ابو نجاشی نے حدیث بیان کی ، کہا : میں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے سنا ، کہہ رہے تھے : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مغرب کی نماز پڑھتے تو ہم میں سے کوئی شخص لوٹتا اور وہ اپنے تیر کے گرنے کی جگہیں دیکھ سکتا تھا ۔","",{"u2":"ولید بن مسلم نے کہا: ہم سے اوزاعی نے حدیث بیان کی، کہا: ہم سے ابو نجاشی نے حدیث بیان کی، کہا: میں نے سیدنا رافع بن خدیج رضی اللہ عنہ سے سنا، کہہ رہے تھے: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مغرب کی نماز پڑھتے تو ہم میں سے کوئی شخص لوٹتا اور وہ اپنے تیر کے گرنے کی جگہیں دیکھ سکتا تھا۔"}],[1378,"شعیب بن اسحاق دمشقی نے اوزاعی سے سابقہ سند کےساتھ رافع بن خدیج رضی اللہ عنہ سے حدیث بیان کی ، کہا : ہم مغرب کی نماز ادا کر تے ۔ ۔ ۔ ( آگے ) پچھلی حدیث کی طرح ہے ۔","",{"u2":"شعیب بن اسحاق دمشقی نے اوزاعی سے سابقہ سند کےساتھ رافع بن خدیج رضی اللہ عنہ سےحدیث بیان کی، کہا: ہم مغرب کی نماز ادا کر تے۔۔۔(آگے)پچھلی حدیث کی طرح ہے۔"}],[1379,"عمرو بن سوّاد عامری اور حرملہ بن یحییٰ دونوں نے کہا : ہمیں ابن وہب نے خبر دی ، انھوں نے کہا : مجھے یونس نے خبر دی کہ انھیں ابن شہاب نے خبر دی ، کہا : مجھے عروہ بن زبیر نے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا نے کہا : ایک رات رسول اللہ صلی اللہ علیہ وسلم نے عشاء کی نماز خوب اندھیرا ہونے تک مؤخر فرمائی اور اسی نماز کو عتمہ ( گہری تاریکی کے وقت کی نماز ) کہا جاتا تھا ۔ رسول اللہ صلی اللہ علیہ وسلم ( اس وقت تک ) گھر سے نہ نکلے یہاں تک کہ سیدنا عمربن خطاب رضی اللہ عنہ نے کہا : ( مسجد میں آنے والی ) عورتیں اور بچے سو گئے ہیں ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لائے اور نکل کر مسجد کے حاضرین سے فرمایا : ’’اہل زمین میں سے تمھارے سوا اس نماز کا اور کوئی بھی انتظار نہیں کررہا ‘‘ اور یہ لوگوں میں ( مدینہ سے باہر ) اسلام پھیلنے سے پہلے کی بات ہے ۔ حرملہ نے اپنی روایت میں اضافہ کیا کہ ابن شہاب نے کہا : مجھے بتایا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’تمھارے لیے مناسب نہ تھا کہ تم اللہ کے رسول صلی اللہ علیہ وسلم سے نماز کے لیے اصرار کرتے ۔ ‘‘ یہ تب ہوا جب عمر بن خطاب رضی اللہ عنہ نے بلند آواز سے پکارا ۔ ( انھوں نے غالباً یہ سمجھا کہ آپ صلی اللہ علیہ وسلم بھول گئے ہیں یا سو گئے ہیں)","",{"u2":"عمرو بن سوّاد عامری اور حرملہ بن یحییٰ دونوں نے کہا: ہمیں ابن وہب نے خبر دی، انھوں نے کہا: مجھے یونس نےخبر دی کہ انھیں ابن شہاب نے خبر دی، کہا: مجھے عروہ بن زبیر نے خبر دی کہ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا: ایک رات رسول اللہ صلی اللہ علیہ وسلم نے عشاء کی نماز خوب اندھیرا ہونے تک مؤخر فرمائی اور اسی نماز کو عتمہ (گہری تاریکی کے وقت کی نماز)کہا جاتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم (اس وقت تک)گھر سے نہ نکلے یہاں تک کہ سیدنا عمربن خطاب رضی اللہ عنہ نے کہا: (مسجد میں آنے والی)عورتیں اور بچے سو گئے ہیں۔ اس پر رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لائے اور نکل کر مسجد کے حاضرین سے فرمایا: ’’اہل زمین میں سے تمھارے سوا اس نماز کا اور کوئی بھی انتظار نہیں کررہا ‘‘ اور یہ لوگوں میں (مدینہ سے باہر)اسلام پھیلنے سے پہلے کی بات ہے۔\nحرملہ نے اپنی روایت میں اضافہ کیا کہ ابن شہاب نے کہا: مجھے بتایا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمھارے لیے مناسب نہ تھا کہ تم اللہ کے رسول صلی اللہ علیہ وسلم سے نماز کے لیے اصرار کرتے۔ ‘‘ یہ تب ہوا جب عمر بن خطاب رضی اللہ عنہ نے بلند آواز سے پکارا۔(انھوں نے غالباً یہ سمجھا کہ آپ صلی اللہ علیہ وسلم بھول گئے ہیں یا سو گئے ہیں"}],[1380,"عقیل نے ابن شہاب سے اسی سنج کے ساتھ مذکورہ بالا روایت بیان کی لیکن اس میں زہر ی کا قول : وذکرلی ( مجھے بتایا گیا ) اور اس کے بعد کا حصہ بیان نہیں کیا ۔","",{"u2":"عقیل نے ابن شہاب سے اسی سنج کے ساتھ مذکورہ بالا روایت بیان کی لیکن اس میں زہر ی کا قول: وذکرلی (مجھے بتایا گیا)اور اس کے بعد کا حصہ بیان نہیں کیا۔"}],[1381,"محمد بن بکر ، حجاج بن محمد اور عبدالرزاق ۔ سب کے الفاظ باہم ملتے جلتے ہیں ۔ سب نے کہا : ابن جریج سے روایت ہے ، انھوں نے کہا : مجھے مغیرہ بن حکیم نے ام کلثوم بنت ابی بکر سے خبر دی کہ انھوں نے انھیں ( مغیرہ کو ) سیدہ عائشہ رضی اللہ عنہ سے روایت کرتے ہوئے خبر دی ، انھوں نے کہا : ایک رات نبی اکرم صلی اللہ علیہ وسلم ےعشاء کی نماز میں دیر کر دی یہاں تک کہ رات کا بڑا حصہ گزر گیا اور اہل مسجد سو گئے ، پھر آپ باہر تشریف لے گئے ، نماز پڑھائی اور فرمایا : ’’ اگر ( مجھے ) یہ ( ڈر ) نہ ہوتا کہ میں اپنی امت کو مشقت میں ڈالوں گا تو یہی اس کا ( بہترین ) وقت ہے ۔ ‘‘ اور عبدالرزاق کی حدیث میں ہے : ’’ اگریہ ( ڈر ) نہ ہوتا کہ یہ میری امت کے لیے مشقت کا سبب بنے گا ۔ ‘‘","",{"u2":"محمد بن بکر، حجاج بن محمد اور عبدالرزاق۔ سب کے الفاظ باہم ملتے جلتے ہیں۔ سب نے کہا: ابن جریج سے روایت ہے، انھوں نے کہا: مجھے مغیرہ بن حکیم نے ام کلثوم بنت ابی بکر سے خبر دی کہ انھوں نے انھیں (مغیرہ کو)سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہوئے خبر دی، انھوں نے کہا: ایک رات نبی اکرم صلی اللہ علیہ وسلم ےعشاء کی نماز میں دیر کر دی یہاں تک کہ رات کا بڑا حصہ گزر گیا اور اہل مسجد سو گئے، پھر آپ باہر تشریف لے گئے، نماز پڑھائی اور فرمایا:’’ اگر (مجھے)یہ (ڈر)نہ ہوتا کہ میں اپنی امت کو مشقت میں ڈالوں گا تو یہی اس کا (بہترین)وقت ہے۔‘‘ اور عبدالرزاق کی حدیث میں ہے:’’ اگریہ (ڈر)نہ ہوتا کہ یہ میری امت کے لیے مشقت کا سبب بنے گا۔‘‘"}],[1382,"حکم نےنافع سے اور انھوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ ایک رات ہم عشاء کی آخری نماز کے لیے رسول اللہ صلی اللہ علیہ وسلم کا انتظار کرتے رہے ، جب رات کا تہائی حصہ گزر گیا یا اس کے ( بھی ) بعد آپ تشریف لائے ، ہمیں معلوم نہیں کہ آپ کو گھر والوں ( کے معاملے ) میں کسی چیز نے مشغول رکھا تھا یا کوئی اور بات بھی ، جب آپ باہر آئے تو فرمایا : ’’بلا شبہ تم ایسی نماز کا انتظار کررہے ہو جسکا تمھارے سوا کسی اور دین کے پیرو کار انتظار نہیں کر رہے ، اور اگر مجھے یہ ڈر نہ ہوتا کہ یہ میری امت کے لیے گراں ہو گا تو میں انھیں اسی گھڑی میں ( یہ ) نماز پڑھایا کرتا ۔ ‘‘ پھر آپ نے مؤذن کو حکم دیا ، اس نے اقامت کہی اور آب نے نماز پڑھائی ۔","",{"u2":"حکم نےنافع سے اور انھوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ ایک رات ہم عشاء کی آخری نماز کے لیے رسول اللہ صلی اللہ علیہ وسلم کا انتظار کرتے رہے، جب رات کا تہائی حصہ گزر گیا یا اس کے (بھی)بعد آپ تشریف لائے، ہمیں معلوم نہیں کہ آپ کو گھر والوں (کے معاملے)میں کسی چیز نے مشغول رکھا تھا یا کوئی اور بات بھی، جب آپ باہر آئے تو فرمایا:’’بلا شبہ تم ایسی نماز کا انتظار کررہے ہو جسکا تمھارے سوا کسی اور دین کے پیرو کار انتظار نہیں کر رہے، اور اگر مجھے یہ ڈر نہ ہوتا کہ یہ میری امت کے لیے گراں ہو گا تو میں انھیں اسی گھڑی میں (یہ)نماز پڑھایا کرتا۔‘‘ پھر آپ نے مؤذن کو حکم دیا، اس نے اقامت کہی اور آب نے نماز پڑھائی۔"}],[1383,"ہمیں ابن جریج نے خبر دی ، کہا : مجھے نافع نے خبر دی ، انھوں نے کہا : ہم سے سیدنا عبد اللہ بن عمر رضی اللہ عنہ نے حدیث بیان کی کہ ایک رات رسول اللہ صلی اللہ علیہ وسلم ( کسی بنا پر ) اس ( عشاء کی نماز ) سے مشغول ہو گئے ، آپ نے اسے مؤخر کر دیا یہاں تک کہ ہم مسجد میں سو گئے ، پھر بیدار ہوئے ، پھر سو گئے ، پھر بیدار ہوئے ، پھر آپ ( گھر سے ) نکل کر ہمارے پاس تشریف لائے اور فرمایا : ’’آج رات تمھارے سوا اہل زمین میں سے کوئی نہیں جو نماز کا انتظار کر رہا ہو ۔ ‘‘","",{"u2":"ہمیں ابن جریج نے خبر دی، کہا: مجھے نافع نے خبر دی، انھوں نے کہا: ہم سے سیدنا عبد اللہ بن عمر رضی اللہ عنہ نے حدیث بیان کی کہ ایک رات رسول اللہ صلی اللہ علیہ وسلم (کسی بنا پر)اس (عشاء کی نماز)سے مشغول ہو گئے، آپ نے اسے مؤخر کر دیا یہاں تک کہ ہم مسجد میں سو گئے، پھر بیدار ہوئے، پھر سو گئے، پھر بیدار ہوئے، پھر آپ (گھر سے)نکل کر ہمارے پاس تشریف لائے اور فرمایا:’’آج رات تمھارے سوا اہل زمین میں سے کوئی نہیں جو نماز کا انتظار کر رہا ہو۔‘‘"}],[1384,"ثابت سے روایت ہےکہ انھوں نے سیدنا انس رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم یک مہر ( یا انگوٹھی ) کے بارے میں پوچھا تو ( سیدنا انس رضی اللہ عنہ نے ) کہا : ایک رات رسول اللہ صلی اللہ علیہ وسلم نے عشاء کی نماز آدھی رات تک مؤخر کی یا آدھی رات گزرنے کو تھی ، پھر آپ تشریف لائے اور فرمایا : ’’بلاشبہ ( دوسرے ) لوگوں نے نماز پڑھ لی اور سوچ کے ، اور تم ہو کہ نماز ہی میں ہو جب تک نماز کے انتظار میں بیٹھے ہو ۔ ‘‘ سیدنا انس رضی اللہ عنہ نے بتایا : جیسے میں ( اب بھی ) آپ کی چاندی سے بنی انگوٹھی کی چمک دیکھ رہا ہوں اور انھوں نے بائیں ہاتھ کی انگلی اٹھاتے ہوئے چھوٹی انگلی سے ( اشارہ کیاکہ انگوٹھی اس میں تھی ۔)","",{"u2":"ثابت سے روایت ہےکہ انھوں نے سیدنا انس رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم یک مہر (یا انگوٹھی) کے بارے میں پوچھا تو (سیدنا انس رضی اللہ عنہ نے)کہا: ایک رات رسول اللہ صلی اللہ علیہ وسلم نے عشاء کی نماز آدھی رات تک مؤخر کی یا آدھی رات گزرنےکو تھی،پھر آپ تشریف لائے اور فرمایا: ’’بلاشبہ (دوسرے)لوگوں نے نماز پڑھ لی اور سوچکے، اور تم ہو کہ نماز ہی میں ہو جب تک نماز کے انتظار میں بیٹھے ہو۔‘‘ سیدنا انس رضی اللہ عنہ نے بتایا: جیسے میں (اب بھی)آپ کی چاندی سے بنی انگوٹھی کی چمک دیکھ رہا ہوں اور انھوں نے بائیں ہاتھ کی انگلی اٹھاتے ہوئے چھوٹی انگلی سے (اشارہ کیاکہ انگوٹھی اس میں تھی۔)"}],[1385,"ابوزید سعید بن ربیع نے ہمیں حدیث بیان کی ، کہا : ہمیں قرہ بن خالد نے قتادہ سے حدیث سنائی ، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : ہم نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کا انتظار کیا حتی کہ آدھی رات کے قریب ( کا وقت ) ہوگیا ، پھر آپ آئے اور نماز پڑھائی ۔ پھر آپ نے ہمارے طرف رخ فرمایا ، ایسا لگتا ہے کہ میں ( اب بھی ) آپ کی انگوٹھی کی چمک دیکھ رہا ہوں ، وہ آپ کے ہاتھ میں تھی ، چاندی کی بنی ہوئی تھی","",{"u2":"ابوزید سعید بن ربیع نے ہمیں حدیث بیان کی، کہا: ہمیں قرہ بن خالد نے قتادہ سےحدیث سنائی، انھوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی، کہا: ہم نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کا انتظار کیا حتی کہ آدھی رات کے قریب (کا وقت)ہوگیا،پھر آپ آئے اور نماز پڑھائی۔پھر آپ نے ہمارے طرف رخ فرمایا، ایسا لگتا ہے کہ میں (اب بھی)آپ کی انگوٹھی کی چمک دیکھ رہا ہوں، وہ آپ کے ہاتھ میں تھی، چاندی کی بنی ہوئی تھی"}],[1386,"عبیداللہ بن عبدالمجید حنفی نے قرہ سے اسی سند کے ساتھ ( یہی ) حدیث بیان کی اور یہ بیان نہ کیا : ’’پھر آپ نے ہمار ی طرف رخ فرمایا ۔ ‘‘","",{"u2":"عبیداللہ بن عبدالمجید حنفی نے قرہ سے اسی سند کے ساتھ (یہی)حدیث بیان کی اور یہ بیان نہ کیا: ’’پھر آپ نے ہمار ی طرف رخ فرمایا۔‘‘"}],[1387,"سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت ہے ، انھوں نے کہا : میں اور میرے ( وہ ) ساتھ ۔ جو میرے ساتھ بڑی کشتی میں ( حبشہ سے واپس ) آئے تھے ۔ بطحان کے نشیبی میدان میں اترے ہوئے تھے ، رسول اللہ صلی اللہ علیہ وسلم مدینہ میں تھے اور ہر رات ان میں سے ایک جماعت باری باری عشاء کی نماز میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتی تھی ۔ ابو موسیٰ رضی اللہ عنہ نے کہا کہ مجھے اور میرے ساتھیوں کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ یوں اتفاق پیش آیا کہ آپ اپنے کسی معاملے میں ( اتنے ) مشغول ہو گئے کہ آپ نے نماز کو مؤخر کر دیا حتی کہ آدھی رات ہو گئی ۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور لوگوں کو نماز پڑھائی ۔ جب آپ نے ناز مکمل کر لی تو ان لوگوں سے جو آپ کے سامنے حاضر تھے ، فرمایا : ’’ذرا ٹھہر و میں تمھیں بتاتا ہوں اور تم خوش ہو جاؤ یہ تم پر اللہ تعالیٰ کی ایک نعمت ہے کہ لوگوں میں اس وقت ، تمھارے سوا ، کوئی بھی نماز نہیں پڑھ رہا ۔ ‘‘ یا آپ نے فرمایا : ’’اس وقت تمھارے سوا کسی نے نماز نہیں پڑھی ۔ ‘‘ ہمیں یاد نہیں کہ آپ صلی اللہ علیہ وسلم نے کون سا جملہ کہا تھا ۔ ابو موسیٰ رضی اللہ عنہ نے بتایا : ہم رسول اللہ صلی اللہ علیہ وسلم کی بات سن کر خوش خوش واپس آئے ۔","",{"u2":"سیدنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت ہے، انھوں نے کہا: میں اور میرے (وہ)ساتھ۔ جو میرے ساتھ بڑی کشتی میں (حبشہ سے واپس)آئے تھے۔بطحان کے نشیبی میدان میں اترے ہوئے تھے، رسول اللہ صلی اللہ علیہ وسلم مدینہ میں تھے اور ہر رات ان میں سے ایک جماعت باری باری عشاء کی نمازمیں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتی تھی۔ ابو موسیٰ رضی اللہ عنہ نے کہا کہ مجھے اور میرے ساتھیوں کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ یوں اتفاق پیش آیا کہ آپ اپنے کسی معاملے میں (اتنے)مشغول ہو گئے کہ آپ نے نماز کو مؤخر کر دیا حتی کہ آدھی رات ہو گئی۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور لوگوں کو نماز پڑھائی۔ جب آپ نے ناز مکمل کر لی تو ان لوگوں سے جو آپ کے سامنے حاضر تھے، فرمایا:’’ذرا ٹھہر و میں تمھیں بتاتا ہوں اور تم خوش ہو جاؤ یہ تم پر اللہ تعالیٰ کی ایک نعمت ہے کہ لوگوں میں اس وقت، تمھارے سوا، کوئی بھی نماز نہیں پڑھ رہا۔‘‘ یا آپ نے فرمایا: ’’اس وقت تمھارے سوا کسی نے نماز نہیں پڑھی۔‘‘ ہمیں یاد نہیں کہ آپ صلی اللہ علیہ وسلم نے کون سا جملہ کہا تھا۔ ابو موسیٰ رضی اللہ عنہ نے بتایا: ہم رسول اللہ صلی اللہ علیہ وسلم کی بات سن کر خوش خوش واپس آئے۔"}],[1388,"ابن جریج نے ہمیں خبر دی ، کہا : میں نے عطاء سے پوچھا : آپ کے نزدیک کون سی گھڑی زیادہ پسندیدہ ہے کہ میں اس میں عشاء کی نماز ، جسے لوگ عتمہ کہتے ہیں ، امام کے ساتھ یا انفرادی طور پر پڑھوں ؟ انھوں نے جواب دیا : میں نے ابن عباس رضی اللہ عنہ کویہ فرماتے ہوئےسنا : ایک رات نبی صلی اللہ علیہ وسلم نے عشاء کی نماز میں دیر کر دی حتی کہ لوگ سوئے ، پھر بیدار ہوئے ، پھر سوئے اور بیدار ہوئے تو سیدنا عمر بن خطاب رضی اللہ عنہ کھڑے ہوئے اور بلند آواز سے کہا : نماز ! عطاء نے کہا : ابن عباس رضی اللہ عنہ نے بتایا : تو نبی اکرم صلی اللہ علیہ وسلم نکلے ، ایسا لگتا ہے کہ میں اب بھی آپ کو دیکھ رہا ہوں ، آپ کے سر مبارک سے قطرہ قطرہ پانی ٹپک رہا تھا اور ( بالوں میں سے پانی نکالنے کے لیے ) آپ نے اپنا ہاتھ سر کے آدھے حصے پر رکھا ہوا تھا ، آپ صلی اللہ علیہ وسلم نے فرمایا : ’’اگر یہ بات نہ ہوتی کہ میری امت کےلیے مشقت ہو گی تو میں انھیں حکم دیتا کہ وہ اس نماز کو اسی وقت پڑھا کریں ۔ ‘‘ ( ابن جریج نے ) کہا : میں نے عطاء سے اچھی طرح چوچھا کہ ابن عباس رضی اللہ عنہ نے انھیں کس طرح بتایا کہ نبی صلی اللہ علیہ وسلم نے اپنا ہاتھ کس انداز سے اپنے سر پر رکھا تھا ؟ تو عطاء نے میرے سامنے اپنی انگلیاں کسی قدر کھولیں ، پھر اپنی انگلیوں کے کنارے سر کی ایک جانب رکھے ، پھر ان کو دباتے ہوئے اس طرح ان کو سر پر پھیرا یہا ں تک کہ ان کا انگوٹھا کان کے اس کنارے کو چھونے لگا جو چہرے کے قریب ہوتا ہے ، پھر کنپٹی اور داڑھی کے کنارے کو ( چھوا ) بس اس طرح کیا نہ ( دباؤ میں ) کمی کی نہ کسی چیز کو پکڑا ( اور نچوڑا ۔ ) میں نے عطاء سے پوچھا : آب کو کیا بتایا گیا کہ اس رات نبی اکرم صلی اللہ علیہ وسلم نے کتنی تخیر کی ؟ انھوں نے کہا : مجھے معلوم نہیں ۔ عطاء نے کہا : میرے نزدیک زیادہ پسندیدہ یہی ہےکہ میں امام ہوں یا اکیلا ، یہ نماز تاخیر سے پڑھوں ، جس طرح نبی اکرم صلی اللہ علیہ وسلم نے اس رات پڑھی تھی ۔ اگر یہ بات تمھارے لیے انفرادی طور پر با جماعت کی صورت میں لوگوں کےلیے جب تم ان کے امام ہو ، دشواری کا باعث ہو تو اس کو درمیان وقت میں پڑھو ، نہ جلد ی اور نہ مؤخر کرکے ۔","",{"u2":"ابن جریج نے ہمیں خبر دی، کہا: میں نے عطاء سے پوچھا: آپ کے نزدیک کون سی گھڑی زیادہ پسندیدہ ہے کہ میں اس میں عشاء کی نماز، جسے لوگ عتمہ کہتے ہیں، امام کے ساتھ یا انفرادی طور پر پڑھوں؟ انھوں نے جواب دیا: میں نے ابن عباس رضی اللہ عنہما کویہ فرماتے ہوئےسنا: ایک رات نبی صلی اللہ علیہ وسلم نے عشاء کی نماز میں دیر کر دی حتی کہ لوگ سوئے، پھر بیدار ہوئے، پھر سوئے اور بیدار ہوئے تو سیدنا عمر بن خطاب رضی اللہ عنہ کھڑے ہوئے اور بلند آواز سے کہا: نماز! عطاء نے کہا: ابن عباس رضی اللہ عنہ نے بتایا: تو نبی اکرم صلی اللہ علیہ وسلم نکلے،ایسا لگتا ہے کہ میں اب بھی آپ کو دیکھ رہا ہوں، آپ کے سر مبارک سے قطرہ قطرہ پانی ٹپک رہا تھا اور (بالوں میں سے پانی نکالنے کے لیے)آپ نے اپنا ہاتھ سر کے آدھے حصے پر رکھا ہوا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا:’’اگر یہ بات نہ ہوتی کہ میری امت کےلیے مشقت ہو گی تو میں انھیں حکم دیتا کہ وہ اس نماز کو اسی وقت پڑھا کریں۔‘‘\n(ابن جریج نے)کہا:میں نے عطاء سے اچھی طرح چوچھا کہ ابن عباس رضی اللہ عنہ نے انھیں کس طرح بتایا کہ نبی صلی اللہ علیہ وسلم نے اپنا ہاتھ کس انداز سے اپنے سر پر رکھا تھا؟ تو عطاء نے میرے سامنے اپنی انگلیاں کسی قدر کھولیں، پھر اپنی انگلیوں کے کنارے سر کی ایک جانب رکھے، پھر ان کو دباتے ہوئے اسطرح ان کو سر پر پھیرا یہا ں تک کہ ان کا انگوٹھا کان کے اس کنارے کو چھونے لگا جو چہرے کے قریب ہوتا ہے، پھر کنپٹی اور داڑھی کے کنارے کو (چھوا)بس اس طرح کیا نہ (دباؤ میں)کمی کی نہ کسی چیز کو پکڑا (اور نچوڑا۔)میں نے عطاء سے پوچھا: آب کو کیا بتایا گیا کہ اس رات نبی اکرم صلی اللہ علیہ وسلم نے کتنی تخیر کی؟ انھوں نے کہا: مجھے معلوم نہیں۔\nعطاء نے کہا: میرے نزدیک زیادہ پسندیدہ یہی ہےکہ میں امام ہوں یا اکیلا، یہ نماز تاخیر سے پڑھوں، جس طرح نبی اکرم صلی اللہ علیہ وسلم نے اس رات پڑھی تھی۔ اگر یہ بات تمھارے لیے انفرادی طور پر با جماعت کی صورت میں لوگوں کےلیے جب تم ان کے امام ہو، دشواری کا باعث ہو تو اس کو درمیان وقت میں پڑھو، نہ جلد ی اور نہ مؤخر کرکے۔"}],[1389,"ابواحوص نے سماک سے ، انھوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی کہ ، کہا : رسول اللہ صلی اللہ علیہ وسلم رات کی دوسری نماز تاخیر سے پڑھتے تھے","",{"u2":"ابواحوص نے سماک سے، انھوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی کہ، کہا: رسول اللہ صلی اللہ علیہ وسلم رات کی دوسری نماز تاخیر سے پڑھتے تھے"}],[1390,"قتیبہ بن سعید اور ابو کامل جحدری نے کہا : ہمیں ابو عوانہ نے سماک سے حدیث سنائی ، انھوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نمازیں تمھاری طرح ( اوقات میں ) پڑھتے تھے ، البتہ عشاء مؤخر کرکے تمھاری نماز سے کچھ دیر بعد پڑھتے تھے اور نماز میں تخفیف کرتےتھے ۔ اور ابو کامل کی روایت میں ( یخف فی الصلاۃ کے بجائے ) ’’یخفف کے الفاظ ہیں ۔ ( مفہوم ایک ہی ہے ۔)","",{"u2":"قتیبہ بن سعید اور ابو کامل جحدری نے کہا: ہمیں ابو عوانہ نے سماک سے حدیث سنائی، انھوں نے سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نمازیں تمھاری طرح (اوقات میں)پڑھتے تھے،البتہ عشاء مؤخر کرکے تمھاری نماز سے کچھ دیر بعد پڑھتے تھے اور نماز میں تخفیف کرتےتھے۔ اور ابو کامل کی روایت میں (یخف فی الصلاۃ کے بجائے) ’’یخفف کے الفاظ ہیں۔ (مفہوم ایک ہی ہے۔)"}],[1391,"زہیر نے کہا : ہم سے سفیان بن عینہ نے ابو لبید سے ، انھوں نے ابو سلمہ سے اورانھوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : ’’تمھاری نماز کے نام پر تمھارے گنوار لوگ غالب نہ آجائیں ، خبردار !یہ عشاء ہے ، وہ اونٹنیوں کا دودھ دوہنے کی وجہ سے اندھیرا کر دیتے ہیں ( اور اندھیرے ( عتمہ ) کی بنا پر اس وقت پڑھی جانے والی نماز کو صلاۃ العتمہ ، یعنی اندھیرے کی نماز کہتے ہیں","",{"u2":"زہیر نے کہا:ہم سے سفیان بن عینہ نے ابو لبید سے، انھوں نے ابو سلمہ سے اورانھوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا:’’تمھاری نماز کے نام پر تمھارے گنوار لوگ غالب نہ آجائیں، خبردار!یہ عشاء ہے، وہ اونٹنیوں کا دودھ دوہنے کی وجہ سے اندھیرا کر دیتے ہیں (اور اندھیرے (عتمہ)کی بنا پر اس وقت پڑھی جانے والی نماز کو صلاۃ العتمہ، یعنی اندھیرے کی نماز کہتےہیں"}],[1392,"وکیع نے سفیان سے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’تمھاری صلاۃ عشاء کے نام پر بدوتم پر غالب نہ آجائیں کیونکہ اللہ کی کتاب میں ا س کا نام عشاء ہے : اور بدو اونٹنیوں کا دودھ دوہنے میں اندھیرا کر دیتے ہیں ۔ ‘‘","",{"u2":"وکیع نے سفیان سے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابن عمر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’تمھاری صلاۃ عشاء کے نام پر بدوتم پر غالب نہ آجائیں کیونکہ اللہ کی کتاب میں ا س کا نام عشاء ہے: اور بدو اونٹنیوں کا دودھ دوہنے میں اندھیرا کر دیتے ہیں۔‘‘"}],[1393,"سفیان بین عیینہ نے زہری سے ، انھوں نے عروہ سے اور انھوں نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ مومن عورتیں صبح کی نماز نبی اکرم صلی اللہ علیہ وسلم کے ساتھ پڑھتی تھیں ، پھر اپنی چادریں اوڑھے ہوئے واپس آتیں اور ( اندھیرے کی وجہ سے ) کوئی انھیں پہچان نہیں سکتا تھا ۔","",{"u2":"سفیان بین عیینہ نے زہری سے، انھوں نے عروہ سےاور انھوں نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی کہ مومن عورتیں صبح کی نماز نبی اکرم صلی اللہ علیہ وسلم کے ساتھ پڑھتی تھیں، پھر اپنی چادریں اوڑھے ہوئے واپس آتیں اور (اندھیرے کی وجہ سے)کوئی انھیں پہچان نہیں سکتا تھا۔"}],[1394,"یونس نے ابن شہاب سے باقی ماندہ سابقہ سند کے ساتھ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، انھوں نےکہا : کچھ مومن عورتیں فجر کی نماز میں اپنی چادریں اوڑھے ہوئے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شریک ہوتی تھیں ، پھر وہ اپنے گھروں کو لوٹتیں تو رسول اللہ صلی اللہ علیہ وسلم کے اندھیرے میں نماز پڑھنے کی بنا پر وپہچانی نہ جا سکتی تھیں","",{"u2":"یونس نے ابن شہاب سے باقی ماندہ سابقہ سند کے ساتھ نبی اکرم صلی اللہ علیہ وسلم کی زوجہ حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی، انھوں نےکہا: کچھ مومن عورتیں فجر کی نماز میں اپنی چادریں اوڑھے ہوئے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شریک ہوتی تھیں، پھر وہ اپنے گھروں کو لوٹتیں تو رسول اللہ صلی اللہ علیہ وسلم کے اندھیرے میں نماز پڑھنے کی بنا پر وپہچانی نہ جا سکتی تھیں"}],[1395,"نصر بن علی جہضمی اور اسحاق بن موسیٰ انصاری نے کہا : ہمیں معن نے مالک سے حدیث بیان کی ، انھوں نے یحییٰ بن سعید سے ، انھوں نے عمرہ سے اور انھوں نے سیدہ عائشہ رضی اللہ عنہ سے روایت کی ، کہا : ایسا تھا کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز پڑھتے تو عورتیں اپنی چادریں اوڑھے ہوئے گھروں کو لوٹتیں ، ( اور ) اندھیرے کی وجہ سے پہچانی نہیں جاتی تھیں ۔ انصاری کی روایت میں ( متلفعات کے بجائے ) متلففات ( چادروں میں لپٹی ہوئی ) کے الفاظ ہیں ۔","",{"u2":"نصر بن علی جہضمی اور اسحاق بن موسیٰ انصاری نے کہا: ہمیں معن نے مالک سے حدیث بیان کی، انھوں نے یحییٰ بن سعید سے، انھوں نے عمرہ سے اور انھوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، کہا: ایسا تھا کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز پڑھتے تو عورتیں اپنی چادریں اوڑھے ہوئے گھروں کو لوٹتیں، (اور)اندھیرےکی وجہ سے پہچانی نہیں جاتی تھیں۔\nانصاری کی روایت میں (متلفعات کے بجائے)متلففات (چادروں میں لپٹی ہوئی)کے الفاظ ہیں۔"}],[1396,"محمد بن جعفر غندر نے ہمیں حدیث بیان کی ، کہا : ہمیں شعبہ نے حدیث سنائی ، انھوں نے سعد بن ابراہیم سے اور انھوں نے محمد بن عمرو بن حسن بن علی ( بن ابی طالب ) رضی اللہ عنہ سے روایت کی ، کہا : جب حجاج مدینہ منورہ آیا ( اور تاخیر سے نمازیں پڑھنے لگا ) تو ہم نے ( نماز کے اوقات کے بارے میں ) جابر بن عبداللہ رضی اللہ عنہ سے پوچھا ، انھوں نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ظہر کی نما دوپہر کو ( زوال کے فورا بعد ) پڑھتے تھے اور عصر ایسے وقت میں پڑھتے تھے کہ سورج بالکل صاف ( اور روشن ہوتا ) تھا اور مغرب کی نماز سورج غروب ہوتے ہی پڑھتے اور عشاء کی نماز کو کبھی مؤخر کرتے اور کبھی جلدی ادا کرتے ، جب آپ دیکھتے کہ لوگ جمع ہو گے ہیں تو جلدی پڑھ لیتے ارو جب انھیں دیکھتے کہ دیر کر دی ہے تو تاخیر کر دیتے ۔ اور صبح ( کی نماز ) یہ لوگ ۔ ۔ یا کہا : نبی صلی اللہ علیہ وسلم اندھیرے میں پڑھتے تھے ۔","",{"u2":"محمد بن جعفر غندر نے ہمیں حدیث بیان کی، کہا: ہمیں شعبہ نے حدیث سنائی، انھوں نے سعد بن ابراہیم سے اور انھوں نے محمد بن عمرو بن حسن بن علی (بن ابی طالب) رضی اللہ عنہ سے روایت کی، کہا: جب حجاج مدینہ منورہ آیا (اور تاخیر سے نمازیں پڑھنے لگا) تو ہم نے (نماز کےاوقات کے بارے میں)جابر بن عبداللہ رضی اللہ عنہما سے پوچھا، انھوں نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ظہر کی نما دوپہر کو (زوال کے فورا بعد)پڑھتے تھے اور عصر ایسے وقت میں پڑھتے تھے کہ سورج بالکل صاف (اور روشن ہوتا)تھا اور مغرب کی نماز سورج غروب ہوتے ہی پڑھتے اور عشاء کی نماز کو کبھی مؤخر کرتے اور کبھی جلدی ادا کرتے، جب آپ دیکھتے کہ لوگ جمع ہو گے ہیں تو جلدی پڑھ لیتے ارو جب انھیں دیکھتے کہ دیر کر دی ہے تو تاخیر کر دیتے۔ اور صبح (کی نماز)یہ لوگ۔۔یا کہا: نبی صلی اللہ علیہ وسلم اندھیرے میں پڑھتے تھے۔"}],[1397,"معاذ عنبری نے شعبہ سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ حجاج نمازوں میں تاخیر کر دیتا تھا تو ہم نے جابر بن عبداللہ رضی اللہ عنہ سے پوچھا ۔ ۔ ۔ ( آگے ) غندر کی روایت کی طرح ہے ۔","",{"u2":"معاذ عنبری نے شعبہ سے باقی ماندہ اسی سند کے ساتھ روایت کی کہ حجاج نمازوں میں تاخیر کر دیتا تھا تو ہم نے جابر بن عبداللہ رضی اللہ عنہما سے پوچھا۔۔۔ (آگے)غندر کی روایت کی طرح ہے۔"}],[1398,"خالد بن حارث نے ہمیں حدیث سنائی ، کہا : شعبہ نے ہمیں حدیث بیان کی ، کہا : مجھے سیار بن سلامہ نے خبر دی ، کہا : میں نے سنا کہ میرے والد ، سیدنا ابو برزہ اسلمی رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھ رہے تھے ۔ ( شعبہ نے ) کہا : میں نے پوچھا : کیا آپ نے خود انھیں سنا ؟ انھوں نے کہا : ( اسی طرح ) جیسے میں ابھی تمھیں سن رہا ہوں ، کہا : میں نے سنا ، میرے والد ان سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں سوال کر رہے تھے ، انھوں نے بتایا کہ آپ اس ، یعنی عشاء کی نماز کو کچھ ( تقریباً ) آدھی رات تک مؤخر کرنے میں مضائقہ نہ سمجھتے تھے اور اس نماز سے پہلے سونے اور اس کے بات چیت کرنے کو نا پسند فرماتے تھے ۔ شعبہ نے کہا : میں بعد ازاں ( دوبارہ ) ان سے ملا تو میں نے ان سے ( پھر ) پوچھا تو انھوں ( سیار ) نے کہا : آپ ظہر کی نماز سورج ڈھلنے کے وقت پڑھتے تھے اور عصر ایسے وقت میں پڑھتے کہ انسان نماز پڑھ کر مدینہ کے دور ترین حصے تک پہنچ جاتا اور سورج ( اسی طرح ) زندہ ( روشن اور گرم ) ہوتا تھا اور انھوں نے کہا : مغرب کے لیے میں نہیں جانتا ، انھوں نے کون سا وقت بتایا تھا ۔ ( شعبہ نے ) کہا : میں اس کے بعد ( پھر ) سیار سے ملا اور ان سے پوچھا تو انھوں نے بتایا : ( آپ صلی اللہ علیہ وسلم ) صبح کی نماز ایسے وقت میں پڑھتے کہ انسان سلام پھیرتا اور اپنے ساتھ بیٹھے ہوئے انسان کے چہرے کو ، جسے وہ جانتا ہوتا ، دیکھتا تو اسے پہچان لیتا اور آپ اس ( نماز ) میں ساٹھ سے سو تک آیتیں تلاوت فرماتے تھے ۔","",{"u2":"خالد بن حارث نے ہمیں حدیث سنائی، کہا: شعبہ نے ہمیں حدیث بیان کی، کہا: مجھے سیار بن سلامہ نے خبر دی، کہا: میں نے سنا کہ میرے والد، سیدنا ابو برزہ اسلمی رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھ رہے تھے۔ (شعبہ نے) کہا: میں نے پوچھا: کیا آپ نے خود انھیں سنا؟ انھوں نے کہا: (اسی طرح)جیسے میں ابھی تمھیں سن رہا ہوں، کہا: میں نے سنا، میرے والد ان سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں سوال کر رہے تھے، انھوں نے بتایا کہ آپ اس، یعنی عشاء کی نماز کو کچھ (تقریباً) آدھی رات تک مؤخر کرنے میں مضائقہ نہ سمجھتے تھے اور اس نماز سے پہلے سونے اور اس کے بات چیت کرنے کو نا پسند فرماتے تھے۔ شعبہ نے کہا: میں بعد ازاں (دوبارہ)ان سے ملاتو میں نے ان سے (پھر)پوچھا تو انھوں (سیار)نے کہا: آپ ظہر کی نماز سورج ڈھلنے کے وقت پڑھتے تھے اور عصر ایسے وقت میں پڑھتے کہ انسان نماز پڑھ کر مدینہ کے دور ترین حصے تک پہنچ جاتا اور سورج (اسی طرح)زندہ (روشن اور گرم) ہوتا تھا اور انھوں نے کہا: مغرب کے لیے میں نہیں جانتا، انھوں نے کون سا وقت بتایا تھا۔ (شعبہ نے)کہا: میں اس کے بعد (پھر)سیار سے ملا اور ان سے پوچھا تو انھوں نے بتایا: (آپ صلی اللہ علیہ وسلم)صبح کی نماز ایسے وقت میں پڑھتے کہ انسان سلام پھیرتا اور اپنے ساتھ بیٹھے ہوئے انسان کے چہرے کو، جسے وہ جانتا ہوتا، دیکھتا تو اسے پہچان لیتا اور آپ اس (نماز)میں ساٹھ سے سو تک آیتیں تلاوت فرماتے تھے۔"}],[1399,"معاذ عنبری نے شعبہ سے حدیث بیان کی اور انھوں نے سیار بن سلامہ سے روایت کی کہ میں نے ابو برزہ کو کہتے ہوئے سنا ، رسول اللہ عشاء کی نماز میں کچھ ( یعنی ) آدھی رات تک تا خیر کی پروانہ کرتے تھے اور اس سے پہلے سونے اور اس کے بعد گفتگو کرنے کو پسند نہیں فرماتے تھے ۔ شعبہ نے کہا : پھر میں انھیں دوبارہ ملا تو انھوں نے کہا : یا تہائی رات تک ۔","",{"u2":"معاذ عنبری نے شعبہ سے حدیث بیان کی اور انھوں نے سیار بن سلامہ سے روایت کی کہ میں نے ابو برزہ کو کہتے ہوئے سنا، رسول اللہ عشاء کی نماز میں کچھ (یعنی)آدھی رات تک تا خیر کی پروانہ کرتے تھے اور اس سے پہلے سونے اور اس کے بعد گفتگو کرنے کو پسند نہیں فرماتے تھے۔ شعبہ نے کہا: پھر میں انھیں دوبارہ ملاتو انھوں نے کہا: یا تہائی رات تک۔"}],[1400,"(شعبہ کے بجائے ) حماد بن سلمہ نے ابو منہال ( سیار بن سلامہ ) سے روایت کی ، کہا : میں نے ابو برزہ اسلمی رضی اللہ عنہ سےسنا ، کہتے تھےکہ رسول اللہ صلی اللہ علیہ وسلم عشاء کو تہائی رات تک مؤخر کر دیتے تھے اور اس سے پہلے سونے اور بعد میں گفتگو کرنے کو ناپسند فرماتے تھے اور صبح کی نماز میں سو سے لے کر ساٹھ تک آیتیں تلاوت فرماتے اور ایسے وقت میں سلام پھیرتے تھے جب ہم ایک دوسرے کے چہرے کو پہچان سکتے تھے","",{"u2":"(شعبہ کے بجائے)حماد بن سلمہ نے ابو منہال (سیار بن سلامہ)سے روایت کی، کہا: میں نے ابو برزہ اسلمی رضی اللہ عنہ سےسنا، کہتے تھےکہ رسول اللہ صلی اللہ علیہ وسلم عشاء کو تہائی رات تک مؤخر کر دیتے تھے اور اس سے پہلے سونے اور بعد میں گفتگو کرنے کو ناپسند فرماتے تھے اور صبح کی نماز میں سو سے لے کر ساٹھ تک آیتیں تلاوت فرماتے اور ایسے وقت میں سلام پھیرتے تھے جب ہم ایک دوسرے کے چہرے کو پہچان سکتے تھے"}],[1401,"خلف بن ہشام ، ابوربیع زہرانی اور ابو کامل جحدری نے حدیث بیان کی کی ، کہا ہمیں حماد بن زید نے حدیث سنائی ، انھوں نے ابو عمران جونی سے ، انھوں نے عبداللہ بن صامت سے اور انھوں نے سیدنا ابو ذر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا : ’’تمھارا کیا حال ہوگا جب تم پر ایسے لوگ حکمران ہوں گے جو نماز کو اس کے وقت سے مؤخر کریں گے یا نماز کو اس کے وقت سے ختم کردیں گے ؟ ‘‘ میں نے عرض کیگ تو آپ مجھے ( اس کے بارے میں ) کیا حکم دیتے ہیں ؟ آپ نے فرمایا : ’’تم اپنے وقت پر نماز پڑھ لینا اگر تمھیں ان کے ساتھ ( بھی ) نماز مل جائے تو پڑھ لینا ، وہ تمھارے لیے نفل ہو جائے گی ۔ ‘‘ خلف نےعن وقتھا ( اس کے وقت سے ) کے الفاظ بیان نہیں کیے ۔","",{"u2":"خلف بن ہشام، ابوربیع زہرانی اور ابو کامل جحدری نے حدیث بیان کی کی، کہا ہمیں حماد بن زید نے حدیث سنائی، انھوں نے ابو عمران جونی سے، انھوں نے عبداللہ بن صامت سے اور انھوں نے سیدنا ابو ذر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے فرمایا: ’’تمھارا کیا حال ہوگا جب تم پر ایسے لوگ حکمران ہوں گے جو نماز کو اس کے وقت سے مؤخر کریں گے یا نماز کو اس کے وقت سے ختم کردیں گے؟ ‘‘ میں نے عرض کیگ تو آپ مجھے (اس کے بارے میں) کیا حکم دیتے ہیں؟ آپ نے فرمایا: ’’تم اپنے وقت پر نماز پڑھ لینا اگر تمھیں ان کے ساتھ (بھی)نماز مل جائے تو پڑھ لینا، وہ تمھارے لیے نفل ہو جائے گی۔‘‘ خلف نےعن وقتھا (اس کے وقت سے)کے الفاظ بیان نہیں کیے۔"}],[1402,"جعفر بن سلیمان نے ابو عمران جونس سے اسی سند کے ساتھ سیدنا ابو ذر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے کہا : ’’ابو ذر! میرے بعد ایسے حکمران آئیں گے جو نماز کو مار دیں گے ( ان کا وقت ختم کردیں گے ) تو تم نماز کو اس کے وقت پر پڑھ لینا ، اگر تم نے نماز وقت پر پڑھ لی تو ( ان کے ساتھ ادا کی گئی دوسری نماز ) تمھارے لیے نفل ہو جائے گی ورنہ تم نے اپنی نماز تو بچا ہی لی ہے","",{"u2":"جعفر بن سلیمان نے ابو عمران جونس سے اسی سند کے ساتھ سیدنا ابو ذر رضی اللہ عنہ سے روایت کی، کہا:رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے کہا: ’’ابو ذر! میرے بعد ایسے حکمران آئیں گے جو نماز کو ماردیں گے (ان کا وقت ختم کردیں گے)تو تم نماز کو اس کے وقت پر پڑھ لینا، اگر تم نے نماز وقت پرپڑھ لی تو (ان کے ساتھ ادا کی گئی دوسری نماز)تمھارے لیے نفل ہو جائے گی ورنہ تم نے اپنی نماز تو بچا ہی لی ہے"}],[1403,"شعبہ نے ابو عمران سے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابو ذر رضی اللہ عنہ سے روایت کی ، کہا : میرے خلیل نے مجھے حکم دیا تھا کہ میں سنوں اور فرمانبرداری کروں ، چاہے کٹے ہوئے بازوں والا غلام ( ہی حکمران ) ہو اور یہ کہ میں نماز وقت پر پڑھوں ( آپ صلی اللہ علیہ وسلم نے فرمایا : ) ’’پھر اگر تم لوگوں کو اس حالت میں پاؤ کہ انھوں نے نماز پڑھ لی ہے تو تم اپنی نماز بچا چکے ہو ( وقت پر پہلے پڑھ چکے ہو ) ، اور اگر ( انھوں نے نہیں پڑھی اور تم ان کے ساتھ شریک ہوئے ) تو تمھاری یہ نماز نفل ہو گی ۔ ‘‘","",{"u2":"شعبہ نے ابو عمران سے باقی ماندہ سابقہ سند کے ساتھ سیدنا ابو ذر رضی اللہ عنہ سے روایت کی، کہا:میرے خلیل نے مجھے حکم دیا تھا کہ میں سنوں اور فرمانبرداری کروں، چاہے کٹے ہوئے بازوں والا غلام (ہی حکمران)ہو اور یہ کہ میں نماز وقت پر پڑھوں (آپ صلی اللہ علیہ وسلم نے فرمایا:)’’پھر اگر تم لوگوں کو اس حالت میں پاؤ کہ انھوں نے نماز پڑھ لی ہے تو تم اپنی نماز بچا چکے ہو (وقت پر پہلے پڑھ چکے ہو)، اور اگر (انھوں نے نہیں پڑھی اور تم ان کے ساتھ شریک ہوئے) تو تمھاری یہ نماز نفل ہو گی۔‘‘"}],[1404,"بدیل سے روایت ہے ، انھوں نے کہا : میں نے ابو عالیہ سے سنا ، وہ عبداللہ بن صامت سے اور وہ سیدنا ابو ذر رضی اللہ عنہ سے روایت کر رہے تھے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور میری ران پر ہاتھ مارا : ’’تمھارا کیا حال ہو گا جب تم ایسے لوگوں میں اپنی بقیہ زندگی گزار رہے ہو گے جو نماز کو اس کے وقت سے مؤخر کردیں گے ؟ ‘‘ ( عبداللہ بن صامت نے ) کہا : انھوں نے کہا : آپ کیا حکم دیتے ہیں ؟فرمایا : ’’تم نماز کواس کے وقت پر ادا کرلینا ، اور اپنی ضرورت کے لیے چلے جانا ، پھر اگر نماز کی اقامت کہی گئی اور تم مسجد میں ہوئے تو ( دوبارہ ) پڑھ لینا ۔ ‘‘","",{"u2":"بدیل سے روایت ہے، انھوں نے کہا: میں نے ابو عالیہ سے سنا، وہ عبداللہ بن صامت سے اور وہ سیدنا ابو ذر رضی اللہ عنہ سے روایت کر رہے تھے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور میری ران پر ہاتھ مارا: ’’تمھارا کیاحال ہو گا جب تم ایسے لوگوں میں اپنی بقیہ زندگی گزار رہے ہو گے جو نماز کو اس کے وقت سے مؤخر کردیں گے؟‘‘ (عبداللہ بن صامت نے)کہا: انھوں نے کہا: آپ کیا حکم دیتے ہیں؟فرمایا: ’’تم نماز کواس کے وقت پر ادا کرلینا، اور اپنی ضرورت کے لیے چلے جانا، پھر اگر نماز کی اقامت کہی گئی اور تم مسجد میں ہوئے تو (دوبارہ) پڑھ لینا۔‘‘"}],[1405,"ایوب نے ابو عالیہ برّاء سے روایت کی ، کہا : ابن زیاد نے نماز میں تاخیر کر دی تو میرے پاس عبداللہ بن صامت تشریف لے آئے ، میں نے ان کے لیے کرسی رکھوا دی ، وہ اس پر بیٹھ گئے ، میں نے ان کے سامنے ابن زیاد کی حرکت کا تذکرہ کیا تواس پر انھوں نے اپنا ( نچلا ) ہونٹ دانتوں میں دبایا اور میری ران پر ہاتھ مار کر کہا : جس طرح تم نے مجھ سے پوچھا ہے ، اسی طرح میں نے ابو ذر رضی اللہ عنہ سے پوچھا تھا ، انھوں نے بھی اسی طرح میری ران پر ہاتھ مارا تھا جس طرح میں نے تمھاری ران پر ہاتھ مارا ہے اور کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تھا جس طرح تم نے مجھ سے پوچھا ہے تو آپ صلی اللہ علیہ وسلم نے میری ران پر ہاتھ مارا جس طرح میں نے تمھاری ران پر ہاتھ مارا ہے اور فرمایا : ’’تم نماز بروقت ادا کرلینا ، پھر اگر تمھیں ان کے ساتھ نماز پڑھنی پڑھ تو ( پھر سے ) نماز پڑھ لینا اور یہ نہ کہنا : میں نے نماز پڑھ لی ہے اس لیے اب نہیں پڑھوں گا ۔ ‘‘","",{"u2":"ایوب نے ابو عالیہ برّاء سے روایت کی، کہا: ابن زیاد نے نماز میں تاخیر کر دی تو میرے پاس عبداللہ بن صامت تشریف لے آئے، میں نے ان کے لیے کرسی رکھوا دی، وہ اس پر بیٹھ گئے، میں نے ان کے سامنے ابن زیاد کی حرکت کا تذکرہ کیا تواس پر انھوں نے اپنا (نچلا)ہونٹ دانتوں میں دبایا اور میری ران پر ہاتھ مار کر کہا: جس طرح تم نے مجھ سے پوچھا ہے، اسی طرح میں نے ابو ذر رضی اللہ عنہ سے پوچھا تھا، انھوں نے بھی اسی طرح میری ران پر ہاتھ مارا تھا جس طرح میں نے تمھاری ران پر ہاتھ مارا ہے اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تھا جس طرح تم نے مجھ سے پوچھا ہے تو آپ صلی اللہ علیہ وسلم نے میری ران پر ہاتھ مارا جس طرح میں نے تمھاری ران پر ہاتھ مارا ہے اور فرمایا: ’’تم نماز بروقت ادا کرلینا، پھر اگرتمھیں ان کے ساتھ نماز پڑھنی پڑھ تو (پھر سے)نماز پڑھ لینا اور یہ نہ کہنا: میں نے نماز پڑھ لی ہے اس لیے اب نہیں پڑھوں گا۔‘‘"}],[1406,"ابو نعامہ نے عبداللہ بن صامت سے اور انھوں نے سیدنا ابو ذر رضی اللہ عنہ سے روایت کی ، کہا : آپ صلی اللہ علیہ وسلم نے فرمایا : ’’تم لوگوں کا کیا حال ہو گا ‘‘ یا فرمایا : ’’تمھاری کیفیت کیا ہو گی جب تم ایسے لوگوں میں رہ جاؤ گے جو نماز کو اس کے وقت سے مؤخر کریں گے ؟ تم وقت پر نماز پڑھ لینا ، پھر اگر ( تمھاری موجودگی میں ) نماز کی اقامت ہو تو تم ان کے ساتھ ( بھی ) پڑھ لینا کیونکہ یہ نیکی میں اضافہ ہے ۔ ‘‘","",{"u2":"ابو نعامہ نے عبداللہ بن صامت سےاور انھوں نے سیدنا ابو ذر رضی اللہ عنہ سے روایت کی، کہا: آپ صلی اللہ علیہ وسلم نے فرمایا:’’تم لوگوں کا کیا حال ہو گا ‘‘ یا فرمایا:’’تمھاری کیفیت کیا ہو گی جب تم ایسے لوگوں میں رہ جاؤ گے جو نماز کو اس کے وقت سے مؤخر کریں گے؟ تم وقت پر نماز پڑھ لینا، پھر اگر (تمھاری موجودگی میں)نماز کی اقامت ہو تو تم ان کے ساتھ (بھی)پڑھ لینا کیونکہ یہ نیکی میں اضافہ ہے۔‘‘"}],[1407,"مطر نے ابو عالیہ بّراء سے روایت کی ، کہا : میں نے عبداللہ بن صامت سے پوچھا کہ ہم جمعہ کے دن حکمرانوں کی اقتدا میں نماز پڑھتے ہیں اور وہ نماز کو مؤخر کر دیتے ہیں ۔ تو انھوں نے زور سے میری ران پر ہاتھ مارا جس سے مجھے تکلیف محسوس ہوئی اور کہا : میں نے اس کے بارےمیں ابو ذر رضی اللہ عنہ سے پوچھا تو انھوں نے ( بھی ) میری ران پر ہاتھ مارا تھا اور کہا تھا : میں نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا تھا تو آپ نے فرمایا : ’’نماز اس کے وقت پر ادا رکر لو ، پھر ان ( حکمرانوں ) کے ساتھ اپنی نماز کو نفل بنالو ۔ ‘‘ کہا : عبداللہ نے کہا : مجھے بتایا گیا کہ نبی اکرم صلی اللہ علیہ وسلم نے ( بھی ) ابو ذر رضی اللہ عنہ کی ران پر ہاتھ مارا تھا ۔","",{"u2":"مطر نے ابو عالیہ بّراء سے روایت کی، کہا: میں نے عبداللہ بن صامت سے پوچھا کہ ہم جمعہ کے دن حکمرانوں کی اقتدا میں نماز پڑھتے ہیں اور وہ نماز کو مؤخر کر دیتے ہیں۔ تو انھوں نے زور سے میری ران پر ہاتھ مارا جس سے مجھے تکلیف محسوس ہوئی اور کہا: میں نے اس کے بارےمیں ابو ذر رضی اللہ عنہ سے پوچھا تو انھوں نے (بھی)میری ران پر ہاتھ مارا تھا اور کہا تھا: میں نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا تھا تو آپ نے فرمایا:’’نماز اس کے وقت پر ادا رکر لو، پھر ان (حکمرانوں)کے ساتھ اپنی نماز کو نفل بنالو۔‘‘\nکہا: عبداللہ نے کہا: مجھے بتایا گیا کہ نبی اکرم صلی اللہ علیہ وسلم نے (بھی)ابو ذر رضی اللہ عنہ کی ران پر ہاتھ مارا تھا۔"}],[1408,"مالک نے ابن شہاب ( زہری ) سے ، انھوں نے سعید بن مسیب سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت یک کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ باجماعت نماز تمھارے اکیلے کی نماز سے پچیس گنا ہ افضل ہے","",{"u2":"مالک نےابن شہاب (زہری)سے، انھوں نے سعید بن مسیب سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت یک کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ باجماعت نماز تمھارے اکیلے کی نماز سے پچیس گنا ہ افضل ہے"}],[1409,"عبدالاعلی نے معمر سے ، انھوں نے زہری سے ، اسی سند کے ساتھ سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : ’’ سب کے ساتھ مل کر نماز پڑھنا اکیلے انسان کی نماز سے پچیس درجے افضل ہے ۔ ’’آپ نے فرمایا : ’’رات کے فرشتے اور دن کے فرشتے فجر کی نماز میں جمع ہوتے ہیں ۔ ‘‘ ابوہریرہ رضی اللہ عنہ نے کہا : تم چاہو تو یہ آیت پڑھ لو ( جو اس بات کی تصدیق کرتی ہے ) : ’’ اور فجر کے وقت قرآن پڑھنا بلاشبہ فجر کی قراءت میں حاضری دی جاتی ہے","",{"u2":"عبدالاعلی نے معمر سے، انھوں نے زہری سے، اسی سند کے ساتھ سیدنا ابو ہریرہ رضی اللہ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا:’’ سب کے ساتھ مل کر نماز پڑھنا اکیلے انسان کی نماز سے پچیس درجے افضل ہے۔’’آپ نے فرمایا:’’رات کے فرشتے اور دن کے فرشتے فجر کی نماز میں جمع ہوتے ہیں۔‘‘ ابوہریرہ رضی اللہ عنہ نے کہا: تم چاہو تو یہ آیت پڑھ لو (جو اس بات کی تصدیق کرتی ہے):’’ اور فجر کے وقت قرآن پڑھنا بلاشبہ فجر کی قراءت میں حاضری دی جاتی ہے"}],[1410,"شعیب نے زہری سے روایت کی ، کہا : مجھے سعید اور ابو سلمہ نے خبر دی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نےکہا : میں نے نبی صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے ۔ ۔ ۔ ۔ آگے معمر سے عبدالاعلیٰ کی ( مذکورہ بالا ) حدیث کی رضی اللہ عنہ طرح ہے ، اس کے سوا کہ انھوں نے ( درجے کی بجائے ) ’’پچیس جز ‘‘ کہا ۔","",{"u2":"شعیب نے زہری سے روایت کی، کہا: مجھے سعیداور ابو سلمہ نے خبر دی کہ سیدنا ابو ہریرہ رضی اللہ عنہ نےکہا: میں نے نبی صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے۔۔۔۔آگے معمر سے عبدالاعلیٰ کی (مذکورہ بالا)حدیث کی ﷾طرح ہے، اس کے سوا کہ انھوں نے (درجے کی بجائے)’’پچیس جز ‘‘کہا۔"}],[1411,"سلمان اغر نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’باجماعت نماز اکیلے کی پچیس نمازوں کے برابر ہے","",{"u2":"سلمان اغر نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’باجماعت نماز اکیلے کی پچیس نمازوں کے برابر ہے"}],[1412,"عمر بن عطاء بن ابی خوار نے خبر دی کہ میں نے نافع بن جبیر بن مطعم کے پاس بیٹھا ہوا تھا کہ اس اثنا میں ہمارے پاس سے جہنیوں کے آزاد کردہ غلام زید بن زبان کے بہنوئی ابو عبداللہ گزرے ، نافع نے انھیں بلایا ( اور حدیث سنا نے کو کہا ۔ ) انھوں نے کہا : میں نے ابو ہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’امام کے ساتھ ( پڑھی گئی ) نماز ایسی پچیس نمازوں سے افضل ہے جو انسان اکیلے پڑھتا ہے ۔ ‘‘","",{"u2":"عمر بن عطاء بن ابی خوار نے خبر دی کہ میں نے نافع بن جبیر بن مطعم کے پاس بیٹھا ہوا تھا کہ اس اثنا میں ہمارے پاس سے جہنیوں کے آزاد کردہ غلام زید بن زبان کے بہنوئی ابو عبداللہ گزرے، نافع نے انھیں بلایا (اور حدیث سنا نے کو کہا۔)انھوں نے کہا: میں نے ابو ہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’امام کے ساتھ (پڑھی گئی) نماز ایسی پچیس نمازوں سے افضل ہے جو انسان اکیلے پڑھتا ہے۔‘‘"}],[1413,"مالک نے نافع سے اورانھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’با جماعت نماز پڑھنا اکیلے کی نماز سے ستائیس درجے افضل ہے ۔ ‘‘","",{"u2":"مالک نے نافع سے اورانھوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’با جماعت نماز پڑھنا اکیلے کی نماز سے ستائیس درجے افضل ہے۔‘‘"}],[1414,"یحییٰ نے عبید اللہ سے حدیث بیان کی ، کہا : مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی ، انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : ’’آدمی کی جماعت کے ساتھ نماز اسکی اکیلے پڑھی گئی ستائیس نمازوں سے بڑھ کر ہے","",{"u2":"یحییٰ نے عبید اللہ سے حدیث بیان کی، کہا:مجھے نافع نے سیدنا ابن عمر رضی اللہ عنہ سے خبر دی، انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: ’’آدمی کی جماعت کے ساتھ نماز اسکی اکیلے پڑھی گئی ستائیس نمازوں سے بڑھ کر ہے"}],[1415,"ابو بکر بن ابی شیبہ نےہمیں حدیث سنائی ، کہا : ہمیں ابو اسامہ اور ( محمد بن عبداللہ ) ابن نمیر نے حدیث سنائی ، نیز ابن نمیر نے ( کہا : ) ہمیں میرے والد نے حدیث سنائی ، ان دونوں ) ( ابو اسامہ اور ابن نمیر ) نے کہا : ہمیں عبیداللہ نے اسی سندکے ساتھ یہی حدیث بیان کی ۔ ابن نمیر نے اپنےوالد سے روایت کردہ حدیث میں بضعا و عشرین ( بیس سے زائد ) کے الفاظ روایت کیے اور ابوبکر بن ابی شبیہ نے اپنی روایت میں ستائیس درجے کہا ۔","",{"u2":"ابو بکر بن ابی شیبہ نےہمیں حدیث سنائی، کہا: ہمیں ابو اسامہ اور (محمد بن عبداللہ)ابن نمیر نے حدیث سنائی، نیز ابن نمیر نے (کہا:)ہمیں میرے والد نے حدیث سنائی، ان دونوں)(ابو اسامہ اور ابن نمیر)نے کہا: ہمیں عبیداللہ نے اسی سندکے ساتھ یہی حدیث بیان کی۔ابن نمیر نے اپنےوالد سے روایت کردہ حدیث میں بضعا و عشرین (بیس سے زائد)کے الفاظ روایت کیے اور ابوبکر بن ابی شبیہ نے اپنی روایت میں ستائیس درجے کہا۔"}],[1416,"ضحاک نے نافع سے ، انھوں نے ابن عمر رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، فرمایا : ’’بیس سے زائد ۔ ‘‘","",{"u2":"ضحاک نے نافع سے، انھوں نے ابن عمر رضی اللہ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی، فرمایا: ’’بیس سے زائد۔‘‘"}],[1417,"اعرج نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو ایک نماز میں غیر حاضر پایا تو فرمایا : ’’میں نے ( یہا ں تک ) سوچا کہ کسی آدمی کو لوگوں کی امامت کرانے کا حکم دو ں ، پھر دوسری طرف سے ان لوگوں کی طرف جاؤں جو نماز سے پیچھے رہتے ہیں اور ان کے بار ے میں ( اپنے کارندوں کو ) حکم دوں کہ لکڑیوں کے گٹھوں سے آگ بھڑکا کر ان کے گھروں کو ان پر جلا دیں ۔ ان میں سے اگر کسی کو یقین ہو کہ نماز میں حاضری سے اسے فربہ ( گوشت سے بھر ہوئی ) ہڈی ملے گی تو وہ اس میں ضرور حاضر ہو جائے گا ۔ ‘‘ آپ صلی اللہ علیہ وسلم کی مراد عشاء کی نماز سے تھی ۔","",{"u2":"اعرج نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو ایک نماز میں غیر حاضر پایا تو فرمایا: ’’میں نے (یہا ں تک)سوچا کہ کسی آدمی کو لوگوں کی امامت کرانے کا حکم دو ں، پھر دوسری طرف سے ان لوگوں کی طرف جاؤں جو نماز سے پیچھے رہتےہیں اور ان کے بار ے میں (اپنے کارندوں کو)حکم دوں کہ لکڑیوں کے گٹھوں سے آگ بھڑکا کر ان کے گھروں کو ان پر جلا دیں۔ ان میں سے اگرکسی کو یقین ہو کہ نماز میں حاضری سے اسے فربہ (گوشت سے بھر ہوئی)ہڈی ملے گی تو وہ اس میں ضرور حاضر ہو جائے گا۔‘‘ آپ صلی اللہ علیہ وسلم کی مراد عشاء کی نماز سے تھی۔"}],[1418,"ابو صالح نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’منافقوں کے لیے سب سے بھاری نماز عشاء اور فجر کی نماز ہے ، اگر ان لوگوں کو پتہ چل جائے ، جو ان میں ( خیرو برکت ) ہے تو چاہے انھیں گھٹنوں کے بل چل کر آنا پڑے ، ضرور آئیں ۔ اور میں نے سوچاتھا کہ نماز کی اقامت کا حکم دو ں ، پھر کسی شخص کو کہوں وہ لوگوں کو جماعت کرائے ، پھر میں کچھ اشخاص کو ساتھ لے کر ، جن کے پاس لکڑیوں کے گٹھے ہوں ، ان لوگوں کی طرف جاؤں جو نماز میں حاضر نہیں ہوتے ، پھر ان کے گھروں کو ان پر آگ سے جلا دو ں ۔ ‘‘","",{"u2":"ابو صالح نےسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’منافقوں کے لیے سب سے بھاری نماز عشاء اور فجر کی نماز ہے، اگر ان لوگوں کو پتہ چل جائے، جو ان میں (خیرو برکت)ہے تو چاہے انھیں گھٹنوں کے بل چل کر آنا پڑے،ضرور آئیں۔ اور میں نے سوچاتھا کہ نماز کی اقامت کا حکم دو ں، پھر کسی شخص کو کہوں وہ لوگوں کو جماعت کرائے، پھر میں کچھ اشخاص کو ساتھ لے کر،جن کے پاس لکڑیوں کے گٹھے ہوں، ان لوگوں کی طرف جاؤں جو نماز میں حاضر نہیں ہوتے، پھر ان کے گھروں کو ان پر آگ سے جلا دو ں۔‘‘"}],[1419,"ہمام بن منبہ سے روایت ہے ، کہا : یہ احادیث ہیں جو ابو ہریرہ رضی اللہ عنہ نےہمیں رسول اللہ سے روایت کیں ، پھر انھوں نے متعدد احادیث بیان کیں ، ان میں سے یہ بھی تھی کہ رسول اللہ نے فرمایا : ’’میں نے ارادہ کیا تھا کہ اپنے جوانوں کو حکم دوں کہ وہ میری خاطر لکڑی کے گٹھے تیار کریں ، پھر کسی آدمی کو حکم دوں وہ لوگوں کو نماز پڑھائے ، پھر گھروں کو ان کے ( بے نماز ) باسیوں سمیت جلا دیا جائے ۔ ‘‘","",{"u2":"ہمام بن منبہ سے روایت ہے، کہا: یہ احادیث ہیں جو ابو ہریرہ رضی اللہ عنہ نےہمیں رسول اللہ سے روایت کیں، پھر انھوں نے متعدد احادیث بیان کیں، ان میں سے یہ بھی تھی کہ رسول اللہ نے فرمایا: ’’میں نے ارادہ کیا تھا کہ اپنے جوانوں کو حکم دوں کہ وہ میری خاطر لکڑی کے گٹھے تیار کریں، پھر کسی آدمی کو حکم دوں وہ لوگوں کو نماز پڑھائے، پھر گھروں کو ان کے (بے نماز)باسیوں سمیت جلا دیا جائے۔‘‘"}],[1420,"یزید بن اصم نے ابو ہریرہ صلی اللہ علیہ وسلم سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کی طرح حدیث روایت کی ہے","",{"u2":"یزید بن اصم نے ابو ہریرہ صلی اللہ علیہ وسلم سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کی طرح حدیث روایت کی ہے"}],[1421,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ان لوگوں سے جو جمعے سے پیچھے رہ جاتے ہیں ، فرمایا : ’’میں نے ارادہ کیا کہ کسی آدمی کو حکم دو ں وہ لوگوں کو نماز پڑھائے ، پھر ان لوگوں کے گھروں کو ان پر ( اس سمیت ) جلا دوں جو جمعے سے پیچھے رہتے ہیں","",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ان لوگوں سے جو جمعے سے پیچھے رہ جاتے ہیں، فرمایا:’’میں نے ارادہ کیا کہ کسی آدمی کو حکم دو ں وہ لوگوں کو نماز پڑھائے، پھر ان لوگوں کے گھروں کو ان پر (اس سمیت)جلادوں جو جمعے سے پیچھے رہتے ہیں"}],[1422,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انھوں نے کہا : نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں اکی نابینا آدمی حاضر ہوا اور عرض کی : اے اللہ کے رسول ! میرے پاس کوئی لانے والا نہیں جو ( ہاتھ سے پکڑ کر ) مجھے مسجد میں لے آئے ۔ اس نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ اسے اجازت دی جائے کہ وہ اپنے گھر میں نماز پڑھ لے ۔ آپ نے اسے اجازت دے دی ، جب وہ واپس ہو ا تو آپ صلی اللہ علیہ وسلم نے اسے بلایا اور فرمایا : ’’کیا تم نماز کا بلاوا ( اذان ) سنتے ہو؟ ‘‘ اس نے عرض کی : جی ہاں ۔ آپ نے فرمایا : ’’تو اس پر لبیک کہو ۔ ‘‘","",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انھوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں اکی نابینا آدمی حاضر ہوا اور عرض کی: اے اللہ کےرسول! میرے پاس کوئی لانے والا نہیں جو (ہاتھ سے پکڑ کر)مجھے مسجد میں لے آئے۔ اس نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ اسے اجازت دی جائے کہ وہ اپنے گھر میں نماز پڑھ لے۔ آپ نے اسے اجازت دے دی، جب وہ واپس ہو ا تو آپ صلی اللہ علیہ وسلم نے اسے بلایا اور فرمایا: ’’کیا تم نماز کا بلاوا (اذان)سنتے ہو؟ ‘‘ اس نے عرض کی:جی ہاں۔ آپ نے فرمایا:’’تو اس پر لبیک کہو۔‘‘"}],[1423,"عبد الملک بن عمیر نے ابو احوص سے روایت کی ، کہا : سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) نےکہا : ساتھیوں سمیت میں نے خود کو دیکھا کہ نماز سے کوئی شخص پیچھے نہ رہتا ، سوائے منافق کے ، جس کا نفاق معلوم ہوتا یا سوائے بیمار کے اور ( بسا اوقات ) بیمار بھی دو آدمیوں کے سہائے سے چلتا آ جاتا یہاں تک کہ نماز میں شامل ہو جاتا ۔ انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نےہمیں ہدایت کے طریقوں کی تعلیم دی اور ہدایت کے طریقوں میں سے ایسی مسجد میں نماز پڑھنا بھی ہے جس میں اذان دی جاتی ہو ۔","",{"u2":"عبد الملک بن عمیر نے ابو احوص سے روایت کی، کہا: حضرت عبداللہ (بن مسعود رضی اللہ عنہ) نےکہا: ساتھیوں سمیت میں نےخود کو دیکھا کہ نماز سے کوئی شخص پیچھے نہ رہتا، سوائے منافق کے، جس کا نفاق معلوم ہوتا یا سوائے بیمار کے اور (بسا اوقات)بیمار بھی دو آدمیوں کے سہائے سے چلتا آ جاتا یہاں تک کہ نماز میں شامل ہو جاتا۔ انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نےہمیں ہدایت کے طریقوں کی تعلیم دی اور ہدایت کے طریقوں میں سے ایسی مسجد میں نماز پڑھنا بھی ہے جس میں اذان دی جاتی ہو۔"}],[1424,"علی بن اقمر نے ابو احوص سے اور انھوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی ، کہا : جو یہ چاہے کہ کل ( قیامت کے دن ) اللہ تعالیٰ سے مسلمان کی حیثیت سے ملے تو وہ جہاں سے ان ( نمازوں ) کے لیے بلایا جائے ، ان نمازوں کی حفاظت کرے ( وہاں مساجد میں جا کر صحیح طرح سے انھیں ادا کرے ) کیونکہ اللہ تعالیٰ نے تمھائے نبی صلی اللہ علیہ وسلم کے لے ہدایت کے طریقے مقرر فرما دیے ہیں اور یہ ( مساجد میں باجماعت نماز یں ) بھی انھی طریقوں میں سے ہیں ۔ کیونکہ اگر تم نمازیں اپنے گھروں میں پڑھو گے ، جیسے یہ جماعت سے پیچھے رہنے والا ، اپنے گھر میں پڑھتا ہےتو تم اپنے نبی کی راہ چھوڑ دو گے اور اگر تم اپنے نبی کی راہ کو چھوڑ دو گے تو گمراہ ہو جاؤ گے ۔ کوئی آدمی جو پاکیز گی حاصل کرتا ہے ( وضو کرتا ہے ) اور اچھی طرح وضو کرتا ہے ، پھر ان مساجد میں سے کسی مسجد کا رخ کرتا ہے تو اللہ تعالیٰ اس کے ہر قدم کے بدلے ، جو وہ اٹھاتا ہے ، ایک نیکی لکھتا ہے ، اور اس کے سبب اس کا ایک درجہ بلند فرماتا ہے اور اس کا ایک گناہ کم کر دیتا ہے ، اور میں نے دیکھا کہ ہم میں سے کوئی ( بھی ) جماعت سے پیچھے نہ رہتا تھا ، سوائے ایسے منافق کے جس کا نفاق سب کو معلوم ہوتا ( بلکہ بسا اوقات ایسا ہوتا کہ ) ایک آدمی کو اس طرح لایا جاتا کہ اسے دو آ دمیوں کے درمیان سہارا دیا گیا ہوتا ، حتی کہ صف میں لاکھڑا کیا جاتا ۔","",{"u2":"علی بن اقمر نے ابو احوص سے اور انھوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی، کہا: جو یہ چاہے کہ کل (قیامت کے دن)اللہ تعالیٰ سے مسلمان کی حیثیت سے ملے تو وہ جہاں سے ان (نمازوں) کے لیے بلایا جائے، ان نمازوں کی حفاظت کرے (وہاں مساجد میں جا کر صحیح طرح سے انھیں ادا کرے)کیونکہ اللہ تعالیٰ نے تمھائے نبی صلی اللہ علیہ وسلم کے لے ہدایت کے طریقے مقرر فرما دیے ہیں اور یہ (مساجد میں باجماعت نماز یں)بھی انھی طریقوں میں سے ہیں۔ کیونکہ اگر تم نمازیں اپنے گھروں میں پڑھو گے، جیسے یہ جماعت سے پیچھے رہنے والا، اپنے گھر میں پڑھتا ہےتو تم اپنے نبی کی راہ چھوڑ دو گے اور اگر تم اپنے نبی کی راہ کو چھوڑ دو گے تو گمراہ ہو جاؤ گے۔ کوئی آدمی جو پاکیز گی حاصل کرتا ہے (وضوکرتا ہے)اور اچھی طرح وضو کرتا ہے، پھر ان مساجد میں سے کسی مسجد کا رخ کرتا ہے تو اللہ تعالیٰ اس کے ہر قدم کے بدلے، جو وہ اٹھاتا ہے، ایک نیکی لکھتا ہے، اور اس کے سبب اس کا ایک درجہ بلند فرماتا ہے اور اس کا ایک گناہ کم کر دیتا ہے، اور میں نے دیکھا کہ ہم میں سے کوئی (بھی)جماعت سے پیچھے نہ رہتا تھا، سوائے ایسے منافق کے جس کا نفاق سب کو معلوم ہوتا (بلکہ بسا اوقات ایسا ہوتا کہ)ایک آدمی کو اس طرح لایا جاتا کہ اسے دو آ دمیوں کے درمیان سہارا دیا گیا ہوتا، حتی کہ صف میں لاکھڑا کیا جاتا۔"}],[1425,"ابراہیم بن مہاجر نے ابو شعثاء سے روایت کی ، کہا : ہم مسجد میں سیدنا ابو ہریرہ رضی اللہ عنہ کے ساتھ بیٹھے ہوئے تھے کہ مؤذن نے اذان کہی ، ایک آدمی مسجد سے اٹھ کر چل پڑا ، سیدنا ابو ہریرہ رضی اللہ عنہ نے مسلسل اس پر نظر رکھی حتی کہ وہ مسجد سے نکل گیا ، سیدنا ابو ہریرہ رضی اللہ عنہ نےکہا : یہ شخص ، یقینا اس نے ابو القاسم صلی اللہ علیہ وسلم کی نافرمانی کی ہے ۔","",{"u2":"ابراہیم بن مہاجر نے ابو شعثاء سے روایت کی، کہا: ہم مسجد میں سیدنا ابو ہریرہ رضی اللہ عنہ کے ساتھ بیٹھے ہوئے تھے کہ مؤذن نے اذان کہی، ایک آدمی مسجدسے اٹھ کر چل پڑا، سیدنا ابو ہریرہ رضی اللہ عنہ نےمسلسل اس پر نظر رکھی حتی کہ وہ مسجد سے نکل گیا، سیدنا ابو ہریرہ رضی اللہ عنہ نےکہا: یہ شخص، یقینا اس نے ابو القاسم صلی اللہ علیہ وسلم کی نافرمانی کی ہے۔"}],[1426,"اشعث بن ابی شعثاء محاربی نے اپنے والد سے روایت کی ، کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا : انھوں نے ایک شخص کو اذان کے بعد مسجد میں سے چل کر باہر نکلتے دیکھتا تو فرمایا : یہ شخص ، بلاشبہ اس نے ابو القاسم صلی اللہ علیہ وسلم کی نافرمانی کی ہے ۔","",{"u2":"اشعث بن ابی شعثاء محاربی نے اپنے والد سے روایت کی، کہا: میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا: انھوں نے ایک شخص کو اذان کے بعد مسجد میں سے چل کر باہر نکلتے دیکھتا تو فرمایا: یہ شخص، بلاشبہ اس نے ابو القاسم صلی اللہ علیہ وسلم کی نافرمانی کی ہے۔"}]]);
